[Definition 43 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the same parameters as in Definition \ref{Def.ParametersBulk}. Fix $m \in \mathbb{N}$, $t_1, \dots, t_m \in [0, \infty)$ with $t_1 < t_2 < \cdots < t_m$, and set $\mathcal{T} = \{t_1, \dots, t_m\}$. We also define for $t \in \mathcal{T}$ the quantity $T_{t} = T_t(N) =  \lfloor t N^{2/3} \rfloor$ and the lattice $\Lambda_t(N) = a_t(N) \cdot \mathbb{Z} + b_t(N)$, where 
\begin{equation}
a_t(N) = \sigma_1^{-1} N^{-1/3}, \mbox{ and } b_t(N) = \sigma_1^{-1} N^{-1/3} \cdot \left( - h_1 N - p_1 T_{t} \right).
\end{equation}

We let $\mathbb{P}_N$ be the Pfaffian Schur process from Definition \ref{Def.SchurProcess}. Here, we assume that $M = M(N)$ is sufficiently large so that $M \geq T_{t_m}$. If $(\lambda^0, \dots, \lambda^M)$ have law $\mathbb{P}_N$, we define the random variables
\begin{equation}
X_i^{j,N} = \sigma_1^{-1} N^{-1/3} \cdot \left( \lambda_i^{T_{t_j}} - h_1 N - p_1 T_{t_j}  - i\right) \mbox{ for } i \in \mathbb{N} \mbox{ and } j \in \llbracket 1, m \rrbracket.
\end{equation}

[Proposition 24 of arXiv:2608.18834, 'The Parabolic Anderson Model's Total Mass at Small Times: Geometry, Fluctuations, and Reno'] Suppose that Assumption \ref{Assumption} holds, and
let $\ka>0$ be fixed.
\begin{enumerate}
\item If $\rho>0$, then
\begin{align}

\lim_{\th\to0}\mbf E\big[\tfrac{\ka^2}{2}\be^\th_1(B)\big]=\frac{\ka^2\mf b}{(1+\rho)\rho}.
\end{align}
\item If $\rho=0$, then
there exist bounded and continuous functions $\msf b_i:[0,\infty)\to\mbb R$, $(i=1,2)$,
such that for every $\th>0$, one has
\begin{align}

\mbf E\big[\tfrac{\ka^2}{2}\be^\th_1(B)\big]
=
\begin{cases}
\ka^2\mf b\,\ell(\th)+\ka^2\msf b_1(\th)&H_0<1,\\
\ka^2\mf b\,(1+\th)\log(1+1/\th)+\ka^2\msf b_2(\th)&H_0=1,
\end{cases}
\end{align}
where
\begin{align}

\ell(\th)=\frac{1}{2\Ga(H_0)\Ga(1-H_0)}\int_0^{2\pi}\left|\frac{\sin\theta}{\cos\theta}\right|^{2H_0-1}
\Ga_0\Big(\th\big(|\sin\theta|+|\cos\theta|\big)\Big)\d\theta,
\end{align}
and $\Gamma_0$ denotes the zero-parameter upper incomplete Gamma function, i.e.,
\[\Gamma_0(\th)=\int_{\th}^\infty \mr e^{-z}z^{-1}\d z,\qquad \th>0.\]
\item 
If $\rho<0$,
then there exists a bounded and continuous function $\msf z:(0,\infty)\to\mbb R$ such that
for every $\th>0$,
\begin{align}

\mbf E\big[\tfrac{\ka^2}{2}\be^\th_1(B)\big]=\ka^2\mf d\,\th^{\rho}+\,\ka^2\msf z(\th).
\end{align}
Moreover,
$\msf z$ satisfies the limit
\begin{align}

\lim_{\th\to0}\msf z(\th)=
\begin{cases}
\frac{\mf b}{(1+\rho)\rho}&H_0>1/2,\\
0&H_0=1/2.
\end{cases}
\end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition newL of arXiv:2607.19651, 'Metastability and phase transition in a social network model with multiple opinions'] For any given opinion $o\in\mathcal{O}$, we define the ladder sets supporting opinion $o$ as follows:
\begin{multline*}
\mathcal{L}^o=\{u\in\mathcal{S}: \{u(1,o),...,u(N,o) \} = \{0,...,N-1 \}, \\ u(\cdot,p)=\frac{-u(\cdot,o)}{M-1}, \forall p \in\mathcal{O}\setminus \{o\}\}.
\end{multline*}
    Also, the ladder set is the union of the ladder sets on all of the $M$ opinions:
    \[\mathcal{L}=\bigcup_{o\in\mathcal{O}}\mathcal{L}^o.\]

[Proposition MartingaleReProp of arXiv:2411.15485, '\bf\Large Stochastic Volterra Equations for Local Times of Spectrally Positive L\'evy Proc'] For each $x\geq 0$, the random variable 
  \begin{eqnarray}
  \mathbf{Y}_x:=  \lambda\cdot  X_\zeta(x)+  \big(g-\boldsymbol{\mathcal{R}}_0\circ V^g_\lambda\big)  *X_\zeta(x) \end{eqnarray}
  is integrable and can be written as
  \begin{eqnarray*}
  \mathbf{Y}_x \!\!\!&=\!\!\!& Y_x(0)  + \int_0^x \int_0^{X_\zeta(s)}   V^g_\lambda(x-s) \, B_c(ds,dz) \cr
  \!\!\!&\!\!\!& + \int_0^x\int_0^{X_\zeta(s)} \int_0^\infty \Big( \int_{(x-s-y)^+}^{x-s} V^g_\lambda(r)\,dr\Big) \, \widetilde{N}_\nu(ds,dz,dy),\cr
  Y_x(0)\!\!\!&:=\!\!\!&   \zeta\cdot c \cdot  V^g_\lambda(x)+ \int_0^\zeta \int_0^\infty \Big( \int_{(x-y)^+}^{x} V^g_\lambda(r)\,dr\Big) N_0(dz,dy).  
  \end{eqnarray*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:zmombd of arXiv:2606.02472, 'Correlated uniform attachment trees'] Let $\ell, j, M, n, u$ be such that $u< M+1 \leq e^\ell<e^j \leq n$, and recall the definitions at~(equation eq:Ukey of the paper) and~(equation eq:Dkey of the paper).
There is a universal constant $C_\star$   such that the random variable
\be{
Z_{\ell,j}^{T_n^i}(u):= U_{\ell,j}^{T_n^i}(u) - D_{\ell,j}^{T_n^i}(u)  
}
satisfies 
    \be{
    \mathbb{E}\bcls{ Z_{\ell,j}^{T_n^i}(u)^4}\leq C_\star.
    } (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop HTR of arXiv:2608.29018, 'Sharp Restricted Isometry Thresholds for\\ Global Minima of Rank-Restricted Matrix LASSO'] Fix $k\ge2$ and $r_{\star}\ge1$, and let $t\coloneqq k/r_{\star}$.
Suppose $A\in\operatorname{rip}(\delta,k)$ with $\delta<\delta_{\mathrm{sharp}}(t)$. For
$\sigma\in\mathbb{R}^{d}$, the quantities $\mathsf{H}$ and $\mathsf{T}$ defined in \defref{HTD}
satisfy
\begin{equation}
\mathsf{H}\le\rho_{\delta,t}\,\mathsf{T}+\tau_{\delta,t}\,\normtwo{A\sigma}
\end{equation}
where $\rho_{\delta,t}$ and $\tau_{\delta,t}$ are defined in ((eq:rhotau of the paper)). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 32 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $\gamma >0$, $0 \leq s \leq t \leq T$, $n \in \mathbb{N}_+$ and $ \widehat{b}_n \in \mathbb{R}$. Denote $C_{\alpha,\beta}:=8 \chi(\rho_{\alpha}) \chi(\rho_{\beta})$. For $1 \leq \ell_n \leq L_n$, it holds
		\begin{align*}
			\mathbb{E}_{\nu_{\rho}} \Bigg[ \Bigg\{ \widehat{b}_n \int_s^t \dd r \sum_{x}   \nabla H ( \tfrac{ \lfloor x - r v_n \rfloor }{n}  )    \big[   \Psi_{x, \ell_n}^{\alpha,\beta}(\eta_r^n) - \Psi_{x,L_n}^{\alpha,\beta}(\eta_r^n)  \big]  \Bigg\}^{2} \Bigg] \leq C_{\alpha,\beta} (t-s)^{2} n \frac{(\widehat{b}_n)^2}{\ell_n} \| \nabla H \|^{2}_{2,n}.
		\end{align*}

[Lemma WPD-NHS-HUD-BB-2 of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] Choose the intensity parameter $ \sigma  = C\left( \Lambda  \right)\lambda _{q + 1}^{ - \frac{1}{2}}$ in the intermittent Dirichlet kernel ${\mathfrak{D}_{\tilde \mu }}\left( {t, \cdot } \right)$ specified by (equation IBW-GJI-A-1 of the paper). Then, for any $N \in \left\{ {0,1, \cdots ,10} \right\} $ and $t \in \mathop  \cap \limits_{j = 0}^{q} \left[ {0,{\mathfrak{t}_j}} \right] \cap \left[ {{t_k},{t_{k + 1}}} \right)$, we have
\begin{equation}
{\left\| {{\mathfrak{D}_{\tilde \mu }}\left( {{\lambda _{q + 1}}{{\tilde \Phi }_k}} \right)} \right\|_N} \lesssim  \delta _q^{\frac{1}{2}} \lambda _{q + 1}^{\frac{1}{2}N}\left( {\lambda _q^{\frac{1}{2}\left( {N - 1} \right)} + 1} \right)    ,
\end{equation}
\begin{equation}
{\left\| {{{\bar D}_{t,\Gamma }}{\mathfrak{D}_{\tilde \mu }}\left( {{\lambda _{q + 1}}{{\tilde \Phi }_k}} \right)} \right\|_N} \lesssim   \delta _q^{\frac{1}{2}}\lambda _q^{\frac{1}{2}N}\lambda _{q + 1}^{\frac{1}{2}N + \frac{1}{2}}    ,
\end{equation}
and
\begin{equation}
{\left\| {{\partial _{tt}}{\mathfrak{D}_{\tilde \mu }}\left( {t,{\lambda _{q + 1}}{{\tilde \Phi }_k}} \right)} \right\|_N}  \lesssim   {{\tilde \mu }^2}\lambda _{q + 1}^N   .
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

