[Lemma lem:fokker_superpo_den of arXiv:2608.30493, '\bf McKean-Vlasov Differential Equations:\\ {An introduction and a focus on some kinetic m'] Let $\nu\in\mathcal{P}(\mathbb{R}^d)$ and let $v:(0,\infty)\to L^{1}(\mathbb{R}^d)$ be a non-negative function

such that 
\begin{equation}
\big[(t,x)\mapsto b\big(t,x,v_t( x)\big) v_t(x)\big], \ \big[ (t,x)\mapsto \sigma \sigma^*\big(t,x,v_t( x)\big) v_t(x) \big] \in L^{1}_{\text{loc}}([0,\infty)\times\mathbb{R}^d).
\end{equation}

Then:

\begin{itemize}
\item[(i)] If $X$ is a solution to MKV$(b,\sigma;\nu)$, with $ [X_t] = v_t (x) d x$ for any $t\geq0$, then $v$ is a weak solution to D-NL-FP$(b,\sigma;\nu)$.
\item[(ii)] [Superposition] Under the additional assumption that the functions 
\begin{equation}
\Big[ t \mapsto \int_{\mathbb{R}^d} \Big( \big|b\big(t,x,v_t(x)\big)\big| +\big\| \sigma \sigma^\top\big(t,x,v_t(x)\big) \big\| \Big)v_t(x) \, d x\Big], \ \Big[  t \mapsto  \int_{\mathbb{R}^d}v_t(x) \, d x\Big] \  \in L^{\infty}_{\text{loc}}([0,\infty),
\end{equation}

if $v$ is a (weak) solution to D-NL-FP$(b,\sigma;\nu)$, 
then there exists a solution $X$ to D-MKV$(b,\sigma;\nu)$ such that $ [X_t] =v_t(x) d x $.

\end{itemize}

