[Thm Theorem10 of arXiv:2412.05521, 'Random attractors for the stochastic Nernst-Planck-Navier-Stokes system with multiplicativ'] Let X be a Banach space and $\varphi$ be a dynamical system defined on X. Given $\varepsilon>0$, we suppose that $\varphi_\varepsilon$ is a random dynamical system over a metric system $(\Omega, \mathcal{F}, P, (\theta_t)_{t \in R})$. Suppose the following three statements are satisfied:\par
		(1)for $P$-a.e.$~\omega \in \Omega$, $t \geq 0$, $\varepsilon_n \rightarrow 0$, $x_n$, $x \in X$, $x_n \rightarrow x$, there holds:
		\begin{align}
			\mathop {lim}\limits_{n \rightarrow \infty} \varphi_{\varepsilon_n}(t, \omega)x_n=\varphi(t)x. 
		\end{align}
		\par
		(2)Let $\mathcal{D}$ be a collection of subsets of X. $\mathscr {A}_0$ is the global attractor of $\varphi$ in $X$. Assume that $\varphi_\varepsilon$ has a random attractor $\mathscr{A}_\varepsilon=\{\mathscr{A}_\varepsilon(\omega)\}_{\omega \in \Omega} \in \mathcal{D}$ and a random absorbing set $\mathcal{K}_\varepsilon=\{\mathcal{K}_\varepsilon(\omega)\}_{\omega \in \Omega} \in \mathcal{D}$ such that for some deterministic positive constant c and for $P$-a.e.$~\omega \in \Omega$,
		\begin{align}
			\mathop {lim}\limits_{\varepsilon \rightarrow 0} sup\|\mathcal{K}_\varepsilon(\omega)\|_X \leq c.
		\end{align}	
		\par
		(3)there exists $\varepsilon_0 > 0$ such that for $P$-a.e.$~\omega \in \Omega$, 
		\begin{align}
			\cup_{0<\varepsilon \leq \varepsilon_0} \mathscr{A}_\varepsilon(\omega) ~is ~precompact~ in~ X.
		\end{align}
		Then, $\mathscr{A}_\varepsilon$ is said to be upper semi-continuous, that is, for $P$-a.e.$~\omega \in \Omega$,
		\begin{align*}
			dist_X(\mathscr{A_\varepsilon}(\omega),\mathscr {A}_0) \rightarrow 0,~as~\varepsilon \rightarrow 0.
		\end{align*}
		Here, $dist_X(\cdot,\cdot)$ denotes the Hausdorff semi-distance given by 
		\begin{align*}
			dist_X(A,B) =\mathop {sup}\limits_{a \in A}\mathop {inf}\limits_{b \in B}d(a,b),
		\end{align*}
		for nonempty sets $A,B \subset X$ on a metric space $(X,d)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:psi_adjoint of arXiv:2604.22528, 'Malliavin calculus for signatures with applications to finance'] The adjoint operator $({\bf\Psi}_{{\color{NavyBlue}{\mathbf{u_1}}}, \ldots, {\color{NavyBlue}{\mathbf{u_n}}}}^{{\color{NavyBlue}{\mathbf{w_1}}}, \ldots, {\color{NavyBlue}{\mathbf{w_n}}}})^*$ is given by
    \begin{equation}
        ({\bf\Psi}_{{\color{NavyBlue}{\mathbf{u_1}}}, \ldots, {\color{NavyBlue}{\mathbf{u_n}}}}^{{\color{NavyBlue}{\mathbf{w_1}}}, \ldots, {\color{NavyBlue}{\mathbf{w_n}}}})^* = {\bf\Psi}^{{\color{NavyBlue}{\mathbf{u_1}}}, \ldots, {\color{NavyBlue}{\mathbf{u_n}}}}_{{\color{NavyBlue}{\mathbf{w_1}}}, \ldots, {\color{NavyBlue}{\mathbf{w_n}}}}.
    \end{equation}
    That is, for $\bm{\ell} \in \TA$, we have
    \begin{equation*}
        \langle \bm{\ell},\, {\bf\Psi}_{{\color{NavyBlue}{\mathbf{u_1}}}, \ldots, {\color{NavyBlue}{\mathbf{u_n}}}}^{{\color{NavyBlue}{\mathbf{w_1}}}, \ldots, {\color{NavyBlue}{\mathbf{w_n}}}} (\sigX) \rangle 
        = \bracketsigX{ {\bf\Psi}^{{\color{NavyBlue}{\mathbf{u_1}}}, \ldots, {\color{NavyBlue}{\mathbf{u_n}}}}_{{\color{NavyBlue}{\mathbf{w_1}}}, \ldots, {\color{NavyBlue}{\mathbf{w_n}}}} (\bm{\ell}) }.
    \end{equation*}

