\begin{align}

  {(G(x),W_{ x})}\textrm{ is a non-degenerate Gaussian vector  {with density bounded by some $ c _{ G}<\infty $}. }
\end{align}
Then for $ I\subseteq \mathbb R$
\begin{align*}\mathbf E(\#\{x\in Q: \nabla G(x) = 0, G(x)\in I\})\le c  | Q | | I |
\end{align*}
where $ c<\infty $ depends  on   the law of $ G$.

