[Lemma 42 of arXiv:2609.04139, 'The conformally invariant metric on CLE$_4$ II:\\ existence of geodesics'] \begin{enumerate}
	\item Almost surely, for each $\SCL_1, \SCL_2 \in \Gamma_{\BD}$, we have $D_{\Gamma_{\BD}}^{\BD}(\SCL_1, x) + D_{\Gamma_{\BD}}^{\BD}(x, \SCL_2) = D_{\Gamma_{\BD}}^{\BD}(\SCL_1, \SCL_2)$ for all $x \in K_{\SCL_1,\SCL_2}$.
\item Almost surely, $\Gamma_{\SCL_1,\SCL} \subset \Gamma_{\SCL_1,\SCL_2}$, $\widetilde\Gamma_{\SCL_1,\SCL} \subset \widetilde\Gamma_{\SCL_1,\SCL_2}$, $K_{\SCL_1,\SCL} \subset K_{\SCL_1,\SCL_2}$, and $\widetilde K_{\SCL_1,\SCL} \subset \widetilde K_{\SCL_1,\SCL_2}$ for all $\SCL_1, \SCL_2 \in \Gamma_{\BD}$ and $\SCL \in \Gamma_{\SCL_1,\SCL_2}$. 
\item Almost surely, $\#\CS_{\SCL_1,\SCL_2}^n \le 2^{n \cdot o(1)}$ as $n \to \infty$ for all $\SCL_1, \SCL_2 \in \Gamma_{\BD}$. 
\item Almost surely, for each $\SCL_1, \SCL_2 \in \Gamma_{\BD}$,
\begin{equation*}
	\sup\nolimits_{S \in \CS_{\SCL_1,\SCL_2}^n} D_{\Gamma_{\BD}}^{\BD}\left(\SCB^S(\SCL_1; D_{\Gamma_{\BD}}^{\BD}), \SCB^S(\SCL_2; D_{\Gamma_{\BD}}^{\BD})\right) \to 0 \quad \text{as } n \to \infty,
\end{equation*}
where, as in the statement of \Cref{prop:hitting-two-metric-balls}, we set $\SCB^{S}(\SCL; D_{\Gamma_{\BD}}^{\BD}) \defeq \SCB_{D_{\Gamma_{\BD}}^{\BD}(\SCL, S)}(\SCL; D_{\Gamma_{\BD}}^{\BD})$.

\end{enumerate}

[Definition d: av set of set of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $n\in\N, p\in\N_0$, $B\in\cB^d$ with $\lambda_d(B)\in(0,\infty)$, and $x_1,...,x_n\in\R^d$. We say that $x_1,...,x_n$ form an \textit{averaging set} of $B$ of order $p$ and size $n$ if they form an averaging set of $\lambda_d|_B$ of order $p$ and size $n$, i.e.,
    \begin{equation}
        \frac{1}{\lambda_d(B)}\int_B x^{\otimes q}\, dx = \frac{1}{n} \sum_{k=1}^n x_k^{\otimes q},\quad q\in\{0,...,p\}.
    \end{equation}

[Definition $Q$-left-deformed and $Q$-right-deformed KL divergences of arXiv:2411.08295, 'Improving the convergence of Markov chains via permutations and projections'] Let $\pi \in \mathcal{P}(\mathcal{X})$. Let $Q \in \mathcal{I}(\pi) \cap \mathcal{L}$ be an isometric involution transition matrix, $P,L \in \mathcal{L}$. The $Q$-left-deformed KL divergence from $L$ to $P$ with respect to $\pi$ is defined to be
	\begin{align*}
		{}^Q D^{}_{KL}(P \| L) := D^{\pi}_{KL}(QP \| QL) := \sum_x \pi(x) \sum_y QP(x,y) \ln \left(\dfrac{QP(x,y)}{QL(x,y)}\right),
	\end{align*}
	where the usual conventions of $0 \ln (0/0) := 0$ and $0 \cdot \infty := 0$ applies. Note that the dependency on $\pi$ of ${}^QD_{KL}$ is suppressed.

	Similarly, we define the $Q$-right-deformed KL divergence from $L$ to $P$ with respect to $\pi$ to be
	\begin{align*}
		D^{Q}_{KL}(P \| L) := D^{\pi}_{KL}(PQ \| LQ).
	\end{align*}

[Lem 111 (regularity for SDE coefficients) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] For $t\geq q_0$ we have the bounds 
	\[
    \bigg\|\frac{\partial}{\partial y}
    	\Big[(\sF^N)^{1/2}\Big]\bigg\|_\infty
    +\bigg\|\frac{\partial}{\partial y}
    	\Big[(\swww^N)^{1/2}\Big]\bigg\|_\infty
	\le 
	\bigg(\frac{\trK L}{\sep}\bigg)^{O(1)} \MAX_N\,,
	\]
with $\MAX_N$ as in \eqref{e:MAX.N} and Proposition~\ref{p:Y.kolmogorov}. 

\begin{proof}
We again simplify notation by suppressing the dependence on $N$ inside the proof. We only consider $\sF$, since $\swww$ is handled identically.
Similarly as in the proof of Lemma~\ref{l:sp.smooth.reg}, we express
	\[
	\sF(t,y)
	=\frac{\overline{\varrho_{F,t}*\sphi}(y)}
		{\overline{\varrho_t*\sphi}(y)}
	\equiv \frac{\Num(t,y)}{\Den(t,y)}\,.
	\]
(Note the abuse of notation, in that we now use $\Num$ to refer to the numerator of $\sF$ rather than the numerator of $\sB$.)
Recall from
\eqref{e:denominator.lbd} and the surrounding discussion that $\Den(t,y)\ge 1/\trK^{O(1)}$ for all $|y|\le 5\trK$, while 
$\Num(t,y)=0$ for $|y|\ge3\trK+1$. Therefore, similarly to the derivation of \eqref{e:sB.quotient.rule}, we have
	\beq
	\bigg|\frac{\partial}{\partial y} \sF(t,y)\bigg|
	\le \trK^{O(1)}
	\bigg| 
	\frac{\partial_y\Num(t,y)}{\Den(t,y)^{1/2}}
	- \sF(t,y) \partial_y \Den(t,y)
	\bigg|\,,\eeq
and we aim to show that $\partial_y\sF/\sF^{1/2}$ is bounded. To this end, we calculate
	\[\bigg|\frac{\partial}{\partial y}
	\Num(t,y)\bigg|
	=\bigg|\frac{\partial}{\partial y}
	\overline{\varrho_{F,t}*\sphi}(y)\bigg|
	= \bigg| \int_{\R^3} F(t,\vx)
		\overline{\sphi}'
		(y-(\vec{1},\vx))
		\,\varrho_t(d\vx)\bigg|\,.\]
Recalling the explicit definition \eqref{e:spatial.smoothing.product} of $\sphi$ from Definition~\ref{d:sp.smooth}, we have 
	\begin{align*}
	\bigg|
	\frac{d}{dy}\overline{\sphi}(y)
	\bigg|
	&=\bigg|
	\lim_{\delta\to0}
	\int_{H(y)}
	\frac{\sphi(\vy+(\delta,0,0))
		-\sphi(\vy)}{\delta}
	\,d\vy\bigg|\\
	&\le  \frac{1}{\sep^4}\int_{H(y)}
	\bigg| (\sphicirc)'\bigg(
		\frac{y_1}{\sep}
		\bigg) \bigg|
	\sphicirc\bigg(\frac{y_2}{\sep}
		\bigg)
	\sphicirc\bigg(\frac{y_3}{\sep}
		\bigg)
	\,d\vy \\
	&\le 
	\frac{O(1)}{\sep^4}
	\int_{H(y)} 
	\sphicirc\bigg(
		\frac{y_1}{\sep}
		\bigg)^{1/2}
	\sphicirc\bigg(\frac{y_2}{\sep}
		\bigg)
	\sphicirc\bigg(\frac{y_3}{\sep}
		\bigg) 
	\,d\vy\\
	&\le
	\frac{O(1)}{\sep^4}\bigg\{
	\int_{H(y)} \sphicirc\bigg(\frac{\vy}{\sep}\bigg)\,d\vy\bigg\}^{1/2}
	\bigg\{
		\int_{H(y)} \boldsymbol{1}\{\|\vy\|_\infty\le\sep\}\,d\vy
		\bigg\}^{1/2}
	\le \frac{O(1)}{\sep^{3/2}} \overline{\sphi}(y)^{1/2}
	\end{align*}
where the third line above follows from Lemma~\ref{l:bump.sqrt.lipschitz} applied to the function $\sphicirc:\R\to[0,\infty)$, and the first inequality in the last line above is by the Cauchy--Schwarz inequality. We then apply the Cauchy--Schwarz inequality to bound 
	\begin{align*}
	\bigg|\frac{\partial}{\partial y}
	\Num(t,y)\bigg|
	&=\bigg|\frac{\partial}{\partial y}
	\overline{\varrho_{F,t}*\sphi}(y)\bigg|
	= \bigg| \int_{\R^3} F(t,\vx)
		\overline{\sphi}' (y-(\vec{1},\vx))
		\,\varrho_t(d\vx)\bigg|\\
	&\le \frac{1}{\sep^{O(1)}}
		 \bigg| \int_{\R^3} F(t,\vx)
		 \overline{\sphi} (y-(\vec{1},\vx))^{1/2}
		\,\varrho_t(d\vx)\bigg|\\
	&\le\frac{1}{\sep^{O(1)}}
	\bigg\{
	\int_{\R^3} F(t,\vx)\,\varrho_t(d\vx)
	\bigg\}^{1/2}
	\bigg\{  \int_{\R^3} F(t,\vx)
		 \overline{\sphi} (y-(\vec{1},\vx))
		\,\varrho_t(d\vx)
	\bigg\}^{1/2} \\
	&=
	\frac{1}{\sep^{O(1)}}
	\bigg\{
	\int_{\R^3} F(t,\vx)\,\varrho_t(d\vx)
	\bigg\}^{1/2} \Num(t,y)^{1/2}\,,
	\end{align*}
where the last equality is by recalling the definition of $\Num$. Recalling the definition of $F$ from \eqref{e:sde.F.N}, we can argue similarly as 
in the proof of Lemma~\ref{l:sp.smooth.reg}
(using the quenched bounds of Lemma~\ref{l:tQ.first.quenched}) to bound 
	\[\bigg\{\int_{\R^3} F(t,\vx)\,\varrho_t(d\vx)\bigg\}^{1/2}
	\le  L^{O(1)}
	\MAX_N\,.
	\]
Altogether this bounds the first term in \eqref{e:sF.quotient.rule}, giving
	\[
	\bigg|\frac{\partial}{\partial y}\Num(t,y)\bigg|
	\le \frac{L^{O(1)}\MAX_N}
