				\begin{align}
					\E_x \Bigl(  \ee^{-q T^{\lambda,\gamma} - p \int_0^{T^{\lambda,\gamma}} 1_{\left\{U_s<b\right\}} \mathrm{d} s} \; \1_{\{T^{\lambda,\gamma} < \infty\}}\Bigr) &= \frac{\int^\infty_0 \ee^{-\varphi_{q+\lambda}y}\, \Bigl(1 +  \gamma \int^b_0 \overline{w}_b^{(q+\gamma_p,-\gamma_p)}(y+a;u) \dd u\Bigr) \dd y}{\int^\infty_0 \ee^{-\varphi_{q+\lambda}y} \,  \overline{z}_b^{(q+\gamma_p,-\gamma_p)}(y+a) \dd y} \overline{z}_b^{(q+\gamma_p,-\gamma_p)}(x) \notag \\
					&\quad - \gamma \int^b_0 \overline{w}_b^{(q+\gamma_p,-\gamma_p)}(x;u) \dd u. 


				\end{align}

