[Proposition 8 of arXiv:2608.27166, 'Well-posedness and regularity of stochastic heat equations on moving domains'] Assume
$
\norm{K}_{L^\infty(D)}\leq1.
$
If $n\geq3$, then there is a constant $C=C(n,\lambda,\Lambda,B,T_0,D)$ such that
\begin{align}
U_{k,a}^{D}
&\leq
\frac{C^k}{a^{2/(n+1)}}
\left(
U_{k-1,a}^{D}
+
X_{k-1,a}^{*,D}
\right)
\left(U_{k-1,a}^{D}\right)^{1/(n+1)} .

\end{align}
For $n=1,2$ and every $\mu\in(0,1/3)$, the same estimate holds with $1/(n+1)$ replaced by $\mu$ and $2/(n+1)$ replaced by $2\mu$.

[Prop Prop local asymp expect CR 1 8 of arXiv:2604.15146, 'Renormalised two-point functions of CLE$_4$ gaskets'] There is an explicit constant $\mathbf{C}_{\rm{SLE}4}^{\rm loop}$ such that as 
$\max(\varepsilon_1,\varepsilon_2)\to 0$, we have that
\begin{multline*}
\mathbb{P}(E_{\varepsilon_1,\varepsilon_2}^v)
=
\varepsilon_{1}^{1/8}
\varepsilon_{2}^{1/8}
(\mathbf{C}_{\rm{SLE}4}^{\rm loop})^2
\,
\mathbb{E}
\big[
\CR(z_1,\widehat{D}_{r_0}(z_1))^{-1/8}
\CR(z_2,\widehat{D}_{r_0}(z_2))^{-1/8}
\1_{E_{r_0}}
\big]
(1+o(1))
.
\end{multline*}
Above, $\widehat{D}_{r_0}(z_1)$ and
$\widehat{D}_{r_0}(z_2)$
are random simply connected domains around
$z_1$, respectively $z_2$,
corresponding to the connected component of
$z_1$, respectively $z_2$, in
$
D\setminus
\overline{
\bigcup_{\mathcal{C}\in \mathfrak{C}_{r_0}}\mathcal{C}
}
.
$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor 11 of arXiv:2506.17045, '\LARGE{On bivariate Archimax copulas: Level sets, mass distributions and related results}'] Let $\gamma \in \mathcal{P}_\mathcal{W}$, $\vartheta \in \mathcal{P_A}$, $C$ be its corresponding Archimax copula and let $L$, $R$ be defined according to eq. \eqref{eq:definition_L_R_measure}. Then the following assertions hold:
    \begin{itemize}
        \item[$(i)$] If $\gamma$ has full support and $L = 0$ as well as $R = 1$, then $\mathrm{supp}(\mu_{C}) = \mathbb{I}^2$.
        \item[$(ii)$] If $\gamma$ is strict and $\vartheta$ has full support, then $\mathrm{supp}(\mu_{C}) = \mathbb{I}^2$.
        \item[$(iii)$] If $\mathrm{supp}(\mu_{C}) = \mathbb{I}^2$, then $\gamma$ is strict and $L = 0$ as well as $R = 1$.
    \end{itemize}

[Theorem 12 of arXiv:2606.16083, 'Eyring--Kramers asymptotics for infinite-dimensional stochastic gradient systems'] Let us assume $U\in C^3(B)$ with $F(x_-)=F(x_+)=0$. The trial state $\Psi_\beta$ defined in \eqref{Eq:def_main_trial_state} is a well-defined element of $\operatorname{dom}(\mathcal{L}_\beta)$
   and there exists a constant $C>0$ such that for $\beta$ large enough, and $r,\kappa$ small enough, we have 
    \begin{align*}
         \|\mathcal{L}_\beta \Psi_\beta\|_{L^2(\mu_\beta)}^2  \leq  C e^{-\beta h}/\beta
    \end{align*}
 as well as
   \begin{align*}
         \frac{1}{\beta}\|A^{1/2}\nabla \Psi_\beta\|_{L^2(\mu_\beta)}^2= \left(1  +  O\! \left(\frac{1}{\sqrt{\beta}}\right)\right)\sum_{j=1}^{m_0} \frac{2C_j \alpha_j e^{-\beta h}}{\pi(C_-  +  C_+)} ,
   \end{align*}
Furthermore, there exists a $\tau>0$ small enough, such that $\Psi_\beta(x)=\pm 1$ for $x\in B_\tau(x_\pm)$.

[Proposition prop:main of arXiv:2510.24424, 'On the Fourier Coefficients of Critical Gaussian Multiplicative Chaos'] Let $\mathcal{F}_{n,t}$ be defined as in Equation (equation eq:def_Ft of the paper). Then there exists a constant $C(A)=C>0$ such that for large enough $t,n>0$,  $\mathcal{F}_{n,t}(\Delta)$ satisfies the bound
    \begin{equation}
        \mathcal{F}_{n,t}(\Delta)\leq C\sqrt{r_n}\cdot\frac{e^{r(\Delta)}}{r(\Delta)} \cdot\frac{t}{(t-{r(\Delta)})+1}\cdot\frac{\log\big(r(\Delta)\big)^4}{(r(\Delta)-r_n)\lor 1}
    \end{equation}
    uniformly in $\Delta\in [0,\Delta_n]$.

