[Proposition thm:jdt-forest-evolution-weak of arXiv:2607.24018, 'Jeu de taquin forests \\ and the inverse infinite RSK correspondence'] Let $T$ be an IYT.
	There exists a canonical injection
	\begin{equation}  
	    \iota\colon \big\{\text{peripheral trees in }\Phi(T)\big\} 
	\to \big\{\text{all trees in }\Phi(J(T))\big\}
	\end{equation}
	uniquely characterized by the following property: for each 
	peripheral tree $\tau$ in $\Phi(T)$, $\tau$ is 
	a subtree of its image $\iota(\tau)$ under the natural 
	inclusion of graphs.

[Lemma lemup of arXiv:2411.18359, 'Large systems of symmetrized trapped Brownian Bridges and Schr\"odinger processes'] If $\phi:{\mathcal X } \to \mathbb{R}$ is an upper semi continuous function for which
the tail condition (tail of the paper) holds, and the Large Deviations upper bound holds with the good rate function $I:{\mathcal X } \to [0,\infty]$, then
\begin{equation}
    \limsup_{\epsilon \to 0}\epsilon\log \mathbb{E}[e^{\frac{\phi( Z_\epsilon)}{\epsilon}}]\leq\sup_{x\in {\mathcal X }}\{\phi(x)-I(x)\}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop LDPforERHyp of arXiv:2609.02682, 'LDP for tensor forms'] Consider the sequence of random tensors $\{\mathcal{G}^{(v)}_n\}_{n\ge1}$ defined in (equation DEF:hyptensor of the paper) and assume $ n^{1-v}\ll p_n $.
Then the following conclusions hold:
 \begin{itemize}
     \item[(i)] Suppose ${\bf{X}}=(X_1,\ldots,X_n)$ where $X_i \overset{\text{i.i.d.}}{\sim} \mu$. Then $N_n(\mathcal{G}^{(v)}_n,\phi,{{\bf X}})$ satisfies a (conditional) LDP with speed $n$, and the good rate function
 \begin{align*}
J_{\mathbbm{1}}(t)=\inf_{{\boldsymbol f}\in \mathcal{F}_c:\ { G}_{\mathbbm{1},\phi}({\boldsymbol f})={t}}  \left\{ \int_0^1\sum_{r=1}^c f_{r}(u)\log \frac{f_{r}(u)}{\mu_r}du\right\},
\end{align*}
where $\mathbbm{1}$ denotes the constant graphon that equals 1 at all points in $[0,1]^v$.
\item[(ii)] For any $\beta\in\mathbb{R}$ we have
\begin{align*}
 Z_{\mathcal{G}^{(v)}_n}(\beta,\mu)\xrightarrow[n\to\infty]{\mathbb P}\sup_{{\boldsymbol f}\in \mathcal{F}_c}\left\{ \beta\,{G}_{\mathbbm 1,\phi}({\boldsymbol f})
-\int_0^1\sum_{r=1}^c f_r(u)\log \frac{f_r(u)}{\mu_r}\,du\right\}.
		\end{align*}


Moreover, the maximizers of the above optimization problem are attained.
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 32 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] The integral operator
\begin{align*}
\mathscr{I} : \big( C([0,T],W), \| \cdot \|_{\infty} \big) \to \big( \scrd_X^{2\alpha}([0,T],W), \interleave \cdot \interleave_{X,2\alpha} \big), \quad Y \mapsto \bigg( \int_0^{\cdot} Y_s \, ds, 0 \bigg)
\end{align*}
is a continuous linear operator between Banach spaces with operator norm bounded by $\| \mathscr{I} \| \leq T^{1-2\alpha}$.

