[Theorem thm:resultknownmask of arXiv:2602.11129, 'Information-Theoretic Thresholds for Bipartite Latent-Space Graphs Under Noisy Observation'] Consider any fixed $p \in (0,1)$. 
    Then, the following holds with probability $1 - o(n)$ over $\ \mathbf{M} \sim \mathbb{M}(n, m, q)$ whenever $d \gg \log(n)^3$.

    \vspace{0.5em}
    If $p \neq \frac{1}{2}$ then:\hspace{1em} $\begin{aligned}[t]
            \hspace{0.8cm}\dtv{\mathbb{W}_{\mathbf{M}}(n, m, p, d)}{ \mathbb{M}(n, m, p)} &= \begin{cases} 1 - o(1) & \text{if } d \ll nmq^2  \hspace{1.3cm} \text{ or } \hspace{.1cm} d \ll m\sqrt{n}q  \\
            o(1) & \text{if } d \gg nmq^2\log(n) \hspace{.1cm} \text{ and } \hspace{.1cm} d \gg m\sqrt{n}q \log(n)
            \end{cases}
        \end{aligned}$

    \vspace{0.5em}
    If $p = \frac{1}{2}$ then:\hspace{1em} $\begin{aligned}[t]
        \hspace{0.8cm}\dtv{\mathbb{W}_{\mathbf{M}}(n, m, p, d)}{ \mathbb{M}(n, m, p)} &= \begin{cases} 1 - o(1) & \text{if } d \ll nmq^2 \\
            o(1) & \text{if } d \gg nmq^2\log(n)
            \end{cases}
        \end{aligned}$

    \vspace{0.5em}
    \noindent Here, $o(1)$ denotes a function that tends to zero as $n \rightarrow \infty$. Recall further that $m \ge n$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 21 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] We define the linear map $\tilde\Delta^\partial : \scal{\tcT} \to \scal{\tcT} \otimes \scal{\tcT_1}$ recursively via
	\begin{align*}
		&\tilde \Delta^\partial \<bs(2)0> = \<s(1)0> \otimes \partial \, \<b1> + \<b1> \otimes \partial \, \<s(1)0>, \qquad && \tilde \Delta^\partial \<ps(2)0> = \<s(1)0> \otimes \partial \, \<p1> + \<p1> \otimes \partial \, \<s(1)0>,
		\\
		&\tilde \Delta^\partial \<b0> = 0, \qquad &&\tilde \Delta^\partial \<p0> = 0,
		\\
		& \tilde \Delta^\partial \<s(1)0> = \mathbf{1} \otimes \partial \, \<s(1)0>, \qquad && \tilde \Delta^\partial X^k = 0,
		\\
		&\tilde \Delta^\partial \tau \sigma = \tilde \Delta^\partial \tau \tilde \Delta \sigma + \tilde \Delta \tau \tilde \Delta^\partial \sigma,
		\\
		&\tilde \Delta^\partial \mcI_\mfl^k \tau = (\mcI_\mfl^k \otimes \id) \tilde \Delta^\partial \tau + \sum_{|j|_\mfs < o(\mcI_\mfl^k \tau) } \frac{X^j}{j!} \otimes \mcI_{(\mfl, \partial)}^{k+j} \tau.
	\end{align*}
	For each $x,y \in \mbR^d$, we also define a linear map ${\chi}_x^y : \langle \tcT_1 \rangle \to \mbR$ as follows. For each $\mfl \in \mfL_+, \mft \in \mfL_-$ we set
	\begin{align*}
		\chi_z^{z'} (\mcI_{(\mfl, \partial)}^k \sigma) &= k! \mcQ_{X^k} [ J^\mfl(z') H_{\sigma; \eps, \delta}^{z, g}(z') + \mathcal{N}_{\gamma_{\sigma}}^{\mfl} H_{\sigma; \eps, \delta}^{z, g}(z')] 
		\\
		& \qquad - \sum_{|l|_\mfs < |\mcI_{\mfl}^k \sigma|_\mfs} \frac{(z'-z)^l}{l!} D^{k+l} K_\mfl \ast \mcR H_{\sigma; \eps, \delta}^{z, g}(z).
	\end{align*}
	We also define
	\begin{align*}
		\chi_z^{z'}(\Xi_{(\mft, \partial)}) &= \begin{cases}
			g_\eps(z') \qquad & \text{ if } \mft = \<b0>,
			\\
			g_{\delta}(z') \qquad & \text{ if } \mft = \<p0>,
			\\
			\eps^{-1/2} \partial_x K \ast g_{\eps, \delta}(z') \qquad & \text{ if } \mft = \<s(1)0>.
		\end{cases}
	\end{align*}
	Finally, we extend this definition by declaring that for $\eta \in \mcT_+$ we have
	\begin{align*}
		\chi_z^{z'}(\mcI_{(\mfl, \partial)}^k \sigma \cdot \eta) = \chi_z^{z'}(\mcI_{(\mfl, \partial)}^k \sigma) \cdot \gamma_{z'z}(\eta)
	\end{align*}
	where $\gamma_{z'z}$ is the element of $\mathcal{G}_+$ corresponding to $\Gamma_{z'z}$.

[Defn of arXiv:2601.00119, 'The largest common subtree of two random trees'] Let $\mu$ be a measure on $\mathbb{N}$. A random plane tree $\tau$ is called a \emph{Bienaym\'{e} tree with offspring distribution $\mu$} if it satisfies the following properties:
\begin{enumerate}
    \item[(a)] The law of $\mathrm{k}_\varnothing(\tau)$ is $\mu$.
    \item[(b)] For all $k \geq 1$ such that $\mu(k) > 0$, conditionally given that $\mathrm{k}_\varnothing(\tau) = k$, the subtrees $\theta_1\tau,...,\theta_k\tau$ are i.i.d.~and with the same law as $\tau$.
\end{enumerate}
We frequently call (b) \emph{the branching property} of Bienaymé trees. If $\sum_{k \geq 0} k\mu(k) = 1$ and $\mu(0) > 0$, then we call $\tau$ and $\mu$ \emph{critical}, and it is well-known that $\tau$ is almost surely finite.

[Prop thm1 of arXiv:2411.06245, 'On the longest/shortest negative excursion of a Lévy risk process and related quantities'] For $r>0$, $x\in \mathbb{R}$ and $\mathbb{E}[X_1]>0$, we have
\begin{equation}
\mathbb{P}_{x}\left( \bar{U}_{\infty }<r\right)=
\mathbb{E}\left[ X_{1}\right]\frac{\Lambda \left( x,r\right) }{\Upsilon
\left( r\right) },
\end{equation}
where
\begin{equation}
\Upsilon \left( r\right) =\int_{0}^{\infty }\dfrac{z}{r}\mathbb{P}\left(
X_{r}\in \mathrm{d}z\right).
\end{equation}

