[Theorem 15 (Study determinant--permanent comparison) of arXiv:2607.20329, '2607.20329'] For every $n\ge1$,
		\begin{equation}
			\Sdet(G_n^{\Hh})^2
			\le_{\mathrm{Lt}}|\per_{\Hh}G_n^{\Hh}|^2.
		\end{equation}
		Equivalently, $\Delta_n^{\Hh}\le_{\mathrm{Lt}}X_n^{\Hh}$.

[Proposition 2 of arXiv:2608.06646, 'Three-dimensional stochastic wave equation with non-Lipschitz coefficients'] Assume that $b$ and $\sigma$ are globally Lipschitz with Lipschitz constants $L_b$ and $L_\sigma$, respectively. Assume further that the initial condition $u_0$ is bounded with bounded derivatives and that $v_0$ is bounded. Under assumption~\eqref{E:ZeroOrderDifference}, there exists a unique random field solution $u$ to the stochastic wave equation~\eqref{E:SWE} such that, for all $p\ge 2$ and $T>0$,
    \begin{equation} 
        \sup_{(t,x)\in [0,T]\times \mathbb{R}^3}\mathbb{E}|u(t,x)|^p
        \le (3M)^{\frac{p}{2}} e^{cp\beta_0 T}.
    \end{equation}
    Here 
    \begin{equation}
    M=3\lr{T\|v_0\|_{L^\infty(\R^3)}+\|u_0\|_{L^\infty(\R^3)}+T\|\nabla u_0\|_{L^\infty(\R^3)}}^2 +Cp|\sigma(0)|^2\frac{T^{\nu+1}}{\nu+1}+C|b(0)|^2T^4\,,
\end{equation}

  and 
  $\beta_0 = C L_b^{1/2} + C p^{1/(\nu+1)} L_\sigma^{2/(\nu+1)}$, and the parameter $\nu$ is defined in~\eqref{E:ZeroOrderDifference}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 10 of arXiv:2512.08745, 'Variance strikes back: sub-game--perfect Nash equilibria in time‑inconsistent $N$‑player g'] Let $\hat\alpha \in \cA_1$, and $\varepsilon >0$. We define
\begin{align*}
\ell_\varepsilon \coloneqq \inf \Big\{ \ell >0 : \exists (t,\alpha) \in [0,T] \times \cA_1, \; \P \big[\big\{\omega \in \Omega: J^1\big(t,\omega,\hat\alpha;\xi\big) < J^1\big(t,\omega,\alpha\otimes_{t+\ell}\hat\alpha;\xi\big) - \varepsilon \ell \big\}\big] >0 \Big\}.
\end{align*}
We say that $\hat\alpha$ is a {\rm sub-game--perfect mean-field equilibrium} for this mean-field game if it holds that $\ell_\varepsilon >0$ for any $\varepsilon >0$, and $\P^{\hat\alpha} \circ (X^1_{\cdot \land t}, \hat\alpha_t)^{-1} = \xi_t$, for $\d t\text{\rm--a.e.} \; t \in [0,T]$.

[Lemma lem:upper_bound_on_width of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] Suppose that we have the same setup described above.  Then,  there exists a universal constant $c>0$,  and a constant $\varepsilon_0 \in (0,1)$ depending only on $a,\delta,N$ and $\theta$ such that
\begin{align*}
L_j \leq \frac{c}{(\theta - 3a\log(2)) \log(1/\varepsilon)} \quad \text{for all} \quad \varepsilon \in (0,\varepsilon_0) , \,\,\, j \in \{1,2,3,4\}.
\end{align*}

[Theorem T:L2Lim of arXiv:2412.03521, 'On ergodic properties of stochastic PDEs'] Suppose that conditions~(it:i-InvMea of the paper) and~(it:iii-InvMea of the paper) of
  Theorem~(T:InvMea of the paper) hold. Let the following condition~(it:ii'-InvMea of the paper)
  replace condition~(it:ii-InvMea of the paper) of Theorem~(T:InvMea of the paper):

  \begin{enumerate}[wide, labelwidth=!, labelindent=0pt, label=\emph{(\roman*')}]
    \setcounter{enumi}{1}
    \setlength\itemsep{.1in}

    \item For $t \ge 0$, $x \in \mathbb{R}$ and a Borel measure
      $\mu$ on $\mathbb{R}^d$, let $J_0(t,x;\mu)$ be the solution to the homegenous
      equation (see~(equation E:def-J0 of the paper)). We assume that the following limit
      exists:
      \begin{align}
        \lim_{t\to\infty} \sup_{x\in\mathbb{R}^d} \left| J_0(t,x;\mu)\right| <\infty.
      \end{align}

  \end{enumerate}

  \noindent We also assume that the nonnegative weight function $\rho$ is an
  element in $L^1(\mathbb{R}^d)$, which does not necessarily need to be admissible (see
  Definition~(D:Rho of the paper)). Recall that $u(t,\cdot)$ is the solution
  to~(equation E:SHE of the paper). Then the following existence and uniqueness statements hold:

  \begin{enumerate}[wide, labelwidth=!, labelindent=0pt, label=\emph{(\arabic*)}]
    \setlength\itemsep{.1in}

    \item There exists a random field $Z=\{Z(x);\;x\in\mathbb{R}^d\}$
      such that $Z(\cdot)\in L_\rho^2(\mathbb{R}^d)$ a.s. and
      \begin{equation}
        u(t,\cdot) \stackrel{\text{(d)}}{\longrightarrow} Z,
          \quad \text{as $t\to\infty$,}
          \quad \text{in $L_\rho^2(\mathbb{R}^d)$.}
      \end{equation}

    \item Suppose $u_1$ and $u_2$ are two solutions
      to~(equation E:SHE of the paper) starting from $\mu_1$ and $\mu_2$, respectively. Assume
      that both $\mu_i$ satisfy~(equation E:InitData-Limit of the paper). Let $Z_1$ and $Z_2$ be
      the respective limiting random fields given in part~(it:L2Lim-1 of the paper). Then
      we have
      \begin{align}
        \lim_{t\to\infty} \sup_{x\in\mathbb{R}^d} \left|J_0(t,x;\mu_1-\mu_2)\right| = 0
        \quad \Longrightarrow \quad Z_1 \stackrel{(d)}{=} Z_2\:,
      \end{align}
      where the notation $Z_1 \stackrel{(d)}{=} Z_2$ denotes that the two random
      fields follow the same law.

  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

