body:
[Defn def local solution of arXiv:2411.01847, 'Well-Posedness of Stochastic Chemotaxis System'] We say that $(u,v,\tau)$ is a local mild solution to the system ((main of the paper)) if
	\begin{enumerate}
    \item$\tau$ is a stopping time, and $(u, v)$ is a progressively measurable stochastic process that takes values in $C(\bar{\mathcal{O}})\times W^{1,\infty}(\mathcal{O})$.

    \item There exists a non-decreasing sequence of stopping times $\{\tau_l, l \geq 1\}$ such that $\tau_l \uparrow \tau$ almost surely as $l \to \infty$, and for each $l$, the pair $(u(t), v(t))$ satisfies:
   \begin{align*}
    u(t) &= e^{-tA} u_0 - \int_0^{t} e^{-(t - s) A} \left( \nabla \cdot \left( \chi u(s) \nabla v(s) - g(u(s)\right)\right)\, ds

    + \int_0^t  e^{-(t - s) A} \sigma(u(s)) \, dW_s,\\
    v(t) &= G * u(t),
    \end{align*}
    for all $t \leq \tau_l$.
\end{enumerate}

[Prop eq:need at least rlogr Poisson subcritical of arXiv:2608.25065, 'Detection of first homology via random geometric graphs in the thermodynamic regime'] \label[prop]{need at least rlogr Poisson version}
    Let $0< \underline{\lambda} \le \overline{\lambda} < \infty$.
    Then there exist $q>0, c_2 > 0$
    depending on $\underline{\lambda},\overline{\lambda},d$
    such that for all sufficiently small $r > 0$,
    we have
    \begin{equation} 
        \mathbb{P}\left( 
        \begin{array}{c} 
        \exists z \in \ker(Z_1(G^n_M(r)) \to H_1(M)) \\
        \mbox{ such that } z \notin Z_1^{q r|\log r|}(G^n_M(r))
        \end{array}
        \right)
        \ge 1 - e^{-c_2 r^{-1}}.
    \end{equation}
    Moreover, if $\underline{\lambda} > \lambda_c$, for any $\kappa > 0$,
    there exists $q>0$
    depending on $\underline{\lambda},\overline{\lambda},d,\kappa$ such that for all sufficiently small $r>0$,
    if $\underline{\lambda} \le nr^d \le \overline{\lambda}$
    we have
    \begin{equation} 
        \mathbb{P}\left( 
        \begin{array}{c} 
        \exists z \in \ker(Z_1(\mathring{G}^n_M(r)) \to H_1(M)) \\
        \mbox{ such that } z \notin Z_1^{q r|\log r|}(G^n_M(r))
        \end{array}
        \right)
        \ge 1 - r^\kappa.
    \end{equation}

