[Corollary 31 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Assume that $k_0$ satisfies condition \eqref{eqn-k_0}, i.e.  $k_0> \frac d2 +1$. Then there  exists a constant $C$ independent of $n$ such that $\d t \otimes \d \mathbb{P}$-a.e.,
\begin{equation}
\begin{aligned}
\Vert \bB_{0,n}(\bu_n,\bu_n) \Vert_{\rU_0^\prime} &\leq C \lvert \bu_n \rvert_{\StokesH}^2,
\\
\newK  \Vert \bar{R}_{0,n}(\phi_n,\phi_n) \Vert_{\rU_0^\prime}
   &\leq C \lvert \cp_n \rvert_{\newone{H}} \lvert \phi_n \rvert_{\newone{H}},
\\
\Vert B_{1,n}(\bu_n,\phi_n) \Vert_{\newonep{V}} &\leq C \lvert \bu_n \rvert_{\StokesH}^{1-\frac d4} \lvert \nabla \bu_n \rvert_{\mathbb{L}^2}^{\frac d4} \lvert \phi_n \rvert_{\newone{H}},
\\
\Vert \newG_{0,n}(t,\bX_n) \Vert_{\ell^2(\nU^\prime)}^2 &\leq C (\lvert \bu_n \rvert_{\StokesH}^2 + \lvert \tilde{h}(t) \rvert^2).
\end{aligned}
\end{equation}

