	\|\mathcal J^{(2)}_{s,t}\|_{\mathcal L(\mathcal X\times \mathcal X;\mathcal X)}\leq C_\gamma\exp\left(\gamma\int_s^t\|u_r\|_{\mathcal H^2}^2dr+C_\gamma(t-s)\right),\quad t\geq s\geq0.
	\end{equation}

