[Coro c:step of arXiv:2411.12003, 'Central Limit Theorem for non-stationary random products of $\SL(2, \R)$ matrices'] Under the assumptions of  Theorem~(t:proba of the paper),
    there exists a constant $K$ such that if for some $\rho>0$, some $a$, some $n,n'\ge n_0$, \emr{with $n_0$ given by Lemma~(l:var-lower of the paper), as soon as} $\frac{n}{2}\le n'\le 2n$, one has

    \begin{equation}
        \rho^{\textcolor{black}{2+{\varepsilon}}} N'_{\rho}(\widetilde{\xi}_{a;n}+\widetilde{\xi}_{a+n;n'})\le \frac{1}{100}
    \end{equation}
    and

    \begin{equation}
        \rho^{\textcolor{black}{2+{\varepsilon}}} \frac{K}{(n+n')^{\textcolor{black}{{\varepsilon}/2}}} e^{\frac{\rho^2}{2}} \le \frac{1}{100},
    \end{equation}
    then
    \[
        N'_{\rho}(\widetilde{\xi}_{a;n+n'}) \le N'_{\rho}(\widetilde{\xi}_{a;n}+\widetilde{\xi}_{a+n;n'})+ 2 \frac{K}{(n+n')^{\textcolor{black}{{\varepsilon}/2}}} e^{\frac{\rho^2}{2}}.
    \]

[Prp 47 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Let $(F,R,\mu)$ be in $\bbF^{\circ}$.
  Set $\g{c}{suffcond2,1}=\left[\mu(F)^{1/2}\g{c}{unihk,1}\right]^{2\kappa-1}$ and $\g{c}{suffcond2,2}=\left[\mu(F)^{1/2}\g{c}{c_1,1}\right]^{2\kappa-1}$.
\begin{itemize}
  \item [$\mathrm{(i)}$]If $F$ is compact, then it holds that
  \begin{align}
    \|P_th\|_{\Lip^{\kappa}}\lesssim \g{c}{unihk,1} t^{-2\kappa}\|h\|_{L^1(F,\mu)},
  \end{align}
  and
  \begin{align}
    \|P_th\|_{\Lip^{\kappa}}\lesssim \g{c}{suffcond2,1} t^{-(3\kappa-1)}\|h\|_{L^2(F,\mu)},
  \end{align}
  for any $t\in(0,1],\;\kappa\in [1/2,1],$ and $h\in L^2(F,\mu)$.

  \item [$\mathrm{(ii)}$]If $F$ is compact, and satisfies assumption $\rm{(A1)}$,
  then it holds that
  \begin{equation}
    \|P_th\|_{\Lip^{\kappa}}\lesssim\g{c}{c_1,1}t^{-\frac{2\kappa s_0+3\kappa-1}{1+s_0}}\|h\|_{L^1(F,\mu)},
  \end{equation}
  and
  \begin{equation}
    \|P_th\|_{\Lip^{\kappa}}\lesssim \g{c}{suffcond2,2} t^{-(3\kappa-1)}\|h\|_{L^2(F,\mu)},
  \end{equation}
  for any $t\in(0,1],\;\kappa\in [1/2,1],$ and $h\in L^2(F,\mu)$.
  \item [$\mathrm{(iii)}$]If $(F,R,\mu)$ satisfies assumption $\rm{(A2)}$,
  then it holds that
  \begin{equation}
    \|P_th\|_{\Lip^{\kappa}}\lesssim \g{c}{c_1,2}t^{-\frac{2[(1+s_0)\theta-s_1]\kappa+s_0\theta+s_1}{2(1+s_0)\theta}}\|h\|_{L^1(F,\mu)},
  \end{equation}
  and
  \begin{equation}
     \|P_th\|_{\Lip^{\kappa}}\lesssim  \g{c}{suffcond1,3} t^{-[\kappa-\frac{s_1}{2(1+s_0)\theta}(2\kappa-1)]}\|h\|_{L^2(F,\mu)},
  \end{equation}
  for any $t\in(0,1],\;\kappa\in [1/2,1],$ and $h\in L^2(F,\mu)$.
  \item [$\mathrm{(iv)}$]If $(F,R,\mu)$ satisfies assumption $\rm{(A3)}$,
  then it holds that
  \begin{equation}
    \|P_th\|_{\Lip^{\kappa}}\lesssim \g{c}{c_1,3}t^{-\frac{2[(1+s_0)\Theta-s_1]\kappa+s_0\Theta+s_1}{2(1+s_0)\Theta}}\|h\|_{L^1(F,\mu)},
  \end{equation}
  and
  \begin{equation}
     \|P_th\|_{\Lip^{\kappa}}\lesssim  \g{c}{suffcond1,4}t^{-[\kappa-\frac{s_1}{2(1+s_0)\Theta}(2\kappa-1)]} \|h\|_{L^2(F,\mu)},
  \end{equation}
  for any $t\in(0,1],\;\kappa\in [1/2,1],$ and $h\in L^2(F,\mu)$. Here, $\Theta=\frac{1+s_0-s_1}{1-(s_0-s_1)(2+s_0)}$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm commutation relation for chordal with marked point u infty of arXiv:2505.16093, 'Multiple chordal SLE($\kappa$) and quantum Calogero-Moser system'] In the upper half plane $\mathbb{H}$, $n$ chordal SLEs start at $x_1,x_2,\ldots,x_n\in \partial{\mathbb{H}}$ with a marked boundary point $u$. 
\begin{itemize}

\item[(i)] Let the infinitesimal diffusion generators be
\begin{equation}
\mathcal{M}_i=\frac{\kappa}{2} \partial_{ii}+b_i(x_1, x_2,\ldots, x_n,u) \partial_i +\sum_{j \neq i} \frac{2}{x_j-x_i}\partial_j 
\end{equation}

where $\partial_i=\partial_{x_i}$. If n SLEs locally commute, then the associated infinitesimal generators satisfy:
\begin{equation}
[\mathcal{M}_i, \mathcal{M}_j]=\frac{4}{(x_i-x_j)^2}(\mathcal{M}_j-\mathcal{M}_i)
\end{equation}
There exists a partition function $\psi(\boldsymbol{x})$ such that the drift term $b_i(\boldsymbol{x})$ is given by:
\begin{equation}
b_i(\boldsymbol{x})= \kappa \partial_i \log \psi
\end{equation}
where $\psi$ satisfies the null vector equations with an undetermined function $h_i(x)$.
\begin{equation}
\frac{\kappa}{2} \partial_{ii} \psi+\sum_{j \neq i} \frac{2}{x_j-x_i}\partial_i \psi+ \left[\left(1-\frac{6}{\kappa}\right) \sum_{j \neq i}\frac{1}{(x_j-x_i)^2}+h_i(x_i)\right]\psi=0
\end{equation}

\item[(ii)]
 By analyzing the asymptotic behavior of two adjacent growth points $x_i$ and $x_{i+1}$ ( with no marked points between $x_i$ and $x_{i+1}$ on the real line $\mathbb{R}$), we can further show that the $h_i(x)=h_{i+1}(x)$ in null vector equations ((null vector equations in mathbb H of the paper)). As a corollary, if all growth points lie consecutively on the real line $\mathbb{R}$ with no marked points between them, then there exists a common function $h(x)$ such that $h(x)=h_1(x)=\ldots=h_n(x)$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary FCLTApplicableUnderMixing of arXiv:2412.01635, 'On the Weak Convergence of the Function-Indexed Sequential Empirical Process and its Smoot'] Let the conditions of Theorem (SupremumInequalityUnderMixing of the paper) be fulfilled for  some $\nu > 2$ and $\lambda > 0$ and suppose there is a constant $1 \leq K < \infty $ with 
\begin{equation}
\sup_{1 \leq t \leq n, n \in \mathbb N} \sup_{f \in \mathcal F} \E{|f(X_{t,n})|^{\nu\frac{2+\lambda}{2}}} \leq K.
\end{equation} 
Then (equation DEF:AEC of the paper) holds for $\mathbb Z_n$ for $\rho$ from Theorem (SupremumInequalityUnderMixing of the paper) and fidi-convergence of $\mathbb Z_n$ implies weak convergence in $\ell^\infty([0,1]\times\mathcal F).$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 30 (Continuous local sewing) of arXiv:2609.01190, 'Rough differential equations on manifolds via natural bundles'] Let $[U,V]\subseteq\Rsf$ be an interval and let $K:\Delta[U,V]\to\Rsf^m$ be a function. Assume that $|K(s,t)|=0$ for every $(s,t)\in\Delta[U,V]$ such that $\omega(s,t)=0$ and that there are constants $C,M\in (0,\infty)$ such that 
	\begin{equation}

		|K(s,t)-K(s,u)-K(u,t)| \leq C|K(s,u)|\omega(u,t)^\frac{1}{p} + M\omega(s,t)^\frac{3}{p}
	\end{equation}
holds for every $(s,t)\in [U,V]^3$ satisfying $s\leq u\leq t$ and $\omega(s,t)\leq 1$. Then there exist constants $\delta\in (0,1)$ and $L \in (0,\infty)$ such that 
	\[
		| K(s,t) | \leq L M\omega(s,t)^\frac{3}{p}
	\] 
holds for every $(s,t)\in\Delta[U,V]$ such that $\omega(s,t)<\delta$. The constant $\delta$ depends only on $p$ and $C$ while $L$ only on $p$.

