[Theorem mainthm of arXiv:2603.24499, 'A central limit theorem for connected components of random coverings of manifolds with nil'] Suppose $G$ is a $\mathscr{T}$-group with at least linear subgroup growth, 
then the leading asymptotics of the mean and variance of the random variables $\mathsf{K}_{G,n}$ are given by
\begin{eqnarray*}
\mathbb{E}\mathsf{K}_{G,n}&\sim & 
\frac{1}{\alpha_G-1}\times{\alpha_G}^{-\left(\frac{m_G-1}{\alpha_G}\right)}
\times(x\mathcal{K}_G)^{\frac{1}{\alpha_G}}
\times n^{\frac{\alpha_G-1}{\alpha_G}}\times(\ln n)^{\frac{m_G-1}{\alpha_G}}
\ , \\
{\rm Var}(\mathsf{K}_{G,n}) & \sim & 
\frac{1}{\alpha_G(\alpha_G-1)}\times{\alpha_G}^{-\left(\frac{m_G-1}{\alpha_G}\right)}
\times(x\mathcal{K}_G)^{\frac{1}{\alpha_G}}
\times n^{\frac{\alpha_G-1}{\alpha_G}}\times(\ln n)^{\frac{m_G-1}{\alpha_G}}
\ . 
\end{eqnarray*}
Moreover, the normalized random variables
\[
\frac{\mathsf{K}_{G,n}-\mathbb{E}\mathsf{K}_{G,n}}{\sqrt{{\rm Var}(\mathsf{K}_{G,n})}}
\]
converge in distribution and in the sense of moments to the standard Gaussian $\mathcal{N}(0,1)$. Namely, we have
\[
\lim\limits_{n\rightarrow\infty}\mathbb{E}\left[f\left(
\frac{\mathsf{K}_{G,n}-\mathbb{E}\mathsf{K}_{G,n}}{\sqrt{{\rm Var}(\mathsf{K}_{G,n})}}\right)\right]
=\frac{1}{\sqrt{2\pi}}\int\limits_{-\infty}^{\infty}f(s)\ e^{-\frac{s^2}{2}}\ {\rm d}s\ ,
\]
for all $f$'s that are bounded continuous functions, or polynomials. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 9 (Gaussian anti-concentration) of arXiv:2605.03100, 'Berry-Esseen bounds for multivariate martingale difference sequences in the Kolmogorov dis'] \cite[Lemma A.1]{chernozhukov2017central}
Let $\bm{Z} \sim \mathcal{N}(\bm{0},\bm{\Sigma})$ be a $d$-dimensional Gaussian random variable and $\mathcal{A} \in \mathscr{H}_d$. Define
\begin{align*}
\mathcal{A}^{\varepsilon} = \{\bm{x} \in \mathbb{R}^d: \inf_{y \in \mathcal{A}}\|\bm{x} - \bm{y}\|_{\infty} \leq \varepsilon\}, \quad \text{and} \quad \mathcal{A}^{-\varepsilon} = \{\bm{x} \in \mathcal{A}: \forall \bm{y} \text{ with } \|\bm{x} - \bm{y}\|_{\infty} \leq \varepsilon, \bm{y} \in \mathcal{A}\}.
\end{align*}
Then it can be guaranteed that
\begin{align*}
\mathbb{P}(\bm{Z} \in \mathcal{A}^\varepsilon) - \mathbb{P}(\bm{Z} \in \mathcal{A}) \lesssim \sqrt{\frac{\log_+d}{d_{\min}(\bm{\Sigma})}}\varepsilon,\quad \text{and} \quad \mathbb{P}(\bm{Z} \in \mathcal{A}) - \mathbb{P}(\bm{Z} \in \mathcal{A}^{-\varepsilon}) \lesssim \sqrt{\frac{\log_+d}{d_{\min}(\bm{\Sigma})}}\varepsilon.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn 21 of arXiv:2510.22155, 'Random walks in space-time random media in all spatial dimensions: the full subcritical fl'] Let us define the difference between the cumulant  generating function of the $k$-point motion and that of $k$ independent motions sampled according to $\mu^{\otimes k}$.
    \begin{equation}\mathcal K(\x,\boldsymbol\beta; k):= \log \int_{I^k} e^{\sum_{i=1}^k    \beta_i\bullet (   a_i-   x_i)} \boldsymbol p^{(k)}(\x,\dr\bfa)\;\;\;-\;\;\;\sum_{i=1}^k\log M(   \beta_i).
    \end{equation}

[Theorem thm:absorbing of arXiv:2607.04620, 'The Exact Ville Identity\\ \large From the Absorbing Case to the General Law\\ with an App'] Let $(M_n)$ be a nonnegative supermartingale with $M_0=1$, let $b>1$, and suppose (ass:absorbing of the paper) holds and $O_b<\infty$. Then
\begin{equation}
  \mathbb{E}[M_{T_b}\mathbf{1}(T_b<\infty)]=1-D_b
  \quad\Longrightarrow\quad
  \mathbb{P}(T_b<\infty)=\frac{1-D_b}{b+O_b}.

\end{equation}

