body:
[Proposition 27 of arXiv:2606.17501, 'Critical spectral behavior and large deviations for geometric $\alpha$-stable processes'] \la{prop:Harris}
  The $h$-transformed process $\bfM^{h} = (\bP_{x}^{h}, X_{t}^{h})$ is Harris recurrent,
  that is, for a non-negative function $f$,
  \begin{align}

    \int_{0}^{\infty} f(X_{t}^{h}) dt = \infty \quad \bP_{x}^{h}\text{-a.s.}\
    \text{for all $x \in \bR^{d}$}
  \end{align}
  whenever $m(\{x : f(x) > 0\}) > 0$.

[Lemma 28 (Regularisation) of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] Assume the setting of Theorem~\ref{lwp:rough:initial:data} $i)$.
		\begin{enumerate}
			\item Let $(u,\sigma)$ be the $(p,\kappa,s,q)$-solution granted by Theorem~\ref{lwp:rough:initial:data}\ref{it:lwp:rough:initial:data:1} or~\ref{it:lwp:rough:initial:data:2}. Then
			\begin{align}
				u&\in H^{\theta,r}_{\loc}(a,\sigma; \nH^{2-4\theta,\zeta}(\sO)), \quad \zeta\in [q,\infty),\, r\in (2,\infty),\, \theta\in [0,1/2),\\
				u &\in C_{\loc}^{\theta,4\theta}((a,\sigma)\times \sO), \quad \theta \in [0,1/2).
			\end{align}
			\item Let $(u,\sigma)$ be the $(p,\kappa,s,q)$-solution granted by Theorem~\ref{lwp:rough:initial:data}\ref{it:lwp:rough:initial:data:3} or~\ref{it:lwp:rough:initial:data:4}. Then 
			\begin{align}
				u&\in H^{\theta,r}_{\loc}(a,\sigma; \nH^{3-4\theta,\zeta}(\sO)), \quad \zeta\in [q,\infty),\, r\in (2,\infty),\, \theta\in [0,1/2),\\
				u &\in C_{\loc}^{\theta,6\theta}((a,\sigma)\times \sO), \quad \theta \in [0,1/2).
			\end{align}
		\end{enumerate}

[Lemma lem.clock-decomp of arXiv:2605.26082, 'Quantitative Einstein relation for reversible diffusions in a random environment'] Let $\alpha\in(0,\delta/2)$, let $\zeta>0$, let $\theta\in(0,1/4)$, and let $\varepsilon>0$ satisfy $\varepsilon(1-\alpha)<\alpha$.
			There exist deterministic constants $C,C'<\infty$ and $c>0$, a deterministic exponent $\sigma\in(0,1)$, and a random scale $\lambda_*^{\rm sc}\colon\Omega\to(0,1]$ such that
			\begin{equation}
					\mathbb{Q}\bigl(\lambda_*^{\rm sc}\le\lambda\bigr)\le C'\exp\bigl(-c (\log(1/\lambda))^\sigma\bigr)\qquad\text{for every }\lambda\in(0,1]\, .
				\end{equation}
				The constants $C,C',c,\sigma$ depend only on the displayed parameters and on $(d,\Lambda,r_0,\beta_h)$. For $\mathbb{Q}$-a.e.\ $\omega$ and every $0<\lambda\le\lambda_*^{\rm sc}(\omega)$,
			\begin{equation}
			\begin{aligned}
				|\eta(\lambda)-\mathbb{E}[e^{-2V(0)}]|
				&\le C\rho(\lambda)^{-2}\lambda^{-2\varepsilon}
				+C\rho(\lambda)^{-1/2+\theta}
				+Ce^{-c3^{h(\lambda)}}\\
				&\qquad
				+C\rho(\lambda)^{13/12}3^{(d/2+7/12-\beta_h/2)h(\lambda)-\delta m(\lambda)}\, .
			\end{aligned}
			\end{equation}

