body:
[Prop 2 (Existing upper-bound and a variant) of arXiv:2605.03528, '\bf Kolmogorov-Smirnov distance and discrepancies {\em versus} Wasserstein distances'] $(a)$ Let $\mu$ and $\nu$ two probability measures on $\big([0,1]^d, {\cal B}or([0,1]^d),\lambda_d\big)$ be such that $\mu\big((0,1]^d\big)= \nu\big((0,1]^d\big) =1$. Then, 
\begin{equation}
{\cal W}^p_p(\mu, \nu)\le\diamd^p\frac{2^p+1}{2}\sum_{\ell= 1}^{+\infty} 2^{-p\ell} \sum_{F\in {\cal P}_\ell}|\mu(F)-\nu(F)|
\end{equation}
where  $\displaystyle \diamd=\sup_{x,y\in (0,1]^d}|y-x|$ depends on $p$, $d$ and the norm $|\cdot|$ on $(0,1]^d$ and
\begin{equation}
{\cal P}_\ell= \Big\{a+(-2^{-(\ell+1)}, 2^{-(\ell+1)}]^d,\; a = \frac{2\mathbf{k}+\mbox{\bf 1}}{2^{\ell+1}},\,\mathbf{k}\!\in\{0,\ldots,2^{\ell}-1\}^d  \Big\}
\end{equation}
with $\mbox{\bf 1} = (1,�\ldots,1)$. Note that ${\rm card}({\cal P}_\ell)= 2^{d\ell}$. We also have for any $\ell_0\in\mathbb{N}^*$,
\begin{equation}
{\cal W}^p_p(\mu, \nu)\le{\diamd^p}\bigg(\frac{2^p+1}{2}\sum_{\ell= 1}^{\ell_0} 2^{-p\ell} \sum_{F\in {\cal P}_\ell}|\mu(F)-\nu(F)|+2^{-p\ell_0}\bigg).
\end{equation}

\noindent $(b)$ When $\mu$ and $\nu$ are probability measures on $([0,1]^d, {\cal B}or([0,1]^d),\lambda_d)$, then~\eqref{eq:FG2} still holds with the family of $(\tilde{{\cal P}_\ell})_{\ell\ge0}$, where $\tilde{{\cal P}_\ell}$ is a partition of $[0,1]^d$ which only differs from ${{\cal P}_\ell}$ for  the semi-open boxes with a multi-index $\mathbf{k}=(k_1,\ldots,k_d)\!\in\{ 0,\ldots,2^{\ell}-1\}^d$ for which there exists $i\!\in\{1,d\}$ such that $k_i=0$. When such is the case, the semi-open box $]\!] \frac {\mathbf{k}}{2^{\ell}}, \frac {\mathbf{k}+ \mathbf{1}}{2^{\ell}}]\!] = \frac{2\mathbf{k}+\ \mathbf{1}}{2^{\ell+1}}+(-2^{-(\ell+1)}, 2^{-(\ell+1)}]^d$ is replaced\footnote{More simply, when a semi-open box of ${\cal P}_\ell$ has one or several faces which are included in the faces of $[0,1]^d$, we add them to define the elements of $\tilde{{\cal P}_\ell}$.} by
$$
\Big]\!\Big[ \frac {\mathbf{k}}{2^{\ell}}, \frac {\mathbf{k}+ \mathbf{1}}{2^{\ell}}\Big]\!\Big]:= \left\{u\in[0,1]^d, \frac{k_i}{2^{\ell}}<u^i\le \frac{k_i+1}{2^{\ell}} \textnormal{ if  $k_i\ge 1$}, 0\le u^i\le \frac{1}{2^{\ell}} \textnormal{ if  $k_i=0$}\right\}.
 $$

