[Theorem 3 (Explicit fourth-power normalization) of arXiv:2608.20101, '\bfseries Largest bulk gap of the complex Ginibre ensemble'] Under \eqref{eq:Bassumption}, for every \(x\in\R\),
\begin{equation}
 \Pp\{n^2M_n(B)^4\le\beta_n+4x\}\longrightarrow e^{-e^{-x}}.
\end{equation}
Equivalently,
\begin{equation}
 \beta_n^{3/4}\bigl(\sqrt n\,M_n(B)-\beta_n^{1/4}\bigr)
 \ \Longrightarrow\ \Gum.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem of arXiv:2605.10309, 'Exponential Decay of $L^2$-Solutions to Stochastic Nonlinear Schr\"odinger Equations Drive'] {[BRZ14]}
Assume (H1). Then for any $T>0, u_0\in L^2$ and $f\in L^{q_2'}(0,T;L^{p_2'})$, the solution of
\begin{align}
u(t)=U(t,0)u_0+\int_0^tU(t,s)f(s)ds, \ 0\le t\le T,
\end{align}
satisfies the estimate
\begin{align}
\|u\|_{L^{q_1}(0,T;L^{p_1})}\le C_T\left( \|u_0\|_{L^2}+\|f\|_{L^{q_2'}(0,T;L^{p_2'})} \right),
\end{align}
where $(p_1,q_1)$ and $(p_2,q_2)$ are Strichartz pairs, namely,
\begin{align}
& (p,q)\in [2,\infty]\times [2,\infty] : \frac{2}{q}=\frac{d}{2}-\frac{d}{p} , \ \text{if} \ d\not=2, \\
& (p,q)\in [2,\infty)\times (2,\infty] : \frac{2}{q}=\frac{d}{2}-\frac{d}{p} , \ \text{if} \ d=2.
\end{align}
Furthermore, the process $C_t, t\ge0$, can be taken to be $(\mathcal{F}_t)$-progressively measurable, increasing and continuous. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 4 of arXiv:2607.27721, 'Asymptotic bias of the plug-in Shannon entropy estimator \\ under a regularly varying occu'] For all $y>0$,
\begin{align*}
\begin{array}{ll}
|\psi(y)| \leq C(1-\log y) &(0 < y \leq 1),\\
|\psi(y)| \leq y^{-1} &(y \geq 1 ).
\end{array}
\end{align*}

[Prop couple_iid of arXiv:2412.03415, 'Critical first passage percolation on random graphs'] First consider the shortest weight graph ${\sf SWG}^v$ from a single randomly sampled vertex $v$. Fix any $m_n = o(\sqrt{n})$.  Then under Assumptions (ass of the paper):
\begin{enumeratea}
\item {\bf Probability of collision from a single source:} Then the probability of collision $\pr( R_{\mathrm{col}}\leqslant m_n) \to 0$ as $n\to \infty$. 
\item {\bf Coupling to an {\it i.i.d.} sequence:} Let $\mathbf{d}$ be a given degree sequence and let $L_n = \sum_{i=1}^n d_i$. Consider the empirical distribution
 \begin{equation} 
 g^{(n)}_k :=\sum_{i=1}^n \frac{ (k+1)\mathds{1}\{d_i=k+1\}}{L_n}, \qquad k\geqslant 0.
 \end{equation} 
Let $\set{Y_i^{\scriptscriptstyle(n)}:i\geqslant 2}$ be an \emph{i.i.d.}~sequence with distribution $(g^{(n)}_k)_{k\geqslant 0}$.  There is a coupling of $(B_{R_i})_{2\leqslant i\leqslant m_n }$ with $(Y_i)_{2\leqslant i\leqslant m_n}$ such that 
\[\pr(\cap_{i=2}^{m_n}\set{B_{R_i} = Y_i^{\scriptscriptstyle(n)}}) \to 1, \qquad \text{ as } n\to\infty. \]
\item {\bf Collision events from multiple sources:} Next consider the growth from two clusters first from $v$ and then from $u$ as described above. Then $\pr( \min (R^v, \tilde{R}^u) \leqslant m_n) \to 0$ as $n\to \infty$. 
\item {\bf Coupling for multiple sources:} The coupling in (b) with an \emph{i.i.d.}~sequence for a single source ${\sf SWG}^v$ continues to hold starting from two distinct randomly sampled sources.  
\end{enumeratea}

[Theorem mt2 of arXiv:2412.04015, 'Linear fluctuation of interfaces in Glauber-Kawasaki dynamics'] Fix $T\ge 1$, and assume that conditions (equation 2-80 of the paper), (equation 2-90 of the paper)
are in force. In particular, $d=1$ or $2$.  Fix $p\ge 1$,
$0\le t_1<t_2 < \cdots <t_p\le T$ and functions
$F_j\in {\mathscr D}({\mathbb R} \times {\mathbb T}^{d-1})$.  Under the measure
${\mathbb P}_{\nu^N}$, the random vector
$(X^{N}_{t_1}(F_1), \dots, X^{N}_{t_p}(F_p))$ converges in
distribution to the centered Gaussian random vector whose covariances
are given by
\begin{equation*}
\begin{aligned}
\text{\rm Cov\,} \big(\, X_{t}(F) \,,\, X_{s}(G)\,\big)\; & =\;
2 \, \int_0^{s} dr\, \int_{{\mathbb R}\times {\mathbb T}^{d-1}} 
\chi (\phi) \, S_{t-r} \partial_{\vartheta} \Pi F\,
\, S_{s-r} \partial_{\vartheta} \Pi G\, d\vartheta\, d \bar\theta
\\
& +\;
\int_0^{s} dr\, \int_{{\mathbb R}\times {\mathbb T}^{d-1}} 
\widehat c_0(\phi) \, S_{t-r} \Pi F\,
\, S_{s-r} \Pi G\, d\vartheta\, d \bar\theta\;.
\end{aligned}
\end{equation*}
for every $0\le s \le t\le T$, $F$,
$G\in {\mathscr D}({\mathbb R} \times {\mathbb T}^{d-1})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary of arXiv:2608.12415, 'Sharp Phase Transition for Ellipsoid Fitting'] Each non-ideal block-step gets assigned a coefficient factor of at most \[ 
\|c(K)\|_1^{  |V(\tau_i)|/2}\cdot \|c(K)\|_1^{|V(\tau_i)|} \leq \|c(K)\|_1^{2|V(\tau_i)|}
\,.\] (Proof in the paper; no proof environment follows the statement in the TeX.)

