[Proposition 5 of arXiv:2604.11921, 'Replica symmetry up to the de Almeida--Thouless line in the Sherrington--Kirkpatrick model'] \label[proposition]{prop:explicit-RS}
For $\mu=\delta_q$, we have
\begin{equation}
u(t,x)=\frac{\beta^2}{2}(1-t)+\log\cosh x,
\qquad
u_x(t,x)=\tanh x,
\qquad
u_{xx}(t,x)=\sech^2 x,
\qquad q\le t\le 1,
\end{equation}
and
\begin{equation}
u(t,x)=\frac{\beta^2}{2}(1-q)+\E\big[ \log\cosh(x+\beta\sqrt{q-t}\,Z )\big],
\qquad 0\le t\le q.
\end{equation}
Moreover,
\begin{equation}
dX_t=
\begin{cases}
\beta\,dW_t, & 0\le t<q,\\
\beta^2\tanh(X_t)\,dt+\beta\,dW_t, & q\le t\le 1,
\end{cases}
\qquad X_0=h,
\end{equation}
and 
\begin{equation}
X_q\stackrel d= h+\beta\sqrt q Z.
\end{equation}

[Lemma lem: loops no self intersecting of arXiv:2411.16398, 'Large Deviations of Cover Time of Tori in Dimensions $d\geq 3$'] For any distinct $\boldsymbol{x} \neq \boldsymbol{y} \in \mathbb{T}_N$, the loop $\beta=\beta(\boldsymbol{x},\boldsymbol{y})$ satisfies  
    \begin{equation}

        \beta[1,H_{\boldsymbol{x}}-1] \cap \beta[H_{\boldsymbol{x}}+1,L(\beta)-1]=\emptyset,
    \end{equation}
    where $H_{\boldsymbol{x}}$ is the time when the loop $\beta$ first hits vertex $\boldsymbol{x}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 4 of arXiv:2606.18433, '\bfseries \Large On a class of Reflected Mean-Field Stochastic Differential Equations with'] Let $(X^{t,x}_s,A^{t,x}_s)_{t\leq s\leq T}$ be the solution of \eqref{008} and $v \in	C_b^{1,2}\left([0,T]\times \bar{G}\right)$ be a solution to the following integral-PDE with Neumann boundary condition 
	\begin{equation}
		\left\{
		\begin{array}{lll}
			\displaystyle	 \frac{\partial v}{\partial t}(t,x)+ \mathcal{L}v(t,x)=0, \hspace{1.2cm} &t\in [0,T[, x\in G \\\\
			\displaystyle v(T,x)=f(x), &x\in \bar{G}\\\\
			\displaystyle	\frac{\partial v}{\partial n}(t,x)=0, & t\in [0,T[, x\in \partial G.
		\end{array}
		\right.
	\end{equation}
	where $f$ is a bounded function and $\mathcal{L} $ is the associated integro-differential operator such that
	\begin{equation*}
		\begin{split}
			&\mathcal{L} = \mathcal{R} + \mathcal{S},\\
			&\mathcal{R}v(t,x)=\frac{1}{2}\mathbb{E}[\sigma(t,X_t^{0,x_0},x)]. \mathbb{E}[\sigma^\top(t,X_t^{0,x_0},x)].D^2v(t,x) + \mathbb{E}[\mu(t,X_t^{0,x_0},x)].D v(t,x),\\
			&\mathcal{S}v(t,x)=\int_{E}^{}\big[v(t,x+\mathbb{E}[\gamma(t,X_t^{0,x_0},x,e)])-v(t,x)- D v(t,x) .\mathbb{E}[\gamma(t,X_t^{0,x_0},x,e)]\big]\lambda(de).
		\end{split}
	\end{equation*}
	and $$ \frac{\partial v}{\partial n} = \sum_{i=1}^{d} \frac{\partial v}{\partial x_i}  \frac{\partial \varphi}{\partial x_i},\quad \forall x\in \partial G.$$
Then, we have the following representation
\begin{equation}
	v(t,x)=\mathbb{E}\left[f(X^{t,x}_T) \Big| \mathcal{F}_t \right].
\end{equation}

