body:
[Lemma lem:bdry_chaining_tail of arXiv:2507.15589, 'Tightness of approximations to metrics on non-simple conformal loop ensemble gaskets'] There exists $\zeta > 0$ such that the following is true. Assume~(equation eq:epsexp2 of the paper). Then
\begin{equation}

\mathbf{P}\left[ G^{\widetilde{U}}_{\widehat{s},\widehat{t}}\bigl(\abs{s-t}^\zeta+\epsilon^{a_0}\bigr)^c \right] = o^\infty(\abs{s-t}) \quad\text{as } \abs{s-t} \to 0 
\end{equation}
where $\widetilde{U} \subseteq \mathcal {H}$ is the $\abs{s-t}^\zeta$-neighborhood of $\eta[s,t]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 21 of arXiv:2607.08536, 'Soft edge limit of the Laguerre beta-ensemble at the lower edge'] For $1\le k\le n_1=n-\lfloor a\mathfrak{f}(a)\rfloor$ we have 
    \begin{align*}
        \ev[Z_{1,k}]& = O\left(\frac{1}{n-k}+\frac{a^2 k}{n (n-k)^2}\right),\\
        \ev[Z_{2,k}]&=\frac{a^2 k}{n(n-k)^2}+O\left(\frac{a^3 k}{n(n-k)^3}+\frac{a}{(n-k)^2}\right),\\
        \Var[Z_{1,k}] &=\frac{4}{\beta(n-k)}+O\left(\frac{a}{(n-k)^2}\right),\\  \Var[Z_{2,k}]&=\frac{4a^2}{\beta(n-k)^3}+O\left(\frac{a^3}{(n-k)^3 n}\right),\\
        \Cov(Z_{1,k},Z_{2,k})&=O\left(\frac{a}{(n-k)^{2}}\right),
    \end{align*}
    and 
    \begin{align*}
         \ev[Z_{1,k}^4] =O\left(\frac{1}{(n-k)^{2}}\right),  \qquad \ev[Z_{2,k}^4]=O\left(\frac{a^8 k^4}{n^4(n-k)^8}+\frac{a^4}{(n-k)^6}\right).
    \end{align*}
    Each of the $O(\cdot)$ error terms have constants that only depend on $\beta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def: nice_box of arXiv:2608.00399, 'The Heavy-tailed Frog Model'] For $k \in \{0,1,\ldots,k_2\}$, an $m_k$-box is called \textbf{nice} if it satisfies the following:

\noindent\textup{(1)} Base case $(k=0)$: An $m_0$-box is \textbf{nice} if and only if every ordered pair of distinct vertices in the box is connected by a directed edge.

\noindent\textup{(2)} Coarse scales $(k \in \{1,\ldots,k_0\})$: An $m_k$-box is \textbf{nice} if and only if both of the following hold:
\begin{enumerate}
    \item[\textup{I}.] At least a $(1{-}\delta)$-fraction of its $m_{k-1}$-sub-boxes are nice.
    \item[\textup{II}.] For any two nice $m_{k-1}$-sub-boxes $H,H'$ contained in it, there exist vertices $u_1, u_2 \in H$ and $v_1, v_2 \in H'$ such that $u_1 \Rightarrow v_1$ and $v_2 \Rightarrow u_2$ ($H$ and $H'$ are bidirectionally connected). Moreover, we require that the endpoints $u_1, u_2, v_1, v_2$ all lie in sub-boxes that are nice at every scale $j \in \{0,\ldots,k-1\}$.
\end{enumerate}

\noindent\textup{(3)} Dense scales $(k \ge k_0{+}1)$: An $m_k$-box is \textbf{nice} if and only if both of the following hold:
\begin{enumerate}
    \item[\textup{I}.] All of its $m_{k-1}$-sub-boxes are nice.
    \item[\textup{II}.] For any two $m_{k-1}$-sub-boxes $H,H'$ contained in it, there exist vertices $u_1, u_2 \in H$ and $v_1, v_2 \in H'$ such that $u_1 \Rightarrow v_1$ and $v_2 \Rightarrow u_2$, with endpoints $u_1, u_2, v_1, v_2$ lying in sub-boxes that are nice at every scale $j \in \{0,\ldots,k-1\}$.
\end{enumerate}

[Question QLimitExist of arXiv:2411.18563, 'Lower tails for triangles inside the critical window'] Does the  limit 
    \begin{equation}

     \lim_{n \to \infty} \frac{1}{n^{3/2}} \log \mathbb{P}_{c/\sqrt{n}}(X \le \eta \mathbb{E} X)
    \end{equation}
    exist for all $c>0$ and $\eta \in [0,1)$? (Stated as a question by the paper; open unless the paper says otherwise.)

[Defn defn3.9 of arXiv:2411.09988, 'A Study in Markov Chains, Loop-Erased Random Walk and Loop Soups'] If $V = \{x_1, x_2, \ldots, x_k\} \subset A$, let
    \begin{equation}
        F_V(A) = \prod_{j=1}^{k}G_{A_j}(x_j, x_j)
    \end{equation}
    where $A_j = A \backslash \{x_1, \ldots, x_{j-1}\}$. Recall (lem3.8 of the paper). This quantity is independent of the
    ordering of the vertices. We also make the following conventions.
    \begin{itemize}
        \item If $V = A$, we write just $F(A)$ for $F_A(A)$.
        \item If $V \not\subset A$, then $F_V(A) = F_{V\cap A}(A)$.
        \item If $\eta$ is a path, $F_\eta(A)=F_V(A)$ where $V$ is the set of vertices visited by $\eta$.
    \end{itemize}

[Lemma 18 of arXiv:2608.28964, '2608.28964'] For every $T>0$, there exists a constant $C>0$ such that for any $f\in L^2(0,T;L^2(D;\R^2))$, the solution $\psi$ of \eqref{eq l1} satisfies
	\begin{align*}
	\|\psi\|_{L^\infty(0,T;\mathcal H^1)}+\|\psi\|_{L^2(0,T;\mathcal H^2)}+\|\partial_t\psi\|_{L^2(0,T;\mathcal H)}\leq C\exp\left(C\|g\|_{L^\infty((0,T)\times D)}^2\right)\|f\|_{L^2(0,T;L^2(D))}.
	\end{align*}

