[Lemma 7 of arXiv:2609.01296, 'Asymptotic safety regions for Gabor frames generated by Hermite functions'] Let $0< a \leq b$ and $r\geq0$. Define an ellipse
    \begin{equation}
        E_r = \left \{(x,y)\in \R^2 :\frac{x^2}{b^2}+\frac{y^2}{a^2}\leq \frac{r}{\pi} \right \}.
    \end{equation}
There exists an absolute constant $C>0$ such that for every $0 \leq r_1 \leq r_2$ we have
\begin{equation}
     \#\left(( E_{r_2} \setminus E_{r_1})\cap \Z^2 \right) \leq ab(r_2-r_1) + C(a\sqrt{r_2} + b \sqrt{r_2-r_1} + 1).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem A1 of arXiv:2411.01847, 'Well-Posedness of Stochastic Chemotaxis System'] Let $\left(e^{-tA}\right)_{t\geq 0}$ be the Neumann heat semigroup in $\mathcal{O}$.

       Let $\nu_1$ denote the first nonzero eigenvalue of $A$ on $\mathcal{O}$ under Neumann boundary condition. Then, there exists a constant $C$, depending only on $\mathcal{O}$, such that:
      \begin{itemize}
  \item[(\romannumeral 1)] If $1\leq p\leq \infty$, for $t>0$
  \begin{align}
      \|(A+1)^\beta e^{-tA} \omega\|_{p}\leq Ct^{-\beta}e^{-\nu_1t}\|\omega\|_{p},\\
       \|\nabla e^{-tA} \omega\|_{p}\leq C(1+t^{-\frac{1}{2}})e^{-\nu_1t}\|\omega\|_{p},
  \end{align}
holds for all $\omega\in L^{p}(\mathcal{O})$.
  \item[(\romannumeral 2)] If $p\in [2,\infty)$, for $t>0$
  \begin{align}
       \|\nabla e^{-tA} \omega\|_{p}\leq Ce^{-\nu_1t}\|\omega\|_{W^{1,p}(\mathcal{O})},
  \end{align}
is valid for all $\omega\in W^{1,p}(\mathcal{O})$.

\item[(\romannumeral 3)]
If $\beta>0$, $p\in (1,\infty), t>0$, then the operators $(A+1)^\beta e^{-tA}\nabla\cdot$ and $e^{-tA}\nabla\cdot$ both possess extension to  operators from $L^{p}(\mathcal{O})$ into $L^{p}(\mathcal{O})$ which fulfill
  \begin{align}
      &\|(A+1)^\beta e^{-tA}\nabla\cdot w\|_{p}\leq C(\epsilon)t^{-\frac{1}{2}-\beta-\epsilon}e^{-\nu_1 t}\|w\|_{p}, \\
      &\| e^{-tA}\nabla\cdot w\|_{p}\leq Ct^{-\frac{1}{2}}e^{-\nu_1 t}\|w\|_{p},
  \end{align}
  for all $\omega\in (L^p(\mathcal{O}))^2$, any $\epsilon>0$.






	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop p:r-X-Y of arXiv:2411.12003, 'Central Limit Theorem for non-stationary random products of $\SL(2, \R)$ matrices'] Under the assumptions of Lemma~(l:X-Y of the paper), let $K_r:=\textcolor{black}{5\,} C_r^{{\varepsilon}} C_X^{2}$ be the factor that appears in its conclusion~(equation eq:t-bound of the paper). Assume additionally that for some $\rho>0$ one has
\begin{equation}
    \rho^{\textcolor{black}{2+{\varepsilon}}} N_{\rho}(X)\le \frac{1}{100}
\end{equation}
and
\begin{equation}
    K_r \rho^{\textcolor{black}{2+{\varepsilon}}} e^{\frac{\rho^2}{2}} \le \frac{1}{100}.
\end{equation}
Then
\[
N_{\rho}(Y) \le N_{\rho}(X) + 2 K_r e^{\frac{\rho^2}{2}}.
\]

[Definition 7 of arXiv:2609.00567, 'Hodge--Tate splitting and Akizuki--Nakano vanishing in positive characteristic'] Consider a pullback square of stacks
  \begin{equation*}
    \begin{tikzcd}
      \mcalY' \arrow[r,"g'"] \arrow[d,"f'"'] & \mcalY \arrow[d,"f"] \\
      \mcalX' \arrow[r,"g"'] & \mcalX.
    \end{tikzcd}
  \end{equation*}
  For \(\mcalF\in\mcalD_{\qcoh}(\mcalY)\), the canonical equivalence \(Lf'^*Lg^*\simeq L(g')^*Lf^*\) and the counit \(Lf^*Rf_*\mcalF\to\mcalF\) give a morphism
  \begin{equation*}
    Lf'^*Lg^*Rf_*\mcalF\xrightarrow{\sim}L(g')^*Lf^*Rf_*\mcalF\to L(g')^*\mcalF.
  \end{equation*}
  Its adjoint under \(Lf'^*\dashv Rf'_*\) is denoted by
  \begin{equation}

    \BC_{f,g}(\mcalF)\colon Lg^*Rf_*\mcalF\to Rf'_*L(g')^*\mcalF
  \end{equation}
   and is called the \emph{base change morphism}. This is a morphism in \(\mcalD_{\qcoh}(\mcalX')\).

[Lemma th:averaged of arXiv:2410.23974, 'Polynomial rate of relaxation for the Glauber dynamics of infinite-volume critical Ising m'] Consider the critical temperature Ising model on $\Lambda_{L}=\llbracket-L,L\rrbracket^{d}$ with $+$ boundary condition in any fixed dimension $d\geq2$. Assume the assumption (equation eq:arm of the paper) is satisfied, then there exists a universal constant $c_{0}(\delta,d)>0$ such that
    \begin{equation}
        \frac{1}{\vert\Lambda_{L}\vert}\sum_{x\in\Lambda_{L}}\big(\langle\sigma_{x}\rangle_{\Lambda_{L}}^{+}\big)^{2}\leq c_{0}L^{-(2\delta\wedge1)}.
    \end{equation}

