[Definition def:lf-insertion-infty of arXiv:2411.19810, 'Radial conformal welding in Liouville quantum gravity'] Let $\beta\in\mathbb{R}$, $(\alpha_i,z_i)\in\mathbb{R}\times\mathbb{H}$ and $(\beta_j,s_j)\in\mathbb{R}\times\partial\mathbb{H}$ for $i=1,...,m$ and $j = 1,...,n$ and the $z_i$'s and $s_j$'s are pairwise distinct. Set 
	\begin{equation*}
	\begin{split}
	&C_{\mathbb{H}}^{(\alpha_i,z_i)_i,(\beta_j,s_j)_j,(\beta,\infty)} =\\ &\prod_{i=1}^m\prod_{j=1}^n(2\mathrm{Im}z_i)^{-\frac{\alpha_i^2}{2}}|z_i|_+^{-2\alpha_i(Q-\alpha_i-\frac{\beta}{2})}|s_j|_+^{-\beta_i(Q-\frac{\beta_i+\beta}{2})}e^{\frac{\alpha_i\beta_j}{2}G_\mathbb{H}(z_i,s_j)+\sum_{i'=i+1}^{m}\alpha_i\alpha_{i'}G_\mathbb{H}(z_i,z_{i'})+\sum_{j'=j+1}^{n}\frac{\beta_j\beta_{j'}}{4}G_\mathbb{H}(s_j,s_{j'}) }.   
	\end{split}
	\end{equation*}
	Let $(h,\mathbf{c})$ be sampled from $C_{\mathbb{H}}^{(\alpha_i,z_i)_i,(\beta_j,s_j)_j,(\beta,\infty)}P_\mathbb{H}\times [e^{(\sum_i\alpha_i+\frac{\beta}{2}+\frac{1}{2}\sum_j\beta_j-Q)c}dc]$, and 
	\begin{equation*}
	    \phi(z) = h(z)+(\beta-2Q)\log|z|_++\sum_{i=1}^m\alpha_iG_\mathbb{H}(z,z_j)+\sum_{j=1}^n\frac{\beta_j}{2}G_\mathbb{H}(z,s_j)+\mathbf{c}.
	\end{equation*}
	We write $\mathrm{LF}_{\mathbb{H}}^{(\alpha_i,z_i)_i,(\beta_j,s_j)_j,(\beta,\infty)}$ for the law of $\phi$ and call a sample from $\mathrm{LF}_{\mathbb{H}}^{(\alpha_i,z_i)_i,(\beta_j,s_j)_j,(\beta,\infty)}$ the Liouville field on $\mathbb{H}$ with insertions $(\alpha_i,z_i)_{1\le i\le m}, (\beta_j,s_j)_{1\le j\le n}, (\beta,\infty)$.

