body:
[Definition def.CFH of arXiv:2411.04778, 'Coupling between Brownian motion and random walks on the infinite percolation cluster'] We denote by $\mathsf{CFH}$$(T,n,y)$ the coupling of $(S_{t},\bar{B}_{t})_{0\leqslant t \leqslant T}$ constructed in the following way. We define that 
		\begin{align}
			\Delta T = T/n, \quad t_k = k \Delta T, \quad I_k = (t_k, t_{k+1}),	\qquad k\in\{0,1,\dots, n-1\}.
		\end{align}
		\begin{enumerate}[label=(\Alph*)]
			\item The processes start from $S_0 = \bar{B}_0 = y$.
			\item Conditioned on $\big(S_{t_i},\bar{B}_{t_i}\big)_{0\leqslant i\leqslant k}$, we sample the increment $\big(\Delta S_{t_k}, \Delta\bar{B}_{t_k}\big)$ 
			\begin{align*} 
				\big(\Delta S_{t_k}, \Delta\bar{B}_{t_k}\big)  \in \varPi\big(p^\omega(\Delta T,S_{t_k} +\cdot,S_{t_k}), \bar{p}(\Delta T,\cdot) \big),
			\end{align*}
			 such that
			\begin{align*} 
				\mathbb{E}^\omega \left[\left\vert \Delta S_{t_k}-\Delta\bar{B}_{t_k}\right\vert \Big\vert \big(S_{t_i},\bar{B}_{t_i}\big)_{0\leqslant i\leqslant k} \right]=W_1\big(p^\omega(\Delta T,S_{t_k}+\cdot,S_{t_k}), \bar{p}(\Delta T,\cdot) \big).
			\end{align*}
			Then we  define 
			\begin{align*} 
				\big(S_{t_{k+1}},\bar{B}_{t_{k+1}}\big) := \big(S_{t_{k}},\bar{B}_{t_{k}}\big) + \big(\Delta S_{t_k}, \Delta\bar{B}_{t_k}\big).
			\end{align*}
			\item Given the sequence $\big(S_{t_k},\bar{B}_{t_k}\big)_{0\leqslant k\leqslant n}$, we sample the trajectories as follows:
			\begin{itemize}[label=---]
				\item $(S_t)_{t \in [0,T]}$ is sampled as the VSRW defined in (equation eq.VSRW of the paper) conditioned on the values $(S_{t_k})_{0\leqslant k\leqslant n}$ at the endpoints $(t_k)_{0\leqslant k\leqslant n}$.
				\item $(\bar{B}_t)_{t \in [0,T]}$ is sampled as Brownian motion with diffusion constant $\bar{\sigma}^2$ conditioned on the values $(\bar{B}_{t_k})_{0\leqslant k\leqslant n}$ at the endpoints $(t_k)_{0\leqslant k\leqslant n}$.
			\end{itemize}
		\end{enumerate}

[Definition Half-Diamond Backtracking Intersection of arXiv:2608.12415, 'Sharp Phase Transition for Ellipsoid Fitting'] Let \(A\) and \(B\) be two \(M_\alpha\)-shapes. We say that the composition
\(A\cdot  B\) forms a \emph{half-diamond backtracking intersection} if
\begin{enumerate}
    \item \(U_A \not\equiv V_B\), where \(U_A\) is the left boundary square
    vertex of \(A\) and \(V_B\) is the right boundary square vertex of \(B\);

    \item the two circle vertices of \(A\) receive the same set of labels in $[d]$ as those in $B$.
\end{enumerate}

[Lemma 16 of arXiv:2607.18104, '2607.18104'] There exist  $c,C>0$ and a coupling $\mathbf{P}$ of $\mathcal{L}_{n}$ under the law $\mathbf{P}_n$ and $\mathcal{L}_{2n}$ under the law $\mathbf{P}_{2n}$  such that all $\delta>0$ and $n \geq 2\delta^{-2}$, 
\begin{equation}
\mathbf{P}\left( \mathsf{D}_{n,\delta} \right) 
\geq 1- C\exp\big(-c\delta^{-\frac{1}{32}}\big),
\end{equation} 
where the event
\begin{equation*}
    \mathsf{D}_{n,\delta} := \left\{ \big(\Lpa(x,s;y,t)\big)_{(x,s;y,t) \in \SetT \cap \mathcal{D}_{\delta^{1/8}}}=\big(\mathcal{L}_{2n}(x,s;y,t)\big)_{(x,s;y,t) \in \SetT \cap \mathcal{D}_{\delta^{1/8}}}  \right\}.
\end{equation*}

