[Defn ofn of arXiv:2506.18207, 'Cartan's Path Development, the Logarithmic Signature and a Conjecture of Lyons-Sidorova'] Assume that $\gamma:[0,T]\to R^d$ is a bounded variation path and $(0,0)=\gamma_0\neq\gamma_T$. We define the associated (with $\gamma$, $T$) normalization operator $\mathcal{A}=\mathcal{A}_{\gamma,T}$ by
$$
\mathcal{A}(\alpha)_t:=k^{-1}A\alpha_t,~\forall~t\in[0,S],
$$
where $\alpha:[0,S]\to R^d$ is a bounded variation path, the rotation $A$ and the scaling $k$ are given by  
\begin{equation}
A
=\left(
\begin{array}{cc}
\cos(\theta) & \sin(\theta) \\
-\sin(\theta) &\cos(\theta)\\
\end{array} 
\right)
=\frac{1}{|\gamma_T|}\left(
\begin{array}{cc}
 x_T & y_T \\
-y_T & x_T\\
\end{array} 
\right),\quad\quad k=|\gamma_T|.
\end{equation}
For any one-form $f(\cdot):=\left(
\begin{array}{c}
f_1  \\
f_2 \\
\end{array} 
\right)(\cdot)$, we define its adjoint operator $\mathcal{A}^*$ by 
\begin{equation*}
\mathcal{A}^*(f)(\cdot)=k^{-1} A^{-1}\left(
\begin{array}{l}
f_1  \\
f_2 \\
\end{array} 
\right)\left(k^{-1}A\cdot\right)
\end{equation*}

[Theorem 5 of arXiv:2604.19924, 'Fluctuation theory for spectrally negative Lévy processes killed by additive functionals'] Let $q \geq 0$ and $x \in (c,b)$. Then 
			\begin{align}
				\E_x\left[e^{-q\tau_b^+-A_{\tau_b^+}};\tau_b^+<\tau_c^-\right]=\frac{W_{{\mathbf{T}}(\nu_A)}^{(q)}(x,c)}{W_{{\mathbf{T}}(\nu_A)}^{(q)}(b,c)},
			\end{align}
			where $W_{\mathbf{T}(\nu_A)}$ is the unique solution to
			\begin{align}
				W_{{\mathbf{T}}(\nu_A)}^{(q)}(x,y)&=W^{(q)}(x-y)+\int_{[y,x]}W^{(q)}(x-z)W_{{\mathbf{T}}(\nu_A)}^{(q)}(z,y){\mathbf{T}}(\nu_A)(dz),\qquad x\geq y.
			\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma approxiamtion IC global of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let $d \geq 2$ and $p\ge 1$.  
		Assume (Hypo-W L of the paper), (Hypo-Q-Pi of the paper), (Hypo-h div of the paper) with $\sigma> \frac{d}{2} + p$, and (Hypo-DNI-1 of the paper). Let $s> \frac{d}{2} + p + \max \{3\zeta,1\}$ where $\zeta=\zeta_{\mathcal Q_1,\mathcal Q_2}$ is given in (equation zeta-Q12 of the paper).  For any $\mathcal{F}_{0}$-measurable $u_0\in H_{\rm div}^s$ and $n\ge1$,  (equation approximation scheme IC global of the paper) admits a global solution $u_n\in D([0,\infty);H_{\rm div}^s)$ such that 
		\begin{equation}
			\sup_{n\ge1} \mathbb E\left[V(\|u_n(t)\|_{H^s}^2)\Big|\mathcal F_0\right]  
			\leq   \Big(V(\|u_0\|^2_{H^s})+\mathscr{G}_2t\Big) {\rm e}^{\mathscr{G}_1t},
			\quad t>0.
		\end{equation}
		Moreover, there exists an $\mathcal{F}_t$-progressively measurable $H_{\rm div}^s$-valued process $u=(u(t))_{t\ge 0}$  and a subsequence of $\{u_n\}_{n\ge1}$  $($still labeled as $\{u_n\}_{n\ge1}$ for simplicity$)$ such that for any $T>0$ and $s'<s$,
		\begin{equation}
			\lim_{n\to\infty}\sup_{t\in[0,T]}\|u_{n}(t)-u(t)\|_{H^{s'}}=0\quad \text{and}\quad  u_{n}\xrightarrow[]{n\to \infty}u \  {\rm in}\ D([0,T];H_{\rm div}^{s'}),\quad T>0
			\quad {\mathbb P}\text{-}{\rm a.s.}
		\end{equation}

