[Thm THM61 of arXiv:2608.16170, '\bf On hitting time distributions of Markov processes with sub-Gaussian heat kernel bounds'] Assume that every $d$-bounded closed subset of $E$ is compact, and that $X$ satisfies one of the following sets of assumptions:
\begin{itemize}
    \item[{\rm(i)}] the symmetry assumptions (H1a) and (H1b);
    \item[{\rm(ii)}] the duality assumptions (H2a) and (H2b);
    \item[{\rm(iii)}] the sector condition (H3), and the associated semi-Dirichlet form $({\mathcal{E}},{\mathcal{F}})$ of $X$ is regular.
\end{itemize}
 If the transition density function of $X$ satisfies the following short-time lower bound estimate at a fixed point $x\in E$:
\[
p(t,x,y)\geq  \frac{C_1}{t^{\alpha/\beta}}\exp\left\{-C_2\left(\frac{d(x,y)}{t^{1/\beta}}\right)^{\beta/(\beta -1)}\right\}, \quad \forall  0<t\leq T, \, y\in E,
\]
for some $\alpha>0$, $\beta>1$, $C_1>0$, $C_2>0$ and $T>0$, then for any $B\in \mathscr{B}^n(E)$, 
\[
        \limsup_{t\downarrow 0}\frac{-t^{1/(\beta-1)}\cdot \left(\log \mathbb{P}^x[\sigma_B\leq t]\right)}{C_2}\leq  \widetilde{d}(x,B)^{\beta/(\beta-1)}.
\]

[Proposition 59 of arXiv:2609.02850, 'Canonical-row Chern flow on Bott--Samelson towers:\\ realizable-volume models for Schubert'] The bundle
\begin{equation}
 \cW_{u,\mu}^{\mathrm{at}}
 :=\bigoplus_{a:c_a>0}(\widehat C_a\otimes\cM)
 \oplus\bigoplus_{j=1}^n(F_j^{(\ell)})^{\oplus d_j}
\end{equation}
is globally generated and satisfies
\begin{equation}
 \rho_*\ctop(\cW_{u,\mu}^{\mathrm{at}})
 =\overline\Pi_u^{(z)}x^\mu(h,h_z).
\end{equation}
Its rank is $\ell+|\mu|$.

[Lemma 34 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] There exists a constant $C_{25}>0$, which depends on the following values:

\begin{equation*}
\delta, \quad T, \quad \|u_0\|_{H^1(\Omega)},\quad \|v_0\|_{H^1(\Omega)},\quad \|w_0\|_{H^1(\Omega)},
\end{equation*}

such that the following uniform estimate is satisfied:

\begin{equation*}
\sup_{\varepsilon \in (0,1)} \left\{ \int_0^T \|v_{\text{{\tiny $\delta,\!\varepsilon$}}}'(t)\|_{L^2(\Omega)}^2dt
+\left( \sup_{0 \le t \le T} \|v_{\text{{\tiny $\delta,\!\varepsilon$}}}(t)\|_{H^1(\Omega)} \right)^2 \right\} \le C_{25}.
\end{equation*}

