body:
[Theorem 17 of arXiv:2609.03750, '\bf Pullback Measure Attractors, Zero-Noise Limits, and Moderate Deviations for 2D Stochas'] Suppose Hypotheses \ref{PEeqAssum-2.2}, \ref{PEeqAssum-2.3}, \ref{PEeqAssum-2.4} and \eqref{PETNs-3.01} hold. Then, for every $\epsilon\in(0,\epsilon_0)$, the measure evolution process $S_\epsilon$ on $\mathcal P_{4,z}(H)$ has a unique $\mathfrak D$-pullback measure attractor $\mathscr A_\epsilon$. For every $\tau\in\mathbb R$,
	\begin{align}
		\mathscr A_\epsilon(\tau)
		=\bigcap_{s\ge0}
		\overline{\bigcup_{t\ge s}
			S_\epsilon(\tau,\tau-t)\mathscr K(\tau-t)}.
	\end{align}
	Moreover, $\mathscr A_\epsilon(\tau)\subset\mathscr K(\tau)$; in particular, every attractor section is a compact subset of $\mathcal P_{4,z}(H)$ in the ambient weak topology.

[Lemma lm:consis of arXiv:2606.12143, 'Continuous stochastic flows driven by white noise and their duals'] Let $\eta\in\{0,1\}^2$ and suppose that $(\sigma,b)$ satisfy Assumption~(assu:H of the paper) and conditions~(item:1a of the paper), (item:1b of the paper), (item:2c of the paper), and~(item:2d of the paper) on ${\mathbb R}$. Then the following properties hold:
\vspace{-0.5em}
\begin{enumerate}[label=(\roman*)]
    \item Almost surely, for any $x\in {\mathbb R}$, the set $M_I(x)$ is dense in $I$.
    \vspace{-0.5em}
    \item Suppose further that the associated stochastic flow $\mathcal S$ on $I\times {\mathbb R}$ with boundary conditions $\eta$ exists. Then, almost surely, for all $(a,r)\in I\times {\mathbb R}$ and $x\ge r$,
    \begin{align}
        \mathcal S_{r,x}(a) = \inf \left\{ \mathcal S_{r_n,x}(a_n):\,r_n< r,\, \mathcal S_{r_n,r}(a_n)>a,\, (a_n,r_n)\in \mathcal I \right\}.
    \end{align}
\end{enumerate}

