body:
[Theorem 3 (Endpoint-conditioned representation of the local objective) of arXiv:2608.29107, 'PathGuide: Dynamic Classifier-Free Guidance via On-Policy Transport Alignment'] Fix \(y\), \(\psi \in C_c^\infty(\mathbb{R}^d)\), and a committed past schedule \(\vec{\omega}_i\).
Under Assumptions~\ref{ass:conditional-path-regularity} and~\ref{ass:endpoint-posterior}, the exact
local objective \eqref{eq:exact-local-objective} admits the endpoint-conditioned form
$\mathcal{L}_i(\omega_i \mid y;\vec{\omega}_i,\psi)
=$
\begin{align}
\left( 
\int_{\R^d}
\int_{\R^d}
(
u_{t_i}(x\mid y,x_1)
-
v_{t_i}^\theta(x\mid y;\omega_{t_i})
)\, 
\frac{
p_{t_i}(x\mid y,x_1)\,q(x_1\mid y)
}{
p_{t_i}(x\mid y)
}\,
\dd x_1
\cdot
\grad \psi(x)\,
\hat p_{t_i}(x\mid y;\vec{\omega}_i)\,\dd x \right)^2,

\end{align}
an identity that is exact at the population level.

[Proposition prop.reg of arXiv:2605.05904, 'Schr\"odinger's problem with constraints'] Under Assumption (a:main of the paper), the following statements hold:
\begin{enumerate}
\item  For any $t\in (0,1], y\in E $, there exists $q(\cdot, t; \cdot, y) \in C^{1,2}([0,t)\times E)$ such that
\begin{align} 
\begin{split}
\bbP^{s,z}(Z_t\in dy)&=q(s,t;z,y)dy,  \quad s<t,\, z\in E\quad \text{and}\\
L(s,t;z)&:=\bbP^{s,z}(Z_t=\ell)=1-\int_E q(s,t;z,y)dy, \quad s<t,\,\, z\in E. 
\end{split}
\end{align}
Moreover, if $\ell$ is finite, for all $t>s$ and $y\in E$ we have
\[
\lim_{z\rightarrow \ell}q(s,t;z,y)=0.
\]
\item  The transition density $q$ and its derivatives satisfy the following bounds:
\[
|D_s^\alpha D_z^\beta q(s,t;z,y)|\leq c(t-s)^{-\frac{1+2\alpha +\beta}{2}}\exp\left(-C\frac{(y-z)^2}{t-s}\right),
\]
for $2\alpha+\beta \leq 2$, where  $c$ and $C$ are constants independent of $s,t,z$ and $y$, and $D_s^{\alpha}$ (resp. $D_z^{\alpha}$) denotes the $\alpha$-th partial derivative with respect to $s$ (resp. $z$).

\item  For any $r>0$, $y\in E$, and $t>0$, 
\begin{align}
&\sup_{\substack{z\in B_r^c(y)\\s<t}}q(s,t;z,y)<\infty,\quad \text{and}\\
&\lim_{s\rightarrow 0}\int_{B_r^c(z)}q(0,t-s;x,y)q(t-s,t;y,z)dy=0, \quad \forall x\in E, 
\end{align}
where $B_r(y):=\{z\in E:|y-z|<r\}$.
\end{enumerate}

[Lemma lem:ergopt of arXiv:2505.12187, 'Speeding up quantum Markov processes through lifting'] Let $\mathcal{P}_t = \exp(t \mathcal{L})$ be a QMS with invariant state $\sigma \in \mathcal{D}_+(\mathcal{M})$. Then, we have 
    \begin{align*}
        \lim_{t \to \infty} \mathcal{P}_t (\mathrm{id} - E_{\mathcal{N}}) = 0\,,
    \end{align*}
    with $E_{\mathcal{N}}$ being the conditional expectation to $\mathcal{N}(\mathcal{L})$, and the limit 
    \begin{align} 
        \lim_{t \to \infty} \frac{1}{t} \int_0^t \mathcal{P}_s \,\mathrm{d} s =: E_{\mathcal{F}}
    \end{align}
    exists and defines the conditional expectation $E_{\mathcal{F}}$ onto $\mathcal{F}(\mathcal{L})$ with respect to $\sigma$. 
    Moreover, the following convergence holds:
    \begin{align} 
        \lim_{t \to \infty} \mathcal{P}_t  = E_{\mathcal{F}}\,,
    \end{align}
    if and only if $\mathcal{N}(\mathcal{L})$ coincides with the fixed-point algebra $\mathcal{F}(\mathcal{L})$, i.e., $\mathcal{N}(\mathcal{L}) = \mathcal{F}(\mathcal{L})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma comparisonstep1 of arXiv:2507.10545, 'KPZ equation from a class of nonlinear SPDEs in infinite volume'] \fsp Fix any {\small$\mathrm{L}>0$}. There exists {\small$\gamma_{\mathrm{L},1}>0$} depending on {\small$\mathrm{L}$} such that with high probability, we have 

\begin{align}
\sup_{\t\in[0,1]}\sup_{|\x|\leq \mathrm{L}N}|\mathbf{Z}^{N}_{\t,\x}-\mathbf{Y}^{N,1}_{\t,\x}|\lesssim_{\mathrm{L}} N^{-\gamma_{\mathrm{L},1}},
\end{align}

where, upon recalling {\small$\mathbf{L}^{N,\zeta_{\mathrm{final}},\sim}$} from (equation eq:lzetasim-sde of the paper), we set

\begin{align}
\mathbf{Y}^{N,1}_{\t,\x}&:=\sum_{\y\in\Z}\mathbf{L}^{N,\zeta_{\mathrm{final}},\sim}_{0,\t,\x,\y}\mathbf{S}^{N}_{0,\y}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defination 3 of arXiv:2511.10814, '\Large \bf \boldmath\ \\ Convergence of the extended Kalman filter with small and state-de'] Let $\varphi:[0,\infty)\times \R^n \to \R^n,$  be  a  family  of   functions and $x_1, x_2 \in \R^n $. 

			\begin{enumerate}
				\item 
				$\varphi$  is said to be  \textbf{almost  linear} if  there  exists  a family  of matrix-valued observable processes $F:[0,\infty)\to \R^{n\times n}$  such  that 				
				\begin{equation}
					\vert \varphi(t,x_1)- \varphi(t,x_2) - F(t) (x_1-x_2) \vert  \leq \mu^{\eps} \vert x_1-x_2 \vert,
				\end{equation}
				for some family of  numbers  $\mu=(\mu^{\eps})_{\eps>0}$ converging to zero as $\eps \to 0$. \\ The  process $F$  will be  called an  \textbf{almost  derivative} of $f$.

				\item The  function  $\varphi$  will be  said  to  be \textbf{strongly  injective} if 
				\begin{equation}
					\vert \varphi (t,x_1)- \varphi(t,x_2)  \vert  \geq c \vert x_1-x_2 \vert,
				\end{equation}
				for  some $c>0$.
			\end{enumerate}

The Fourier transform $f\mapsto\hat f$, $\hat f(\xi)=\int f(x)e^{-2\pi i x\cdot\xi}dx$, maps $\mathcal S(\mathbb R^d)$ continuously and bijectively onto itself, with continuous inverse given for every $x$ (pointwise, not just a.e.) by $f(x)=\int_{\mathbb R^d}\hat f(\xi)e^{2\pi i x\cdot\xi}d\xi$. Moreover $\hat{\hat f}(x)=f(-x)$, so the transform has order 4, and $\widehat{\partial^\beta f}=(2\pi i\xi)^\beta\hat f$, $\widehat{x^\alpha f}=(-2\pi i)^{-|\alpha|}\partial^\alpha\hat f$. Also $\int f\bar g=\int\hat f\,\overline{\hat g}$ on $\mathcal S$, which together with density gives the Plancherel theorem, and $\widehat{fg}=\hat f*\hat g$, $\widehat{f*g}=\hat f\hat g$ within $\mathcal S$.
f in the Schwartz space S(R^d)
convention e^{-2 pi i x.xi}

[Proposition prop:siteperc_dom_SIR of arXiv:2607.29409, 'The Zombie Infection Model'] Let $G=(V,E)$ be a graph of bounded degree. Then, for any $\lambda > 0$ and $\Delta\Subset V$, there
		is a coupling $\widehat{\BP}$ of ${\mathcal{C}}^{\SIR}_{\Delta, \lambda}$,
		$\widetilde{G}_{u}\sim G_{q_u}^{\siteperc}$ and
		$\widetilde{G}_{l}\sim G_{q_l}^{\siteperc}$ such that
		\begin{equation}
			\widehat{\BP}\!\left( {\mathcal{C}}^{\siteperc}_{\Delta}(\widetilde{G}_{l}) \subseteq {\mathcal{C}}
			^{\SIR}_{\Delta, \lambda}\subseteq {\mathcal{C}}^{\siteperc}_{\Delta}( \widetilde{G}_{u}
			)\cup \partial_{v}^{o}\big({\mathcal{C}}^{\siteperc}_{\Delta}(\widetilde{G}_{u})\big) \right)
			= 1,
		\end{equation}
		where
		$q_{l} = \int_{0}^{\infty} (1-e^{-\lambda y})^{\mathrm{deg}(G)} e^{-y}\,dy \text{ and }q_{u}
    		= \frac{\lambda \mathrm{deg}(G)}{\lambda \mathrm{deg}(G) + 1}$.

