[Lemma 15 of arXiv:2608.30178, '2608.30178'] {
Assume that $0 < q_1, q_2 \le 1$. Then the model \eqref{eq:noimm-system} is source-conservative. Moreover,
\eqref{eq:concave-energy} holds, and
\(\bigl(H(X_t,Y_t)\bigr)_{t\ge0}\) is a nonnegative supermartingale.
}

[Definition def:jordan2 of arXiv:2606.24465, 'History estimation in random recursive trees:\\Pointwise approach via iterated Jordan cent'] For a finite tree $\mathrm{t}=(V_n,E_n)$, we define the \emph{Jordan-$2$ centrality} $\phi_{\mathrm{t}}^{{\scriptscriptstyle{({2}})}} : V_n \to \mathbb{R}_{\geq 0}$ by
\begin{equation}
    \phi_\mathrm{t}^{{\scriptscriptstyle{({2}})}}(v):=  \phi_\mathrm{t}(v) \cdot \big(\phi_\mathrm{t}(v^{{\scriptscriptstyle{({1}})}}) \vee  \phi_\mathrm{t}(v) \big).
\end{equation}
If $v^{{\scriptscriptstyle{({1}})}}$ is not uniquely defined, we let $v^{{\scriptscriptstyle{({1}})}}$ be such that the resulting choice minimizes $\phi_\mathrm{t}^{{\scriptscriptstyle{({2}})}}$.  The Jordan-2 ordering $\widehat\sigma_2$ is given by ordering vertices decreasingly by $\phi_\mathrm{t}^{{\scriptscriptstyle{({2}})}}$, and breaking ties uniformly at random.

[Theorem thm:simple-azuma-gtp of arXiv:2512.21026, 'Minimax Duality in Game-Theoretic Probability\thanks{Work in progress: mistakes are likely'] Let $(\mathcal{Y},\hat\mathcal{Z},T)$ be the simple repeated gamble space with $\mathcal{Y} = [-1,1]$, $\hat\mathcal{Z} = \{y\mapsto \beta y \mid \beta \geq 0\}$, and some $T\in\mathbb{N}$.
  Then for all $\epsilon > 0$ we have
  \begin{align}

    \overline{\textsf{\textbf{P}}}\left[\sum_{t=1}^T Y_t \geq \epsilon\right] \leq \exp \left(- {\epsilon ^{2} \over 2T}\right)~.
  \end{align}

[Theorem Thm_stationary of arXiv:2606.28067, 'Ergodic approximation for the invariant distribution: An abstract framework for law-depend'] Suppose that $\mathrm{\mathbf{A}}_p(b,\alpha,\varepsilon)$ is
		satisfied with $\overline{b}:=b-\alpha >0$ {and that $\sup_{k>r}\|\Theta^\pi_{t_r,t_k}(\mu) \|_p<\infty$ for any $\mu\in\mathcal{P}_p({\mathbb R}^d)$.}
		Then the following statements
		hold.

		\medskip

		\textbf{A. } There exists a $(\psi ,p)-$stationary measure $\mu _{\ast }$
		for $\{X_{n}\}_{n}.$

		\smallskip

		\textbf{B. } Furthermore, for every $\mu$, there exists $C(\mu)\in {\mathbb R}_+$
		\begin{equation}
			W_{p}^{p}(\mathcal{L}(X_{n}),\mu _{\ast
			})=W_{p}^{p}(\Theta^\pi_{t_{0},t_{n}}(\mu ),\mu _{\ast })\leq C(\mu)(e^{-
				\overline{b} t_{n}}+c_{\ast }\gamma _{n}^{\varepsilon
			})+\limsup_{m\rightarrow \infty }\delta _{0,n,m},  
		\end{equation}
		where $\mu=\mathcal{L}(X_0)$. { Besides, if there exists $C\in \mathbb{R}_+$ such that for all $\mu$, $\sup_{0\le r \le k} \left\Vert \Theta_{t_{r},t_{k}}^{\pi
			}(\mu)\right\Vert _{p}^p\leq C(1+\left\Vert \mu\right\Vert
			_{p}^p) $ (this holds when the assumption~(equation New0bis of the paper) holds), we can take $C(\mu)\le \tilde{C}(1+\|\mu\|_p^p)$ for some constant $\tilde{C}\in {\mathbb R}_+$. } (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:hypocoercivesemi of arXiv:2505.12187, 'Speeding up quantum Markov processes through lifting'] We say that $\{P_t\}_{t \geq 0}$ \emph{converges to equilibrium} if for each $x \in \mathcal{H}$, there exists a decay function $r: \mathbb{R}_+ \to \mathbb{R}_+$ with $\lim_{t \to \infty} r(t) = 0$ such that
\begin{align} 
    \|P_t x - P_\infty x\|_{\mathcal{H}} \leq r(t) \|x - P_\infty x\|_{\mathcal{H}}.
\end{align}
When $r(t) = Ce^{- \nu t}$ for some $C >  1, \nu > 0$, we say the semigroup is \emph{hypocoercive}. In the case of $r(t) = e^{-\nu t}$ (i.e., $C = 1$), it is called \emph{coercive}.

[Definition 1 (Quasi-classical solution) of arXiv:2604.17973, 'Schauder estimates and classical solutions of the Dirichlet problem for stochastic parabol'] A predictable random field $u:\bar Q_T\times\Omega\to\R$ is called a quasi-classical solution of \eqref{eq:main}--\eqref{eq:boundary-initial} if
\begin{enumerate}[label=\rm(\roman*)]
\item for each $t\in(0,T]$, the map $x\mapsto u(x,t)$ is twice strongly differentiable from $G$ into $L_\omega^\gamma$, and $u(\cdot,t)$ together with its spatial derivatives up to order two extends continuously to $\bar G$ as an $L_\omega^\gamma$-valued function;
\item for each $x\in G$, the process $u(x,\cdot)$ is stochastically continuous and satisfies
\[
\begin{aligned}
u(x,t)-u(x,0) & =\int_0^t \bigl(a^{ij}D_{ij}u+b^iD_i u+cu+f\bigr)(x,s)\md s \\
& \quad +\int_0^t \bigl(\sigma^{ik}D_i u+\nu^k u+g^k\bigr)(x,s)\md w_s^k
\end{aligned}
\]
almost surely for all $t\in[0,T]$;
\item $u=0$ on $\Gamma_T$ and $u(0,\cdot)=0$ in $G$ almost surely.
\end{enumerate}

[Lemma 82 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] The following statements are true:
\begin{enumerate}
\item For every $y \in D(A)$ the mapping
\begin{align*}
\mathbb{R}_+ \rightarrow W, \quad t \mapsto S_t y
\end{align*}
belongs to class $C^1(\mathbb{R}_+;W)$.

\item For all $t \geq 0$ and $y \in D(A)$ we have $S_t y \in D(A)$ and
\begin{align*}
\frac{d}{dt} S_t y = A S_t y = S_t A y.
\end{align*}

\item For all $t \geq 0$ and $y \in W$ we have $\int_0^t S_s y \, ds \in D(A)$ and
\begin{align*}
A \bigg( \int_0^t S_s y \, ds \bigg) = S_t y - y.
\end{align*}

\item For all $t \geq 0$ and $y \in D(A)$ we have
\begin{align*}
\int_0^t S_s A y \, ds = S_t y - y.
\end{align*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 238 (The Cauchy horizon) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] We define the \textbf{Cauchy horizon} to be the set:
\begin{align} 
	\CH \eqdef  \ingoingcharacteristicsurfacetwoarg{0}{[\moreinterestingu_1,\moreinterestingu_2]} \cap \{ \newuL \upmu \ge 0\}.
\end{align}

[Lemma 12 of arXiv:2609.02790, 'Full-Model Optimality for Tunable Linear Generative Priors in Compressed Sensing'] Under Lemma \ref{Under_E(k)} assumption, let  \(M_k = A_kG_k \) be a sequence of matrices evolving as \( M_k = [M_{k-1}, m_k] \), where \( m_k = \sigma_ka_k \) is an additional column vector. The projection matrices associated with these matrices are given by:
\[
P_{G_k^T A_k^T} =P_{M_k^T}= M_k^T (M_k M_k^T)^{-1} M_k, \quad
P_{G_{k-1}^T A_{k-1}^T}=P_{M_{k-1}^T} = M_{k-1}^T (M_{k-1} M_{k-1}^T)^{-1} M_{k-1}.
\]
Then,
\begin{align}
 \sum_{i=1}^{k-1}\sigma_i^2\Big(P_{M_k^T}-P_{M_{k-1}^T}\Big)_{ii} 
  \geq -\sum_{i=1}^{k-1}\sigma_i^2\bigg(M_{k-1}^T\bigg(\Big(M_{k-1}M_{k-1}^T\Big)^{-1} m_km_k^T \Big(M_{k-1}M_{k-1}^T\Big)^{-1}\bigg)M_{k-1}\bigg)_{ii}.
\end{align}

