[Theorem phi-conv of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] If the density $f_{12}$ is $TP_{2}$ (Totally Positive of
order 2), then the following hold for $i=1,2$:

\begin{enumerate}
\item The sequence of functions $\Phi _{n}^{i}$ converges pointwise to $1$
on $[0,1]$, that is, 
\begin{equation}
\lim_{n\rightarrow +\infty }\Phi _{n}^{i}(x)=\left\{ 
\begin{array}{c}
1,\text{ }x>0 \\ 
0,\text{ }x=0
\end{array}
\right.  
\end{equation}

\item Furthermore, for any $\delta $ $\in (0,1)$, the convergence is uniform
on the interval $[\delta ,1].$
\end{enumerate}

If the density $f_{12}$ is $SRR_{2}$ under the additional assumptions of
log-concavity and non-degeneracy, then the following hold for $i=1,2$:

\begin{enumerate}
\item For any sequence of indices $\{n_{k}\}_{k\geq 0}$ with $
n_{k}\rightarrow \infty $ the sequence of functions $\Phi _{n_{k}}^{i}$
converges subsequentially to $\phi _{i}$ on $[0,1]$, that is, 
\begin{equation}
\lim_{k\rightarrow +\infty }\Phi _{n_{k}}^{i}(x)=\left\{ 
\begin{array}{c}
\phi _{i},\text{ }x\in (0,1) \\ 
0,\text{ }x=0 \\ 
1,\text{ }x=1
\end{array}
\right. ,  
\end{equation}

where $\phi _{i}=c_{i}$ is the limit of the crossings of $L_{i}^{n}(x)$ with
the diagonal.

\item Furthermore, for every fixed $(\delta ,\eta )$ $\subset $ $(0,1)$, the
convergence to $\phi _{i}$ is uniform on the interval $[\delta ,\eta ]$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 45 (Adapted from Lemma 4.1 of \cite{ks}) of arXiv:2511.07350, 'Decoupling of clusters in independent sets in a percolated hypercube'] For every $p \in (0,1)$ and every fixed $k \geq 1$,
    \begin{equation}
        \sum_{j > k}
        \sum_{\fp \in \polymers_j} \E[\phi_\fp]
        \leq \poly(d) \cdot \Fr{(2-p)^{k+1}}{2^k}^d
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: GUBinary of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] For all $\tau_0,\ldots, \tau_k\in{\mathcal T}$:
		\begin{equation}
			(\tau_k\cdots \tau_1)\curvearrowright\tau_0= \frac1{k!} \sum_{p\in\Sigma_k} \sum_{\rho\in{\mathcal T}_b^{p(I_k)}} C(\rho)
			\, (-1)^{k-m_R(\rho)} \, G(\rho)\,,
		\end{equation}
		where $G$ is the mapping from planar binary trees to rooted trees of Definition (Def: link binary to rooted of the paper), $m_R(\rho)\in\mathbb{N}$ denotes the distance of the rightmost leaf from the root and $C(\rho)$ is the combinatorial factor defined in (equation Eq: C of the paper).

[Thm 21 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Let $D,f$ be as in \Cref{def:harpoon}. There exists $\phi\in\Adm(D;f)$ such that, for any sequence $(D_N)_{N\ge1}$ of tilable domains such that $D_N\stackrel{N\to\infty}\rightharpoonup (D,f)$ and  for every $\varepsilon>0$, it holds
    \begin{eqnarray}
      \lim_{N\to\infty}\pi_{D_N}(\exists z\in D_N:|H_\eta(z)-\phi(z)|>\varepsilon)=0
    \end{eqnarray}
    where $\pi_{D_N}$ is the uniform measure on $\Omega_{D_N}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 41 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $(Y,Y') \in \scrd_X^{2\alpha}([0,T],W)$ and $f \in C_b^{2\alpha,2}([0,T] \times W, \bar{W})$ be arbitrary. Then we have
\begin{align}
(f(Y),f(Y)') \in \scrd_X^{2\alpha}([0,T],\bar{W}),
\end{align}
where the paths $f(Y)$ and $f(Y)'$ are given by \eqref{comp-f-def-1} and \eqref{comp-f-def-2}. Furthermore, we have
\begin{align}
\| f(Y) \|_{\alpha} &\leq \| f \|_{C_b^{2\alpha,2}} ( \| Y \|_{\alpha} + T^{\alpha} ),
\\  \| f(Y)' \|_{\alpha} &\leq \| f \|_{C_b^{2\alpha,2}} \big( \| Y' \|_{\alpha} + \| Y \|_{\alpha} \| Y' \|_{\infty} + T^{\alpha} \| Y' \|_{\infty} \big),
\\  \| R^{f(Y)} \|_{2\alpha} &\leq \| f \|_{C_b^{2\alpha,2}} \bigg( 1 + \frac{1}{2} \| Y \|_{\alpha}^2 + \| R^Y \|_{2\alpha} \bigg),
\end{align}
and we have the estimates
\begin{align}
| f(Y),f(Y)' |_{X,2\alpha} &\leq C \big( 1 + | Y,Y' |_{X,2\alpha}^2 \big),
\\  \interleave f(Y),f(Y)' \interleave_{X,2\alpha} &\leq C \big( 1 + \interleave Y,Y' \interleave_{X,2\alpha}^2 \big),
\end{align}
where the constant $C > 0$ depends on $\alpha$, $T$, $X$ and $\| f \|_{C_b^{2\alpha,2}}$. Moreover, for $T \leq 1$ the constant $C$ does not depend on $T$.

