body:
[Definition def:alpha of arXiv:2605.17082, 'Spectral Purification in Reversible Markov Chains: Hidden Parameters, Observable Equivalen'] The \emph{slow-mode energy fraction} at step $k$ is
\begin{equation}
\alpha_2(k) := p_2(k) = \frac{n_2(k)}{E_k} = \frac{|c_2|^2 \lambda_2^{2k}}{\sum_{i=2}^n |c_i|^2 \lambda_i^{2k}} \in (0,1).
\end{equation}
The \emph{residual energy} in the fast modes ($i \ge 3$) is
\begin{equation}
R_k := \sum_{i=3}^n n_i(k) = E_k - n_2(k) = (1 - \alpha_2(k)) E_k.
\end{equation}

[Definition 158 of arXiv:2601.16377, '2601.16377'] Let $h \in [H]$ and $k \in \llbracket k^-(h),k^+(h) \rrbracket$. We introduce
\begin{equation*}
\begin{split}
& \mathfrak{a}_k = \hat{a}_k(\textnormal{\textsf{\textbf{Gau\ss{}}}}_{\amsmathbb{Z}}),\qquad \mathfrak{a}_k' = \mathfrak{a}_k  + \frac{\theta_{h,h} - \frac{1}{2}}{\N} \\
& \mathfrak{b}_k = \hat{b}_k(\textnormal{\textsf{\textbf{Gau\ss{}}}}_{\amsmathbb{Z}}),\qquad \mathfrak{b}_k' = \mathfrak{b}_k - \frac{\theta_{h,h} - \frac{1}{2}}{\N}
\end{split}
\end{equation*}
If $f$ is a continuous function defined in a neighborhood of the $h$-th segment $[\hat{a}_h,\hat{b}_h]$, we set
\begin{equation}

\begin{split}
\mathsf{Shift}_h[f] & = \sum_{l = 1}^{K} (\textnormal{\textsf{Gau\ss{}}}_{\amsmathbb{Z},l} - Q_l^{\boldsymbol{\mu}}) \int_{\hat{a}_h'}^{\hat{b}'_h} f(x) \big(\partial_{\hat{p}_l} \mu_h^{\hat{\boldsymbol{p}}}(x)\big)\big|_{\hat{\boldsymbol{p}} = \frac{\boldsymbol{Q}^{\boldsymbol{\mu}}}{\N}}\,\dd x \\
& \quad + \frac{\theta_{h,h} - 1}{2\theta_{h,h}}\bigg[\mathbbm{1}_{\amsmathbb{S}_h}(\hat{a}_h')\big(f(\mathfrak{a}_{k^-(h)}') - f(\hat{a}_{h}')\big)  + \sum_{k = k^-(h)}^{k^+(h) - 1} \mathbbm{1}_{\amsmathbb{S}_h}(\beta_k) \big(f(\mathfrak{b}_k') + f(\mathfrak{a}'_{k + 1})\big)  \\
& \quad\qquad \qquad\qquad + \mathbbm{1}_{\amsmathbb{S}_h}(\hat{b}'_h) \big(f(\mathfrak{b}_{k^+(h)}') - f(\hat{b}'_h)\big)\bigg]
\end{split}
\end{equation}
As in \eqref{eq_x258}, the indicator functions indicate respectively that $[\hat{a}_h',\alpha_{k^+(h)}]$, $[\beta_{k},\alpha_{k + 1}]$ and $[\beta_{k^+(h)},\hat{b}_h']$ are saturations.  The equilibrium measure $\boldsymbol{\mu}^{\hat{\boldsymbol{p}}}$ is the one already encountered in Section~\ref{Sec:gausdssat}.

[Lemma two point commutation relation in angular of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] In the angular coordinate, suppose two radial SLE hulls start from $x,y \in \mathbb{R}$ with marked points $z_1,z_2,\ldots,z_n \in \mathbb{R}$ and marked interior point $u \in \mathbb{D}$. If $u=0$ is a marked point, we simply omit it since $u=0$ is fixed by the Loewner flow. Let $\mathcal{M}_1$ and $\mathcal{M}_2$ 
$$
\begin{gathered}
\mathcal{M}_1=\frac{\kappa}{2} \partial_{x x}+b(x, y \ldots) \partial_x+\cot(\frac{y-x}{2}) \partial_y+\sum_{i=1}^n \cot(\frac{z_i-x}{2}) \partial_i+ \cot\left(\frac{v-x}{2}\right) \partial_v+\cot\left(\frac{\overline{v}-x }{2}\right)\overline{\partial}_{v}\\
\mathcal{M}_2=\frac{\kappa}{2} \partial_{yy}+\tilde{b}(x, y, \ldots) \partial_y+\cot(\frac{x-y}{2}) \partial_x+\sum_{i=1}^n \cot(\frac{z_i-y}{2}) \partial_i+\cot\left(\frac{v-y}{2}\right) \partial_v+\cot\left(\frac{\overline{v}-y}{2}\right)\overline{\partial}_{v}
\end{gathered}
$$
be the infinitesimal diffusion generators of two SLE hulls,
where $\partial_i=\partial_{z_i}$.

If two SLEs locally commute, then the associated infinitesimal generators satisfy:
\begin{equation}
[\mathcal{M}_1, \mathcal{M}_2]=\frac{1}{\sin^2(\frac{y-x}{2})}(\mathcal{M}_2-\mathcal{M}_1)
\end{equation}
Moreover, there exists a smooth positive function $\mathcal{\psi}(x,y,\boldsymbol{z},u)$ such that:
$$
b=\kappa \frac{\partial_x \psi}{\psi}, \tilde{b}=\kappa \frac{\partial_y \psi}{\psi}
$$

and $\psi$ satisfies the null vector equations:
\begin{equation}
\left\{\begin{array}{l}
\frac{\kappa}{2} \partial_{x x} \psi+\sum_i \cot(\frac{z_i-x}{2})\partial_i \psi+\cot(\frac{y-x}{2})\partial_y \psi+\cot\left(\frac{v-x}{2}\right) \partial_v\psi+\cot\left(\frac{\overline{v}-x }{2}\right)\overline{\partial}_{v}\psi \\
+\left( \left(1-\frac{6}{\kappa}\right) \frac{1}{4\sin^2(\frac{y-x}{2})}+h_1(x, z)\right) \psi=0 \\
\frac{\kappa}{2} \partial_{y y} \psi+\sum_i \cot(\frac{z_i-y}{2}) \partial_i \psi+\cot(\frac{x-y}{2}) \partial_x \psi+ \cot\left(\frac{v-y}{2}\right) \partial_v\psi+\cot\left(\frac{\overline{v}-y }{2}\right)\overline{\partial}_{v}\psi
\\
+\left(\left(1-\frac{6}{\kappa}\right) \frac{1}{4\sin^2(\frac{x-y}{2})}+h_2(y, z)\right) \psi=0
\end{array}\right.
\end{equation}

