[Cor Kor: Diag.matrix, char. Poly. superkrit. Reg. of arXiv:2509.15790, 'Covariance matrices of volume power functionals of random simplicial complexes -- an asymp'] Assuming the situation of Theorem (Thm: EW.e, ER.e superkrit. Reg. of the paper) set  $D=\text{diag}(\lambda_1,\dots,\lambda_1,\lambda_2)\in \mathbb{R}^{n \times n}$
and $S \in \mathbb{R}^{n \times n}$ with column vectors $v_1, \dots,v_n$.
Under the given conditions $\Sigma_n$ is similar to $D$ and $D=S^{-1} \Sigma_n S$, where $S^{-1} = (\tilde{s}_{ij})\in \mathbb{R}^{n \times n}$ with entries
\begin{align*} 
\tilde{s}_{ij} = \left\{
\begin{array}{ll}
\frac{\prod_{k=1}^n a_k^2}{a_{j}a_n b}&\text{ for }\,i=n,\\
-\frac{\sum_{k \in [n] \setminus \{i\}} a_{i}^2\prod_{l\in [n] \setminus \{k, \, i\}} a_{l}^2}{b}&\text{ for}\,j=i+1,\\
\frac{\prod_{k=1}^n a_k^2}{a_{i+1}a_j b}& \text{ else.}\\
\end{array}
\right.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 56 of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] Assume \eqref{H1}--\eqref{H2}. Then:
\begin{enumerate}[label=(\arabic*), ref=\arabic*]
    \item Uniformly for all $1\le i\le m\le M_0$, $1\le r\le K_\theta$, and vertices $v^j_l$ with $h_r< j\le h_{r-1}$ and $1\le l\le q_n(j)-m$, 
    \begin{align}
        \p_n\big(\tau_i(v^j_l)<\infty\,\big|\,\widetilde{B}_{r}\big)
        =\frac{1}{m}\left\{1- \prod_{h=0}^{j-h_r-1}\Bigg[1-\frac{m\sigma^2_n(j-h)}{q_n(j-h)}\big(1+o_n(1)\big)\Bigg]\right\}.

    \end{align}
    \item Uniformly for all $1\le i\le m\le M_0$ and vertices $v^j_l,\,v^{j'}_{l'}$ with $h_r< j\le j' \le h_{r-1}$, $1\le l\le q_n(j)-m$, and $1\le l'\le q_n(j')-m$,  
    \begin{equation} 
    \begin{aligned} 
        &\p_n\big( \tau_i(v^j_l) < \infty \,\big|\, \tau_i(v^{j'}_{l'})<\infty,\,\widetilde{B}_{r} \big) \\
        \le \,& \frac{1}{m}\left\{1-\big(1+o_n(1)\big)\prod_{h=0}^{j-h_r-1}\Bigg[1-\frac{(m+1)\sigma^2_n(j-h)}{q_n(j-h)}\big(1+o_n(1)\big)\Bigg]\right\}. 
    \end{aligned} 
    \end{equation}
\end{enumerate}

