[Definition def:walk of arXiv:2411.12149, 'Airy limit for $\beta$-additions through Dunkl operators'] Fix $N,l\in \mathbb{Z}_{\ge 1}$ and $M_{1},\ldots,M_{l}\in \mathbb{Z}_{\ge 1}$, $M_1+\ldots+M_l=M$. For each sequence of monomials $\{P(s)\}_{s=0}^{M}$, coming form the action $\frac{1}{\mu_{+}(N)^{M}}\left(\frac{\mathcal{D}_{i_{l}}}{N}\right)^{M_{l}}\cdots \left(\frac{\mathcal{D}_{i_{1}}}{N}\right)^{M_{1}}G_{N}(x_1,\ldots,x_N;\beta)|_{\vec{x}=0}$, let $E(t):[0,M]\rightarrow \mathbb{Z}_{\ge 0}$ be a C\'adl\'ag function defined by 
        \begin{equation}
        E(t)=\operatorname{Deg}(P(\lfloor t\rfloor)).
        \end{equation} 
        We refer to $E(t)$ as a walk.

[Theorem thm:sineb_series of arXiv:2509.15446, 'On the pair correlation function of the $\Sineb$ process'] Define $\mathbf{s}_k \in {\mathbb C}^n$ recursively as
\begin{align}
    \mathbf{s}_0&=-\frac{n+1}{2}\mathbf{A}_n^{-1}\mathbf{e}_n, \qquad \mathbf{s}_k=i \left(k \mathbf{I}-\tfrac{2}{n} \mathbf{A}_n\right)^{-1} \mathbf{B}_n \mathbf{s}_{k-1}, \qquad k\ge 1.
\end{align}
Then 
\begin{align}
    \rho_{2n}^{(2)}(0,\lambda)=\frac{1}{2\pi^2} \sum_{j=1}^\infty \mathbf{v}_n^{T} \cdot \mathbf{s}_{2j}\,  \lambda^{2j}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:coercivity_est of arXiv:2605.15742, 'Turbulent stretching of FENE dumbbell polymer model via special stochastic scaling and sin'] Let $\kappa/(2+ \kappa_T \beta)> 1$, then there exists $\eta >0$ such that if $k_T\beta \le \eta$, there exists positive constants $C$, $\theta$ such that for every $f\in V_0$ it holds 
             \begin{align}
    \frac{1}{\beta}\int_{\mathbb{T}^2 \times D} \mathbf{M}_0 \left| \nabla_r \left(\frac{f}{\mathbf{M}_0}\right)\right|_{I+ \frac{\beta}{2}A}^2 drdx - \frac{1}{2}\int_{\mathbb{T}^2 \times D} A \nabla_r f \cdot \frac{\nabla_r f}{\mathbf{M}_0}drdx \ge -C \|f\|^2_{H_0} + \theta [f]^2_{V_0}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma L:ML of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] The Mittag--Leffler function $E_{a,b}(\cdot)$ defined in~(equation E:ML of the paper)
  satisfies the following properties:

  \begin{enumerate}[\rm (i)]

    \item For all $a>0$ and $b\in\mathbb{R}$, $E_{a,b}(z)$ is an analytic function on
          $\mathbb{C}$. Moreover, if $b>0$, then $E_{a,b} (0) =
            \Gamma(b)^{-1} > 0$.

    \item Suppose that $a \in (0,2]$ and $b \in \mathbb{R}$. Then, by restricting $x\in \mathbb{R}$, $E_{a, b} (- x)$
          admits the following asymptotic expansions as $x \to \infty$:
          \begin{subequations}
            \begin{empheq}[left={E_{a, b}(-x) = \empheqlbrace}]{align}
              & \frac{1}{\Gamma(b - a) x} + O\left(x^{-2}\right),                                                                     &  & a < 2, a \ne b,        \\
              & \frac{1}{\Gamma(-a) x^2} + O\left(x^{-3}\right),                                                                      &  & 1 \ne a = b \in (0,2), \\
              & \exp\left( - x \right),                                                                                               &  & a = b =  1,            \\
              & \frac{\cos \left(\sqrt{x} + (1 - b) \pi /2\right)}{x^{(b - 1)/2}} + \frac{1}{\Gamma(b - 2) x} + O\left(x^{-2}\right), &  & a = 2\ne b,            \\
              & \frac{\sin \left(\sqrt{x}\right)}{\sqrt{x}},                                                                          &  & a = b =  2.           
            \end{empheq}
          \end{subequations}

    \item For some finite constant $C>0$, the following uniform upper bounds
          hold for all $x\ge 0$:
          \begin{subequations} 
            \begin{empheq}[left={\left|E_{a, b}(-x)\right| \le \empheqlbrace}]{align}
              & \dfrac{C}{1 + x^{(b-1)/2}} &  & a = 2, \; b \in [2,3),     \\
              & \dfrac{C}{1+x},            &  & a \in (0,2), \: b \in \mathbb{R}. 
            \end{empheq}
          \end{subequations}

    \item For any $a>0$, $b$, $\lambda \in \mathbb{R}$, and $m=1,2,3,\cdots$, it holds
          that
          \begin{align}
            \frac{\ensuremath{\mathrm{d} }^m}{\ensuremath{\mathrm{d} } x^m} \left(x^{b - 1} E_{a,b} \left(\lambda x^a\right)\right)
            = x^{b-1-m} E_{a, b-m}(\lambda x^a).
          \end{align}

  \end{enumerate}

[Lemma 11 of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] Assume the same setup as in Lemma~\ref{lem::earlierconstruction_marginal_conditional}.
The law of $\bs{\gamma}=(\gamma^1,\ldots,\gamma^n)$ under $\widehat{\mathsf{P}}$ enjoys the domain Markov property: for $t_1,\ldots,t_n<r$, given $(\gamma_{[0,t_1]}^1,\ldots,\gamma_{[0,t_n]}^n)$, the law of $(\gamma_{[t_1,r]}^1,\ldots,\gamma_{[t_n,r]}^n)$ is 
\begin{align*}
	\widehat{\mathsf{P}}(\A_r\setminus \cup_{j=1}^n \gamma_{[0,t_j]}^j ;\gamma_{t_1}^1,\ldots,\gamma_{t_n}^n,\ee^{\ii \bs{\beta}-r}).
\end{align*}

