 \sum_{(\lambda,b)\in I_{m,i}}
 a_{m,i,\lambda,b}\,
 \sidedistat{m}{i}^\lambda
 (\ln \sidedistat{m}{i})^b
 +
 \mathcal R_{m,i}(\sidedistat{m}{i}),
 \qquad
 \mathcal R_{m,i}
 \in
 \mathcal C_{\sigma,B}^{q,\gamma}(0,\ell_{\mathrm{vtx}}),

\end{align}
for $i=1,2$, where an exponent occurring on one ray only has coefficient zero on the other.

\item \emph{Global admissibility and the data size.} Let $H^{\rm sing}$ and $f^{\rm cut}$ be as in (equation eq:finite-part-cutoff-realization of the paper)--(equation eq:finite-part-commutator-source of the paper) and $h_{\rm rem}$ as in (equation eq:finite-part-residual-trace of the paper), with $\Tr_{\rm ray}H^{\rm sing}$ the explicit restriction to the open sides. The hypothesis is that the far-field quantity
\begin{align}
