body:
[Proposition 9 of arXiv:2609.03339, 'Exterior Serrin Rigidity for the Homogeneous \texorpdfstring{$k$}{k}-Hessian Equation\\'] There exists $T_\ast>0$ such that
		\begin{equation}
			\Psi(x)=\frac{e^{T_\ast(\mu(x)-1)}-1}{T_\ast}
		\end{equation}
		is smooth in $E$, vanishes on $\partial\Omega$, is positive in $E$,
		and satisfies $D^2\Psi\in\Gamma_k$ throughout $E$.

[Lemma lem:postbin-compensator-envelope-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] There exists a nonnegative random variable \(E^{\mathrm{post}}_n\), not depending on \(\xi\), such that, for every finite truncation \(L\),
\[
\sup_{2^n\le\lvert\xi\rvert\le2^{n+1}}
\mathfrak C^{\mathrm{post}}_{\xi,n,L}
\le
E^{\mathrm{post}}_n,
\]
and, for some \(c>0\),
\begin{equation}
\mathbb{E}[E^{\mathrm{post}}_n]
\le
C2^{-sn/2}2^{-cn}.
\end{equation}

[Theorem 148 of arXiv:2601.16377, '2601.16377'] Consider a family of discrete ensembles with $H\geq 1$ segments, parameterized by $\boldsymbol{t} = (\hat{a}_h,\hat{b}_h,\hat{n}_h)_{h = 1}^{H}$ in some open set of $\amsmathbb{R}^{3H}$, where for each $h \in [H]$, $[\hat{a}_h,\hat{b}_h]$ and $\hat{n}_h$ represent the $h$-th segment and its segment filling fraction. We suppose that the tuples of integers $(\iota_h^{\pm})_{h = 1}^{H}$ and complex domains $(\amsmathbb{M}_h)_{h = 1}^{H}$ independent of $\boldsymbol{t}$, while for any $h \in [H]$ the regular part of the potential $U_h(z)$ for $z \in \amsmathbb{M}_h$ and the reals $(\rho_{h,j}^{\pm})_{j = 1}^{\iota_h^{\pm}}$ are twice-continuously differentiable with respect to $\boldsymbol{t}$ --- with partial derivatives of $U_h(z)$ derivatives up to order $2$ which are holomorphic functions of $z \in \amsmathbb{M}_h$. Assume that the discrete ensemble for $\boldsymbol{t}^0$ satisfies Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic}, \ref{Assumptions_offcrit}, Assumptions~\ref{Assumptions_analyticity} and has one band per segment.

 Then, there exists a constant $C > 0$ depending only on the constants in the assumptions, such that for any $\varepsilon > 0$ and any $\boldsymbol{t}$ in a $\frac{1}{C}$-neighborhood of $\boldsymbol{t}^0$ and satisfying the integrality constraints \eqref{eq_segment_ff_relation}, for $\N$ large enough in a way that depends only on $\varepsilon$ and $C$ we have
  \begin{equation}
  \Bigg|\log\Z_\N - \bigg[\I[\boldsymbol{\mu}]\N^2 + \bigg( \sum_{h = 1}^{H} \theta_{h,h}\hat{n}_h\bigg) \N\log \N + \mathbbm{Rest}_1\N\bigg]\Bigg| \leq \varepsilon.
 \end{equation}
Besides, the absolute values of $\mathbbm{Rest}_1$ and its partial derivatives with respect to $\boldsymbol{t}$ up to order $2$ are bounded by $C$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:b of arXiv:2412.05503, 'Critical scaling profile for trees and connected subgraphs \\ on the complete graph'] Let $\gamma \ge 0$, $\kappa > 0$, and $\lambda \in \mathbb{R}$.
There is a constant $C_{\kappa, \lambda}>0$ such that
\begin{align} 
\sum_{n=\lceil b \sqrt V \rceil}^{V}
	\frac{ 1 }{n^\gamma}
	e^{- \kappa n^2/V} e^{\lambda n/\sqrt{V}}
\le C_{\kappa,\lambda} b^{-\gamma} V^{ (1 - \gamma) /2} .
\end{align}
for all $V$ and for all $b$ sufficiently large (depending on $\kappa,\lambda$).

