\\[1mm]
&=
\int_0^\alpha
\frac{
\left[
\gamma W^{(\gamma)}(r)
-
\bigl(Z^{(\gamma)}(r)-1\bigr)
\dfrac{W^{(\gamma)\prime}(r)}
{W^{(\gamma)}(r)}
