[Proposition 13 of arXiv:2605.20115, 'Moment bounds on correctors for the degenerate random conductance model'] Suppose that $u:\Z^d\to \R$ and $f:\Z^d\to \R^d$ are related on $\Z^d$ via
\begin{equation}
-\nabla^*\cdot A\nabla u=\nabla^*\cdot f.
\end{equation}
There exists $\beta>1$ depending only on $\Lambda$ such that for any $p\in[1,\beta]$ and any ball $B$, we have almost surely
\begin{equation}
\fint_{x\in B}\Big(\fint_{B_{\di}(x)}A\nabla u\cdot\nabla u\Big)^{p}\,\lesssim \,\fint_{x\in 2B}\Big(\fint_{B_{\di}(x)}A^{-1} f\cdot f\Big)^{p}+\Big(\fint_{x\in 2B}\fint_{B_{\di}(x)}A\nabla u\cdot\nabla u \Big)^{p}.
\end{equation}
Furthermore, the following elliptic regularity estimates hold:
\begin{enumerate}
\item
(Global quenched Meyers' estimates) For $p\in[1,\beta]$,
\begin{equation}
\int_{x\in \ZZ^d}\Big(\fint_{B_{\di}(x)}A\nabla u\cdot\nabla u\Big)^{p}\,\lesssim  \,\int_{x\in \ZZ^d}\Big(\fint_{B_{\di}(x)}A^{-1} f\cdot f\Big)^{p}.
\end{equation}
\item
(Large-scale hole-filling estimates) For $\rd(x)\le r\le R$, if $f\equiv0$ in $B_R(x)$, then 
\begin{equation}
\int_{ B_r (x) }A\nabla u\cdot \nabla u\,\lesssim \, \Big(\frac rR\Big)^{\frac d{\beta'}}\int_{B_{R} (x) } A\nabla u\cdot \nabla u.
\end{equation}
Here we recall that $\beta':=\frac\beta{\beta-1}$ is the H\"older conjugate of $\beta$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

