body:
[Lemma lem:h-basic-chernoff of arXiv:2602.21315, 'The Instability of all Backoff Protocols\thanks{For the purpose of Open Access, the author'] Fix a send sequence $\overline{p}$ with $p_0=1$. Let $\alpha$ be a real number with $0 < \alpha \le 1$, let $j\ge 1$ be an integer, and suppose $j$ is sufficiently large relative to $\alpha$. Fix an integer $\tau \ge 0$, a real number $\nu\ge 0$, and $\overline{a} \in (\mathbb{Z}_{\ge 0})^j$. Let $E^+$ be a constant-escape process on $[j]$ with send sequence~$\overline{p}$, start time $\tau$, end-of-step arrival rate $\nu$, and $\overline{\mathrm{arr}}_{[j]}^{E^+}(\tau) = \overline{a}$. Fix $k \in [j]$ and $t \ge \tau$, and let $\mu = h_k^{\nu,\overline{a}}(t-\tau)$. If $\mu \leq \alpha^2j(\log j)^2/6$, then with probability at least $1-j^{-3j}$,
    \begin{equation}
        b_k^{E^+}(t) \le \alpha^2j(\log j)^2.
    \end{equation}
    Otherwise, with probability at least $1-j^{-3j}$,
    \begin{equation}
        b_k^{E^+}(t) \le \Big(1 + \frac{\alpha j^{1/2}\log j}{4\mu^{1/2}}\Big)\mu < 2\mu.
    \end{equation}

[Lemma lm:ProbEstimate of arXiv:2608.27828, 'Scaling limit of the 3D abelian Yang--Mills Langevin dynamics'] Let $T>0$, $p \geq 2$, and $0<\kappa<1$ sufficiently small. Then, for any $\tilde\kappa\in (0,\kappa)$,
\begin{align}

 \E\sup_{t\in [0,T]}\|\tilde \Psi^\varepsilon(t)\|^p_{\CC^{-1/2-\kappa}_\varepsilon} & \le C_{p,T}  \;,
 \\

  \E \sup_{t\in [0,T]} \norm{  \varepsilon^{4}\mathop{}\!\mathrm{d}_\varepsilon^* (\mathop{}\!\mathrm{d}_\varepsilon\tilde\Psi^\varepsilon )^3 (t)}^p_{\CC^{-3/2-2\kappa}_\varepsilon}
  & \le C_{p,T} \varepsilon^{p \tilde\kappa} 
\end{align}
where the constant $C_{p,T}>0$ may depend on $p,T,\kappa,\tilde\kappa$, but is independent of $\eps>0$.

