{"artifact_digest":"sha256:bf7a65b0e4c8e7dee6634e8cea9f5720706d3c16a2c3955f92c382692fb9d417","artifact_path":"objects/sha256/bf/bf7a65b0e4c8e7dee6634e8cea9f5720706d3c16a2c3955f92c382692fb9d417.md","bundle_digest":"sha256:e9b8ee6055b1c101dade12042df114c83056296f6bc449d777806b4bf1ac28ac","bundle_entry_key":"2606-01944-theorem-4-prop4-2","bundle_id":"population.tex-extract-s1_030","claim_kind":"theorem","conditions":[],"domain":"probability theory","draft":"tex-extract-v2-20260907/bundle_s1_030.json","evidence_ids":[],"logical_id":"math:harvest.arxiv.mathematics:arxiv-2606-01944-proposition-4-prop4-2","overlay_schema_version":1,"proof_text":"Paper's own proof, opening: Set 
\begin{align*}
\bar{U}^i_t=\mathsf{E}\left[\xi^i+\int_t^T f^i\left(s,Y^{i}_s,\frac{1}{N}\sum_{j=1}^N Y^j_s\right)ds\Bigg|\mathcal{F}^{(N)}_t\right].
\end{align*}

Let $\bar{S}$ be the Snell envelope for $\{L^{(N)}_t(\bar{U}_t)\}_{t\in[0,T]}$. By the proof of Theorem (thm4.1 of the paper), we have
\begin{align}
Y^i_t=\bar{U}^i_t+\bar{S}_t=\bar{U}^i_t+\esssup_{\tau\in\mathcal{T}^N_{t,T}}\mathsf{E}\left[L^{(N)}_\tau(\bar{U}_\tau)\Big|\mathcal{F}^{(N)}_t\right].
\end{align}
It follows that, for any $t\in[0,T]$, 
\begin{equation}\begin{split}
