[Lemma 19 of arXiv:2608.13687, 'Multiplicative chaos from random multiplicative functions'] For $\theta \in (0,1]$, the family of measures $(\mu^{\text{GMC}}_{N,\varepsilon})_{N,\ep \geq 0}$
    converges in distribution in $\cM(\mathcal{I})$ to $\mu_{\infty}^{\text{GMC}}$ as $\min(N,1/\ep) \to \infty$.
\begin{proof}
Let $C_{N,\ep}(x,y)$ denote the covariance function of $2\Re G_{N,\ep}$.
According to \cite[Theorem~1.1]{junnila-saksman}, and given \cref{lem:gmc-critical-line-convergence}, it suffices to show the following: there exists a sequence $R=R(\varepsilon, N)\in\N$, such that $R(\varepsilon,N)\to\infty$ as $\min(N,1/\ep)\to\infty$, and $C_{N,\ep}$ satisfies
\begin{equation}
        \sup_{N,\ep}\sup_{x,y}|C_{N,\ep}(x,y)-C_{R,0}(x,y)|\leq C<\infty 
\end{equation}
as well as
    \begin{equation}
        \lim_{\min(N,1/\ep)\to\infty}\sup_{|x-y|\geq\delta}|C_{N,\ep}(x,y)-C_{R,0}(x,y)|=0 \,,\quad\text{for all $\delta>0$.}
    \end{equation}
We show \eqref{eq:criteria1} and \eqref{eq:criteria2} for $R \coloneqq \min(\lfloor \exp(1/\ep) \rfloor , N)$. 
The computation is similar to the proofs of \cite[Lemma~2.6]{goro-wong-2} and \cite[Lemma~1]{atherfold2025fourier}. All convergence statements are as $\min(N,1/\varepsilon)\to\infty$. 

Using Stieltjes integration by parts, we have 
\begin{align}
    \big|C_{N,\varepsilon}&(x,y)-C_{R,0}(x,y)\big|=2\Big|\sum_{p}\frac{|f(p)|^2}{p}\big(p^{-2\varepsilon}\mathbbm{1}_{p\leq N}-\mathbbm{1}_{p\leq R}\big)\cos(|x-y|\log p)\Big|\notag\\
    &=2\Big|\int_{2}^{N} p^{-1}\big(p^{-2\varepsilon }\mathbbm{1}_{p\leq N}-\mathbbm{1}_{p\leq R}\big)\cos(|x-y|\log p)\d(\theta\li(p)+\cE_{|f|^2}(p))\Big|\notag\\
    &\ll\Big|\int_{2}^{N}\theta\big(p^{-2\varepsilon }\mathbbm{1}_{p\leq N}-\mathbbm{1}_{p\leq R}\big)\cos(|x-y|\log p)\tfrac{\d p}{p\log p}\Big| \\
    &\qquad+\Big|\,\Big[p^{-1}(1-p^{-2\varepsilon})\cE_{|f|^2}(p)\cos(|x-y|\log p)\Big]^{R}_{2}\,\Big|\\
    &\qquad+\int_{2}^{R}\frac{\cE_{|f|^2}(p)}{p^2}\Big(\big|(1+2\varepsilon)p^{-2\varepsilon}-1\big|+(1-p^{-2\varepsilon})|x-y|\Big)\d p\\
    &\qquad + \Big|\Big[p^{-1} p^{-2\varepsilon}\cE_{|f|^2}(p)\cos(|x-y|\log p) \Big]_{R}^N \Big|+\int_R^N \frac{\mathcal{E}_{|f|^2}(p)}{p^2}\big(p^{-2\varepsilon}(1+2\varepsilon)+p^{-2\varepsilon}|x-y|\big)\;\mathrm{d}p\,. 
\end{align}
We start by bounding \eqref{eq:line3}. Using that $\mathcal{E}_{|f|^2}(x) = o(x/\log x)$ and $|\cos(|x-y|\log p)|\le 1$ we get
\begin{equation*}
    \Big|\,\Big[p^{-1}(1-p^{-2\varepsilon})\cE_{|f|^2}(p)\Big]^{R}_{2} \,\Big|\ll o\Big(\frac{1}{\log R}\Big)+C\cdot (1-2^{-2\varepsilon}) \to 0\,.
\end{equation*}
For \eqref{eq:line4}, let $F(\ep;p)$ be the integrand in \eqref{eq:line4}. 
Using 
$
\max\{1-p^{-2\varepsilon},|(1-2\varepsilon)p^{-2\varepsilon}-1|\}\ll 2\varepsilon \log p
$,
\begin{align}
    \int_{2}^{R}F(\varepsilon;p)\d p\ll\int_{2}^{\log R}\frac{|\cE_{|f|^2}(p)|}{p^2}(2\varepsilon\log p)(1+|x-y|)~\d p+\int_{\log R}^{\infty}\frac{|\cE_{|f|^2}(p)|}{p^2}(1+|x-y|)~\d p.
\end{align}
Due to condition \eqref{eq:remainder}, the second integral converges to 0 uniformly in  $x,y\in\mathcal{I}$. For the first integral, using $\cE_{|f|^2}(p)=o(p/\log p)$ and $\varepsilon\ll 1/\log R$, we see that it is uniformly bounded by $O( \log\log R/\log R)$, which converges to zero. Thus, \eqref{eq:line3} and \eqref{eq:line4} satisfy  \eqref{eq:criteria1} and \eqref{eq:criteria2}. 

For \eqref{eq:line5}, the first term is uniformly bounded by $O(R^{-1}|\cE_{|f|^2}(R)|+N^{-1}|\cE_{|f|^2}(N)|)\ll o(1/\log R)$, which converges to zero. Up to a universal constant, the second term is smaller than the second summand on the right hand side of \eqref{eq:FeppSplit} and thus also converges to zero.

Lastly, for \eqref{eq:line2}, we first compute the integral over $p\in[2,R)$ by changing variables $s=\log p$:
\begin{align}
    \Big|\int_{2}^{R}\theta&\big(p^{-2\ep}\mathbbm{1}_{p\leq N}-\mathbbm{1}_{p\leq R}\big)\cos(|x-y|\log p)\tfrac{\d p}{p\log p}\Big|\leq\Big| \int_{\log2}^{\log R}\frac{e^{-2\ep s}-1}{s}\cos(|x-y|s)\d s\Big|\,.
\end{align}
For fixed $|x-y|>0$,  we use Taylor's theorem $e^ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 33 (Viscosity solutions) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] Let $\bar\xi$ be a regularization of $\xi$, and let $\H$ be defined by~\eqref{e.def_H_spin_glass}. Consider the Hamilton--Jacobi equation
\begin{align}
    \partial_t f- \H(\partial_q f)=0,\quad &\text{on $\R_+\times \mcl Q^\D_2$}.
\end{align}
\begin{enumerate}
    \item A continuous function $f:\R_+\times \mcl Q_2^\D\to \R$ is a \textbf{viscosity subsolution} of~\eqref{e.hj_H} if, for every $(t,q) \in (0,\infty)\times \mcl Q_2^\D$ and every smooth $\phi:(0,\infty)\times \mcl Q_2^\D\to\R$ such that $f-\phi$ has a local maximum at $(t,q)$, we have
    \begin{align*}
        \left(\partial_t \phi - \H(\partial_q\phi)\right)(t,q)\leq 0.
    \end{align*}
    \item A continuous function $f:\R_+\times \mcl Q_2^\D\to \R$ is a \textbf{viscosity supersolution} of~\eqref{e.hj_H} if, for every $(t,q) \in (0,\infty)\times \mcl Q_2^\D$ and every smooth $\phi:(0,\infty)\times \mcl Q_2^\D\to\R$ such that $f-\phi$ has a local minimum at $(t,q)$, we have
    \begin{align*}
        \left(\partial_t \phi - \H(\partial_q\phi)\right)(t,q)\geq 0.
    \end{align*}
    \item A continuous function $f:\R_+\times \mcl Q_2^\D\to \R$ is a \textbf{viscosity solution} of~\eqref{e.hj_H} if it is both a viscosity subsolution and a viscosity supersolution.
\end{enumerate}
Finally, a continuous function $f:\R_+\times \mcl Q^\D_2\to\R$ is called a \textbf{viscosity solution} of~\eqref{e.hj} if it is a viscosity solution of~\eqref{e.hj_H} for some regularization $\bar\xi$.

[Prop p:cond-var-delta of arXiv:2607.18194, 'Temperature chaos in directed polymers'] There exists $C,c>0$ depending only on $R_1,R_2$, such that for all sufficiently small $\delta$,
    \begin{align*}
        \max_{i\in\llbracket 0, N-1\rrbracket}
        \sup_{z,w\in J^\delta}
        \mathbb{E}\left[
            \Var\left(
                \mathcal{L}(s_i,z ;s_{i+1}, w)\,\middle|\,\mathcal{F}_{R_1}\vee\mathcal{F}_{R_2}
            \right)
        \right]
        \leqslant Ce^{-c\log^2(1/\delta)}.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

