body:
[Theo 3 of arXiv:2609.00186, 'Macroscopic scalar curvature bounds on surfaces'] Let $(\Sigma,g)$ be a closed oriented Riemannian surface of genus $k= 1$. Then, for every $r>0$,
    \begin{equation}
    \max_{\tilde x\in \tilde \Sigma}\area_{\tilde g}(B_{\tilde g}(\tilde x,r))\geq \pi r^2,
    \end{equation}
    with equality for a given $r>0$ if and only if $g$ has constant curvature 0. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Conjecture conj:1 of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Let $\operatorname{\bf NG}_{s}$ be a probability measure given by moment generating function
\begin{align}
	\operatorname{\bf NG}_s [e^{(\psi, f)} ] \propto \int_{\R} e^{(\psi,  \Phi(f) )} e^{-\frac{1}{4} |y|^4 -  s |y|^2} {\rm d} y .
\end{align}
Under the assumptions of Theorem~(thm:NGlimit of the paper),  there exists $c>0$ such that
\begin{align}
	\lim_{N\rightarrow \infty}  \langle e^{(\varphi,f_N) / {\sf b}_N} \rangle_{g,\nu_c + sw_N, N} = \operatorname{\bf NG}_{cs} ( e^{(\psi, f) / c_3^{1/4}}  ) .
\end{align} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Lem 8 of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Let $M$ be a compact connected smooth manifold without boundary, $H$ a Tonelli Hamiltonian on $M$, $\phi\in\SCL(M)$, and $u$ the viscosity solution of \eqref{eq:HJephi pre}. If $x\in\reg(\phi,H)$ and $t\in(0,\tau_{\phi,H}(x)]$ for $\tau_{\phi,H}(x)<+\infty$, or $t\in(0,+\infty)$ for $\tau_{\phi,H}(x)=+\infty$, then there exists a unique $(u,H)$-calibrated curve $\gamma:[0,t]\to M$ with $\gamma(0)=x$, and it is given by
	\begin{align*}
		\gamma(s)=\pi\circ\Phi^s_H(x,D\phi(x)),\qquad \forall s\in[0,t],
	\end{align*}
	where $\pi:T^*M\to M$ is the canonical projection and $\Phi^s_H$ is the Hamiltonian flow of $H$.

