[Lemma 16 of arXiv:2607.23791, 'Precise cover times for branching random walks on Hamming graphs: (iterated) logarithmic c'] For every integer $P\ge2$ and every $0\le\gamma<P-1$, for $d$ large enough,
\begin{equation*}
 \sum_{k\ge1}(1+k)^\gamma
 \E_{\mathbb Q_s}\!\left[\Pi_{\mathcal T_s}(k)^P\right]
 \ll_{P,\gamma,B}1.
\end{equation*}

[Lemma 12 of arXiv:2608.14802, 'Dynamical Gibbs-non-Gibbs transitions for finite-alphabet models on trees'] For the constant configuration $\eta\equiv k$ where $k\in \{1,2,3\}$, the time-dependent homogeneous
recursion $g_t^{[k]}$ expressed in the quotient coordinates defined in \eqref{eq: Quotient coordinates definition} is represented by the map
$\widetilde{g}_t^{[k]}:(\R_+)^2\to(\R_+)^2$ defined by 
\begin{equation*}
\widetilde{g}_t^{[1]}(x,y)=\left( m_tg_1, g_2\right), \quad \widetilde{g}_t^{[2]}(x,y)=\left( m_t g_1,m_t g_2\right), \quad \widetilde{g}_t^{[3]}(x,y)
=\left( g_1,m_t g_2\right)
\end{equation*}
where
\begin{equation*}
    g_1=g_1(x,y):=\left(\frac{\theta x+y+1}{x+y+\theta}\right)^2\qquad \text{and} \qquad g_2=g_2(x,y):=\left(\frac{x+\theta y+1}{x+y+\theta}\right)^2
\end{equation*}
and $m_t:=\frac{1-e^{-\frac{3}{2} t}}{1+2e^{-\frac{3}{2} t}}.$

