body:
[Proposition 3 of arXiv:2605.30030, 'Critical exponents for planar random-cluster model with cluster-weight~$q=4$'] There exists a function~$f:(0,1)\to(0,\infty)$ such that
\begin{align}

\lim_{\delta\to 0} f(\delta)^{-2}\rcE_{\delta \Z^2,p_c,4}[0\longleftrightarrow x_\delta]=|x|^{-1/4}
\end{align}
uniformly for~$x$ in any compact subset of~$\R^2\setminus\{0\}$, where~$x_\delta$ denotes the vertex of~$\delta\Z^2$ closest to~$x$ (if there are more than one, choose one arbitrarily), and~$f(\delta)=\delta^{1/8+o(1)}$ as~$\delta$ tends to $0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop eq:min.odometer.bound of arXiv:2411.02541, 'The hockey-stick conjecture for\\ activated random walk'] \thlabel{prop:min.odometer.concentration}
 Let  
  $\mathfrak{m}$ be the minimal odometer of $\mathcal{O}_{n}(\mathsf{Instr},\sigma,u_0,f_0)$.
  Let
  \begin{align*}
    e_i= -f_0-\sum_{v=1}^i\abs{\sigma(v)}
  \end{align*}
  and suppose that $\abs{e_i}\leqe_{\max}$ for some $e_{\max}\geq 1$.
  For some constants $c,C>0$ depending only on $\lambda$, it holds
  for all $t\geq 4e_{\max}$ that
  \begin{align}
    \mathbf{P}\Biggl(\abs[\bigg]{\rt{\mathfrak{m}}{j}-\biggl(\frac{u_0}{2(1+\lambda)}+\sum_{i=1}^je_i\biggr)} \geq t\Biggr)
      \leq C\exp\biggl(-\frac{ct^2}{n\bigl(ne_{\max} + u_0+t\bigr)}\biggr)
  \end{align}
  for all $1\leq j\leq n$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 3 of arXiv:2606.10074, ''] Let $a,b\in \{0,1\}^L$.  For $v\in\{0,1\}^\#$, define 
  \begin{align} 
    \Pi^v_{a,b}
    =
    \{x\in\{0,1\}^\#: (vx)^L_{L+t}\ne a\text{~or~} b \text{~for~}
    0<t<|x|, (vx)^L_{L+|x|} = a\}. 
  \end{align}
  If $a\ne b$, then the following are true.
  \begin{subenum}
  \item
    $\Pi^a_{b,a} \ne \emptyset$.
  \item
    For any $v\in \{0,1\}^L\setminus\{a,b\}$, $\Pi^a_{v,b} \cup
    \Pi^b_{v,a} \ne \emptyset$ and $\Pi^v_{a,b}\cup \Pi^v_{b,a} \ne
    \emptyset$.
  \item
    $\Pi^a_{a,b}\ne\emptyset\Iff \{a,b\}\ne\{(1-x)x^{L-1},
    x^{L-1}(1-x)\}$, where $x=0$ or 1.
  \end{subenum}

[Proposition 23 of arXiv:2604.22461, 'Large deviation principles for stationary solutions and invariant measures of a class of S'] For the solution $X^{\epsilon}_{t;t_0,\xi}$ of Eq. \eqref{eq: SPDE}, if the following two items hold:
\begin{description}
  \item[(S1)] Let $M>0$, the sequence $\{v^{\epsilon}: \epsilon>0\}\subset \mathcal{A}_M$ and $\{\xi^{\epsilon}\}_{\epsilon>0} \subset H$. If $v^{\epsilon}$ converges to $v$ in distribution as $S_M-$valued random elements and $\xi^{\epsilon}$ converges to $\xi$ in $H$ as $\epsilon\rightarrow 0$, then
\begin{equation*}
  \mathcal{G}^{\epsilon}_{t_0,\xi^{\epsilon}}\Big(W(\cdot)+\frac{1}{\sqrt{\epsilon}}\int^{\cdot}_0v^{\epsilon}(s) \, \d s\Big) \rightarrow \mathcal{G}^{0}_{t_0,\xi}\Big(\int^{\cdot}_0v(s) \,  \d s\Big) \quad \mbox{on} \quad \sC_{t_0},
 \end{equation*}
in distribution as $\epsilon\rightarrow 0$.
  \item[(S2)] $\xi\mapsto \mathcal{I}_{t_0,\xi}$ is an l.s.c. map from $H$ to $[0,+\infty]$; and for each $M>0$ and compact set $K\subset H$, the set $\Gamma_{M; t_0,K}=\{\mathcal{G}^{0}_{t_0,\xi}(\int^{\cdot}_0v(s) \,  \d s)\in\sC_{t_0}: v\in S_M, \xi\in K\}$ is compact,
\end{description}
then $X^{\epsilon}_{t;t_0,\xi}$ satisfies ULDP over compact subsets  on $\sC_{t_0}$ with the good rate function $\mathcal{I}_{t_0,\xi}$:
\begin{equation*}
  \mathcal{I}_{t_0,\xi}(\Phi):=\inf_{\Big \{v\in L^2(\mathbb{R};U); \, \Phi=\mathcal{G}^{0}_{t_0,\xi}\Big(\int^{\cdot}_0 v(s) \,  \d s\Big)\Big\}} \big\{\frac{1}{2}\int^{+\infty}_{-\infty} |v(s)|^2_U \, \d s \big\}, \quad \forall \, \Phi \in \sC_{-\infty}.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

