[Theorem 12 of arXiv:2607.08242, 'Convergence of random sums in non-commutative probability'] Suppose $\{a_i\}$ of $\mathcal{S}_{N_n}$ in Theorem \ref{thm31} are half independent and identically distributed. Let $r_S$ be a standard symmetric Rayleigh variable in $\tilde{\mathcal{A}}$, independent of $\tilde{N}_n$. Then the following hold. \vskip5pt
\noindent(i) Under the conditions of Theorem \ref{thm31} (i), \begin{equation}
        \tilde{\varphi}(\tilde{\mathcal{S}}_{N_n}^m(\delta_n\tilde{N}_n)^l)=\tilde{\varphi}[(\delta_n\tilde{N}_n\cdot1_\mathcal{A}+\sqrt{1-\delta_n^2}r_S)^m(\delta_n\tilde{N}_n)^l]+o(1)\ \ \text{for all}\ \ m,l\in\mathbb{N}\cup\{0\}.
    \end{equation}


\noindent (ii) Under the assumptions of Theorem \ref{thm31} (ii), 
    \begin{equation*}
        \tilde{\varphi}(\tilde{\mathcal{S}}_{N_n}^m(\frac{N_n}{\eta_n})^l)=\mathbb{E}[(\frac{N_n}{\eta_n})^{\frac{m}{2}+l}]\varphi(r_S^m)+o(1),\ \  \text{for all}\ \ m,l\in\mathbb{N}\cup\{0\}.
        \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 14 of arXiv:2511.06196, 'Central limit theorem for high temperature spin models via martingale embedding'] Let \(A \subset \{1,\ldots,n\}\) and choose arbitrary \(\epsilon > 0\).
Denote $a_{j}^{(A)}=\sum_{l=1}^{n} m_{jl}^{(A)}$. Then, for some \(C_{t,\epsilon}, c_\epsilon > 0\), independent of \(n\), we have
    \begin{equation*}
        \E\Big|(a_{j}^{(A)}-a_{j}^{(A\cup \{i\})})(t)\Big|^{2+\ep}\leq \frac{C_{t,\ep}}{n^{1+\ep/2}}
    \end{equation*}
for all \(i\in \{1,\ldots,n\}\), $j\ne i$ and \(0 \le t < c_\epsilon\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 21in of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] [cai2025mesoscopicratesconvergencehermitian]
    Suppose $\mathbf{A}$, $\mathbf{B}$ and $\mathbf{C}$ are Hilbert--Schmidt operators on a Hilbert space. Then the following inequality holds:
    \begin{equation*}
2\|\mathbf{A}\mathbf{B}+\mathbf{B}\mathbf{A}-\mathbf{C}\mathbf{C}\|_1\le\|\mathbf{A}+\mathbf{B}-\sqrt2\mathbf{C}\|_2\|\mathbf{A}+\mathbf{B}+\sqrt2\mathbf{C}\|_2+\|\mathbf{A}-\mathbf{B}\|^2_2.
    \end{equation*}
      Moreover, for any Hilbert--Schmidt operator $\mathbf{K}$ with the integral kernel $K$, it follows that $\|\mathbf{K}\|_2=\|K\|_{L^2}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 29 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Under the assumptions of Lemma \ref{Proposition décomposition de la trace en plusieurs termes}, we have
        \begin{equation}
    \begin{split}
        \int_{t=\alpha}^\beta II^1_tdt &=\mc{O}_M\pr{N^{-(1-\eta)}}\int_{t=0}^{C\beta}\frac{1}{\alpha+t}d\mathscr{V}(t)\\
        &\m\m+N^{-(1-\eta)}\alpha^{-1}\Bigl(\mc{O}_M\pr{N^{-\varrho\eta}\alpha^{-1}}+\mc{O}_M\pr{N^{-\eta{\kappa_1}}\bb{\log(\alpha)}}\Bigl)
    \end{split}

\end{equation}
    and 
    \begin{equation}
    \begin{split}
        II^0_\alpha =N^{-(1-\eta)}\alpha^{-1}\Bigl(\mc{O}(\alpha^{\kappa_2})+\mc{O}(N^{-\varrho\eta}\alpha^{-1})+\mc{O}(N^{-\eta{\kappa_1}})\Bigl).
    \end{split}

