body:
[Theo 2 of arXiv:2603.25459, 'Cram\'{e}r-type moderate deviation for double index permutation statistics'] For double index permutation statistics $W_n$ defined as (\ref{normalized-DIPS-a-b-form}) in Proposition \ref{general-DIPS-convert}, assume that for some constant $0<\delta<1$, the following boundedness conditions hold
\begin{equation}
\begin{aligned}
    &\max_{i,k}|a(i,k)|\leq \delta, \quad \max_{i,\pi}\sum_{j}\left|b(i,j,\pi(i),\pi(j))\right| \leq \delta,\\
    &\max_{i,j,k,l}|b(i,j,k,l)| \leq \delta,\quad \max_{\substack{s\in\{1,2\}\\ t\in\{1,2\}}}\max_{\substack{i_{s}\in[n]\\k_{t}\in[n]}}\sum_{\substack{i_{3-t}\in[n]\\j_{3-t}\in[n]}}|b(i_{1},i_{2},k_{1},k_{2})|\leq \delta.

\end{aligned}

\end{equation}

Without loss of generality, assume that $\mathbb{E}\{W_n^2\} = 1 + \frac{C}{\sqrt{n}}$, where $C$ is a constant. For any $\theta >0$, let $\tau(\theta) := \max\{0\leq t \leq 1/\delta: t^3\delta + \sqrt{n}\delta^3t^2 + n\delta^3t^3 + t\delta + t^2/n \leq \theta \}$. Then for any $0\leq z\leq \tau(\theta)$,
\begin{align}
    \left|\frac{\mathbb{P}(W_n>z)}{1-\Phi(z)}-1\right|\leq C_1e^{\theta}(1+z^2)(\sqrt{n}\delta^2 + n\delta^3 +n\delta^3z+\delta)
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 14 of arXiv:2608.04853, 'Minimal-Norm Extensions of Stationary Kernels on Subgroups of Locally Compact Abelian Grou'] Let $G$ be a compact abelian group and let $H\subseteq G$ be a closed subgroup. Let
$X:\Omega\to L^2(G)$ be a centered stationary Gaussian random variable with continuous realizations, and let $k_X$ be its covariance kernel with spectral density $\hat k_X$. Define $Y:=\tilde{X}|_H$. Then the Fourier formula 
\begin{align*}
    \widehat{Mg}(\xi)= \hat{g}(\xi_H) \frac{\hat{k}_X(\xi)}{\hat{k}_Y(\xi_H)}, \qquad \xi \in \hat{G}, \quad \xi_H =\xi+H^\perp,
\end{align*}
with the quotient interpreted as zero whenever $\hat{k}_Y(\xi_H)=0$, defines a bounded operator $M:L^2(H) \to L^2(G)$. Equivalently 
\begin{align*}
    Mg
=
\sum_{\xi\in\widehat G}
\hat g(\xi_H)
\frac{\hat k_X(\xi)}
{\hat k_{Y}(\xi_H)}
\xi,
\qquad
\xi_H:=\xi+H^\perp.
\end{align*} 
Moreover, 
\begin{align*}
  \Vert  Mg\Vert_{L^2(G)}^2
\leq
\left[
\sup_{\xi_H\in\hat G/H^\perp}
\frac{
\sum_{\xi^\perp\in H^\perp}
|\hat k_X(\xi_H+\xi^\perp)|^2
}{
\left|
\sum_{\xi^\perp\in H^\perp}
\hat k_X(\xi_H+\xi^\perp)
\right|^2
}
\right]
\Vert g\Vert_{L^2(H)}^2
\leq
\Vert g\Vert_{L^2(H)}^2 .
\end{align*}
If $W_Y$ is dense in $L^2(H)$, then $M$ is the unique bounded extension of the minimal-norm extension operator $M_W:W_Y \to W_X$. In this case 
\begin{align*}
    MY= \E(X \vert Y).
\end{align*} 
Finally, since $W_X=\mathcal{N}(G)$ and $W_Y=\mathcal{N}(H)$, it follows that, for $0 \leq \theta \leq 1$, the operator $M$ restricts to a bounded operator $M_\theta:\mathcal{N}(H)_\theta \to \mathcal{N}(G)_\theta$ and
\begin{align*}
    \Vert M_\theta \Vert_{\mathcal{N}(H)_\theta \to \mathcal{N}(G)_\theta} \leq 1.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:GFF-integration of arXiv:2411.19810, 'Radial conformal welding in Liouville quantum gravity'] Let $U\subset \mathbb{H}$ be a bounded simply connected domain such that there exists $a,b>0$ with $(-a,b)\subset\partial U$. Also assume $U$ is disjoint from $\mathcal{L}_i$ and $\partial U\cap\mathbb{H}$ is smooth.
	    Let $t >0$ be any  time such that $\eta([0,t]) \subset \overline U$.
	    Suppose $\tilde g\in H(\mathbb{H})$ is a smooth function whose support is bounded and disjoint from $\mathcal{L}_i$ such that $\tilde g(z) = g(z)$ in $U$. Then for $w\in U$,
	    \begin{align}
	        &\int_\mathbb{H} \Delta\tilde g(z) G_t(z,w) dz = -2\pi(\arg(f_t(w)-f_t(i))+\arg(f_t(w)+\overline{f_t(i)}));
	          \\& \int_\mathbb{H} \Delta\tilde g(z) \mathrm{Im}(\frac{2}{f_t(z)}) dz = -2\pi\mathrm{Re}(\frac{2}{f_t(i)}). 
	    \end{align}

[Proposition 5 of arXiv:2510.27451, 'Bi-martingale optimal transport and its applications'] For every plan $\gamma \in \ov\Gamma(\mu,\nu)$ there exists a Zolotarev projection $\ov\rho \in \Pi_{\succeq_c \mu}(\nu)$ and a martingale plan $\breve\gamma  \in \Gamma_{\mathrm{M}}(\mu,\ov\rho)$ such that,
	\begin{equation*}
		\int_X W_2^2(\gamma_x,\breve\gamma_{x}) \,\mu(dx)  =  \big(1- \alpha_{\succeq_c}(\nu\,|\,\mu) \big) Z_2(\mu,\nu),
	\end{equation*}
	where $\gamma_x,\breve\gamma_{x}$ are the relevant transport kernels with respect to the marginal $\mu$. Moreover, the Zolotarev projection and the martingale plan can be computed as follows: $\breve\gamma = (\pi_1,\ov\zeta) \# \gamma$ and $\ov{\rho} = \ov\zeta \# \gamma$, where $\ov\zeta$ is expressed by \eqref{eq:ovzeta} for any optimal potential $\ov{u}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:2G_randomD of arXiv:2605.21265, 'The non-Hermitian minor process'] Let $X$ satisfy Assumption~(ass:chi of the paper)(i).  Fix a (large) $L>0$ and (small) $c_0,\epsilon,\nu,\xi>0$. Let $\theta>0$ be a (possibly, $N$-dependent) small parameter.  Consider $k_j\in[N]$ and denote $x_j:=k_j/N$, $j=1,2$. There exists a universal constant $d>0$ such that
\begin{equation}
\left\vert\left\langle \left(G_1B_1\widetilde{G}_2 - M_{1\widetilde{2}}^{B_1}\right)B_2\right\rangle\right\vert \le C_\theta \frac{N^\xi}{N\eta_1\eta_2},

\end{equation}
uniformly in $\eta_j:=|\Im w_j|\in (N^{-1+\epsilon}, N^L)$, $|\Re w_j|\le \theta^d N^{-\nu}\eta_j$, $z_j\in \mathbf{C}$ such that $\theta\le|z_j-\sqrt{x_j}|\le L$, $x_j\in [c_0,1]$ and in deterministic matrices $B_j\in \{E_\pm^{(k_j)},\big(F^{(k_j)}\big)^{(*)}\}$, $j=1,2$. The constant $C_\theta>0$ in (equation eq:2G_av of the paper) satisfies $C_\theta\le \theta^{-D}$ for some fixed $D>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

