[Lemma AuxiliaryEstimate of arXiv:2411.06089, '{\Large \bf Averaging principle for semilinear slow-fast rough partial differential equati'] For any $T>0$ and $(x,y)\in \mathcal H_\eta \times \mathcal{H}$ with $\eta \in [0,\gamma)$ and $\gamma\in (1/3,\gamma_0)$, there exists a constant $C_{M,T}>0$ such that
\begin{equation}
\sup_{t\in [0,T]}\mathbb E \| Y_t^\varepsilon-\hat{Y}_t^\varepsilon\|_{\mathcal H}^4 \leq  C_{M,T} \delta^{4 \eta} (1+\|x\|_{\mathcal{H}_\eta}^4+\|y\|_{\mathcal{H}}^4 ),
\end{equation}
and
\begin{equation}
	\sup_{t\in[0,T]}\mathbb E\|\hat{Y}_t^\varepsilon\|_{\mathcal H}^2\leq C_T(1+\|x\|_{\mathcal H}^2+\|y\|_{\mathcal H}^2).
\end{equation}

