[Proposition prop:asymptotic_threshold of arXiv:2412.00279, 'Optimal local storage policy based on stochastic intensities and its large scale behavior'] Consider a family of local memory systems, indexed by $N$, with request processes satisfying Assumptions (ass:renewal of the paper) and (ass:weak_convergence of the paper). Choose the memory size of the $N$-th system as $C_N=cN$ with $0< c \leqslant 1$. If there exists a unique solution to $\theta^*$ satisfying:
\begin{equation*}
  G_\infty(\theta^*) = 1-c
\end{equation*}
then the sequence of thresholds $\theta_N:=\theta_{C_N}$ defined by (equation eq:threshold_n of the paper) satisfies $\theta_{N}\to\theta^*$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 (Uniform threshold transfer) of arXiv:2608.20101, '\bfseries Largest bulk gap of the complex Ginibre ensemble'] Let \(t_n\ge0\), \(\kappa>0\), and suppose that
\begin{equation}
 \sup_{a\in B}
 \left|K_n(a,a)q_n(a,t_n)-\kappa\right|\longrightarrow0.
\end{equation}
Then
\begin{equation}
 \Pp\{N_n(t_n;B)=0\}\longrightarrow e^{-\kappa|B|},
\end{equation}
and, for every fixed \(k\ge1\),
\begin{equation}
 \Pp\{N_n(t_n;B)\le k-1\}
 \longrightarrow e^{-\kappa|B|}
 \sum_{j=0}^{k-1}\frac{(\kappa|B|)^j}{j!}.
\end{equation}

[Proposition 24 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] Let $\Lambda$ be a compact subset of $\Delta_I$ and let $k_t:\Lambda\to\N^d$ satisfy the preceding approximation condition. Then

\begin{equation*}
\sup_{\lambda\in\Lambda}
\left|\frac{\mathfrak N(k_t(\lambda))}{t}-\kappa(\lambda)\right|
\xrightarrow[t\to\infty]{\mathrm{a.s.}}0.
\end{equation*}

If $\Ee_{\mathfrak a}[L_1]<\infty$, then

\begin{equation*}
\sup_{\lambda\in\Lambda}
\left|\frac{N(k_t(\lambda))}{t}-\rho(\lambda)\right|
\xrightarrow[t\to\infty]{\mathrm{a.s.}}0.
\end{equation*}

The same convergences hold in probability under every initial law for which the first entrance time into the split atom and the corresponding entrance displacement are finite almost surely. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 16 ({\cite[Theorem 8.1.6) of arXiv:2608.12070, 'Central limit theorems for a heavy-tailed subcritical Galton-Watson process with state-dep'] {RV}}] 
$\xi$ is an non-negative random variable, $l(\cdot)$ is a slowly varying function at $\infty$. Define $F(x)=\P(\xi\le x)$. $\hat F$ is the Laplace transform of $\xi$, i.e., $\hat F(s)=\E[\mathrm{e}^{-s \xi}]$.   If $\mu_n:=\E[\xi^n]<\infty,\, \alpha=n+\beta,\, \beta\in[0,1]$, then the following are equivalent:
\begin{align*}
f_n(s):= (-1)^{n+1}\left\{\hat F(s)-\sum_{i=0}^n \mu_i\frac{(-s)^i}{i!} \right\}\sim s^\alpha l(1/s),\,  s\downarrow 0\\
\begin{cases}
\displaystyle\int_{x}^\infty t^n dF(t)\sim n!l(x)\quad   &\beta=0 \\
1-F(x)\sim \dfrac{(-1)^n}{\Gamma (1-\alpha)}x^{-\alpha}l(x)   &\beta\in(0,1),\quad  x\to \infty,\\ 
\displaystyle\int_{0}^x t^{n+1} dF(t)\sim (n+1)!l(x)\quad   &\beta=1
\end{cases}
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

Let $(K, \langle \cdot, \cdot \rangle_K)$ and $(\mathcal{H}, \langle \cdot, \cdot \rangle_\mathcal{H})$ be real separable Hilbert spaces. An isonormal Gaussian process $W = \{W(h) : h \in \mathcal{H}\}$ on a complete probability space $(\Omega, \mathcal{F}, \mathbb{P})$ is a family of centered Gaussian random variables such that $\mathbb{E}[W(h_1) W(h_2)] = \langle h_1, h_2 \rangle_\mathcal{H}$. A $K$-valued Wiener functional is a measurable map $F: \Omega \to K$. The space $L^p(\Omega; K)$ consists of strongly measurable $K$-valued random variables $F$ with $\mathbb{E}[\|F\|_K^p] < \infty$.
K and \mathcal{H} are real separable Hilbert spaces
W is an isonormal Gaussian process on \mathcal{H}

[Definition 19 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] We say that a rough path $\mathbf{X} = (X,\bbx) \in \scrc^{\alpha}([0,T],V)$ is \emph{weakly geometric} if the first order calculus condition
\begin{align}
{\rm Sym}(\bbx_{s,t}) = \frac{1}{2} X_{s,t} \otimes X_{s,t} \quad \text{for all $s,t \in [0,T]$}
\end{align}
is fulfilled.

[Thm 43 (Explicit upper bounds) of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] Let $\sigma, \alpha > 0$ and $d_0 \coloneqq 1 - \log 2$. Then
\begin{align}
    \sigma \vee \alpha \ <\ c^{\SG}(\sigma, \alpha) \ \le\ (\sigma + 2\alpha) \wedge \sigma\,\mathcal{U}(a),

\end{align}
{where $a = \alpha/\sigma$ as in \eqref{eqn:normalize} and}
\begin{align}
    \mathcal{U}(a) \coloneqq \sup_{\ell \ge \log 2} \frac{a\ell + \sqrt{2\ell}}{\ell + d_0},

\end{align}
{a one-variable supremum that Lemma~\ref{lem:sgMeval} evaluates in closed form. Its variable is $\ell = \log(1/p)$, and the constraint $\ell \ge \log 2$ is the range of $\ell$ as the atom weight $p$ runs over $(0,1/2]$.} Consequently
\begin{align}
    \frac{c^{\SG}(\sigma,\alpha)}{\sigma \vee \alpha} \longrightarrow 1
    \qquad \text{as } a \downarrow 0 \text{ and as } a \to \infty.

\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 30 (Contribution of $\Omega_{\pm,\alpha}$ in direction $\alpha_b$) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] Suppose that $x_{max}^+ < x_{max}^-$.
Then, \begin{itemize}
    \item If $r(\alpha - \alpha_b)^2$ remains bounded, then the asymptotic contribution of the integrals along $\Omega_{\pm,\alpha}$ in \eqref{I111} is negligible compared to \eqref{jujuju} as $r\to+\infty$ and $\alpha \to \alpha_b$.
    \item If $r(\alpha - \alpha_b)^2 \to +\infty$ and $\alpha \leq \alpha_b$, the following asymptotics hold:
\begin{equation}
\frac{1}{2i\pi}\int_{\Omega_{\pm,\alpha}}\Phi(x)e^{-r(\cos(\alpha)x+\sin(\alpha)Y^+(x))}
 dx
\end{equation}
$$  \underset{r\to+\infty\atop \alpha\to\alpha_b, \alpha \leq \alpha_b}{\sim}\frac{\sin^{3/2}(\alpha_b)\sqrt{\det(\Sigma^-)(\M - x_{min}^-)}}{\sqrt \pi \Sigma_{22}^-(\Sigma_{22}^+ + \Sigma_{22}^-)} f_0(z_0)e^{-r(\cos(\alpha)x(\alpha) + \sin(\alpha)y(\alpha))} \frac{e^{r\tau(\alpha)^2}}{(r(\alpha_b - \alpha))^{3/2}}.$$
\end{itemize}

