[Lemma 20 of arXiv:2604.15226, '\bfseries Nonlinear Schrödinger equations with spatial white noise potential on full space'] Let $\alpha,\mu \in \R$ and $p,q \in [1,\infty ]$. Then there exists a constant $C>0$ such that
\begin{equation*} 
\Big| \int_{\R^d} u(x)v(x)\dd x \Big| \leq C \|u\|_{\mathcal{B}_{p,q,\mu}^\alpha(\R^d)} \|v\|_{\mathcal{B}_{p',q',-\mu}^{-\alpha}(\R^d)},
\end{equation*}
where $\frac{1}{p}+\frac{1}{p'}=1$ and  $\frac{1}{q}+\frac{1}{q'}=1$ for any $u,v\in\CS(\IR^d)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Dfn 35 (Bilateral sub-Gamma class) of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] Let $\sigma, \alpha > 0$. A random variable $X$ belongs to the class $\SG(\sigma^2, \alpha)$ if
\begin{align}
    \E\left[e^{\lambda X}\right] \le \exp\left(\frac{\sigma^2\lambda^2}{2\left(1 - \alpha|\lambda|\right)}\right)
    \qquad \text{for all } |\lambda| < \frac{1}{\alpha}.

\end{align}

[Theorem local_limit_boundary of arXiv:2603.05491, '\textbf{Local limits of uniform triangulations with boundaries in high genus}'] Fix $\theta \in [0,\frac{1}{2})$, $\displaystyle \frac{g_n}{n} \underset{n \to +\infty}{\longrightarrow}\theta$ and $\mathbf{p}^{n} = (p^n_{1},\cdots,p^n_{\ell_n})$ such that $|\mathbf{p}^{n}| = o(n)$ and $\displaystyle \frac{|\mathbf{p}^{n}|}{\ell_n}  \underset{n \to +\infty}{\longrightarrow}+\infty$. Denote by $e^n$ a uniformly chosen oriented edge on the union $\partial_1\cup \cdots \cup \partial_{\ell_n}$ of the boundaries of $T_{n,g_n,\mathbf{p}^{n}}$. Then, the following convergence holds for the local topology
\begin{align*}
   (T_{n,g_n,\mathbf{p}^{n}},e^n) \overset{(d)}{\to}\mathbb{H}_{\lambda(\theta)},
\end{align*}
where $\lambda(\theta)$ is the unique solution to the equation 
\begin{align}
    d(\lambda(\theta)) = \frac{1-2\theta}{6}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:distinct-pair of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] If $L_w(\ell)\ge\tfrac12$, then
\begin{equation}
  s^{\times}(S)
  \le
  \frac{M_w+\binom{\ell}{2}}{2}
  -\frac{L_w(\ell)^2-L_w(\ell)}4.
\end{equation}

[Proposition 5 of arXiv:2608.29713, '\textbf{A Cartan geometry from a correspondence space in Riemannian geometry}'] Let $(M,g)$ be a Riemannian manifold, and let $(q:\mathcal F_g(M)\to M,\omega)$ be the Riemannian geometry associated with $(M,g)$. Under the identification $\mathcal U M \cong \mathcal F_g(M)/H,$ the Cartan connection $\omega$ determines a Cartan geometry of type $(G,H)$ on $\mathcal U M$. Then the objects induced on $\mathcal U M$ by this Cartan geometry are exactly as follows:
\begin{enumerate}
\item the metric $\bar{g}$  is the restriction of the Sasaki metric $\widehat g$ to $\mathcal U M$;
\item the vector field $U$ is the geodesic vector field $\mathbf Z_g$;
\item the $1$-form $\alpha$ is the $1$-form $\tau$;
\item $\mathbb R U\oplus\mathcal E$ is the horizontal distribution $\mathcal{H}$ of $\pi:\mathcal U M\to M$;
\item $\mathcal B$ is the vertical distribution $V$ of
$\pi:\mathcal U M\to M$;
\item the tensor $\Psi$ is the tensor $\Phi$ defined by
\[
J(\xi)=\Phi(\xi)+\widehat g(\mathbf Z_g,\xi)\mathbb A,
\qquad
\xi\in T(\mathcal U M),
\]
where $J$ is the almost complex structure on $TM$ and $\mathbb A$ is the Liouville normal vector field along $\mathcal U M\subset TM$.
\end{enumerate}
Consequently, $(\bar g,U,\alpha,\Psi)$ is the contact metric structure on $\mathcal U M$ induced by the Sasaki metric, as described in
Subsection~\ref{31052026}.

[Theorem thm-ultra-representation of arXiv:2411.12623, 'Random signed measures'] A random signed measure $\xi$ on $S\times T$ has independent $S$-increments iff a.s.
	\begin{equation}
		\xi=\alpha+\sum_{k}(\delta_{s_k}\otimes\beta_k)+\int\int (\delta_s\otimes\mu)\eta_+(ds\,d\mu)-\int\int (\delta_s\otimes\mu)\eta_-(ds\,d\mu)
	\end{equation}
	for some $\alpha\in\mathsf{M}_{S\times T}$ with $\alpha_+(\{s\}\times T)=\alpha_-(\{s\}\times T)=0$, some $\eta_+$ and $\eta_-$ independent Poisson processes on $S\times(\mathcal{M}_T\setminus\{0\})$ with $\mathbb{E}[\eta_+(\{s\}\times (\mathcal{M}_T\setminus\{0\}))]=\mathbb{E}[\eta_-(\{s\}\times (\mathcal{M}_T\setminus\{0\}))]=0$, some distinct points $s_1,s_2,...\in S$, and some independent random signed measures $\beta_1,\beta_2$ on $\hat{\mathcal{T}}$ with distributions $\nu_1, \nu_2,... $, such that
	\begin{equation*}
		\int\mu(C)\wedge 1 \rho(B\times d\mu)<\infty,\quad B\in\hat{\mathcal{S}},\, C\in\hat{\mathcal{T}},
	\end{equation*}
	where $\rho=\rho_1+\rho_2$ and $\rho_1=\mathbb{E}[\eta_+]+\sum_{k}(\delta_{s_k}\otimes\nu_{k})$ and $\rho_2=\mathbb{E}[\eta_-]$. The triplet $(\alpha,\rho_1,\rho_2)$ is unique and determines $\mathcal{L}(\xi)$, and any $\alpha$, $\rho_1$ and $\rho_2$ with the stated properties may occur. Further, $\eta_+$ and $\eta_-$ are the Jordan decomposition of the non-fixed atomic component of $\xi$. (Proof in the paper; no proof environment follows the statement in the TeX.)

