[Definition 12 of arXiv:2606.06193, 'Peng's Maximum Principle for McKean-Vlasov Stochastic Differential Equations with Common N'] On the probabilistic set-up $(\Omega,\cF,(\cF_t)_{t\in[0,T]}, \P)$ we call a strong solution to the conditional McKean--Vlasov BSDE \eqref{eq:Cond-MKVBSDE} on the interval $[0, T]$ a $4$-tuple $(P,Q,R,S)\in \mathbb{S}^{2,m}\times\Lambda^{2,m\times d}\times\Lambda^{2,m\times d}\times\Lambda^{2,m\times d}$ such that $\P$-a.s. for every $t\in[0,T]$,
            \begin{equation*}
                \begin{aligned}
                   P_t=&\xi-\int_t^T\tilde{\E}\left[F\left(t,
                    P_t,\tilde{P}_t,
                    Q_t,\tilde{Q}_t,
                    S_t,\tilde{S}_t,
                    R_t,\tilde{R}_t,
                    \chi_t,\tilde{\chi}_t\right)\right]\dt \\
                    &-\int_t^T R_t\dW^0_t-\int_t^TQ_t\dW^1_t-\int_t^TS_t\dW^2_t,
                \end{aligned}
            \end{equation*}
            such that all integrals are well-defined.

[Lemma lem:swfourier2 of arXiv:2602.11129, 'Information-Theoretic Thresholds for Bipartite Latent-Space Graphs Under Noisy Observation'] Whenever $\boldsymbol{\Sigma}_\beta$ is positive definite for all $\beta \subseteq \alpha$, we have
    \begin{align*}
        \Expectedsub{\mathbf{x}}{ \SW{K_{1,\alpha}} \mid (\mathbf{x}_u)_{u \in \alpha} } &= \lim_{h \rightarrow \infty} \frac{-1}{(2\pi)^{|\alpha|}} \int_{[-\infty, \infty]^{|\alpha|}} e^{-\trp{i\mathbf{t}}{\mathbf{x}}_{\tau}} \left( \sum_{\beta \subseteq \alpha} (-1)^{|\alpha \setminus \beta|}  \hspace{.1cm}\varphi_{\beta}(\mathbf{t}) \right) \prod_{e \in \mathbf{t}} \frac{1 - e^{ih\mathbf{t}(e)}}{i\mathbf{t}(e)} \mathrm{d} \mathbf{t},
    \end{align*}
    where $\varphi_{\beta}(\mathbf{t}) = \Expected{\exp(i\trp{\mathbf{t}}{\mathbf{z}_\beta})}$ is the characteristic function of $\mathbf{z}_\beta$, and $\mathbf{x}_{\tau}$ is the vector that contains $\tau $ everywhere. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 23 (Fixed-precision subcritical dimension cutoff) of arXiv:2608.15914, 'Absorption cutoff and stationary singularities for rounded Gaussian random dynamical syste'] Assume $A<A_{\mathrm{lat}}$, fix $\varrho\in(0,1)$, and let
  $x_N\in[-1,1]^N$ be deterministic. Suppose that $\bar t_N\to\infty$.
  Then
  \begin{equation}
    \Pp\left(
      \tau_{\varrho}^{(N)}
      >
      \bar t_N-1
    \right)
    \to1,
    \qquad
    \Pp\left(
      \tau_{\varrho}^{(N)}
      >
      \bar t_N+2
    \right)
    \to0.
  \end{equation}
  Equivalently, by the total-variation/absorption identity
  \cref{eq:tv-absorption},
  \begin{equation}
    \norm{
      P_{\varrho,A,N}^{\bar t_N-1}
      (Q_\varrho x_N,\cdot)-\delta_0
    }_{\TV}
    \to1,
    \qquad
    \norm{
      P_{\varrho,A,N}^{\bar t_N+2}
      (Q_\varrho x_N,\cdot)-\delta_0
    }_{\TV}
    \to0 .
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 24 of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] Let $p\in[5/2,3)$. Under the assumption of Hypothesis \ref{hypothesis_A}, let $X$ be a solution to the signature McKean--Vlasov SDE \eqref{eq:sig_MKV_SDE}. It holds that
    \begin{equation*}
        \mathbb{E}\left[\lVert \augpr{X}\rVert_{\textup{$p$-var};[0,T]}\right] <\infty.
    \end{equation*}

[Lemma intermediate-system of arXiv:2606.21556, 'Mean field limit of non-exchangeable interacting diffusions on co-evolutionary networks'] Consider the following nonlinear system of SDEs for the unknown processes \((\bar{X}_i^N)_{1\leq i\leq N}\):
	\begin{align}
		d\bar X_i^N(t) &= \frac{1}{N}\sum_{j=1}^N\int_{\mathcal{C}^d_t}\int_{-W}^{W}\Phi_t(\bar X_{i,[0,t]}^N,\gamma,w) K(\bar X_i^N(t),\gamma(t)) \, dq_{ij,0}^N(w) \, d\bar \mu^{N,j}_{[0,t]}(\gamma) \, dt + \sqrt{2\nu}\,dW_i^N(t),\quad t\in [0,T], \nonumber\\
		\bar X_i^N(0) &= X_{i,0}^N, \quad \bar \mu^{N,i}_{[0,t]} := \mathrm{Law}(\bar X_{i,[0,t]}^N) \in \mathcal{P}(\mathcal{C}^d_t),
	\end{align}
	where \(q_{ij,0}^N := \mathrm{Law}(Nw_{ij,0}^N) \in \mathcal{P}(\mathbb{R})\). Under Assumptions (assump:interaction-kernel of the paper), (assump:plasticity-function of the paper), and (assump:weights of the paper), consider initial states \((X_{i,0}^N)_{1\leq i\leq N} \subset L^p(\Omega,\mathbb{R}^d)\) for some \(p\in[1,\infty)\). Provided that these initial states are independent of the driving standard Wiener processes \((W_i^N)_{1\leq i\leq N}\), there exists a unique strong solution \((\bar{X}_i^N)_{1\leq i\leq N} \subset L^p(\Omega,\mathcal{C}_T^d)\) to the system (equation eq:multi-agent-discrete-independent-projection-solved-weights of the paper). Furthermore, if the initial states \((X_{i,0}^N)_{1\leq i\leq N}\) are independent, then the resulting solution processes \((\bar{X}_i^N)_{1\leq i\leq N}\) are also independent.

