[Theorem 8 ({\cite[Theorem 3.2, Remark 3.3) of arXiv:2606.17501, 'Critical spectral behavior and large deviations for geometric $\alpha$-stable processes'] {SikicSongVondracek2006}}]

    For any $\alpha \in (0,2]$,
    \begin{align}
      G(x,y) &\sim
               \begin{dcases}
                 \frac{\Gamma(d/2)}{2\alpha \pi^{d/2}|x-y|^{d} \log^{2}{\frac{1}{|x-y|}}},
                 & |x-y| \to 0, \\
                 \frac{1}{\pi^{d/2}2^{\alpha}}
                 \frac{\Gamma(\frac{d-\alpha}{2})}{\Gamma(\frac{\alpha}{2})}
                 |x-y|^{\alpha - d}, & |x-y| \to \infty.  
               \end{dcases}
      \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 13 of arXiv:2510.24244, 'Statistical properties of Markov shifts: part II-LLT'] Let Assumptions \ref{MixAss}, \ref{Assss} and \ref{Ball Ass} be in force.
There exists $0<\delta_0<1$ such that for every $z\in\bbC$ with $|z|\leq\delta_0$ there are $\lambda_j(z)\in\bbC\setminus\{0\}$, $h_j^{(z)}\in B_j$ and $\ka_j^{(z)}\in B_j^*$ such that $\ka_j^{(z)}(\textbf{1})=\ka_j^{(z)}(h_j^{(z)})=1$, 
 $\lambda_j(0)=1$, $h_j^{(0)}=\textbf{1}$, $\ka_j^{(0)}=\ka_j$
and
\begin{equation}
 L_{j,z} h_j^{(z)}=\lambda_j(z)h_{j+1}^{(z)},\, (\mathcal L_{j,z})^*\ka_{j+1}^{(z)}=\lambda_j(z)\ka_{j}^{(z)}.   
\end{equation}
Moreover, $z\to\lambda_j(z)$, $z\to h_j^{(z)}$ and $z\to\ka_j^{(z)}$ are analytic functions of $z$ with uniformly (over $z$ and $j$) bounded norms.
Finally,  there are $C_1>0, \delta_1\in(0,1)$ such that for every $g\in B_j$ and all $n$,
\begin{equation}
 \left\|L_j^{z,n}g-\lambda_{j,n}(z)\ka_j^{(z)}(g)h_{j+n}^{(z)}\right\|_{j+n,\om}\leq C_1\|g\|_{j,\om}\delta_1^n
\end{equation}
where $\lambda_{j,n}(z)=\prod_{k=j}^{j+n-1}\lambda_k(z)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

