[Proposition 14 of arXiv:2604.22461, 'Large deviation principles for stationary solutions and invariant measures of a class of S'] Assume that $A^{\epsilon}$ and $B$ satisfy the conditions {\rm [A1- A5]}. For any $t_0 \in \R$, $T>t_0$ and $\xi \in H$, there is the unique solution $X^{\epsilon}_{t;t_0,\xi}$ of Eq. \eqref{eq: SPDE}, and it holds:
    \begin{description}
      \item[(i)] For any $0<\gamma \leq \frac{(1+\beta)\lambda_1 \gamma_0}{2} $, we have
    \begin{align}
        & \E \sup_{t \in [t_0,T]} \Big\{  e^{\gamma (t-t_0)} \| X^{\epsilon}_{t;t_0,\xi} \|_{H}^{2+\beta} + \gamma_0  \int_{t_0}^{t}  e^{\gamma (s-t_0)} \|X^{\epsilon}_{s;t_0,\xi}\|_{H}^{\beta} \|X^{\epsilon}_{s;t_0,\xi}\|_{V}^{2} \, \d s \Big\}  \nonumber \\
        & \quad \leq 2 e^{-\gamma(T-t_0)} \| \xi \|_{H}^{2+\beta} + \frac{(2+\beta) (C_{A,\rho,\epsilon} + (18+10\beta )  C_{B} \epsilon )}{\gamma}, \quad \quad \forall \, T \geq t_0.  
    \end{align}
      \item[(ii)]For any $0<\delta \leq \frac{ (1+\beta)\lambda_1 \gamma_{0}}{2(2+\beta)^2 C_{B} \epsilon}$, $X^{\epsilon}_{t;t_0,\xi}$ satisfies
    \begin{align}
        \E \Big[ \exp \Big\{  \delta \sup_{t \geq t_0} & \Big( \| X^{\epsilon}_{t;t_0,\xi}\|_{H}^{2+\beta} + \frac{\gamma_0}{2} \int_{t_0}^t \| X^{\epsilon}_{s;t_0,\xi} \|_{H}^{\beta} \| X^{\epsilon}_{s;t_0,\xi} \|_{V}^{2} \, \d s  \nonumber \\
         & \quad -  (1+\frac{\beta}{2}) \big( C_{A,\rho,\epsilon}+ \beta C_B \epsilon \big) (t-t_0) \Big) \Big\} \Big] \leq 2 e^{\delta \| \xi \|_{H}^{2+\beta}  }. 
    \end{align}
      \item[(iii)] For any $t_1 \geq t_0$, it satisfies the following uniform estimates
    \begin{align}
        \E  \exp \Big\{ \delta \big\{ \| X^{\epsilon}_{t_1;t_0,\xi}\|_{H}^{2+\beta} \big\} \Big\}  & \leq 2 \,  e^{\delta \big(\| \xi \|_{H}^{2+\beta} + (2+\beta) \frac{ C_{A,\rho,\epsilon}+ \beta C_B \epsilon   }{\lambda_1 \gamma_0} \big)} ;  \\
        \E \Big[ \exp \Big\{  \frac{\delta}{2} \sup_{t \geq t_1}  \big( \frac{\gamma_0}{2} \int_{t_1}^t \| X^{\epsilon}_{s;t_0,\xi} \|_{H}^{\beta} \| X^{\epsilon}_{s;t_0,\xi} \|_{V}^{2} \, \d s & - (1+\frac{\beta}{2}) \big( C_{A,\rho,\epsilon}+ \beta C_B \epsilon \big) (t-t_1) \big) \Big\} \Big]  \nonumber \\
        &  \leq 2 \, e^{\delta  \big( \frac{\| \xi \|_{H}^{2+\beta}}{2} + \frac{2+\beta}{2} \frac{ C_{A,\rho,\epsilon} + \beta C_{B} \epsilon  }{\lambda_1 \gamma_0} \big)}. 
    \end{align}
    \end{description}
    The above results imply that $X^{\epsilon}_{t;t_0,\xi} \in L^{2}(\Omega; \sC_{t_0})$.

