[Lemma conv_z of arXiv:2601.15223, 'Large time behaviour for a class of 2D and 3D stochastic non-Newtonian fluids of different'] For each $N\in\mathbb{N}$, suppose $\omega_\mathfrak{k},\omega_0\in\Omega_{N}$ are such that $d_{\Omega}(\omega_\mathfrak{k},\omega_0)\to0$ as $\mathfrak{k}\to+\infty$. Then, for each $\mathfrak{r}\in\mathbb{R}$ and $T\in\mathbb{R}^+$ ,
		\begin{align}
			\sup_{t\in[\mathfrak{r},\mathfrak{r}+T]}&\bigg[|y(\vartheta_{t}\omega_\mathfrak{k})-y(\vartheta_{t}\omega_0)|+|e^{ y(\vartheta_{t}\omega_\mathfrak{k})}-e^{ y(\vartheta_{t}\omega_0)}|\bigg]\to 0 \ \text{ as } \ \mathfrak{k}\to+\infty,\nonumber\\
			\sup_{\mathfrak{k}\in\mathbb{N}}\sup_{t\in[\mathfrak{r},\mathfrak{r}+T]}&|y(\vartheta_{t}\omega_\mathfrak{k})|\leq C(\mathfrak{r},T,\omega_0).
		\end{align}

