[Lem gaussian of arXiv:2510.23430, 'On the Martin boundary for discrete TASEP'] Let $\sigma>0$, $x_1, \dots, x_k\in\mathbb R$. Then
\begin{equation}
\int_{\mathbf i\mathbb R}\frac{dv_1}{2\pi\mathbf i}\dots\int_{\mathbf i\mathbb R}\frac{dv_k}{2\pi\mathbf i}\exp\left(\sum_{i=1}^k -\sigma x_iv_i+\frac{\sigma^2 v_i^2}{2}\right)\prod_{i<j}(v_i-v_j)=(2\pi)^{-\frac k2}\sigma^{-k(k+1)}\prod_{i=1}^ke^{-\frac{x_i^2}{2}}\prod_{i<j}(x_i-x_j).
\end{equation}

[Lem 29 of arXiv:2607.06242, 'Exponential mixing and Freidlin--Wentzell large deviation principle for Markov cocycles'] For $m$-a.e. $\sigma\in\Sigma$ and every $M>0$, the level set
  \begin{align*}
  K_M(\sigma)=\{E_{\Ac(\sigma)}\leq M\}
\end{align*}
  is compact in $X$.

