[Proposition 3 of arXiv:2608.30561, '\Large Informative Label Missingness in Multiclass Classification: Information Geometry an'] Assume that
\(\boldsymbol{A}_{\lambda\lambda}\) and
\(\boldsymbol{J}_{\lambda\lambda}
=
\boldsymbol{A}_{\lambda\lambda}
+
\boldsymbol{K}_{\lambda\lambda}\)
are nonsingular. Then the efficient Fisher information for
\(\boldsymbol{\beta}\) under informative partial classification is
\begin{equation}
\boldsymbol{J}_{\mathrm{eff}}(\boldsymbol{\beta})
=
\boldsymbol{A}_{\mathrm{eff}}(\boldsymbol{\beta})
+
\widetilde{\boldsymbol{K}}_{\beta\beta}
-
\widetilde{\boldsymbol{K}}_{\beta\lambda}
\boldsymbol{J}_{\lambda\lambda}^{-1}
\widetilde{\boldsymbol{K}}_{\lambda\beta}.

\end{equation}
Moreover,
\begin{equation}
\boldsymbol{C}_{K}
=
\widetilde{\boldsymbol{K}}_{\beta\lambda}
\boldsymbol{J}_{\lambda\lambda}^{-1}
\widetilde{\boldsymbol{K}}_{\lambda\beta}
\succeq
\boldsymbol{0}.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:KX-one-sided-walk-estimates of arXiv:2609.03532, 'Airy limit for the Jack process and topological expansion'] [Xu]

There exist constants $C,c>0$  
such that the following estimates hold for all sufficiently large
\(N\) and all \(L,H,R\in\mathbb Z_{\ge0}\).  Write
\[
  Z_L^{\rightarrow}(H):=Z_L(0,H),\qquad
  Z_L^{\leftarrow}(H):=Z_L(H,0),
\]
and, for any path of length $L$, write
$\max W:=\max_{0\leq t\leq L}W(t)$.  The forward bridge satisfies the estimate
\begin{align}
  &\sum_{W\in\mathcal W(0,H,L)}
      \operatorname{wt}(W)
      \mathbf 1_{\{\max W-H\geq R\}}
  \notag\\
  &\qquad\leq
  C\frac{H+1}{(L+1)^{3/2}}
  \exp\!\left\{-c\left(
    \frac{H^2}{L+H+1}
    +\frac{R^2}{L+1}\right)\right\}.

\end{align}
The reverse bridge satisfies the estimate
\begin{align}
  &\sum_{W\in\mathcal W(H,0,L)}
      \operatorname{wt}(W)
      \mathbf 1_{\{\max W-H\geq R\}}
  \notag\\
  &\qquad\leq
  \frac{C}{L+1}
  \exp\!\left\{-c\left(
    \frac{H^2}{L+1}
    +\frac{R^2}{L+1}\right)\right\}.

\end{align}
In both estimates above the event is empty when $R>L$.  Indeed, once the path reaches a height at least $H+R$, the Lukasiewicz feature
requires at least $R$ remaining steps to finish at height $H$ or below.
Finally, after summing the initial height of a bridge ending at zero,
\begin{align}
  \sum_{H\geq0}\sum_{W\in\mathcal W(H,0,L)}
      \operatorname{wt}(W)
      \mathbf 1_{\{\max W\geq R\}}
  &\leq
  C(L+1)^{-1/2}
  \exp\!\left\{-c\frac{R^2}{L+1}\right\},
  \\
  \sum_{W\in\mathcal W(0,0,L)}
      \operatorname{wt}(W)
      \mathbf 1_{\{\max W\geq R\}}
  &\leq
  C(L+1)^{-3/2}
  \exp\!\left\{-c\frac{R^2}{L+1}\right\}.

\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem exponential_c_k of arXiv:2606.15339, 'Uniform integrability of the distance to the nearest leaf in random trees'] Let $(\mathcal{T}_n)_{n\geq1}$ be a sequence of size-conditioned simply generated trees of type~I or~II. Then there are constants $C, c > 0$, depending only on the offspring distribution, such that
	\begin{align}
		c_k = \mathbf{P}(\partial(\hat{\mathcal{T}}) \geq k) \leq C e^{-ck}\,, \qquad k \geq 1\,.
	\end{align}
	More precisely, $c_k \leq (1 - p_0^2)^{k-1}$ in type~I and $c_k \leq m^{\,k-1}$ in type~II.

