[Proposition 71 (Growth of $k_i$) of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] There exists $c=c(\varepsilon)>0$ such that for all $n,i\ge 1$,
\begin{equation}
\widetilde{\p}_n\bigg( k_{i+1}> k_i\Big( 1+ \frac{2}{(\log n)^\alpha}\Big) \,\bigg|\, k_i\bigg) \mathbf{1}\left\{i<S,\,k_i < \frac{\varepsilon n}{16(\log n)^{2\alpha}}\right\}
\le \exp\Big(-\frac{c k_i}{(\log n)^{2\alpha}}\Big).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:pure-input of arXiv:2606.29557, 'Propagation of chaos for Belavkin equations beyond pure states'] Let Hypothesis~(hyp:perfect-efficiency-tensorization-purity of the paper) (1) hold.  
For $j\in[N]$, set
\begin{equation}
\rho_t^{N:(j)}
  :=
  \mathrm{Tr}_{[N]\setminus\{j\}}(\rho_t^N) \qquad \mbox{ and } \qquad  \alpha_{N,j}(t)
  :=
  1-\mathrm{Tr}\bigl(\rho_t^{N:(j)}\gamma_t^j\bigr).

\end{equation}
Then, for every $T>0$, there exists a constant $C_T<\infty$, independent
of $N$ and $j$, such that
\begin{equation}
  \sup_{0\le t\le T}
  \mathbb E\bigl[\alpha_{N,j}(t)\bigr]
  \le
  \frac{C_T}{\sqrt N}.

\end{equation}
Consequently, for every fixed $n\ge1$,
\begin{equation}
  \sup_{0\le t\le T}
  \mathbb E\left[
    \left\|
      \rho_t^{N:n}-\Gamma_t^n
    \right\|_1
  \right]
  \le
  2\sqrt{nC_T}\,N^{-1/4}.

\end{equation}

[Lemma lem:correlation_stopping of arXiv:2608.05089, 'Correlation decay in area-tilted line ensembles'] There is some $\lambda_0 > 1$ and $C, c > 0$ such that for all $\lambda \geqslant \lambda_0$
and all $k \in \mathbb{N}$, when $\mathbf{X}$ and $\mathbf{Y}$ are sampled independently we have
\begin{equation}
    \tau_\ell^{0,k} < 0 < \tau_r^{0,k}
    \qquad \text{and} \qquad
    \tau_\ell^{t,k} < t < \tau_r^{t,k}
\end{equation}
with probability at least $1 - C e^{-ct}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:admissible of arXiv:2608.26564, 'Real ideal points, Conway spheres, and left-orderable Dehn fillings'] An \emph{admissible real limiting datum} is a limiting gluing datum $\xi = (\chi_1, \chi_2)$ represented by irreducible homomorphisms $\rho_i: \pi_1(T_i) \to SL_2(\mathbb{R})$ such that, in the same-oriented strand variables,
\begin{equation}
	\rho_i(m_{i, 1}) = \rho_i(m_{i, 2}) = I \ \ \ \ \ \rho_i(m_{i, 3}) = \rho_i(m_{i, 4}) = P_i
\end{equation}
where $P_i$ is a noncentral parabolic of trace 2. Equivalently, in boundary variables, 
\begin{equation} \begin{array}{c|cccc} &\mu_{i,1}&\mu_{i,2}&\mu_{i,3}&\mu_{i,4}\\ \hline T_1&I&I&P_1^{-1}&P_1\\ T_2&I&I&P_2&P_2^{-1}. \end{array} \end{equation}

