body:
[Proposition prop:shearM of arXiv:2608.16915, 'Exact mean--covariance dynamics of the Weber field in the stochastic Lagrangian representa'] For $f_0\in L^2(\mathbb{T}^2)$ with zero mean, the field
\[
  u(t,x)=\bigl(e^{\nu t\Delta_\perp}f_0(x_2,x_3),\,0,\,0\bigr)
\]
is a global smooth solution of (equation eq:NS of the paper) for $t>0$, since $(u\cdot\nabla)u=0$. Its
mean displacement and mean deformation are
\begin{equation}
  \ell(t)=-t\,u(t),\qquad
  M(t)=I-t\,e_1\otimes\nabla_\perp e^{\nu t\Delta_\perp}f_0 ,
\end{equation}
and for every $0<\alpha<1$ and $\tau>0$,
\begin{equation}
  \sup_{t\ge\tau}\left\lVert M(t)-I\right\rVert_{C^\alpha}
  \le C_\alpha\,\nu^{-1-\alpha/2}\,\tau^{-\alpha/2}\,\left\lVert f_0\right\rVert_{L^2(\mathbb{T}^2)} .
\end{equation}

[Lem 17 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] For every $n \in \mathbb{N}_+$, it holds 
\begin{align} 
 \sup_{r \in [0,T]} \Bigg\{ \frac{1}{n} \sum_{x} \big[  \Theta(n) ( \mathbb{L}_n^{\gamma,s} H )( \tfrac{x + q_n^r }{n}  ) \big]^{2}  \Bigg\} \leq C(\gamma,H).
\end{align}
Moreover, if $H \in C_c^{2}(\mathbb{R})$, then the role of $C(\gamma,H)$ above is fulfilled by some constant $C(H)$ satisfying \eqref{Cinvshift}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 of arXiv:2604.22461, 'Large deviation principles for stationary solutions and invariant measures of a class of S'] Assume that {\rm [A1-A3]} hold. If $C_{\rho_2} < \lambda_1  \gamma_0$, then for any $0 \leq \epsilon \leq \epsilon_0 < \frac{\lambda_1 \gamma_0-C_{\rho_2}}{2 C_B + \lambda_1 L_B}$,
    \begin{equation} 
     \max \{ \| v\|_{H}^{\beta} ,1 \}  \big(   2 _{V^{\ast}}\<A^{\epsilon}(v)  , v\>_V + \epsilon  \, \| B(v) \|_2^2 +  \gamma_0 \|v\|_{V}^{2} \big)  \leq  C_{A,\rho,\epsilon} \leq C_{A, \rho},
    \end{equation}
    where
    \begin{align*}
      & C_{A, \rho,\epsilon}:= \max \Big\{ \frac{\|A^{\epsilon}(0)\|_{V^{\ast}}^2}{4 \delta(\epsilon)}, \frac{2}{2+\beta} \Big(\frac{\beta}{\lambda_1 (2+\beta)} \Big)^{\frac{\beta}{2}} \, \delta(\epsilon) \Big( \frac{ \|A^{\epsilon}(0)\|_{V^{\ast}}^2}{4 \delta(\epsilon)^2} \Big)^{1+\frac{\beta}{2}}   \Big\} + \epsilon C_{B}, \\
      & C_{A, \rho}:= \max \Big\{ \frac{\sup_{0 \leq \epsilon \leq \epsilon_0}\|A^{\epsilon}(0)\|_{V^{\ast}}^2}{4 \delta(\epsilon_0)}, \frac{2}{2+\beta} \Big(\frac{\beta}{\lambda_1 (2+\beta)} \Big)^{\frac{\beta}{2}} \, \delta(\epsilon_0) \Big( \frac{ \sup_{0 \leq \epsilon \leq \epsilon_0}\|A^{\epsilon}(0)\|_{V^{\ast}}^2}{4 \delta(\epsilon_0)^2} \Big)^{1+\frac{\beta}{2}}   \Big\} + \epsilon_0 C_{B} ; \\
& \delta(\epsilon) :=\frac{\lambda_1 \gamma_0- C_{\rho_2} -2 \epsilon \, C_B - \epsilon \, \lambda_1 L_B}{2 \lambda_1}  \geq \delta(\epsilon_0)>0.
\end{align*}
It implies that the condition {\rm [A5]} holds.

