body:
[Lemma lem:one-large-position of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] If $m\ge40$, then
\begin{equation}
  \kappa\le\floor*{\frac{3m}{2}}+1
  +\mu(\kappa)+2\mu(\floor{\kappa/2}).
\end{equation}
In particular,
\begin{equation}
  e=\kappa-1\le3m-6.
\end{equation}

[Definition 8 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] We introduce the set of noise types $\tilde{\mathfrak{L}}_- = \{ \<b0>, \<p0>, \<s(1)0>, \<bs(2)0>, \<ps(2)0> \}$ (with homogeneities $-3/2 - \kappa, -3/2 - \kappa, -1 - \kappa, -3/2 - 2\kappa, -3/2 - 2\kappa$ respectively) and kernel types $\tilde{\mathfrak{L}}_+ = \{ \<bk>, \<pk>, \<k> \}$. We let $\hat{\mfT}$ be the (reduced) regularity structure associated to the (completion of) the subcritical rule
	\begin{align*}
		R( \<bk> ) &= \{ (\<dbk>, \<dbk>), (\<dbk>), (\<b0>), () \},
		\\
		R( \<pk> ) &= \{ (\<dpk>, \<dpk>), (\<dpk>), (\<p0>), () \},
		\\
		R( \<k> ) &= \{ (\<dk>, \<dbk>), (\<dk>), (\<dbk>), (\<dk>, \<dpk>), (\<dpk>), (\<s(1)0>, \<dbk>), (\<s(1)0>), (\<s(1)0>, \<dpk>), (\<bs(2)0>), (\<ps(2)0>), ()\}
	\end{align*}
	where we have used the convention that thick lines such as $\<k>$ represent kernels carrying a vanishing derivative decoration whilst thin lines such as $\<dk>$ represent edges carrying a spatial derivative.

	We let $\tilde{\mfT}$ be the substructure generated by those trees in the natural basis for $\hat{\mfT}$ which do not contain either of 
	\begin{align*}
		\<s(1)b1>, \qquad \<s(1)p1>
	\end{align*}
	as subtrees. We equip this with the structure group described in Appendix~\ref{app:degree_shift} which can be identified with the elements of the character group of $\hat{\mcT}_+$ which vanish on trees containing one of the two trees excluded as subtrees above.

[Proposition 9 of arXiv:2512.08745, 'Variance strikes back: sub-game--perfect Nash equilibria in time‑inconsistent $N$‑player g'] We suppose that {\rm\Cref{assumption:regularityForNecessityZero}.\ref{differentiableG}} and {\rm\Cref{assumption:genIsaacsZero}} are satisfied. Let $(Y,Z,M^{\star},Z^{m,\star})$ be a solution to the following system of {\rm BSDEs}
\begin{align*}
\notag Y_t &= g\big(X^1_{\cdot \land T}\big) + G\big(\varphi(X^1_{\cdot \land T})\big)\big) + \int_t^T H^0_s\big(X^1_{\cdot \land s},Z_t,M^{\star}_s,Z^{m,\star}_s\big) \d s - \int_t^T Z_s \cdot \d W_s^1, \; t \in [0,T], \; \P\text{\rm--a.s.}, \\
M^{\star}_t &= \varphi\big(X^1_{\cdot \land T}\big) + \int_t^T Z^{m,\star}_s \cdot b_s\big(X^1_{\cdot \land s},\hat\alpha^1_s,\hat\alpha^2_s\big) \d s - \int_t^T Z^{m,\star}_s \cdot \d W_s^1, \; t \in [0,T], \; \P\text{\rm--a.s.},
\end{align*}
and satisfy, for some $p \geq 1$, the following integrability condition
\begin{align*}
&\sup_{\balpha \in \cA^\smalltext{2}_\smalltext{1}} \E^{\P^{\smalltext{\balpha}}} \Bigg[ \sup_{t \in [0,T]} |Y_t|^p + \bigg(\int_0^T \|{Z}_t\|^2 \d t\bigg)^\frac{p}{2} \Bigg] +\esssup_{\balpha \in \cA^\smalltext{2}_\smalltext{1}} \Bigg\{\sup_{t \in [0,T]} | M^{\star}_t| + \sup_{\tau \in \cT_{0,T}} \E^{\P^{\smalltext{\balpha}\smalltext{,}\smalltext{\tau}}_{\smalltext{\cdot}}} \bigg[ \int_\tau^T \|Z^{m,\star}_t\|^2 \d t \bigg] \Bigg\} < +\infty.
\end{align*}
If we define $\hat\balpha_t \coloneqq \big(\mathfrak{a}^{1,0}(t,X^1_{\cdot \land t},Z_t),\mathfrak{a}^{2,0}(t,X^1_{\cdot \land t},Z_t)\big)$, $t \in [0,T]$, it holds that $\hat\balpha \in \mathcal{N}\!\mathcal{A}_{s,0}$, and $J(t,\cdot,\hat\balpha) = Y_t$, $\P\text{\rm--a.s.}$, $t\in [0,T]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma cont of arXiv:2411.04157, 'Stochastic homogenization of dynamical discrete optimal transport'] Let $m\in W^{1,1}((0,T);{\mathcal P}(\mathcal X))$ and $J\in L^1((0,T);\mathbb{R}^{\mathcal E}_a)$ solve (equation eq: dcont of the paper). 
    Then $(m,\iota J)$ solves 
    \begin{align}
    \partial_tm+\dive \iota J=0 \quad \text{ in }\mathcal{D}'((0,T)\times \mathbb{R}^n).
\end{align}

