body:
[Proposition p:averaging set counterexample of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Define $B_{m, p}:=[0, 1-m^{-p}]\cup [m, m+m^{-p}]$ for $m\in\N, p>0$. Then, for every $n\in\N$, there is an $m\in\N$ such that there exists no averaging set of $B_{m, 1}$ of size less than $n$ and degree $1$ if we require the points to lie in $B_m$. If we allow the points of the averaging set to lie in $\R$, then for every $n\in\N$, there is an $m\in\N$ such that there exists no averaging set of $B_{m, 2}$ of size less than $n$ and degree $3$. Hence, in the previous Proposition~(p:averaging set bound improved of the paper), we cannot drop the assumption that $\frac{\lambda_d(\conv(B))}{\lambda_d(B)}\leq C$ for some $C>0$. The same holds for $\frac{\diam(B)^d}{\lambda_d(B)}\leq C$ in Theorem~(t:averaging set bound of the paper).
    \begin{proof}
        Let $n,m\in\N$, and $x_1,...,x_n\in B_{m,1}$. Assume that $x_1,...,x_n$ form an averaging set of $B_{m,1}$ of degree $1$. Then,
        \begin{equation*}
            \frac{1}{n} \sum_{k=1}^n x_k = \int_{B_{m,1}} x\, dx = \frac{3}{2}-\frac{1}{m}+\frac{1}{m^2} > 1-\frac{1}{m}.
        \end{equation*}
        Hence, $x_k\in[m,m+\frac{1}{m}]$ for at least one $k\in\{1,...,n\}$. This fact, together with $x_k\geq0$ for $k\in\{1,...,n\}$ and the previous bound, implies that
        \begin{equation*}
            \frac{3}{2} \geq\frac{1}{n} \sum_{k=1}^n x_k \geq \frac{m}{n}.
        \end{equation*}
        In total, we obtain that $n\geq \frac{2}{3}m$, which proves the first assertion. 

        Now, we instead assume that $x_1,...,x_n$ form an averaging set of $B_{m,2}$ of degree $3$, and that $x_1,...,x_n\in\R$ are not restricted to $B$. Then
        \begin{equation*}
            \frac{1}{n} \sum_{k=1}^n x_k^3 = \int_{B_{m,2}} x^3\, dx = m + \frac{1}{4} + \frac{1}{2m^2} + \frac{3}{2m^4} +\frac{1}{m^5} - \frac{1}{m^6} +\frac{1}{2m^8} \geq m.
        \end{equation*}
        Hence, $|x_k|\geq \sqrt[3]{m}$ for at least one $k\in\{1,...,n\}$. Therefore,
        \begin{equation*}
            \frac{m^\frac{2}{3}}{n} \leq \frac{1}{n} \sum_{k=1}^n x_k^2 = \int_{B_{m,2}} x^2\, dx = \frac{4}{3} - \frac{1}{m^2} +\frac{1}{m^3} + \frac{1}{m^4} \leq \frac{7}{3}.
        \end{equation*}
        In total, we obtain that $n\geq \frac{3}{7}m^\frac{2}{3}$, which proves the second assertion.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

