body:
[Theorem 15 of arXiv:2608.29152, 'Uniform Statistical Convergence of Empirical Sinkhorn Potentials\\ with Exponential and Po'] For a model in $\mathfrak M_\eps$, let $\mathfrak d_*= \max(\mathfrak d_{\cX},\mathfrak d_{\cY})$ and $D_*=\max(D_{\cX},D_{\cY})$.
Define the geometric complexity term:
\begin{equation}
 \Lambda_{\eps,\delta} := 1+ \sqrt{\mathfrak d_* \left\{ 1+\log(1+2D_*L_0\eps^{-q}) \right\}} +\sqrt{\log(4/\delta)}. 
\end{equation}
There exists a universal numerical constant $C$ such that, for any $\delta\in(0,1)$, with probability at least $1-\delta$, we have
\begin{equation}
 d_\infty([\widehat f_{\eps,n}],[f_\eps]) \le C e^{5A_0} \eps^{\,1-5\gamma_{\mathrm{osc}}} \Lambda_{\eps,\delta} n^{-1/2}.
\end{equation} 
If both potentials are anchored at the same point $x^\circ$, the standard sup-norm error is at most double this bound. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition Prop: ISP of arXiv:2609.02213, 'Invariant subspaces for free linearizations of Lipschitz maps'] Let $M$ be an infinite separable metric space, let $f\in \Lip(M,M)$ and let $e\in M$. If one of the following assumptions is satisfied, then $T_{f,e}$ has a non-trivial invariant subspace:
		\begin{enumerate}[$(i)$]
			\item $f(M)$ is not dense in $M$;
			\item $f$ has a non-trivial and non-dense orbit;
			\item there exist $a\in M$ and $r>0$ such that $f(a)=a$, $\Lip\bigl(f|_{\overline B(a,r)}\bigr)\leq 1$,
			and $\{a\}\subsetneq \overline B(a,r)\subsetneq M$;
			\item there exist $a\in M$ and $r>0$ such that $f(a)=a$, $M\setminus B(a,r)\neq \emptyset$, and $d(f(y),a)\geq d(y,a)$ for all $y\in M\setminus B(a,r)$;
			\item $T_{f,e}$ is not injective. In particular, this holds if $f$ is not injective.
		\end{enumerate}

[Lemma main_lemma_com of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] Let $H$ and $\widetilde H$ be two matrices satisfying (main_assm of the paper). Suppose they satisfy the following moment-matching conditions: for $i,j\in \mathcal I$ and integers $l,l'\ge 0$,  

\begin{equation}
\mathbb{E} (H_{ij})^l (H^*_{ij})^{l'} - \mathbb{E} (\widetilde H_{ij})^l (\widetilde H^*_{ij})^{l'}=0 \ \ \text{for} \ \ l+l'\le 3, 
\end{equation}
and there exists a constant $\delta \in (0,1/2)$ such that 
\begin{equation}
\left|\mathbb{E} (H_{ij})^l (H^*_{ij})^{l'} - \mathbb{E} (\widetilde H_{ij})^l (\widetilde H^*_{ij})^{l'}\right| \lesssim N^{-2-\delta}  \ \ \text{for} \ \ l+l'= 4. 
\end{equation}
Then, for any $z\in \mathbf D(\tau)$, $z_1,z_2\in \{z, \overline z\}$, and $a,b \in \llbracket D\rrbracket$, we have
\begin{equation}
\mathbb E \langle G_1E_{a}G_2E_{b}\rangle-\mathbb E \langle \widetilde G_1E_{a}\widetilde G_2E_{b}\rangle\prec N^{-1-\delta}\eta^{-2},
\end{equation}
where $\widetilde G_i \equiv G(z_i,\widetilde H,\Lambda)$, $i\in \{1,2\}$, denote the Green's functions of $\widetilde H$.

