[Corollary 250 of arXiv:2601.16377, '2601.16377'] Assume that $\pi_{\boldsymbol{v}}^{\circ}$ is a bijection, that $\boldsymbol{v}$ has bipartite $\mathfrak{G}$-orbit and $\textbf{\text{\foreignlanguage{russian}{B}}} = \textnormal{\textbf{Id}} - \boldsymbol{1}$. Then, the Green function on $\Sigma_{\boldsymbol{v}}^{\textnormal{half}}$ with Dirichlet boundary conditions on $\partial\Sigma_{\boldsymbol{v}}^{\textnormal{half}}$ is
\begin{equation}

\textnormal{Gr}(p_1,p_2) = -\frac{1}{4\pi}\left(\textnormal{gr}_{\boldsymbol{v}}(p_1,p_2) + 2\log\bigg|\frac{z_1 - z_2}{z_1 - z_2^*}\bigg|\right).
\end{equation}

[Lemma Lemma_localized_approx of arXiv:2608.30548, 'Finite speed of propagation and waiting time phenomena for stochastic porous media equatio'] Let $\zeta\in C^2(\mathbb{T}^d)$, $p\in [1,\infty)$ and $\tau \le T$ a stopping time. Then it holds
\begin{align}\begin{split}

&
 \mathbb{E}\biggl[\biggl(
        \sup_{t\le \tau} \int_{\mathbb{T}^d} \zeta^2 u_{\kappa,l}^{\alpha+1 }\,\mathrm{d} x \,+\, \int_0^\tau \int_{\mathbb{T}^d}   \zeta^2 u_{\kappa,l}^{\alpha+m-2}|\nabla u_{\kappa,l}|^2\,\mathrm{d} x\, \mathrm{d} t \,+\,\kappa \int_0^\tau \int_{\mathbb{T}^d}\zeta^2 u_{\kappa,l}^{\alpha-1}|\nabla u_{\kappa,l}|^2 \,\mathrm{d} x\, \mathrm{d} t\biggr)^p
        \biggr]^{1/p}
        \\&\quad \lesssim_{(\alpha,m,n,p,\phi,\psi)} \,\int_{\mathbb{T}^d} \zeta^2 u_0^{\alpha+1 }\,\mathrm{d} x \,+\, \mathbb{E} \biggl[\biggl(\int_0^\tau \int_{\mathbb{T}^d} u_{\kappa,l}^{\alpha+m}|\nabla \zeta|^2 \,\mathrm{d} x\,\mathrm{d} t \,+\,
        \kappa\int_0^\tau  \int_{\mathbb{T}^d}u_{\kappa,l}^{\alpha+1}|\nabla \zeta|^2\,\mathrm{d} x\, \mathrm{d} t\biggr)^p
        \biggr]^{1/p}
        \\&\qquad +\, \mathbb{E}\biggl[\biggl(
        \int_0^\tau 
        \int_{\mathbb{T}^d} 
        u_{\kappa,l}^{\alpha+2n-1} \bigl(|\zeta \Delta  \zeta| + |\nabla \zeta|^2 +\zeta^2 \bigr)
        \,\mathrm{d} x
        \,\mathrm{d} t \biggr)^p
        \biggr]^{1/p}
        \\&\qquad +\, \frac{1}{l^{2n-2}}\mathbb{E}\biggl[\biggl(
        \int_0^\tau 
        \int_{\mathbb{T}^d} 
        u_{\kappa,l}^{\alpha+1} \bigl(|\zeta \Delta  \zeta | + |\nabla \zeta|^2 +\zeta^2  \bigr)
        \,\mathrm{d} x
        \,\mathrm{d} t \biggr)^p
        \biggr]^{1/p}
\end{split}
\end{align}
for any weak solution $   u_{\kappa,l} $ to (equation Eq_viscous_reg of the paper) in the sense of Definition (def_weak_sol of the paper) with initial value $u_0$ {satisfying (equation assumption_m_plus_one of the paper)}.

[Lemma 32 of arXiv:2607.23791, 'Precise cover times for branching random walks on Hamming graphs: (iterated) logarithmic c'] Fix $c,w,\lambda,\delta>0$ and choose $C_{\rm shell}$ so that
$\lambda\delta C_{\rm shell}>2$.  Then
\begin{equation}
 \sum_{\ell>C_{\rm shell}\log\log d}^{d}
 \binom d\ell\exp\!\left(-cw e^{\lambda\delta\ell}\right)=o(1).
\end{equation}

