[Lemma lem:fisherrao of arXiv:2411.16366, 'Connections between sequential Bayesian inference and evolutionary dynamics'] The pure replicator equation (equation eq:norm_repmut of the paper) with $\mathcal L^\star = 0$ and with frequency dependent but time-independent fitness $f_t(x,z) = f(x,z)$ performs a gradient flow of the average fitness functional $ \mathcal F(p): \mathcal{P}(\mathbb{R}^d) \rightarrow \mathbb{R}$ 
	\begin{align}

		\mathcal F(p) = -\frac{1}{2} \iint f(x,z) p(z) p(x) d z d x
	\end{align}
	with respect to the Fisher-Rao metric. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem prop:uniform-time-averaged-w1 of arXiv:2607.00149, '\bf Uniform-in-time Propagation-of-Chaos for\\ Stein Variational Gradient Descent'] Let Assumption~(ass:w1-normalized-matern of the paper) hold.  Recall the constant $c_0$ from Lemma~(lem:finite-time-w1 of the paper). Let $$\gamma := (3(1+7d/6+2\nu))^{-1}.$$ Then, there exists a finite constant $C>0$ such that, for any $\delta>0$ and all sufficiently large $N$,
\begin{equation}
\sup_{T>0}
\mathbb E\,\left[W_1\bigl(\overline\mu_T^N,\overline\mu_T\bigr)\, \mathbf{1}_{\{\int \|x\|^2 \mu^N_0(dx) \le R\}}\right]
\le C N^{-\beta}\exp\{c_0(1+R)(\log N)^{c_0\delta}\} + C(\delta\log\log N)^{-\gamma/2}.
\end{equation}
Consequently,
\begin{equation}
    \lim_{M \to \infty} \, \limsup_{N \to \infty}\,\sup_{T>0}\mathbb{P}\left[W_1\bigl(\overline\mu_T^N,\overline\mu_T\bigr) \ge M (\log \log N)^{-\gamma/2}\right] = 0.
\end{equation}
Moreover, suppose that the empirical initial second moments satisfy the uniform sub-Gaussian bound
\begin{equation}
R_N:=\int_{\mathbb R^d}|x|^2\,\mu_0^N(dx),
\qquad
\sup_{N\ge1}\mathbb E\exp\{\lambda R_N^2\}<\infty
\end{equation}
for some \(\lambda>0\). Then there exists \(C<\infty\) such that, for all sufficiently large \(N\),
\begin{equation}
\sup_{T>0}
\mathbb E\,W_1(\overline\mu_T^N,\overline\mu_T)
\le
C(\log\log N)^{-\gamma/2}.
\end{equation}

[Prop 64 (Bounds for Uniform integrability) of arXiv:2510.22155, 'Random walks in space-time random media in all spatial dimensions: the full subcritical fl'] Fix $f:I\to \mathbb R$ of exponential decay at infinity.  
\begin{enumerate}


\item 
We have a bound uniform over all $N\ge 1$, all initial conditions $   a_1,   a_2\in I$ and all $  {\boldsymbol{v}}$ in some neighborhood of the origin of $\mathbb R^d$:
\begin{multline}
    \left| N^{\frac{d-2}{2}}\sum_{s=0}^{Nt}\frac1{m!} \mathbf E^{(  {\boldsymbol{v}},2)}_{(   a_1,   a_2)} \bigg[ \bigg(\sum_{r=0}^{s-1}\boldsymbol u_{  {\boldsymbol{v}}}(   R^1_{r}-   R^2_{r})\bigg)^m  \phi \big(N^{-1/2} (   R^1_{s} - N^{-1}   d_Ns)\big)\cdot f(    R^1_{s}-   R^2_{s})\bigg]\right| \\\leq 
    \begin{cases}
      C^m \|\phi\|_{L^\infty} |  {\boldsymbol{v}}|^{2pm}\frac{(Nt)^{\frac{m}{2}}}{(m/2)!} & d=1  \\
      C^m \|\phi\|_{L^\infty}|  {\boldsymbol{v}}|^{2pm}  (\log Nt)^{2pm} \left[ 1+\big|\log \left(\frac{Nt}{  1+|a_1-a_2|^2}\right)\big|\right]  & d=2\\
      C^m \|\phi\|_{L^\infty}  |  {\boldsymbol{v}}|^{2pm}  \big(N^{-1/2} (1+|a_1-a_2|)\big)^{2-d} & d\ge 3\\
    \end{cases}
\end{multline}
Here $C$ is an absolute constant not depending on $v,t,m,\phi, a_1,a_2$.

\item Summing \eqref{geombound} over $m\in\mathbb Z_{\ge 0}$, we have a bound uniform over all $N\ge 1$, all initial conditions $   a_1,   a_2\in I$ and all $  {\boldsymbol{v}}$ in some neighborhood of the origin of $\mathbb R^d$:
\begin{multline}
\left| N^{\frac{d-2}{2}}\sum_{s=0}^{Nt} \mathbf E^{(  {\boldsymbol{v}},2)}_{(   a_1,   a_2)} \bigg[ e^{\sum_{r=0}^{s-1}\boldsymbol u_{  {\boldsymbol{v}}}(   R^1_{r}-   R^2_{r})}  \phi \big(N^{-1/2} (   R^1_{s} - N^{-1}   d_Ns)\big)\cdot f(    R^1_{s}-   R^2_{s})\bigg]\right| \\\leq 
    \begin{cases}
      C\|\phi\|_{L^\infty} e^{N |  {\boldsymbol{v}}|^{4p} t} & d=1  \\
      \frac{C\|\phi\|_{L^\infty}}{1-C|  {\boldsymbol{v}}|^{2p}\log Nt}   \left[ 1+\big|\log \left(\frac{Nt}{  1+|a_1-a_2|^2}\right)\big|\right] & d=2\\
     \frac{C\|\phi\|_{L^\infty}}{1-C|  {\boldsymbol{v}}|^{2p}}  \left(N^{-1/2} (1+|a_1-a_2|)\right)^{2-d}  & d\ge 3\\
      \end{cases}
\end{multline}
The right side should be understood to be infinite if the denominator is non-positive. Here $C$ is an absolute constant not depending on $v,t,m,\phi, a_1,a_2$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:wishart of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Let \(M\le N\) and  $\alpha = {M}/{N}$ where $M$ may depend on $N$, define   
\begin{equation} 
H_N \;=\; \Sigma_N \circ W_N,
\end{equation} as an inhomogeneous Wishart  matrix  and the corresponding additive perturbation (namely, signal-plus-noise matrices)   \begin{equation}
X_N \;=\; (H_N + A_N)\,(H_N + A_N)^*.
\end{equation}
where \(W_N=(W_{ij})\) is an \(M\times N\) random matrix with real or complex   entries  and \(\Sigma_N=(\sigma_{ij})\) is a deterministic  \(M\times N\)  matrix  with nonnegative entries. 
Precisely, the following assumptions hold:

\begin{enumerate}[leftmargin=*,label=(C\arabic*)]
  \item \textbf{(Entry moment)}  
 The entries $\{W_{ij}\}_{i,j=1}^N$ are independent, symmetric, and satisfy
 \begin{equation}
      \begin{cases}
       \mathbb{E}[W_{ij}^2]=1, & \text{real 
        case},\\
        \mathbb{E}[|W_{ij}|^2]=1,\;\mathbb{E}[W_{ij}^2]=0, & \text{complex 
        case}.
      \end{cases}
    \end{equation} 
    and for some \(\theta\ge1\) and all integers \(k\ge2\),
    \begin{equation}
      \mathbb{E}[|W_{ij}|^{2k}]
      \;\le\;
      \theta^{\,k-1}(2k-1)!!,
    \end{equation}
  where   \(\theta=\theta_N\to\infty\)  may be allowed  if needed.

  \item \textbf{(Variance profile)}  
    The profile matrix \(\Sigma_N=(\sigma_{ij})\) satisfies
    \begin{equation}
      \sum_{j=1}^N \sigma_{ij}^2 = 1
      \quad(\forall\,i\in[M]),
      \qquad
      \sum_{i=1}^M \sigma_{ij}^2 = \alpha
      \quad(\forall\,j\in[N]).
    \end{equation}
    Equivalently, the bipartite transition matrix on \(S=[M]\sqcup[N]\) is
    \begin{equation}
      P_{S}
      = \begin{pmatrix}
          0 & (\sigma_{ij}^2)_{M\times N} \\
          \alpha^{-1}(\sigma_{ij}^2)_{N\times M}^T & 0
        \end{pmatrix}.
    \end{equation}

  \item \textbf{(Rank-\(r\) perturbation)}  
    The deterministic matrix \(A_N\) admits a decomposition
\begin{equation}
    A_N = Q_1\,\Lambda\,Q_2^*, 
    \quad 
    \Lambda = \big( \mathrm{diag}(a_1,\dots,a_r, \underbrace{0,\dots,0}_{M-r}), \; 0_{M \times (N-M)} \big),
\end{equation}
where \(Q_1\) and \(Q_2\) are orthogonal (or unitary) matrices of size \(M\) and \(N\), respectively, and \(\underbrace{0,\dots,0}_{M-r}\) denotes the \(M-r\) zeros in the diagonal block.
     Moreover, for some fixed $\tau>0$, 
    \begin{equation}
      \|A_N\|_{\mathrm{op}}
      \;\le\;
      \sqrt{\alpha} \;+\;\tau\,N^{-1/3}.
    \end{equation}
\end{enumerate}
When  \(W_N\) has i.i.d.\ Gaussian entries,   the resulting model is denoted  by \(\widetilde X_N\) with \(\beta=1,2\).

[Proposition eq:diamond_simplified of arXiv:2604.22528, 'Malliavin calculus for signatures with applications to finance'] If ${\color{NavyBlue}{\mathbf{i}}}, {\color{NavyBlue}{\mathbf{k}}} \in A$ and $\bm{\ell}, \bm{\ell}' \in \TA[d+1]$, then the diamond product $\diamond^{{\color{NavyBlue}{\mathbf{i}}}, {\color{NavyBlue}{\mathbf{i}}}}_{{\color{NavyBlue}{\mathbf{k}}}}$ can be written in carré du champ form:
\begin{equation}
    \bm{\ell} \diamond^{{\color{NavyBlue}{\mathbf{i}}}, {\color{NavyBlue}{\mathbf{i}}}}_{{\color{NavyBlue}{\mathbf{k}}}} \bm{\ell}'
    = \dfrac{1}{2}\left({\bf \Psi}^{{\color{NavyBlue}{\mathbf{ii}}}}_{{\color{NavyBlue}{\mathbf{k}}}}(\bm{\ell}\mathrel{\sqcup \mkern -3mu \sqcup}\bm{\ell}') - {\bf \Psi}^{{\color{NavyBlue}{\mathbf{ii}}}}_{{\color{NavyBlue}{\mathbf{k}}}}(\bm{\ell})\mathrel{\sqcup \mkern -3mu \sqcup}\bm{\ell}' - \bm{\ell}\mathrel{\sqcup \mkern -3mu \sqcup}{\bf \Psi}^{{\color{NavyBlue}{\mathbf{ii}}}}_{{\color{NavyBlue}{\mathbf{k}}}}(\bm{\ell}')\right).
\end{equation}
In particular, we have
\begin{equation}
    \bm{\ell} \diamond \bm{\ell}'
    = \dfrac{1}{2}\sum_{i=1}^d\left({\bf \Psi}^{{\color{NavyBlue}{\mathbf{ii}}}}_{{\color{NavyBlue}{\mathbf{0}}}}(\bm{\ell}\mathrel{\sqcup \mkern -3mu \sqcup}\bm{\ell}') - {\bf \Psi}^{{\color{NavyBlue}{\mathbf{ii}}}}_{{\color{NavyBlue}{\mathbf{0}}}}(\bm{\ell})\mathrel{\sqcup \mkern -3mu \sqcup}\bm{\ell}' - \bm{\ell}\mathrel{\sqcup \mkern -3mu \sqcup}{\bf \Psi}^{{\color{NavyBlue}{\mathbf{ii}}}}_{{\color{NavyBlue}{\mathbf{0}}}}(\bm{\ell}')\right).
\end{equation}

[Lemma untied-raw-moment-expansion of arXiv:2609.03858, 'High-Dimensional Learning Dynamics of \\ Attention-Indexed Models'] Under the conditions of Theorem (theo:untied-SGD of the paper), let \(J\) be a
stopping time satisfying (equation eq:stopping-time of the paper). Fix a finite word $\alpha=(Z_1,\ldots,Z_w)\in\mathscr Z^w$, and let \(k_i\) denote the index carried by the letter \(Z_i\). Then, uniformly on \(\{n<J\}\),
\begin{equation}
\mu_\alpha^{(n+1)}-\mu_\alpha^{(n)}=\frac{\alpha_d}{d}
[\mathcal V_{\mathrm{raw}}^{(d,n)}]_\alpha+\alpha_d\eta_\alpha^{(n)}+R_\alpha^{(n)},

\end{equation}
where
\begin{equation}
\eta_\alpha^{(n)}:=\sum_{\substack{i=1\\k_i\in\mathcal K}}^w
\frac1d{\rm Tr}\left[Z_1^{(n)}\cdots Z_{i-1}^{(n)}
\mathscr N_{k_i}^{(n)}(Z_i)Z_{i+1}^{(n)}\cdots Z_w^{(n)}\right]

\end{equation}
is a martingale difference: $\mathbb E_n[\eta_\alpha^{(n)}]=0$.
Moreover, for every fixed word \(\alpha\), there exists
\(C_\alpha<\infty\), independent of \(d\) and \(n\), such that
\begin{equation}
\mathbf 1_{\{n<J\}}\mathbb E_n\left[
|\eta_\alpha^{(n)}|^2\right]\le\frac{C_\alpha}{d},

\end{equation}
and
\begin{equation}
\mathbf 1_{\{n<J\}}\mathbb E_n\left[|R_\alpha^{(n)}|
\right]\le C_\alpha\left[(1+\gamma)^2\alpha_d^2+\frac{\alpha_d}{d^{3/2}}\right].

\end{equation}

