body:
[Cor 62 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Let $\kappa,\;E,\;E_1,$ and $E_2$ be in \cref{hkest}, and $x\in F,\;x_n\in F_n$ be points satisfying
\begin{align*}
  h:=d_{\rm{H}}(F,F_n)^{\kappa}+d_{\BL^{\kappa}}(\mu,\mu_n)+d(x,x_n)\leq \frac{1}{4}.
\end{align*}
Then, for any $t>0$ and $f\in \BL^{\kappa}$,
it holds that
\begin{align*}
  |P_tf(x)-P_t^nf(x_n)|\lesssim 
  \begin{dcases}
    \|f\|_{\BL^{\kappa}}h^E, & \text{if the assumption $\rm{(A1)}$ or $\rm{(A2)}$ holds.}\\
    \|f\|_{\BL^{\kappa}}h^{E_1}(\log (1/h))^{E_2}, & \text{if the assumption $\rm{(A3)}$ holds.}
  \end{dcases}
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition PropMartingaleProperty of arXiv:2411.12522, 'Canonical insurance models: stochastic equations and comparison theorems'] Let $Y$ be a jointly measurable and $\mathcal{F}^-$-adapted process such that 
	\begin{align*}
		\mathbb{E}_{s}^i\bigg[\int_{(s,t]} |Y(u)|  I^j(u-) \Lambda^{jk} (\mathrm{d} u)\bigg] < \infty.
	\end{align*}
	Then we have
	\begin{align*}
		\mathbb{E}_{s}^i\bigg[\int_{(s,t]} Y(u) N^{jk} (\mathrm{d} u)\bigg]=\mathbb{E}^i_{s}\bigg[ \int_{(s,t ]} Y(u) I^j(u-) \Lambda^{jk} (\mathrm{d} u)\bigg]
	\end{align*}
	for $0 \leq s < t < \infty$ and $ i,j,k \in \mathcal{Z}$ with $j \neq k$.

