body:
[Definition 35 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] For $\zeta \in [0, \zeta_0)$ we write
	\begin{align*}
		E^\zeta_\vartheta = \{(Z, \boldsymbol{\psi}, \mcV) \in \cM_{\mathrm{adm}}(\tilde{\mfT}^\zeta) \times (C^{\vartheta - N\zeta})^3 \times \mathcal{D}^{3/2 + 2 \kappa - N\zeta, - \kappa - N\zeta} ({\tilde \mfT^\zeta_{\ge - 2\kappa}}) \},
	\end{align*}
	which we equip with the metric
	\begin{align*}
		d_{E^\zeta_\vartheta}&((Z, \boldsymbol{\psi}, \mcV), (\bar{Z}, \bar{\boldsymbol{\psi}}, \bar{\mcV})) \\
		&= \| Z; \bar{Z} \|^{(\zeta)}_{2+2\kappa; \mathcal{O}_T} + \| \boldsymbol{\psi} - \bar{\boldsymbol{\psi}} \|_{(C^{\vartheta - N\zeta})^3} + \| \mcV; \bar{\mcV} \|^{(\zeta)}_{3/2+2\kappa - N\zeta, -\kappa - N\zeta; \mathcal{O}_T}\;,
	\end{align*}
	with the dependence of this metric on the fixed terminal time $T$ suppressed.\\
	Furthermore, given $T > 0$, we define $E^\zeta_{\vartheta, T} \subset E^\zeta_\vartheta$ by
	$$E^\zeta_{\vartheta, T} = \{(Z, \boldsymbol{\psi}, \mcV) \in E^\zeta_\vartheta: \text{ there exists a unique solution to \eqref{eq: tct_sys} in } \mathcal{D}^{(\zeta)}_{T}(\vartheta; Z) \},$$
	where for $\zeta > 0$ all operations in \eqref{eq: tct_sys} are understood with respect to the grading $|\cdot|_\fs^{(\zeta)}$, with the truncation exponents lowered by $N\zeta$.

[Prop 20 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $0<\A{1},\A{2}\leq 1$ be such that $N^{-1}\ll  \pr{\A{1}\A{2}}^{1/2}$ and let $f\in S(m,\A{1},\A{2})$. Then,  
    \begin{equation*}
        \mathrm{tr}\pr{f_{N,\A{1},\A{2}}}=\pr{N\A{1}^{1/2}\A{2}^{1/2}}^d\int_{\mc{T}_{\A{1},\A{2}}}f(x,\xi)dxd\xi+r_N
    \end{equation*}
    where, for all $k\in \N$, 
    \begin{equation*}
        r_N=\mc{O}_k(1)N^{d-k}\A{1}^{(d-k)/2}\A{2}^{d/2}\sum_{\bb{\beta}+\bb{\gamma}\leq \max(2d+1,k)}\norme{\partial_x^\beta\partial_\xi^\gamma f}_{L^1(\mc{T}_{\A{1},\A{2}})}.
    \end{equation*}

