body:
[Lem 4 of arXiv:2604.06122, 'REM universality for linear random energy'] For any measurable $f:\R\to \bar\R_{\geq 0}$
\been{
\mathcal{L}_{\PPP_{\tilde \lambda}}(f)=\exp\(-\int^{\infty}_{-\infty}\(1-e^{-f(x)}\)\D_{\tilde \lambda}(dx)\).
}

[Lemma lem:mainformula of arXiv:2410.23250, 'Strict inequalities for arm exponents in planar percolation'] For every function $F:\{0,1\}^n\times \{0,1\}^n\rightarrow \mathbb{R}$, we have \begin{equation}
        \frac{d}{dt}\mathbb{E}[F(\omega, \omega_t)]=-\frac{1}{2}\sum_{i=1}^{n}{\mathbb{E}[\nabla_{ii} F(\omega, \omega_t)]}.
    \end{equation}

