[Definition def_betacorner of arXiv:2411.10829, 'Airy$_\beta$ line ensemble and its Laplace transform'] Fix $\beta>0$.\footnote{Compared to [GS1] or [BGC], we set $\beta=2\theta$.} The \emph{$\beta$-corners process with top row $\lambda_1>\dots>\lambda_N$}
is a random array
$\{y^n_i\}_{1\leq i\leq n\leq N}\in \mathcal G_N$ with top row $(\lambda_1,\dots,\lambda_N)$, in which
the $N(N-1)/2$ coordinates $y_i^n$, $1\le i \le n<N$, have the probability density
\begin{equation}

\frac{1}{Z_{N; \beta}} \cdot
\prod_{n=1}^{N-1} \left[\prod_{1\le i<j\le n} |y_j^n-y_i^n|^{2-\beta}\right] \cdot \left[\prod_{a=1}^n \prod_{b=1}^{n+1}
|y^n_a-y^{n+1}_b|^{\beta/2-1}\right],
\end{equation}
where $Z_{N; \beta}$ is the normalization constant:
\begin{equation}

Z_{N; \beta} =\left[\prod_{n=1}^N \frac{ \Gamma(\beta/2)^n}{\Gamma(k\beta/2)}\right] \cdot \prod_{1\le i < j \le N}
 |\lambda_j-\lambda_i|^{\beta-1}.
\end{equation}

[Lemma 29 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Fix $b > 0$, $q \in (0,1)$, $c \in [0,1)$, $\vec{y} = (y_1, y_2) \in \weyl_2$ and set $p = \frac{q}{1-q}$, $\sigma = \sqrt{p(1+p)}$. Let $\{d_n \}_{n \geq 1}$ be a sequence of positive reals, such that $d_n \rightarrow \infty$. Let $T_n = \lceil b d_n \rceil$ and $Y^n \in \mathfrak{W}_2$ be a sequence, such that 
\begin{equation}
\lim_{n \rightarrow \infty}\sigma^{-1} d_n^{-1/2} (Y_1^n  - p T_n) = y_1 \mbox{ and }\lim_{n \rightarrow \infty}\sigma^{-1} d_n^{-1/2} (Y_2^n  - p T_n) = y_2.
\end{equation}
Finally, let $\mathfrak{L}^n = \{L^n_i\}_{i = 1}^2$ be a $\llbracket 1, 2 \rrbracket$-indexed geometric line ensemble on $\llbracket 0, T_n \rrbracket$ with law $\mathbb{P}^{T_n, Y^n}_{\ice; q, c}$ as in Definition \ref{Def.InteractingPair}. Then, we have the following weak convergence
\begin{equation}
\left(\sigma^{-1} d_n^{-1/2} L^n_1(0) - \frac{y_1 + y_2}{2}, \sigma^{-1} d_n^{-1/2} L^n_2(0) - \frac{y_1 + y_2}{2} \right) \Rightarrow \sqrt{b/2} \cdot (Z,Z),
\end{equation}
where $Z$ is a normal random variable with mean $0$ and variance $1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 5 of arXiv:2608.25094, 'Noising-Denoising by Large Temperature Schr\"{o}dinger Bridges'] Let $M$ be a compact manifold. There exists $C > 0$ and $T > 0$ such that for all $t \geq T$ and $x \in M$, the following holds for all $y,z \in M$
    \begin{align*}
        \abs{\log \left(\frac{r_t(x,y)}{r_t(x,z)}\right)} \leq C \exp(-\lambda_1 t) d(y,z). 
    \end{align*}

