[Lemma 29 of arXiv:2511.13559, 'Asymptotic analysis of rare events in high dimensions'] Let $X\sim\mathcal N(0_d, (\la H)^{-1})$ and $q, \Delta$ be as in Lemma~\ref{lma:BD}. We have
\begin{align}
\la\E[q(X)^2\ind_{\us}(X)]^{1/2}&\les\omega_{3,0}\frac{d}{\sqrt\la} + \omega_{4,0}(R\e,0)\frac{d^2}{\la},\\
\la\E[\Delta(X)^2\ind_{\us}(X)]^{1/2} &\les \delta_3\frac{d}{\sqrt\la} + \delta_4(R\e)\frac{d^2}{\la},\\
\E \left[e^{\la(t_1q+t_2\Delta)(X)}\ind_{\us}(X)\right] &\leq C(R,\CL,c_\delta, |t_1|, |t_2|).
\end{align}

[Definition 11 of arXiv:2606.11271, '\LARGE The $K$-th nearest neighbor random walk on a Poisson point process gets trapped'] For any given $\varepsilon >0$, $R\in \N^*$ and $u \in \Z^d$, the block $\Lambda_R(u)$ is said $\varepsilon$-good if both following statements are satisfied.
\begin{itemize}
\item[$(i)$] For any $v \in \Z^d$ s.t. $\| u-v \|_\infty \leq d$, we have $| \chi \cap \Lambda_R (v) | \geq M+1$.

\item[$(ii)$] For any $x \in \chi$, $B(x, r_M(x) ) \cap \Lambda_R (u) \neq \emptyset$ implies that $B(x, r_M(x) ) \cap \Lambda_R (u)$ contains an Euclidean ball of radius $2 \varepsilon$.
\end{itemize}

[Thm 3 of arXiv:2604.24624, 'Limit distributions of the threshold radius for the maximum degree and the associated poin'] Assume that $d \geq 1$, $k \geq 1$, and $X_1$ has the bounded density $f$.
    Assume also that $n^{k+1} r_n^{dk} \to \infty$ and $nr_n^d \to 0$.
    Let $\{\Gamma_i\}_{i=1}^m$ be the set of all non-isomorphic feasible graphs with $k+1$ vertices that have at least one vertex of degree $k$.
    Then, for every continuity point $x_0$ of $f$, the spatially scaled point process $D_{n^{(k+1)/d} r_n^k} (T_{-x_0} \Phi_{k,n})$ converges in distribution, with respect to the vague topology, to a compound Poisson point process $\widetilde{\CH}_{x_0}$ with its Laplace functional
    \begin{equation*}
        \CL_{\widetilde{\CH}_{x_0}}(g) = \exp\left(-\int_{\BR^d} \left(1-\sum_{i=1}^m \frac{\mu_{\Gamma_i}}{\mu_{d,k}} e^{-q_i g(x)}\right) \lambda_{x_0}\,dx\right),
    \end{equation*}
    where $g : \BR^d \to [0,\infty)$ is measurable and
    \begin{equation*}
        \lambda_{x_0} := \frac{f(x_0)^{k+1}}{(k+1)!} \sum_{i=1}^m \int_{(\BR^d)^k} h_{\Gamma_i} \left(\delta_{\bm{0}} + \sum_{\ell=1}^k \delta_{x_{\ell}}\right) \,\prod_{\ell=1}^k dx_{\ell}.
    \end{equation*}
    That is, $\widetilde{\CH}_{x_0}$ has a homogeneous Poisson point process of intensity $\lambda_{x_0}$ as its supporting measure, and i.i.d. weights $\zeta_j$ having the distribution $P[\zeta_j = \ell] = (\sum_{1 \leq i \leq m, q_i = \ell} \mu_{\Gamma_i})/\mu_{d,k}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition CLT adapted of arXiv:2511.05223, 'Kac's Program and Relative Entropy Decay for Nonlinear Spin-Exchange Dynamics'] Let \(\nu \in \mathcal{P}(\Omega)\) be irreducible, and let $M^{(N)}$ be the sum of $N$ independent copies of $M$, each distributed according to $\nu$. 
Then, there exists a constant \(K(\nu) > 0\) such that for all $N\ge 1$, 
\begin{align*}
\max_{S}\, \left|\, {\ensuremath{\mathbb P}} \big(M^{(N)} = S\big) - \frac{e^{-\frac{1}{2}\langle z_N, z_N \rangle}}{(2\pi N)^{|\mathcal{A}|/2} \sqrt{\det V^\mathcal{A}_\nu}} \,\right| \le \frac{K(\nu)}{(2\pi N)^{|\mathcal{A}|/2 + 1}},
\end{align*}
where $z_N$ is the \(|\mathcal{A}|\)-dimensional vector defined as
\begin{equation}
z_N = \frac{(V_\nu^{\mathcal{A}})^{-1/2}}{\sqrt{N}} \left(S - \mathbb{E}[M^{(N)}] \right),
\end{equation}
and the maximum is taken over all  \(|\mathcal{A}|\)-tuples \(S=(S_A, A\in\ensuremath{\mathcal A})\) such that for each $A\in\ensuremath{\mathcal A}$, $S_A=2X_A-N|A|$ for some integer
$X_A\in\{0,\dots,N|A|\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lam g lam g minus one formula of arXiv:2609.02409, 'Membranes and Maps'] Let $\iota \colon \overline{M}_{g-1,n+2} \to \overline{M}_{g,n}$ be the normalization map of the irreducible boundary divisor. For
    $g\geq1$ and $2g-2+n>0$, we have
    \begin{equation}

        \lambda_g\lambda_{g-1}
        =
        \frac{B_{2g}}{4g}\,
        \iota_*
        \sum_{k=0}^{2g-2}
            (-1)^{g-1-k} \,
            \psi_{n+1}^k \psi_{n+2}^{2g-2-k}
    \end{equation}
    in $\mathsf{CH}^{2g-1}(\overline{M}_{g,n})$.

