[Definition 1 of arXiv:2607.06428, 'Impact of spinning on the early-warning signs in non-Markovian stochastic systems'] Let $(\mathbf{x}_t)_{t\geq 0}$ be a $n$-dimensional stochastic process. Then the autocovariance at time $t\ge0$ 
and lag time $\tau\ge0$ is defined as 
\begin{align}
    V_t(\tau):=\E[\mathbf{x}_t\overline{\mathbf{x}}_{t+\tau}^{\text{T}}]-\E[\mathbf{x}_t]\E[\overline{\mathbf{x}}_{t+\tau}^{\text{T}}],
\end{align}
where $\overline{\mathbf{x}}$ is the complex conjugate and $\mathbf{x}^{\text{T}}$ is the transpose.
For $\tau=0$ we recover the variance of the process. For $n=1$ we can also define the autocorrelation function
\begin{align}
    AC_t(\tau):=\frac{V_t(\tau)}{V_t(0)}.
\end{align}

[Proposition prop:lln of arXiv:2605.10361, 'Limit shape of single-source stochastic sandpiles with $p$-topplings on $\Z$'] For $\mathtt{l}_{n}=\inf\{v\in\mathbb{Z}\;|\; \eta_{K_n}^{(n)}(v)>0\}$ and $\mathtt{r}_{n}=\sup\{v\in\mathbb{Z}\;|\;\eta_{K_n}^{(n)}(v)>0\}$, it holds that
    \begin{align*}
        \frac{\mathtt{l}_{n}}{n}\xrightarrow[n\rightarrow\infty]{\mathbb{P}}-\frac{1}{2}&&\text{and}&&\frac{\mathtt{r}_{n}}{n}\xrightarrow[n\rightarrow\infty]{\mathbb{P}}\frac{1}{2}.
    \end{align*}

[Lemma 18 of arXiv:2607.11756, 'Full replica symmetry breaking in the Sherrington--Kirkpatrick model'] For $\beta>1$,
\begin{equation}
 \Gamma'(0)=1,\qquad u_{xx}(0,0)=\frac1\beta.
\end{equation}

[Lemma L:2F1 of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] We have that
    \begin{align}
       & \lMr{2}{F}{1}(1,b;1;-1) = 2^{-b}, \qquad \text{for all $0<b<1$,} \shortintertext{and}
     & \lMr{2}{F}{1}(1,-1;2H;-1) = \frac{1+2H}{2H}, \qquad \text{for all $H\in [1/2,1)$.}

  \end{align}

[Theorem thm:Driscoll:zero of arXiv:2605.28106, 'Gaussian Processes with Sample Paths in Reproducing Kernel Banach Spaces'] Let \( \xi : T \times \Omega \to \mathbb{R} \) be a centered Gaussian process with covariance function \( K \), and suppose that \( (\Omega,\mathcal{A},\mu) \) is complete.
    If \( H(K) \not\subseteq X \) or if the embedding \( \iota : H(K) \to X \) is not \( \gamma \)-radonifying, then
    \begin{equation} 
        \mu(\{ \omega \in \Omega : \xi(\cdot,\omega) \in X \}) = 0.
    \end{equation}

