[Definition def:fourlongitude of arXiv:2608.26564, 'Real ideal points, Conway spheres, and left-orderable Dehn fillings'] A \emph{four-longitude decomposition along $B$} is a decomposition of $\lambda$ into four longitudinal pieces $\lambda = \ell_1\ell_2\ell_3\ell_4$, where:
\begin{enumerate}
	\item $\ell_i, \ell_{i+2} \in \pi_1(T_i)$ for $i = 1, 2$.
	\item $m_{i, 2} = \ell_i^{-1}m_{i,1}\ell_i$ and $m_{i, 4} = \ell_{i+2}^{-1}m_{i, 3}\ell_{i+2}$.
\end{enumerate}
We say that a four-longitude decomposition is in \emph{parabolic form} if, in addition:
\begin{enumerate}
	\item $\rho_i^B(\ell_i)$ and $\rho_i^B(\ell_{i+2})$ are noncentral parabolic for $i = 1, 2$.
	\item $\mathrm{Fix}(\rho_i^B(\ell_i)) \neq \mathrm{Fix}(\rho_i^B(\ell_{i+2}))$.
\end{enumerate}

[Lemma lem:ZIM_onCG of arXiv:2607.29409, 'The Zombie Infection Model'] Consider the ZIM on $K_{N}$ with $\lambda >0$ and initially
		$\Delta= \{1,\dots,M\}$ infected. Then
		\begin{equation}
			\tau_{dt}= \min(\tau_{Z},\tau_{S}) \leq 2N - M.
		\end{equation}
		Moreover, we have that 
		\begin{equation}
			\lim_{N \rightarrow \infty}\BP_{\lambda,K_N, \Delta}^{\ZIM}( \tau_{dt}= \tau
			_{Z}) =
			\begin{cases}
				1                                  & \text{if }\lambda\leq 1, \\
				\left(\frac{1}{\lambda}\right)^{M} & \text{if }\lambda>1.
			\end{cases}
		\end{equation}

