[Definition 79 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $\alpha, \beta > 0$ be arbitrary. We denote by $\hat{\calc}_2^{\alpha,\beta}([0,T],W)$ the space of all functions $\Xi : \Delta_T^2 \to W$ such that $\Xi_{t,t} = 0$ for all $t \in [0,T]$ and
\begin{align*}
\| \Xi \|_{\alpha,\beta} := \| \Xi \|_{\alpha} + \| \hat{\delta} \Xi \|_{\beta} < \infty.
\end{align*}
Here $\| \Xi \|_{\alpha}$ denotes the H\"older norm \eqref{Hoelder-norm-sewing-1}. Furthermore, the function $\hat{\delta} \Xi : \Delta_T^3 \to W$ is defined as
\begin{align*}
\hat{\delta} \Xi_{s,u,t} := \Xi_{s,t} - S_{t-u} \Xi_{s,u} - \Xi_{u,t}, \quad (s,u,t) \in \Delta_T^3,
\end{align*}
and its H\"older norm is defined as
\begin{align*}
\| \hat{\delta} \Xi \|_{\beta} := \sup_{\genfrac{}{}{0pt}{}{(s,u,t) \in \Delta_T^3}{s < u < t}} \frac{|\hat{\delta} \Xi_{s,u,t}|}{|t-s|^{\beta}}.
\end{align*}

[Theorem thm:uppermatrix of arXiv:2505.12187, 'Speeding up quantum Markov processes through lifting'] Let the QMS $\exp(t \mathcal{L}_\gamma)$ be a lift of $\exp(t \mathcal{L}_O)$ in the sense of (def:2ndlift of the paper). The exponential convergence holds: for $X \in \mathcal{M}$ with $E_{\mathcal{F}}(X) = 0$, 
        \begin{align*}
            \norm{e^{t \mathcal{L}_\gamma} (X)}_{2,\sigma} \le C e^{-\nu t} \lVertX\rVert_{2,\sigma}\,,
        \end{align*}
    with $ C = \mathcal{O}(1)$ and $\nu = \frac{\gamma}{\gamma^2 C_0 + C_1}$,
    where 
    \begin{align*}
        C_0 = \Theta\left(\lambda_O^{-1} \right)\,, \quad C_1 = \Theta\left(
         \left(\lambda_S^{-1} + 1 + \lambda_S^{-1/2}(K_1 + K_2 \lambda_O^{-1/2}) \right)^2
           \right)\,.
    \end{align*}
   The spectral gaps $\lambda_O$ and $\lambda_S$ are given in (equation eq:spgaplado of the paper) and (equation eq:spgaplads of the paper), respectively, and the constants $K_1$ and $K_2$ are such that 
   \begin{align}  
    \norm{(\mathrm{id} - E_S)\mathcal{L}_A^\dag (-\mathcal{L}_S)^{-1} \mathcal{L}_A Y}_{2,\sigma} 
  \le & \left( K_1 \lVert\mathcal{L}_O (Y)\rVert_{2,\sigma} + K_2 \sqrt{\mathcal{E}_{\mathcal{L}_O}(Y)} \right)\,.
\end{align}
If $\gamma = \gamma_{\max} := \sqrt{C_1(T)/C_0(T)}$, we have the maximal convergence rate:
\begin{align} 
    \max_{\gamma > 0} \, \nu(\mathcal{L}_\gamma) \ge \nu(\mathcal{L}_{\gamma_{\max}}) = \Omega\left(\frac{\lambda_O^{1/2}}{ \lambda_S^{-1} + 1 + \lambda_S^{-1/2}(K_1 + K_2 \lambda_O^{-1/2})}\right)\,.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 5 (Negative drift of $c_n$) of arXiv:2607.20838, 'Long-memory Markov chains with power-law intensities'] There exists $x_* > 0$ such that the following statements hold.
	\begin{enumerate}
		\item For $0 < x < x_*$, if 
		\begin{equation}
			c > C_1 
			:= \frac{2\mu \gamma + 3 \mu_{\varepsilon} + \sqrt{(2\mu \gamma + 3 \mu_{\varepsilon})^2 
					+ \frac{24  \mu \mu_{\varepsilon} \gamma x_*}{\xi}}}{4\mu}, 
		\end{equation}
		then $\mathbb{E}_{x,c}[c_n] - c < 0$.

		\item For $x \ge x_*$, if 
		\begin{equation}
			c > C_2 
			:= \frac{\gamma + \sqrt{\gamma^2 + \frac{3 \mu_{\varepsilon} \gamma}{k_p \xi}}}{2}, 
		\end{equation}
		then $\mathbb{E}_{x,c}[c_n] - c < 0$.
	\end{enumerate}

