body:
[Theorem thrm:random_apprx_noisy_robustified of arXiv:2609.03129, 'A Closed-Form Formula for Consistent Lipschitz Regression on Metric Spaces with Sparse Neu'] Suppose that Assumption~(assumption:main_1Lip of the paper) holds.  Let
$N_0,N_1\in\mathbb{N}_+$ and set $N\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} N_0+N_1$.  Fix
$\varepsilon\in(0,1)$ and
$\delta_{\operatorname{net}},
 \delta_{\operatorname{noise}}\in(0,1)$
such that
$
    \varepsilon/2\le\operatorname{diam}(X)
$.
Set
\[
    \eta\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\frac{\varepsilon}{4},
    \qquad
    \beta\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\frac{\varepsilon}{2},
    \qquad
    q_\varepsilon
    \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    \left\lceil\varepsilon^{-2}\right\rceil.
\]
Use the first $N_0$ observations as the reference block and the remaining
$N_1$ observations as the averaging block.  Assume that
\begin{equation}

\begin{aligned}
    N_0
    &\ge
    \frac{1}{a(\varepsilon/8)^s}
    \log\left(
        \frac{
            2\mathcal N(X,\rho,\varepsilon/8)
        }{
            \delta_{\operatorname{net}}
        }
    \right),
    \\
    N_1
    &\ge
    \frac{1}{a(\varepsilon/2)^s}
    \max\left\{
        2q_\varepsilon,
        8\log\left(
            \frac{
                2N_0
            }{
                \delta_{\operatorname{net}}
            }
        \right)
    \right\}.
\end{aligned}
\end{equation}

For each $k\in[N_0]_+$, set $\xi_k\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} X_k$.  If at least
$q_\varepsilon$ indices
$j\in\{N_0+1,\ldots,N_0+N_1\}$ satisfy
$
    \rho(X_j,\xi_k)\le\beta,
$
let
$
    j_{k,1}<\cdots<j_{k,q_\varepsilon}
$
be the first $q_\varepsilon$ such indices and define
\[
    \overline Y_k
    \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    \frac{1}{q_\varepsilon}
    \sum_{\ell=1}^{q_\varepsilon}
        Y_{j_{k,\ell}}.
\]
If fewer than $q_\varepsilon$ such indices exist, set
$
    \overline Y_k\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}0
$.

Define, for every $x\in X$,
\begin{equation}

    \hat{f}(x)
    \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    \frac{1}{2}
    \left[
        \min_{k\in[N_0]_+}
        \left\{
            \overline Y_k+\rho(x,\xi_k)
        \right\}
        +
        \max_{k\in[N_0]_+}
        \left\{
            \overline Y_k-\rho(x,\xi_k)
        \right\}
    \right].
\end{equation}
Then, for every fixed
$f\in\operatorname{Lip}((X,\rho);1)$:

\begin{enumerate}
    \item[(i)] $\hat{f}:X\to\mathbb{R}$ is $1$-Lipschitz for every
    realization of the sample;

    \item[(ii)] the random variable
    $
        \|\hat{f}-f\|_\infty
    $
    is measurable and satisfies
    \begin{equation}

        \mathbb{P}\left(
            \|\hat{f}-f\|_\infty
            \le
            \varepsilon
            \left[
                1
                +
                \sqrt{
                    C
                    \log\left(
                        \frac{
                            2N_0
                        }{
                            \delta_{\operatorname{noise}}
                        }
                    \right)
                }
            \right]
        \right)
        \ge
        1
        -
        \delta_{\operatorname{net}}
        -
        \delta_{\operatorname{noise}}.
    \end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 of arXiv:2608.19832, 'Sharp Convex Concentration for Symmetric Random Tensors with Subgaussian Coordinates'] Under the assumptions of \Cref{thm:main}, for every $d\ge1$ and
\begin{equation}
 0\le t\le c_KLn^{d/2},
\end{equation}
we have
\begin{equation}
 \Pp\left\{\abs{Z-\E Z}>t\right\}
 \le C\exp\left[-c_K\mathcal I_{n,d}\left(
 \frac{t}{Ln^{(d-1)/2}}
 \right)\right].
\end{equation}
Matching minimax lower bounds under a fixed absolute subgaussian bound are
stated in \Cref{cor:rate-sharpness}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 15 (Unimodality of the sub-Gaussian ratio) of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] Fix $p \in (0, 1/2)$. The function $\psi$ is strictly increasing on $(0, 2\beta_p]$ and strictly decreasing on $[2\beta_p, \infty)$, with maximum
\begin{align}
    \psi(2\beta_p) = \frac{1 - 2p}{4\beta_p}.

\end{align}
For $p = 1/2$, $\psi$ is strictly decreasing on $(0,\infty)$ with $\sup_{s>0}\psi(s) = \psi(0^+) = 1/8$.

