[Lem 4 (\cite{A59}, Theorem 4.4.23  and \cite{Zhu}, Proposition 2.2) of arXiv:2604.25964, 'Strong convergence rate of Euler-Maruyama approximations in temporal-spatial H\"older-norm'] Let $\mathcal{P}$ be the progressive $\sigma$-algebra on $\mathbb{R}_+\times\Omega$ and $\mathcal{B}(\mathbb{R}_0)$ be the Borel $\sigma$-algebra of \;$\mathbb{R}_0$. Assume that $g$ is a $\mathcal{P}\otimes \mathcal{B}(\mathbb{R}_0)$-measurable function such that $\int_0^T\int_{\mathbb{R}_0}\vert g(s,z) \vert^2\nu(dz)ds<\infty$ $\pr$-a.s. for all $T\geq 0$. Then, for any $p\geq 2$, there exists a constant $C_p >0$ such that
	\begin{align*}
		&\mathbb{E}\left[\sup_{0\leq t \leq T}\left\vert \int_0^t\int_{\mathbb{R}_0} g(s,z) \widetilde{N}(d s, d z)\right\vert^p\right]\\
		&\leq C_p \left(\mathbb{E}\left[\left(\int_0^T\int_{\mathbb{R}_0} \vert g(s,z) \vert^2 \nu(dz)ds\right)^{\frac{p}{2}}\right]+\mathbb{E}\left[\int_0^T\int_{\mathbb{R}_0} \vert g(s,z) \vert^p \nu(dz)ds\right]\right).
	\end{align*}
	Moreover, for any $1\leq p<2$, there exists a constant $C_p >0$ such that
	\begin{align*}
		\mathbb{E}\left[\sup_{0\leq t \leq T}\left\vert \int_0^t\int_{\mathbb{R}_0} g(s,z) \widetilde{N}(d s, d z)\right\vert^p\right]\leq C_p \, \mathbb{E}\left[\left(\int_0^T\int_{\mathbb{R}_0} \vert g(s,z) \vert^2 \nu(dz)ds\right)^{\frac{p}{2}}\right].
	\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 5 of arXiv:2608.01860, 'A Variational Characterization of a Gibbs Measure related to the Aviles-Giga Functional'] Let $g:C([0,\infty),H)\to\R$ be such that \[\int_X(|g(W(x))|+1)\exp(-g(W(x))\ \mu(dx)<\infty.\] Then 
    \begin{align*}
    &-\log\int_X \exp(-g(W(x)))\ \mu(dx)\\
    &=\inf_{v}\left\{\int_X\left(g\left(W(x)+\int_0^{\cdot}v_s(x)\ ds\right)+ \frac{1}{2}\int_0^\infty \Vert v_s(x)\Vert^2\ ds\right) \mu(dx)\right\},
\end{align*}
where the infimum is taken over drifts $v$ such that $v(x)\in L^2([0,\infty),H)$ for almost every $x\in X$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop of arXiv:2507.09421, 'Stability of randomly switching stochastic reaction networks with asymptotically linear tr'] In Example (ex:disjoint species of the paper), there exists vectors $v^1,v^2$ such that all hypotheses of Theorem (thm:slow-switching-transience of the paper) are satisfied, except that $\operatorname{supp}(v^1)\ne\operatorname{supp}(v^2)$. Nevertheless, the mixed process is positive recurrent for any choice of $\kappa$.
\begin{proof}
    If $M_i$ denotes the rate matrix for $\mathcal R_i$, then
    \begin{align*}
        M_1=\begin{pmatrix}-2&0\\0&1\end{pmatrix}
        \qquad
        M_2=\begin{pmatrix}1&0\\0&-2\end{pmatrix}
    \end{align*}
    If $v^1=(0,1)$ and $v^2=(1,0)$, then $v^iM_i=v^i$ for $i=1,2$. We see that all hypotheses of Theorem (thm:slow-switching-transience of the paper) are satisfied, except that $\operatorname{supp}(v^1)\ne\operatorname{supp}(v^2)$.

    But fix $\kappa>0$, and define $h:\mathbb Z^2_{\ge0}\times\{1,2\}\to[0,\infty)$ via $h(a,b,1)=a+(1+2\kappa^{-1})b$ and $h(a,b,2)=(1+2\kappa^{-1})a+b$. Let $\mathcal L$ denote the generator of the mixed process; we see that
    \begin{align*}
        \mathcal Lh(a,b,1)&=\kappa2\kappa^{-1}(a-b)+(b+1)(1)-2a(1+2\kappa^{-1})\\
        &=-4\kappa^{-1}a-b+1.
    \end{align*}
    Similarly, $\mathcal Lh(a,b,2)=-a-4\kappa^{-1}b+1$. We conclude that $\mathcal Lh$ is negative outside a finite set, and so the model is positive recurrent, as claimed.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

