[Lemma elliptic_sys2 of arXiv:2609.00627, 'Global well-posedness of radially symmetric strong solutions to two-dimensional compressib'] Let $\Omega$ be a bounded domain with $C^{k+2}$ boundary.  Given $f \in W^{k,p}(\Omega)$,  if $v$ is the solution to following \textit{Neumann} boundary problem of the elliptic system equation
	\begin{equation}
		\begin{cases}
			\Delta v=f,  \enspace in \enspace \Omega\\
			\frac{\partial v}{\partial n}=0, \enspace on \enspace \partial\Omega
		\end{cases}
	\end{equation}
	satisfies the following elliptic estimates
	\begin{equation}
		\begin{aligned}
			\|\nabla v\|_{W^{k+1,p}(\Omega)} \leq C\| f \|_{W^{k,p}(\Omega)}. 
		\end{aligned}
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Propo 16 of arXiv:2605.11264, 'Uniform sampling of multitype continuous-time Bienaym\'e-Galton-Watson trees'] For any $k\geq 1$, $T\in \re_+$,  $r\in [d]$ and $A\in \F^{(k)}_T$, we have
\begin{equation}
	\begin{split}
\mathbb{P}^{(k)}_{unif,T,r}\paren{A}&= \frac{1}{(k-1)!}\frac{1}{\mathbb{P}_{r}\paren{\ N_T\geq k}}\int_0^\infty(e^\phi-1)^{k-1}\Q^{(k),\phi\vec{1}}_{T,r}(A)\E_{r}\left[N^{\floor{k}}_Te^{-\phi\vec{1}\cdot \bo Z_T}\right]{\rm d}\phi.
\end{split}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: partition procedure in sle of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] There exist a constant $c_2>0$ and a  partition $\mathsf{B}_1,\cdots,\mathsf{B}_n$ of $\Lambda_N$ such that the following holds:
\begin{enumerate}
    \item For every \(1\le i\le n\), we have
\begin{equation}
\sum_{x\in \mathsf{B}_i}{\operatorname{dist}}(x,\gamma\cup \partial\mathsf{B}_i)^{-1/4}
\le c_2M^{7/4}.

\end{equation}
\item The number of boxes satisfies \begin{equation}
n\le \frac{c_2}{\iota^2 \mathsf r^{2+\frac{21}{4}\kappa}}.

\end{equation}
\end{enumerate}

