[Lemma 38 of arXiv:2609.04139, 'The conformally invariant metric on CLE$_4$ II:\\ existence of geodesics'] Fix $a>0$ and let $\Gamma_{V_a}$ be a non-nested CLE$_4$ in $V_a$. Then, there exists $r_0>0$ such that with positive probability, we have that 
\begin{align*}
D_{\Gamma_{V_a}}^{V_a}(\{0\} \times [0,1], \{a\} \times [0,1]) <r_0 \quad \text{and} \quad 2r_0 \le D_{\Gamma_{V_a}}^{V_a}([0,a] \times \{0\}, [0,a] \times \{1\}).
\end{align*}
Moreover, the following holds with positive probability. Let $L_2 = \{0\} \times [1/5,4/5]$ and let $L = \{0\} \times [0, 1]$ be the left boundary of $V_a$. Let $\partial_\mathrm{R} \SCB_{r_0}(L; D^{V_a}_{\Gamma_{V_a}})$, the \emph{right boundary} of the metric ball (it faces the right side of $V_a$ but may also meet $L$), be the intersection of $\SCB_{r_0}(L; D^{V_a}_{\Gamma_{V_a}})$ with the closure of the union of the connected components $C$ of $V_a \setminus \SCB_{r_0}(L; D^{V_a}_{\Gamma_{V_a}})$ such that $\overline{C} \cap (\{a\} \times (0,1)) \neq \emptyset$. Then:
	\begin{enumerate}[label=(\alph*),ref=\alph*]
		\item We have $D_{\Gamma_{V_a}}^{V_a}(L_2, \{a\} \times [1/5,4/5]) < r_0$;
		\item The right boundary $\partial_\mathrm{R} \SCB_{r_0}(L; D^{V_a}_{\Gamma_{V_a}})$ intersects $L_2$;
		\item We have $D_{\Gamma_{V_a}}^{V_a}([0,a] \times \{0\}, [0,a] \times \{1/5\}) \ge 2r_0$ and $D_{\Gamma_{V_a}}^{V_a}([0,a] \times \{4/5\}, [0,a] \times \{1\}) \ge 2r_0$.
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 20 of arXiv:2605.09372, 'Sharp weighted norm estimates for martingale square functions'] Let $1<p<\infty$. Given a  scalar
	 weight $w\in A_p$, we have
	\begin{equation}
		\left\|\mathcal T_{w,2}f\right\|_{L_p(\Omega)} \lesssim_{p,d}[w]_{A_p}^{\max\{\frac12 ,\frac1{p-1}\}} \|f\|_{L_p(\Omega)},\quad\forall f\in L_p(\Omega).
	\end{equation}

