[Lemma lem:fdb of arXiv:2510.09818, 'On the Fourier dimension of fractional Brownian graphs'] [LL25]
	Consider $\varepsilon \in \mathcal{A}_{2q}$ and the function $G_\varepsilon$ defined in (equation lambda,T of the paper).
	For $\sigma \in \Sigma(q)$, recall that the non-trivial entries of $\sigma_{k_m}\cdots\sigma_{k_1}(\varepsilon)$ are written as $a = (a_1,\dots,a_I)$ in (equation j_1-j_I of the paper).
	Let $s=(s_1,\dots,s_I)$ be the variables introduced in Lemma (lem:variables of the paper).
	Then, the derivatives in equation (equation E:sigmaG:s of the paper) can be expressed as
	\begin{align*}
		\partial_{s_{p_1}}\cdots \partial_{s_{p_\ell}}G_{\sigma_{k_m} \cdots \sigma_{k_1} (\varepsilon)}(s) = \sum_{P \in \mathscr{P}_2\{p_1,\dots,p_\ell\}} \pi^{\# P} \exp(\pi g_a(s)) \prod_{B \in P} g_a^{(B)}(s),
	\end{align*}
	where $\mathscr{P}_2\{p_1,\dots, p_\ell\}$ denotes the set of all partitions $P$ of $\{p_1,\dots, p_\ell\}$ such that $\# B \le 2$ for all $B \in P$,
	\begin{align}
		g_a(s) = -\mathrm{Var}\left( \sum_{i=1}^I a_i B_{s_i} \right),
	\end{align}
	and $g_a^{(B)}(s) = \partial_{s_{i_1}}\cdots \partial_{s_{i_n}} g_a(s)$ if $\# B = n$ and $B = \{s_{i_1},\dots,s_{i_n}\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 42 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Assume that the condition \eqref{Eq cond small boundary} holds:
the area of the $\varepsilon$-neighborhood of $\partial D$
decay faster than any power of $1/\vert \log\varepsilon \vert$.
Fix $\eta>0$. Let $b$ depend on $\varepsilon$, $b=b(\varepsilon)$,
with values in $[(2v)\vee(2\lambda),+\infty)$.
We further assume that as $\varepsilon\to 0$,
\begin{equation}

\dfrac{\vert \log \varepsilon\vert}{b(\varepsilon)^{2}}\gg \log \vert\log\varepsilon\vert,
\end{equation}
that is to say
\begin{displaymath}
b(\varepsilon) = o\Big(\dfrac{\vert \log \varepsilon\vert^{1/2}}{(\log \vert\log\varepsilon\vert)^{1/2}}\Big).
\end{displaymath}
Then for every $\beta>0$, as $\varepsilon\to 0$,
\begin{equation}

\E\Big[\big\Vert\ind_{\widetilde{U}_{0,b(\varepsilon),\varepsilon}}\big\Vert_{H^{-\eta}(\C)}^{2}\Big]^{1/2}
= o(\vert \log\varepsilon \vert^{-\beta}).
\end{equation}
Similarly, for every $j\geq 1$ and $\beta>0$,
\begin{equation}

\E\Big[\Big\Vert \ind_{\widetilde{U}_{0,b(\varepsilon),\varepsilon}} 
\vert \log \CR(z,D\setminus A_{0,b})\vert^{j}
\Big\Vert_{H^{-\eta}(\C)}^{2}\Big]^{1/2}
= o(\vert \log\varepsilon \vert^{-\beta}).
\end{equation}

