body:
[Thm critical_gauge_scaling_limit of arXiv:2506.12171, 'The multinomial dimer model'] Fix a $d$-dimensional lattice $\Lambda$ and $R\subset \mathbb{R}^d$ as before. Suppose that $H$ is $C^1$ and solves the gauge PDE: $\text{div}(\nabla F(\nabla H))=0$, and that $g_n$ is the critical gauge function on black vertices of $R_n$ with limiting multiplicity $1$ everywhere on $R_n$. Further suppose that
    \begin{align*}
        \sup_{u\in B\cap\partial R_n} |(1/n) \log g_n(u) - H(u)| = O(1/n).
    \end{align*}
    We equate $(1/n) \log g_n$ defined on $B\cap R_n$ with its linear interpolation to a continuous function. Then
    \begin{align*}
        \lim_{n\to \infty} (1/n) \log g_n 
    \end{align*}
    exists in the topology induced by the supremum norm on continuous functions and is equal to $H$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 8 of arXiv:2606.31287, '\bf Heat kernel lower bound estimates for symmetric pure jump processes via averaged jump '] (\cite[Definition 1.5]{CKW1})
  \rm Let $U$ and $V$ be open subsets sets of $\sX$ with $\overline{U} \subseteq V$. A measurable function $\vp: \sX \to [0, 1]$ is called a cut-off function for $U \subseteq V$ if $\vp \equiv 1$ on $U$ and $\vp \equiv 0$ on $V^c$. We say that the condition $\CSJ(\phi)$ holds if there exist constants $C_0\in (0,1]$ and $C_1, C_2>0$ such that for every $0 < r \le R$, almost all $x_0 \in \sX$ and any $f \in \sF$, there exists
a cut-off function $\vp \in \sF_b$ for $B(x_0,R) \subset B(x_0,R+r)$ so that the following holds:
\be  \begin{split}
 \int_{B(x_0,R+(1+C_0)r)} f^2 \, d\mu_{\<\vp\>}
\le \,\,&C_1 \int_{U\times U^*}(f(x)-f(y))^2\,J(dx,dy) \\
&+ \frac{C_2}{\phi(r)}  \int_{B(x_0,R+(1+C_0)r)} f(x)^2m(dx),
\end{split}
\ee
where $U=B(x_0,R+r)\setminus B(x_0,R)$ and $U^*=B(x_0,R+(1+C_0)r)\setminus B(x_0,R-C_0r)$.

[Lemma 3 (A substitution) of arXiv:2609.03881, 'Eulerian insertion operators and an Eulerian form of the Pieri rule'] For every \(f\in\mathbb Q[x,y]\),
\begin{equation}
 \G(z)f(x,y)
 =f\left(
     \frac{x}{1-yz},
     \frac{y\bigl(1-yz+xz\bigr)}{1-yz}
   \right),
\end{equation}
where the right-hand side is expanded at \(z=0\).

[Defn defn4.19 of arXiv:2411.09988, 'A Study in Markov Chains, Loop-Erased Random Walk and Loop Soups'] The \textit{unrooted loop measure} $m=m^p$ is the measure that assigns to each unrooted loop
    \begin{equation}
        m(\ell) = J(\ell)\frac{p(\ell)}{|\ell|}.
    \end{equation}
    The \textit{(unrooted) loop measure} is a Poissonian realization from $m$.

[Proposition 15 of arXiv:2605.30030, 'Critical exponents for planar random-cluster model with cluster-weight~$q=4$'] There exists~$c>0$ such that the following holds true. For every integer~$k\ge1$ and~$\dst\in(0,1)$, there exists a constant~$C=C(k,\dst)>0$ such that for every~$0<\delta\le \eps<\dst/2$ and every~$F\in\mathcal F_\eps$ with~$k$ points~$x_1,\dots,x_k\in B_{1/\dst}(0)$ at mutual distances at least~$\dst$ of each other,
\begin{equation}
\Big|\bc^\delta(\eps)^k\phi_\delta[\mathcal A_F(\calL_{\{x_1,\dots,x_k\},\eps})]-\phi_\delta[\mathcal A_F(\calL)]\Big|\le C\pi_1^\delta(\eps,\dst)^k(\tfrac\eps\dst)^c.\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 10 of arXiv:2608.24675, 'Towards Liouville Quantum Gravity on fractals'] Let $h$ be the FGFF on $K$. For any $w\in\{1,2,3\}^n$ and $n\geq 1$,
	\begin{align*}
		h^{w}{:=}h\circ F_w^{-1},
	\end{align*}
    defined in the distributional sense \eqref{E:def_weak_prod_Kw},
	is the FGFF on $K_w$.

