body:
[Lem lem7 of arXiv:2412.05521, 'Random attractors for the stochastic Nernst-Planck-Navier-Stokes system with multiplicativ'] Let $(v^\varepsilon,\sigma,\rho)$ be a solution of system (equation b2 of the paper). Let $v^\varepsilon(t_0)$ $\in$  $H^1$ and $c_i(t_0) \in H^1$. Then,
		\begin{align}
			\|v^\varepsilon(t)\|_{L^2}^{2}\ \leq {e}^{-\nu t}[	\|v^\varepsilon(t_0)\|_{L^2}^{2}\ {e}^{\nu t_0} +\frac{2}{\nu}\int_{t_{0}}^{t} {z^{2}(s,w)}(\|\rho(s) \|_{L^2}^{3}\|\nabla \rho(s) \|_{L^2}+\|f\|_{L^2}^2) {e}^{\nu s}ds ],
		\end{align}
		for $t \geq t_0$.
		\begin{proof}
			Taking the ${L}^{2}$ inner product of the first equation in (equation b2 of the paper) with $v^\varepsilon$ yields
			\begin{align}
				\frac{1}{2}\|v^\varepsilon\|_{L^2}^{2}\ +\nu \|\nabla v^\varepsilon\|_{L^2}^{2}=-(\rho\nabla\Phi,v^\varepsilon)z(t,w)+(f,v^\varepsilon)z(t,w).
			\end{align}
			In view of Young's and Ladyzhenskaya's inequalities, we estimate
			\begin{align}
				|(\rho\nabla\Phi,v^\varepsilon)z(t,w)| \leq \frac{\nu}{4}\|\nabla v^\varepsilon\|_{L^2}^{2}+\frac{1}{\nu}{z^{2}(t,w)}\|\rho \|_{L^2}^{3}\|\nabla \rho \|_{L^2},
			\end{align}
			and
			\begin{align}
				|(f,v)z(t,w)| \leq  \frac{\nu}{4}\|\nabla v^\varepsilon\|_{L^2}^{2}+\frac{1}{\nu}{z^{2}(t,w)}\|f\|_{L^2}^2.
			\end{align}
			Putting (equation jia1 of the paper) to (equation jia3 of the paper) together, we get
			\begin{align}
				\frac{d}{dt} \|v^\varepsilon\|_{L^2}^{2}\ + \nu \|\nabla v^\varepsilon\|_{L^2}^{2} \leq\frac{2}{\nu}{z^{2}(t,w)}\|\rho \|_{L^2}^{3}\|\nabla \rho \|_{L^2}+\frac{2}{\nu}{z^{2}(t,w)}\|f\|_{L^2}^2.
			\end{align}
			By Lemma (lem1 of the paper), we obtain (equation d5 of the paper).
		\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

