[Lemma eq:propB of arXiv:2411.07157, 'Rough differential equations in the flow approach'] Fix $\mu \in[0,1]$, $\tau_i \in \mathfrak{T}$, and $\text{$\mathfrak{z}$}^{\tau_i} \in {\mcb{C}}[\tau_i]\,$ for $i = 1,2$. The most important property of the grafting $\big(\text{$\mathfrak{z}$}^{\tau_2}\graft^\mu\text{$\mathfrak{z}$}^{\tau_1}\big)^\tau$, upon which we rely extensively, is that for every $N\in\N$, uniformly in $\text{$\mathfrak{z}$}^{\tau_i}$ and $\mu\in(0,1]$ we have
    \begin{equs}
        \|K_{N,\mu}^{\otimes1+\mathfrak{s}(\tau)}&\big(\text{$\mathfrak{z}$}^{\tau_2}\graft^\mu\text{$\mathfrak{z}$}^{\tau_1}\big)^\tau\|_{L^\infty_t L^1_{s^\tau}}\\&\lesssim \|   \mathcal{P}_{2N,\mu} \dot G_\mu\|_{\mathcal{L}^{\infty,\infty}}
\|K_{N,\mu}^{\otimes1+\mathfrak{s}(\tau_1)}\text{$\mathfrak{z}$}^{\tau_1}\|_{L^\infty_t L^1_{s^{\tau_1}}}
\|K_{N,\mu}^{\otimes1+\mathfrak{s}(\tau_1)}\text{$\mathfrak{z}$}^{\tau_2}\|_{L^\infty_t L^1_{s^{\tau_2}}}    \,.\textcolor{white}{a}    
    \end{equs}

[Proposition eq_1819 of arXiv:2605.10479, 'Poisson approximation of random lattices'] Let $S \subseteq \mathbb R^n$ be a measurable set with $S \cap (-S) = \emptyset$ and $0 < { \rm Vol }_n(S) < \infty$. Let $f: \mathcal F(S) \rightarrow \mathbb R$ be a bounded, measurable
	function such that $f(X) = 0$ if $|X| \geq n$. Then,
	\begin{equation}  \mathbb E \sum_{X \subseteq L \cap S}
		f (X) \cdot \iota(X) =
		\mathbb E \sum_{X \subseteq S \cap P }
		f (X),
		 \end{equation}
	where the sum runs over all subsets $X$ of $L \cap S$ on the left-hand side, and of $S \cap P$ on the right-hand side. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition analytic R transform of arXiv:2607.22156, 'A random matrix approach to lamplighter groups'] Let $x=u+u^*$.  For $\|b\|<1/2$,
\begin{align*}
 R_x^{\mathcal{B}_0}(b)&=\sum_{m\geq0}(-1)^mC_m\left((\alpha(b)b)^m\alpha(b)+(\alpha^{-1}(b)b)^m\alpha^{-1}(b)\right)\\
 &=2\alpha(b)\bigl(1+\sqrt{1+4b\alpha(b)}\bigr)^{-1}+2\alpha^{-1}(b)\bigl(1+\sqrt{1+4b\alpha^{-1}(b)}\bigr)^{-1}.
\end{align*}
The square roots are the principal square roots given by functional calculus.

