body:
[Lemma 21 of arXiv:2506.20789, 'Central limit theory for Peaks-over-Threshold partial sums of long memory linear time seri'] Let $(X_t)$ be a stationary time series, and
  let $g$ be an increasing, continuously differentiable function whose derivative $g'$ is regularly varying at infinity.
  For $x>0$ define
  \begin{align*}
    \xi(x)
    \ := \
    \frac{xf_{X_0}(x)}{\PP[X_0>x]}
    \,.
  \end{align*}
  Assume the following:
  \begin{itemize}
    \item
    There exists a threshold sequence $(u_n)$ with $u_n\to\infty$, and a rate sequence $(r_n)$ with $r_n\to\infty$, such that $r_n/\xi(u_n)\to\infty$,
 and there exists a constant $c>0$ such that
      \begin{align}

        \begin{split}
        u_n
        \cdot
        g'(u_n)
        \frac
        {
        \PP[X_0>u_n]
        }
        {
\EE
\left[
  \,
\left(
      g(X_0)
       -
      g(u_n)
      \right)
      \mathbbm{1}
      \left\{
        X_0>u_n
      \right\}
\right]
        }
        \
        \sim
        \
          c
          \cdot
          \xi(u_n)
          \,,
        \end{split}
      \end{align}
      and,
      for all $t\in\mathbb{R}$,
\begin{align}

        r_n
        \left(
        \frac{\PP[X_0>u_n]}{\PP[X_0>(1+t/r_n)\cdot u_n]}
        \ - \
        1
        \right)
        \ \sim\
        t
        \cdot
        \xi(u_n)
        \,.
      \end{align}
\item
    There exists $\delta_\epsilon\in(0,1)$ such that for all
    sequences $(\epsilon_n)$ converging to $0$ and satisfying
    \begin{align}

      |\epsilon_n|= \mathcal{O}(r_n^{\delta_\epsilon-1})
    \end{align}
    the following holds:
\begin{align}

  \begin{split}
    &
      \frac
      {
    r_n/\xi(u_n)
      }
      {n}
      \\&
      \cdot \
      \sum_{t=1}^{n}
     \left[
      \left(
      \frac
      {
      \left(
      g(X_t)
       -
      g(u_n)
      \right)
      \mathbbm{1}
      \left\{
        X_t>u_n
      \right\}
    }
      {
\EE
\left[
  \,
\left(
      g(X_0)
       -
      g(u_n)
      \right)
      \mathbbm{1}
      \left\{
        X_0>u_n
      \right\}
\right]
      }
      \ - \
      1
      \right)
      \,,
      \left(
      \frac
      {
            \mathbbm{1}
      \left\{
        X_t>u_n(1+\epsilon_n)
      \right\}
    }
      {
      \PP[
        X_0>u_n(1+\epsilon_n)
      ]
      }
      \ - \
      1
      \right)
    \right]
  \end{split}
      \end{align}
      converges in distribution, as $n\to\infty$, to a pair of non-degenerate continuous random variables $[\Phi, \Psi]$.
        \item
There exists a positive sequence $(\tau_n)$
such that
\begin{align}

\tau_n \ = \  \mathcal{O}(r_n^{\delta_\epsilon - 1})
\,,
\end{align}
    \begin{align}

      \tau_nr_n\to \infty
      \,,
    \end{align}
and
      \begin{align}

        \frac{\PP[X_0>u_n]}{\PP[X_0>u_n(1\pm\tau_n)]}
        \ \to \
        1
        \,,
      \end{align}
      as $n\to\infty$.
  \end{itemize}
  If additionally $n\PP[X_0>u_n]\to\infty$, then under the above assumptions, for
  \begin{align*}
    k
    \ = \
    k(n,u_n)
    \ := \
        \lfloor n\PP[X_0>u_n]\rfloor
        \,,
  \end{align*}
  it holds that
      \begin{align*}
        &
     \left[
        \frac{r_n}{\xi(u_n)}
     \frac{1}{k}
      \sum_{i=1}^{k}
      \left(
      \frac
      {
        g(X_{n-i+1:n})
      \ - \
        g(X_{n-k:n})
    }
      {
\EE
\left[
        \left(
          \,
      g(X_0)
      -
      g(u_n)
        \right)
      \mathbbm{1}
      \left\{
        X_0>u_n
      \right\}
\right]
      }
      \frac{k}{n}
      \ - \ 1
      \right)
      \,
      , \
      r_n
      \left(
      \frac
      {
        X_{n-k :n}
      }
      {u_n}
    \ - \
    1
      \right)
    \right]
      \end{align*}
      converges in distribution to
      $
      \left[
      \Phi
      \ - \
      c\cdot
      \Psi
      \,,
      \Psi
      \right]
      $ as $n\to\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:gcan of arXiv:2603.27906, 'Marked GUE-corners process in doubly periodic dimer models'] Let $R_2>R_1>0$, then
 \begin{multline}
\mathcal{J}_d=
\frac{1}{(2\pi\mathrm{i})^2}\int_{\tilde \Gamma_s'}\int_{\tilde \Gamma_l'}
\boldsymbol{\mathcal{M}}_{i_1,j_1,i_2,j_2}(z_1,w_1;z_2,w_2) 
\exp\left({N(G(z_2,w_2)-G(z_1,w_1))}\right)
\frac{w_1^{r_1}}{w_2^{r_2}}
 \frac{z_1^{\mu_1\sqrt{N}}}{z_2^{\mu_2\sqrt{N}}}
 \frac{\,\mathrm{d} z_2\,\mathrm{d} z_1}{z_2(z_2-z_1)}
\\+N^{-\frac{1}{2}}\frac{h(\ell x_2+i_2,2y_2+j_2)}{h(\ell x_1+i_1,2y_1+j_1)}\mathcal{O}\left(e^{-\frac{\sigma^2}{4}\log^2 N}\right),\quad \text{as}\quad N\rightarrow\infty
\end{multline}
where the curves of integration have been replaced by $\widetilde{\Gamma}_s'$, a circle of radius $\frac{R_1}{\sqrt{N}}$ around $q_{\infty}$ and $\widetilde{\Gamma}_l'$ is a curve to the right of $\widetilde{\Gamma}_s'$ first treading over a half-circle of radius  $\frac{R_2}{\sqrt{N}}$ and then from  $z_2=1+i\frac{R_2}{\sqrt{N}}$ to $z_2=1+i\frac{\log N}{\sqrt{N}}$ along the $y$ axis and from $z_2=1-i\frac{R_2}{\sqrt{N}}$ to $z_2=1-i \frac{\log N}{\sqrt{N}}$ along the $y$-axis, see Figure (fig:local_sight of the paper). The implicit constant in the remainder term is uniform on compact subsets of $\Lambda_{\{0,1\}}^2$.

