[Coro advanced geographic ineq coupling map of arXiv:2604.21663, 'Large deviations for non-irreducible Markov chains on Euclidean spaces'] Let $n\in \mathbb N$ be such that $\tau_{K}/n\leqslant \delta$ and $n(1-\varepsilon-\delta)\geqslant 1$, let $T\in \mathbb N$ be such that $n+r\tau_{K}\leqslant T\delta$, and let\footnote{This choice of $N$ satisfies $T\geqslant Nn+Nr\tau_K$.}
	\begin{equation*}
		N=\left\lfloor\frac T{n+r\tau_K}\right\rfloor.
	\end{equation*}
	Let
	$\underline u=(u^1,\ldots ,u^N)\in \widetilde{\mathcal{W}}_n^N$ be such that $d_{\mathrm{LP}} (L[u^i], \mu_1)\leqslant \delta$ when $i$ is odd and $d_{\mathrm{LP}} (L[u^i], \mu_2)\leqslant \delta$ when $i$ is even. Then,
	for all $w\in \Psi_{N,n,T}(\underline u)$,
	\begin{equation}

		d_{\mathrm{LP}}(L[w], \mu)\leqslant 4h\Big((1-\varepsilon-\delta)\frac{1-\delta}{1+r\delta}\Big)+3\delta=:f(\varepsilon, \delta).
	\end{equation}

