body:
[Lemma l: fourier smooth differentiation of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Suppose that $f\in L^1(\R^d, \C)$ is Fourier-smooth with exponent $p\in (d, \infty)$. Then $f$ is $\lceil \tfrac{p-d}{2}-1\rceil$-times continuously differentiable and every component of the $q$-th derivative $f^{(q)}$ is Fourier-smooth with exponent $p-2q$ for $q\in\{0,..., \lceil \tfrac{p-d}{2}-1\rceil\}$.
    \begin{proof}
        Since $f$ is Fourier-smooth with exponent $p>d$, we know that, by~(equation e: fourier smooth 12 of the paper),
        \begin{equation*}
            (1+\|k\|)^{ \big\lceil\tfrac{p-d}{2}-1\big\rceil}|\hat{f}(k)|\leq c \frac{(1+\|k\|)^{ \big\lceil\tfrac{p-d}{2}-1\big\rceil}} {(1+\|k\|)^{\frac{d+p}{2}}} = c \frac{1}{(1+\|k\|)^{d+\big(\tfrac{d+p}{2}-\big\lceil\tfrac{p+d}{2}-1\big\rceil\big)}}, \quad k\in\R^d,
        \end{equation*}
        for some $c>0$. Since the exponent in the denominator of the right-most side is strictly greater than $d$, this fact implies that $k\mapsto (1+\|k\|)^{ \big\lceil\tfrac{p-d}{2}-1\big\rceil}|\hat{f}(k)|$ is integrable, whereby $f$ is \linebreak $\lceil \tfrac{p-d}{2}-1\big\rceil$-times continuously differentiable. The Fourier-smoothness of the components of $f^{(q)}$ then is a direct consequence of the fact that
        \begin{equation*}
            \|\widehat{f^{(q)}}(k)\|=\|k^{\otimes q}\hat{f}(k)\|\leq \|k\|^q |\hat{f}(k)|, \quad k\in\R^d.
        \end{equation*}
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma of arXiv:2604.15146, 'Renormalised two-point functions of CLE$_4$ gaskets'] Suppose we are in the set-up of Theorem (thm:convbls of the paper) with $a > 0$. Consider the boundary cluster that is given by the closed union of all critical Brownian loop soup clusters that intersect at least one boundary to boundary excursion, denote it by $\widetilde C_{a}^{m}$ for the metric graph, and by $C_{a}$ for the continuum.

Then for any $z_1, \dots, z_n \in D$, and any 
$\varepsilon_1, \dots, \varepsilon_n > 0$, 
we have that the probabilities
$$\tilde p^{\rm bd}_{a,m} := \mathbb{P}\left(\nexists \widetilde \gamma \in \widetilde C_{a}^m\text{ such that} \sum_{j=1}^{n}
\indx_{\widetilde \gamma}(z_j)
\text{ odd}
 \: \& \: \widetilde C_{a}^{m} \cap \bigcup_{j=1}^n\mathbb{D}(z_j, \varepsilon_j) = \emptyset\right),$$  

converge, as $m \to \infty$, to 
$$p^{\rm bd}_a := \mathbb{P}\left(\nexists \gamma \in C_{a}\text{ such that} \sum_{j=1}^{n}
\indx_{\gamma}(z_j)
\text{ odd}
 \: \& \: C_{a} \cap \bigcup_{j=1}^n\mathbb{D}(z_j, \varepsilon_j) = \emptyset\right).$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 13 (CLT for empirical Sinkhorn potentials) of arXiv:2604.23461, 'Scaling limit of Sinkhorn-rescaled Random Matrices \\ via Stability of Static Schrödinger '] Let $\X$ be a random matrix satisfying Assumption \ref{assump:random_matrix} with mean $\bLambda$ subject to a margin $(\r,\c)$ meeting Assumption \ref{assump:bounded_cost}, and let $\bSigma = \text{Cov}(\textup{vec}(\X))$ denote its covariance matrix. Let $\bar{\X}_M$ be the empirical mean of $M$ independent copies of $\X$. 

	Let $\bLambda^{\r,\c} = \D(e^{\balpha}) \bLambda \D(e^{\bbeta})$ denote the exact scaled mean matrix. Define the symmetric block matrix $\mathbf{L} \in \R^{(m+n) \times (m+n)}$ and the linear operator $\mathbf{H} \in \R^{(m+n) \times mn}$ by:
	\begin{align}
		\mathbf{L} := \begin{pmatrix}
			\D(\r) & \bLambda^{\r,\c} \\
			(\bLambda^{\r,\c})^\top & \D(\c)
		\end{pmatrix}, 
		\qquad 
		\mathbf{H} \, \textup{vec}(\Delta) := \begin{pmatrix}
			\big(\D(e^{\balpha}) \Delta \D(e^{\bbeta})\big) \mathbf{1}_n \\
			\big(\D(e^{\balpha}) \Delta \D(e^{\bbeta})\big)^\top \mathbf{1}_m
		\end{pmatrix}.
	\end{align}
	Let $\mathbf{L}^{\dagger}$ denote the Moore-Penrose pseudoinverse of $\mathbf{L}$. As $M \to \infty$, the scaled empirical potentials converge in distribution:
	\begin{align}
		\sqrt{M}\begin{pmatrix}
			\balpha_{\bar{\X}_M} - \balpha\\
			\bbeta_{\bar{\X}_M} - \bbeta
		\end{pmatrix}
		\xrightarrow{d}
		\mathcal{N}\left(0,  \mathbf{L}^{\dagger} \mathbf{H} \bSigma \mathbf{H}^{\top} (\mathbf{L}^{\dagger})^\top \right).
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma p<2 moment bound for uniform on disk of arXiv:2605.29095, 'Asymptotics of the number of components of random polynomial lemniscates'] [Ghosh-numberofcomponents]
     Let $X$ be a uniform random variable on the open unit disk $\mathbb{D}$. For $ p<2 $, there exists a constant $C_p$ such that for all $ z \in \mathbb{D}$,
    \begin{align}
            \mathbb{E}\left[\frac{1}{|z-X|^p}\right] \leq C_p.
        \end{align}
        Furthermore, 
        \begin{equation}
             \mathbb{E}\left[\frac{1}{z-X}\right]  = \overline{z}.
        \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:general of arXiv:2509.16694, 'A central limit theorem for two-dimensional directed polymers with critical spatial correl'] Let $\{Z_N\}_{N \in {\mathbb N}}$ and $\{Z_{k,M,N}\}_{1 \le k \le M, \, M , \, N \in {\mathbb N}}$ be respectively a sequence of positive random variables and an array of random variables with mean one and finite variance, satisfying the following conditions:        \begin{enumerate}[label=(\roman*)]
            \item  \emph{Independence:} for $M,N\in\mathbb N$, $\{Z_{k,M,N}\}_{ 1 \le k\leq M}$ is a collection of independent random variables.    
            \item \emph{Decoupling in $L^2$:} for $M\in\mathbb N$, $Z_N$ admits a multiplicative approximation in $L^2$, i.e.\ \begin{equation}

             Z_N - \prod_{k=1}^{M} Z_{k,M,N} \xrightarrow[N \to \infty]{L^2} 0\,.
            \end{equation}        
    \end{enumerate}
    Moreover, denoting the centered variables $U_{k,M,N}:=Z_{k,M,N}-1$, we assume:
    \begin{enumerate}[label=(\roman*), start=3]
        \item  \emph{Second moment convergence:} there exists $\sigma_M^2>0$ and $\sigma^2>0$ such that
        \begin{equation}

        \lim_{N \to \infty} \sum_{k=1}^M \mathbb{E} \big[ U_{k,M,N}^2 \big] = \sigma_M^2\,, \, \ \text{for }M \in {\mathbb N} \qquad \text{and} \qquad \lim_{M \to \infty} \sigma_M^2 = \sigma^2\,.
        \end{equation}
        \item  \emph{Lyapunov condition:}
        \begin{equation} \exists \, \varepsilon_0>0 : \quad \limsup_{M\to\infty} \,\limsup_{N\to \infty}\, \sum_{k=1}^M \mathbb{E}\big[ \big|U_{k,M,N}\big|^{2+\varepsilon_0} \big]=0\,.
        \end{equation}
    \end{enumerate}
Then, $\log Z_N \, \stackrel{{ (d)}}{\longrightarrow} \, \mathcal{N}\left(-\frac{\sigma^2}{2},\sigma^2\right)\,.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 55 of arXiv:2608.29585, '2608.29585'] For every $s\ge1$ and $k\ge0$,
\begin{equation}
 \prod_{i=0}^{k-1}\{s+i\}\in(q;q)_k\Z[q^{\pm1}].
\end{equation}

[Theorem 25 of arXiv:2607.27150, 'Modelling Anomalous Diffusion: The Role of CTRWs and Non-Local Dynamics'] Let $D$ be regular for $A$ and $\mathpzc{l}(D)<+\infty$, and $f\in \BB_b(D)\cap C_{loc}^2(D)$. The  problem
		\begin{align}
			\begin{cases}
				\partial_t u(x,t)=-\Lpsi u(x,t), & x\in D,\,t>0,\\
				u(x,t)=0,& x\in D^c,\, t>0,\\
				u(x,0)=f(x),& x\in D,
			\end{cases}
		\end{align}
		has a pointwise solution $u(x,t)\coloneqq \mathds{E}^x[f(A^D(t))]=\mathds{E}^x[f(A(t));t<T_D]$, and $u(x,t)\to u(x,0)$ as $t\to 0$, for all $x\in D$.

