[Lemma L:F_tht of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] \begin{enumerate}[\rm (i)]
    \item If $s_1 = s_2 = s$, then $F_{\theta}(s,s)$ is convergent if and only
      if $-3 < \theta < -1$, and in that case it holds that
      \begin{gather}
        F_{\theta}(s,s) =
        \begin{dcases}
          \frac{\Gamma( 1+ \theta) \sin (\theta \pi/2)}{2^{2 + \theta}} s^{-1-\theta}, & \theta \in (-3,-1)\setminus \{-2\},\\
          \frac{\pi}{2}s, & \theta = -2.
        \end{dcases}
      \end{gather}

    \item If $s_1 < s_2$, then $F_{\theta}(s_1,s_2)$ is nonnegative and finite
      if and only if $-3 < \theta < 0$, and in that case it holds that
      \begin{gather}
        F_{\theta}(s_1,s_2) =
        \begin{dcases}
          \frac{1}{2} \Gamma(1+\theta)\sin\left(\frac{\pi\theta}{2}\right) \left( (s_2 + s_1)^{-1-\theta} -  (s_2 - s_1)^{-1-\theta} \right), & \theta \in (-3, 0)\setminus \{-2, -1\}, \\
          \frac{\pi}{2} s_1,                                                                                                                  & \theta = -2,                            \\
          \frac{1}{2} \log \left(\frac{s_1 + s_2}{s_2 - s_1} \right),                                                                         & \theta = -1.
        \end{dcases}
      \end{gather}

  \end{enumerate}

[Theorem 22 of arXiv:2608.18075, '2608.18075'] For every $T>0$,
