[Lemm l:edge-L2-resampling of arXiv:2607.18194, 'Temperature chaos in directed polymers'] For all sufficiently small $\varepsilon>0$ and all $k\in\{0,M\}$,
    \begin{align*}
        \limsup_{n\to\infty} \frac{1}{n^{2/3}}\mathbb{E}_\mathrm{re}\left[
            \left|
                \mathcal{H}^{\xi,(n)}_{{\,\mathrm{TF}_k}} - \mathcal{H}^{\eta_k, (n)}_{{\,\mathrm{TF}_k}}
            \right|^2
            \1_{\xi,\eta_k \in \mathsf{Good}_{\varepsilon,n}}
        \right]
        &\leqslant 4\varepsilon^{2\gamma/3}\log^8(1/\varepsilon).
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 39 of arXiv:2605.11801, 'A non-local singular non-linear Fokker-Planck PDE'] A solution to  the McKean  rough martingale problem


  with  drift $ F(K*\,\cdot\,)b$ and initial condition $v_0$,   is  a Borel  probability measure $\P$ on  $\Omega^d_T$,
  such that the following hold.
\begin{itemize}
\item[-] The time marginals of $\P$ admit a density for each time $t\in[0,T]$, denoted by $v(t)$;
\item[-] $v: [0,T ]\times\R^d  \to \R$  is an element of $C_T \mathcal C^{\be}$;
\item[-] $\P$ solves the rough martingale problem rMP$(B,\nu)$ according to Definition \ref{def:rMP} with
 $B:=F(K*v)b$ and $\nu(dx) = v_0(x) dx$. 
\end{itemize}
We denote it by McKean--rMP$(F(K*\, \cdot \,)b,v_0)$ for shortness\footnote{The notation $F(K*\, \cdot \,)b$ is due to the fact that the density  $v$ is unknown, and thus it is not part of the given coefficients.}.

[Lemma 23 of arXiv:2608.30875, 'A Decomposition Theorem for Topological Semi-small Maps'] Let $f:X \longrightarrow Y$ be an almost covering map from a closed topological $n$-manifold $X$ to a closed topological $n$-pseudomanifold $Y$. Let $R$ be the fibered set of $f$ and suppose the restriction $f|_{f^{-1}(R)}:f^{-1}(R)\longrightarrow R$ is a fiber bundle with fiber $F$. Set $B:=f^{-1}(R)$. Assume $R$ and $F$ are closed topological manifolds, the normal bundle of $B$ in $X$ exists and is orientable, and the link of every $x\in B$ in $X$ is homeomorphic to a sphere. Let $k:B\hookrightarrow X$ and $i:X\setminus B\hookrightarrow X$ be the inclusion maps. Then the distinguished triangle
	   \begin{align}
	   	Rf_{\ast}Rk_{\ast}\underline{\mathbb{Q}}_{B}[-c_B]
	   	\longrightarrow
	   	Rf_{\ast}\underline{\mathbb{Q}}_{X}
	   	\longrightarrow
	   	Rf_{\ast}Ri_{\ast}\underline{\mathbb{Q}}_{X\setminus B}
	   	\xrightarrow{[1]}
	   \end{align}
	   does not split.

