[Theorem thm:lbstrthm2 of arXiv:2607.26551, 'An RDT based confirmation of Lehner's formula for Kronecker-Gaussian matrices'] Assume the setup of Theorem (thm:lbstrthm1 of the paper). Let $\bar{L}$ be as in ((eq:hrd9b0 of the paper)). Set 
\begin{eqnarray}

Z_{1}^T  =   \sum_{i=1}^{l}  F_i G_i^{(x,1)}  
 \quad \mbox{and}\quad
 Z_{2}^T  =   \sum_{i=1}^{l}  F_i G_i^{(x,2)}   ,
\end{eqnarray}
and
\begin{eqnarray}

W_1=\Lambda+2\Gamma \quad \mbox{and}\quad 
W_2= -\Lambda+2\Gamma.
\end{eqnarray}
Let
\begin{equation}

\bar{L}^{(2,G)} \triangleq
\sqrt{2} \left (  \frac{1}{4} \mbox{Tr} ((Z_{1}+Z_2)^T(Z_1+Z_2)W_1^{-1}) + \frac{1}{4}\mbox{Tr}((Z_1-Z_2)^T(Z_1-Z_2)W_2^{-1})  +2\mbox{Tr}(\Gamma) + \mbox{Tr}(\Lambda Q) \right ).
\end{equation}
  One then has  
\begin{eqnarray}

\lim_{n\rightarrow \infty } \frac{1}{\sqrt{n}} {\mathbb E} D^{(2)}(t) 
 \leq  
\lim_{n\rightarrow \infty } \frac{1}{\sqrt{n}} {\mathbb E} L^{(2)}(t) 
 \leq  
\lim_{n\rightarrow \infty }  \frac{1}{\sqrt{n}} {\mathbb E}  \min_{\Gamma=\Gamma^T,\Lambda=\Lambda^T}  \bar{L}^{(2,G)} .
\end{eqnarray}

[Theorem 1 of arXiv:2607.23427, '\textbf{A note on Latała's argument in SK model}'] Let $\beta\geq0$ and $h\in \mathbb R$, and suppose that
\begin{equation}
\rho(\beta,h) = \beta^2\kappa(q(\beta,h))
<1,
\end{equation}
Then, the overlap concentration holds in the sense that there exists a constant $C=C(\beta,h)<\infty$ such that
\begin{equation}
\E\braket{(R_{12}-q)^2}\leq \frac{C}{N}.
\end{equation}
Consequently, we have the quantitative estimate of the replica symmetric free energy $\phi^{\mathrm{RS}}(\beta,h)$:
\begin{equation}
0\leq \phi^{\mathrm{RS}}(\beta,h)-\phi_N\leq \frac{C}{N}.
 \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 15 of arXiv:2605.13727, 'Stochastic evolution equations\\ driven by arbitrary cylindrical Lévy processes'] Assume that the following assumptions are satisfied:
\begin{enumerate}
	\item [{\rm (A1)}] $(S(t))_{t\ge 0}$  is a contraction semigroup on $H$;
	\item [{\rm (A2)}] there exists a constant $c_\drift$ such that 
	\[   \norm{\drift(h_1)-\drift(h_2)}\le c_\drift \norm{h_1 -h_2}\qquad\text{for all }h_1,h_2\in H; \]
	\item[{\rm (A3)}] there exists a constant $c_\diff$ such that 
	\[   \norm{\diff(h_1)-\diff(h_2)}_{L_2(U,H)}\le c_\diff \norm{h_1 -h_2}\qquad\text{for all }h_1,h_2\in H. \]
\end{enumerate}
Then there exists a unique mild solution to Equation \eqref{eq.equation}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition lower bound proposition of arXiv:2606.01683, 'Singular-value gap of nonreversible Markov processes'] For every $t>0$,
\begin{align*}
\sup_{s \in [t,2t]} \delta_s^{U + V}
\ge
\frac{1}{\frac32   t\mkern1mu \gamma_V+3}.
\end{align*}

[Lemma lem-rasemote of arXiv:2510.13733, 'Internal Diffusion Limited Aggregation \\ with Critical Branching Random Walks'] Assume that $d \geq 3$. 
For arbitrary  $R>0$ let  $x\in B_R$ and $y\in B_R \cup\partial B_R$. Then there is an absolute constant $\kappa$ such that 
\begin{equation}
\mathbb{P}\big( H_y(S^x)\le H_{\partial B_R} (S^x) \big)\le \kappa \cdot \frac{1}{\|x-y\|^{d-2}}
 \cdot \Big(1\wedge \frac{(R-\|y\|+1)}{\|x-y\|}\Big)\cdot \Big(1\wedge \frac{(R-\|x\|+1)}{\|x-y\|}\Big).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 10 (Jet identifiability) of arXiv:2609.01319, 'Matched Queries for Curvature and Density at Branching Junctions'] Fix distinct directions $v_1,\ldots,v_s\in\Sph^{D-1}$ and positive weights $w_1,\ldots,w_s$. The map
\begin{equation}
\{(a_j,k_j)\}_{j=1}^s\longmapsto G

\end{equation}
is injective over $a_j\in\R$ and $k_j\in v_j^\perp$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma of arXiv:2602.19773, 'Regularization of a stationary point process by a stationary increments perturbation'] Let $\xi$ be a stationary point process with finite second moment and $f : \mathbb{R}^{d} \longrightarrow \mathbb{R}_{+}$ be a measurable mapping satisfying 
		\begin{equation*}
			f(t) \underset{\|t\|\to +\infty}{=}O\left(\|t\|^{-(d+1)}\right)
		\end{equation*}
		Then, 
		\begin{equation*}
			\@ifnextchar[{\@withe}{\@withoute}{\int_{\mathbb{R}^{d}}f(t) \, \hat{\xi}(\mathrm{d}t)} < +\infty. 
		\end{equation*}

[Theorem 3 (Exact primitive kernel) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] Let $q\ge2$ and let $k=[f_n]_{\mathcal U}\in\cH_q$.  The following
conditions are equivalent.
\begin{enumerate}[label=\textup{(\roman*)}]
 \item $k\in\cK_q$.
 \item For every $1\le r<q$ and every $u=[u_n]\in\cH_r$,
 \begin{equation}
  [f_n\otimes_ru_n]_{\mathcal U}=0.

 \end{equation}
 \item For every $1\le r<q$,
 \begin{equation}
  \Ulim\norm{L_{f_n,r}}_{\op}=0.

 \end{equation}
 \item For every $1\le r<q$,
 \begin{equation}
  \Ulim\norm{f_n\otimes_rf_n}=0.

 \end{equation}
\end{enumerate}
Equivalently, if $M_{r,u}v=u\wtensor v$, then
\begin{equation}
 \boxed{\displaystyle
 \cK_q=\bigcap_{r=1}^{q-1}\ \bigcap_{u\in\cH_r}
 \Ker M_{r,u}^*.}

\end{equation}

Moreover, if $k=[f_n]\in\cK_p$ and $\ell=[g_n]\in\cK_q$, then
\begin{equation}
 \Ulim\norm{f_n\otimes_rg_n}=0

\end{equation}
for every contraction which is not total, that is, except possibly when
$p=q=r$.

