[Cor TypeIII of arXiv:2411.12149, 'Airy limit for $\beta$-additions through Dunkl operators'] \begin{align*}
   & \frac{1}{\mu_{+}(N)^{M_{1}+\ldots+M_{l}}}\cdot \prod_{j=1}^{l}\left[\left(\frac{\mathcal{D}_{1}}{N}\right)^{M_{j}}+\ldots+\left(\frac{\mathcal{D}_{N}}{N}\right)^{M_{j}}\right]G_{N}(\vec{x};\beta)\Bigg|_{\vec{x}=0}\\
    =&\sum_{\substack{(i_{1},\ldots,i_{l})\\ \text{mutually\ distinct}}}\sum_{(E,\vec{q})\in \tilde{\mathcal{B}}(i_{1},\ldots,i_{l})\cap\mathcal{C}}w(E,\vec{q}) +o(1)=N(N-1)\cdots(N-l+1)\sum_{(E,\vec{q})\in \tilde{\mathcal{B}}(1,\ldots,l)\cap\mathcal{C}}w(E,\vec{q}) +o(1),
\end{align*}
where the $o(1)$ term vanishes as $N\to \infty$.

