[Lemma 21 (Rank invariance under reduced coordinates) of arXiv:2604.10792, 'Variable-Length Markov Chains on Finite Quivers: Boundary-Window Identifiability, Exact De'] For every visible depth $\ell$ and tangent block $T\subset T_{\theta_0}\Theta$,
\begin{equation}
\rank\bigl(D\bar q_{\cQ}^{(\ell)}(\theta_0)|_T\bigr) = \rank\bigl(Dq_{\cQ}^{(\ell)}(\theta_0)|_T\bigr).
\end{equation}

[Theorem thm:SW of arXiv:2608.16915, 'Exact mean--covariance dynamics of the Weber field in the stochastic Lagrangian representa'] Let $u$ be a maximal classical periodic solution on $[0,T_*)$, and let
$\bar F=M^\top N+\mathcal R$ as in (equation eq:decomp of the paper), so that $u=\mathbb{P}\bar F$. For
$1<p\le\infty$, $1<q<\infty$ and any interval $I=(\tau,T_*)$,
\begin{equation}
  C_q^{-1}\,\left\lVert u\right\rVert_{L^p(I;L^q)}
  \ \le\ \Bigl\|\,t\mapsto\left\lVert [\bar F(t)]\right\rVert_{L^q/\nabla W^{1,q}}\Bigr\|_{L^p(I)}
  \ \le\ \left\lVert u\right\rVert_{L^p(I;L^q)} .
\end{equation}
If $q>3$ and $2/p+3/q\le1$, finiteness of the middle quantity implies that $u$ extends
past $T_*$; the same conclusion holds at the endpoint $(p,q)=(\infty,3)$ by the
backward-uniqueness theorem of Escauriaza, Seregin and \v Sver\'ak
[EscauriazaSereginSverak2003], whose localization to the periodic setting is
standard.

[Prop 26 of arXiv:2511.10535, 'Eigenvalues of Brownian Motions on $\mathrm{GL}(N,\mathbb{C})$'] In the setting of Definition \ref{tech1}, for any monomial $M$ (with coefficient 1) in non-commutative variables $(X_{i,I})_{i\in [1,d],I\in J_n}$ we have
	\begin{equation}

		0 \leq \tau\left(M(\bs x^{T_n})\right) \leq \E[M(g)],
	\end{equation}
	\begin{equation}

		0 \leq \E\left[\tau_N\left(M(\bs X^{N,T_n})\right)\right] \leq \E[M(g)],
	\end{equation}
	where $g=(g_{i,I})_{i\in[1,d],I\in J_n}$ are centered real Gaussian random variables of variance $1$ such that $g_{i,I}$ and $g_{j,J}$ are independent if $i\neq j$ and equal otherwise.

	In particular, given $c_M\in\C$ and $a_M\in\R^+$ such that $|c_M|\leq a_M$, then
	\begin{equation}

		\left| \E\left[\tau_N\left(\sum_{M \text{ monomial}}c_M M(\bs X^{N,T_n})\right)\right] \right| \leq \E\left[\sum_{M \text{ monomial}}a_M M(g)\right],
	\end{equation}
	and similarly for $\bs x^{T_n}$ instead of $\bs X^{N,T_n}$.

[Proposition MEEETTTT of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Consider the equation in Theorem (SSRR of the paper) and assume that \(\varphi\) is the cocycle defined for this equation (restricted to \((E_{\omega})_{\omega \in \Omega}\)). Further, assume that \(\{Y_\omega\}_{\omega \in \Omega}\) is a stationary point of this cocycle such that
			\begin{align}
				\Vert Y_\omega\Vert_{E_\omega} \in \bigcap_{p \geq 1} L^{p}(\Omega).
			\end{align}
			Then \(\varphi\) is differentiable (in the Fréchet sense), and for \(\psi^{m}_{\omega} := D_{Y_{\omega}}\varphi^{m}\), the linear cocycle property holds. That is, for \(p, q \in \mathbb{N}\), we have
			\[
			\psi^{p+q}_{\omega} = \psi^{p}_{\theta_{rq} \omega} \circ \psi^{q}_{\omega}.
			\]
			Furthermore, for every \(m \in \mathbb{N}\), the function \(\psi^{m}_{\omega}: E_\omega \to E_{\theta_{mr} \omega}\) is linear. For \(\mu \in \mathbb{R}\), set
			\[
			F_{\mu}(\omega) := \left\{ x \in E_\omega : \ \limsup_{m \rightarrow \infty} \frac{1}{m} \log \Vert \psi^{m}_{\omega}(x) \Vert_{E_{\theta_{mr}\omega}} \leq \mu \right\}.
			\]
			Then, we have:
			\begin{itemize}
				\item There exists a measurable $\theta_r$-invariant set $\tilde{\Omega} \subset \Omega$ of full measure, along with a decreasing sequence $\{\mu_i\}_{i \geq 1}$ of Lyapunov exponents, $\mu_i \in [-\infty, \infty)$, which have the properties $\lim_{n \to \infty} \mu_n = -\infty$ and either $\mu_i > \mu_{i+1}$ or $\mu_i = \mu_{i+1} = -\infty$. For each $\omega \in \tilde{\Omega}$, we have $F_{\mu_1}(\omega) = E_{\omega}$, and
				\begin{align}
					x \in F_{\mu_{i}}(\omega) \setminus F_{\mu_{i+1}}(\omega) \quad \text{if and only if} \quad \lim_{m \rightarrow \infty} \frac{1}{m} \log \Vert \psi^m_{\omega}(x) \Vert_{E_{\theta_{mr}\omega}} = \mu_{i}.
				\end{align}
				Moreover, there exist integers $m_1, m_2, \ldots$ such that $\operatorname{codim} F_{\mu_j}(\omega) = m_1 + \ldots + m_{j-1}$ for each $\omega \in \tilde{\Omega}$. Furthermore, for every $i \geq 1$ with $\mu_i > \mu_{i+1}$ and $\omega \in \tilde{\Omega}$, there exists an $m_i$-dimensional subspace $H^i_\omega$ with the following characteristics:
				\begin{itemize}
					\item[(i)] \textbf{(Invariance)}\ \ $\psi_{\omega}^k(H^i_{\omega}) = H^i_{\theta_{kr} \omega}$ for each $k \geq 0$.
					\item[(ii)] \textbf{(Splitting)}\ \ $H_{\omega}^i \oplus F_{\mu_{i+1}}(\omega) = F_{\mu_i}(\omega)$. Specifically,
					\begin{align*}
						E_{\omega} = H^1_{\omega} \oplus \cdots \oplus H^i_{\omega} \oplus F_{\mu_{i+1}}(\omega).
					\end{align*}
					\item[(iii)] \textbf{(Fast-growing subspace)}\ \ For every $h_{\omega} \in H^{i}_{\omega} \setminus \{0\}$,
					\begin{align*}
						\lim_{m \rightarrow \infty} \frac{1}{m} \log \Vert \psi^{m}_{\omega}(h_{\omega}) \Vert_{E_{\theta_{mr}\omega}} = \mu_{i},
					\end{align*}
					and
					\begin{align*}
						\lim_{m \rightarrow \infty} \frac{1}{m} \log \Vert (\psi^{m}_{\theta_{-mr}\omega})^{-1}(h_{\omega}) \Vert_{E_{\omega}} = -\mu_{i}.
					\end{align*}
				\end{itemize} 
			\end{itemize}

[Lemma 24 of arXiv:2412.09290, 'Asymptotics of Harish-Chandra transform and infinitesimal freeness'] Let $\Psi, \Phi$ be two infinitely differentiable at 0 functions
  and consider sequences $(c_n)_{n \in \mathbb{N}}, (c'_n)_{n \in
  \mathbb{N}}$, where
  \[ c_n := \frac{\Psi^{(n)} (0)}{(n - 1) !} \text{\quad and\quad}
     c'_n := \frac{\Phi^{(n)} (0)}{(n - 1) !}, \text{\quad for
     every \ } n \in \mathbb{N}. \]
  Then we have
  \begin{equation}
    \sum_{m = 0}^{k - 1} \frac{k!}{m! (m + 1) ! (k - m - 1) !}  \left.
    \frac{\mathrm{d}^m}{\mathrm{d} x^m} ((\Psi' (x))^{k - m - 1} \Phi' (x))
    \right|_{x = 0} = \sum_{\pi \in \ensuremath{\operatorname{NC}} (k)} \sum_{V \in \pi}
    c'_{|V|} \prod_{W \in \pi; W \ne V} c_{|W|} . 
  \end{equation}

