body:
[Lemma lem:FJ2 of arXiv:2412.03366, 'Regularity of Weighted Tensorized Fractional Brownian Fields and associated function space'] Let $1 \le p \le \infty$  and $\ell_1, \ell_2, m_1, m_2$ be integers such that $\ell_1 \le m_1$ and $\ell_2 \le m_2$. Assume that $g_{\bar{k}}$, $\bar{k} \in \mathbb{Z}^2$, are functions satisfying the following inequality 
\begin{equation}
\forall {\boldsymbol{x}} \in \mathbb{R}^2, \, \vert g_{\bar{k}}(\boldsymbol{x}) \vert \le \frac{C}{\left( 1+2^{\min(\ell_1,m_1)}|x_1 - 2^{-m_1}k_1 \vert \right)^2 \left( 1+2^{\min(\ell_2,m_2)}|x_2 - 2^{-m_2}k_2 \vert \right)^2}.
\end{equation}
for some $C>0$. If one sets  
$$
F = \sum_{\bar{k} \in \mathbb{Z}^2} d_{\bar{k}} g_{\bar{k}},
$$
then
\begin{equation}
\Vert F \Vert_{L^p} \le C \, 2^{-(m_1+m_2)/p} 2^{m_1-\ell_1}2^{m_2 - \ell_2} \left( \sum_{\bar{k} \in \mathbb{Z}^2} \vert d_{\bar{k}} \vert^p \right)^{1/p}.
\end{equation}

[Defn def:valid of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] A bounded, simply connected domain $D$ is \emph{valid} if
    \begin{enumerate}[label=(\roman*)]
        \item $\dim_M(\partial D)<2-\alpha^2/2$, when considering $\field{e^{i\alpha\phi}}$ or $\cos(\alpha\phi)$;
        \item $\mathrm{Leb}(\partial D)=0$, when considering $:\! \sin(\alpha\phi) \!: $.
    \end{enumerate}

[Corollary 6 of arXiv:2605.02771, 'Universality in Deep Neural Networks:\\ An approach via the Lindeberg exchange principle'] Let \(z^{(L+1)}(x)\) be the output of a DNN with weights and biases satisfying \textbf{Assumptions \ref{assum:weights}} and \textbf{\ref{assum:biases}} and with activation function \(\sigma\in C^{3}_b(\R)\). Assuming that 
    \(K^{(\ell)}(x)\) is invertible for \(\ell=1,\ldots,n_{L+1}\), we have
    \begin{equation*}
        \max\{d_{TV}\bigl(z^{(L+1)}(x),\Zcal^{(L+1)}(x)\bigr),\,\Wcal_1\bigl(z^{(L+1)}(x),\Zcal^{(L+1)}(x)\bigr)\}\leq C\sum_{k=1}^{L}\frac{1}{\sqrt{n_{k}}},
    \end{equation*}
    where \(d_{TV}\) denotes the total variation distance. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 23 of arXiv:2606.22611, 'Upper and Lower Bounds on Expected Soft Maxima\\of Gaussian Processes'] For any $\theta \in \cP_N, \bm{t}\in T^N$,
  \begin{align*}
    \lVert\hat{P}_{\bm{t}}- \theta\rVert_{\rm TV } 
    = \frac{1}{N} \min_{\bm{s}\in \cC_{N,\theta}} d_{\rm H} (\bm{t}, \bm{s}),
  \end{align*}
  where $d_{\rm H}(\bm{t},\bm{s}) \deq \sum^N_{i=1}\bm{1}_{\{t_i \neq s_i\}}$ is the Hamming distance between $\bm{t}$ and $\bm{s}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:Birkhoff's ergodic of arXiv:2411.02030, 'Finite ergodic components for upper probabilities'] Let $(\Omega,\mathcal{F},V,T)$ be	an UPPS. Then the following three statements are equivalent:
	\begin{enumerate}
		\item [(i)]  $V$ is of finite ergodic components;
		\medskip
		\item [(ii)]there exist  $Q_1,\ldots,Q_n\in\mathcal{ M}^e(T)\cap\operatorname{core}(V)$ and $A_1,\ldots,A_n\in\mathcal{I}$ satisfying that  $\Omega=\cup_{j=1}^nA_j$, $Q_j(A_j)=1$, and $A_j\cap A_k=\emptyset$ when $j\neq k$ such that for any $f\in B(\Omega,\mathcal{F})$,  
		\begin{equation}
			\lim_{N\to\infty}\frac{1}{N}\sum_{i=0}^{N-1}f(T^i\omega)=\sum_{j=1}^{n}\left(\int fdQ_j\right) \cdot1_{A_j}(\omega),\text{ for }V\text{-a.s. }\omega\in\Omega.
		\end{equation}
		\medskip
		\item [(iii)]there exist  $Q_1,\ldots,Q_n\in\mathcal{ M}(T)\cap\operatorname{core}(V)$ and $A_1,\ldots,A_n\in\mathcal{I}$ satisfying that  $\Omega=\cup_{j=1}^nA_j$, $Q_j(A_j)=1$, and $A_j\cap A_k=\emptyset$ when $j\neq k$ such that for any $f\in B(\Omega,\mathcal{F})$,  
		\begin{equation}
			\lim_{N\to\infty}\frac{1}{N}\sum_{i=0}^{N-1}f(T^i\omega)=\sum_{j=1}^{n}\left(\int fdQ_j\right) \cdot1_{A_j}(\omega),\text{ for }V\text{-a.s. }\omega\in\Omega.
		\end{equation}
	\end{enumerate}

[Proposition of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{prop:tile_and_cell_volume_bounds}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 1$ and let $\varepsilon > 0$.
    Let $\overline{r}_0 > r_0 > 0$, let $(m_i)_{i \in \mathbf{N}}$ satisfy $m_i > (1+\varepsilon)/\varepsilon$ for all $i \in \mathbf{N}$, and suppose that $\overline{r}_0 \leq \varepsilon r_1$. 

    Consider the renormalisation scheme $((\Tile{i}{j})_{j \geq 0})_{i \geq 0}$ associated to the renormalisation scales $(r_i)_{i \geq 0}$.

    Then there exist $c_{\mathrm{vor}}{} = c_{\mathrm{vor}}{}(G,\varepsilon) > 0$ and $C_{\mathrm{vor}}{} = C_{\mathrm{vor}}{} (G,\varepsilon) \ge 1$ such that 

    \begin{equation}
        c_{\mathrm{vor}}{}
        r_{i}^d
        \leq 
        \# \Cell{i}{j} 
        \leq
        C_{\mathrm{vor}}{}
        r_{i}^d,
        \quad
        c_{\mathrm{vor}}{}
        r_{i}^d
        \leq 
        \# \Tile{i}{j} 
        \leq
        C_{\mathrm{vor}}{}
        r_{i}^d,
        \quad 
        \text{and}
        \quad
        c_{\mathrm{vor}}{} 
        m_i^d
        \leq
        \kappa_{i,j}
        \leq 
        C_{\mathrm{vor}}{}
        m_i^d
    \end{equation}

    for any tile $\Tile{i}{j}$ and any cell $\Cell{i}{j}$.

    Further, $\Tile{i}{j} \subseteq B(x_{i,j},C_{\mathrm{vor}}{} r_i)$ for any tile $\Tile{i}{j}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem main of arXiv:2412.03450, 'On intermediate levels of nested occupancy scheme in random environment generated by stick'] Under Assumptions $A$ and $B$ imposed on $(\xi, \eta)=(|\log W|, |\log (1-W)|)$, let $(j_n)_{n\geq 1}$ be a sequence of positive numbers satisfying $\lim_{n\to\infty}j_n=\infty$ and
\begin{equation*}
j_n = o\left((\log n)^{\min \left(1/3,(\alpha-\beta)/(\alpha-\beta+1)\right)}\right),\quad n\to\infty,
\end{equation*}
where $\beta=\rho$ if $m_0<\infty$ and $\beta=\max (\rho, \alpha-\theta)$ if $m_0=\infty$ and $m_1<\infty$. Then
$$\left(\frac{c j_n ^\alpha }{\rho_{\lfloor j_n u \rfloor - 1}(\log n)^{\alpha \lfloor j_n u \rfloor}} K_n(\lfloor j_n u \rfloor )
\right)_{u>0}~\overset{{\rm f.d.d.}}{\longrightarrow}~\left(\int_0^\infty {\rm e}^{-\alpha u y} {\rm d} \mathcal{Z}_\alpha^\leftarrow(y) \right)_{u>0},\quad n\to\infty,
$$
where
\begin{equation}
\rho_i:= \frac{(C\Gamma(\alpha + 1))^i}{\Gamma(\alpha i + 1)}, \quad i\in \mathbb{N}_0:=\{0,1,\ldots\},
\end{equation}
and $\Gamma$ is the Euler gamma-function. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:parity of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] A geodesic Leech labeling satisfies
\begin{equation}
  \nu_A+\nu_B+\nu_A(m-\nu_A)-\chi_A+\chi_B=\ceil{N/2}.
\end{equation}
Moreover, $\chi_A$ and $\chi_B$ are even.

[Lemma 8 of arXiv:2606.09121, 'Truncated Signature Information for Mixed Fractional Brownian Paths'] Let $y\in C([0,1];\R)$ with $y_0=0$, and let $z_u=(u,y_u)$ be equipped with a geometric lift.  Then
\begin{align}
    2\pi_{122}S(z)&=\int_0^1(y_1-y_u)^2\,\dd u,\\
    2\pi_{221}S(z)&=\int_0^1y_u^2\,\dd u.
\end{align}

