[Lemma 9 of arXiv:2606.27520, 'Critical curve of loop percolation on the $d$-regular tree'] Let $\alpha>0$ and $\kappa\geq\kappa_c$. For all distinct vertices $u$ and $v$,  
\begin{equation}
 \mu_\kappa(\ell\,:\, u \xleftrightarrow{\ell} v) = - \log( 1 - \tau_\kappa^{2d(u,v)}).
\end{equation}
In particular, 
\begin{equation}
        \P\big(\exists \ell\in\mathcal L_{\alpha,\kappa}\,:\,u \xleftrightarrow{\ell} v\big) = 1 - (1 - \tau_\kappa^{2d(u,v)})^\alpha \leq 2\alpha\, \tau_\kappa^{2d(u,v)}. 
\end{equation}

[Theorem mdd-HIHS of arXiv:2606.27573, 'Conditional Path Decomposition at the Infimum and Maximum Drawdowns for Spectrally Negativ'] Fix $a<0<b$ and let $r=b-a$.  Under $\mathbb{P}_{a,b}^{<}$, the following identities hold.
\begin{enumerate}[label=\textup{(\roman*)}]
\item For the pre-infimum process,
\begin{equation*}\hspace{-1cm}\small
\mathbb{P}_{a,b}^{<}\{M_{0,H_I}^-<d\}=\begin{cases}
0, & d\le -a,\\
\displaystyle
1-\left[\frac{W^{(\gamma)\prime}(d)W^{(\gamma)}(r)-W^{(\gamma)\prime}(r)W^{(\gamma)}(d)}{W^{(\gamma)\prime}(-a)W^{(\gamma)}(r)-W^{(\gamma)\prime}(r)W^{(\gamma)}(-a) }\right]
\left(\frac{W^{(\gamma)}(-a)}{W^{(\gamma)}(d)}\right),
& -a<d<r,\\
1, & d\ge r.
\end{cases}
\end{equation*}

\item For the intermediate process,
\begin{equation*}
\mathbb{P}_{a,b}^{<}\{M_{H_I,H_S}^-<d\}=\begin{cases}
0, & d\le0,\\[4pt]
\displaystyle
\frac{W^{(\gamma)}(r)}{W^{(\gamma)}(d)}
\exp\left\{-(r-d)\frac{W_+^{(\gamma)\prime}(d)}{W^{(\gamma)}(d)}\right\},
& 0<d<r,\\[12pt]
1, & d\ge r.
\end{cases}
\end{equation*}

\item For the post-supremum process,
\begin{equation*}
\mathbb{P}_{a,b}^{<}\{M_{H_S,T}^-<d\}=\begin{cases}
0, & d\le0,\\[4pt]
\displaystyle
\frac{\big(Z^{(\gamma)}(d)-1\big)\dfrac{W^{(\gamma)\prime}(d)}{W^{(\gamma)}(d)}-\gamma W^{(\gamma)}(d)}
     {\big(Z^{(\gamma)}(r)-1\big)\dfrac{W^{(\gamma)\prime}(r)}{W^{(\gamma)}(r)}-\gamma W^{(\gamma)}(r)},
& 0<d<r,\\[14pt]
1, & d\ge r.
\end{cases}
\end{equation*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:f^d-regular of arXiv:2411.12076, 'Explicit solutions of the SI and Bass models on sparse Erd\H{o}s-R\'enyi and regular netwo'] Let 
	\begin{equation}

		f^{ \text{\rm d-reg}}(t):= \lim_{M \to \infty}\mathbb{E}_{{\cal G}_{M}^{\text{\rm d-reg}}} [f]
	\end{equation}
	denote the expected adoption/infection level in the Bass/{\rm SI }model~{\rm ((eqs:Bass-SI-models-ME of the paper),(eqs:d-regular-network of the paper))} on $\lim_{M \to \infty} {\cal G}_{M}^{\text{\rm d-reg}}$.
	Then 

	\begin{subequations}

		\begin{equation}

			f^{ \text{\rm d-reg}} = 1- [S^{ \text{\rm d-reg}}],
		\end{equation}
		where $[S^{ \text{\rm d-reg}}]$ is the solution of the equation
		\begin{equation}

			\frac{d [S]}{dt} = -[S] \left( p+q \Big(1- 

			\Big(\frac{[S]}{e^{-pt}(1-I^0)}\Big)^{-\frac{2}{d}} [S]
			\Big) \right),
			\qquad [S](0 )= 1-I^0.
		\end{equation}
	\end{subequations}

[Corollary CorNonExpanding of arXiv:2608.02897, 'Local limit theorem and Edgeworth expansions for inhomogeneous random walks on $GL(d,\bbR)'] Let $C_1$ and $\theta_1$ be the numbers from Lemma (ll1 of the paper).
Let $k_0=k_0(C_1)$ be the first positive integer $k$ such that $2C_1{\theta}_1^k\leq 1$. Then
\begin{equation}
\sup_{|t|\leq T}\sup_{j\geq0}\sup_{k\geq k_0}\|{\mathcal L}_{j,it}^k\|_{*}\leq 1
\end{equation}
where $\|{\mathcal L}_{j,it}^k\|_{*}$ is the operator norm with respect to the norm $\|\cdot\|_*$.

[Theorem 1 of arXiv:2609.01403, '2609.01403'] Let \(n\geq2\) and \(0<s<1\). Define
\[
    \Gamma_{n,s}
    =
    \mathcal F^{-1}
    \left(\frac{1}{|\xi|^2+|\xi|^{2s}}\right)
    \in\mathcal S'(\mathbb R^n).
\]
Then
\begin{equation}
    \mathscr{L}_s\Gamma_{n,s}
    =\delta_0
    \qquad\text{in }\mathcal S'(\mathbb R^n),

\end{equation}
and \(\Gamma_{n,s}\) is represented by a smooth real-valued radial
function in \(\mathbb R^n\setminus\{0\}\). Moreover, the following assertions hold.

\begin{enumerate}
\item \textbf{Asymptotics at the origin.}

\begin{description}
\item[\(n\geq3\) and \(4-2s<n\)]
As \(|x|\to0\),
\begin{equation}
\begin{aligned}
    \Gamma_{n,s}(x)
    &=
    \frac{|x|^{2-n}}{(n-2)\omega_{n-1}}
    -\kappa_{n,4-2s}|x|^{4-2s-n}
    +o\!\left(|x|^{4-2s-n}\right),\\
    \nabla\Gamma_{n,s}(x)
    &=
    -\frac{x}{\omega_{n-1}|x|^n}
    -(4-2s-n)\kappa_{n,4-2s}
      x|x|^{2-2s-n}
    +o\!\left(|x|^{3-2s-n}\right).
\end{aligned}

\end{equation}

\item[\(n=3\) and \(s=\frac12\)]
As \(|x|\to0\),
\begin{equation}
\begin{aligned}
    \Gamma_{3,1/2}(x)
    &=
    \frac{1}{4\pi|x|}
    -\frac{1}{2\pi^2}\log\frac1{|x|}
    +O(1),\\
    \nabla\Gamma_{3,1/2}(x)
    &=
    -\frac{x}{4\pi|x|^3}
    +\frac{1}{2\pi^2}\frac{x}{|x|^2}
    +O(1).
\end{aligned}

\end{equation}

\item[\(n=3\) and \(0<s<\frac12\)]
There exists \(C_{3,s}\in\mathbb R\) such that, as \(|x|\to0\),
\begin{equation}
\begin{aligned}
    \Gamma_{3,s}(x)
    &=
    \frac{1}{4\pi|x|}
    +C_{3,s}
    -\kappa_{3,4-2s}|x|^{1-2s}
    +o\!\left(|x|^{1-2s}\right),\\
    \nabla\Gamma_{3,s}(x)
    &=
    -\frac{x}{4\pi|x|^3}
    -(1-2s)\kappa_{3,4-2s}
      x|x|^{-1-2s}
    +o\!\left(|x|^{-2s}\right).
\end{aligned}

\end{equation}

\item[\(n=2\)]
There exists \(C_{2,s}\in\mathbb R\) such that, as \(|x|\to0\),
\begin{equation}
\begin{aligned}
    \Gamma_{2,s}(x)
    &=
    \frac{1}{2\pi}\log\frac1{|x|}
    +C_{2,s}
    -\kappa_{2,4-2s}|x|^{2-2s}
    +o\!\left(|x|^{2-2s}\right),\\
    \nabla\Gamma_{2,s}(x)
    &=
    -\frac{x}{2\pi|x|^2}
    -(2-2s)\kappa_{2,4-2s}
      x|x|^{-2s}
    +o\!\left(|x|^{1-2s}\right).
\end{aligned}

\end{equation}
\end{description}

\item \textbf{Asymptotics at infinity.}

\begin{description}
\item[\(s\neq\frac12\)]
As \(|x|\to\infty\),
\begin{equation}
\begin{aligned}
    \Gamma_{n,s}(x)
    &=
    \kappa_{n,2s}|x|^{2s-n}
    -\kappa_{n,4s-2}|x|^{4s-2-n}
    +o\!\left(|x|^{4s-2-n}\right),\\
    \nabla\Gamma_{n,s}(x)
    &=
    -(n-2s)\kappa_{n,2s}
      \frac{x}{|x|^{n+2-2s}}
    \\&\qquad
    +(n+2-4s)\kappa_{n,4s-2}
      \frac{x}{|x|^{n+4-4s}}
    +o\!\left(|x|^{4s-3-n}\right).
\end{aligned}

\end{equation}

\item[\(s=\frac12\)]
As \(|x|\to\infty\),
\begin{equation}
\begin{aligned}
    \Gamma_{n,1/2}(x)
    &=
    \kappa_{n,1}|x|^{1-n}
    +\kappa_{n,-1}|x|^{-n-1}
    +o\!\left(|x|^{-n-1}\right),\\
    \nabla\Gamma_{n,1/2}(x)
    &=
    -(n-1)\kappa_{n,1}
      \frac{x}{|x|^{n+1}}
    -(n+1)\kappa_{n,-1}
      \frac{x}{|x|^{n+3}}
    +o\!\left(|x|^{-n-2}\right).
\end{aligned}

\end{equation}
\end{description}
\end{enumerate}
All vector-valued little-\(o\) terms are understood with respect to the
Euclidean norm. (Proof in the paper; no proof environment follows the statement in the TeX.)

