body:
[Mycor t4.1 of arXiv:2411.08430, 'The Restricted Isometry Property of Block Diagonal Matrices Generated by $\varphi$-Sub-Gau'] Let $\xi=(\xi_{1},\cdots, \xi_{n})$ be a random vector with independent centered $\varphi$-sub-Gaussian variables and $\mathcal{A}$ is a family of $m\times n$ fixed matrices. We have for $t\ge 0$
	\begin{align}
		&\textsf{P}\Big\{ \sup_{A\in \mathcal{A}}\big\vert \Vert A\xi\Vert_{2}^{2}-\textsf{E}\Vert A\xi\Vert_{2}^{2}  \big\vert>CL_{1}^{2}(U_{1}(1, \infty)+t)\Big\}\nonumber\\
		\le& C_{1}\exp\Big(-\min\Big\{(\frac{t}{\sup_{A\in \mathcal{A}}\Vert A^{\top}A\Vert_{F}})^{2}, (\frac{t}{M_{l_{2}\to l_{2}}^{2}(\mathcal{A})})^{1/2}\Big\}\Big),\nonumber
	\end{align}
	where $U_{1}(1, \infty)$ is defined as above and $L_{1}=\max_{i}\tau_{\varphi}(\xi_{i})$.

