[Lemma return-shift of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Under the assumptions of Theorem~(IP-limit of the paper), define 
\begin{equation}
I=\mathrm{FS}(q_{1},q_{2},\dots ),\qquad I^{\prime }=\mathrm{FS}
(q_{2},q_{3},\dots ),\qquad m=q_{1}.  
\end{equation}
Then:

\begin{enumerate}
\item $a_{n}\rightarrow a^{\ast }$ as $n\rightarrow \infty $ along $n\in I$;

\item $a_{n+m}\rightarrow a^{\ast }$ as $n\rightarrow \infty $ along $n\in
I^{\prime }$;

\item for every $n\in I^{\prime }$, the pair $(n,n+m)$ lies in $I\times I$.
\end{enumerate}

[Theorem LLN0 of arXiv:2411.01731, '$L^2$-Wasserstein contraction of modified Euler schemes for SDEs with high diffusivity and'] Assume that $(i)$ $({\bf A}_0)$ with $\ell_0=0$, $({\bf A}_{4})$ and $({\bf A}_{5})$ with $\ell_0^\star=0$ for the EM scheme (equation WW of the paper);   $(ii)$ $({\bf A}_0)$, $({\bf A}_2)$ and $({\bf A}_{3})$ for the TEM scheme (equation EW0- of the paper);   $(iii)$ $({\bf A}_0)$, $({\bf A}_{4})$ and $({\bf A}_{5})$ for the PEM scheme (equation EWW of the paper).
Then, for any $f\in\mathscr C_\rho$, $\varepsilon\in(0,1/2)$, and $x\in\mathds R^d,$ there exist constants $C_0=C_0(x,\rho,\varepsilon,\|f\|_\rho),\sigma_0>0$ and  a random time $N_{\varepsilon,\delta}=N_{\varepsilon,\delta}(x,\rho,d)\ge 1$    such that for all $\delta\in(0,\delta_2^\star]$,  $n\ge N_{\varepsilon,\delta}$ and the noise intensity  $\sigma$ satisfying  $|\sigma|\ge\sigma_0,$
\begin{equation}
\bigg|\frac{1}{n}\sum_{k=0}^{n-1} f(X_{k\delta}^{\delta,x})-\pi_\8(f) \bigg|\le C_0 \big(n^{-{1}/{2}+\varepsilon}\delta^{-1/2}+\delta^{\gamma_\star}   d^{(\ell_\star+ \rho)/2}\big),\quad a.s.,
\end{equation}
where
$\pi_\8$ means the unique IPM of $(X_{t})_{t\ge 0}$ solving (equation E1 of the paper), and the  quantities $\gamma_\star,\ell_\star$ are the same as those given in Theorem (cor of the paper). Moreover, for any $q>0,$ there is a constant $C_q^*>0$ such that
\begin{align}
	\mathbb E N_{\varepsilon,\delta}^q\le C^*_q\big(1+|x|^{2(1+\rho)} +d^{1+\rho}\big)^{\frac{q+2}{2\varepsilon}}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition thm:observable-suboptimality-eb-rate of arXiv:2608.25551, 'Beyond Optimal Rates in Stochastic Optimization: Trajectory-Adaptive Stopping Rules'] Fix $\alpha \in (0,1)$ and suppose Assumptions~(assump:strong-convexity of the paper)--(assump:stepsize-bound of the paper) and~(assump:bounded-stochastic-gradients of the paper) hold. Let $R_0 = G^2/\mu^2$, $t_0 = 4$, and $\eta_t = 2/(\mu(t+1))$ for every $t \ge 4$. Then there exist universal constants $C, C_{\mathrm r} < \infty$ such that, almost surely,
\begin{equation}

    \widehat U_t^{\mathrm{sub,EB}}(\alpha)
    \le
    C B_{\mathrm{sub}}^{\mathrm{EB}}
    \left[
        \frac{L_t^{\mathrm{sub,EB}}(\alpha)}{t}
        +
        \left(
            \frac{L_t^{\mathrm{sub,EB}}(\alpha)}{t}
        \right)^2
    \right],
    \qquad
    t \ge 4,
\end{equation}
and, whenever $L_t^{\mathrm{sub,EB}}(\alpha) \le t$,
\begin{equation}

    \mathcal R_t^{\mathrm{sub,EB}}(\alpha)
    \le
    C_{\mathrm r} B_{\mathrm{sub}}^{\mathrm{EB}}
    \left(
        \frac{L_t^{\mathrm{sub,EB}}(\alpha)}{t}
    \right)^{3/2}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

