[Theorem examCBO of arXiv:2604.22510, 'Asymptotics of Multi-Scale McKean--Vlasov Diffusions with Super-Linear Kernels: a Lifted S'] Suppose that the assumptions $(\mathbf{A}^1_{\Phi})$-$(\mathbf{A}^4_{\Phi})$ hold. The  functional type law of large numbers holds for the multi-scale CBO model $((eq:examCBOsystem1 of the paper))$-$((eq:examCBOsystem2 of the paper))$, i.e.,
	\begin{align*}
		\mathbb{E}\Big[\sup_{t\in [0, T]}|X_{t}^{\varepsilon}-\bar{X}_{t}|^{2}\Big]\lesssim_T (\varepsilon+\delta^{1/3}),
	\end{align*}
	provided that $\lambda_2$ is sufficiently small, where $\bar{X}_t$ is the solution of the corresponding averaged equation. Moreover,
	if $\delta = o(\varepsilon)$ and $\lambda_3> 0$, then $\{X^{\varepsilon}\}_{\varepsilon\in (0,1)}$ satisfies the LDP. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop pre-coh of arXiv:2510.23430, 'On the Martin boundary for discrete TASEP'] Let $\Phi\in\mathcal F$, $\Phi(0)\neq 0$. Then for any $\mu\in\mathbb{G}^p_n$ we have
\begin{equation}
\sum_{\lambda\in\mathbb{G}^p_{n+1}}g^{(0,p)}_{\lambda}(\Phi) G^{(0,-p)}_{\lambda/\mu}(z)=g^{(0,p)}_{\lambda}(\Phi)\frac{\Phi(z)}{\Phi(0)},
\end{equation}
where the sum converges uniformly on $\overline{\mathbb D}$.

[Definition eq:s_property_1 of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{def:renormalisation_scheme}
    Let $\xi > 0$ and let $\eta = \eta(\xi) = \lceil 2 \left( 1/\xi - 1 \right) \rceil$.

    Let $\overline{r}_0 \geq r_0 \geq 1$ be two large constants. For $\alpha \in (0,2)$, we define $s = s(\alpha,G,\xi)$ to be the least integer satisfying $c_{\mathrm{vor}} (i+s)^{2d} \ge 2$ and

    \begin{align}

        s^{\xi + \alpha}
        & \geq 
        (1 + s)^{\alpha},
        \\

        (1 + s)^{2 + \eta} 
        & > 
        (1 + \xi) / \xi,
        \\

        (1 + s)^{2 + \eta}
        & \geq 
        \overline{r}_0/(\xi r_0),
        \\

        \frac{
            C_G (1 + \xi)^d 
        }{
            c_G (1 - 2 \xi)^d
        }
        (1+s)^{-2d}
        & < 
        1/2
    \end{align}

    simultaneously. For $i \geq 1$ we iteratively define 

    \begin{equation}

        m_i 
        = 
        (i + s)^{2 + \eta}
        \quad 
        \text{and}
        \quad
        r_i 
        = 
        m_i r_{i-1}.
    \end{equation}

    Let $((\Tile{i}{j})_{j \geq 0})_{i \geq 0}$ be the renormalisation scheme associated to the renormalisation scales $(r_i)_{i \geq 0}$.

[Lemma 8 of arXiv:2608.19744, 'Conditioned Brownian motion and local equivalence of path ensembles'] Let $K\subset\mathbb R^d$ be compact.  There exist
$\varepsilon,c,C,\gamma>0$ such that, for all $T\geq1$,
\begin{equation}
 \sup_{x\in K}|\chi_{T,x}(u)|
 \leq C\bigl(\mathrm e^{-cTu^2}+ \mathrm e^{-\gamma T}\bigr),
 \qquad |u|\leq\varepsilon.

\end{equation}
Moreover, locally uniformly in $(x,v)\in\mathbb R^d\times\mathbb R$,
\begin{equation}
 \chi_{T,x}\left(\frac v{\sqrt T}\right)
 \longrightarrow \mathrm e^{-\sigma_\beta^2v^2/2}.

\end{equation}
Finally, for every $0<\delta<R<\infty$, there exist
$C_{K,\delta,R},\eta_{\delta,R}>0$ such that
\begin{equation}
 \sup_{\substack{x\in K\\\delta\leq|u|\leq R}}
 |\chi_{T,x}(u)|
 \leq C_{K,\delta,R}\mathrm e^{-\eta_{\delta,R}T}.

\end{equation}

