[Prop Existence of arXiv:2605.18744, 'Lattice random-field Widom--Rowlinson models'] Assume that $\Lambda_n\uparrow \mathbb{Z}^d$, i.e., $(\Lambda_n)_n$ is an increasing sequence of finite sets with $\bigcup_{n\in \mathbb{N}}\Lambda_n=\mathbb{Z}^d$. Then, for $\zeta \in\mathcal{H}$ and $\lambda\in \mathbb{R}$,
    \begin{enumerate}[label=(\roman*)]
        \item  there are $\mu_{\pm}^{\zeta,\lambda}\in \mathcal{G}(\zeta, \lambda)$ such that the sequence $\mu_{\Lambda_n,\pm }^{\zeta,\lambda}$ converges locally to $\mu_{\pm}^{\zeta,\lambda}$,
        \item for every $f$ local, $\zeta\mapsto \mu_{\pm}^{\zeta,\lambda}(f) $ is measurable when endowing $\mathcal{H}$ with the product-$\sigma$-algebra, and
        \item for every infinite-volume Gibbs measure $\nu^{\zeta,\lambda}$ of the WRM with external field $\zeta$, it holds that
        \begin{align*}
            \mu_{-}^{\zeta,\lambda}\preceq \nu ^{\zeta,\lambda}\preceq \mu_{+}^{\zeta,\lambda}.
        \end{align*}
    \end{enumerate}

[Definition 14 of arXiv:2506.10817, 'On the Weak Error for Local Stochastic Volatility Models'] Let $X,\xi$ be two random variables, such that $\xi$ is square integrable. Let $\eps,\delta\in(0,1/2)$ and $K_\eps$ some Kernel satisfying Assumption \ref{Ass:kernel} below. 
    If $\mathbb{V}(X)>0$ define the estimator $\hE_\delta^\eps$ of the conditional expectation as
    \begin{align}
        \hE_\delta^\eps\bigl[\xi^2\big|X\bigr]=\frac{
        \E\bigl[ \xi^2 K_\eps\bigl(x-X\bigr)\bigr]\big|_{x=X}+\delta
        }{{\E\bigl[ K_\eps\bigl(x-X\bigr)\bigr]\big|_{x=X}}+\delta }.
    \end{align}
    as well as $ \hE^\eps\bigl[\xi^2\big|X\bigr]= \hE^\eps_0\bigl[\xi^2\big|X\bigr]$.
    In case $\mathbb{V}(X)=0$ set $\hE_\delta^\eps\bigl[\xi^2\big|X\bigr]=\hE^\eps\bigl[\xi^2\big|X\bigr]=\E[\xi^2]$.

[Proposition prop_boundtoset_zero of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] For any $d\ge 3$, there exist constants $
	\refstepcounter{newcnstcnt}
	\ensuremath{C_{\thenewcnstcnt}}(d),
	\refstepcounter{cnstcnt}
	\ensuremath{c_{\thecnstcnt}}(d)>0$ such that 
		\begin{equation}
			\mathbb{P}^D\big( A\xleftrightarrow{\ge 0}  \partial B(M) \big) \asymp \mathbb{P}^{D\cup D'}\big( A\xleftrightarrow{\ge 0}  \partial B(M) \big) 
	\end{equation}
	if either of the following two conditions holds:
	\begin{enumerate}
		\item[(a)]  $N\ge 1$, $A,D\subset \widetilde{B}(N)$, $M\ge \ensuremath{C_{\ref*{prop_boundtoset_zero1}}}N$ and $D' \subset [\widetilde{B}( \ensuremath{C_{\ref*{prop_boundtoset_zero1}}}M)]^c$; 


		\item[(b)] $N\ge 1$, $A,D\subset [\widetilde{B}(N)]^c$, $M\le \ensuremath{c_{\ref*{prop_boundtoset_zero2}}}N$ and $D' \subset \widetilde{B}( \ensuremath{c_{\ref*{prop_boundtoset_zero2}}}M)$.
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

