body:
[Definition 7 of arXiv:2608.18834, 'The Parabolic Anderson Model's Total Mass at Small Times: Geometry, Fluctuations, and Reno'] Define the renormalization function $\msf c:(0,\infty)\to\mbb R$ as follows:
\begin{enumerate}
\item If $\rho>0$, then no renormalization
is necessary; hence $\msf c(\eps)=0$ for all $\eps>0$.
\item If $\rho=0$, then $\xi$ needs a logarithmic
renormalization: If $\mf b$ is the constant defined in \eqref{Equation: b Constant}, then
\begin{align}

\msf c(\eps)=\mf b\,\log(1/\eps),\quad\eps>0.
\end{align}
\item If $\rho<0$, then $\xi$ requires a power-law renormalization:
\begin{align}

\msf c(\eps)=\mf d\,\eps^{\rho},\qquad\eps>0,
\end{align}
where we define the constant
\begin{align}

\mf d=
\frac{\Ga(-\rho)}{2^H\Ga(d-H)\Ga(1-H_0)}\prod_{j=0}^d\frac{\Ga(2H_j+1)}{\Ga(H_j)}
\int_0^{\pi/2}\frac{(\cos\theta)^{-(2H_0-1)}(\sin\theta)^{d-H}}{(\cos\theta+\sin\theta)^{-\rho}}\d\theta.
\end{align}
\end{enumerate}

[Theorem thm:recurrent-nonstab of arXiv:2604.13968, 'Divisible sandpiles via random walks in random scenery'] For every $p\in(0,3)$ and every $d_f\in(\max(p,2),3)$, there exists a recurrent bounded-degree graph~$G$ with
		\begin{equation}
			|B(o,R)|\leq C\,R^{d_f}
			\qquad\text{for all } R\geq 1\,,
		\end{equation}
		such that for every $\mu<1$, there is an i.i.d.\ law bounded from below with $\mathbb{E}[\sigma]=\mu$ and $\mathbb{E}[|\sigma-\mu|^p]<\infty$ for which $u_\infty(o)=\infty$ almost surely. Hence the divisible sandpile does not stabilize.
		Moreover, $|B(o,r_k)|\geq c\,r_k^{d_f}$ along a subsequence $r_k\to\infty$, so $\limsup_{r\to\infty}\frac{\log|B(o,r)|}{\log r}=d_f$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition tilt of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] \noindent  Let $w(x_{1},x_{2})=x_{1}x_{2}$ for $(x_{1},x_{2})\in
R^{2}$. We define the \textit{tilted measures} $\tilde{P}_{i}$ by 
\begin{equation}
d\tilde{P}_{i}(x_{1},x_{2})=\frac{w(x_{1},x_{2})}{E^{P_{i}}[w(X_{1},X_{2})]}
\,dP_{i}(x_{1},x_{2})=\frac{x_{1}x_{2}}{E^{P_{i}}[X_{1}X_{2}]}
\,f_{i}(x_{1},x_{2})\,dx_{1}dx_{2}.  
\end{equation}
We denote expectation with respect to $\tilde{P}_{i}$ by $E^{\tilde{P}
_{i}}[\cdot ]$.

[Theorem thm:inhomogeneousBerryEsseensecond of arXiv:2411.16103, 'Non-commutative Stein's Method: Applications to Free Probability and Sums of Non-commutati'] Assume that the sequence $\xi^n$ has dependency graph $E_n$. Then,  under the condition  
\begin{align*}
\lim_{n}\mathcal{D}(E_n)^2\sum_{k=1}^{n}m_3[\mu_{k,n}]=0,
\end{align*} 
we have that for $n$ sufficiently large,  
\begin{align*}
d_{W}(\nu_n,\mathbf{s})
  &\leq C\mathcal{D}(E_n)^{q+1}\sum_{k=1}^nm_{q+1}[\mu_{k,n}],
\end{align*}
for some constant $C>0$ independent of $n$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 3 (Proposition \ref{DecoTheo1}) of arXiv:2608.30875, 'A Decomposition Theorem for Topological Semi-small Maps'] Let $f : X \longrightarrow Y$ be an almost covering such that $X$ and the fibered set $R$ are closed topological manifolds, and $Y$ is a closed topological $n$-pseudomanifold. Assume that the restriction $f|_{f^{-1}(R)} : f^{-1}(R) \longrightarrow R$ is a fiber bundle with fiber $F$, a closed orientable topological manifold, and that $\operatorname{codim}_{X}(f^{-1}(R)) \geq 2$. Let $\overline{p} \in \{\overline{n}, \overline{m} \}$ be a perversity. Moreover,
        \begin{enumerate}
    	\item suppose that the normal bundle of $B:=f^{-1}(R)$ exists and is orientable, and that for each $r \in R$ there is a trivializing neighborhood $U$ of $r$ such that the connecting homomorphism in the Gysin sequence of the normal bundle of $B$ restricted to $f^{-1}(U)$ vanishes in degree $\operatorname{codim}_{X}(B)-1$.
    	\end{enumerate}
    	Let $R(f\vert_{X \setminus B})_{\ast}\underline{\mathbb{Q}}_{X \setminus B} \simeq \underline{\mathbb{Q}}_{Y \setminus R} \oplus \mathcal{L}$, where $\mathcal{L}$ is the local system on $Y \setminus R$ induced by the covering map $f\vert_{X \setminus B}$. If $\overline{p}(\operatorname{codim}_{Y}(R))+1 = \operatorname{codim}_{X}(B)$ and $\operatorname{codim}_{Y}(R)$ is even, then
    \begin{align}
    	Rf_{\ast}\underline{\mathbb{Q}}_{X}[n] \simeq h_{\ast} \big((R^{0}f\vert_{B})_{\ast} \underline{\mathbb{Q}}_{B}[\dim(B)]\big) \oplus IC^{\overline{p}}_{Y} (\underline{\mathbb{Q}}_{Y \setminus R} \oplus \mathcal{L}),
    \end{align}
    where $h: R\hookrightarrow Y$ is the inclusion, and $IC^{\overline{p}}_{Y}$ is Deligne's sheaf complex with respect to the stratification $Y \supset R$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition Quantum sphere of arXiv:2510.05850, 'Three-point connectivity constant for $q$-state Potts spin clusters'] For $W>0$, we define the measure $\mathcal{M}_2^{\rm sph}(W)$ as follows. Write $\alpha=Q-\frac{W}{2\gamma}$ and let $(B_t)_{t \ge 0}$ be a standard Brownian motion conditioned on $B_t-(Q-\alpha)t<0$ for all $t>0$, and $(\widetilde B_t)_{t \ge 0}$ be its independent copy. Let
    \begin{equation*}
        Y_t=
        \begin{cases}
            B_t-(Q-\alpha) t, & \mbox{ for }\,t \ge 0, \\
            \widetilde B_{-t}+(Q-\alpha)t, & \mbox{ for }\,t<0,
        \end{cases}
    \end{equation*}
    and set $h_1(z)=Y_{\mathrm{Re} z}$ for $z \in \mathcal{C}$. Let $h_2$ be a random generalized function with the same law as $h_\mathcal{C}^2$ defined above and independent from $h_1$.
    Sample $\mathbf{c} \in \mathbb{R}$ independently from the measure $\frac{\gamma}{2} e^{(\beta-Q)c} \mathop{}\!\mathrm{d} c$, and set $\phi(z)=h_1(z)+h_2(z)+\mathbf{c}$. The infinite measure $\mathcal{M}_2^{\rm sph}(W)$ is defined as the law of $(\mathcal{C},\phi,-\infty,+\infty)/{\sim_\gamma}$.

