[Cor 44 of arXiv:2510.22155, 'Random walks in space-time random media in all spatial dimensions: the full subcritical fl'] Let $F:[0,\infty) \to[0,\infty)$ be a decreasing function of exponential decay at infinity. Fix $\sigma>0$, $M>0$, $K > 0$, and $d\ge 2$. Let $H:[0,\infty)\to[0,\infty)$ be decreasing and satisfy $H(x) \leq Ae^{-bx}$ where $A,b>0$. Let $\br_0 \in \Ekk$ be centered and $\delta$-repulsive. Then there exists $\epsilon=\epsilon(F,\sigma,M,\delta,d)>0$ and $C=C(F,\sigma,M,\delta,K, A,b,d)>0$ such that uniformly over $\x\in I^k$, $y\in \mathbb R^d$, $r\ge 0$ and  all $f: I\to [0,\infty)$ satisfying $|f(x)| \leq H(|x|)$ one has 
        $$ \sup_{\substack{\br\in \Ekk\\d_{\mathrm{SRI}}(\br,\br_0) <\epsilon
       }}\Ebb [f(   R^i_r -    R^j_r -y)]<C \cdot A b^{-d} \cdot r^{-\frac{d}2}  \big( 1+ r^{-1/2} |x_i-x_j-y|\big)^{-K} .$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Pro 2.2 of arXiv:2608.00420, '{Weighted $L^p$ solutions of scalar BSDEs with general unbounded stochastic coefficients}\'] Let $\bar\rho_t(\omega)$, $\bar\mu_t(\omega)$: $\Omega \times [0,\tau]\mapsto {\mathbb R}$ and $\bar f_t(\omega)$, $\bar\nu_t(\omega)$: $\Omega \times [0,\tau]\mapsto {\mathbb R}_+$ be four $(\mathcal{F}_t)$-progressively measurable processes satisfying $\int_{0}^{\tau}\left(|\bar\rho_t|+|\bar\mu_t|+\bar\nu_t^2\right){\rm d}t<+\infty$,
\begin{align*}
\bar\rho_t\geq \bar\mu_t+\frac{\theta}{2(p-1)}\bar\nu_t^2, \ \ t\in[0,\tau]
\end{align*}
for some constant $\theta>1$, and
$$
\mathbb{E}\left[\left(\int_0^\tau e^{\int_{0}^{t}\bar\rho_r{\rm d}r}\bar f_t{\rm d}t\right)^{p}\right]<+\infty.
$$
Assume that the generator $g$ satisfies the following assumption:
\begin{enumerate}
\renewcommand{(A)}{(A)}
\renewcommand{(A)}{(A)}
\item $\forall (t,y,z)\in[0,\tau]\times{\mathbb R}\times{\mathbb R}^d$,~ $\sgn(y)g(\omega,t,y,z) \leq \bar f_t(\omega) + \bar\mu_t(\omega)|y| + \bar\nu_t(\omega)|z|$,
\end{enumerate}
and $(y_t,z_t)_{t\in [0,\tau]}$ is an adapted solution of BSDE (equation BSDE1.1 of the paper) such that $y_\cdot\in S_\tau^{p}(\bar\rho_\cdot;{\mathbb R})$. Then there exists a constant $C_{p,\theta}>0$ depending only on $p$ and $\theta$ such that for each $0\leq r\leq t< +\infty$,
\begin{align*}
\mathbb{E}\left[\sup_{s\in[t\wedge\tau,\tau]}\left(e^{p
\int_{0}^{s}\bar{\rho}_{r}{\rm d}r}|y_s|^{p}\right)\bigg|\mathcal{F}_{r\wedge\tau}\right]\leq
C_{p,\theta}\mathbb{E}\left[e^{p\int_{0}^{\tau}\bar{\rho}_{r}{\rm d}r}|\xi|^{p}+\left(
\int_{t\wedge\tau}^{\tau}e^{ \int_{0}^{s}\bar{\rho}_r{\rm d}r}\bar{f}_s{\rm d}s\right)^{p}\bigg|\mathcal{F}_{r\wedge\tau}\right].
\end{align*}

[Theorem 10 of arXiv:2606.11142, 'Strong invariance principles for diffusions, Markov chains and their perturbations.'] (Simplified Theorem 1.1 from \cite{Bitter}). Under the Boundedness Assumption, for every $n$ and pairs $(t_i, x), (t_j, y)$, there exists a constant $C > 0$ such that the error between the transition densities is bounded by:
\begin{equation*}
|p - p_\epsilon|(t_i, t_j, x, y) \le C \ln(e(j - i)) \cdot \Delta^{(n)} \cdot \mathcal{Q}_{S-d-6} \left( \frac{x - y}{\sqrt{t_j - t_i}} \right),
\end{equation*}
where $\Delta^{(n)} = \frac{1}{n^{\min(\gamma_2/2,\alpha_2,\beta)}} + \Delta_a + \Delta_b$, and $S$ is some number greater than $2d + 6$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 30 of arXiv:2604.11682, 'Semilocalization for inhomogeneous random graphs'] Define for all $x \in \hcV^{(\rm h)}_{\nu}, \sigma\in\{\pm 1\}$,
  \begin{equation*}
    \delta_{\sigma}(x) = A^{\pp}\b u_{\sigma}(x) - \sigma\sqrt{D_{x}^{\pp-}}\b u_{\sigma}(x)\,.
  \end{equation*}
  This vector can also be expressed as
  \begin{equation*}
    \delta_{\sigma}(x) = \frac{1}{\sqrt{Z_{x}}} \left(\sigma\sum_{y \in S_{1}^{\pp -}(x)}\frac{\b 1_{S_{1}^{\pp}(y)\setminus \{x\}}}{\sqrt{D_{x}^{\pp -}}} - \sum_{y\in S_{1}^{\pp -}(\hat{x})}\frac{\ind_{\{y \prec x\}}}{\#\Sib^{-}(x)}\b 1_{S^{\pp-}_{1}(y)} +  \sigma\sqrt{D_{x}^{\pp -}}\frac{\b 1_{\Sib^{-}(x)}}{\#\Sib^{-}(x)}\right)\,.
  \end{equation*}

