[Lemma lem:oscillation of arXiv:2504.11107, 'An Invariance Principle for some\\% Reaction-Diffusion Equations with a Multiplicative Ran'] For every $a>0$ and $k\in[2\,,\infty)$,
	\begin{equation}
		\sup_{t\in[a,1+a]} \mathrm{E}\left(\left|
		\frac{ \sup_{x\in\mathbb{T}} w(t\,,x) }{ \inf_{x\in\mathbb{T}} w(t\,,x)} \right|^k\right)<\infty,
	\end{equation}
	uniformly in the initial data $w_0\in L^\infty(\mathbb{T})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition propostion estimation L^2 of arXiv:2412.00865, 'On the spectral problem and fractional diffusion limit for Fokker-Planck with(-out) drift '] Assume (a1 of the paper)-(a2 of the paper).  Let $ \eta_0, \lambda_0>0$ small enough.  Then, for all $\eta \in [0,\eta_0]$ and for all $\lambda \in \mathbb{C}$ such that $|\lambda|\leqslant \lambda_0$,  the solution $M_{\lambda,\eta}$ of the penalised equation (equation eq de M_eta + cont. of the paper) satisfies the following estimates \smallskip

\noindent 1.  For all $\gamma > \frac{d}{2}$, one has
\begin{equation}
\|N_{\lambda,\eta}\|_{L^2(\mathbb{R}^d)}^2 := \|M_{\lambda,\eta}-M\|_{L^2(\mathbb{R}^d)}^2 \lesssim |\lambda| + |b(\lambda,\eta)| + \eta^{\frac{\delta}{3}} ,
\end{equation}
and 
\begin{equation}
\|M_{\lambda,\eta}\|^2_{L^2(\{ |v_1| \geqslant s_0\eta^{-\frac{1}{3}}\})} \leqslant \frac{1}{s_0^2} \left\| \eta^{\frac{1}{3}} v_1 M_{\lambda,\eta} \right\|_{L^2(\{ |v_1| \geqslant s_0\eta^{-\frac{1}{3}}\})} \lesssim \eta^{\frac{\delta}{3}} ,
\end{equation}
where $\delta := \frac{1}{2}(\gamma-\frac{d}{2})$ and $s_0$ is a positive constant.  \smallskip

\noindent 2.  For all $\gamma > \frac{d+1}{2}$, one has 
\begin{equation}
\left\|  |v_1|^{\frac{1}{2}} N_{\lambda,\eta} \right\|_{L^2(\mathbb{R}^d)}^2 := \left\| |v_1|^{\frac{1}{2}}(M_{\lambda,\eta}-M) \right\|_{L^2(\mathbb{R}^d)}^2 \lesssim 1 .
\end{equation}
In particular, the functions $M_{\lambda,\eta}$ and $|v_1|^{\frac{1}{2}} M_{\lambda,\eta}$ are uniformly bounded, with respect to $\lambda$ and $\eta$, in $L^2(\mathbb{R}^d,\mathbb{C})$ for $\gamma > \frac{d}{2}$ and $\gamma > \frac{d+1}{2}$ respectively. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem prop:uniform-T-W2 of arXiv:2607.00149, '\bf Uniform-in-time Propagation-of-Chaos for\\ Stein Variational Gradient Descent'] Let Assumption~(ass:Wass of the paper) hold. Recall the exponent $\mathfrak r=\mathfrak r(d,\nu)$ in (equation eq:rdef of the paper), and let
$
    \gamma_*:=\frac{\mathfrak r}{4} \wedge \beta_{\rm init},
$
where $\beta_{\rm init}$ is the logarithmic decay rate of the probability associated with the initialization in Assumption~(ass:Wass of the paper). Then there is a $N_0 \in \mathbb{N}$ and $C \in (0,\infty)$ such that,
for all $N\ge N_0$,
\begin{equation}
    \sup_{T>0}\,
    \mathbb P\left(
        W_2(\overline\mu_T^N,\overline\mu_T)
        > (\log N)^{-\mathfrak r / 4}
    \right)
    \le C\,(\log N)^{-\gamma_*}.
\end{equation}
Moreover,
\[
W_2(\overline\mu_T^N,\overline\mu_T)
=
O_{\mathbb P}\bigl((\log N)^{-\mathfrak r/2}\bigr)
\]
uniformly over deterministic averaging horizons \(T>0\), in the sense that
\begin{equation}
\lim_{M\to\infty}\limsup_{N\to\infty}
\sup_{T>0}
\mathbb P\left(
W_2(\overline\mu_T^N,\overline\mu_T)>M(\log N)^{-\mathfrak r/2}
\right)
=0.
\end{equation}

[Lemma le:double_bound_given_pts of arXiv:2507.15589, 'Tightness of approximations to metrics on non-simple conformal loop ensemble gaskets'] Fix $a_1,a' > 0$. Then for each $\underline{z} \in \mathcal {D}_k^m$, $\underline{r} \in \mathbf{R}_+^m$ with $r_u > 2^{-k(1-a_1)}$ for each $u$ we have
\begin{equation}
\mathbf{P}[F(\underline{z},\underline{r}) \cap E_k] \lesssim \prod_u \left(\frac{ 2^{-k(1-a_1)}}{r_u}\right)^{\alpha_{4,\kappa}-a'}
\end{equation}
where the implicit constant does not depend on the choice of $\underline{z},\underline{r}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem Hypercon of arXiv:2507.02518, '{\bf Exponential Ergodicity in Relative Entropy and $L^2$-Wasserstein Distance for non-equ'] Let $\bar{\mu}$ be the invariant probability measure of $(P_t)_{t\ge0}$, and
assume that $(P_t)_{t\ge0}$ is hyperbounded, i.e.,
$\|P_{t_0}\|_{p\rightarrow q }:= \|P_{t_0}\|_{L^p(\bar{\mu})\rightarrow L^q(\bar{\mu})}<\infty $ for some   $t_0>0 $ and  $1<p<q<\infty$.
Assume moreover that $L^2$-exponential ergodicity holds, i.e.
\begin{align*}\|P_t f-\bar{\mu}(f)\|_{L^2(\bar{\mu})}\leq c\text{\rm{e}}^{-\lambda t}\|f-\bar{\mu}(f)\|_{L^2(\bar{\mu})},\ \ t\geq 0
\end{align*}
for some constants $c,\lambda>0$.
Then hypercontractivity holds, i.e.
\begin{align*}
\|P_{\tilde{t}_0}\|_{p\rightarrow q }\leq 1
\end{align*}
for some constant $\tilde{t}_0>0$ depending only on $c,\lambda,q,p,t_0$ and $\|P_{t_0}\|_{p\rightarrow q }$.
Consequently, exponential ergodicity in relative entropy holds:
\begin{align*}
\bar{\mu}(P_t f\log P_tf)\leq \tilde{c}\text{\rm{e}}^{-\tilde{\lambda} t}\bar{\mu}(f\log f),\ \ \bar{\mu}(f)=1, f>0, t\geq 0
\end{align*}
for some constants $\tilde{c}, \tilde{\lambda}>0$ depending only on $\tilde{t_0},q,p$. (Proof in the paper; no proof environment follows the statement in the TeX.)

