[Prop momentformula of arXiv:2411.12149, 'Airy limit for $\beta$-additions through Dunkl operators'] Fix $\beta>0$, $N\in \mathbb{Z}_{\ge 1}$. Define $G_{N}(x_{1},\ldots,x_{N};\beta)$ as in Eqn.~((eq_additionbgf of the paper)), and let $\lambda_{1}\ge \ldots\ge \lambda_{N}$ be its random eigenvalues distributed according to $P_{N,\beta}$. Then for any $k_{1},\ldots,k_{m}\in \mathbb{Z}_{\ge 1}$, we have
    \begin{equation}
        \mathbb{E}\left[\prod_{i=1}^{m}p_{k_{i}}(\lambda_{1},\ldots,\lambda_{N})\right]=\left(\prod_{i=1}^{m}p_{k_{i}}(\mathcal{D}_{1},\ldots,\mathcal{D}_{N})\right)G_{N}(x_{1},\ldots,x_{N};\beta)|_{x_1=\ldots=x_N=0}.
    \end{equation}

[Lemma lem: H estimate of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] Under Assumption (As: regularity assumption of the paper), for $B^{[m+1]}$ defined in (equation eq:Bn of the paper) and $m=0,\ldots,N-1$, we have
		\begin{equation}
			\|B^{[m+1]}(\tau)\|_{(m+\beta)\alpha,\mu}\lesssim_{\mathbb X,\sigma} \sum_{\ell=2}^{m}\|Z^{[\ell]}\|_{\ell\alpha,\mu}+(\mu\wedge T)^{1-\beta}\left(1\vee\| Z^{[1]}\|_{\alpha,\mu}\right).
		\end{equation}
		If $\beta=1$, namely if $\Upsilon_\tau$ is globally Lipschitz continuous for all $\tau\in{\mathcal T}^{\leq N}$, then
		\begin{equation}
			\|B^{[m+1]}(\tau)\|_{(m+\beta)\alpha,\mu}\lesssim_{\mathbb X,\sigma} \sum_{\ell=1}^{m}\|Z^{[\ell]}\|_{\ell\alpha,\mu}.
		\end{equation}

