[Prop 7 of arXiv:2605.05986, '\bf Convergence rate of the occupation measure of { classes of ergodic processes toward th'] Let $(P_t)_{t\ge0}$ be  a  (strongly Feller)\footnote{{The strong Feller property is ensured by $(i)$ (which implies that $P_{\theta_0}g$ is continuous when $g$ is bounded measurable).}} Markov transition semi-group defined on bounded and nonnegative Borel functions on $\R^d$. Assume it admits a unique invariant distribution $\nu$. {Assume} 

$(i)$ $\LSF$ (for Lipschitz Strong Feller):  there exists $\theta_0>0$, $c(\theta_0)>0$   such that
\begin{equation}
\hskip-1,25cm \; \mbox{ for every {bounded} Borel function $g: \R^d \to \R$, $P_{\theta_0}g$ is Lipschitz with $[P_{\theta_0}g]_{\rm Lip}\le c(\theta_0)\|g\|_{\sup}$}, 
\end{equation}

$(ii)$ {$\ATROISbis$} :  there exists $\mu_0\!\in {\cal P}_q(\R^d)$ for some $q> 1$ and $\psi:\ER\rightarrow[0, +\infty) $ and $\ee\!\in \mathbb{L}^1([0, +\infty))$  some Borel  functions such that 
\begin{equation}
\qquad \begin{cases}
(i) & \forall t\ge0,\forall\, x \!\in \R^d, \quad \W_1(P_t(x,dy),\nu)\le \psi(x)\ee(t),\\
 (ii) & \sup_{t\ge 0}\mu_0P_t(\psi^q+ |\cdot|^{q})<+\infty.
\end{cases}
\end{equation}
Then the assumptions of Proposition~\ref{prop:Markovsetting} are satisfied with $\psi\vee 1$ and $t \mapsto 2\mbox{\bf 1}_{\{t\le \theta_0\}}+ c(\theta_0)e(t-\theta_0)\mbox{\bf 1}_{\{t\ge \theta_0\}}\!\in {\mathbb L}^1(du)$ instead of $\psi$ and $e$ respectively so that $\nu(|\cdot|^q)<+\infty$ and all the other conclusions of Theorem~\ref{thm:possiblynonmarkov} are satisfied  for a Markov process $(X_t)_{t\ge 0}$ with transition $(P_t)_{t\ge 0}$ such that $X_0\stackrel{d}{\sim} \mu_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 45 of arXiv:2601.16377, '2601.16377'] Let $\mathcal I^{(2)}$ denote the quadratic part of the energy functional, \textit{i.e.}
\begin{equation}

  \mathcal{I}^{(2)}[\boldsymbol{\nu}] := \sum_{g,h = 1}^{H} \int_{\hat a'_g}^{\hat b'_g} \int_{\hat a'_{h}}^{\hat b'_{h}} \theta_{g,h}\log|x-y|\,
 \nu_g(x)\nu_{h}(y)\,\dd x \dd y
 \end{equation}

[Theorem 6 of arXiv:2605.23222, 'On global solutions to the semidiscrete stochastic heat equation'] For $\beta$ sufficiently small, the following holds: For every $\sigma \in (0,1)$ there exists $\theta = \theta(\sigma) > 0$ such that for all $x,y\in\Z^d$ and $s < t$ with $\| x - y \| < (t - s)^{\sigma}$, the partition function $Z_{x,s}^{y,t}$ has the representation 

\begin{equation}     
Z_{x,s}^{y,t} = p_{t-s}^{y-x} \left(Z_{x,s}^{\infty} Z_{-\infty}^{y,t} + \delta_{x,s}^{y,t} \right),
\end{equation} 

where the error term $\delta_{x,s}^{y,t}$ defined by the formula above satisfies 

\begin{equation}   
\lim_{(t-s) \to \infty} (t-s)^{\theta} \sup_{x, y \in \Z^d: \|x-y\| < (t-s)^{\sigma}} \langle \lvert \delta_{x,s}^{y,t} \rvert \rangle = 0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 34 of arXiv:2609.02850, 'Canonical-row Chern flow on Bott--Samelson towers:\\ realizable-volume models for Schubert'] For $1\le t\le c_a$, there are exact sequences
\begin{equation}
 0\longrightarrow Q_{a,t}\longrightarrow G_{a,t}
 \longrightarrow G_{a,t-1}\longrightarrow0.
\end{equation}
At the end of the row, the bundle $G_a:=G_{a,c_a}$ is globally generated; more precisely, there is a natural surjection
\begin{equation}
 \cL_a\oplus\cdots\oplus\cL_n\twoheadrightarrow G_a.
\end{equation}
Moreover,
\begin{equation}
 c_{c_a}(G_a\otimes\cM)
 =\prod_{t=1}^{c_a}(q_{a,t}+h_z).
\end{equation}

[Definition 22 of arXiv:2606.14443, 'SEMICLASSICAL LIMIT OF POLYAKOV-LIOUVILLE MEASURE and Q-Curvature Uniformization ON EVEN-D'] An \emph{augmented massive (co-polyharmonic) Gaussian field} $\tilde h$ on $(M,g)$ with mass $m>0$ is a centered Gaussian random variable $\tilde h$ on ${\mathfrak D}$ with covariance
	\begin{equation}

		\mathbb{E} \Big[\langle \tilde h|\phi\rangle\cdot \langle \tilde h|\eta\rangle\Big]={\mathcal K}_{m}(\phi,\eta)

		\quad\qquad \forall \phi,\eta\in {\mathfrak D} ,
	\end{equation}
	where
	\begin{align*}
		{\mathcal K}_{m}(\phi,\eta)
		=&\sum_{j=1}^\infty \frac{\scalar{\phi}{\psi_j}\scalar{\eta}{\psi_j}}{\nu_j+m}+\sigma^2\scalar{\phi}{1}\scalar{\eta}{1}.
	\end{align*}

[Defn Radial ground solutions of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] For each radial link pattern $\alpha$, we choose Pochhammer contours $\mathcal{C}_1, \ldots, \mathcal{C}_n$ along which to integrate out the $\boldsymbol{\xi}$ variables. The integration is well-defined since the conformal dimension of $\Phi_\kappa(\boldsymbol{z}, \boldsymbol{\xi},u)$ is 1 at the $\boldsymbol{\xi}$ points, i.e. since $\lambda_b(-2 a)=1$. This leads to a new function of $\boldsymbol{z}$ defined by
\begin{equation}
\mathcal{J}^{(m, n)}_{\alpha}(\boldsymbol{z},u):=\oint_{\mathcal{C}_1} \ldots \oint_{\mathcal{C}_m}  \Phi_\kappa(\boldsymbol{z}, \boldsymbol{\xi},u) d \xi_m \ldots d \xi_1 .
\end{equation}

In angular coordinates, we obtain 
\begin{equation}
\mathcal{J}^{(m, n)}_{\alpha}(\boldsymbol{\theta}):=\oint_{\mathcal{C}_1} \ldots \oint_{\mathcal{C}_m} \Phi_\kappa(\boldsymbol{\theta}, \boldsymbol{\zeta}) d \zeta_m \ldots d \zeta_1 .
\end{equation}

[Lem 10 of arXiv:2604.00190, '2604.00190'] For any strategy $\pi\in\un{\Pi}^\nu$ and $n\in\bN$, we have
\begin{align}
v_{\pi_n}(x, y)\leq \cV^{\nu, (n)} {v_0}(x, y)\leq V^{\nu}(x, y),\qquad (x, y)\in\bR\times E. 
\end{align}

Let $\mathbb{M} = [0, 1]^{\mathbb{N}}$ be the product space of countably many unit intervals equipped with the product Borel $\sigma$-algebra and product uniform measure $\mathbb{Q}$. The augmented Poisson process $\Psi$ is a Poisson point process on $\mathbb{R}^d \times \mathbb{A} \times [0, 1] \times \mathbb{M}$ with intensity measure $\gamma \lambda_d \otimes \Theta \otimes \lambda_{[0, 1]} \otimes \mathbb{Q}$. Each point $(x, a, t, u) \in \Psi$ represents a potential vertex $(x, a)$ along with continuous auxiliary uniform marks $t \in [0, 1]$ and $u = (u_1, u_2, \dots) \in \mathbb{M}$ used to determine the independent inclusion of incident simplices according to the connection functions $\varphi_j$.
\mathbb{M} is the countable product of [0, 1] with measure \mathbb{Q}
\Psi has intensity \gamma \lambda_d \otimes \Theta \otimes \lambda_{[0,1]} \otimes \mathbb{Q}

[Proposition 2 of arXiv:2608.22636, 'Q-Learning with Stable Infinite-Dimensional \\Linear Function Approximation'] Under Assumptions~\ref{assump:mdp} and \ref{assump:stable_kernels}, the operator
$\cG=\mrm{K}\mathcal T\Phi$ maps $\Theta$ into itself and is a $\gamma$-contraction on $\Theta$.  Hence $\cG$
has a unique fixed point $\theta^*\in\Theta$.  Moreover, $\theta^*$ is $\rho$-Lipschitz and
\begin{equation}
        [\theta^*]_{\rho}
        \le
        \frac{2L_{\kappa,\rho}}{c_\wedge(1-\gamma)}.

\end{equation}
With $q^*:=\Phi\theta^*$, we have
\begin{equation}
        \theta^*=\mrm{K}\mathcal T\Phi\theta^* \quad\text{and}\quad 
        q^*=\Phi\mrm{K}\mathcal T q^* .

\end{equation}
Moreover, if $Q^*\in C(\mbb Z)$ satisfies $Q^*=\mathcal TQ^*$, then
\begin{equation}
        \norm{Q^*-q^*}
        \le
        \frac{\norm{Q^*-\Phi\mrm{K}Q^*}}{1-\gamma}.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 2 of arXiv:2506.12632, 'Point process convergence of extremes in $K$-symmetric exclusion'] If $\mu = \sum_{i \in S} \delta_{x_i}$ is a counting measure on $\R$ and $A \in \sB_\R$, then 
\begin{equation}
	\mu^{(n)}(A^n) = \mu(A)(\mu(A) - 1) \cdots (\mu(A) - n + 1) = (\mu(A))_n. 
\end{equation}

[Lem Wk-lemma of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] Suppose $W \in \tilde{\mathcal{D}}^{ext}_+(\mathcal{M})$ (see (spde-tilde-domain of the paper)) and $W': \mathcal{M} \to [0,\infty]$ are nonnegative functions satisfying:
    \begin{itemize}
        \item $\mathcal{L} W \leq K - W'$ for some constant $K > 0$.
        \item $\Gamma W / W$ vanishes over $W'$ (see (fxn-vanish of the paper)).
        \item $W << W'$ (see (<< of the paper)).
    \end{itemize}
    Then for all $k \geq 1$, $W^k \in \mathcal{D}^{ext}_2(\mathcal{M})$ and there is a constant $K' > 0$ such that \begin{equation}
        \mathcal{L} W^k \leq K' - \frac{k}{4}W^{k-1}W' \quad \text{and} \quad \Gamma W^k \leq K' + k^2W^{2k-1}W' \,.
    \end{equation}

