[Cor cor11 of arXiv:2411.03712, '{\bf Probability Versions of Li-Yau Type Inequalities and Applications }\footnote{Supporte'] Assume that $\partial M$ is either empty or convex, and let $(equation C of the paper)$ hold for a constant $K\in\mathbb R.$  Then the inequality
$(equation A1 of the paper)$ holds for $\sigma=0$ and  implies the following estimates.
\begin{enumerate}
 \item[$(1)$] For any constant $\alpha>1$
\begin{equation} \begin{split}&\left(1+ \frac{2K\int_0^t (1- \text{\rm{e}}^{-\frac{Ks}{\alpha-1}} )^2\text{\rm{d}} s}{\alpha(1-\text{\rm{e}}^{-\frac{Kt}{\alpha-1}})^2}\right)
\frac{|\nabla u_t|^2}{u_t^2}\\
&   \le \frac{  Lu_t}{u_t}+ \frac{nK\alpha } {4(\alpha-1)}\coth\Big(\frac{Kt}{2(\alpha-1)}\Big),\ \ t>0.\end{split}\end{equation}
\item[$(2)$] For any $t>0$ and $\alpha\ge 1+ K^-t$,
 \begin{equation}    \Big(1+\frac 2 {3\alpha} K t\Big) \frac{|\nabla u_t|^2}{u_t^2}   \le \frac{   L u_t}{u_t} + \frac {n \alpha  } {2t}.  \end{equation}
 Consequently, when $K>0$,
 \begin{equation}    \Big(1+\frac 2  3  K t\Big) \frac{|\nabla u_t|^2}{u_t^2}   \le \frac{L u_t}{u_t} + \frac {n } {2t},\ \ t>0.  \end{equation}
