body:
[Definition Def: weighted norms of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] Given $F \in C ([0, T]^2_{\leq}, \mathbb{R}^n)$, $G \in C ([0,
		T]^3_{\leq}, \mathbb{R}^n)$ and $\beta,\mu \in (0, \infty)$ we define
		\begin{align*}
			&\| F \|_{\beta, \mu}:=\sup_{0 \leq s \leq t \leq
				T} \mathbbm{1}_{\{ 0 < t - s \leq \mu \}} e^{- \frac{t}{\mu}}
			\frac{| F_{s t} |}{(t - s)^{\beta}}\,,  \\
			&\| G \|_{\beta, \mu} := \sup_{0 \leq s \leq u \leq
				t \leq T} \mathbbm{1}_{\{ 0 < t - s \leq \mu \}} e^{-
				\frac{t}{\mu}} \frac{| G_{s u t} |}{(t - s)^{\beta}}\,.  
		\end{align*}

[Theorem thm:BSSK_crit of arXiv:2510.26960, 'Free energy fluctuations in SK and related spin glass models: \\ A literature survey'] Consider a BSSK model where $N_1/N_2=\lambda+O(N^{-1})$ for some $\lambda\in(0,1)$ and let $\beta=\beta_c+bN_1^{-1/3}\sqrt{\log N_1}$ for some fixed $b\in\mathbb{R}$.  Then the free energy exhibits the following convergence in distribution as $N_1,N_2\to\infty$.
 \begin{equation} 
\frac{N}{\sqrt{\frac16\log N_1}}\left(F_{N_1,N_2}(\beta)-F(\beta)+\frac{\log N_1}{12N}\right)\to\mathcal{N}(0,1)+C_\lambda\max\{0,b\}\TW_1
 \end{equation} 
where $F(\beta)$ and $C_\lambda$ are given in Theorem 1.1 of [CWL_BSSK]. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition LUE fac of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] Let $L_{a,N}$ be an LUE with parameter $a\in\mathbb{N}$ and kernel $K_{L_{a,N}}(x,y)$. Then for $a\ge 2$, the following decomposition holds for the corresponding integral operator $\mathbf{K}_{L_{a,N}}$:
 \begin{equation}
\mathbf{K}_{L_{a,N}}=\mathbf{G}_{a,N}\mathbf{H}_{a,N}+\mathbf{H}_{a,N}\mathbf{G}_{a,N}.
\end{equation}
Thereinto, the operators $\mathbf{G}_{a,N}$ and $\mathbf{H}_{a,N}$ have kernels $\xi_{a,N}(x+y)$ and $\eta_{a,N}(x+y)$ for
\begin{equation}
    \begin{array}{ll}
   \xi_{a,N}(x):=\frac{(-1)^N}{\sqrt2}\left(N(N+a)\right)^\frac{1}{4}\sqrt{\frac{\Gamma(N+1)}{\Gamma(N+a)}}x^{\frac{a}{2}-1}e^{-\frac{x}{2}}L_{N}^{a-1}(x)\chi_{(0,\infty)}(x),\\
   \\
    \eta_{a,N}(x):=\frac{(-1)^{N-1}}{\sqrt2}\left(N(N+a)\right)^\frac{1}{4}\sqrt{\frac{\Gamma(N)}{\Gamma(N+a+1)}}x^{\frac{a}{2}}e^{-\frac{x}{2}}L_{N-1}^{a+1}(x)\chi_{(0,\infty)}(x)
    \end{array}
\end{equation}
respectively.

Let $\mathbf{K}_{Ai}$ be the integral operator with the Airy kernel defined in (equation airy kernel of the paper), then
\begin{equation}
    \mathbf{K}_{Ai}=\mathbf{Ai}\mathbf{Ai}
\end{equation}
where $\mathbf{Ai}$ has the kernel $Ai(x+y)$.

Moreover, all operators above are Hilbert-Schmidt on $L^2(0,+\infty)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 (The Brownian snake for super-Brownian motion) of arXiv:2604.01852, 'The on/off Brownian snake'] There exists a measure-valued process $(\mathcal{X}_y)_{y \geq 0}$ such that for any nonnegative bounded Borel measure function $g$ on $\mathbb{R}^d$ and any $y>0$ we have
    \begin{equation}
        \langle \mathcal{X}_y, g \rangle = \sum_{i \in I} \int_{r=0}^{\sigma_i} dL^i_y(r) g(\hat{w}^i_r) \hspace{0.5cm} \mathbb{P}_{(\mu_{\rm d}, \mu_{\rm a})}\text{-a.s.}
    \end{equation}
    The process $(\mathcal{X}_y)_{y \geq 0}$ is an $\text{SBM}(4)$ started from $\mu \coloneqq \mu_{\rm d} + \mu_{\rm a}$.
    \par
    Furthermore we have that for any $y > 0$ that
    \begin{equation}
        \text{supp}(\mathcal{X}_y) = \overline{\bigcup_{i \in I}\{\hat{w}^i_r: r \in [0,\sigma(f^i)], f^i_r = y\}} \hspace{0.5cm} \mathbb{P}_{(\mu_{\rm d}, \mu_{\rm a})}\text{-a.s.}
    \end{equation}
    This follows from \cite[Equation IV.10]{le1999spatial} which states the support for each component of the superprocess $\mathcal{X}_y$ constructed from each of the snakes $x^i$, $i \in I$. The closure of the union of the supports for these components is stated in \eqref{equation sbm supp snake rep}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: D2 of arXiv:2603.26932, 'On the satisfaction frequency of spectral characterization conditions'] Let $q = p^{\deg(\beta)}$. 
    Then, for every $n\geq 1$,  
    \begin{align}
        \biggl\lvert \, \bbP\biggl(\frac{\coker(\bM_{p,\beta})}{p\coker(\bM_{p,\beta})}  \cong  \frac{\bbF_{p}[x]}{ \beta(x)^2 \bbF_p[x]},\,  \frac{\coker(\bM_{p,\beta})}{\beta(x)\coker(\bM_{p,\beta})} \cong \frac{\bbF_{p}[x]}{ \beta(x) \bbF_p[x]} \biggr) &-   \frac{1}{q^2}\Bigl(1 - \frac{1}{q}\Bigr) \prod_{i\geq 0}\Bigl(1 - \frac{1}{q^{2i+1}} \Bigr)    \, \biggr\rvert \nonumber\\ 
        &\leq \frac{3}{q^n}. 
    \end{align}

