[Theorem 3 of arXiv:2606.26619, 'Ergodicity of stochastic reaction-diffusion equations on unbounded domains driven by space'] Let $u^i(t,\cdot)$ denotes the solution to euqation (\ref{3.1}) with initial value $u_0^i$, $i=1,2$. 
\begin{itemize}
  \item [(i)] Suppose that (H4) holds. 

Then for any $\lambda, t\geq 0$,
\begin{align}
    \mathbb{E} \Vert u^2(t) - u^1(t)\Vert_{L^1_{\lambda}} \leq 2 e^{-(\alpha -\frac{\lambda^2}{2}) t} \mathbb{E}\Vert u_0^2 - u_0^1 \Vert_{L^1_{\lambda}} .
\end{align}
  \item [(ii)] Suppose that (H2) and (H4) hold. Assume that for some $\lambda\geq 0$,  $\mathbb{E}\int_{\mathbb{R}}|u^2(t,x) - u^1(t,x)|^2 e^{-\lambda|x|} dx <\infty$ for any $t\geq 0$. 
  If $\alpha>\frac{L_{\sigma}^4}{8}$ and $\kappa\geq 0$ satisfy
\begin{align}
\kappa + \frac{\lambda^2}{8} < \alpha - \frac{L_{\sigma}^4}{8} \quad \text{ and } \quad   \kappa + \frac{\lambda^2}{4}\leq \alpha,
\end{align}
then there exists a constant $C_{\alpha,\lambda,\kappa}>0$ such that for any $t\geq 0$,
\begin{align}
\left(\mathbb{E} \int_{\mathbb{R}} |u^2(t,x) - u^1(t,x)|^2 e^{-\lambda |x|} dx\right)^{\frac{1}{2}} \leq 2 C_{\alpha,\lambda,\kappa} e^{-\kappa t}\left(\mathbb{E}\Vert  u^2_0 - u^1_0 \Vert_{L^2_{\lambda}}^2\right)^{\frac{1}{2}}.
\end{align}
\end{itemize}

[Lemma 205 of arXiv:2601.16377, '2601.16377'] Choose a polynomial $p(z)$ of degree at most $H-1$ and suppose that $f \in \mathscr{H}^{[2],0}$ satisfies
\begin{equation}
 f(z) =
\frac{p(z)}{\sigma(z)} + \sum_{1 \leq g \neq h \leq H} \frac{1}{\sigma(z)}
\oint_{\gamma_h} \frac{\dd\zeta}{2\ii\pi}\,\frac{\sigma(\zeta)}{z - \zeta}\,\frac{(\theta_{h,h} -
\theta_{h,g})f_{g}(\zeta)}{\theta_{h,h}},
\end{equation}
where $z$ is outside all the contours $\gamma_h$. Then $f$ is identically equal to zero. (Proof in the paper; no proof environment follows the statement in the TeX.)

