[Theorem 5 of arXiv:2606.09691, '\textsc{Degenerate Diffusions on Continuum Percolation and Hamilton-Jacobi-Bellman Equatio'] Assume \ref{f1}, \ref{f2}-\ref{f4} and
\ref{assump:est-erg}-\ref{assump:inf-comp}. Then the following hold:
\begin{enumerate}

\item
For any $\omega\in\Omega_0$ and $T>0$, the function
$u(t,x,\omega)$ defined in \eqref{eq:visc-sol-var-form} is a viscosity solution
(cf. Definition \ref{def:SubSuperSol}) of
\begin{equation}
\begin{cases}
\partial_t u
=
\frac12\mathrm{div}\big(a(x,\omega)\nabla u\big)
+
H(x,\nabla u,\omega),
&\text{in } (0,T)\times\mathcal C_\infty(\omega),
\\
u(0,x,\omega)=f(x),
&\text{on } \mathcal C_\infty(\omega),
\end{cases}
\end{equation}
in the class of viscosity solutions of at most linear growth.

\item
For any $\eps>0$, the function $u_\eps$ defined in \eqref{eq:u-eps-def} is a viscosity solution of
\begin{equation}
\begin{cases}
\partial_t u_\eps
=
\frac{\eps}{2}
\mathrm{div}\big(a\big(\frac x\eps,\omega\big)\nabla u_\eps\big)
+
H\big(\frac x\eps,\nabla u_\eps,\omega\big),
&\text{in } (0,T)\times\eps\mathcal C_\infty(\omega),
\\
u_\eps(0,x,\omega)=f(x),
&\text{on } \eps\mathcal C_\infty(\omega),
\end{cases}
\end{equation}
in the class of viscosity solutions of at most linear growth.

\item
If we additionally assume that the initial condition is uniformly bounded, i.e.,
$\sup_{x\in\R^d}|f(x)|\leq K_f<\infty$, then for each $T>0$ and
$\omega\in\Omega_0$,
\begin{equation}
\sup_{t\in[0,T]}
\sup_{\eps>0}
\sup_{x\in\eps\mathcal C_\infty(\omega)}
|u_\eps(t,x,\omega)|
<\infty.
\end{equation}

\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem cancellation1 of arXiv:2411.12149, 'Airy limit for $\beta$-additions through Dunkl operators'] There exists a constant $C>1$ that depends on $\mathbf{k}_{1},\ldots,\mathbf{k}_{l}$ and $\sigma$, and is uniform in $N$, such that for all $N\ge 100$,
    \begin{equation}
    \begin{split}
        \sum_{(E,\vec{q})\in \mathcal{I}}\left|\sum_{(E,\vec{q}')\sim (E,\vec{q})}w(E,\vec{q}')\right|\le&C \prod_{j_{p}\in J_{A}:\eta_{j_{p}}\ne \varnothing}(C_{b_{j_{p}}}-Y_{j_{p}}+1)^{-1/2}\cdot \prod_{p:j_{p}\in J_{IV}}\tau_{j_{p}}^{-1/2}\prod_{p:j_{p}\in  J_{III}\cup J_{VI}}\tau_{j_{p}}^{-3/2}\\
