[Lemma 16 of arXiv:2604.11921, 'Replica symmetry up to the de Almeida--Thouless line in the Sherrington--Kirkpatrick model'] For $\lambda\ge 0$ define
\begin{equation}
F_\lambda(s)=
 e^{-\lambda/2}\E\left[\cosh(\sqrt\lambda\,G)
 \frac{1+(4-3s)\sinh^2(\sqrt\lambda\,G)}{(1+s\sinh^2(\sqrt\lambda\,G))^3}
 \right],
 \qquad s\in[0,1].
\end{equation}
Then, for every $0\le \lambda\le \beta^2(1-q)$,
\begin{equation}
a_2(\lambda)=\E\bigl[S^2F_\lambda(S)\bigr].
\end{equation}
Moreover, for every $\lambda>0$, the function $F_\lambda$ is strictly decreasing on $[0,1]$.

[Proposition 76 of arXiv:2609.03875, 'Measure theory without infinities'] Let $\eta_1$ and $\eta_2$ be $\mf R$-valued maps, $\mu_1 = \mf F\eta_1$, and $\mu_2 = \mf F\eta_2$.
  \begin{enumerate}
  \item [(i)] $\mf F(\eta_1\dotplus_{\mf R}\eta_2) = \mu_1\dotplus_\R\mu_2$.
  \item [(ii)] If $\eta_1\dotleq_{\mf R}\eta_2$, then $\mu_1\dotleq_\R \mu_2$.
  \end{enumerate}

[Proposition 31 of arXiv:2605.03851, 'The Relay Random Tree:\\A stochastic geometry approach of multihop relay in an urban visib'] \textbf{Distribution of the blocking building: general finite range.}

For $x_1< x_2\in \R$, $h_1, h_2\in \R_+$, and $t_1 = \frac{h_2-h_1}{x_2-x_1}$ let us denote
\begin{align*}
    \placehold((x_1, h_1), (x_2, h_2)) : =\bigintsss_{\hspace{-5pt}x_2}^{\max\{a : \exists (a, b)\in \mathrm{R}+(x_1, h_1)\}}\hspace{-100pt}\lambda \mathcal{L}([h_{\mathrm{R}+(x_1, h_1)}&(u), +\infty[)\\
&\exp\left(-\lambda \int_{x_2}^{u}\mathcal{L}([(h_2+(a-x_2)t_1)\wedge h_{\mathrm{R}+(x_1, h_1)}(a), +\infty[ \rm{d}a\right)\rm{d}u \\
+ \exp\Biggl(-\lambda&\bigintsss_{\hspace{-5pt}x_2}^{\max\{a : \exists (a, b)\in \mathrm{R}+(x_1, h_1)\}}\hspace{-100pt} \mathcal{L}([(h_2+(a-x_2)t_1)\wedge h_{\mathrm{R}+(x_1, h_1)}(a), +\infty[\rm{d}a\Biggl).
\end{align*}
Then for $(X, H)\in \Half$ a given point, the restriction of the law of $(x_b, y_b)$ to $\Half$, or in other words, the restriction of the law of the blocking building to the event of its existence has density with respect to the product measure $\Leb \otimes \mathcal{L}$, which is given by
\begin{align*}
g_{\mathrm{R}}: (x, h)_{0\leq n\leq N} \mapsto \lambda &\exp\Biggl(-\lambda\frac{(\primi(h)-\primi(H))(x-X)}{h-H}\Biggl) \placehold((X, H), (x, h)) \mathds{1}_{(x, h)\in \mathrm{R}+(X, H)},
\end{align*}
where, if $h=H$, we consider the continuous extension $\frac{(\primi(h)-\primi(H))}{h-H} = (1-F(h))$.

