[Corollary 21 of arXiv:2608.17449, 'Spectral Simplicity and Joint Eigenvalue Densities\\ for a Non-Gaussian Brownian Time Chan'] Let $f_1,\ldots,f_N$ and $\mu_t$ be as in \cref{prop:response}.  Fix
$t_0\in\R^N$ and $n\ge1$.  Suppose that $\Lambda_n^{\mu_{t_0}}$ has
multiplicity one.  Then there is a neighborhood $U$ of $t_0$ such that
$\Lambda_n^{\mu_t}$ has multiplicity one for every $t\in U$, and the function
$t\mapsto\Lambda_n^{\mu_t}$ is real-analytic on $U$.  Choose a real
eigenfunction $\phi_{n,t_0}$ satisfying
\begin{equation*}
 A_{\mu_{t_0}}\phi_{n,t_0}
 =\Lambda_n^{\mu_{t_0}}\phi_{n,t_0},
 \qquad
 \|\phi_{n,t_0}\|_{L^2(\mu_{t_0})}=1.
\end{equation*}
Then, for $1\le j\le N$,
\begin{equation}
 \partial_{t_j}\Lambda_n^{\mu_t}\big|_{t=t_0}
 =-\gamma\Lambda_n^{\mu_{t_0}}
 \int_Df_j\phi_{n,t_0}^2\,d\mu_{t_0}.

\end{equation}

