\item[(ii)] If \(b\in A\), then \(I(A)-I(A\setminus\{b\})\le D^2\).
\end{enumerate}

[Definition def:conjugator of arXiv:2608.26564, 'Real ideal points, Conway spheres, and left-orderable Dehn fillings'] Choose $C_i \in SL_2(K)$ as in Proposition (prop:branchmodel of the paper), and set $R = C_1C_2^{-1} \in SL_2(K)$. Let $\varpi$ be a uniformizer of $K$, positive for small $u > 0$, and put
\begin{equation*}
	m_R = \min_{j,k}v(R_{jk}) \ \ \ \ \ \widehat R = \varpi^{-m_R}R \ \ \ \ \ \widehat\Delta = \det(\widehat R) = \varpi^{-2m_R}	
\end{equation*}
Then every entry of $\widehat{R}$ lies in $\mathcal{O}_K$, at least one entry is a unit, and $\widehat\Delta > 0$ at every small $u > 0$. We refer to $R$ as the \emph{relative conjugator}, and $\widehat R$ as the \emph{projective relative conjugator}.

[Prop compactness of arXiv:2411.04157, 'Stochastic homogenization of dynamical discrete optimal transport'] Suppose (equation edge of the paper) and (equation degree of the paper) in Assumption (ass: graph of the paper) hold.    Let \\$m^\varepsilon\in W^{1,1}((0,T);{\mathcal P}({\mathcal X_{\varepsilon}}))$ and $J^\varepsilon\in L^1((0,T);\mathbb{R}^{\mathcal E_{\varepsilon}}_a)$ for every $\varepsilon>0$ with
     \begin{align}
    \sup_{\varepsilon>0}\mathcal{A}_{\varepsilon}(m^\varepsilon,J^\varepsilon)<\infty
     \end{align}
     and $m^\varepsilon_0\stackrel{*}{\rightharpoonup} \rho_0$ as $\varepsilon\to 0$. Then there exists a subsequence such that $m^\varepsilon\stackrel{*}{\rightharpoonup}\rho$ in $\mathcal{M}_+((0,T)\times \mathbb{R}^n)$ and $\iota J^\varepsilon\stackrel{*}{\rightharpoonup} j$ in $\mathcal{M}((0,T)\times \mathbb{R}^n;\mathbb{R}^n)$, where
     $(\rho,j)$ is a finite action curve.
     In addition 
     \begin{align*}
        m_t^\varepsilon\stackrel{*}{\rightharpoonup}\rho_t 
     \end{align*} for every $t\in[0,T]$ as $\varepsilon\to0$.

