[Theorem inv th1 of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] There exists a constant $\gamma\in (0,1)$ such that for each $t_0\in [0,T]$, one can find a constant $\mathcal{C}=\mathcal{C}(t_0)>0$ satisfying that

\begin{align} 
& |y (t_0)-\hat y(t_0)|_{L^2_{\mathcal{F}_{t_0}}(\Omega;L^2(G))}
 \leq
\mathcal{C} |y (\cdot)-\hat y(\cdot) |^{1-\gamma}_{L^2_{{\mathbb{F}}}(0,T;L^2(G))}
|y(T)-\hat y(T)|^{\gamma}_{L^2_{\mathcal{F}_T}(\Omega;H^1(G))},
\end{align}

where $y(\cdot)$ (resp. $\hat y(\cdot)$) solves the equation (sp-eq1 of the paper) with the initial datum $y_0$ (resp. $\hat y_0$). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 7 (Concentration of random potentials) of arXiv:2604.23461, 'Scaling limit of Sinkhorn-rescaled Random Matrices \\ via Stability of Static Schrödinger '] Let $(\r, \c)$ be an $m \times n$ $\delta$-smooth margin. Under Assumptions \ref{assump:random_matrix} and \ref{assump:bounded_cost}, define the minimum and maximum expected entries $\bLambda_{\min} := \min_{i,j} \bLambda_{ij}$ and $\bLambda_{\max} := \max_{i,j} \bLambda_{ij}$.  Let $(\balpha, \bbeta)$ denote the deterministic Schr\"{o}dinger potentials for $\bLambda$ with margin $(\r, \c)$. Fix $D > 0$ and let $\tau = (D+1)\log(m \vee n) + \log 4$. Define the approximate scaling error $\eps_0$ and the explicit stability constant $C_*$ by:
		\begin{align}
			\eps_0 := \frac{e^{2K}(m\vee n)}{\delta \|\bLambda\|_1} \left( \sigma\sqrt{2(m\vee n)\tau} + 2R\tau \right), \qquad C_* := 1 + \frac{18\, e^{8K} \|\bLambda\|_1^2}{\delta^2 \bLambda_{\min}^2 m^2 n^2}.
		\end{align}
		Suppose $\eps_0 \le \frac{1}{50 C_*^2}$, and define the row-alignment rate
		\begin{align}
			\Phi_{\bLambda} := \min\!\left( n\, \frac{\bLambda_{\min}^4}{(\sigma + R + \bLambda_{\max})^4},\ \sqrt{n}\, \frac{\bLambda_{\min}}{\sigma + R + \bLambda_{\max}} \right).
		\end{align}
		Then there exists an absolute constant $c>0$ such that for the following event
		\begin{align}
			\mathcal{E}_{1} := \{ \X\in \mathcal{S}(\r,\c) \} \cap \left\{ \exists t\in \R\,:\, \max\left( \left\|\balpha_{\X}+t\mathbf{1} - \balpha\right\|_{\infty},\; \left\|\bbeta_{\X}-t\mathbf{1} - \bbeta\right\|_{\infty} \right) \le 4C_* \eps_{0} \right\},
		\end{align}
		we have
		\begin{align}
			\P(\mathcal{E}_{1}) &\ge 1 - (m \vee n)^{-D} - m^2 \exp(-c\,\Phi_{\bLambda}).
		\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 16 (Finite Jacobi normal-form transfer) of arXiv:2608.14475, '\vspace{-1.2cm}\textbf{Finite Gaussian Reconstruction of Polynomial Orbits:\\ From Correla'] Under \eqref{eq:principal-isolated}, there is a contraction
\[
 \left(\mathcal J_m(P)\otimes K\right)[-d]
 \ \underset{\pi}{\overset{\iota}{\rightleftarrows}}\
 (\Omega_K^\bullet,\delta_{0,t}),
 \qquad h_t:\Omega_K^\bullet\longrightarrow\Omega_K^{\bullet-1},
\]
such that
\begin{equation}
 \delta_{0,t}h_t+h_t\delta_{0,t}
 =\Id-\iota\pi,
 \qquad
 \pi\iota=\Id,
 \qquad
 h_t^2=\pi h_t=h_t\iota=0,

\end{equation}
and \(h_t\) lowers polynomial degree by \(m-1\).

The operators
\begin{align}
 \pi_{P,t}
 &=
 \pi(1+\eta_{P,t}h_t)^{-1}
 =
 \pi\sum_{k\geq0}(-\eta_{P,t}h_t)^k,
 \\
 h_{P,t}
 &=
 h_t(1+\eta_{P,t}h_t)^{-1}

\end{align}
are finite on every polynomial form and satisfy
\begin{equation}
 \nabla_{P,t}h_{P,t}+h_{P,t}\nabla_{P,t}
 =
 \Id-\iota\pi_{P,t},
 \qquad
 \pi_{P,t}\nabla_{P,t}=0.

\end{equation}
Consequently
\begin{equation}
 H^p(\Omega_K^\bullet,\nabla_{P,t})=0\quad(p\neq d),
 \qquad
 H^d(\Omega_K^\bullet,\nabla_{P,t})
 \simeq\mathcal J_m(P)\otimes K.

\end{equation}
For every polynomial \(f\),
\begin{equation}
 [f\,\operatorname{vol}_x]_{\nabla_{P,t}}
 =
 [\iota\pi_{P,t}(f\,\operatorname{vol}_x)]_{\nabla_{P,t}}.

\end{equation}
In particular, the direct image has exact rank \(\mu=(m-1)^d\).

[Theorem 1 of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] For every $t \ge 0$ and $q \in \mcl Q_2^\sS$, we have
\begin{equation}  

\lim_{N \to +\infty} \bar F_N(t,q) = \sup_{p \in \mcl Q_\infty^\sS}\inf_{q' \in \mcl Q_\infty^\sS} \mcl J_{t,q}(q',p).
\end{equation}
Moreover, denoting this limit by $f(t,q)$, the function $f$ is the Lipschitz viscosity solution to
\begin{align}
\begin{cases}
    \partial_t f - \int_0^1 \xi(\partial_q f)=0 ,\qquad &\text{on }\R_+\times\mcl Q^\sS_2,
    \\
    f(0,\cdot) = \psi ,\qquad &\text{on }\mcl Q^\sS_2.
\end{cases}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[1 10 (\cite{HX26b}) of arXiv:2606.10058, 'Mean First Passage Times and Fundamental Tensors of Higher Order Markov Chains'] Let $\tilde {\cal P}$ be given as in (\ref{part}). Then, for any $k=1, 2, \ldots$, 
\be

\tilde{\cal P}^k=[\tilde{p}^{(k)}_{i_1i_2\ldots i_m}]=\left[\begin{array}{cc}
{\cal Q}^k & {\cal O}\\
{\cal R}_k & {\cal I}
\end{array}\right],
\ee
where ${\cal R}_k$ satisfies 
$${\cal R}_1={\cal R}, ~{\cal R}_{k+1}={\cal R}_k \boxtimes {\cal Q} + {\cal R}.$$
Equivalently, we have the following partitioned tensor $\boxtimes$ multiplication: 
$$\left[\begin{array}{cc}
{\cal Q}^k & {\cal O}\\
{\cal R}_k & {\cal I}
\end{array}\right] \boxtimes \left[\begin{array}{cc}
{\cal Q} & {\cal O}\\
{\cal R} & {\cal I}
\end{array}\right]=\left[\begin{array}{cc}
{\cal Q}^{k+1} & {\cal O}\\
{\cal R}_{k+1} & {\cal I}
\end{array}\right].$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary ch-5-hidden r-1 of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] For any solution to the equation (ch-5-system1 of the paper), it holds
that

\begin{align}
\notag
\Big|\frac{\partial z}{\partial \nu}\Big
|_{L^2_{{\mathbb{F}}}(0,T;L^2(\Gamma_0))} 
\leq e^{{\cal C}(r_1^2 + r_2^2 +1)}
&  \Big(|(z_0,z_1)|_{L^2_{{\cal F}_0}(\Omega; H_0^1(G)\times L^2(G))}
\\
&+ |f|_{L^2_{{\mathbb{F}}}(0,T;L^2(G))}+
|g|_{L^2_{{\mathbb{F}}}(0,T;L^2(G))}\Big ).
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

