[Corollary of arXiv:2411.08295, 'Improving the convergence of Markov chains via permutations and projections'] Let $P \in \mathcal{L}(\pi) \subseteq \mathcal{M}$ and consider the sequence $(R_n)$ defined in (equation eq:Rndef of the paper), where $Q_i \in \mathcal{I}(\pi) \cap \mathcal{L}$ for $i \in \llbracket 0,m-1 \rrbracket$ is a sequence of isometric involution transition matrices. We have
	\begin{align*}
		\norm{R_{mn} - R_\infty}_F \leq \alpha^n \left\lVertP\right\rVert_F,
	\end{align*}
	where $\alpha$ is given by (equation eq:alpha of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 52 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the notation from Definition \ref{Def.ParametersEdge}. There exist constants $\delta_0 \in (0,1)$ and $C_0 > 0$, depending on $q, \kappa$ and $c$, such that the function $\SFb(z;\kappa)$ is analytic in the disk $\{|z-\zc(\kappa)| < 2\delta_0\}$, the functions $\SFt(z;\kappa), \GFt(z)$ are analytic in the disk $\{|z- c| < 2\delta_0\}$, and the following statements hold. 
If $|z-\zc(\kappa)| \leq \delta_0$, then
\begin{equation}
\left| \SFb(z;\kappa) - \SFb(\zc(\kappa);\kappa)  \right| \leq C_0 |z - \zc(\kappa)|^3.
\end{equation}
If $|z-c| \leq \delta_0$, then
\begin{equation}
\left| \SFt(z;\kappa) - \SFt(c;\kappa) - [\sigmap^2(\bar{\kappa} - \kappa)/2c^2] (z-c)^2 \right| \leq C_0 |z - c|^3,
\end{equation}
\begin{equation}
\left| \GFt(z) - \GFt(c) + (\sigmap^2/2c^2) (z-c)^2 \right| \leq C_0 |z - c|^3.
\end{equation}

[Lemma eq:second_moment_chaos of arXiv:2509.16694, 'A central limit theorem for two-dimensional directed polymers with critical spatial correl'] We have
    \begin{align} 
&E_{x}\left[\prod_{n=s+1}^{t} \{1+\sigma_N^2 h(S_{2n})\}\right]=1+\sum_{k=1}^\infty \sigma_N^{2k} \sum_{s+1\leq n_1<\dots<n_k\leq t} E_{x}\left[\prod_{i=1}^k h(S_{2n_i})\right] \nonumber\\
    &=\sum_{k=0}^\infty \sigma_N^{2k} \sum_{s+1\leq n_1<\dots<n_k\leq t}\,\sum_{x_1,\dots,x_k\in\mathbb{Z}^2} \prod_{i=1}^k  h(x_i)p_{2(n_i-n_{i-1})}(x_i-x_{i-1})\,,
    \end{align}
    where $n_0=0$, $x_0=x$ and $\sigma_N^2>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 66 of arXiv:2608.30549, '\vspace{-1cm}Maximally Spread Out Measures and Implications\\{} for Phase Transitions in A'] Let $\emptyset \ne \Omega \subset \RR^d$ be an open and bounded subset.
Let $A_1,A_2\in \{B,F\}$.
Let $s_1,s_2\in \RR$ and let $0<p_1,q_1,p_2,q_2 \le \infty$ (with $p_i<\infty$ if $A_i=F$).
Assume that 
\begin{equation*}
   s_1 > s_2 
   \quad \text{and} \quad
    s_1 - \frac{d}{p_1} > s_2 -\frac{d}{p_2}.
\end{equation*}
Then the embedding $\iota \colon (A_1)^{s_1}_{p_1,q_1}(\Omega) \embeds (A_2)^{s_2}_{p_2,q_2}(\Omega)$
is compact and there exist constants $C_1, C_2>0$ such that the dyadic entropy numbers of $\iota$ satisfy
    \begin{equation*}
        C_1 \cdot k^{-\frac{s_1-s_2}{d}} 
        \le \en_k(\iota) 
        \le C_2 \cdot k^{-\frac{s_1-s_2}{d}} 
        \quad 
        \text{ for all $k\in \NN$}.
    \end{equation*}

[Lemma 8 of arXiv:2607.07022, 'Coordinate-wise Elephant Random Walk'] Let $t_0:=k\lceil \ln(2k)\rceil.$ Then, for every $x \in Q_k$ and every $A \subseteq Q_k,$
    \begin{equation}
        (K^{\star})^{t_0}(x,A) \geq \frac{1}{2}\pi(A), \qquad x\in Q_k ,\quad A\subseteq Q_k.
    \end{equation}
    Consequently, for every probability measure $\mu$ on $Q_k,$ 
    \begin{equation}
        ||\mu (K^{\star})^{mt_0}- \pi||_{\TV} \leq 2^{-m}, \qquad m\geq0.
    \end{equation}
    In particular, for every bounded $g:Q_k\to\R,$
    \begin{equation}
        \sup_{x\in Q_k} \left|((K^{\star})^{mt_0}g)(x)-\pi(g) \right| \leq ||g||_{\infty}2^{-(m-1)}, \qquad m\geq 0.
    \end{equation}

