[Lemma prop:conformal_rectangles of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] Suppose that we have the same setup as in (rem:no_crossings,rem:crossings_general_case of the paper),  where we explore crossings of the nested $\CLE_4$ $\overline{\Gamma}$ on $\BD$ with height in $\{-\lambda ,  \lambda\}$.  Then,  there exist universal constants $b>0$, $R_0>0$,  and $B>0$,  such that the following is true for all $R \geq R_0$.  Conditional on $U_1,\ldots,U_N$,  the following holds with conditional probability at least $1-2^{-b R}$.  Fix $j \in \{1,\ldots,N\}$ such that the boundary conditions of $\Psi|_{U_j}$ on $\partial U_j$ are given by the zero function and such that $\partial U_j$ contains a crossing of $A$ made by a loop of $\overline{\Gamma}$ with height in $\{\pm \lambda\}$.  Suppose also that we are working on the event that $I_j^3 \cap \partial B_{2^{-2R/3}}(0) = \emptyset$ and $I_j^4 \cap \partial B_{2^{-R/3}}(0) = \emptyset$.  Then,  there exists a collection of conformal rectangles $R_{j,m}$ contained in $U_j$ for $1\leq m \leq 8$,  satisfying the following properties (see (fig:constructing_conformal rectangles2 of the paper) for an illustration).

	\begin{enumerate}
		\item 
		$R_{j,m+1}$ disconnects $R_{j,m}$ from $I_j^3$ for all $m = 1,2,\ldots,7$ in the following sense.  Any path in $U_j$ which connects $I_j^3$ with $I_j^4$ and intersects $R_{j,m}$,  has to cross $R_{j,m+1}$ from its top boundary to its bottom boundary.  Moreover,  the left (resp.\ right) boundary of $R_{j,m}$ is contained in $I_j^1$ (resp.\ $I_j^2$).
		\item 
		For $1 \leq m \leq 8$,  we let $\Gamma_{j,m}$ denote the collection of outermost loops in $\overline{\Gamma}|_{U_j}$ with height in $\{-\lambda,\lambda\}$ which intersect $\partial R_{j,m}$.  Then,  there are no loops in $\Gamma_{j,m}$ intersecting both the top and bottom marked boundary arcs of $\partial R_{j,m}$ and the $D^{U_{j,m}}_{\Gamma|_{U_{j,m}}}$-distance between the left / right marked boundary arcs of $\partial U_{j,m}$ is strictly less than $B$ and the  $D^{U_{j,m}}_{\Gamma|_{U_{j,m}}}$-distance between the top / bottom marked boundary arcs of $\partial U_{j,m}$ is at least $B$,  where $U_{j,m}$ denotes the connected component of $R_{j,m} \setminus \overline{\bigcup_{\SCL \in \Gamma_{j,m}} \SCL}$ whose boundary intersects both the left and right marked boundary arcs of $R_{j,m}$. For later use, we also require the following more precise properties. Here and below,  given a conformal rectangle $W$ with four marked boundary arcs,  we write $L(W)$ (resp.\ $R(W)$) for its left (resp.\ right) marked boundary arc.  One can divide the rectangle $U_{j,m}$ from top to bottom into three conformal rectangles $U^1_{j,m},U^2_{j,m}, U^3_{j,m}$ as in (fig:constructing_conformal rectangles2 of the paper) such that {
			\begin{enumerate}
				\item  The $D^{U_{j,m}}_{\Gamma|_{U_{j,m}}}$-distance from the left boundary $L(U^2_{j,m})$ of $U^2_{j,m}$ to the right boundary of $U^2_{j,m}$ is less than $B$;
				\item  The right boundary (as defined in (lem:genealogy of the paper)) of the metric ball $\SCB_B(L(U_{j,m}), D^{U_{j,m}}_{\Gamma|_{U_{j,m}}})$ intersects the left boundary $L(U^2_{j,m})$;
				\item  The $D^{U_{j,m}}_{\Gamma|_{U_{j,m}}}$-distance from the bottom side to the top side of $U^1_{j,m}$ (resp.\ $U^3_{j,m}$) is at least $B$.
			\end{enumerate}}
	\end{enumerate}


	\begin{figure}[h]
		\centering
		$\vcenter{\hbox{\includegraphics[scale=0.8]{Lemma_constructing_conformal_rectangles2.pdf}}}$


		\caption{Illustration of (prop:conformal_rectangles of the paper). On the left-hand side, we draw the connected component $U_j$ with its associated boundaries. The top boundary $I^3_j$ is associated with the inner boundary of the annulus while the bottom boundary $I^4_j$ is associated with the outer boundary of the annulus. The left and right boundaries $I^1_j$ and $I^2_j$ correspond to crossings by loops. The conformal rectangles $R_{j,1}, \ldots, R_{j,8}$ are drawn in blue. The top and bottom sides of the conformal rectangles $U_{j, 1}, \ldots, U_{j,8}$ are drawn in  (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 11 of arXiv:2608.26288, 'Muon with Finite Newton--Schulz: The Smoothing Benefit in Nonsmooth Nonconvex Optimization'] Suppose~\cref{ass:oracle} holds, $\Gamma>0$, and $\lVert G_s\rVert_{\mathrm{op}}\leq G_{\mathrm{op}}$ almost surely for every~$s$, fix $\rho>0$ and $\epsilon>0$, and let $B_{\mathrm{NS}}\coloneqq\sqrt r((1+2A)\Gamma+\sigma)$.
Running~\cref{alg:generic-o2nc} using \cref{alg:momentum-muon} as its online learner $\mathcal A$ with $1-\beta=\min\{1/9,(\epsilon/3B_{\mathrm{NS}})^2\}$, $D=(1-\beta)\rho/(4\beta)$, and depth $q=\left\lceil\log_A\max\left\{1,\ 3B_{\mathrm{NS}}G_{\mathrm{op}}\sqrt r / (\Gamma\epsilon)\right\}\right\rceil$ gives
\begin{equation}
  \E\brk*{\lVert\nabla\mathcal L(\bar W_\tau)\rVert_*^{[\rho]}}
  \leq\frac{\epsilon}{3} + O\left(
    \frac{\Delta_{\mathcal L}\,r(\Gamma+\sigma)^2}{\rho\epsilon^2 T}
    +\frac{r(\Gamma+\sigma)^2}{\epsilon T}
  \right),

\end{equation}
so $\bar W_\tau$ is a $(\rho,\epsilon)$-stationary point in expectation with gradient-oracle complexity
\begin{equation}
  T=O\left(
    \max\left\{
      \frac{\Delta_{\mathcal L}\,r(\Gamma+\sigma)^2}{\rho\epsilon^3},\
      \frac{r(\Gamma+\sigma)^2}{\epsilon^2}
    \right\}
  \right).

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

