[Thm Generalised Theorem of arXiv:2411.07671, 'Long Time Behavior of General Markov Additive Processes'] Let $((\xi,\Theta),\mathbb{P})$ be a MAP such that Assumptions 1,2,3, and 4* satisfied. Then, 
\begin{enumerate}[label=(\roman*)]
    \item $\xi_t$ drifts to $-\infty$ $\:\mathbb{P}_{0,\pi}$-a.s.,  if and only if\begin{equation*}
    \int_{S\times \mathbb{R}^+}U_\pi^+(dv,dz)\eta^+_v(\zeta^+ =+\infty)=1  \quad \text{and} \quad  \int_{S\times \mathbb{R}^+}\widetilde{U}_\pi^+(dv,dz)\widetilde{\eta}^+_v(\tilde{\zeta}^+ =+\infty)=1
\end{equation*}
\item  $\xi_t$ drifts to $+\infty$ $\:\mathbb{P}_{0,\pi}$-a.s.,  if and only if\begin{equation*}
   \int_{S\times \mathbb{R}^+}U_\pi^-(dv,dz)\eta^-_v(\zeta^- =+\infty)=1 \quad \text{and} \quad  \int_{S\times \mathbb{R}^-}\widetilde{U}_\pi^-(dv,dz)\widetilde{\eta}^-_v(\tilde{\zeta}^- =+\infty)=1
\end{equation*}
\item $\xi_t$ oscillates $\mathbb{P}_{0,\pi}$-a.s., if and only if\begin{equation*}
    \int_{S\times \mathbb{R}^+}U_\pi^+(dv,dz)\eta^+_v(\zeta^+ =+\infty)=0 \quad \text{and} \quad \int_{S\times \mathbb{R}^+}{U}_\pi^-(dv,dz){\eta}^-_v(\zeta^- =+\infty)=0
\end{equation*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm box-bounds of arXiv:2609.03856, 'Consensus time for asynchronous $\ell^p$ relaxation: graph dependence'] Fix $1<p<\infty$, put $q=p/(p-1)$, and let $d,L\ge2$ be integers,
$n=L^d$, and
$0<\epsilon\le1$.  For every
$f_0\in[-1,1]^{[L]^d}$,
\begin{equation}
 \mathbb{E}\tau_p(\epsilon;f_0)\le C_p
 \begin{cases}
 n d^{1/(p-1)}L^{p/(p-1)}\log(n/\epsilon),&1<p<2,\\
 n dL^2\log(n/\epsilon),&p\ge2.
 \end{cases}
\end{equation}
For the worst initial profile,
\begin{equation}
 \sup_{f_0\in[-1,1]^{[L]^d}}\mathbb{E}\tau_p(1/2;f_0)\ge c_pn
 \begin{cases}
 \max\{d^{1/(p-1)-1}L^q,d\log L\},&1<p<2,\\
 dL^2,&p=2,\\
 \max\{d\log L,L^2\},&p>2.
 \end{cases}
\end{equation}
The terms inside a maximum may be realized by different profiles.

[Theorem thm:5.2 of arXiv:2608.27474, 'Nonlocality of Cover-Time Changes Under Edge Addition'] Let \(C_L\) and \(C_L^+\) be the old and unit-inserted worst-start cover
times. Then
\begin{equation}
C_L^+-C_L<0\quad(L=0,1),
\qquad
C_L^+-C_L>0\quad(L\ge2).

\end{equation}
More exactly,
\begin{equation}
C_0^+-C_0=-2,
\qquad
C_1^+-C_1=-\frac2{15}.

\end{equation}

[Corollary 4 (Exact two-population location) of arXiv:2609.03466, 'Least-Favorable Location for Binomial Top-$t$ Selection'] For every $\delta\in(0,1)$,
\begin{equation*}
 \mathcal M_{n,2,1,\delta}
 =
 \begin{cases}
 [0,1-\delta], & n=1,\\
 \{\pc\}, & n\ge2.
 \end{cases}
\end{equation*}
For every $n\ge2$, $\boldsymbol\theta$ minimizes $\PCS_n(\boldsymbol\theta)$ over $\Theta_{2,1,\delta}$ if and only if $(\theta_{[1]},\theta_{[2]})=(\pc,\pc+\delta)$. Thus one may take $n_0(2,1,\delta)=2$ in \Cref{thm:global-top-t}.

[Theorem 1 of arXiv:2608.25887, '\bf Efficient Estimation of High Information Projections using Nearest Neighbours'] Let $X_1, X_2, ...$ be a sequence of i.i.d. random variables on $\R^p; p > 4$, with density function $f_X$ satisfying
    \begin{itemize}
    \item[C1:] The support of $f_X$ is bounded, i.e. $\exists M > 0$ s.t. $Supp(f_X):= \{\x \in \R^p | f_X(\x) > 0\} \subset B_M(\0)$.
    \item[C2:] The density $f_X$ has bounded first two derivatives on the interior of $Supp(f_X)$.
    \item[C3:] There exist $l, H > 0$ s.t.
    \begin{align*}
        \sup_{\substack{\x \in Supp(f_X)\\0 < h_1 \leq h_2 \leq H}} \frac{f_X(\x)^2h_1^{p-1}h_2^{p-1}h_2^3}{\oint_{B_{h_1}(\x)}\oint_{B_{h_2}(\x)}f_X(\z)f_X(\w)d\z d\w} \leq l
    \end{align*}
    \item[C4:] For any $a > 0$ $\exists U > 0$ for which
    \begin{align*}
        \sup_{\substack{\x \in Supp(f_X),\\ 0 < u < U}} \frac{1}{\Fdx(u)^k} \int_1^\infty \Fdx( u\epsilon^{-1/a})^k d\epsilon = o(1),
    \end{align*}
    as $k \to \infty$.
\end{itemize}
Then
\begin{align*}
    I(\X_n, k(n)) \xrightarrow{P} I(f_X)
\end{align*}
provided the sequence $\{k(n)\}_{n \in \mathbb{N}}$ satisfies $k(n) \to \infty$ and $k(n)^{2-p/4}/n^{1-p/4} \to 0$ as $n\to\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 12 of arXiv:2606.27078, 'Semimartingale Optimal Transport with Jumps: A General Framework and Equivalent Formulatio'] Let $\Theta \subseteq \mathbb{R}^d \times \mathbb{S}_+^d \times \mathcal{L}$ be closed, convex, and satisfy Assumptions \ref{B} and \ref{J}. Moreover, let $\ell$ satisfy Assumption~\ref{ellcontinuous}. Then $\lambda$ is the unique viscosity solution of the HJB equation
\begin{equation}
\begin{cases}
-\partial_{t}\lambda(t,x)-H\bigl(t,x,D_x\lambda(t,x),D_{xx}^2\lambda(t,x),\lambda(t,x+\cdot)\bigr)=0,\\
\lambda(1,x)=\lambda_1(x).
\end{cases}
\end{equation}

