[Lemma thm:lem4.5 of arXiv:2509.20657, 'Scaling limit for Brownian motions \\ on the $l$-level Sierpinski gaskets: \\ The fractal '] There exists finite constants $C>0$ and $C_0>1$ such that for $l\geq 2$: if $r\in  (\tfrac14l^{-(m+1)},\tfrac14l^{-m}]$ for some $m\geq 0$, $x\in \psi_i(\Delta)$ for some $i=(i_1,\dots,i_{m})\in\{1,\dots,N_{d,l}\}^{m}$, where we define $\psi_i:=\psi_{i_1}\circ\cdots\circ \psi_{i_{m}}$, and $f\in\mathcal{F}^l$, then
\begin{equation}
\int_{B(x,r)\cap\psi_i(\mathrm{SG}(l))}\left(f(y)-\bar{f}^{l,i}_{B(x,r)}\right)^2\mu^l(dy)\leq C\Psi_l(r)\rho_l^{m+1}
\sum_{\substack{j\in \{1,\dots,N_{d,l}\}^{m+1}:\\(j_1,\dots,j_m)=(i_1,\dots,i_m),\\\psi_j(\mathrm{SG}(l))\cap B(x,5r)\neq \emptyset}}\mathcal{E}^l\left(f\circ\psi_j,f\circ\psi_j\right),
\end{equation}
where
\[\bar{f}^{l,i}_{B(x,r)}:=\frac{1}{\mu^l(B(x,r)\cap\psi_i(\mathrm{SG}(l)))}\int_{B(x,r)\cap\psi_i(\mathrm{SG}(l))}f(y)\mu^l(dy).\]

