[Proposition 32 (Annulus BPZ) of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] Recall that $\Theta_1, \Theta_3$ are rescaled Jacobi theta functions in~\eqref{eqn::JacobiTheta_productexpansion}. Define
\begin{align} 
	H_1(r;z) := 2 \partial_z \log \Theta_1(r;z), \qquad
	H_3(r;z) := 2 \partial_z \log \Theta_3(r;z).
\end{align}
The partition functions $\LZann{n}$ and $\LZcro{n}^{(\ell)}$ in~\eqref{eqn::LZann_def} and~\eqref{eqn::LZcroell_def} satisfy the following system of annulus BPZ equations: for all $j\in\{1, \ldots, n\}$, 
\begin{align} 
	\begin{split}
		\frac{\partial_r \LZ}{\LZ}=2\frac{\partial_{\alpha_j}^2 \LZ}{\LZ} & +   \sum_{\ell\neq j} \left( H_1(r; \alpha_\ell-\alpha_j) \frac{\partial_{\alpha_\ell} \LZ}{\LZ} + \frac{1}{4} \partial_z H_1(r; \alpha_\ell-\alpha_j) \right) \\
		& +  \sum_{\ell=1}^n \left( H_3(r; \beta_\ell-\alpha_j) \frac{\partial_{\beta_\ell} \LZ}{\LZ} + \frac{1}{4} \partial_z H_3(r; \beta_\ell-\alpha_j) \right) + \frac{1}{2r} + \frac{3}{4} \LE(r) + \frac{n}{4}; 
	\end{split} \\

	\begin{split}
		\frac{\partial_r \LZ}{\LZ}= 2\frac{\partial_{\beta_j}^2 \LZ}{\LZ} &+  \sum_{\ell\neq j} \left( H_1(r; \beta_\ell-\beta_j) \frac{\partial_{\beta_\ell} \LZ}{\LZ} + \frac{1}{4} \partial_z H_1(r; \beta_\ell-\beta_j) \right) \\
		& +  \sum_{\ell=1}^n \left( H_3(r; \alpha_\ell-\beta_j) \frac{\partial_{\alpha_\ell} \LZ}{\LZ} + \frac{1}{4} \partial_z H_3(r; \alpha_\ell-\beta_j) \right) + \frac{1}{2r} + \frac{3}{4} \LE(r) + \frac{n}{4}; 
	\end{split}
\end{align}
where \begin{equation} 
	\LE(r) := -\frac{1}{6} + \sum_{k=1}^{\infty} \frac{1}{\sinh^2(kr)}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:log_price_sig_repr of arXiv:2604.22528, 'Malliavin calculus for signatures with applications to finance'] The log-price $X_t = \log S_t$ for $t \in [0, T]$ is given by
\begin{equation}
    X_t = \bracketsigW{\bm{\ell}^X}, \quad\bm{\ell}^X := \log (S_0){\color{NavyBlue}{\mathbf{\varnothing}}}{-\dfrac{1}{2}\bm{\sigma}^{\mathrel{\sqcup \mkern -3mu \sqcup} 2}\otimes{\color{NavyBlue}{\mathbf{0}}} + \rho\left(\bm{\sigma}\otimes{\color{NavyBlue}{\mathbf{1}}} - \dfrac{1}{2}\bm{\sigma}|_{{\color{NavyBlue}{\mathbf{1}}}}\otimes{\color{NavyBlue}{\mathbf{0}}}\right) + \bar\rho\bm{\sigma}\otimes{\color{NavyBlue}{\mathbf{2}}} } \in \TA,
\end{equation}
where $\bm{\sigma}|_{{\color{NavyBlue}{\mathbf{i}}}}= \sum_{n \geq 0}\sum_{|{\color{NavyBlue}{\mathbf{v}}}|=v}\bm{\sigma}^{{\color{NavyBlue}{\mathbf{vi}}}}{\color{NavyBlue}{\mathbf{v}}}$.

