[Lemma l:basic-properties-weighted-sobolev of arXiv:2607.24640, 'The Yang-Mills measure on surfaces via Morse theory'] Let $(q,q')\in  \mathbb{R} _+^2$ and $(p,p')\in  \mathbb{Z} _+^2$. One has
\begin{enumerate}
\item if $p\leqslant p'$ and $q\leqslant q'$, then $H^{p',q'}(\Sigma\setminus\{a_{2g+2}\},T^*\Sigma\otimes\mathfrak{g})$ is continuously embedded in $H^{p,q}(\Sigma\setminus\{a_{2g+2}\},T^*\Sigma\otimes\mathfrak{g})$;
\item if $p< p'$ and $q+p< q'$, then $H^{p',q'}(\Sigma\setminus\{a_{2g+2}\},T^*\Sigma\otimes\mathfrak{g})$ is compactly embedded in $H^{p,q}(\Sigma\setminus\{a_{2g+2}\},T^*\Sigma\otimes\mathfrak{g})$.

\item the Hilbert space $H^{p,q} \left( \Sigma \setminus \{a_{2g+2}\}, T^*\Sigma\otimes \mathfrak{g}  \right) $ is separable and with a countable dense family in $\Omega^1_c \left( \Sigma \setminus \{a_{2g+2}\},  \mathfrak{g}  \right) $.
\end{enumerate}

[Lemma 67 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the same notation as in Definition \ref{Def.LETop}. For any $s \in [0, \bar{\kappa})$, we can find $\epsilon > 0$, depending on $q,c,s$, such that 
\begin{equation}
\lim_{N \rightarrow \infty} \mathbb{P}_N \left( L_2^N(\lfloor tN\rfloor ) \geq h_2(t)N - \epsilon N \mbox{ for some }t \in [0, s] \right) = 0.
\end{equation}

