[Lemma 12 of arXiv:2606.12720, 'On McDiarmid's Inequality under Dependence \\ via Approximate Tensorization of Entropy'] {Approximate Entropy Conservation (Proposition 39, \cite{chen:eldan2022})}


    Let $\nu_t$ be a stochastic localization process as in Definition \ref{def:stoclocproc} with driving matrix $C_t$. Fix $T > 0$ and suppose that for all $t \in [0,T]$ the $\nu_t$ are $\epsilon_t$-entropically stable \wrt{} $\psi(x,y) := \frac 1 2 \twonorm{C_t(x-y)}^2$. Then, $\nu_t$ fulfills the following approximate entropy conservation
    \begin{align*}
        \ent[\nu]{f}
        \leq \exp\Parent{\int_0^T \epsilon_t dt} \cdot \E[\ent[\nu_T]{f}], 
        \quad \text{for all $f : \R^n \to [0,\infty)$}.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 34 (Asymptotic) of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] For $\bs{\theta}=(\theta_1, \ldots, \theta_n)\in\LX_n$, define 
\begin{align}
\LZ_n(\bs{\theta})=\prod_{1\le i<j\le n}\left|\ee^{\ii\theta_i}-\ee^{\ii\theta_j}\right|^{\frac{1}{2}(-1)^{j-i}}, \qquad
\LZradial{n}(\bs{\theta})=\prod_{1\le i<j\le n}\left|\ee^{\ii\theta_i}-\ee^{\ii\theta_j}\right|^{\frac{1}{2}}. 
\end{align}
Assume the same setup as in Theorem~\ref{thm::crossingproba}. The crossing probabilities have the following asymptotic as $r\to\infty$: 
\begin{align}
&\PP[\cross(\bs{\gamma}), \wind(\bs{\gamma})=(m;\ell)]=\sqrt{2}^{n^2}\frac{\LZradial{n}(\bs{\alpha})\LZradial{n}(\bs{\beta})}{\LZ_n(\bs{\alpha})\LZ_n(\bs{\beta})}\exp\left(-\frac{n^2r}{8}-\frac{1}{8r}\LA(\bs{\alpha}, \bs{\beta}; m; \ell)+O(1)\ee^{-r} \right);\\
&\PP[\cross(\bs{\gamma})]=\sqrt{2}^{n^2}\frac{\LZradial{n}(\bs{\alpha})\LZradial{n}(\bs{\beta})}{\sqrt{2\pi}\LZ_n(\bs{\alpha})\LZ_n(\bs{\beta})}\exp\left(-\frac{n^2r}{8}+\frac{\log r}{2}+\frac{1}{8r}\left(\sum_{j=1}^n(-1)^j(\alpha_j-\beta_j)\right)^2+O(1)\ee^{-r/n^2}\right);
\end{align}
where 
\begin{align*}
\LA(\bs{\alpha}, \bs{\beta}; m; \ell)=\left(\sum_{j=1}^{n}(\alpha_j-\beta_{j})-2m\pi-2n\pi\ell\right)^2-\left(\sum_{j=1}^{n}(-1)^j(\alpha_j-\beta_j)\right)^2. 
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

