[Theorem hls of arXiv:2411.05204, '\Large\bf Sample Path Properties of the Fractional Wiener--Weierstrass Bridge'] Let $H\in(0,1),\,k\in\mathbb N,\,\alpha\in(0,1),\,b=\alpha^{-1/H}$, and $\{I_m\}_{m\in\mathbb N_0}$ be a collection of $k$-intervals with $|I_m|=b^m$. Define
\begin{align}
f_m:=\alpha^m {\mathbbm{1}} _{I_m} \quad \text{ and }\quad g_M:=\sum_{m=0}^{M-1}f_m.
\end{align}
Then there exists $L>0$, depending on $k,H,\alpha,b$, such that for all $M\in\mathbb N$,
\begin{align}
    \frac{M}{L}\leq \left\lVertM_-^H(g_M)\right\rVert_{L^2}^2\leq LM.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 of arXiv:2609.03958, '2609.03958'] Let $\lambda\in \Gamma_2$ and $\sigma_2(\lambda)=f$. Assume that $$\ell_i:=\sigma_1(\lambda)-\lambda_i,\ \ \ i=1,\ldots,n.$$
Then we have 
\begin{equation}
 R_k:=\max_{\substack{z\ne0\\ \ell\cdot z=0}}
      \frac{(e\cdot z)^2}{z^TD_kz}=\frac13\left[ n+2- \frac{\bigl((n-1)\sigma_1(\lambda)+2\ell_k\bigr)^2} {(n-1)\sigma_1^2(\lambda)-2f+2\ell_k^2} \right].
\end{equation}

[Theorem 26 of arXiv:2606.21111, 'On Elephant Random Walk with Delayed Amnesia'] Let $(4a-1)/4a<p\le1$. Then,
	\begin{equation*}
		\lim_{n\to\infty}\frac{W_n}{n^{2a(p-1)+1}}=\mu L\ \ \text{a.s.},
	\end{equation*}
where $L$ is as given in \eqref{Lvariab}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2606.22940, 'From smooth to discontinuous kernels: a variance transfer principle for hyperuniform proce'] (Non-asymptotic result) Let $ d\geqslant 1.$ Let $  \alpha \geqslant 0.$ Let $\maxscale,\delta >0$  such that $\maxscale (d + 2) + \delta <\frac{ 1}{d}$. 
 \begin{itemize}
\item (i) Assume that there exists  a non-degenerate  function $ f\in \B_{ c}^{ }(B_{ 1})$ non-negative such that for some finite constant $ C_{ f}$,    for all $N\geqslant 1,R \in [1,N^{ \maxscale }]  ,$  
\begin{align}

\sup_{ x\in \Sigma ^{ R }}\mathbf E  \left[\;
   \overline{\X_{ N}}(\tau _{ x}f_{ R  }) ^{ 2}
\right]\leqslant C _{ f}  R ^{ d  -\alpha }.
\end{align}

 Then   for $N\geqslant 1,\varepsilon _{ N}: = N^{ -\delta },$
  for $\gamma \in (0,1], \varphi \in \F_{ \gamma }(B_{ 1})$ we have  for all $ R \in [R^{ \circ}_{ f},N^{ \maxscale }],$   
\begin{align}

\sup_{ x\in \Sigma ^{2\varepsilon _{ N}N^{ 1/d}  }} \overline{  \textrm{Var} }^{ \varepsilon _{ N}}\left[
{ \X_{ N}}(\tau_{ x }\varphi _{  R} )
\right]\leqslant C_{ \varphi ,f} V_{ \alpha ,\gamma }(R)\end{align}

where $ C_{ \varphi ,f},R^{ \circ}_{ f}<\infty $ only depend on $ \varphi ,f,d,C_{ f}.$

 \item (ii) {\bf Converse direction}. Assume $ \alpha \in (0,2).$  Let  $ f\in \C_{ c}^{ k}(  \mathbb  T  _{ 1}^{ d})$  for some $k>(d + 1)/2 $.
Assume that   there is $R _{ N}\leqslant N^{ \maxscale }$ with $ R_{ N}\to \infty $ such that,  with $ \varepsilon _{ N} = N^{ -\delta }$,
\begin{align}

 \frac{  \overline{\textrm{Var}}^{ \varepsilon _{ N}}\left(\X_{ N}(f_{ R_{ N}})\right)}{V_{ \alpha ,1}(R_{ N})} \to \infty .
\end{align}
Then there is $ R_{ N}'\in [1,R_{ N}]$ such that
\begin{align}
  \frac{  \textrm{Var}\left(\X_{ N}(B(0,R_{ N}'))\right)}{ V_{ \alpha  ,1 }(R'_{ N})} \to \infty .
\end{align}

\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition Censored random walk, \cite{ding2014mixing} of arXiv:2505.02685, 'On the Spectral Expansion of Monotone Subsets of the Hypercube'] Given $A \subseteq \{0,1\}^n$, the \emph{random walk on $\{0,1\}^n$ censored to}
    $A$ is defined as follows. On state $x \in A$, sample $i \in [n]$ uniformly
    at random and let $y$ be the vertex obtained by flipping the $i$-th bit of
    $x$. Then
    \begin{enumerate}
        \item If $y \in A$, flip a coin and either stay at $x$ or move to $y$ (each with probability $1/2$).
        \item If $y \not\in A$, stay at $x$ (in which case we call this a \emph{censored} step).
    \end{enumerate}

[Proposition 40 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] Let $0<T\le1$, $0<\sigma<1$, and suppose that $H$ satisfies the parabolic tail condition \eqref{eq:parabolic-tail-bound}.  Then the heat spectral splitting satisfies
\begin{equation}

\max\{\norm{Q_{cb}}_{H^\alpha},\norm{Q_{ba}}_{H^\alpha}\}\le \left(\frac12+C L^\eta\right)\norm{Q_{ca}}_{H^\alpha} +C\bigl(\norm{H}_{\gamma,\alpha}+K\bigr)L^\gamma,
\end{equation}
where $\eta:=\min\{1-\sigma,\rho\}>0$ and $\rho=\frac{\sigma\beta}{2}$.
In particular, at $\gamma=1$ this is a critical admissible scale splitting.  If $0<\gamma<1$, then after restricting to a sufficiently small time horizon $T_0$, it is a subcritical admissible scale splitting, because $1/2+C T_0^\eta<2^{-\gamma}$.

[Thm Thm_MakNikPal of arXiv:2606.22183, 'Expected loss of quasi-arithmetic means of exchangeable random variables'] Let $I\subseteq \mathbb{R}$ be a nonempty open interval, $\alpha:(I-I)\to\mathbb{R}_+$ be an even error function, and $L:I\to \mathbb{R}$ be a function.
Then the following two assertions are equivalent:
 \begin{enumerate}
   \item[(i)] $L$ is strongly $\alpha$-convex, i.e., (equation help_strongly_alpha_convex_def of the paper) holds for all  $x,y\in I$ and $t\in[0,1]$.
   \item[(ii)] For all $x_0\in I$, there exists a constant $c_{x_0}\in\mathbb{R}$ such that
         \begin{align}
           L(x)\geqslant L(x_0) + c_{x_0}(x-x_0) + \alpha(x-x_0),\qquad x\in I.
         \end{align}
 \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:H-norm-integral of arXiv:2412.01645, 'Regularisation by Gaussian rough path lifts of fractional Brownian motions'] Let $(s, t) \in [0,1]^2_{\leq}$ and let $f,g \in \mathcal{H}$ such that they both have support in $[s,t]$ and $f,g \in \mathcal{C}^\gamma([s,t])$ for some $\gamma>1-2H$. Then we have 
    \begin{equs}
        \langle  \Pi_{\mathcal{H}_s^\perp} f,  \Pi_{\mathcal{H}_s^\perp} g \rangle_{\mathcal{H}} =\int_s^t \int_s^t f(u) g(r) Q_s(du,dr).
    \end{equs}

