[Theorem 7 of arXiv:2608.17493, 'Integrals of some compound processes'] Let $M\sim CP(\lambda, F)$, $f$ be a Bernstein function (see \eqref{definizioneFunzioneBernstein}) and $\mathcal{H}_f$ be the corresponding Bernstein subordinator.
\begin{itemize}
	\item[($i$)] $a=0$ if and only if $M\circ \mathcal{H}_f\sim CP\big(f(\lambda), F_f\big)$, with 
	$F_f$ in \eqref{distribuzioneComposizioneBernstein}. The jumps are distributed as $Y = \sum_{h=1}^A X_h$, with $A$ being independent of $X_1,X_2,\dots\sim F$ and $M$ and $P\{A = k\} = a'_k,\ k\ge1,$ with $a'_k$ in ($iii$) of Lemma \ref{lemmaEquazioneOperatorialeBernstein}.



	\item[($ii$)] Let $a=0$. The probability law of $M\circ\mathcal{H}_f$ satistfies, for $x\in\mathbb{R}$,	\begin{equation}
		\frac{\dif}{\dif t}p(t, \dif x) = - f\Big(\lambda\big(I-C_F\big)\Big)p(t, \dif x), \ t\ge0,\ \ \ p(0,\dif x) = \delta_0(\dif x).
	\end{equation}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem NonlinearVolterra02 of arXiv:2411.15485, '\bf\Large Stochastic Volterra Equations for Local Times of Spectrally Positive L\'evy Proc'] For any $T\geq 0$ and $\sigma$-finite measure $\mu(dx)$ on $\mathbb{R}_+$, the following hold.
 \begin{enumerate}
  \item[(1)] For any $\beta\in\mathbb{R}$, the nonlinear Volterra equation (equation NonlinearVolterra of the paper) is equivalent to 
  \begin{eqnarray}
  V_\mu (t) =   W'_\beta*d\mu(t) + \big(\beta  V^g_\lambda-\boldsymbol{\mathcal{R}}\circ  V_\mu\big) *W'_\beta(t) ,\quad t\geq 0.
  \end{eqnarray}

  \item[(2)] The nonlinear Volterra equation (equation NonlinearVolterra of the paper) has a unique  global solution $V_\mu \in D(\mathbb{R}_+;\mathbb{R}_+) $ such that 
  \begin{eqnarray}
  0\leq V_\mu(t) \leq \frac{\mu([0,t])}{c},\quad t\geq 0.
  \end{eqnarray}

  \item[(3)] The process  $Z_T:=\{Z_T(t):t\in[0,T] \}$ with
  \begin{eqnarray*}
  Z_T(t):= \mathbf{E}\big[  X_\zeta*d\mu(T) \,\big|\, \mathscr{F}_t \big] - \int_t^T \big(\boldsymbol{\mathcal{R}}\circ V_\mu\big) (T-s) \mathbf{E}\big[  X_\zeta(s) \,\big|\, \mathscr{F}_t \big] ds  
  \end{eqnarray*}
  is a continuous $(\mathscr{F}_t)$-semimartingale. 

  \item[(4)] The process $e^{-Z_T}:=\{ e^{-Z_T(t)}: t\in[0,T]  \} $ is a continuous $(\mathscr{F}_t)$-martingale. 

  \item[(5)] The Laplace functional of the process $L^\xi_\zeta$ admits the representation
  \begin{eqnarray*}
  \mathbf{E}\big[ \exp\big\{-  L^\xi_\zeta *d\mu(T) \big\} \big]
  = \mathbf{E}\big[ \exp\big\{ -Z_T(T) \big\} \big] 
  = \exp\big\{  -\zeta \cdot \boldsymbol{\mathcal{F}}\circ V_\mu(T)   \big\}, 
  \end{eqnarray*}
  where $\boldsymbol{\mathcal{F}}$ is a nonlinear operator acting on a locally integrable
  function $f$ by
  \begin{eqnarray*}
  \boldsymbol{\mathcal{F}}\circ f(t)
  \!\!\!&=\!\!\!& c\cdot f(t) + \int_0^\infty \Big(1- \exp\Big\{-\int_{(t-y)^+}^{t} f(r)dr\Big\}   \Big) \bar\nu(y)dy . 
  \end{eqnarray*} 
 \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 24 of arXiv:2605.03851, 'The Relay Random Tree:\\A stochastic geometry approach of multihop relay in an urban visib'] \textbf{Markov behaviour in horizontal finite range.}

For $n\in\N$, let $\tilde{x}_n:= X_n-X_{n-1}$ denote the length of the $n-$th hop.

The sequence $(\tilde{x}_n, \mathrm{t}_n, H_n)$ is a Markov chain with kernel $\mathrm{VIS}_R$ given by:
    \begin{align*}
        &\forall (\tilde{X}, T, H)\in \Half, \forall A \in \mathcal{B}(\R\times\Half), \mathrm{VIS}_R((\tilde{X}, T, H), A) = \int_A vis^{\tilde{X}, T, H}(t, h) \delta_{\frac{h-H}{t} }(\tilde{x})\rm{d}\Leb(t) \rm{d}\mathcal{L}(h)
        \end{align*}
    \begin{align*}
        \forall \tilde{X}, T, H, t, h \in \R_+, vis^{\tilde{X}, T, H} (t, h) :=\frac{h-H}{t^2}\lambda \exp\Biggl(-\lambda \Biggl(&\frac{\primi(H)-\primi(H+(R-\tilde{X})T)}{T}-\frac{\primi(H+Rt)-\primi(H)}{t}\\
        &+\frac{\primi(H + (R-\tilde{X} (t \wedge T)}{t\wedge T}-\frac{\primi(H +(R-\tilde{X} t)}{t}\Biggl)\Biggl)\\
        &\mathds{1}_{\frac{h-H}{t}\in ]0, R], T\geq t \text{ or } \tilde{X}+ \frac{h-H}{t}> R } ,
    \end{align*}
    and 
    \begin{align*}
        &\mathrm{VIS}_R((\tilde{X}, T, H), (-\infty, -\infty, -\infty)) = \exp\Biggl(-\lambda \Biggl(R - \frac{\primi(H)-\primi(H+(R-\tilde{X})T)}{T}\Biggl)\Biggl)\\
        &\mathrm{VIS}_R((-\infty, -\infty, -\infty), (-\infty, -\infty, -\infty)) = 1.
    \end{align*}

[Definition def-rareevent of arXiv:2603.01322, 'Gibbs conditioning, atypical consensus and splitting Gibbs measures on random regular grap'] Given an edge potential $h$ and $\cc\in \R$ with $ \cc \neq \sref$, 
let the event $\Conset_n(h,\cc)$ be defined by 
\begin{align}
    \Conset_n(h,c)\coloneqq
    \begin{cases}
       \{ \mathbb{E}_{L_n} [S_h] \geq \cc\} \quad \text{ if } \cc > \sref,\\
       \{ \mathbb{E}_{L_n} [S_h] \leq \cc\} \quad \text{ if } \cc < \sref. 
    \end{cases}

\end{align}
and let the collection of measures $\Conset(h,\cc)$ be defined by
\begin{align}
    \Conset(h,c)\coloneqq
    \begin{cases}
       \{ \mu\in \P\cpr{\TkappaX{1}}:\mathbb{E}_{\mu} [S_h] \geq \cc\} \quad \text{ if } \cc > \sref,\\
       \{ \mu\in \P\cpr{\TkappaX{1}}:\mathbb{E}_{\mu} [S_h] \leq \cc\} \quad \text{ if } \cc < \sref. 
    \end{cases}

\end{align}

[Theorem thm:ldp of arXiv:2512.17747, 'On exponentially height-penalized random trees'] Let $\mu=\mu_n$ be such that $1/\sqrt{n}\ll\mu\ll n$.
    Let $\mathbf{T}_n$ be a $\mu$-height-biased tree of size $n$.
    Then the sequence of random variables $(h(\mathbf T_n)/(2\pi^2n/\mu)^{1/3})_{n \geq 1}$ satisfies a large deviation principle at speed $(\mu^2 n)^{1/3}$ and with good rate function given by
    \begin{align*}
        \Lambda^*(x)=\left\{\begin{array}{ll}
            \left(\frac{\pi}{2}\right)^{2/3}\frac{(x-1)^2(2x+1)}{x^2} & \textrm{if $x>0$} \\
            \infty & \textrm{otherwise.}
        \end{array}\right.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor eigencor of arXiv:2411.18359, 'Large systems of symmetrized trapped Brownian Bridges and Schr\"odinger processes'] Assume in addition that $g,\mu$ and $W$ are such that the operator 
    \begin{equation}
        T(f)(x):=\int_{\mathbb{R} ^d} f(y) \mathbb{E}_{x,y}^{\beta}\left [e^{-\Tilde{W} }\right]g(x,y){\mathfrak m}({\rm d} y)
    \end{equation}
    attains its minimum eigenvalue $\lambda_T>0$ with corresponding ${\mathfrak m}$-normalized eigenfunction $\varphi^2_T \in H^1(\mathbb{R} ^d)$. Then \item[(i)] we have
\begin{equation}
\begin{aligned}
&\inf_{\mu \in {\mathcal M }_1({\mathcal C }_\beta)}\Bigl\{I^{{\scriptscriptstyle{({\rm sym}})}}_{W,{\mathfrak m}}(\mu)-\langle \mu_{0,\beta},\log g\rangle\Bigr\}=-\log \lambda_T. 
\end{aligned}
\end{equation}
\item[(ii)] The minimizer of (i) is given by 
\begin{equation}
    \mu^*_{T}=\frac{1}{\lambda_T}\int_{\mathbb{R}^d}\int_{\mathbb{R}^d} \varphi_T(x)\varphi_T(y)e^{-\Tilde{W} }\mathbb{P}_{x,y}^{\beta}g(x,y){\mathfrak m}({\rm d} y){\mathfrak m}({\rm d} x).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

