body:
[Thm 79 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $n\geq 1$.
The Wick power $:\Phi^{n}:$ can be decomposed
\begin{displaymath}
:\Phi^{n}:~= \psi^{\rm gen}_{n,0}
+
\sum_{m=1}^{+\infty}
\sum_{0\leq k <\lfloor n/2\rfloor}
(-1)^{k}\dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen, +}_{m-1}}^{k}
\,
\psi^{\rm gen}_{n-2k,m}
\, ,
\end{displaymath}
where the convergence holds in $L^{2}(d\PP,\sigma(\Phi),H^{-\eta}(\C))$ for $\eta>0$.
Moreover, one has the following $L^2$ decomposition of Sobolev norms:
\begin{eqnarray*}
\E\Big[
\Vert
:\Phi^{n}:
\Vert^{2}_{H^{-\eta}(\C)}
\Big]
&=&
\E\Big[
\Vert
\psi^{\rm gen}_{n,0}
\Vert^{2}_{H^{-\eta}(\C)}
\Big]
\\&&+
\sum_{m=1}^{+\infty}
\E\Big[
\Big\Vert
\sum_{0\leq k <\lfloor n/2\rfloor}
(-1)^{k}\dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen, +}_{m-1}}^{k}
\,
\psi^{\rm gen}_{n-2k,m}
\Big\Vert^{2}_{H^{-\eta}(\C)}
\Big]
\, .
\end{eqnarray*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 10 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] Let $f$ and $g$ be nonnegative real functions defined on $\T^d\times\R^d$ with $m_0(f)$, $m_1(f)$, $m_0(g)$ and $m_1(g)$ which are finite almost everywhere.
Let $k>1+\frac{d}{2}$ (\emph{i.e.} $k\geq 3$ since $k$ is an integer), then there exists a constant $C=C(k,d)>0$ such that
\begin{equation*}
\lVert m_{0}(f) -m_{0}(g) \rVert_{L^2_x} \leq C \lVert \langle v \rangle^k (f-g) \rVert_{L^2_{x,v}},
\end{equation*}
and
\begin{equation*}
\lVert m_{1}(f) - m_{1}(g)\rVert_{L^2_x} \leq C \lVert \langle v \rangle^k (f-g) \rVert_{L^2_{x,v}}.
\end{equation*}

