[Lemma lem.glivenkocantelli of arXiv:2605.14149, 'The mean-field limit of online stochastic vector balancing'] Suppose that $\bm{x}^n = (x^n_1,\dots,x^n_n) \in {\mathbb R}^n$, and $h^n \in {\mathbb R}_+$ are such that
    \begin{align*}
        m_{\bm{x}^n}^n \xlongrightarrow{\mathbf{d}_p} m, \qquad h^n \longrightarrow h,
    \end{align*}
    for some $m \in \mathcal{P}_p({\mathbb R})$ and $h \in (0,\infty)$. Suppose moreover that for each $n$,
    \begin{align*}
        \bm{G}^n = \big(G^n_1,\dots,G^n_n \big) \sim \gamma_{h^n}^{\otimes n}.
    \end{align*}
   Then,
    \begin{align*}
       \mathbf{d}_p\big( m_{\bm{x}^n + \bm{G}^n}^n, m * \gamma_h \big) \longrightarrow 0\quad \text{  in probability.}
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemm boundZ of arXiv:2412.08497, 'Time discretization of Quadratic Forward-Backward SDEs with singular drift'] Let assumptions of Lemma (lemm4.1 of the paper) hold. Then for any $p >p_0'> 1$ there is a constant $C$ only depending on $p,d,T$ and $\|b\|_{L^{\infty}([0,T];C_b(\mathbb{R}^d))}$ such that 
				\begin{equation}
					\mathbb{E}\big[\sup_{ 0\leq t\leq T}|Z_t|^p\big] \leq C(1 + S^p({\varphi})),
				\end{equation}
				where $p_0'$ is the conjugate of $p_0$ and $p_0$ is such that $\mathcal{E}\left(\nabla_z g*W\right) \in L^{p_0}$(see Remark (rem3.1 of the paper)).
				In particular, if $g$ is Lipschitz continuous in $y$ then the control process $Z$ is uniformly bounded i.e. there is a constant $C>0$ such that
				\begin{align*}
					|Z_t|\leq Ce^{\|\nabla_y g\|_{\infty}}(1+S(\varphi)).
				\end{align*}

[Definition def_3_SBO of arXiv:2411.13972, 'The Stochastic Bessel operator at high temperatures'] ~\\ \emph{
Let $B$ be a standard Brownian motion on $\mathbb{R}_+$. For $\beta>0$ and $a>-1$, the stochastic Bessel operator (known as SBO) is the random differential operator
\begin{gather*}
\mathfrak{G}^{\beta,a} = -\frac{1}{m(x)}\frac{\mathrm{d}}{\mathrm{d} x}\Big(\frac{1}{s(x)}\frac{\mathrm{d}}{\mathrm{d} x}\Big), \\ 
m(x)=\exp\big(-(a+1)x-\frac{2}{\sqrt{\beta}}B(x)\big), \quad s(x)=\exp\big(ax+\frac{2}{\sqrt{\beta}}B(x)\big),
\end{gather*}
defined on a subset of $L^2(\mathbb{R}_+,m)$ with Dirichlet and Neumann boundary conditions at $0$ and at infinity, respectively.
}

[Cor 48 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $\eta\in (0,1)$.
Then there are constants $c,C>0$,
depending only on $\eta$ and $v$, such that
for every $\varepsilon>0$ and $b\in2\lambda\N$ with $b\geq v + 2\lambda$,
\begin{displaymath}
\E\Big[\Big\Vert
\ind_{\Ns_{\varepsilon}(A)}
-\E\big[\ind_{\Ns_{\varepsilon}(A)}\big\vert  A_{0,b},\ell_{0,b}\big]
\Big\Vert_{H^{-\eta}(\C)}^{2}\Big]
\qquad
\text{and}
\qquad
\E\Big[\Big\Vert
\ind_{\widetilde{\Ns}_{\varepsilon}(A)}
-\E\big[\ind_{\widetilde{\Ns}_{\varepsilon}(A)}\big\vert  A_{0,b},\ell_{0,b}\big]
\Big\Vert_{H^{-\eta}(\C)}^{2}\Big]
\end{displaymath}
are bounded by
\begin{equation}

Ce^{-cb}
(\vert D\vert \diam(D)^{2\eta} +
\Vert 1_{D} \Vert_{H^{-\eta}(\C)}^{2}
).
\end{equation}
Given a deterministic smooth cutoff function $f_{0}:D\rightarrow [0,1]$, compactly supported in $D$,
then
\begin{displaymath}
\E\Big[\Big\Vert
f_{0}\ind_{\widetilde{\Ns}_{\varepsilon}(A)}
-\E\big[f_{0}\ind_{\widetilde{\Ns}_{\varepsilon}(A)}\big\vert  A_{0,b},\ell_{0,b}\big]
\Big\Vert_{H^{-\eta}(\C)}^{2}\Big]
\end{displaymath}
is again bounded by \eqref{Eq ind norm exp}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 49 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $(X_1, \mu_1)$ and $(X_2, \mu_2)$ be Polish measure spaces, and let $c$ be a continuous cost function on $X_1\times X_2$ such that $-c(X_1 \times X_2)=[a,b)$. Fix a weight $\lambda \in (0,1)$. Assume that $(X_1, \mu_1)$ and $(X_2,\mu_2)$ satisfy the Cost-Santal\'o inequality in Lemma~\ref{l:transfer} associated with $(\lambda,c,F)$ and domain $(\mathcal{A}_1, \mathcal{A}_2)$, where $F:[a,b]\to [0,\infty)$ is a continuous, non-decreasing function such that $F(a)=0$.  Assume also that the total masses 
    \[
    0<Z_1 = \int_{X_1} \Omega(\Phi_1(x_1)) d\mu_1(x_1),\, Z_2 = \int_{X_2}\Omega(\Phi_2(x_2)) d\mu_2(x_2) <+\infty.
    \]

    Let $\Phi_1: X_1 \to [a,b]$ and $\Phi_2: X_2 \to [a,b]$ be measurable functions satisfying
    \begin{equation}

        \lambda \Phi_1(x_1) + (1-\lambda) \Phi_2(x_2) \ge -c(x_1, x_2), \quad \forall x_1\in X_1, x_2\in X_2.
    \end{equation}
    Let $\Omega: [a,b] \to (0,\infty)$ be a continuous, non-increasing, log-concave function. Moreover, assume the following balance condition holds:
    \begin{equation}

        \int_a^b \Omega(r) dF(r) \leq Z_1^\lambda Z_2^{1-\lambda}.
    \end{equation}
    Define the probability measures
    \[
    dP_1(x_1) = Z_1^{-1} \Omega(\Phi_1(x_1))d\mu_1(x_1) \quad \text{and} \quad dP_2(x_2) = Z_2^{-1} \Omega(\Phi_2(x_2)) d\mu_2(x_2)
    \]
    and define the transport cost function on $X_1 \times X_2$ by:
    \begin{equation}
        c_{\Omega}(x_1, x_2) = \log \left( \frac{\Omega(-c(x_1, x_2))^{\frac{1}{1-\lambda}}}{\Omega(\Phi_1(x_1))^{\frac{\lambda}{1-\lambda}} \Omega(\Phi_2(x_2))} \right).
    \end{equation}
    Then $c_\Omega \ge 0$, and for any $\nu_1 \in \mathcal{P}(X_1)$ having density with respect to $P_1$, and $\nu_2 \in \mathcal{P}(X_2)$ having density with respect to $P_2$, one has the optimal transport bound:
    \begin{equation}
        \mathcal{T}_{c_{\Omega}}^{\mathcal{A}}(\nu_1, \nu_2) \leq \frac{\lambda}{1-\lambda} H(\nu_1 | P_1) + H(\nu_2 | P_2),
    \end{equation}
    where $\mathcal{T}_{c_{\Omega}}^{\mathcal{A}}(\nu_1, \nu_2)$ denotes the restricted Kantorovich cost taken as the supremum over pairs $(\varphi, \psi)$ satisfying the pointwise bound $\varphi(x_1) + \psi(x_2) \le c_\Omega(x_1, x_2)$, with the additional constraint that $e^{\frac{1-\lambda}{\lambda}\varphi} \Omega(\Phi_1(\cdot)) \in \mathcal{F}(\mathcal{A}_1)$ and $e^{\psi} \Omega(\Phi_2(\cdot)) \in \mathcal{F}(\mathcal{A}_2)$.

