body:
[Corollary corol:HHgenerale of arXiv:2606.27549, 'On Analytically Tractable Multidimensional Diffusions via Doob $h$-Transforms, with Resett'] For any  initial state ${\bf y}\in {\cal D}$, let us define the set 

\begin{equation}
    H_{\bf y}=\{{\bf x} \in {\cal D}:\;h({\bf x})=h({\bf y})\}.

\end{equation}

From Eq.\ ((2.1 of the paper)), for $\bf{y}\in  {\cal D}$ and $t>\tau\geq 0$, one has

\begin{equation*}
f({\bf x},t\,|\,{\bf y},\tau)=\widehat{f}({\bf x},t\,|\,{\bf y},\tau),\qquad \forall \,{\bf x} \in H_{\bf y}. 
\end{equation*}

In addition, by defining the regions  

\begin{equation}
{\cal H}^-_{\bf y}=\left\{ {\bf x} \in {\cal D}:\;h({\bf x})<h({\bf y}) \right\} \quad \text{and} 
\quad 
{\cal H}^+_{\bf y}=\left\{{\bf x} \in {\cal D}:\;h({\bf x})>h({\bf y})\right\},

\end{equation}

we have

\begin{equation} 
f({\bf x},t\,|\,{\bf y},\tau)<    (>)\, \widehat{f}({\bf x},t\,|\,{\bf y},\tau),
\qquad \forall \, {\bf x} \in {\cal H}^-_{\bf y}\; ({\bf x} \in {\cal H}^+_{\bf y}), 

\end{equation}

and thus  

\begin{equation}
\begin{array}{l}
  {F}({\cal H}^-_{\bf y},t\,|\,{\bf y},\tau)
 = \widehat{F}({\cal H}^-_{\bf y},t\,|\,{\bf y},\tau)- \Pi (t\,|\,{\bf y},\tau),
\\
 {F}({\cal H}^+_{\bf y},t\,|\,{\bf y},\tau)
 =\widehat{F}({\cal H}^+_{\bf y},t\,|\,{\bf y},\tau)+ \Pi (t\,|\,{\bf y},\tau),
\end{array}

\end{equation}

where ${F}$ is defined similarly as 
$\widehat{F}$ in ((1.1 of the paper)), and  
$$
 \Pi(t\,|\,{\bf y},\tau):=\int_{{\cal H}^-_{\bf y}} 
 \left|\widehat{f}({\bf x},t\,|\,{\bf y},\tau)- {f}({\bf x},t\,|\,{\bf y},\tau) \right|
    \,{\rm d}{\bf x}
    =\int_{{\cal H}^+_{\bf y}} 
 \left|\widehat{f}({\bf x},t\,|\,{\bf y},\tau)- {f}({\bf x},t\,|\,{\bf y},\tau) \right|
    \,{\rm d}{\bf x}.
$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm MAIN-THM of arXiv:2506.12752, 'Strong Detection Threshold for Correlated \ER Graphs with Constant Average Degree'] {}
    Suppose $\lambda$ is a constant. Then for any constant $\epsilon>0$, 
    \begin{enumerate}
        \item[(1)] if $s<\min\{ \tfrac{1}{\sqrt{\lambda}}, \sqrt{\alpha} \}-\epsilon$ where $\alpha\approx 0.338$ is the Otter's threshold, we have $\operatorname{TV}(\mathbb P,\mathbb Q)=1-\Omega(1)$ and thus strong-detection is information-theoretically impossible. 
        \item[(2)] if $s>\min\{ \tfrac{1}{\sqrt{\lambda}}, \sqrt{\alpha} \}+\epsilon$, we have $\operatorname{TV}(\mathbb P,\mathbb Q)=1-o(1)$ and thus strong-detection is information-theoretically possible. 
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] From a set $D = \mathsf{Dis}_{k-1}(B) \subset \mathscr{B}_{k-1}$ having $|\mathsf{Dis}_{k-1}(B)|\le s_k$, we construct $R_1,...,R_K$ as follows. Start with candidate set $\mathcal R = \{B': B'\in \mathsf{Dis}_{k-1}(B)\}$;  repeat the following process
        \begin{itemize}
            \item If the current candidate $\mathcal R$ contains two squares $R, R'$ of side-length $a \ell_{k-1}$ and $b \ell_{k-1}$ within distance $10 \ell_{k-1}$, then replace $R,R'$ in $\mathcal R$ with $R''$ which is a smallest square covering both squares.  
        \end{itemize}

[Prop holderct-general of arXiv:2604.14122, 'The scaling limit of random walk and\\ the intrinsic metric on planar critical percolation'] For all $\eta<\frac{5}{8}$ and $\varepsilon>0$, there exist $p=p(\eta)$ and $C=C(\eta,\varepsilon)>0$ such that for all $n$,
\begin{equation}
    \mathbf{P}\!\left(\forall x,y\in \Lambda_n\colon\,\mathbf{q}_n^{-1}D_n(x,y)\leq Cd^{{\mathrm {path}}}_n(x,y)^\eta\right)>1-\varepsilon.
\end{equation}
Furthermore, let $\gamma$ denote any open path in $\Lambda_n$. Then for any $\nu>0$ and $\alpha>0$, there exist $p=p(\nu)$, $C_1=C_1(\nu,\alpha),C_2=C_2(\nu,\alpha)$ such that for all $n$ and $M$ sufficiently large,
\begin{equation}
    \mathbf{P}\!\left(\exists \gamma: \mathbf{q}_n^{-1}D_n(\gamma(0),\gamma(1))> C_1(M+\dist(\gamma,\partial\Lambda_n)^{-\frac{1}{4}-\nu})\right)\leq C_2M^{-\alpha} .
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

