body:
[Lemma Weg of arXiv:2607.02367, 'Flux solutions for stochastic chemical systems with sources and sinks'] The following statements hold for mass action systems. 
\begin{enumerate} 
\item A chemical system $(\Omega, \mathcal R , \mathcal R_s , \mathcal K, \mathcal K_s )$ satisfies the detailed balance property  if and only if 
\begin{equation} 
\prod_{ \rho =1  }^r  \left( \frac{K_\rho }{ K_{-\rho} } \right)^{w(\rho)} \prod_{ k \in \Omega_c   }^r  \left( \frac{\alpha_k }{\beta_k  } \right)^{w(k )}  =1, \quad  \forall w \in \mathcal W.
\end{equation}
\item 
If the detailed balance condition holds at the steady state $f_s \in \mathcal P ( \mathbb N^M )  $, then 
    \begin{equation} 
         f_s(n)= \frac{1}{Z} \prod_{k=1}^M   \frac{ e^{ - E_k n_k } }{n_k ! } =\frac{1}{Z}  \frac{ e^{ - E^T  n } }{n ! }, \quad n \in \mathbb N^M 
     \end{equation}
     where $E \in \mathbb R^M $ is a solution to the system of equations
         \begin{equation} 
            S_\rho^T  E = \ln \left( \dfrac{ K_{ - \rho} }{ K_{  \rho } }  \right)  \ \forall \rho \in \{ 1, \dots, r \}, \quad     e_k^T  E = \ln \left( \dfrac{\beta_k  }{ \alpha_k  }  \right)  , \quad \forall k  \in \Omega_c. 
        \end{equation}
     and $Z:= \prod_{\ell =1}^M e^{e^{- E_\ell} }$.
     \item 
     If detailed balance holds, then every steady state $\overline f $ to equation (equation eq:master with sources of the paper), i.e. every solution to equation (equation eq:master with sources_stst of the paper), has the form (equation steady state when detailed balance holds of the paper) for a solution $E \in \mathbb R^M $ to the system of equations (equation eq:energies of the paper). 
     \end{enumerate}

