[Proposition 10 of arXiv:2609.02426, 'Deformations of the $\osp(n|2)$-action on the superspace\\ of symbols of differential oper'] Let $\lambda,\mu\in\R$ and $k\geq1$. Then, for all $i$,
\begin{equation}

L^{\mu}_{X_{\theta_i}}\circ A_k-(-1)^{n}A_k\circ L^{\lambda}_{X_{\theta_i}}=0,
\end{equation}
while
\begin{equation}

L^{\mu}_{X_{x\theta_i}}\circ A_k-(-1)^{n}A_k\circ L^{\lambda}_{X_{x\theta_i}}
=(\lambda-\lambda_k)\,\Ehat{i}\,\partial_x^{k-1}+(\mu-\lambda-N_k)\,\theta_i A_k .
\end{equation}
Consequently $A_k:\Fc^n_\lambda\to\Fc^n_\mu$ is $\osp(n|2)$-invariant, i.e.\ $X\cdot A_k=0$ for all
$X\in\osp(n|2)$, if and only if $(\lambda,\mu)=(\lambda_k,\mu_k)$, and in that case $A_k$ spans the
space of invariants.

[Definition 104 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] A centered Gaussian process $X$ is called a \emph{$Q$-fractional Brownian motion} with Hurst index $H \in (\frac{1}{3},\frac{1}{2}]$ if its covariance function is given by
\begin{align*}
R(s,t) =  \frac{1}{2} \Big( s^{2H} + t^{2H} - |t-s|^{2H} \Big) Q, \quad s,t \in \bbr_+.
\end{align*}

[Theorem Maria!! of arXiv:2412.09290, 'Asymptotics of Harish-Chandra transform and infinitesimal freeness'] Let $\varrho (N)$ be a sequence of probability measures on
  $\hat{U} (N)$ such that for every finite $r$ one has
  \begin{equation}
    \lim_{N \rightarrow \infty} N \left( \frac{1}{N} \log S_{\varrho (N)}^{U
    (N)} (u_1, \ldots, u_r, 1^{N - r}) - \sum_{i = 1}^r \Psi (u_i) \right) =
    \sum_{i = 1}^r \Phi (u_i), 
  \end{equation}
  where $\Psi, \Phi$ are analytic functions in a neighborhood of $1$ and the
  above convergence is uniform in a neighborhood of $1^r$. Then, for every $k
  \in \mathbb{N}$, we have
  \begin{equation}
    \lim_{N \rightarrow \infty} N \left( \frac{1}{N} \sum_{\lambda \in
    \hat{U} (N)} \varrho (N) [\lambda] \sum_{i = 1}^N \left(
    \frac{\lambda_i + N - i}{N} \right)^k -\mathbf{m}_k \right)
    =\mathbf{m}'_k, 
  \end{equation}
  where $(\mathbf{m}_k)_{k \in \mathbb{N}}$ are given by ((mporw? of the paper)) and
  \begin{equation}
    \mathbf{m}'_k = \sum_{m = 0}^{k - 1} \frac{k!}{m! (m + 1) ! (k - m - 1) !}
    \left. \frac{\mathrm{d}^m}{\mathrm{d} x^m} \left( x^k \left( \Phi' (x) -
    \frac{1}{2 x} \right) (\Psi' (x))^{k - m - 1} \right) \right|_{x = 1} .

  \end{equation}

[Thm exact ruin  for the collective model of arXiv:2606.28031, 'Insurance risk models in a heterogeneous time-dependent population: scaling limits and rui'] Assume:
\begin{enumerate}
\item[{\em (1)}] {the Cram\'er condition (equation cram of the paper) applies};
\item[{\em (2)}] there exists a deterministic $\ell_\alpha$ such that 
\[
\ell_\alpha = \lim_{t \to \infty} \frac{k_\alpha(t)}{t} \quad \text{almost surely, for all } \alpha \in [0, \overline{\alpha}];
\]
\item[{\em (3)}] $\alpha_*:=\sup\BRA{\alpha>0 :\ell_{\alpha}=0}\in (0, \overline{\alpha})$.
\end{enumerate}

Then, the ruin probability $p(u)$ is positive and satisfies, for any $\alpha \in (\alpha_*, \overline{\alpha}]$,
\begin{equation*}
p(u) = \frac{1}{\mathbb{E}\big[{\mathrm e}^{-\alpha V(\tau(u)) - k_{\alpha}(\tau(u))} \,\big|\, \tau(u) < \infty\big]}.
\end{equation*}

[Definition 63 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Define  the cell $\mathfrak Y \subset \bar{\mathfrak{X}}$ centered at $z_0$ by
  \begin{flalign}

    \begin{aligned}
  \mathfrak{Y} = \bigg\{ z \in \overline{\mathfrak{X}} : & \dist_{\bm{u}_{z_0;q}} (z, z_0) \le q^{-1/2} N^{(\frac34 A-\frac12)\delta -1/2} (\md_{z_0}\me_{z_0;q})^{-1/4},\\
  &  \dist_{\bm{w}_{z_0;q}} (z, z_0) \le q^{-1/2} N^{(\frac34A-\frac12)\delta -1/2} (\md_{z_0}\me_{z_0;q})^{1/4} \bigg\}.
  \end{aligned}
	\end{flalign} 

\noindent Further define $\mathfrak{Y}^- \subset \mathfrak{X}$ by  $\mathfrak{Y}^-=(1/L)\cdot(\mathfrak{Y}-z_0)+z_0$ (namely, to be its shrinking by a factor $L$), where $L$ is a sufficiently large constant that depends only on the constant $C$ in \Cref{prop:last}.

[Theorem thm:isotropicbbpXfree of arXiv:2510.01021, '\Large Random Matrices, Intrinsic Freeness, and Sharp Non-Asymptotic Inequalities\relatedv'] Let $X$ be a $d\times d$ self-adjoint gaussian random matrix for which $\mathbb{E}(X-\mathbb{E} X)^2= \sigma(X)^2 I$ and for which $\mathbb{E} X$ has rank $r$. If $\sigma_\ast(X)\sqrt{r}\leq 1$ then
\begin{equation}
    \big| \lambda_{\max}(X_{\mathrm{free}}) - B\big( \lambda_{\max}(\mathbb{E} X) \big)  \big| \leq 2\sigma_{\ast}(X) \sqrt{r},
\end{equation}
where $B(\lambda)$ is given by~(equation eq:def:Blambda of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 of arXiv:2604.06516, 'From stochastic individual-based models to free-boundary Hamilton-Jacobi equations'] Let us consider $t\geq 0 $ and $f\in AC[0,t]$ such that $I_t(f)<+\infty$ and such that for all $s\leq t$, $F_s(f)>0$. For all $\delta'>0$, for all sufficiently small $\varepsilon>0$ and sufficiently large $K$, we have
    \begin{equation}
\E\big[\big(N^{K,\varepsilon,f}_t\big)^2\big]\leq \E^2\big[N^{K,\varepsilon,f}_t\big] \times K^{8\delta'}.
     \end{equation}

