[Def local-consistency of arXiv:2605.30017, 'Conditional Probability Spaces and the Structure of Agreement\footnote{We thank Emiliano C'] Alice and Bob satisfy \textbf{local consistency} at a state $\omega \in \Omega$ if:
\begin{equation}
p^A_{m(\omega)} = p^B_{m(\omega)}.
\end{equation}

[Lemma lem.decom_DF_j of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] Let $F_*, F_\circ$ follow the decomposition (equation eq.def_WIP_new of the paper), and $v_{m}$ follow the canonical grain extension in Definition~(def.ConstantExtension_canonical of the paper). Given ${\scaleobj{1}{\square}}_m \in  \mathcal{G}^{(N)}_{k}$ and ${\scaleobj{1}{\square}} \in \mathcal{P}^{(N,k)}_{h}$, we have the identity
		\begin{equation}
			\forall x \in \frac{16}{15} {\scaleobj{1}{\square}}, \qquad V_m(F,j \vert {\scaleobj{1}{\square}})(x) = \nabla_{F_\circ} V_m(F_*,j \vert {\scaleobj{1}{\square}})(x),
		\end{equation}
		and following observations:
		\begin{itemize}
			\item  $V_m(F,j)$ is then constant on every holes in $\frac{16}{15} {\scaleobj{1}{\square}}$.
			\item For  $x \notin  \mathscr{C}_{\operatorname{bc}}^F({\scaleobj{1}{\square}}_m) \cap \frac{16}{15} {\scaleobj{1}{\square}}$, if $F_\circ \nsubseteq \mathcal{E}(\mathscr{O}^{F_\circ}(x))$, then $V_m(F,j \vert {\scaleobj{1}{\square}})(x) = 0$.
			\item For $x \in \mathscr{C}_{\operatorname{bc}}^F({\scaleobj{1}{\square}}_m) \cap \frac{16}{15} {\scaleobj{1}{\square}}$, if $F_\circ \neq \emptyset$, then $V_m(F,j \vert {\scaleobj{1}{\square}})(x) = 0$.
		\end{itemize}

