    \begin{align*}
    e^{d(s,t,\varphi)} 
    &\leq 2(\cosh(s)\cosh(t)-\sinh(s)\sinh(t)\cos(\varphi))\\
    &= 2(\cosh(s-t) + \sinh(s)\sinh(t)(1-\cos(\varphi)))\\
    &\leq 2(e^{|s-t|} + e^{s+t}(1-\cos(\varphi)))
    \end{align*}
