[Lemma 8 of arXiv:2506.10817, 'On the Weak Error for Local Stochastic Volatility Models'] Let $\varphi_\lambda(x)=\frac{1}{\sqrt{2\pi\lambda}}e^{-\frac{x^2}{2\lambda}}$ be the density of a Gaussian with mean $0$ and variance 
    \begin{align}
        \lambda=c_{min}^2\rhobar^2h.
    \end{align}
    Let Assumptions \ref{Ass:Half_Step} and \ref{Aspt_new} hold (guaranteeing that $\lambda >0$).
    Consider $\tiX^h$ given by \eqref{Eq:Half_step}. Then for $j \in \{1,\dots,\frac Th\}$
    \begin{align*}
        \E\bigl[ \xi_{jh}^2|\tiX^{h,\delta}_{jh}\bigr]=\frac{\E\Bigl[\xi_{jh}^2\varphi_{\lambda}\bigl(x-\tiX_{jh-h/2}^{h,\delta}
        \bigr)\Bigr]}{\E\Bigl[
        \varphi_{\lambda}
        \bigl(x-\tiX_{jh-h/2}^{h,\delta}
        \bigr)
        \Bigr]}\Bigg|_{x=\tiX^{h,\delta}_{jh}}.
    \end{align*}
    In particular if $\delta=0$, then for $\hE_\delta$ from Equation \eqref{eq_hatEdelta}
    \begin{align*}
        \hE_0\bigl[ \xi_{jh}^2|\tiX^{h,0}_{jh}\bigr]=\E\bigl[ \xi_{jh}^2|\tiX^{h,0}_{jh}\bigr].
    \end{align*}
    and in this case 
    $\mathcal{L}\bigl( (\tiX_{jh}^{h,0},\xi_{jh})_{j\le T/h}\bigr) =\mathcal{L}\bigl((X_{jh}^{h},\xi_{jh})_{j\le T/h}\bigr)$, with $X^{h}$
    from Equation \eqref{Eq:Euler_Scheme}.

[Definition D:semiflow of arXiv:2411.01364, 'Global Dynamics of Granular Media Equations via Stochastic Order'] A map $P^*: 
\mathbb{R_+}\times\mathcal P_2(\mathbb R)\rightarrow\mathcal P_2(\mathbb R)$ is said to be a jointly continuous semigroup, or a semiflow on $\mathcal P_2(\mathbb R)$, if 
\begin{enumerate}[label=(\roman*)]
    \item  $P^*: \mathbb{R_+}\times\mathcal P_2(\mathbb R)\rightarrow\mathcal P_2(\mathbb R)$ is continuous;
    \item $P_0^*\mu=\mu$  for all $\mu\in\mathcal P_2(\mathbb R)$;
    \item $P_t^*\circ P_s^*=P_{t+s}^*$ for all $t,s\in \mathbb{R_+}$.
\end{enumerate}

