body:
[Definition def:limiting_function of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] Given a typical diagram $\Gamma$, for $t_1,\dots,t_s>0$ we introduce a family of linear constraints for edge–weighted variables $\{\alpha_e\geq 0\}$
\begin{equation}
\mathfrak{C}(\{t_i\})
:\quad
\sum_{e\in E(\Gamma)} c_i(e)\,\alpha_e \;\le\; t_i,
\quad i=1,\dots,s,
\end{equation}
where \(c_i(e)\in \{0,1,2\}\)  counts how many times the edge
$e$ appears in the boundary $\partial D_i$.
   Let \(C_\Gamma>0\) be a combinatorial constant depending only on \(\Gamma\) defined by
\begin{equation}
    C_\Gamma=\lim_{n_j\rightarrow\infty}\frac{\#\{(w_e)_{e\in E(\Gamma)}|
        m_j, w_e\in \mathbb{N},~m_j \ge 0,\; w_e \ge 1,~
        2m_j + \sum\limits_{e \in \partial D_j} w_e = n_j,~ j=1,\dots,s\}}{\mathrm{Vol}\{(\alpha_e)_{e\in E(\Gamma)}|\alpha_e\in \mathbb{R}^+, \sum_{e\in E(\Gamma)} c_j(e)\,\alpha_e \;\le\; n_j,
\quad j=1,\dots,s\}}.
\end{equation}
The three limiting  diagram functions are then defined separately for each phase regime as follows:
\begin{enumerate}
    \item[(i)] \textbf{(Supercritical case)}
    \begin{equation}
\mathcal{F}^{\mathrm{(Super)}}_\Gamma(t_1,\dots,t_s)
\;=\frac{C_\Gamma}{\,t_1\cdots t_s\,}\mathrm{Vol}_{\mathfrak{C}}(\{t_i\}),
\end{equation}
where
\begin{equation}
    \mathrm{Vol}_{\mathfrak{C}}(\{t_i\})=\int_{\mathfrak{C}(\{t_i\})}1\,\prod_{e\in E(\Gamma)}d\alpha_e.
\end{equation}
\item[(ii)]  \textbf{(Subcritical case, $\alpha>d=1$)}
\begin{equation}
    \mathcal{F}^{\mathrm{(Sub)}}_\Gamma(t_1,\dots,t_s)
    \;=\;
    \frac{C_\Gamma}{\,t_1\cdots t_s\,}\,
    \int_{x_v\in \mathbb{R}^d, v\ne v_0}\int_{\mathfrak{C}(\{t_i\})}
    \prod_{e\in E(\Gamma)}f_{\alpha}(x_{u}-x_{v},\alpha_e ) \prod_{e\in E(\Gamma)}d\alpha_e \prod_{v_0\neq v\in V(\Gamma)} dx_v,
\end{equation} where
the first integral is over all $x_v$ in $\mathbb{R}^d$ except for  $x_{v_0}=0$, with   some $v_0\in V(\Gamma)$.
\item[(iii)] \textbf{(Critical case, $\alpha>d=1$)}
    \begin{equation}
    \mathcal{F}^{\mathrm{(Crit)}}_\Gamma(t_1,\dots,t_s;\tau)
    \;=\;
    \frac{C_\Gamma}{\,t_1\cdots t_s\,}\,
    \int_{x_v\in \mathbb{T}^d}\int_{\mathfrak{C}(\{t_i\})}
    \prod_{e\in E(\Gamma)}\theta_{\alpha}(x_{u}-x_{v},\alpha_e\tau) \prod_{e\in E(\Gamma)}d\alpha_e \prod_{v\in V(\Gamma)}dx_v.
\end{equation}
\end{enumerate}

[Lemma lem:extreme_means of arXiv:2607.22291, 'Rare subtree patterns in size-conditioned Bienaymé trees: Poisson approximation and declum'] Assume (hyp:M of the paper)  for $(G_{k})$  along $(k_{n})$ with respect to $(M_{n})$. The following statements hold. 
\begin{enumerate}[label=\textup{(\roman*)}]
\item  If $n\pi_n\to0$, then under $\P(\cdot\mid S_n=-1)$,
$\sum_{i=1}^n I_i^{(M_n)}$ converges in probability to $0$;
\item  Assume in addition (hyp:C of the paper) for $(G_k)$  along $(k_{n})$ with respect to $(M_{n})$. If $n\pi_n\to\infty$, then $$ \frac{\sum_{i=1}^n I_i^{(M_n)}}{n\pi_n}  \quad \mathop{\longrightarrow}^{(\P)}_{n \rightarrow \infty} \quad1 \qquad \textrm{under } \P(\cdot\mid S_n=-1).$$
\end{enumerate}

[Definition defn_Mm of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] We define $m(z)\equiv m_N(z)$ as the unique solution to 
 \begin{equation}
m(z)= \big\langle \left(\Lambda -z- m(z)\right)^{-1} \big\rangle ,
\end{equation}
 such that $\im m(z)>0$ whenever $z\in \mathbb{C}_+$.  
 Then, we define the matrix $M(z)\equiv M_N(z,\Lambda)$ as 
\begin{equation}
M(z):= \left(\Lambda -z- m(z)\right)^{-1}.
 \end{equation}
Since $\Lambda$ is Hermitian, we have that $m(\overline z)= \overline {m(z)}$ and $M(\overline z)=M(z)^*$.

[Lemma lemma_localized_eigenvalue_local_law of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] In the setting of (theorem_localized_eigenvector_localization of the paper), the following estimate holds uniformly in $t\in \left[{0,1}\right]$ for some constant $C>0$ that does not depend on $\varepsilon$:

\begin{equation}
        \begin{aligned}
            \mathbb{E}\avg{\left({\im G_t}\right){\widehat{\Lambda}}_t\left({\im G_t}\right){\widehat{\Lambda}}_t}\prec N^{C\varepsilon}N^{-5/3}k^{2/3}\lVert A \rVert_{\text{\rm{HS}}}^2\le N^{-1-2\varepsilon_A+C\varepsilon}
        \end{aligned}
    \end{equation}

    where $G_t$ is defined by $G_t :=\left({H+t\Lambda-z_t}\right)^{-1}$ with $z_t$ defined in (equation eq:z1t of the paper).

