[Lemma 8 of arXiv:2607.17030, 'Stationary measures for log-gamma polymer on a strip and in half-space'] Let $-\alpha<u<0$ and $v>u$. 
Then , as $N\to\infty$,
\begin{equation}
R_{N,N-1}:=1+\zeta_{N,1}+\zeta_{N,1}\zeta_{N,2}+\ldots+\zeta_{N,1}\zeta_{N,2}\ldots \zeta_{N,N-1}{\Rightarrow}
R,
\end{equation}
where $R=\lim_{n\to\infty} R_n$   is   given by \eqref{Rseries}; furthermore,
\begin{equation}
\lim_{N\to\infty}\,\mathbb E\,[R_{N,N-1}^{-u-v}]\,=\,\mathbb E\,[R^{-u-v}].
\end{equation}

Let $-\alpha<v<0$ and  $v<u$. 
Then, as $N\to\infty$, \begin{equation}
  R_{N,N-1}':=1+  \zeta_{N,1}'+  \zeta_{N,1}'  \zeta_{N,2}'+\ldots+
  \zeta_{N,1}'  \zeta_{N,2}'\ldots   \zeta_{N,N-1}'{\Rightarrow} 
  R',
\end{equation}
where $  R'=\lim_{n\to\infty}   R_n'$  is  given by \eqref{Rseries2}; furthermore,
\begin{equation}
\lim_{N\to\infty}\,\mathbb E\,[  (R_{N,N-1}')^{-u-v}]\,=\,\mathbb E\,[ (R')^{-u-v}].
\end{equation}

[Defi 23 (Terms of the $m$-th kind) of arXiv:2511.10535, 'Eigenvalues of Brownian Motions on $\mathrm{GL}(N,\mathbb{C})$'] If $P\in\PP_d$, a ``term of the $m$-th kind associated to $P$''
    is a tuple $(P_1,\dots, P_{m+1})\in \mathcal P_d^{m+1}$ defined inductively as follows:
    \begin{itemize}
        \item For $m=0$, it is either $P$ or $P^*$.
        \item For $m>0$ and any term of the $m-1$-st kind $(P_1,\dots,P_m)$, for every $i,j$ we fix choices of $A_l^{i,j}, B_l^{i,j}\in \PP_d$ such that
        \begin{equation}

            \partial_iP_j=\sum_lA_l^{i,j}\otimes B_l^{i,j},
        \end{equation}
        and declare $(P_1,\dots,P_{j-1}, A_l^{i,j},B_l^{i,j},P_{j+1},\dots, P_m)$ to be a term of the $m$-th kind for each $i,j,l$.
    \end{itemize}
    This allows us to define
    $$ c(P) \deq \sup_{\substack{m\geq 0, \\ i\in [1,d]}} \sup_{\substack{(P_1,\dots,P_{m+1}) \text{ is a} \\ \text{term of the $m$-th kind.}}} \left\{ \sum_{j=1}^{m+1}\kappa_j\ \middle|\ \forall j,\ \partial_i P_j = \sum_{l=1}^{\kappa_j} A_l^{i,j}\otimes B_l^{i,j} \right\}.$$

[Definition 17 of arXiv:2608.30077, 'Lie groupoid integration of singular isometries of the Poincaré disk'] Define $X_n$ to be the space of pairs consisting of a smooth path in $\psu$ and a point on the punctured disk, subject to conditions:
    \begin{equation*}
    X_{n} := \{ (u: [0,1] \to \psu, z \in \Dbarstar) \mid u(0)=e, u(t) \cdot z^{n} \neq 0 \}.
    \end{equation*}

[Definition def:longEdges of arXiv:2411.10333, 'Subcritical annulus crossing in spatial random graphs'] We define for all \(r>0\) and \(c>0\) the \emph{presence of long edges} event as
		\begin{equation}
			\mathcal{L}(r,c):=\big\{\exists\ \boldsymbol{x}\sim \boldsymbol{y}\colon |x|<r, |x-y|>cr \big\}.
		\end{equation} 
		That is, we can find an edge of length at least \(cr\) in \(\mathscr{G}\) with one endpoint being located in \(B(r)\). We say that \(\mathscr{G}\) has 
		\begin{equation*}\tag{\(\mathscr{L}\)}
			\text{Property } \mathscr{L}_\lambda \quad \text{ if } \quad \limsup_{r\to\infty}\mathbb{P}_\lambda(\mathcal{L}(r,c))=0 \quad \text{ for all }c>0.  
		\end{equation*}
		If Property \(\mathscr{L}_{\lambda'}\) is \emph{uniformly} fulfilled for all \(\lambda'\leq \lambda\), we say that the graph has Property \(\overline{\mathscr{L}}_\lambda\). More precisely, \(\mathscr{G}\) has 
		\begin{equation*}\tag{\(\overline{\mathscr{L}}\)} 
			\text{Property } \overline{\mathscr{L}}_\lambda \quad \text{ if }\quad \limsup_{r\to\infty}\sup_{\lambda'\leq \lambda}\mathbb{P}_{\lambda'}(\mathcal{L}(r,c))=0 \quad \text{ for all }c>0.
		\end{equation*}

