[Theorem 7 of arXiv:2604.17302, 'Elephant random walk with attributed steps and extractions of random sizes'] }
\sloppy Under Scenario~\eqref{Scenario_1}, the sequence $\{n^{-1}C_{n}\}$ converges almost surely. Under Scenario~\eqref{Scenario_2}, $\{n^{-1}C_{n}\}$ converges almost surely as long as $\{(n^{-1}A_{n},n^{-1}B_{n})\}$ does and one of the following is true:
\begin{enumerate}[label=(C\arabic*), ref=C\arabic*]
\item _a.s.:g_Lipschitz} the function $g$, defined in \eqref{g_defn}, is Lipschitz on $\mathcal{S}$, and $\E[K_{n}^{-1/2}]\rightarrow 0$ as $n\rightarrow\infty$;
\item _a.s.:g_C^{1}} the function $g\in\mathcal{C}^{(1)}(\mathcal{S})$, and, as $n\rightarrow\infty$:
\begin{equation}
\min\{\omega(\nabla g;(\E[K_{n}^{-1}])^{1/2})(\E[K_{n}^{-1}])^{1/2},\omega(\nabla g;\E[K_{n}^{-1}]/\E[K_{n}^{-1/2}])\E[K_{n}^{-1/2}]\}\rightarrow 0;\nonumber
\end{equation}
\item _a.s.:g_C^{2}} the function $g\in\mathcal{C}^{(2)}(\mathcal{S})$, and $\E[K_{n}^{-1}]\rightarrow 0$ as $n\rightarrow\infty$.
\end{enumerate}
Furthermore, if $\{(n^{-1}A_{n},n^{-1}B_{n})\}$ converges almost surely to some $(x^{*},y^{*})\in\mathcal{S}$, then $\{n^{-1}C_{n}\}$ converges almost surely to $(1-q_{1})x^{*}/q_{1}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 2 of arXiv:2604.22644, '2604.22644'] For $n=0, 1, 2, \dots$,
\begin{align}
    P(L_{\tau_N}=n) = \left( 1 - \int_0^1 \frac{p}{S(N;p)} dp \right)^n \int_0^1 \frac{p}{S(N;p)} dp ,
\end{align}
where $S(N;p)$ is the scale function defined in Theorem \ref{thm1}.

