[Corollary cor:stoch_int_bd of arXiv:2411.09482, 'Anomalous Regularization in Kazantsev-Kraichnan Model'] Let $s\in (0,d/2)$. For every $(\mathcal{F}_t)_t$-progressively measurable process $M$ with paths in $L^2_t(H^{-s}_{\div})$ $\mathbb{P}$-a.s., the stochastic integral
	\begin{align*}
		N_t:= \int_0^t B[M_r] \,\mathrm{d} W^\mathcal{K}_r
	\end{align*}
	is a well-defined local martingale with values in $\dot{H}^{-s-1}_{\div}$ and the following bound holds for its quadratic variation $[N]$:
	\begin{align} 
		\trace_{\dot{H}^{-s-1}_{\div}}[N]_t  = \int_0^t \| B(M_r) \|^2_{\operatorname{HS}(H^{d/2 + \alpha}_{\div}; \dot{H}^{-s-1})} \,\mathrm{d} r \lesssim \int_0^t \|M_r\|_{H^{-s}}^2 \,\mathrm{d} r.
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma of arXiv:2601.07808, 'Supercritical long-range percolation on graphs of polynomial growth: the truncated one-arm'] \label[lemma]{lem:complement_r_connected}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 2$, and let $R \in \mathbf{N}$ be as in (prop:boundary_connectivity of the paper).

    Let $b \in \mathbf{N}$ and let $\mathbf{A} = (A_0,\ldots,A_{b-1}) \in \mathcal{A}(b)$ be a sequence of $1$-disconnected blocks. Then the set $G \setminus \mathbf{A}$ is $R$-connected.

