[Lemma bilinearestforkdv of arXiv:2606.31155, 'The well-posedness of stochastic Korteweg--de Vries equations revisited'] Let $1/4< a, b < 1/2$, $a+2b\geq 5/4$, and $0<T<1$. We have
		\begin{equation*}
			\begin{aligned}
				\|(uv)_x\|_{X_T^{0,-a}}&\lesssim \|P_1 u\|_{L_T^\infty L_x^2}\|P_1v\|_{L_{T}^2L_x^\infty}+ \|P_1 u\|_{L_x^2L_T^\infty}\|P_{>1}v\|_{X_T^{0,b}} \\
				&\quad +\|P_{>1}u\|_{X_T^{0,b}}\|P_1 v\|_{L_x^2L_T^\infty}+ \|P_{>1}u\|_{X_T^{0,b}}\|P_{>1}v\|_{X_T^{0,b}},
			\end{aligned}
		\end{equation*}
		which implies
		\begin{equation*}
			\|(uv)_x\|_{X_T^{0,-a}}\lesssim \|u\|_{Z_T^{0,b}}\|v\|_{X_T^{0,b}}+\|u\|_{X_T^{0,b}}\|v\|_{Z_T^{0,b}}.
		\end{equation*}

