[Lem eq:inside:L:N of arXiv:2411.12717, 'Excursion theory for Markov processes indexed by Lévy trees'] For every fixed $y \neq x$ and $\delta,\upsilon\geq 0$, $\varepsilon > 0$ set:
\begin{equation*}
    J_{\delta,\upsilon,\varepsilon}(y):=\mathbb{N}_{y}\Big(\sup_{t\geq 0}\Big|L_t(\rho,W)- \varepsilon^{-1}\int_{0}^{t} {\mathrm{d}} s \,  \mathbbm{1}_{\{\uptau_{\delta, \upsilon}(W_s)<H(\rho_s)<\uptau_{\delta, \upsilon}(W_s)+\varepsilon<\uptau(W_s) \}}\Big|\Big).
\end{equation*}
The following properties hold:
\begin{itemize}
\item[$\mathrm{(i)}$] $J_{\delta, \upsilon,\varepsilon}(y)\leq 2$;
\item[$\mathrm{(ii)}$] $ \limsup_{\upsilon \to 0} \limsup_{\varepsilon \to 0} J_{0,\upsilon,\varepsilon}(y)=0$. 
\end{itemize}

[Lemma 1 ({\cite[Theorem 2.5) of arXiv:2604.05234, 'Quantitative propagation of chaos and universality for asymmetric Langevin spin glass dyna'] {Arous1995-zj}}] There exists a unique weak solution $(Y,B)$ with $\mu=\textup{Law}(Y)$ to the following McKean-Vlasov equation,
\begin{equation}

    \begin{aligned}
        dY_t &= - U'(Y_s) ds + dB_t, \\
        dB_t &=  \beta^2  \bigg[ \int_0^t H^t_\mu(t, s) dB_s\bigg] dt + dW_t,   \\
        Y_0 &\sim \mu_0.
    \end{aligned}
\end{equation}
where $W$ is a standard Brownian motion. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:John of arXiv:2412.05142, 'Strong convergence of the Euler scheme for singular kinetic SDEs driven by $\alpha$-stable'] [BDG-Levy]
    Let $0\leqslant S\leqslant T$ and let ${\mathcal A}:\Omega\times[S,T]\mapsto{\mathbb R}^d$, $\xi:\Omega\times [S,T]\mapsto{\mathbb R}_+$ be  processes adapted to $({\mathcal F}_t)_{t\in[S,T]}$. Further assume  $({\mathcal A}_t)_{t\in[S,T]}$ to be continuous and integrable.  Suppose that for $(s,t)\in[S,T]_\leqslant^2$ one has
    \begin{align}
    {\mathbb E}^s|{\mathcal A}_t-{\mathcal A}_s|\leqslant \xi_s\quad a.s.
    \end{align}
    Then for any $p\geqslant1$ there exists a constant $N=N(p)$ such that for any $(s,t)\in[S,T]_\leqslant^2$ one has
    \begin{align}
        \|\sup_{r\in[s,t]}|{\mathcal A}_t-{\mathcal A}_s|\|_{L_p(\Omega)|{\mathcal F}_s}\leqslant N \|\sup_{r\in[s,t]}\xi_r\|_{L_p(\Omega)|{\mathcal F}_s}.
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:entropic-hypocoercivity of arXiv:2506.23062, 'Shifted Composition IV\@: \\ Toward Ballistic Acceleration for Log-Concave Sampling'] Suppose that $\pi$ satisfies~(equation eq:lsi of the paper) with constant $1/\alpha$, and $-\beta I \preceq \nabla^2 V \preceq \beta I$.
    Consider the Lyapunov functional over $\mathcal{P}(\mathbb{R}^d\times \mathbb{R}^d)$,
    \begin{align*}
        \mathfrak L(\bs\nu) \coloneqq \KL(\bs\nu \mathbin{\|} \bs\pi) + \mathbb{E}_{\bs\nu} \biggl\langle\nabla \log \frac{\bs\nu}{\bs\pi}\,,\; \Bigl(\begin{bmatrix}
            b_1/\beta & b_2/\sqrt{\beta} \\
            b_2/\sqrt{\beta} & b_3
        \end{bmatrix} \otimes I \Bigr)\,\nabla \log \frac{\bs\nu}{\bs\pi} \biggr\rangle\,.
    \end{align*}
    There exist absolute constants $b_1, b_2, b_3\in\mathbb{R}$ and $c>0$ such that for any $\bs\nu_0\in \mathcal{P}(\mathbb{R}^d\times\mathbb{R}^d)$, and $\boldsymbol{P}_t$ the kernel of~(eq:ULD of the paper) up to time $t$ with friction $\gamma \asymp \sqrt\beta$, we have 
    \begin{align*}
        \KL(\bs\nu_0\boldsymbol{P}_t \mathbin{\|} \bs\pi)
        \leqslant \mathfrak{L}(\bs\nu_0 \boldsymbol{P}_t) \leqslant \exp\bigl({-\frac{c\alpha t}{\sqrt{\beta}}}\bigr)\, \mathfrak{L}(\bs\nu_0)\,.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemm l:FAFBisFAB of arXiv:2607.18194, 'Temperature chaos in directed polymers'] For any Borel sets $A,B\in\mathcal{B}(\mathbb{R}^2)$ and any $X\in L^2(\Xi,\mathcal{F},\mathbb{P})$, if $X$ is $\mathcal{F}_B$-measurable, then
    \begin{align*}
        \mathbb{E}[X|\mathcal{F}_A] = \mathbb{E}[X|\mathcal{F}_{A\cap B}].
    \end{align*}

