body:
[Lemma lem:supp_lmeasx of arXiv:2606.11951, 'On Skorokhod Problems for Reflected and Singular Stochastic Heat Equations'] The set $\mathcal{G}_0 \coloneqq \{z \in \mathrm{HC} \mid z_a=0\}$ is a measurable set of full measure w.r.t.\ $\mu^{(a)}$ and $\var{\sigma^{(a)}}$, (where we identify $\mathcal{G}_0$ with its canonical embedding into $[C_0]$,) but it is not closed as a subset of $(C_0, \| \cdot \|_{\infty})$. Identifying the considered measures with their restrictions to $\mathcal{B}(L)\cap [C_0]$ or $\mathcal{B}(C_0,\|\cdot\|_{\infty})$ (see Remark (rem:embeddings_and_measurability of the paper)), it holds that
    \begin{equation*}
        \mathrm{supp} \, \mu^{(a)} = \mathrm{supp} \var{\sigma^{(a)}} = \{z \in C_0 \mid z_a=0\},
    \end{equation*}
    where the support is defined w.r.t.\ the topology on $C_0$ induced by $\| \cdot \|_{\infty}$.

[Theorem thm:global_clt_intro of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] Define
\begin{equation}

    \sigma_n^2 = 
    \mleft( 1 - 2 p (1-p) \sum_{j=1}^K \beta_j \mathsf{e}_j (\mathsf{e}_j-1) p^{\mathsf{e}_j-2} \mright)^{-1}
    \times p(1-p) \binom{n}{2}.
\end{equation}
Then for any $\varepsilon > 0$, we have
\begin{equation}
    \mathbf{d} \mleft( \frac{\mathsf{E}(X) - \mathbb{E}[\mathsf{E}(X)]}{\sigma_n}, Z \mright) \lesssim n^{-\frac{1}{2} + \varepsilon},
\end{equation}
for both $\mathbf{d} = \mathbf{d}_\mathrm{Was}$ and $\mathbf{d} = \mathbf{d}_\mathrm{Kol}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eq:diamond_def of arXiv:2604.22528, 'Malliavin calculus for signatures with applications to finance'] Fix three words ${\color{NavyBlue}{\mathbf{u_1}}}, {\color{NavyBlue}{\mathbf{u_2}}}, {\color{NavyBlue}{\mathbf{w}}} \in V$. For two words ${\color{NavyBlue}{\mathbf{v}}}, {\color{NavyBlue}{\mathbf{v'}}}$, define $\diamond^{{\color{NavyBlue}{\mathbf{u_1}}}, {\color{NavyBlue}{\mathbf{u_2}}}}_{{\color{NavyBlue}{\mathbf{w}}}}: \TA\times\TA\to\TA$ by
    \begin{equation}
        {\color{NavyBlue}{\mathbf{v}}} \diamond^{{\color{NavyBlue}{\mathbf{u_1}}}, {\color{NavyBlue}{\mathbf{u_2}}}}_{{\color{NavyBlue}{\mathbf{w}}}}{\color{NavyBlue}{\mathbf{v'}}} 
        = \sum_{\substack{{\color{NavyBlue}{\mathbf{v_1}}}, {\color{NavyBlue}{\mathbf{v_2}}}:\\{\color{NavyBlue}{\mathbf{v_1u_1v_2}}} = {\color{NavyBlue}{\mathbf{v}}}}}
          \sum_{\substack{{\color{NavyBlue}{\mathbf{v_1'}}}, {\color{NavyBlue}{\mathbf{v_2'}}}:\\{\color{NavyBlue}{\mathbf{v_1'u_2v_2'}}} = {\color{NavyBlue}{\mathbf{v'}}}}}
          ({\color{NavyBlue}{\mathbf{v_1}}}\mathrel{\sqcup \mkern -3mu \sqcup}{\color{NavyBlue}{\mathbf{v_1'}}})\otimes{\color{NavyBlue}{\mathbf{w}}}\otimes({\color{NavyBlue}{\mathbf{v_2}}}\mathrel{\sqcup \mkern -3mu \sqcup}{\color{NavyBlue}{\mathbf{v_2'}}}).
    \end{equation}
    For two tensor sequences $\bm{\ell}, \bm{\ell}' \in \TA$, the operator is extended by bilinearity. We also define $\diamond := \sum_{i = 1}^d \diamond^{{\color{NavyBlue}{\mathbf{i}}}, {\color{NavyBlue}{\mathbf{i}}}}_{{\color{NavyBlue}{\mathbf{0}}}}$.

[Proposition prop:walk-overshoot of arXiv:2411.10113, 'Long-range one-dimensional\\ internal diffusion-limited aggregation'] Suppose that~(equation ass:irreducible of the paper) and~(equation ass:moments of the paper) hold. 
Then $\mu :=  \bE Y$ has $1 \leq \mu < \infty$, and
\begin{equation}

   \mu = \exp \left\{ \sum_{n=1}^\infty \frac{1}{n} \left[ \frac{1}{2} - \bP ( S_n > 0 ) \right] \right\} .
\end{equation}
Moreover, define the probability distributions $(\pi_k)_{k \in {\mathbb N}}$ 
and $(\psi_k)_{k \in {\mathbb N}}$ by
\begin{equation}

 \pi_k := \frac{\bP ( Y \geq k )}{\mu} , ~~~
 \psi_k := \frac{ k \bP ( Y = k)}{\mu}, 
 \text{ for } k \in {\mathbb N}.\end{equation}
 \begin{thmenumi}[label=(\roman*)]
    \item

Let $Z_\infty$, $L_\infty$ denote independent
random variables with distributions given by $\pi$, $\psi$ from~(equation eq:pi-k of the paper), respectively, and set $U_\infty := \max (Z_\infty, L_\infty)$. Then
\[ \sup_{y \in {\mathbb Z}_+} \bP_0 ( Z_y \geq k ) \leq \bP_0 ( U_\infty \geq k) , \text{ for all } k \in {\mathbb Z}_+. \] 
    \item

    It holds that, for every~$x \in {\mathbb Z}$ and every~$k \in {\mathbb N}$, 
\begin{equation}

 \lim_{y \to \infty} \bP_x ( Z_y = k  ) = \pi_k .\end{equation}
 \item 

 Suppose, additionally, that $\Exp ( |X|^p ) < \infty$, for some $p >2$. Then, 
\begin{equation}

\sup_{y \in {\mathbb Z}_+} \bE_x \bigl[ Z_y^{p-2} \bigr] < \infty .\end{equation}
\end{thmenumi} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 31 of arXiv:2606.12720, 'On McDiarmid's Inequality under Dependence \\ via Approximate Tensorization of Entropy'] {DKW-type Inequality under ATE}


    Let $X \sim \nu$ on $\R^n$ where $\nu$ is a probability measure fulfilling $\kappa$-ATE. Assume that the average marginal cumulative distribution function $\bar F$ is continuous. Then, for any $r > 0$,
    \begin{align*}
        \P\Parent{\sup_{x\in\R} |\bar F(x) - \hat F_n(x)| \geq r} 
        \leq \frac 4 r \exp\Parent{-\frac{nr^2}{2\kappa}}. 
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:prefix-postbin-variance-budgets-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] Assume that the local-mass bounds defining \(\mathcal G_n^{\mathrm{pre}}\) hold up to the levels under consideration. If \(2^n\le\lvert\xi\rvert\le2^{n+1}\) and \(
d\in\mathfrak D_{\xi,n}^{\mathrm{osc}}\), then
\begin{equation}
\sum_{\ell=0}^{m-1}
\sum_{I\in\mathcal D_\ell^\circ}
\sum_{\substack{J\in\mathcal D_{\ell+1}^\circ\\ J\subset I}}
\lvert c_J(\xi,d,\ell)\rvert^2M_IT_{\ell+1,n}
\le
C2^{2\varepsilon n}\lvert\xi\rvert^{-a},
\end{equation}
and
\begin{equation}
\sum_{\ell=m}^{\infty}
\sum_{I\in\mathcal D_\ell^\circ}
\sum_{\substack{J\in\mathcal D_{\ell+1}^\circ\\ J\subset I}}
\lvert c_J(\xi,d,\ell)\rvert^2M_IT_{\ell+1,n}
\le
C2^{2\varepsilon n}\lvert\xi\rvert^{-a}.
\end{equation}

[Lemma lem:conditional_continuity_delta_1 of arXiv:2412.01645, 'Regularisation by Gaussian rough path lifts of fractional Brownian motions'] For every $p \in [1, \infty)$,  there exists $k=k(p) \in \mathbb{N}$ and a constant $C=C(p)$ such that for all separable Hilbert spaces $V$ and all  $u \in \mathbb{D}^{k,p}(V \otimes \mathcal{H})$ we have with probability one
    \begin{equs}
        \mathbb{E}^B_s \| \delta_{\mathcal{H}_s^\perp}(u)\|^p_V \leq C \sum_{l=0}^{k}  \left(\mathbb{E}^B_s \| D^l_{\mathcal{H}_s^\perp} \Pi_{\mathcal{H}_s^\perp}u \|_{V \otimes \mathcal{H}^{ \otimes (l+1)}}^{2p} \right)^{1/2}.
    \end{equs}

[Theorem thm:contractionMarkov of arXiv:2603.00773, 'Long-time $L^p$ Wasserstein contraction for diffusion processes without global dissipativi'] Under Assumptions~(assum:decomposeYZ of the paper) and (assum:Contract_at_infty of the paper), for any $p\geqslant 1$, there exist $C_p,\lambda_p>0$ (which depend only and explicitly on $p$ and the parameters in $\mathfrak{P}'$) such that for any $\nu,\mu\in\mathcal P_p(\mathbb R^{n+m})$ and $t\geqslant 0$,
\begin{equation}

\mathcal W_{\omega}(\nu P_t,\mu P_t) \leqslant C_p e^{-\lambda_p t}  \mathcal W_{\omega}(\nu ,\mu)\,,
\end{equation}
with $\omega(x,x')=\max(|x-x'|,|x-x'|^p)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem T:EWDSHE of arXiv:2511.08479, '\Large From disordered systems to the Critical 2D Stochastic Heat Flow'] Let $u^\varepsilon$ be the solution of the mollified 2D SHE  (equation eq:mollSHE of the paper) with disorder strength $\beta_\varepsilon=(\hat\beta+o(1)) \sqrt{\frac{2\pi}{\log \frac{1}{\varepsilon}}}$ for some $\hat\beta\in (0,1)$. Then for any test function $\phi\in C_c(\mathbb{R}^2)$, we have
\begin{equation} 
\frac{1}{\beta_\varepsilon} \int_{\mathbb{R}^2} \phi(x) \big(u^\varepsilon(t,x)-1\big) {\rm d}x
\xrightarrow[\,\varepsilon\to 0\,]{d} \int_{\mathbb{R}^2} \phi(x) v(t, x) {\rm d}x,
\end{equation}
where $v(t, x)$ is the solution to the Edwards-Wilkinson equation
\begin{equation}
\begin{aligned}
	\partial_t v(t,x) & =\frac{1}{2} \Delta v(t,x) + \sqrt{\frac{1}{1-\hat\beta^2}}\, \tilde\xi(t,x), \qquad v(0, x)\equiv 0\,.
\end{aligned}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

