body:
[Theorem thm:martingale of arXiv:2411.07878, 'Bernstein-type and Bennett-type inequalities for unbounded matrix martingales'] Let $\mathbf{X}_1, \dots, \mathbf{X}_n \in \mathbb{H}(d)$ be a supermartingale difference sequence adapted to a filtration $(\mathscr{F}_i)^n_{i=0}$ with $\mathscr{F}_0 = \{\varOmega, \varnothing\}$. Fix $\alpha > 0$ and set for all $i \in [n]$
    \[
    \boldsymbol{\Sigma}_i \coloneqq \E\lrs{\mathbf{X}^2_i \middle| \mathscr{F}_{i-1}},
    \quad
    U_i \coloneqq \norm*{\lambda_{\max}(\mathbf{X}_i)_+ \big| \mathscr{F}_{i-1}}_{\psi_{\alpha}}.
    \]

    Fix $\sigma > 0$, $U \ge K > 0$ and define the event
    \begin{equation}

        E \coloneqq \lrc{\lambda_{\max}\left(\sum^n_{i = 1} \boldsymbol{\Sigma}_i\right) \le \sigma^2, \quad
        \sum^n_{i = 1} U^{2}_i \le U^2, \quad
        \max_{i \in [n]} U_i \le K}.
    \end{equation}
    Let
    \begin{equation}

        z = z(U, \sigma; \alpha) \coloneqq
        \begin{cases}
            \lr{4 \hspace{0.2em}\underline{\log}\hspace{0.2em} \frac{e U}{\sigma}}^{1/\alpha} & \text{if}~\alpha\ge 1, \\
            \lrs{\frac{4}{\alpha} \ln \frac{e}{\alpha} + 4 \lr{\ln \frac{U}{\sigma}}_+}^{1/\alpha}, &\text{if}~\alpha < 1.
        \end{cases}  
    \end{equation}

    Then for any $\mathrm{x} > 0$, it holds, with probability at least $\mathbb{P}(E) - d e^{-\mathrm{x}} - e^{-\mathrm{x}} \ind[\alpha < 1]$, that
    \begin{align}
        \max_{k \in [n]} \lambda_{\max}(\mathbf{S}_k) \le& \sigma \sqrt{2 \mathrm{x}} + \frac{4 Kz \mathrm{x}}{\min\lrc{2 \alpha z^{\alpha}, \hspace{0.2em}\underline{\log}\hspace{0.2em}\lr{\lr{\frac{Kz}{\sigma}}^2 \mathrm{x}} }} \nonumber \\
        &+ \frac{3K}{\alpha}\mathrm{x}\left(2 \mathrm{x} + 2\ln\lr{\frac{4 U}{K}}
        + \frac{4}{\alpha}\ln \lr{\frac{4}{\alpha e}} \right)^{\frac{1-\alpha}{\alpha}} \ind[\alpha < 1]
        \tag{Ben}
    \end{align}
    and, moreover,
    \begin{align*}
        \max_{k \in [n]} \lambda_{\max}(\mathbf{S}_k)  \le \sigma \sqrt{2 \mathrm{x}} + \frac{3}{4} Kz \mathrm{x} 
        + \frac{3K}{\alpha}\mathrm{x}\left(2 \mathrm{x} + 2\ln\lr{\frac{4 U}{K}}
        + \frac{4}{\alpha}\ln \lr{\frac{4}{\alpha e}} \right)^{\frac{1-\alpha}{\alpha}}  \ind[\alpha < 1] .
        \tag{Ber}
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eqn:dim-restriction of arXiv:2608.27904, 'Instantons, indefinite 4-manifolds, and Dehn surgery'] An \textit{instanton $SO(3)$-flow category} $\mathcal M$ consists of a set of $SO(3)$-orbits $\mathsf{Ob}(\mathcal M)$ and a grading function $| \cdot | : \mathsf{orb}(\mathcal M) \to \mathbb Z$ with finitely many orbits in each grading. For each $ \alpha, \beta \in \mathsf{orb}(\mathcal M)$ with \begin{equation} 1\leq |\alpha| - |\beta| \le \dim \mathscr O(\beta) + 2,\end{equation}
there is a compact stratified-smooth $SO(3)$-manifold of dimension $|\alpha| - |\beta|+\dim \mathscr O(\alpha)-1$, denoted $\mkern3mu\widetilde{\mkern-3muM\mkern-1mu}\mkern1mu(\alpha, \beta)$. These spaces are equipped with equivariant maps \[\mathscr O(\alpha) \xleftarrow{s_{\alpha \beta}} \mkern3mu\widetilde{\mkern-3muM\mkern-1mu}\mkern1mu(\alpha, \beta) \xrightarrow{t_{\alpha \beta}} \mathscr O(\beta)\]
called the {\it source} and {\it target} maps. The stabilizer of any point in $\mathscr O(\alpha)$ or $\mkern3mu\widetilde{\mkern-3muM\mkern-1mu}\mkern1mu(\alpha, \beta)$ is required to be conjugate to one of $\{I\}, SO(2)$, or $SO(3)$. The orbits $\mathscr O(\alpha)$ with trivial stabilizer are called \emph{irreducible}. The orbits $\mathscr O(\alpha) \cong S^2$, with stabilizer conjugate to $SO(2)$, are called {\it abelian}, and the orbits $\mathscr O(\alpha) = \{\ast\}$ with stabilizer $SO(3)$ are called {\it central}.\\ 

\noindent Whenever $\alpha, \beta$ satisfy (equation eqn:dim-restriction of the paper), these spaces are also equipped with composition maps \[\circ: \mkern3mu\widetilde{\mkern-3muM\mkern-1mu}\mkern1mu(\alpha, \gamma) \times_{\gamma} \mkern3mu\widetilde{\mkern-3muM\mkern-1mu}\mkern1mu(\gamma, \beta) \to \partial \mkern3mu\widetilde{\mkern-3muM\mkern-1mu}\mkern1mu(\alpha, \beta)\] which are $SO(3)$-equivariant, associative, and preserve the source and target maps. We require that these maps induce a diffeomorphism 
\begin{equation}\partial \mkern3mu\widetilde{\mkern-3muM\mkern-1mu}\mkern1mu(\alpha, \beta) \cong \bigsqcup_{\gamma \in \mathsf{orb}(\mathcal M)} \mkern3mu\widetilde{\mkern-3muM\mkern-1mu}\mkern1mu(\alpha, \gamma) \times_{\gamma} \mkern3mu\widetilde{\mkern-3muM\mkern-1mu}\mkern1mu(\gamma, \beta).\end{equation}
Finally, there is an equivariant periodicity homeomorphism $U: \mathsf{Ob}(\mathcal M)_i \to \mathsf{Ob}(\mathcal M)_{i+8}$ and $U: \mkern3mu\widetilde{\mkern-3muM\mkern-1mu}\mkern1mu(\alpha, \beta) \to \mkern3mu\widetilde{\mkern-3muM\mkern-1mu}\mkern1mu(U\alpha, U\beta)$ preserving the source, target, and composition maps.

