[Theorem thm:main of arXiv:2411.10829, 'Airy$_\beta$ line ensemble and its Laplace transform'] For any $\beta>0$, there is a unique family of time-dependent (stationary) continuous random processes --- denoted by $\{\mathcal{A}^\beta_i(\boldsymbol{\tau})\}_{i=1}^\infty$ --- such that they are ordered $\mathcal{A}^\beta_1\ge \mathcal{A}^\beta_2\ge \dots$; and for any $m\in \mathbb N$, $\vec \mathbf k \in \mathbb R^m_+ $, and $\vec \boldsymbol{\tau}\in \mathbb R^m$ such that $\boldsymbol{\tau}_1\le \cdots \le \boldsymbol{\tau}_m$, the joint moment for the Laplace transforms
\begin{equation} 
\mathbb E\left[ \prod_{\ell=1}^m \left(\sum_{i=1}^\infty
\exp(\mathbf k_\ell \mathcal{A}^\beta_i(\boldsymbol{\tau}_\ell)/2) \right) \right]
\end{equation}
equals $\mathbf L_\beta(\vec\mathbf k,\vec\boldsymbol{\tau})$, which is defined below in (defn:core of the paper)\footnote{The factor of dividing by $2$ in (equation eq_expected_Laplace of the paper) is to simply the expressions in (defn:core of the paper), avoiding various extra factors there. It also comes up naturally in the edge scaling limits.}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 15 of arXiv:2606.27078, 'Semimartingale Optimal Transport with Jumps: A General Framework and Equivalent Formulatio'] Let $\Theta\subseteq\mathbb{R}^d\times\mathbb{S}_+^d\times\mathcal{L}$ be closed, convex and satisfy Assumption~\ref{B}. 
Then for every $\mathbb{P}\in\mathfrak{P}_{\Theta}(\mu_0)$ there exists another probability measure $\widehat{\mathbb{P}}\in\mathfrak{P}_{\Theta}(\mu_0)$ with differential characteristics $(\hat b,\hat c,\widehat F)$ such that
\[
\widehat{\mathbb{P}}\circ X_t^{-1}=\mathbb{P}\circ X_t^{-1}\qquad\forall t\in[0,1],
\]
and under $\widehat{\mathbb{P}}$ the canonical process $X$ solves the martingale problem for the non‑local operator $\mathscr{L}=(\mathscr{L}_s)_{0\leq s\leq 1}$ with initial law $\mu_0$. More precisely,
\begin{enumerate}
\item $\widehat{\mathbb{P}}\circ X_0^{-1}=\mu_0$;
\item for every $f\in C_c^2(\mathbb{R}^d)$, the process
\[
M^f_t:=f(X_t)-f(X_0)-\int_0^t \mathscr{L}_s f(X_s)\,\mathrm{d}s
\]
is well defined and an $\mathbb{F}$‑martingale under $\widehat{\mathbb{P}}$, 
\end{enumerate}
where the operator $\mathscr{L}_s$ acts on $f\in C_c^2(\mathbb{R}^d)$ as
\begin{equation}
\begin{aligned}
\mathscr{L}_s f(x)&:=\hat b(s,x)\cdot D_x f(x)+\frac12\hat c(s,x)\cdot D_{xx}^2 f(x)\\
&\quad +\int_{\mathbb{R}^d}\bigl(f(x+z)-f(x)-D_x f(x)\cdot h(z)\bigr)\,\widehat F(s,x,\mathrm{d}z),\quad \forall s\in[0,1],
\end{aligned}
\end{equation}
with $h$ being the fixed continuous truncation function. The coefficients $(\hat b,\hat c,\widehat F)$ are defined as jointly measurable functions on $[0,1]\times\mathbb{R}^d$ satisfying
\begin{equation}
\begin{aligned}
\hat b(t,X_{t-}) &= \mathbb{E}^{\mathbb{P}}\bigl[b_t^{\mathbb{P}}\,\big|\, X_{t-}\bigr],\\
\hat c(t,X_{t-}) &= \mathbb{E}^{\mathbb{P}}\bigl[c_t^{\mathbb{P}}\,\big|\, X_{t-}\bigr],\\
\int_A (1\land|z|^2)\,\widehat F(t,X_{t-},\mathrm{d}z) &= \mathbb{E}^{\mathbb{P}}\!\left[\int_A (1\land|z|^2)\,F_t^{\mathbb{P}}(\mathrm{d}z)\,\bigg|\, X_{t-}\right],\quad \forall A\in\mathcal{B}(\mathbb{R}^d).
\end{aligned}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:Epm of arXiv:2506.18673, 'Asymptotic Expansions of Gaussian and Laguerre Ensembles at the Soft Edge III: Generating '] Consider $0\leq \xi \leq 1$ and define the
functions\footnote{The definition of $E_{\pm,n}(x;\xi)$ mirrors an analogous construction [MR2895091] in the soft-edge scaling limit.}
\begin{equation}
E_{\pm,n}(x;\xi) := E_{\operatorname{even},n}(x;\xi) + \bigl(1\mp\xi^{1/2}\bigr) E_{\operatorname{odd},n}(x;\xi),
\end{equation}
which are polynomials in $\xi^{1/2}$.
Then, the generating functions $E_{\beta,n}$ can be expressed in terms of~$E_{\pm,n}$ as follows:
\begin{subequations}
\begin{align}
&E_{1,n}(x;\xi)= \frac{1}{2} E_{+,n}\bigl(x;\bar\xi\,\bigr) \bigl(1+\xi/{\bar\xi}^{\,1/2}\bigr)+ \frac{1}{2} E_{-,n}\bigl(x;\bar\xi\,\bigr) \bigl(1-\xi/{\bar\xi}^{\,1/2}\bigr),\\
&E_{2,n}(x;\xi)= \frac{1}{2} E_{+,n}(x;\xi) E_{-,n+1}(x;\xi) + \frac{1}{2} E_{+,n+1}(x;\xi) E_{-,n}(x;\xi),\\
&E_{4,n}(x;\xi)= \frac{1}{2} E_{+,2n+1}(x;\xi) + \frac{1}{2} E_{-,2n+1}(x;\xi).
\end{align}
\end{subequations}
Here, observing \smash{$\xi/\bar\xi^{\,1/2}= \sqrt{\xi/(2-\xi)}$}, the right-hand sides are well defined for all $0\leq \xi\leq 1$.

[Definition def:cone_cond of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] An open set $\Omega\subset\mathbb G$ is said to satisfy the
\emph{intrinsic exterior cone condition} if there exist $\beta,\rho>0$ such
that, for every $p\in\partial\Omega$, there exists a unit vector
$X_p\in V_1$ satisfying
\begin{align*}
\mathcal C_p^+(\beta,\rho;X_p)\setminus\{p\}
\subseteq
\mathbb G\setminus\overline{\Omega}.
\end{align*}

