body:
[Proposition 32 (Moments of the corrected large side) of arXiv:2607.04138, 'Hives from deformed GUE minor processes'] \lab{prop:large-side-moments}
Let
\[
Q_n=\frac{\E|L_n|^2}{n^2}.
\]
Then
\begin{equation}\lab{eq:large-side-Q}
Q_n=n^{21}+O(n^{20}).
\end{equation}
Moreover,
\begin{align}
\frac{\E|\lambda_n|^2}{n^2}&=a^2n,&
\frac{\E|\lambda'_n|^2}{n^2}&=b^2n,\lab{eq:large-side-spectral-moments}\\
\frac{\E\langle L_n,\diag(X_n)\rangle}{n^2}
&=un^{11}+O(n^{10}),&
\frac{\E\langle L_n,\diag(Y_n)\rangle}{n^2}
&=u'n^{11}+O(n^{10}),\lab{eq:large-side-mixed-moments}\\
\frac{\E|\diag(X_n)|^2}{n^2}&=w^2+u^2n,&
\frac{\E|\diag(Y_n)|^2}{n^2}&=(w')^2+(u')^2n.\lab{eq:large-side-diagonal-moments}
\end{align}
Consequently, for
\[
N_n=L_n+\diag(X_n),\qquad P_n=L_n-\diag(Y_n),
\]
one has
\begin{equation}\lab{eq:large-side-exterior-moments}
\frac{\E|N_n|^2}{n^2}
=Q_n+2un^{11}+O(n^{10}),\qquad
\frac{\E|P_n|^2}{n^2}
=Q_n-2u'n^{11}+O(n^{10}).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:integrals of arXiv:2412.05491, 'Near-critical and finite-size scaling for \\ high-dimensional lattice trees and animals'] Let $d>8$ and $L \ge L_0$.
There is a constant $C>0$ such that for all $r \ge 2L+1$, $p \in [p_c - \delta_L, p_c)$, and $x\in \mathbb{T}_r^d$,
\begin{equation}
\Gamma_p^{\star k}(x) \le G_p^{*k}(x) + \frac C{ m(p)^{2k} r^d }
	\qquad (k=1,2,3,4).
\end{equation}

