[Lemma 49 of arXiv:2609.02065, '\textbf{From Bowditch's question to Goldman's conjecture for type-preserving representatio'] Let $P: \univcover\times \univcover\to \univcover$ be a product map, and let $m, n, l\in \mathbb{Z}, s\in\{+,-\}$.
Consider the following restrictions of $P$:
\begin{align*}
P_1:&\ (\Hyp_m\times \Par_0^s) \cap P^{-1}(\Hyp_l) \to \Hyp_l, \text{ and}
\\
P_2: &\ (\Ell_m \times \Par_0^s) \cap P^{-1}(\Hyp_l) \to \Hyp_l.
\end{align*}
For each $i\in \{1,2\}$, every non-empty fiber of $P_i$ is path-connected. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 1 of arXiv:2511.19308, 'Universal scaling limits at the spectral singularity of structured random matrices'] Let $H$ be given by \eqref{eq: matrix model definition}.
    Then for all $z \in \C$ with $\Im(z) > 0$ and all $N \in \N$ the expectation of the resolvent has the integral representation
    \begin{equation} 
        \E\s*{\Tr\p*{\frac{1}{H - z}}}
        = \frac{\ii N^{K+1}}{(2 \pi \ii)^K} \int_{(0, \infty)^K} \dd a \oint^K \dd b \, \ee^{-N I(a) + N I(b)} \det\s*{ S + \diag_{i = 1}^K\p*{\frac{1}{a_i b_i}} } \sum_{j = 1}^K a_j,
    \end{equation}
    where $\dd a$ is the $K$-dimensional Lebesgue-measure and the $b$-integral is $\oint^K \dd b := \oint \dd b_1 \dots \oint \dd b_K$ where each $\oint \dd b_i$ is a counter-clockwise contour integral over the circle around $0$.
    The function $I: \R^K \to \C$ in the exponent is
    \begin{equation} 
        I(a) := \frac{1}{2} \sum_{i, j = 1}^K s_{ij} a_j a_i - \ii z \sum_{i = 1}^K a_i - \sum_{i = 1}^K \log(a_i).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:inhomo of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Let $W_N$ be an $N\times N$ real symmetric (or complex Hermitian) Wigner matrix, let $\Sigma_N$ be a deterministic variance-profile matrix and $A_N$ be a finite-rank perturbation.  Define
\begin{equation} 
H_N=\Sigma_N \circ W_N,  
\end{equation}
where “\(\circ\)” is the Hadamard (entrywise) product, and the corresponding deformed inhomogeneous random  matrix
\begin{equation}
    X_N=H_N+A_N.
\end{equation}
Here,  the following conditions are assumed: 

\begin{enumerate}[leftmargin=*,label=(A\arabic*)]
  \item  \textbf{(Wigner matrix)}  
    The entries $\{W_{ij}\}_{i\le j}$ are independent, symmetric, and satisfy
    \begin{equation}
      \begin{cases}
        \mathbb{E}[W_{ii}^2]=2,\;\mathbb{E}[W_{ij}^2]=1, & \text{real 
        case},\\
        \mathbb{E}[W_{ii}^2]=1,\;\mathbb{E}[|W_{ij}|^2]=1,\;\mathbb{E}[W_{ij}^2]=0, & \text{complex 
        case}.
      \end{cases}
    \end{equation}
    Moreover, there exists $\theta\ge 1$ such that for all $k\ge2$,
    \begin{equation}
      \mathbb{E}\bigl[|W_{ij}\bigr|^{2k}]
      \;\le\;
      \theta^{\,k-1}(2k-1)!!,
     \end{equation}
    where  $\theta:=\theta_N\rightarrow\infty$ may be  allowed   if needed. 
  \item  \textbf{(Variance profile)}  
    The profile matrix $\Sigma_N=(\sigma_{ij})$ has nonnegative entries such that 
    \(\sum_{j=1}^N\sigma_{ij}^2=1\) for each~$i$.  Equivalently, 
    $P_N:=(\sigma_{ij}^2)_{i,j=1}^N
    $ is a Markov transition matrix.

  \item  \textbf{(Finite-rank deformation)}  
    The perturbation $A_N$ is symmetric (resp.\ Hermitian) of rank $r$, with spectral decomposition
    \begin{equation}
        A_N = Q\,\Lambda\,Q^*, 
      \qquad
      \Lambda = \mathrm{diag}(a_1,\dots,a_r,0,\dots,0),
    \end{equation}

    where $Q$ is an orthogonal (resp.\  unitary) matrix.  
\end{enumerate}

[Definition 1 of arXiv:2604.23610, 'Scaling limits of Lévy walks with random velocities'] Let $\left\{\left(V_i, T_i, \mathbf{J}_i\right)\right\}_{i\geq1}$ be the sequence of IID random vectors with components defined in Eq. \eqref{jumpdef}, then
    \begin{equation}
        U_V\left(t\right) = \sum_{i=1}^{N\left(t\right)} \mathbf{J}_i, \quad O_V\left(t\right) = \sum_{i=1}^{N\left(t\right)+1} \mathbf{J}_i, \quad W_V\left(t\right) = \sum_{i=1}^{N\left(t\right)} \mathbf{J}_i + \left(t - \sum_{i=1}^{N\left(t\right)}T_i\right)\mathbf{I}_{N\left(t\right)+1}V_{N\left(t\right)+1}
    \end{equation}
    are called wait-first L\'evy walk with random velocity, jump-first L\'evy walk with random velocity, and (continuous) L\'evy walk with random velocity, respectively. A similar model was introduced in the physics literature in \cite{Denisov2012Levy}.

[Theorem th:multidim of arXiv:2604.20327, 'Persistent Homology of the Wiener Sausage II: A Central Limit Theorem for Drifted Planar B'] Let $\psi_1, \ldots, \psi_m$ be bounded Borel functions supported in a common compact
  interval $[r_0, r_1]$. Then
  \begin{equation}
    \left(
      \frac{\Phi_{\psi_1}(t) - \rho_1 t}{\sqrt{t}},
      \ldots,
      \frac{\Phi_{\psi_m}(t) - \rho_m t}{\sqrt{t}}
    \right)
    \xrightarrow{d}_{t \to \infty}
    \mathcal{N}(0, \Sigma),
  \end{equation}
  where the covariance matrix $\Sigma = (\Sigma_{ij})_{1 \leq i,j \leq m}$ is given by
  \begin{equation}
    \Sigma_{ij}
    = \frac{1}{\mathbb{E}[\eta_0]}
      \bigl(\operatorname{Cov}(Y_0^i, Y_0^j) + \operatorname{Cov}(Y_0^i, Y_1^j) + \operatorname{Cov}(Y_1^i, Y_0^j)\bigr).
  \end{equation}

