[Defn d.omegatmixing of arXiv:2605.28430, 'Limit theory for Lipschitz-localized statistics in random geometric models'] \ 
 \begin{enumerate}[wide,label=(\roman*),labelindent=0pt]
\item  The  marks $U$ of the point process $\tilde \mathcal{P}=\sum_{x \in \mathcal{P}}
  \delta_{\tilde{x}}$, $\tilde{x}=(x,U)$, $x\in\mathbb{R}^d$,  $U\in\mathbb{K}$,
satisfy  {\em $\textnormal{BL}$-mixing correlations} if
there exists an increasing-decreasing family of  functions $\omega_k :  [0, \infty) \to [0,2]$, $k \in \mathbb{N}$, called correlation decay functions,  such that for all $p,q \in \mathbb{N}, x_1,\ldots,x_{p+q} \in \mathbb{R}^d$, and all $f \in \textnormal{BL}(\mathbb{K}^p)$, and
  $g \in \textnormal{BL}(\mathbb{K}^q)$ we have

\begin{align} 
\left|\mathbb {E} _{\bk x1{p+q}}[f(\bk U1{p})g(\bk U{p+1}{p+q})] - \mathbb {E} _{\bk x1p}[f(\bk U1p)]\mathbb {E} _{\bk x{p+1}{p+q}}[g(\bk U{p+1}{p+q})]\right|\le \omega_{p+q}(s),
\end{align}

where $s := d(\bk x1p,\bk x{p+1}{p+q})$ is at (equation defs of the paper).

\item  The marks $U$ have  {\em fast $\textnormal{BL}$-mixing correlations} if $(\omega_k)_{k \in \mathbb{N}}$ are fast decreasing.

\end{enumerate}

[Proposition 194 of arXiv:2601.16377, '2601.16377'] For each $q\in[m]$, $k \geq 1$ and $x\in [-\hat{W}_q,0]$, the random variables
 \begin{equation}

 \int_{\amsmathbb{R}} \left(\mathsf{Ht}^{(q)}_\N(\N^{-1}\lfloor x \N \rfloor, y)-\E\big[\mathsf{Ht}^{(q)}_\N(\N^{-1}\lfloor x \N \rfloor, y)\big]\right) y^k\dd y
 \end{equation}
 are asymptotically Gaussian (in the sense that the joint moments of these random variables converge towards expressions satisfying the Wick formula) with asymptotic covariance for the triplets $(k_1,q_1,x_1)$ and $(k_2,q_2,x_2)$ given by
 \begin{equation}

 \frac{1}{\pi} \int_{\{y_1 \mid (x_1,y_1)\in\pounds_{q_1}\}}\int_{\{y_2 \mid (x_2,y_2)\in\pounds_{q_2}\}} \mathrm{Gr}\big(z^{(q_1)}(x_1,y_1),z^{(q_2)}(x_2,y_2)\big)\,y_1^{k_1}y_2^{k_2}\dd y_1\dd y_2,
 \end{equation}
 where the maps $z^{(q)}$ are as in Section~\ref{Section_complex_structure}.

