[Proposition prop:bound-T_n-optimal of arXiv:2509.08928, 'The near critical random bond Ising model via embedding deformation'] Assume that all the variances in $\Lambda_n$ are unitary and all the other variances vanish. Then there exist some small enough universal constants $c_{1}>0$ such that
 	\begin{equation}
 		\mathbf{P}\Big[ \mathbf{T}_{\Lambda_n}\leq \frac{c_1}{n^\frac{2}{3}\log^{\frac{1}{3}}(n)} \Big] \leq O(\frac{1}{n^4}). 
 	\end{equation}

[Proposition of arXiv:2411.09257, 'Iterated Generalized Counting Process and its Extensions'] The distribution function  $\hat{H}(w,t)=\mathrm{Pr}\{Z(t)\le w\}$ is given by
{\small\begin{align*}
\hat{H}(w,t)&=\mathbb{I}_{\{w\ge0\}}\exp\Big(-\sum_{j_0=1}^{k_0}\mu_{j_0}t(1-e^{-j_0\lambda})\Big)\\
&\ \  +\sum_{m=1}^{\infty}H_X^{*(m)}(w)\sum_{\Omega(k,m)}\Big(\prod_{j=1}^{k}\frac{\lambda_{j}^{m_{j}}}{m_{j}!}\Big)e^{-\mu t}\sum_{\sum_{j_0=1}^{k_0}r_{j_0}=z_{k}}z_{k}!\prod_{j_0=1}^{k_0}\frac{j_0^{r_{j_0}}}{r_{j_0}!}e^{\mu_{j_0}te^{-j_0\lambda}}\mathcal{B}_{r_{j_0}}(e^{-j_0\lambda}\mu_{j_0}t),
\end{align*}}
where $\mathcal{B}_n(x)$ is the $n$th order Bell polynomial defined in (equation bell of the paper).

