[Proposition MartingaleReProp of arXiv:2411.15485, '\bf\Large Stochastic Volterra Equations for Local Times of Spectrally Positive L\'evy Proc'] For any $T\geq 0$, the random variable 
 \begin{eqnarray}
  \boldsymbol{Y_T}
  :=  X_\zeta*d\mu(T) - \big(\boldsymbol{\mathcal{R}}\circ V_\mu\big)  *X_\zeta(T) 
 \end{eqnarray}
 is integrable and has the following equivalent representation
 \begin{eqnarray} 
 \boldsymbol{Y_T}
 \!\!\!&=\!\!\!&  \zeta\cdot c \cdot  V_\mu (T)+ \int_0^\zeta \int_0^\infty \Big( \int_{T-y}^{T} V_\mu (r)\,dr\Big) N_0(dz,dy)\cr
 \!\!\!&\!\!\!& + \int_0^T \int_0^{X_\zeta(s)}   V_\mu (T-s) \, B_c(ds,dz) \cr
 \!\!\!&\!\!\!& + \int_0^T\int_0^{X_\zeta(s)} \int_0^\infty \Big( \int_{T-s-y}^{T-s} V_\mu (r)\,dr\Big) \, \widetilde{N}_\nu(ds,dz,dy) .

 \end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lem_Slepian of arXiv:2608.17463, 'Persistence probabilities of fractional L\'evy fields indexed by hyperbolic space and othe'] Let $(E,d)$ be a metric space and let $(X_t)_{t\in E}$ and $(Y_t)_{t\in E}$ denote two real-valued, separable, centred Gaussian processes, such that
    \begin{align*}
        \mathbb{E}\left[X_t^2\right] & = \mathbb{E}\left[Y_t^2\right], \quad \forall t\in E,
        \qquad\qquad
        \mathbb{E}\left[X_s X_t\right]  \leq \mathbb{E}\left[Y_s Y_t\right], \quad \forall s,t\in E.
    \end{align*}
    Let $f: E\to \mathbb{R}$ be a measurable function that is continuous except for countably many points. Then
    \begin{align*}
        \mathbb{P}\left(X_t \leq f(t) \quad \forall t\in E\right) \quad \leq \quad \mathbb{P}\left(Y_t \leq f(t) \quad \forall t\in E\right).
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

