[Proposition 4 of arXiv:2506.11799, 'Quenched limit for diffusive biased random walks in random environment'] Under our assumptions, there exists a universal constant $\eta>0$ such that we have that
	\begin{equation*}
		\inf_{x, y \in \mathbb{V}_d} \mathbb{P}_{x, y} \left( \{\mathcal{D}^\bullet = \infty\} \right) \ge \eta.
	\end{equation*}
    Furthermore, we have that for all $p>0$ there exists a constant $C = C_p$ such that
    \begin{equation*}
    	\sup_{x, y \in \mathbb{V}_d} \mathbb{E}_{x, y} \Bigg[ \Big(\sup_{0 \le t \le \mu^{(1)}_1} \|X^{(1)}_t\|\Big)^p \Bigg] < \infty,
    \end{equation*}
    the same result holds symmetrically for $X^{(2)}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 4 of arXiv:2606.10336, 'From Pitman's local times representation to the Gorin-Shkolnikov identity and beyond'] Assume that $\phi: \mathbb{R} \to \mathbb{R}$ be sufficiently smooth and $\int_0^1\phi(x)^2dx < \infty$.
We have:
\begin{equation}

\int_0^\infty \phi(I_x) dx - \frac{1}{4} \int_0^\infty \ell_x^2 \left( \frac{\phi(I_x)}{I_x} + \phi'(I_x) \right)dx 
\stackrel{d}{=} \mathcal{N}\left(0, \frac{1}{4} \int_0^1\phi(x)^2 dx\right).
\end{equation}

[Proposition 5 of arXiv:2607.07022, 'Coordinate-wise Elephant Random Walk'] Assume $p_i\in(0,1).$ There exists $C_{p_i}<\infty$ such that for all $r \geq 1,$
    \begin{equation*}
        \E[(m_r^{(i)})^2] \leq C_{p_i} \begin{cases}
            r^{-1}, & \text{\rm if }\, 0<p_i<\tfrac34,\\
            \dfrac{\log r}{r}, &\text{\rm if } \, p_i=\tfrac34,\\
            r^{-4(1-p_i)}, &\text{\rm if } \, \tfrac34<p_i<1.
        \end{cases}
    \end{equation*}

