[Lemma 18 (The two outer blocks) of arXiv:2608.20101, '\bfseries Largest bulk gap of the complex Ginibre ensemble'] Uniformly for \(t\in I\),
\begin{equation}
 S_>=O_I(e^{-c_I N}).
\end{equation}
Moreover,
\begin{equation}
 S_<=F_1N^2+F_2N\log N+F_3N+F_5\log N+F_6
       +O_I\!\left(\frac{\log N}{N}\right),
\end{equation}
where
\begin{align*}
 F_1={}&-\frac{t^4}{4(1+\epsilon)^2}
       \bigl(1+4\epsilon-2\log(1+\epsilon)\bigr), \qquad  F_2=-\frac{t^2}{2(1+\epsilon)},\\
 F_3={}&\frac{t^2}{1+\epsilon}\left[
 (1-\vartheta)\epsilon+1-\log(t\sqrt{2\pi})
 +\epsilon\log\frac{\epsilon}{1+\epsilon}
 +(\vartheta-1)\log(1+\epsilon)\right],\\
 F_5={}&\frac7{12}-\frac{\vartheta}{2},\\
 F_6={}&\frac{-1+6\vartheta^2}{12}\log(1+\epsilon)-\frac1\epsilon
 +\frac{1-2\vartheta}{2}\log\epsilon+\frac76\log t
 +\frac12\log(2\pi)\\
 &\hspace{17mm}-\vartheta\log(t\sqrt{2\pi})-\zeta'(-1).
\end{align*}

[Lem convergence of degree couting processes of tilted trees of arXiv:2412.08236, 'Aging and sub-aging for Bouchaud trap models on resistance metric spaces'] Write $I$ for the identity map from $[0,1]$ to itself.
  Assume that a sequence $(m_{n})_{n \geq 1}$ satisfies $n^{-2/3} m_{n} \to \sigma \in (0,\infty)$.
  Then, for any $k \in \mathbb{Z}_{\geq 0}$,
  \begin{equation}
      m_{n}^{-1} N_{\tilde{T}_{m_{n}}^{p_{n}}}^{(k)}((m_{n}-1) \cdot)
    \xrightarrow{\mathrm{p}}
    p_{k}\, I(\cdot)
  \end{equation}
  in $D([0,1], \mathbb{R}_{\geq 0})$.

[Proposition 57 of arXiv:2601.16377, '2601.16377'] The measure $\mu$ has a density which is given, if $\sqrt{2 \theta \kappa}\leq \pi$, by
\begin{equation}
 \mu(x)= \left\{\begin{array}{lll}
  \dfrac{\kappa}{\pi \theta}\sqrt{\dfrac{2\theta}{\kappa}- x^2 } & & |x| \leq \sqrt{\dfrac{2\theta}{\kappa}}, \\[10 pt] 0 & & \textnormal{otherwise,} \end{array}\right.
\end{equation}
 and if $\sqrt{2 \theta \kappa}>{\pi}$, by
\begin{equation}
 \mu(x)= \left\{\begin{array}{lll}
 \dfrac{1}{\theta} & & |x| \leq \alpha \\[10pt]
  \dfrac{2 \sqrt{(\beta^2 - x^2)(x^2 - \alpha^2)}}{\pi \theta \beta |x|}\,\Pi_1\bigg[-\dfrac{\alpha^2}{x^2}\,;\,\mathsf{k}\bigg] & & |x| \in (\alpha,\beta) \\[10pt]
  0& & |x|\geq \beta \end{array}\right. ,
\end{equation}
 where $\beta$ and $\mathsf{k} = \frac{\alpha}{\beta}$ are determined by the system of two equations:
\begin{equation}
 \kappa \beta= 2K(\mathsf{k}),\qquad \kappa\theta = 2K(\mathsf{k})\big(2E(\mathsf{k}) - (1 - \mathsf{k}^2)K(\mathsf{k})\big).
\end{equation}

