[Cor stronger RW to independent RI coupling of arXiv:2411.16398, 'Large Deviations of Cover Time of Tori in Dimensions $d\geq 3$'] Let $\delta > 0, \eta \in (0,1) \text{ and } N \in \mathbb{N}$. Assume that $R \in (N^{\frac{1}{2}}, \frac{N}{1+\delta}]$, $\boldsymbol{F} \subset \mathbb{T}_N$ is $(1+\delta)R$-well separated, and $Q_R(x) \subset Q_\eta$ for all $x \in F$. Then for every $u \geq 1$ and $\rho \in (0,1)$, there exists a probability measure $\widetilde{\mathsf{P}}$ extending $\mathsf{P}$ and carrying independent random interlacements $\left(\mathcal{I}^{(x),u(1\pm\rho)}\right)_{x\in F}$ with the same law as $\mathcal{I}^{u(1\pm\rho)}$, such that
    \begin{multline}

        \widetilde{\mathsf{P}}\Big(\mathcal{I}^{(x), u(1-\rho)} \cap Q_R(x) \subset X[0, uN^d] \cap Q_R(\boldsymbol{x}) \subset \mathcal{I}^{(x), u(1+\rho)} \cap Q_R(x) \text{\quad for all } x \in F \Big) \geq \\
        1-CuN^{3d}\exp\Big(-c\rho^2 \sqrt{uN^{d-2}}\Big)
    \end{multline}
    holds for some constants $c,C \in (0, \infty)$ depending only on $\delta$, $\eta$ and $d$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 16 of arXiv:2608.26803, 'On bubbling of Fueter maps'] For a complex manifold $(X, I)$, let 
    \begin{equation*}
        \Rat(X, I) \coloneq \{ x \in X \; | \; x\in C \; \text{for some irreducible rational curve } C\} 
    \end{equation*}
    denote the \textbf{locus of rational curves} on $(X, I)$.

[Lemma lemmas3.1 of arXiv:2608.01279, 'Stochastic heat equation with nondegenerate Hölder diffusion coefficient: uniqueness below'] For every fixed \(\delta>0\),

\begin{equation}
D\to K_\delta(D)-I,
\qquad
D\to S_\delta(D)

\end{equation}
are globally Lipschitz maps from \(H\) to the Hilbert--Schmidt
operators on \(H\).  More precisely,

\begin{equation}
\|K_\delta(D)-K_\delta(E)\|_{\mathrm{HS}}
+\|S_\delta(D)-S_\delta(E)\|_{\mathrm{HS}}
\le C_{K_0}\delta^{-1}\|D-E\|_H,

\end{equation}
where $C_{K_0}>0$ only depends on $K_0$.
Furthermore,

\begin{equation}
\|K_\delta(D)\|_{\mathrm{op}}\le1,
\qquad
\|S_\delta(D)\|_{\mathrm{op}}\le1,
\qquad
K_\delta K_\delta^*+S_\delta S_\delta^*=I.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

