[Proposition 38 of arXiv:2606.22611, 'Upper and Lower Bounds on Expected Soft Maxima\\of Gaussian Processes'] For some $m,n\in \bN$, if $p \deq m/n \le \frac{1}{2}$, then 
\begin{align*}
 \frac{1}{n+1}e^{n h(p)} \le
\sum_{i=0}^m \binom{n}{i}
\le e^{n h(p)}
\end{align*}
where $h(p) \deq -p \log p -(1-p)\log (1-p)$ is the binary Shannon entropy in nats.
\begin{proof}
  Let $V_m \deq \sum_{i=0}^{m} \binom{n}{i}$. Observe that for $i \le n$ 
\begin{align*}
\frac{(1-p)^{n-i}p^i}{(1-p)^{n-m}p^m}
= (1-p)^{m-i} p^{i-m}=\Big(\frac{1}{p}-1\Big)^{m-i}
\end{align*}
is decreasing as $i$ increases. Therefore,
\begin{align*}
  1= (1-p+p)^{n} \ge \sum_{i=1}^m (1-p)^{n-i}p^{i}\binom{n}{i}
   \ge (1-p)^{n-m}p^{m} V_m = e^{-n h(p)}V_m 
\end{align*}
yields the upper bound. For lower bound,
since for binomial distribution, its mode is $\floor{(n+1)p}=m$, i.e., 
for any $i \le n$,
\begin{align*}
  (1-p)^{n-i}p^{i}\binom{n}{i} \le (1-p)^{n-m}p^{m}\binom{n}{m} 
  = e^{-n h(p)}\binom{n}{m}
\end{align*}
Summing over $i$ gives the lower bound.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 11 of arXiv:2605.30560, 'Projected McKean--Vlasov Dynamics for Entropic Weak Optimal Transport'] When $d=1$ and $\mu,\nu \in \Pc_2(\R)$, for any $\pi\in\Pi(\mu,\nu)$,
\begin{equation}
\begin{aligned}
T^{\rm ad}_{\pi}\big(\Pi(\mu,\nu)\big)
& =
\big(L^2(\mu)\oplus L^2(\nu)\big)^{\perp},
\end{aligned}
\end{equation}
where orthogonality is taken in $L^2(\pi;\R^{2})$.
The orthogonal projection onto $T^{\rm ad}_{\pi}\big(\Pi(\mu,\nu)\big)$ is given by
\begin{equation}
\begin{aligned}
P^{\pi}:\ T^{\rm ad}_{\pi}\!\big(\Pc_2(\R^{2})\big) &\longrightarrow T^{\rm ad}_{\pi}\big(\Pi(\mu,\nu)\big),\\
u=(u_1,u_2) &\longmapsto \Big(0,\ u_2-\E_{Y}^{\pi}\!\big[u_2(X,Y)\big]\Big).
\end{aligned}
\end{equation}

