[Lemma lem:vertex_split of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] There exists a map from the set of diagrams   with all unmarked vertices of degree at least $3$ to the set of typical connected diagrams 
\begin{equation}
    \phi : \mathscr{D}_{s;\beta}^* \to \mathcal{T}_{\ell, s}, \quad \Gamma \mapsto \phi(\Gamma)
\end{equation}
  such that  the following three conditions hold: 
\begin{itemize}
    \item[(i)] (Preserving $|E|-|V|$) 
    \begin{equation}
        |E(\phi(\Gamma))| - |V(\phi(\Gamma))| = |E(\Gamma)| - |V(\Gamma)|,
    \end{equation}

    \item[(ii)] (Monotonic decreasing) 
    \begin{equation}
        |E(\phi(\Gamma))| \ge |E(\Gamma)|, \qquad |V(\phi(\Gamma))| \ge |V(\Gamma)|,
    \end{equation}

    \item[(iii)] (Multiplicity controlling)  
       \begin{equation}
        |\phi^{-1}(\Gamma)| \le 2^{|E(\Gamma)|},\quad \forall \,\Gamma \in \mathcal{T}_{\ell, s}.
    \end{equation}

\end{itemize}

[Definition 19 of arXiv:2605.11801, 'A non-local singular non-linear Fokker-Planck PDE'] We say that $v\in C_T\shc^{\beta} $ is a   mild solution to \eqref{eq:FPlim} if  for all $t\in[0,T]$
\begin{equation}
  v(t)= P_{t}v_0-\int_0^t P_{t-s}\left({\rm div}
    \left((v(s)F(K*v(s)))\cdot b(s)\right)\right)ds.
\end{equation}

[Lemma 19 of arXiv:2607.29495, 'Fast Mixing for Low-Temperature Potts Models via Poisson Trees'] Suppose that $\rho\in (0,\tfrac{1}{20})$ and that $\mathcal{B}=\{B_v\}_{v\in \Vin(T)}$ is a rooted block decomposition of~$T$ that satisfies non-reconstruction with block decay~$\rho$ under the distribution~$\nu$. 

Then, for every $v\in T$ and  $\eta\in\Omega$, for any
function $g:\Omega\to\mathbb R$,
\[
        \Var^{\eta}_{T_v}
        \left(\E^{\circ}_{T'_v}g\right)
        \le
        4\E^{\eta}_{T_v}
        \left[\Var^{\circ}_{B_v}(g)\right]
        +
        5\rho\E^{\eta}_{T_v}
        \left[\Var^{\circ}_{T'_v}(g)\right].
\]

