[Lem 36 ({\cite[Lemma 4.2) of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] {Cr18}}]\quad\par
  \begin{itemize}
    \item[$\mathrm{(i)}$] If $x\in F$, $A$ is a non-empty closed subset of $F\setminus\{x\}$ and $\delta\in (0,R(x,A))$, then
\begin{align*}
  P_x(\sigma_A\leq t)\leq 2\left[ 1-\left(\frac{R(x,A)-\delta}{R(x,A)+\delta}\right)e^{-\frac{ 2t }{\mu(B(x,\delta))(R(x,A)-\delta)}} \right],\qquad \forall t\geq 0.
\end{align*}
In particular, if $x,y\in F$, $\varepsilon\in (0,R(x,y)/2),\delta\in (0,R(x,y)-2\varepsilon)$, then
\begin{align*}
  P_x\left(\sigma_{\overline{B(y,\varepsilon)}}\leq t\right)\leq 4\left[\frac{\delta}{R(x,y)-2\varepsilon}+\frac{t}{\mu(B(x,r))(R(x,y)-2\varepsilon-\delta)}\right],\qquad \forall t\geq 0.
\end{align*}
\item [$\mathrm{(ii)}$]If $\rho\in F$ and $\delta\in (0,R(\rho,B(\rho,r)^c))$, then 
\begin{align*}
  P_{\rho}\left( \sigma_{B(\rho,r)^c}\leq t \right)\leq 4\left[ \frac{\delta}{R(\rho,B(\rho,r)^c)}+\frac{t}{\mu(B(\rho,\delta))(R(\rho,B(\rho,r)^c)-\delta)} \right],\quad t\geq 0.
\end{align*}
NB. If $B(\rho,r)^c=\emptyset$, then we interpret the right-hand side as being equal to zero.
  \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

