    \end{equation*}
    where 
\begin{equation}
    v(\mathcal{A}) \coloneqq \max_{\substack{R= [q+2]\backslash C\\q+1, q+2\in C\\R \neq \emptyset}} \left\|\flatta{R}{C}\right\|.
