body:
[Theorem main left soft edge2 of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] Consider an LUE $L_{a,N}$ such that $\lim\limits_{N\rightarrow\infty}\frac{N}{n}=\gamma\in(0,1)$ where $n=N+a$. On any $A\subset[s_0,+\infty)$ for $s_0>-\infty$. Define parameters:
    \begin{equation*}
      \begin{array}{ll}
      \mu_{k,m}:=\left(\sqrt{k+\frac{1}{2}}-\sqrt{m+\frac{1}{2}}\right)^2,\\
      \sigma_{k,m}:=\left(\sqrt{k+\frac{1}{2}}-\sqrt{m+\frac{1}{2}}\right)\left(\left(m+\frac{1}{2}\right)^{-\frac{1}{2}}-\left(k+\frac{1}{2}\right)^{-\frac{1}{2}}\right)^{\frac{1}{3}}.
      \end{array}
    \end{equation*}
    Let $G_\tau=\xi_\tau$, $H_\tau=-\eta_\tau$ be kernels defined in (equation left soft kernel of the paper) and $\tau$ be the scaling with respect to
\begin{equation*}
    \tilde{\mu}_{n,N}=\left(\frac{1}{\sqrt{\sigma_{n-1,N}}}+\frac{1}{\sqrt{\sigma_{n,N-1}}}\right)\left(\frac{1}{\mu_{n-1,N}\sqrt{\sigma_{n-1,N}}}+\frac{1}{\mu_{n,N-1}\sqrt{\sigma_{n,N-1}}}\right)^{-1},
\end{equation*}
\begin{equation*}
    \tilde{\sigma}_{n,N}=\left(\frac{\sqrt{\sigma_{n-1,N}}}{\mu_{n-1,N}}+\frac{\sqrt{\sigma_{n,N-1}}}{\mu_{n,N-1}}\right)\left(\frac{1}{\mu_{n-1,N}\sqrt{\sigma_{n-1,N}}}+\frac{1}{\mu_{n,N-1}\sqrt{\sigma_{n,N-1}}}\right)^{-1}.
\end{equation*}
Then, for large $N$ and $t\in A$,
   \begin{equation}
\begin{array}{ll}
  |G_{\tau}(t)+H_{\tau}(t)+(-1)^{N+1}\sqrt2 Ai(t)|\le N^{-\frac{2}{3}}C(s_0,\gamma)e^{-\frac{t}{2}},\\
  \\
  \left|G_{\tau}(t)+(-1)^{N+1}\frac{\sqrt2}{2} Ai(t)\right|\le N^{-\frac{1}{3}}C(s_0,\gamma)e^{-\frac{t}{2}},\\
  \\
  \left|H_{\tau}(t)+(-1)^{N+1}\frac{\sqrt2}{2} Ai(t)\right|\le N^{-\frac{1}{3}}C(s_0,\gamma)e^{-\frac{t}{2}}.
\end{array}
\end{equation}
Furthermore, for any fixed $\gamma$, $C(s_0,\gamma)$ is non-increasing with respect to $s_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma of arXiv:2601.07808, 'Supercritical long-range percolation on graphs of polynomial growth: the truncated one-arm'] \label[lemma]{lem:block_connectivity}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 2$, and let $R \in \mathbf{N}$ be as in (prop:boundary_connectivity of the paper).

    For any block $A \in \mathcal{A}$, the boundary $\partial A$ is $R$-connected.

[Theorem 1 of arXiv:2605.28801, 'Microscopic Weak Selection Principle for the Logistic Branching Brownian Motion with selec'] For each $T>0$, the sequence of probability measures $\{\mu^K\}_{K\in\mathbb{N}}$ defined by \eqref{eq: defemp0} converges in law in $D\left([0,T], M_F(\mathbb{R})\right)$ to a continuous deterministic function $\mu:=(\mu_t)_{t\in[0,T]}$. In particular, the measure-valued function $\mu$ is the unique solution of the following PDE, written in its weak form
	\begin{equation}
		\left<\phi, \mu_t\right> = \left<\phi, \mu_0\right> + \int_0^t\int_{\mathbb{R}}\Bigg[\partial_t \phi(s,x) + \frac{1}{2}\partial_{xx} \phi(s,x)
		+ \phi(s,x) \left(1- 2 \int_x^{\infty} \mu_s(dy)\right)\Bigg]\mu_s(dx)ds,
	\end{equation}
	for all bounded functions $\phi(t,x) \in C^{1,2}_b(\mathbb{R}_+\times\mathbb{R})$.

	Moreover, if $\mu_0$ has a density with respect to the Lebesgue measure, then for every $t \in [0,T]$ the finite measure $\mu_t$ has a density $u$ with respect to the Lebesgue measure, such that $\mu_t(dx) = u(t,x)dx$, and $u$ is a weak solution of the (nonlocal and nonlinear) partial integro-differential equation
	\begin{equation}
		\begin{split}
			\partial_t u(t,x)=  \frac{1}{2}\partial_{xx} u(t,x)
			+ u(t,x)\Big(1 - 2  \int_x^{\infty} u(t,y)dy\Big)\
		\end{split} .
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop closed-strict of arXiv:2608.27939, 'Entropy and domination for quasi-Hitchin representations'] Let $S$ be closed, let $\lambda$ be an arbitrary maximal geodesic lamination on $S$, and let $\rho:\pi_1(S) \to \mathrm{PSL}_n(\mathbb{C})$ determined by $(\alpha_\rho, \theta_\rho) \in \mathcal{Y}(\lambda,n;\mathbb{C}/2\pi i\mathbb{Z})$ with $n\geq3$.  Let $\rho_0$ be the Hitchin representation determined by the real part of the cocycle as in (equation eq:rho0coords of the paper).  If $(\operatorname{Im}\alpha_\rho,\operatorname{Im}\theta_\rho)\neq0$,
then there exist a nontrivial $\gamma\in\pi_1(S)$, and determinant-one lifts
$A,A_0\in\mathrm{SL}_n(\mathbb{C})$ of $\rho(\gamma), \rho_0(\gamma) \in \mathrm{PSL}_n(\mathbb{C})$ respectively, 
such that
\begin{equation}
 \abs{\minor{I}{J}{A}}
 <\minor{I}{J}{A_0}
\end{equation}
for every $I,J\subset \{1,2,\ldots, n\}$ with $1\leq|I|=|J|<n$.  In particular $|A|<A_0$.

[Definition def:NAmag of arXiv:2511.05223, 'Kac's Program and Relative Entropy Decay for Nonlinear Spin-Exchange Dynamics'] Given a partition $\ensuremath{\mathcal A}$ of $[n]$, we write $D_{\ensuremath{\mathcal A},N}$ for the set of all vectors $\r=(\r(A),\,A\in\ensuremath{\mathcal A})\in[0,1]^\ensuremath{\mathcal A}$ such that $N|A|\r(A)$ 
is a nonnegative integer. Given $\ensuremath{\mathcal A}$,  $D_{\ensuremath{\mathcal A},N}$ is called the set of $\ensuremath{\mathcal A}$-\emph{density profiles}. Given $\r\in D_{\ensuremath{\mathcal A},N}$, we define
\begin{equation}
\O_{N,\r}= \left\{\si\in\O^N: \; \textstyle{\sum_{i\in [N]}\sum_{\ell\in A}}\si_\ell(i)=(2\r(A)-1)N|A|,\; \;\forall A\in\ensuremath{\mathcal A}\right\}\,.
            \end{equation}

[Lemma 70 of arXiv:2607.18104, '2607.18104'] For all $n\in \N$ and $\ell \in \lbr n \rbr$, we define the sets
\begin{equation}
    U_{\ell}^n := \left\{ (u;v)\in \Z^4_{\uparrow}  \,  \colon \,  \gper_{u,v} \cap X^{n}_{\ell-1} \neq \emptyset \, \wedge \, \gper_{u,v} \cap X^{n}_{\ell} \neq \emptyset \right\}
\end{equation}
and the events
\begin{equation*}
    A_n :=  \bigcap_{\ell \in \lbr n-1\rbr} \bigcap_{(u;v) \in U^{n}_{\ell}}  \Big\{ \Big| \gamma^{\per,\pm}_{u,v}( \lfloor \ell n^{-1}N^{3/2} \rfloor ) - \gamma^{\per,\pm}_{u,v}( \lfloor (\ell-1) n^{-1}N^{3/2} \rfloor) -  m_{\ast}^{-1}n^{-1}N^{3/2}\Big| \leq 4 N \Big\} . 
\end{equation*} 
 Then there exist constants $c,C>0$ such that for all $n \in \N$, we get that
\begin{equation}
    \P_{\per}(A_n) \geq 1 - C\exp(-c n^{2/3} )
\end{equation} for all $N$ large enough. Similarly, for all $n\in \N$, we define the events
\begin{equation}
    \tilde{A}_n :=  \bigcap_{\ell \in \lbr n\rbr} \bigcap_{(u;v) \in Y_{\ell}^{n} \times Y_{\ell}^{n}}  \Big\{ \TF(\gper_{u,v}) \leq 4 N \Big\} . 
\end{equation} 
 Then there exist constants $\tilde{c},\tilde{C}>0$ such that for all $n \in \N$, we get that
\begin{equation}
    \P_{\per}\big(\tilde{A}_n\big) \geq 1 - \tilde{C}\exp(-\tilde{c} n^{2/3} )
\end{equation} for all $N$ large enough.

