[Corollary 19 of arXiv:2608.25971, 'Positive \texorpdfstring{$\tau$}{tau}-bi-Ricci curvature and Mean curvature flow with surg'] There are constants
\begin{equation*}
 h_\#=h_\#(n,\alpha)<\infty,
 \qquad c_\#=c_\#(n,\alpha)<\infty
\end{equation*}
such that, whenever $H(p,t)\geq h_\#R^{-1}$,
\begin{equation}
 |\nabla H|(p,t)\leq c_\#H(p,t)^2,
 \qquad
 |\partial_tH|(p,t)\leq\frac12c_\#^2H(p,t)^3.
\end{equation}
If the cylinder
\begin{equation*}
 \mathcal P\left(
 p,t,\frac1{10c_\#H(p,t)},
       \frac1{100c_\#^2H(p,t)^2}\right)
\end{equation*}
is defined, then
\begin{equation}
 \frac1{10}H(p,t)\leq H(q,s)\leq10H(p,t)
\end{equation}
throughout this cylinder.

[Lemma 4 of arXiv:2608.13732, '\textbf{On the First Hitting Time Problems \\ for Diffusion Processes: \\ Local Time-Space'] For any function $c:[0,T]\to\mathbb{R}$ in $C^1$, the transition density function $q(s,y;t,x)$ with $0\le t<s\le T$ and $x,y\in\mathbb{R}$ has the following asymptotic behavior:
\begin{equation}
q(s,c(s);t,c(t))
\sim
\frac{1}{\sqrt{2\pi}\,\sigma(t,c(t))}(s-t)^{-1/2}
\quad \text{as } s\to t+,
\end{equation}
and $q(s,y;t,x)\to0$ for $x\neq y$ as $s\to t+$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:berrycanc2 of arXiv:2607.09946, 'Statistics on Yau's conjecture: Variance asymptotics'] Under the same hypotheses of (cor:berrycanc_intro of the paper), if $\alpha=1$ and $(M,g)$ has no conjugate points, then
    \begin{equation} 
{\mathbb{V}\mathrm{ar}}\left( \frac{\mathrm{Vol}^{n-1}(\{x:\phi_{[\ell-\eta_\ell,\ell]}^M(x)=t\sigma_\ell(x)\})}{\lambda\left( \phi_{[\ell-\eta_\ell,\ell]}^M\right)}\right)
=
\frac{1}{N^M_{[\ell-\eta_\ell,\ell]}}\cdot\begin{cases}
    \Omega(1), \quad &\text{if $t\neq 0$, }
    \\
    \mathrm{o}(1), \quad &\text{if $t=0$.}
\end{cases}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:Beurling of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] {kkmt2026cle4_part2}}]
		There is a universal constant $C > 0$ such that the following is true: Let $K_1, K_2 \subset \overline\BD$ be two disjoint, connected, simply connected, and compact subsets,  such that $\partial \BD \not\subseteq K_1 \cup K_2$. Then the extremal distance in $\BD$ between $K_1$ and $K_2$ is at most 
		\begin{equation}
			\left.C\middle/\log\left(\frac{\diam(K_1) \wedge \diam(K_2)}{\dist(K_1, K_2)} \vee 1\right)\right., 
		\end{equation}
		where $\diam$ and $\dist$ denote Euclidean diameter and distance, respectively. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 18 ({\cite[Theorem 1.6) of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] {DLE}}]
    Fix $q\in\mathbb R, a,b,c>0$.   There exists a deterministic function $\cH_{q;a,b,c}:\mX_{a,b,c}\mapsto \mathbb R$ such that the height function $H_\eta$ of a random tiling sampled from $\mathbb P^{N,q}_{a,b,c}$ tends in probability to $\cH_{q;a,b,c}$ as $N\to\infty$:
    for every $\varepsilon>0$,
    \begin{eqnarray}

      \lim_{N\to \infty}\mathbb P^{N,q}_{a,b,c}(\exists z\in \mX_{a,b,c}:|H_\eta(z)-\cH_{q;a,b,c}(z)|\ge \varepsilon)=0.
    \end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 16 of arXiv:2608.06646, 'Three-dimensional stochastic wave equation with non-Lipschitz coefficients'] Let $\alpha\in(-3,0)$ and $\beta>0$. Then there exists a constant
$C=C(\alpha,\beta)>0$ such that
    \begin{align*}
    \sup_{y\in \R^3}\int_{\R^3}{\left|x-y\right|^{\alpha}}e^{-\frac{|x|^2}{\beta}}\ud x\le C\,.
    \end{align*}
In particular, the integral is finite and uniformly bounded with respect to the spatial shift $y\in\R^3$.

