[Lemma 48 of arXiv:2608.29157, 'Dilator-based analysis of $\KP$'] Let $H=E\circ (F+1+G)$ and $\ttX$ be a template order.
    \begin{enumerate}
        \item If $H[\ttX]\sststile{\rho}{\alpha} \Gamma,A\land B$, then $H[\ttX]\sststile{\rho}{\alpha} \Gamma,A$ and $H[\ttX]\sststile{\rho}{\alpha} \Gamma, B$.
        \item Suppose that $H[\ttX]\sststile{\rho}{\alpha} \Gamma,\forall x\in t\ B(x)$. For every template order $\ttY\supseteq\ttX$ and a term $s\in \bfL(u)_\ttY$ satisfying $(\spadesuit)$, we have $H[\ttY] \sststile{\rho}{\alpha} \Gamma, s\dotin t\to B(s)$.
    \end{enumerate}

