body:
[Theorem thm:Polya schur and multiplicative groups of arXiv:2605.31356, 'P\'olya--Schur problems and free probability'] Let $\{f_n\}\subset\mathcal{LP}$ be a sequence of functions with only negative roots and which satisfies  Assumption (assump:main assumption of the paper). If $t\geq 0$ and $\{p_n\}_{n\geq 1}$ is a sequence of positively-rooted polynomials indexed by their degree such that $\llbracket p_n\rrbracket\Rightarrow\mu$ as $n\rightarrow\infty$, then \begin{equation}
		\left\llbracket f_{\lfloor tn\rfloor}(tz\partial_{z})p_n(z)\right\rrbracket\Rightarrow \mu\boxtimes \tilde{\mu}_{c,\Sigma}^{\boxtimes t},
	\end{equation} where $\tilde{\mu}_{c,\Sigma}$ is the $\boxtimes$-infinitely divisible probability measure on $[0,\infty)$ with $S$-transform \begin{equation}
		S_{\tilde\mu_{c,\Sigma}}(z)=\exp\left(-R_{\mu_{c,\Sigma}}(z+1) \right),
	\end{equation} for $z\in (-1,0)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 27 (Change of contour for direction $\alpha_b$) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] Assume that $x_{max}^+ < x_{max}^-$, i.e., $\alpha_b \in (0,\pi)$. Let $z_0 \in \R^2$, $a \in \R$, and $b > b_0$ such that $(a, b) \neq z_0$.
Then, for $0 < \alpha < \alpha_b$ (i.e., $x_{max}^+ < x(\alpha)$), we have
\begin{equation}
I_1^{z_0}(a,b) + I_2^{z_0}(a,b) = \frac{1}{2i\pi} \int_{S^-_{x, \alpha} \cup \Gamma^-_{x,\alpha} \cup \Omega_{-,\alpha} \cup \Omega_{+,\alpha} \cup \Gamma^+_{x,\alpha} \cup S^+_{x, \alpha}} \Phi(x) e^{-a x - b Y^+(x)}\, dx.
\end{equation}

[Lemma 10 of arXiv:2606.26619, 'Ergodicity of stochastic reaction-diffusion equations on unbounded domains driven by space'] Assume that (S1)--(S3) and (H5) hold. Define
  \begin{align*}
    h_{-}(u):=
  \begin{cases}
        -\gamma u + \inf_{0\leq v\leq u}\big(b(v) - b(0) - C_{b,\theta}\big), & u\geq 0, \\
        - C_{b,\theta}, & u\leq 0,\\
  \end{cases}
  \end{align*}
where $\gamma > 2(2\nu)^2 G_{\sigma}^2$. Let $v_{-}$ be the unique solution to (\ref{260603.1828}) with $\tilde{b}=h_{-}$. If
\[
m >\frac{G_{\sigma}^2}{8},
\]
then
\begin{align*}
  \sup_{t\geq 0}\sup_{x\in\mathbb{R}}\mathbb{E}|v_{-}(t,x)|^2 <\infty.
\end{align*}

