body:
[Corollary 18 of arXiv:2607.16479, 'The Site Frequency Spectrum in an Exponentially-Growing Population with Selection'] The following hold:
\begin{itemize}
    \item $j(t)\gg\exp(t\lambda_0\lambda_1/(\lambda_0+\lambda_1))$ implies $S_{j(t)}(t)\to 0$ in $L^1$.
    \item $j(t)\sim C\exp(t\lambda_0\lambda_1/(\lambda_0+\lambda_1))$ implies:
    \[\lim_{t\to\infty}\mathbb{E}[S_{j(t)}(t)]=\frac{\lambda_1(av+\mu)}{(a+b)^2}C^{-\frac{\lambda_1+\lambda_0}{\lambda_1}}\left(\frac{a+b}{a+b-d}\right)^{\frac{\lambda_1+\lambda_0}{\lambda_1}}\Gamma(1+\lambda_0/\lambda_1).\]
    \item $j(t)\ll \exp(t\lambda_0\lambda_1/(\lambda_0+\lambda_1))$ implies
    \begin{align*}
        \lim_{t\to\infty}\mathbb{E}[e^{-\lambda_0 t}j(t)^{(\lambda_1+\lambda_0)/\lambda_1}S_{j(t)}(t)]=\begin{cases}
            \frac{\lambda_1(av+\mu)}{(a+b)^2}\left(\frac{a+b}{a+b-d}\right)^{\frac{\lambda_1+\lambda_0}{\lambda_1}}\Gamma(1+\lambda_0/\lambda_1) & \text{if }\lim_{t\to\infty}j(t)=\infty\\
            (av+\mu)I_\infty(N) & \text{if }\lim_{t\to\infty}j(t)=N,\,N<\infty
        \end{cases}
    \end{align*}
\end{itemize}

[Proposition prop:aveflowim of arXiv:2411.16572, 'Optimal decay of eigenvector overlap for non-Hermitian random matrices'] Fix small $n$--independent constants $\tau,\omega_*,\epsilon>0$, and for $i=1,2$ fix spectral parameters $\Lambda_{i,0}$ as in (equation eq:defincond of the paper), with $|z_{i,0}|\le 10$, $|\eta_{i,0}|\le \omega_*$. For $t\le T^*$ let $\Lambda_{i,t}$ be the solution of (equation eq:charflowmat of the paper) with initial condition $\Lambda_{i,0}$. Let $G_{i,t}:=(W_t-\Lambda_{i,t})^{-1}$, and let $\widehat{M}_{12,t}^A$ be the deterministic approximation of $\mathrm{Im}\, G_{1,t}A\mathrm{Im}\, G_{2,t}$ from (equation avlaw12_im of the paper). Let $\ell$ from (equation eq:defcontrolparam of the paper), and define the control parameter
	\begin{equation}

		\widehat{\gamma}=\widehat{\gamma}(\eta_1,z_1,\eta_2,z_2):=|z_1-z_2|^2+\rho_1|\eta_1|+\rho_2|\eta_2|+\left(\frac{\eta_1}{\rho_1}\right)^2+\left(\frac{\eta_2}{\rho_2}\right)^2, \qquad\quad \widehat{\gamma}_t:=\widehat{\gamma}(\eta_{1,t},z_{1,t},\eta_{2,t},z_{2,t}).
	\end{equation}
	Assume that for some small $0<\xi\le \epsilon/10$, with very high probability, it holds
	\begin{equation}
		\big|\big\langle\big(\mathrm{Im}\, G_{1,0}A_1\mathrm{Im}\, G_{2,0}-\widehat{M}_{12,0}^{A_1}\big)A_2\big\rangle\big|\le \frac{n^\xi\rho_{1,0}\rho_{2,0}}{\sqrt{n\ell_0}\widehat{\gamma}_0}\wedge \frac{n^\xi}{n|\eta_{1,0}\eta_{2,0}|}
	\end{equation}
	uniformly in $\lVert A_i\rVert\le 1$ and for any $|\eta_i|\in [|\eta_{i,0}|,n^{100}]$. Then,
	\begin{equation}
		\big|\langle (\mathrm{Im}\, G_{1,t}A_1\mathrm{Im}\, G_{2,t}-\widehat{M}_{12,t}^{A_1})A_2\rangle\big|\le \frac{n^{2\xi}\rho_{1,t}\rho_{2,t}}{\sqrt{n\ell_t}\widehat{\gamma}_t}\wedge \frac{n^{2\xi}}{n|\eta_{1,t}\eta_{2,t}|},
	\end{equation}
	with very high probability uniformly in $\lVert A_i\rVert\le 1$ and all $t\le T^*$ such that $n\ell_t\ge n^\epsilon$.

