body:
[Proposition bound on the norm of the limit of arXiv:2411.13062, 'Graphon-Theoretic Approach to Central Limit Theorems for $\epsilon$-Independence'] Let $w$ be a graphon and $\mu_w$ be the measure such that its odd moments vanish, and for any integer $p\ge 1$, we have
    \begin{align*}
        \int x^{2p}\, \text{d}\mu_w=\sum_{\pi \in P_2(2p)}\rho(f_\pi,w).
    \end{align*}
Denote
    \begin{align*}
        q:=\sup_{(x,y)\in [0,1]^2}w(x,y),
    \end{align*}
and let $\mu_q$ be the corresponding $q$-Gaussian law (equation eq: q-gaussian def of the paper). Then, for all integers $p\ge 1$, we have that  
\begin{align*}
        \int x^{p}\, \text{d}\mu_w \le \int x^{p}\, \text{d}\mu_q.
    \end{align*}
In particular, if $q<1$, then the measure $\mu_w$ is bounded and its support is contained in $[-2/\sqrt{1-q},2/\sqrt{1-q}]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop prob: lower bound on event E of arXiv:2411.16398, 'Large Deviations of Cover Time of Tori in Dimensions $d\geq 3$'] For all $\delta, \eta>0$, there exist $K_0(\eta), \varepsilon_0(\eta)>0$ such that the following holds. 
For all $K>K_0$ and $0<\varepsilon<\varepsilon_0$, there exists $M=M(K,\varepsilon)$ such that, 
    \begin{equation}

        \mathsf{P}(E)\geq \exp\Big(-(1+\eta)N^{d(1-\gamma)}\Big)
    \end{equation}
for sufficiently large $N$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 2 of arXiv:2605.27742, 'Multidimensional Stein's method for asymptotic independence with invariant measures of dif'] Assume that both Conditions~\ref{cdn1} and \ref{cdn2} are satisfied. Let
	$h : (l, u) \times \mathbb{R}^d \longrightarrow \mathbb{R}$ be a bounded $C^1$
	function with bounded partial derivatives. There exists a solution to \eqref{st1}
	which is bounded on $(l, u) \times \mathbb{R}^d$. It is given for every
	$y \in \mathbb{R}^d$ and $x \in (l, u)$ by:
	\begin{eqnarray}
		f_h (x, y) &=& \frac{2}{a(x) p(x)} \int_{l}^{x}
		\bigl(h(t, y) - \mathbf{E}[h(Z, y)]\bigr)\, p(t)\,\mathrm{d}t \\
		&=& \frac{2(1 - F(x))}{a(x) p(x)} \int_{l}^x \frac{\partial h}{\partial x}(w, y)
		F(w)\,\mathrm{d}w + \frac{2 F(x)}{a(x) p(x)} \int_x^{u}
		\frac{\partial h}{\partial x}(w, y)(1 - F(w))\,\mathrm{d}w,

	\end{eqnarray}
	where $F$ is the cumulative distribution function of $\mu$ and $Z \sim \mu$.
	Moreover, the following inequalities hold:
	\begin{equation}
		\sup_{(x, y) \in (l, u) \times \mathbb{R}^d} \big| f_h(x, y) \big|
		\leqslant \left\| \frac{\partial h}{\partial x} \right\|_{\infty},
		\qquad
		\max_{1 \leqslant j \leqslant d}\,\sup_{(x, y) \in (l, u) \times \mathbb{R}^d}
		\left| \frac{\partial f_h}{\partial y_j}(x, y) \right|
		\leqslant \frac{2}{a(\mu_m)\,p(\mu_m)}
		\left\| \frac{\partial h}{\partial y_j} \right\|_{\infty},
	\end{equation}
	where $\mu_m$ is the median of $\mu$, and there exists $C > 0$ (equal to
	$\| S \|_{\infty}$ with $S$ defined in Lemma~\ref{Lem:IngS}) such that
	\begin{equation}
		\sup_{(x, y) \in (l, u) \times \mathbb{R}^d}
		\left| \frac{\partial f_h}{\partial x}(x, y) \right|
		\leqslant C \left\| \frac{\partial h}{\partial x} \right\|_{\infty}.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 4 of arXiv:2604.13454, 'Invariant and periodic measures in classical spin systems on infinite lattices with highly'] A function $h:\ell_\rho^{2}(\mathbb{Z}^+) \rightarrow\mathbb{R}$ is called a cylinder function if there exists a finite subset $\Lambda\subset\mathbb{Z}^+$ and $g:\mathbb{R}^{\Lambda}\rightarrow\mathbb{R}$ such that $h(x)=g(\Pi_{\Lambda}x)$, for $x=(x_\gamma)_{\gamma\in\mathbb{\mathbb{Z}^+}}\in\ell_\rho^{2}(\mathbb{Z}^+)$, where $\Pi_{\Lambda}:\ell_\rho^{2}(\mathbb{Z}^+)\rightarrow\mathbb{R}^{\Lambda}$ is the restriction mapping, i.e. $\Pi_{\Lambda}x=(x_\gamma)_{\gamma\in\Lambda}\in\mathbb{R}^{\Lambda}$. Moreover,
		\begin{itemize}





			\item[(1)]If $g\in C^2(\mathbb{R}^{\Lambda},\mathbb{R})$, we say that $h\in C^{2,Cyl}(\ell_\rho^{2}(\mathbb{Z}^+))$;
			\item[(2)] If $g\in C^2_c(\mathbb{R}^{\Lambda},\mathbb{R})$, we say that $h\in C_{c}^{2,Cyl}(\ell_\rho^{2}(\mathbb{Z}^+) )$.
		\end{itemize}

[Lem 13 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] With the same notations as in Definition \ref{Definition de l'espace des disctri tempérées périodiques}, we have :
    \begin{equation*}
        \Hd\neq \{0\}\Longleftrightarrow \exists N\in \N^*, \m h=\frac{1}{2\pi N}\m .
    \end{equation*}
    In that case, $\Hd$ is finite dimensional with $\mathrm{dim}\pr{\Hd}=N^d$.
    Furthermore, $\Hd=\mathrm{Span}\left\{Q_k^{\A{1}}, \m k\in \disc{0}{N-1}^d\right\}$ where 
    \begin{equation}
        Q_k^{\A{1}}=\pr{\A{1}^{1
        /2}N}^{-d/2}\sum_{n\in \Z^d}\delta_{\A{1}^{-1/2}(n+k/N)}.

    \end{equation}
    and we will denote 
    \begin{equation}
        \mc{B}^{\alpha_1}=\pr{Q_k^{\A{1}}}_{k\in \disc{0}{N-1}^d}
    \end{equation}
    the basis given by the elements of \eqref{Basis vectors}.

