[Lemma 8 of arXiv:2605.17296, 'Zero correlations and averaged fields of orthonormal Gaussian Functions'] For every $z_0 \in \C$, 
\begin{equation*}
\bigl(X_n(z+z_0)\bigr)_{n\ge 0}
\inlaw 
\bigl(\lambda(z_0,z) X_n(z)\bigr)_{n\ge 0}, 
\end{equation*}
where 
$\lambda(z_0,z) = e^{- i \Im (z_0\bar z)}$.

[Theorem 20 (Foster--Lyapunov criterion for Joint Stability) of arXiv:2607.20838, 'Long-memory Markov chains with power-law intensities'] Suppose $ \{(X_n, c_n)\}_{n \in \mathbb{N}}$ is a $\psi$-irreducible Markov chain on the state-space $\mathcal{X} = \mathbb{R}_{\ge 0} \times [\gamma, \infty)$. If there exists a measurable function $V: \mathcal{X} \to [0, \infty)$, a petite set $C \subset \mathcal{X}$, and constants $\delta > 0$ and $b < \infty$ such that
	\begin{align}
		\mathbb{E}[V(X_{n+1}, c_{n+1}) \mid X_{n} = x, c_n = c ] - V(x, c) \leq - \delta + b \mathbbm{1}_{C}(x, c), 
	\end{align}
	then the Markov chain is positive Harris recurrent, and there exists a unique invariant probability measure $\pi$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 22 of arXiv:2609.00285, 'Multicrossing complex of knot and secant classes'] Let $K$ be  an oriented knot, $-K$ the reversed knot, and $\bar K$ the mirror knot. Then
\begin{enumerate}
    \item the multicrossing complexes for $-K$ and $\bar K$ are identified with the complex $(C_*(K,A), -d)$;
    \item the maps $\tau_n=(-1)^n id\colon C_n(K,A)\to C_n(K,A)$ define an isomorphism $\tau_*$ between $H_*(K,A)$ and $H_*(-K,A)=H_*(\bar K,A)$;
    \item for $A=\Z$, $\tau_*(\sigma_n(K))=\sigma_n(-K)=\sigma_n(\bar K)$, $n=3,4$, but $\tau_*(\sigma_2(K))=\sigma_2(-K)=-\sigma_2(\bar K)$.
\end{enumerate}

[Proposition 15 of arXiv:2607.17030, 'Stationary measures for log-gamma polymer on a strip and in half-space'] If $|u|<\alpha$, $v>-\alpha$ and $\alpha-u+2t_j>0$, $j=1,\dots N-1$, and $\alpha+v+2t_N>0$, then
\begin{multline}
     \GG_{t_1,\dots,t_N}(\alpha,u,v)
     =\Gamma(\alpha+v+2t_N) \Gamma(\alpha+u)^N \\ \cdot  \Biggl(\prod_{k=1}^{N-1}\Gamma(\alpha-u+2t_k)\Biggr)\, \EE [(1+\zeta_1+\zeta_1\zeta_2+\dots+\zeta_1\dots \zeta_{N-1})^{-u-v}]
     \end{multline}
with independent $\zeta_k\simeq \mathrm{Beta}_{II}(\alpha+u,\alpha-u+2t_{N-k})$, $k=1,\dots,N-1$.

    If $|v|<\alpha$, $u>-\alpha$ and $\alpha+v+2t_j>0$, $j=1,\dots,N$,  then
   \begin{multline}
     \GG_{t_1,\dots,t_N}(\alpha,u,v)
     =\Gamma(\alpha+u) \Gamma(\alpha-v)^{N-1} \\ \cdot   \Biggl(\prod_{k=1}^N \Gamma(\alpha+v+2t_k)\Biggr)\, \EE [(1+\xi_1+\xi_1\xi_2+\dots+\xi_1\dots\xi_{N-1})^{-u-v}]
     \end{multline}
with independent $\xi_k\simeq \mathrm{Beta}_{II}(\alpha+v+2 t_k,\alpha-v)$, $k=1,\dots,N-1$.

