[Theorem thm:RBM-multipoint of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The dressed observable $\mathcal{A}_{\mathbf{n}}$ satisfies
\begin{align}
\partial_t (\mathcal{A}_{\mathbf{n}+\mathbf{1}}
- \mathcal{A}_{\mathbf{n}})
- \tfrac{1}{2}\partial_{\mathbf{a}}^2(\mathcal{A}_{\mathbf{n}+\mathbf{1}}
+ \mathcal{A}_{\mathbf{n}})
- \partial_{\mathbf{a}}(\mathcal{A}_{\mathbf{n}}
  \mathcal{A}_{\mathbf{n}+\mathbf{1}})
+ \mathcal{A}_{\mathbf{n}+\mathbf{1}}
  \partial_{\mathbf{a}} \mathcal{A}_{\mathbf{n}+\mathbf{1}}
+ \partial_{\mathbf{a}} \mathcal{A}_{\mathbf{n}}
  \mathcal{A}_{\mathbf{n}} = 0.
\end{align}

[Lem 26 of arXiv:2506.20146, 'Parabolic Anderson Model in the Hyperbolic Space. Part I: Annealed Asymptotics'] Define the function $\Phi\triangleq\sum_{m}|\nabla\varphi_{m}|^{2}$
($\Phi$ is well-defined due to Condition (iii)). Then one has 
\begin{equation}
\lambda^{V-\Phi}(D)\leqslant\sup_{m}\lambda^{V}(D_{m}).
\end{equation}

[Lemma 23 (Exact mixed-degree formula) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] For $p,q\ge1$, $f\in H^{\odot p}$, and $g\in H^{\odot q}$,
\begin{equation}
 \Gamma(I_p(f),I_q(g))
 =\sum_{s=1}^{p\wedge q}c_{p,q,s}
 I_{p+q-2s}(f\wtensor_sg),

\end{equation}
where
\begin{equation}
 c_{p,q,s}
 =p(s-1)!\binom{p-1}{s-1}\binom{q-1}{s-1}.

\end{equation}
When $p=q=s$, the term in \eqref{hs:eq:mixed-gamma} is the constant
$q!\ip fg$.

[Lm Perm Expansion of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] For deterministic matrices $A_1,\dots ,A_j$, we have
    \begin{equation*}
        \mathbb{E}\left[\prod_{i=1}^{j}\theta(t_i)^T A_i \theta(t_i)\right] = \sum_{\pi \in \mathcal{P}_2(\{1,2\} \times [j])} \left(\prod_{i \in [j]} \frac{e^{-|t_i-t_{\sigma(i)}|}}{n}\right)\prod_{i=1}^{l}\mathrm{Tr}\left(A_{\sigma_i^{(1)}}\cdots A_{\sigma_i^{(|\sigma_i|)}}\right),
    \end{equation*}
    where $\sigma = \sigma_1\cdots \sigma_l = \mathrm{Perm}(\pi)$ in the sum above, and each cycle in the disjoint cycle decomposition can be written as $\sigma_i = (\sigma_i^{(0)}\cdots \sigma_i^{(|\sigma_i|)})$.

[Lem 13 of arXiv:2609.01358, 'Regularized spectral expansion of a Rankin--Selberg period and moments'] Let $\Phi=\otimes'_v\Phi_v$ be a factorizable Schwartz--Bruhat function. Let the vector $\varphi$ be a factorizable vector (in the above sense) in $\1_{n-2}\boxplus\pi$ or $\1_{n-2}\boxplus\chi\boxplus\chi^{-1}$, respectively, and let $\lambda\in\a^\ast_{\widetilde{\Q_{n-2}},\C}$. Then
		\optionA{\begin{equation*}
				\P(\lambda;\varphi,f,f_s)=\prod_v\P_v(\lambda;\varphi_v,f_v,f_{v,s}),
		\end{equation*}}
		\optionB{\begin{equation*}
				\P(s,\lambda;\varphi,\Phi)=\prod_v\P_v(s,\lambda;\varphi_v,\Phi_v),
			\end{equation*}
			\rn{If you see this, than maybe you need to change the proof below}}
		for sufficiently large $\Re(s)$.

