[Prop partition of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] Given a random set of good cubes $\mathcal{G}\subseteq \mathcal{T}$ satisfying (equation e:local_dependence of the paper), then for any cube ${\scaleobj{1}{\square}} \in \mathcal{G}$, there exists its local partition of good cubes denoted by $\mathcal{S}^{loc}_{\mathcal{G}}({\scaleobj{1}{\square}}) \subseteq \mathcal{G}$, such that the following properties hold:
		\begin{enumerate}
			\item All predecessors of elements of $\mathcal{S}^{loc}_{\mathcal{G}}({\scaleobj{1}{\square}})$ in ${\scaleobj{1}{\square}}$ are good: for every ${\scaleobj{1}{\square}}', {\scaleobj{1}{\square}}'' \in \mathcal{T}$, 
			\begin{align*}
				{\scaleobj{1}{\square}}' \in  \mathcal{S}^{loc}_{\mathcal{G}}({\scaleobj{1}{\square}}) \text{ and } {\scaleobj{1}{\square}}'  \subseteq {\scaleobj{1}{\square}}'' \subseteq {\scaleobj{1}{\square}}  \Longrightarrow {\scaleobj{1}{\square}}''  \in  \mathcal{G}.
			\end{align*}
			\item Neighboring elements of $\mathcal{S}^{loc}_{\mathcal{G}}({\scaleobj{1}{\square}})$ have comparable sizes: for every ${\scaleobj{1}{\square}}', {\scaleobj{1}{\square}}'' \in \mathcal{S}^{loc}_{\mathcal{G}}({\scaleobj{1}{\square}})$ such that $\operatorname{dist}({\scaleobj{1}{\square}}', {\scaleobj{1}{\square}}'')\leqslant 1$, we have
			\begin{equation}

				\frac{1}{3}\leqslant \frac{\size({\scaleobj{1}{\square}}'')}{\size({\scaleobj{1}{\square}}')}\leqslant 3.        
			\end{equation}
			\item Locality: the partition $\mathcal{S}^{loc}_{\mathcal{G}}({\scaleobj{1}{\square}})$ is $\mathcal{F}(3 {\scaleobj{1}{\square}})$-measurable.
			\item Estimate for the coarseness of $\mathcal{S}^{loc}_{\mathcal{G}}({\scaleobj{1}{\square}})$: if we also assume the tail event estimate (equation e:rarely_bad of the paper) for $\mathcal{G}$, then there exists a finite positive constant $C(K,s)$, such that for any ${\scaleobj{1}{\square}}$ and any $x \in {\scaleobj{1}{\square}}$, we have
			\begin{equation}

				 \mathbb{P}\left[\size({\scaleobj{1}{\square}}_{\mathcal{S}^{loc}_{\mathcal{G}}}(x)) \geqslant t\right] \leqslant \exp(-C^{-1}t^s),
			\end{equation}

			where we denote by ${\scaleobj{1}{\square}}_{\mathcal{S}^{loc}_{\mathcal{G}}}(x)$ the unique cube in partition $\mathcal{S}^{loc}_{\mathcal{G}}({\scaleobj{1}{\square}})$ containing $x$.
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm t:KPZ-to-landscape-reformulated of arXiv:2607.18194, 'Temperature chaos in directed polymers'] We have the following weak convergence
    of $C(\mathbb{R}^{4}_{\uparrow})$-valued random variables:
    \begin{align}
        \frac{2^{1/3}}{n^{1/3}}
        \left(
            \mathcal{H}^{\xi,(n)}(s,x;t,y)
            +
            \frac{(t-s)n}{24}
        \right) 
        \xrightarrow[n\to\infty]{d} \mathcal{L}(s,2^{-1/3}x; t, 2^{-1/3}y),
    \end{align}
    where $\mathcal{H}^{\xi,(n)}$ was defined in (equation e:def-Hn of the paper), and where $\mathcal{L}$ is the directed landscape (see (d:dl of the paper)). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:trees of arXiv:2411.07157, 'Rough differential equations in the flow approach'] We associate to any $\underline{\tau}  \in \boldsymbol{\mathfrak{T}}$, an \textit{order} ${\mathfrak{o}}(\underline{\tau}) \eqdef |E(\underline{\tau})|$, a \textit{size} $\mathfrak{s}(\underline{\tau}) \eqdef |N(\underline{\tau})| = |E(\underline{\tau})|+1$, and a \textit{scaling} $|\underline{\tau}|$ defined by
    \begin{equs}
        |\underline{\tau}|\eqdef -1+\mathfrak{s}(\underline{\tau})H\equiv -1+({\mathfrak{o}}(\underline{\tau})+1)H\,.
    \end{equs}
All these quantities are well-defined for elements of $\mathfrak{T}$ as well and we overload notation accordingly. 

For $k\in\N$, we denote by $\mathfrak{T}_{\leqslant k}$ the set of all trees $\tau\in\mathfrak{T}$ with ${\mathfrak{o}}(\tau)\leqslant k$, and let
\begin{equs}
    \mathcal{T}\eqdef\mathfrak{T}_{\leqslant 2}\equiv\Big\{ \raisebox{0ex}{\includegraphics[scale=1.2]{figures/Xi.pdf}},\raisebox{-0.5ex}{\includegraphics[scale=1.2]{figures/XiX.pdf}},\raisebox{-1ex}{\includegraphics[scale=1.2]{figures/Tree1.pdf}},\raisebox{-.5ex}{\includegraphics[scale=1.2]{figures/Tree2.pdf}}\Big\}\,,
\end{equs}    
where in the graphical representation for trees, we always draw the root as the bottom node. 

We also define 
\begin{equs}
    \mathcal{T}_*\eqdef \{\raisebox{+0.05ex}{\includegraphics[scale=1.5]{figures/Xi.pdf}}\}\cup
    \Bigg\{\tau\in\mathfrak{T}_{\leqslant5} :
\begin{array}{c}
\exists\, \underline{\tau}_1\in\tau_1\in\mathcal{T}\,,\;\underline{\tau}_2\in\tau_2\in\mathcal{T},\text{ and}\;n\in N(\underline{\tau}_1)\\
\text{such that}\;\underline{\tau}_2\graft_n\underline{\tau}_1\in\tau
\end{array}
    \Bigg\}\,.
\end{equs}
Observe that $\mathcal{T}\subset\mathcal{T}_*$ and
\begin{equs}
    \tau\in\mathcal{T}_*\setminus\mathcal{T}\Rightarrow{\mathfrak{o}}(\tau)\geqslant3\Rightarrow|\tau|\geqslant\delta\eqdef-1+4H>0\,.
\end{equs}

[Lem 143 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Fix $\gamma''>0,\gamma'''\in\mathbb R$. Let $\mu\in\mathbb R$, $\mathfrak H_{q,\gamma'',\gamma'''}$ be as in \eqref{approxG2} and let
  \begin{eqnarray}
 		X=\hat x+\frac{\mathfrak d q}{2\gamma''} (\mu \hat x+\gamma'' \hat x^2);
		\qquad
		Y={\hat y}.
  \end{eqnarray}
  Then,
  \begin{eqnarray}

    \frak H_{q,\gamma''+\mu q \md,\gamma'''+3\gamma'' q}(\hat x,{\hat y})=    \frak H_{0,\gamma'',\gamma'''}(X,Y)+\mathcal O(q \md^2+q^2\md).
  \end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

