[Lem balanced-identities of arXiv:2608.29018, 'Sharp Restricted Isometry Thresholds for\\ Global Minima of Rank-Restricted Matrix LASSO'] The quantities defined in ((eq:XYZ of the paper))
satisfy \begin{subequations}
\begin{align}
\mathsf{X}={} & t\vartheta\normtwo{A\sigma_{\mathrm{head}}}^{2}+2\alpha\beta t(2-t)\ip{A\sigma_{\mathrm{head}}}{A\sigma},\\
\mathsf{Y}={} & t^{2}\normtwo{A\sigma_{\mathrm{head}}}^{2}\qquad\text{for }0<t<1,\\
\mathsf{Z}={} & t(4-3t)\normtwo{A\sigma_{\mathrm{head}}}^{2}\nonumber \\[-1mm]
 & +2t(t-1)\ip{A\sigma_{\mathrm{head}}}{A\sigma}\qquad\text{for }1\le t<4/3.
\end{align}
\end{subequations} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lem144 of arXiv:2609.02795, 'Global smooth behavior in Kuznetsov and Westervelt type\\ viscous wave equations:\\ A unif'] Assume ((h of the paper)), ((f0 of the paper)) and ((f1 of the paper)) with some $\lambda>1$, let $p\ge 2$ be such that $p>n$, 
  and let $r\ge p$ satisfy $r\ge 2\lambda$.
  Then there exist $\Gamma_9=\Gamma_9(p,r,a,h,f)>0$ and
  $\mu_3=\mu_3(h,f)>1$ such that whenever ((init of the paper)) holds and $T\in (0,T_{max}]$ is such that ((uut of the paper)) is satisfied
  with $\delta_1=\delta_1(h)$ as in Lemma (lem11 of the paper), it follows that
  \begin{eqnarray}\label{144.1}
	\int_\Omega |\nabla v|^{p-2} f^2(u,u_t,\nabla u,\nabla u_t)
	&\le& \Gamma_9 \cdot \bigg\{ \int_\Omega |\nabla u|^r \bigg\}^\frac{p}{r}
	+ \Gamma_9 \cdot \bigg\{ \int_\Omega |\nabla v|^r \bigg\}^\frac{p}{r} \nonumber\\
	& & + \Gamma_9 \int_\Omega |\nabla v|^{p-2+2\lambda}
	+ \Gamma_9 \|\nabla u\|_{L^r(\Omega)}^{2\lambda} \|\nabla v\|_{L^\frac{(p-2)r}{r-2\lambda}(\Omega)}^{p-2} \nonumber\\
	& & + \Gamma_9 \cdot \bigg\{ \int_\Omega |\nabla u|^r \bigg\}^{\frac{p}{r}\cdot\mu_3}
	+ \Gamma_9 \cdot \bigg\{ \int_\Omega |\nabla v|^p \bigg\}^{\mu_3}
  \end{eqnarray}
  for all $t\in (0,T)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 22 of arXiv:2605.31471, 'Convergence Rates of Continuous-Time Random Walks to Time-Fractional Diffusions with Unbou'] Let Assumption~\ref{asm:classical} hold. Let $L$ be the generator of the diffusion
        corresponding to \eqref{eq:SDE-flow}, acting on $f\in D_2$ by
        \[
            Lf(x)  = \nabla f(x)[b(x)] + \frac12 \sum_{l=1}^d \DD^2 f(x)\bigl[\sigma_l(x),\sigma_l(x)\bigr].
        \]
        Then for a constant $l = 2 K + d K^2 > 0$ and for all  $f \in D_2$,
        \begin{equation} 
            \|Lf\|_V \;\le\; l \,\|f\|_2.
        \end{equation}
        Furthermore, if $f \in D_4$, then there exists a constant $l' = l'(K,d) >0$ such that
        \begin{equation} 
            \|L^2 f\|_W \;\le\; l' \,\|f\|_4.
        \end{equation}

