body:
[Lemma 35 of arXiv:2604.00630, 'The contact process on a bipartite spatial network'] If~$(\gamma_1,\gamma_2,a) \in \mathcal S \times (0,\infty)$ with~$\gamma_2 > 1/2$, then
	\begin{equation*}
		f_{\mathsf D}(\gamma_1,\gamma_2,\tfrac{\bar{\gamma}_2}{\Delta_2}) \begin{cases}
			> \tfrac{\gamma_2}{\Delta_2} &\text{if } \gamma_1 \in (\bar{\gamma}_2, \kappa(\gamma_2));\\[.2cm]
			= \tfrac{\gamma_2}{\Delta_2} &\text{if } \gamma_1  = \kappa({\gamma}_2);\\[.2cm]
			< \tfrac{\gamma_2}{\Delta_2} &\text{if } \gamma_1  \in (\kappa({\gamma}_2),1).
		\end{cases}
	\end{equation*}

[Theo 1 (Monotonicity theorem for the $H^{2|2}$ model) of arXiv:2603.25536, 'The $H^{2|2}$ monotonicity theorem revisited'] Fix an integer $N\geq 1$, consider the vertex set $V=\{1,\dots,N,\delta\}$ with a root vertex $\delta$, unoriented edges $(ij)=(ji)$ for $i,j\in V$, and symmetric positive edge weights $W_{ij}=W_{ji}>0$ for $i,j\in V$. Define
\begin{equation}
    \mathcal{D}_W(t_1,\dots,t_N)=\sum_{T\in\mathcal{T}}\prod_{(ij)\in T}W_{ij}e^{t_i+t_j}
\end{equation}
for $t=(t_1,\dots,t_N)$ and $t_{\delta}=0$, where the sum is over the spanning trees $\mathcal{T}$ of the complete graph over $\{1,\dots,N,\delta\}$. Consider the effective $H^{2|2}$ action functional
\begin{equation*}
    S^W_{\text{eff}}(t)=\frac{1}{2}\sum_{i,j\in V}W_{ij}(\cosh(t_i-t_j)-1)-\frac{1}{2}\left(\ln \mathcal{D}_{W}(t_1,\dots,t_N)-2\sum_{i=1}^{N}t_i\right).
\end{equation*}
Then for fixed $p_1,\dots,p_N>0$, the integral
\begin{equation*}
    K=\int_{\mathbb{R}^{N}}f\left(\sum_{i=1}^{N}p_ie^{t_i}\right)e^{-S^W_{\text{eff}}(t)}dt_1\cdots dt_{N}
\end{equation*}
is non-increasing in each of the $(W_{ij})_{i,j\in\{1,\dots,N,\delta\}}$ if $f:\mathbb{R}\to\mathbb{R}$ is convex. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:unique of arXiv:2607.05671, 'Bi-infinite systems of singularly interacting Brownian particles and the KPZ equation'] Fix $\gamma \in \mathcal{P}_0(\mathbb{R}^{\mathbb{Z}})$, and let $x = \{x_i\}_{i \in \mathbb{Z}} \sim \gamma$. Assume that, $\gamma$-almost surely,  
\begin{equation} 
\limsup_{M \to \infty} \frac{-x_{-M}}{\sqrt{M}} = \infty.
\end{equation}
Consider the following condition on the local times for some solution $(X,L)$ of (equation eq:asym_eq of the paper):
\begin{equation} 
\forall T \in [0,\infty), \quad \limsup_{M \to \infty} \left(\frac{q}{p}\right)^{-M} L_{(-M,-M+1)}(T) = 0 \text{ a.s.}
\end{equation}
Then, solutions to (equation eq:asym_eq of the paper) are pathwise unique for parameter $p$ and initial distribution $\gamma$, among all solutions whose associated local times satisfy (equation eq:aloc of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:two-large-position of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] If $m\ge40$, then
\begin{equation}
  \kappa\le\floor*{\frac{3m}{2}}+\mu(d)+2\mu(\kappa),
  \qquad 1\le d<\frac\kappa2.
\end{equation}
Moreover
\begin{equation}
  \kappa\le3m,
\end{equation}
and, setting $\Pi_m=\floor{5m/2}+1$,
\begin{equation}
  p=\kappa-d-1\le \Pi_m.
\end{equation}

[Defn def:manfence of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] A $3$-manifold with annular boundary fences and boundary windows, or \textbf{manifold with fences and windows} for simplicity, is a manifold with boundary and (concave) corners $M_{\mathord{\scalebox{0.45}{$\square$}}}$ of the form $\overline{M \setminus N}$, where $M$ is a usual $3$-manifold with boundary (and without corners), and $N$ is a disjoint union of codimension-$0$ submanifolds with boundary and corners, disjoint from $\partial M$, and diffeomorphic to $S^1 \times I \times I$. It also comes with the data of \textbf{windows} which are subsets of $\partial M_{\mathord{\scalebox{0.45}{$\square$}}}$ two types: 
    \begin{itemize}
        \item A \textbf{square window} is a smoothly embedded squares $I \times I$ inside a component of $\partial M_{\mathord{\scalebox{0.45}{$\square$}}}$ which is not a fence,
        \item A \textbf{toroidal window} is a an entire boundary component of $\partial M_{\mathord{\scalebox{0.45}{$\square$}}}$ which is not a fence.
    \end{itemize}
    Moreover, we require that the windows are pairwise disjoint.

[Lemma 9 (Computation of $q(\pi_p\otimes\tilde\chi)$) of arXiv:2609.04155, 'The subconvexity problem for symmetric square\\ $L$-functions in Level aspect'] Let $\pi\simeq\bigotimes_\nu^\prime\pi_\nu$ be as usual. Then
		\begin{itemize}
			\item If $\pi_{p}$ is a principal series representation, then for all but at most two primitive characters $q(\pi\otimes\tilde\chi)=p^2$, and for those two exceptional characters $q(\pi\otimes\tilde\chi)=p$.
			\item If $\pi_{p}$ is twist minimal supercuspidal representation then $q(\pi\otimes\tilde\chi)=p^2$.
		\end{itemize}

[Cor cA3 of arXiv:2504.07255, 'A Tail-Respecting Splitting Numerical Scheme\\ for L\'evy-Driven SDEs With Superlinear Dri'] For any $q\in (0,p)$
\begin{equation}\begin{aligned}
\sup_{t\in[t_k, t_{k+1})} \mathbf{E}^{(N)}_{t_1,\dots,t_N}\Big[\|\Delta_t^n\|^q\Big|\mathcal{F}_{t_k}\Big]
\leq_C \|\Delta_{t_k}^n\|^q
& + h_n^{(\frac{p-q}{\chi}\wedge q) + (1\wedge\frac{q}{2})}(1+\|X_{t_k}^{(n)}\|^p)
+ h_n^{\frac{p-q}{\chi}\wedge q}(1+\|X_{t_k}^n\|^{p})\\
&+ h_n^{1\wedge\frac{q}{2}}  (U_{t_k}^n)^q
+h_n^{(\frac{p-q}{\chi }\wedge q)   +(1\wedge\frac{q}{2})} (U_{t_k}^n)^{(p-q)\wedge (q\chi)}
+h_n^{1\wedge\frac{q}{2}}
\end{aligned}\end{equation}
for $n$ large enough uniformly over
$N\in\mathbb{N}_0$, partitions $\{t_1,\dots, t_N\}$,  and $k=0, \dots, N$.

