[Lemma 30 of arXiv:2608.27374, '\Large \bf Distribution-constrained optimal multiple stopping: the Root-type solution'] Assume that \(\sigma^\xi\) is a finite iterated lower-barrier time and
\(\P\left(\sigma^\xi>0\right)=1\).  Then
\[
    \tau_b=\tau_b^{<}
    \qquad\text{a.s.}
\]

[Defi def:genDirichlet of arXiv:2602.17579, 'Non-equilibrium functional inequalities for finite Markov chains'] Let $\zeta\in \mathcal{P}_+(\ensuremath{\mathbb{Z}})$. For any $f\in \ensuremath{\mathbb{R}}^{|\ensuremath{\mathbb{Z}}|}$ we define the \emph{generalised Dirichlet form} with respect to $\zeta$  as 
\begin{equation}
    \mathscr{E}_\zeta(f,M) 
    \coloneqq  \mfrac12 \sum_{z,z'\in\ensuremath{\mathbb{Z}}} M(z,z')\zeta(z)\bigl(f(z)-f(z')\bigr)^2 
    =  (f,-Mf)_\zeta + \mfrac12(1,Mf^2)_\zeta.
\end{equation}
For any $\varphi\in \mathcal D_\zeta(\ensuremath{\mathbb{Z}})$ (defined in~(equation def:SpaceDen of the paper)) we define the \emph{generalised Fisher information} with respect to $\zeta$ as 
\begin{equation}
    \mathscr{R}_\zeta(\varphi,M) \coloneqq 
    \sum_{z,z'\in \ensuremath{\mathbb{Z}}} M(z,z')\zeta(z) \varphi(z) \biggl[ \frac{\varphi(z')}{\varphi(z)} - 1 -\log\biggl(\frac{\varphi(z')}{\varphi(z)}\biggr)\biggr]. 
\end{equation}

[Proposition p:moment setting of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $p\in[-d, \infty)$. Suppose that $\Phi$ is a locally absolutely square-integrable invariant random complex measure, and suppose that $K,L$ are invariant transport kernels. Assume that $K,\Phi$ and $L,\Phi$ either both fulfill Condition~(c:condition square-integrable general with p of the paper) or both fulfill Condition~(c:condition square-integrable Markov with p of the paper).
    Further, assume that 
    \begin{equation}
        \int x^{\otimes q}\, (K_y-L_y)(dx) = 0,\quad q\in\N_0, q<\max(\tfrac{d+p}{2}, 1), y\in\R^d.
    \end{equation}
    Then $K\Phi$ is (beyond) $p$-uniform iff $L\Phi$ is (beyond) $p$-uniform.

    In particular, if $L$ is deterministic, e.g., $L_0:=\BE_0^\Phi[K_0]$ when $\Phi$ is nonnegative, then $K\Phi$ is (beyond) $p$-uniform if $\Phi$ is (beyond) $p$-uniform. The converse holds if $L_0(\R^d)\neq 0$.
    \begin{proof}
        By assumption, the invariant transport kernel $\tilde{K}:=K-L$, together with $\Phi$, fulfills Condition~(c:condition square-integrable general with p of the paper) or Condition~(c:condition square-integrable Markov with p of the paper). Further, using the Cauchy-Schwarz inequality
        \begin{equation}
            \BV[K\Phi(f)] = \BV[\tilde{K}\Phi(f) + L\Phi(f)] \leq 2 \BV[\tilde{K}\Phi(f)] + 2 \BV[L\Phi(f)]
        \end{equation}
        for some bounded $f:\R^d\to\C$ with compact support, and vice versa. Hence, if $\tilde{K}\Phi$ is (beyond) $p$-uniform, then $K\Phi$ is (beyond) $p$-uniform iff $L\Phi$ is (beyond) $p$-uniform. We define $\Psi_q$ as in~(equation e:Psi_q definition of the paper) with respect to $\tilde{K}$ and $\Phi$. Then, by~(equation e:markov difference 0 of the paper), $\Psi_q=0$ for $q\in\N_0, q < \max(\frac{d+p}{2}, 1)$, whereby $\Psi_q$ trivially is $\infty$-uniform. Hence, an application of Theorem~(t:main theorem of the paper) concludes the first part of the proof. The second part then follows from the first, as if $L$ is deterministic, then $L\Phi$ inherits its $p$-uniformity from $\Phi$, and if further $L_0(\R^d)\neq0$, then $\Phi$ also inherits $p$-uniformity from $L\Phi$. See~[Klatt_Last_Lotz_Yogeshwaran_2025] for the case that $L_0$ is a probability measure, which can be directly generalized to the case that $L_0(\R^d)\neq0$.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 (One-coordinate posterior risk) of arXiv:2608.25706, 'Fast rates in Bayesian online learning with approximate posteriors'] \label[lemma]{lem:coordinate-risk}
Under \cref{ass:sequence_model}, there is an absolute constant $C>0$ such that
    \begin{equation}
    \E\sbr{\left.\int(\theta-\theta^\star_j)^2\Pi_{t,j}(\d\theta)\right| N_{t,j}}
    \le C \cbr{\frac1{\kappa_j+N_{t,j}}
    +\frac{\kappa_j^2(\theta^\star_j)^2}{(\kappa_j+N_{t,j})^2}}
    \end{equation}
for any $j\in \bN$ and $t\in \bN$.

