[Theorem 16 (Doob's optional stopping version I, supermartingale $\{f_j \equiv \overline{\sigma}_j f\}$) of arXiv:2606.17452, 'Optional Stopping for Superhedging Supermartingales'] \hspace{.1in}

\noindent
Let $f \in Q$, $\rho \leq \tau$ be two stopping times and set $f_j = \overline{\sigma}_j f$, $j \geq 0$. Then
\begin{enumerate}
\item
\begin{equation} \nonumber
\overline{\sigma}_{\rho} f^{\tau}_k \leq f^{\rho}_k\;\;\mbox{for all}\;\; k \geq 0.
\end{equation}

\item 
\begin{equation} \nonumber
\overline{\sigma}_{\rho} f_{\tau} \leq f_{\rho}~\mbox{on}~\mathcal{S}.
\end{equation}
\end{enumerate}

