[Lemma Ptdef of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] [dgauss1]

For $t >0$, there exists polynomial $P_t$ of degree at most $t$ such that for $x \in (0,3]$,
\begin{align}
	\frac{1}{x} = \int_0^\infty t^2 P_t (\lambda) \frac{{\rm d} t}{t}
	.
\end{align}
For $t < 1$, $P_t (x) = c / t$ for some constant $c>0$ and for $t \ge 1$,  the polynomials satisfy
\begin{align}
	0\le P_t (x) & \le C e^{-c(x t^2)^{1/4}} .   
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm-MCG lens spaces of arXiv:2609.00233, 'A survey on mapping class groups of 3-manifolds'] The group $\pi_{0}\Diff(L(p,q))$ for $p\geq 2$ is isomorphic to:
    \begin{enumerate}[(a)]
        \item $\mathbb{Z}/2$, generated by $\tau$, if $q^{2} \not\equiv \pm 1 \mod{p}$;
        \item $\mathbb{Z}/2 \oplus \mathbb{Z}/2$, generated by $\tau$ and $\sigma_{+}$, if $q^{2} \equiv 1 \mod{p}$ and $q \not\equiv \pm 1 \mod{p}$;
        \item $\mathbb{Z}/2$, generated by $\tau$, if $q \equiv \pm 1 \mod{p}$ and $p\neq 2$;
        \item $\mathbb{Z}/4$, generated by $\sigma_{-}$, if $q^{2} \equiv -1 \mod{p}$ and $p \neq 2$;
        \item $\mathbb{Z}/2$, generated by $\sigma_{-}$, if $p=2$.
    \end{enumerate}
    In each case the orientation-preserving subgroup $\pi_{0}\Diff^+(L(p,q))$ is the subgroup generated by $\tau$ and $\sigma_+$.  Thus
    $\pi_{0}\Diff^+(L(p,q)) = \pi_{0}\Diff(L(p,q))$ in cases (equation lens-space-case-a of the paper), (equation lens-space-case-b of the paper), and (equation lens-space-case-c of the paper), while $\pi_{0}\Diff^+(L(p,q)) \cong \mathbb Z/2$ in case (equation lens-space-case-d of the paper) and $\pi_{0}\Diff^+(L(2,1)) \cong \pi_{0}\Diff^+(\mathbb{RP}^3) = \{0\}$ in case (equation lens-space-case-e of the paper).

