body:
[Proposition 8 of arXiv:2607.17396, '2607.17396'] Under the assumptions of Theorem 1,
\begin{equation}
\bigl\{Y_{n}^{(1)}(t),\, t \ge 0 \bigr\}
\mathop{\to}\limits^{\mathcal{D}}
\bigl\{\widetilde{Y}(t),\, t\ge 0 \bigr\}, \ \ n\to \infty,
\end{equation}
where the limit process $\{\widetilde{Y}(t),\, t \ge 0\}$ is the pathwise unique strong solution of the SDE
\begin{equation}
\mathrm{d}\widetilde{Y}(t)=\lambda\,\mathrm{d}t+\sigma\sqrt{\widetilde{Y}(t)^{+}}\,\mathrm{d}W(t),
\qquad t \ge 0,
\end{equation}
with initial condition $Y(0)=0$.

[Theorem main of arXiv:2412.00865, 'On the spectral problem and fractional diffusion limit for Fokker-Planck with(-out) drift '] \item Assume (a1 of the paper)-(a2 of the paper).  Let  $\alpha := (\beta-d+2)/3$,  and let $\eta_0>0$ and  $\lambda_0>0$ small enough.  Then, for all $\eta\in [0,\eta_0]$,  there exists a unique eigen-couple $\big(\mu(\eta),M_\eta\big)$ in $\{\mu\in \mathbb C, |\mu|\leqslant \eta^{\frac{2}{3}}\lambda_0\}\times L^2(\mathbb{R}^d,\mathbb{C})$, solution to the spectral problem 
\begin{equation}
\mathcal{L}_\eta(M_{\mu,\eta})(v)=\big[-\Delta_v +W(v) + \mathrm{i} \eta v_1 \big] M_{\mu,\eta} (v)= \mu M_{\mu,\eta}(v) , \quad  v\in \mathbb{R}^d .
\end{equation}
Moreover,  \smallskip

\noindent 1.  the eigenfunction $M_\eta$ converges to the equilibrium $M$ in $L^2(\mathbb{R}^d,\mathbb{C})$ when $\eta$ goes to $0$.  \smallskip

\noindent 2.  If furthermore we assume (a3 of the paper) and (a5 of the paper) then, the  eigenvalue $\mu(\eta)$ satisfies
 \begin{equation}
\mu(\eta) - \mathrm{i} \eta  j^\vare_1 = \kappa \eta^\alpha \big(1+O(\eta^{\alpha})\big) ,
\end{equation}
where $j^\vare_1$ is defined in (equation def eta, j-1,v-1 of the paper)




and $\kappa$ is a positive constant given by 
\begin{equation}
\kappa := - \int_{\{|s_1|>0\}} s_1 m(s) \mathrm{Im} H_0(s)  \mathrm{d} s ,
\end{equation}
and where $H_0$ is the unique solution to  
\begin{equation}
- \frac{1}{m} \nabla_s \cdot \bigg(m^2 \ \nabla_s\bigg(\frac{H_0}{m}\bigg)\bigg) + \mathrm{i} s_1 H_0 = 0 , \quad  \  s \in\mathbb{R}^d\setminus\{0\}  ,
\end{equation}
satisfying \begin{equation}
\int_{\{|s_1|\geqslant 1\}}|H_0(s)|^2\mathrm{d}s <+\infty \qquad  \mbox{ and } \qquad   H_0(s)\underset{0}{\sim} m(s).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:discrete-kac-counterexample of arXiv:2604.04882, 'On a Problem of M. Kac on Laplace Distributions'] Fix $\lambda>0$ and $\theta\in(0,1/2)$. Then the functions
    \begin{align}
        G_1(z)\coloneqq \frac12+\frac{1}{2\bigl(1+\theta\lambda(1-z)\bigr)},
        \qquad
        G_2(z)\coloneqq \frac{2+\theta\lambda(1-z)}
        {2+2\lambda(1-z)+\theta\lambda^2(1-z)^2}.
    \end{align}
    are probability generating functions satisfying
    \begin{align}
        \Phi(G_1(z),G_2(z))=\frac{1}{1+\lambda(1-z)},
        \qquad
        \Phi(x,y)\coloneqq \frac{1}{x^{-1}+y^{-1}-1},
    \end{align}
    but neither $G_1$ nor $G_2$ is of the form $(1+\mu(1-z))^{-1}$.

