[Theorem 17 of arXiv:2608.30752, '2608.30752'] Under Assumption~\ref{assump:-covering},
\begin{equation}
  \frac{\eta_Y}{2}e^{2d_{\mathrm T}(X,Y)}
  \le
  E_{u_0}(X)
  \le
  A_Ye^{2d_{\mathrm T}(X,Y)}

\end{equation}
for every $X\in\mathcal T(\Sigma)$. Equivalently,
\begin{equation}
  \frac12\log E_{u_0}(X)
  =
  d_{\mathrm T}(X,Y)+O_Y(1).

\end{equation}
More explicitly,
\begin{equation}
  d_{\mathrm T}(X,Y)+\frac12\log\frac{\eta_Y}{2}
  \le
  \frac12\log E_{u_0}(X)
  \le
  d_{\mathrm T}(X,Y)+\frac12\log A_Y.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 8 (Variance bound on a finite chaos) of arXiv:2604.27242, 'Statistical Inference for Homogenization Limits Driven by Wiener or Hermite Processes'] Let \(\delta(\varepsilon)>0\) be such that \(\delta(\varepsilon)\xrightarrow{\varepsilon\to 0} 0\) and \(\varepsilon/\delta\to 0\) as \(\varepsilon\to 0\). For \(\varepsilon\) small enough,
\[
\mathrm{Var}(C_{\varepsilon, \delta}) \;\lesssim\;
\begin{cases}
\delta^{2(2-2H)\wedge 1}, & H^*(m)>1/2,\\[0.6em]
\delta + \varepsilon^{2(2-2H)}, & H^*(m)<1/2,
\end{cases}
\]
with implicit constants depending only on \(H, m, G\). In both regimes \(\mathrm{Var}(C_{\varepsilon,\delta})\to 0\) as \(\varepsilon\to 0\), so that \(C_{\varepsilon,\delta}\to \mathbb{E}[C_{\varepsilon,\delta}]\) in \(L^2\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem dualityext of arXiv:2605.06488, 'Continuous-state branching processes with L\'evy-Khintchine drift-interaction: Laplace dua'] Under the convention $0^+\cdot \infty, \infty^{-}\cdot 0$, we have for all $x, y\in [0,\infty]$,
    \begin{equation}
        \mathbb{E}_x\left[e^{-X_t^{\mathrm{e}\infty}y}\right]=\mathbb{E}^{y}\left[e^{-xY_t^{\mathrm{m}}}\right], \qquad \forall t\geq 0.
    \end{equation}

[Lemma 15 of arXiv:2608.10515, 'Limiting Law of Local Fields for the Mean Field Ghatak-Sherrington Model'] Under the same conditions as in Proposition~\ref{prop:ratio}, we have
\begin{equation}
  \E\left[\E_\xi\left[U(\xi+\gamma)
  \left(\frac{W(\beta_-(\xi+\gamma)+h)}{\Wtil(\beta\gamma+h)}
  -\frac{W(\beta(\xi+\gamma)+h)}{\Wtil(\beta\gamma+h)}\right)\right]\right]^{2k}\le \frac{K}{N^k}.
\end{equation}

[Proposition prop.GreenEstimateDeg2 of arXiv:2606.13442, 'Scaling limit of additive functionals for reversible non-gradient exclusion process: criti'] We have the following estimates for the Green function $\overline{G}_\lambda$.
		\begin{enumerate}
			\item 
			The $L^2$ norm of $\overline{G}_\lambda$ is of order $\lambda^{-1}$:
			\begin{equation*}
				\norm{\overline{G}_\lambda}_{L^2}^2=O(\lambda^{-1}).
			\end{equation*}
			\item 
			The Dirichlet form of $\overline{G}_\lambda$ is of order $\log(\lambda^{-1})$:
			\begin{equation*}
				\expec{\overline{G}_\lambda,-{\overbracket[1pt][-1pt]{\mathcal{L}}}\overline{G}_\lambda}=\tfrac{\chi(\rho)^2}{2\pi\mathbf{D}(\rho)}\log(\lambda^{-1})+O(1).
			\end{equation*}
			\item 
			The $H^{2}$ norm of $\overline{G}_\lambda$ is uniformly bounded with respect to $\lambda\in(0,1)$:
			\begin{equation*}
				\expec{-{\overbracket[1pt][-1pt]{\mathcal{L}}}\overline{G}_\lambda,-{\overbracket[1pt][-1pt]{\mathcal{L}}}\overline{G}_\lambda}=O(1).
			\end{equation*}
		\end{enumerate}

