[Theorem 5 of arXiv:2608.30638, 'On compact steady pluriclosed soliton surfaces'] Let $M$ be a Hopf surface, then $\pi_1(M)$ contains a cyclic subgroup $\langle \gamma\rangle$ with finite index. The action of $\gamma$ on $\mathbb C^2\setminus\{(0,0)\}$ under some holomorphic coordinate can be written as 
    \begin{equation}
        (z_1,z_2)\mapsto (\alpha z_1+\lambda z_2^m,\beta z_2)
    \end{equation}
    for $\alpha,\beta,\lambda\in\mathbb C$ and $m\in\mathbb N$ such that $0<\vert\alpha\vert\leq\vert\beta\vert<1$ and $\lambda\cdot(\alpha-\beta^m)=0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lm:claim of arXiv:2606.12143, 'Continuous stochastic flows driven by white noise and their duals'] The quadratic covariation of $M$ and $N(\phi)$ satisfies
	\begin{align}
		\langle M, N(\phi) \rangle_x = \int_r^x \!\! \int_{{\mathbb R}} \sigma(X(u), u, s)\, \phi(u, s) \, \ensuremath{\mathrm{d}} s \ensuremath{\mathrm{d}} u.
	\end{align}

[Proposition 45 of arXiv:2608.27307, '2608.27307'] Under Assumptions~\ref{ass:basic} and~\ref{ass:rand_ent}, suppose that $E_{+,0}$ is a regular right edge for $\Pi_0$ in the sense of Definition~\ref{def:reg_r_edge}. Then the rightmost edge $E_{+,0}$ of $\bnu_0$ is a regular right edge. Moreover,
        \begin{align}
                \abs{E_{+,0}-E_+}\lesssim t, \qquad c_{{\rm edge},0}\sim1, \qquad \gamma_{+,0}:=(\pi c_{{\rm edge},0})^{2/3}\sim1, \nonumber
        \end{align}
        and the constants in Proposition~\ref{prop:sqrt_edge} and Theorem~\ref{thm:opt_ll} may be chosen uniformly for $Y_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:X:scale of arXiv:2506.15949, 'On the passage times of self-similar Gaussian processes on curved boundaries'] Thanks to (equation cond:gamma of the paper), the Gaussian process $X$ in (equation X(t) of the paper)
	is $\alpha$-self similar for
	\begin{align}
		\alpha =  1 - \frac12\left( \nu + \frac{\beta}{\gamma}\right).
	\end{align}

[Proposition 5 of arXiv:2607.09575, 'Probabilistic estimates for a system of\\noisy integrate-and-fire neurons'] Define the transformation $\Upsilon \in \mathcal{C}^{1,\,2}\left([0,\,T]\times\R\right)$ by
	\begin{equation*}
		(t,\,x) \mapsto \Upsilon_t(x) \coloneqq \int_0^x\frac{\diff{y}}{\sigma(t,y)}.
	\end{equation*}
	Fixing an arbitrary index $i \in \{1,\,\ldots,\,N\}$, then 
	\begin{equation*}
		\diff\Upsilon_t\left(X_t^i\right) = \hat{b}_t^i \ind_{\{\Upsilon_t\left(X_t^i\right) < 0\}}\diff{t} + \ind_{\{\Upsilon_t\left(X_t^i\right) < 0\}} \diff{B_t^i} + \diff\sum_{k \ge 1} \Upsilon_{\tau_k^i + \varsigma_k^i}(-\xi_k^i)\ind_{[0,t]}(\tau_k^i + \varsigma_k^i),
	\end{equation*}
	where $B^i$ is a Brownian motion and the (stochastic) drift $\hat{b}_t^{i}$ satisfies the growth condition
	\begin{equation}
		\nnorm{\hat{b}_t^{i}} \le C_{b,\sigma,\mathfrak{K}} \left(1 + \nnnorm{X_t^i} + \langle\nu_t^N,\nnnorm{\cdot}\rangle + \nnnorm{{F}_t^{N}}\right).
	\end{equation}
	Furthermore, the transformed process $\Upsilon_t\left(X_t^i\right)$ satisfies
	\begin{equation}
		\operatorname{sgn}\left(\Upsilon_t\left(X_t^i\right)\right) = \operatorname{sgn}\left(X_t^i\right) \quad \text{and} \quad \nnnorm{\Upsilon_t\left(X_t^i\right)} \le C\nnnorm{X_t^i}.
	\end{equation}

