[Lemma lem-G-aux of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] Assume that the map $G$ satisfies assumptions (G1-2) and the following modification of (G3):
\begin{trivlist}
\item[(G3)']
There exists  a constant $C_3^\prime>0$ such that
\begin{align}

    \int_{Y} \normb{G(t,y)u }{U^\prime}{2} \, \nu (\mathrm{d} y) &\leq  {C}_{3}^\prime  \normb{u }{U^\prime}{2}, \;  u \in U^\prime , \; t \in [0,T].
\end{align}
\end{trivlist}
Then
\begin{trivlist}
\item[(G5)'] the linear map
\begin{align*}
\textbf{G}\colon  \mathscr{Z}_T
\ni u \mapsto  \bigl\{  [0,T] \times Y \ni (t,y) & \mapsto      G(t,y)u(t) \inU^\prime \bigr\} \\
&\in {L}^{2}([0,T]\times Y,\Leb\otimes \nu, U^\prime )
      \quad
      \nonumber
\end{align*}
is continuous with respect to the $ \mathbb{D} ([0,T];U^\prime)$ topology.
\end{trivlist}

