body:
[Proposition 14 of arXiv:2606.29512, '2606.29512'] Let $u$ be an $\R^d$-valued admissible function and let
$v,w\in C^{\infty}_0(\cR,\bR^d)$. 
Then for $\P\otimes dt$-almost every $(\omega,t)$ we have 
\begin{align}
|b(u_t,v,w)|&\leq N\hat u \big(|Dw|_{L_2}|w|_{L_2}\big)|Dv|_{L_2}  
                                                                                  \nonumber\\
&\quad+\bar u_t|Dv|_{L_2}|w|_{L_2}                         \nonumber
\end{align}
with a constant $N=N(d,r)$.

[Prop 10 of arXiv:2609.01358, 'Regularized spectral expansion of a Rankin--Selberg period and moments'] Let $P$ be a standard parabolic of $G$ with Levi $M$ and let $\sigma\in\Pi(M)$. Let $\phi\in \mathcal{S}([\bar{G}])$ and $\lambda\in\a_{P,\C}^\ast/\a^\ast_{G,\C}$ be sufficiently dominant. Then the following sum
		\begin{equation*}
			F_{\sigma,\lambda}(g):=\sum_{\eta\in \B(\sigma)}
			\left(\int_{A_G M(F)\backslash M(\A)}\phi_P(mg)
			e^{\IP{\lambda-\rho_P,H_P(m)}}\overline{\eta}(m)\,dm\right)\eta,
		\end{equation*}
		converges absolutely and we have
		\begin{equation*}
			F_{\sigma,\lambda}(g)=\sum_{\varphi\in\B\left(\mathcal{I}(\sigma)\right)}
			\IP{\phi,\Eis(\varphi, \overline{\lambda})}_{[G]^1 }\varphi_{-\lambda}(g).
		\end{equation*}
		Moreover, the above sums do not depend on the choice of bases.

