[Lemma 10 of arXiv:2607.04012, 'Hölder regularity for backward stochastic Volterra integral equations and applications to '] Let $t\in[0,T]$ and $u\in[0,t)$. Let $1\leq \lambda<2$ and $2<\eta<q$. Then there exists a constant $C>0$, independent of $\pi$, $t$ and $u$, such that
\begin{flalign*}
    \mathbb{E}\bigg[
    \bigg(
    \sum_{k=0}^{N-1}
    \Delta_k
    \mathbb{E}_{u}\Big[
    \sup_{v \in [t, T]}
    \big|D_u U^\pi(t,v)_{k,k}\big|^{\lambda}
    \Big]^{\frac{2}{\lambda}}
    \bigg)^{\frac{\eta}{2}}
    \bigg]^{\frac{1}{\eta}}
    \leq
    C \Big\{
    \mathfrak p_2^\Pi
    +
    \gamma_1^\Pi
    +
    \gamma_z^\Pi
    \Big\}.
\end{flalign*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:positive-Gram-bound of arXiv:2609.01464, 'Removability of non-isolated singularities for Einstein metrics and RCD spaces'] The quadratic form $G_u$ in (equation eq:Gudefn of the paper) satisfies the estimate
    \begin{equation}
 0\leqslant G_u\leqslant(1+C(n)(D+\eta))I
 \qquad \mathcal H^n\text{-a.e. on }B_{7/8}(x).
\end{equation}

[Lemma eq:joint-K-subg of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[lemma]{lem:remainder-tight}
Suppose, without requiring independence, that the coefficient vector
satisfies the joint linear-form estimate
\begin{equation}
 \mathbb E\exp\left\{\sum_{I\in[N]^p}t_IJ_I\right\}
 \le\exp\left\{\frac{K^2}{2}\sum_{I\in[N]^p}t_I^2\right\},
 \qquad t\in\mathbb R^{N^p}.
\end{equation}
Then
\begin{equation}
 \mathbb E\sup_{x\in\mathbb S^{N-1}(1)}\left\lvertR_N(x)\right\rvert\le C_{p,K}
\end{equation}
uniformly in \(N\).  Consequently, there is \(M=M(p,K)\) such that
\begin{equation}
 \inf_N\mathbb P\left(\left\lVertR_N\right\rVert_\infty\le M\right)\ge\frac12.
\end{equation}

