[Lemma lem:clean lem_unique_saddlepoint of arXiv:2605.31356, 'P\'olya--Schur problems and free probability'] \begin{enumerate}
	\item Let $\mu$ be any freely infinitely divisible distribution. Then, for any $z\in\mathbb{C}_{+}\cup\{z\in\mathbb{R}: -\infty<\operatorname{Im} G_{\mu}(z+\ii0)<0\}$
	 \begin{equation}
	z-\frac{1}{u}-R_{\mu}(u)=0
\end{equation} has a unique solution $G_{\mu}(z)$ in $\mathbb{C}_-$. Hence, if $f_n\in\mathcal{LP}$ and $z\in\mathbb{C}_{+}\cup\{z\in\mathbb{R}:-\infty< \operatorname{Im} G_{\mu_{c,\Sigma}}(z+\ii0)<0 \}$, then (equation eq:clean saddle point equation of the paper) has a unique solution in $\mathbb{C}_{-}$ given by $u_n^*(z)=G_{\mu_n}(z)$.

\item If $\{f_{n}\}$ satisfy Assumption (assump:main assumption of the paper), then for any $\varepsilon>0$ (equation eq:clean saddle point equation of the paper) has at most one solution in $\{u\in\mathbb{C}:\operatorname{Im} u<-\varepsilon\}$ for $n$ sufficiently large. Additionally, if $\varepsilon>0$ is sufficiently small, then this unique solution $u_n^*(z)$ exists. 

\item Let $\{f_n\}$ satisfy Assumption (assump:main assumption of the paper) and let $B\subset\mathbb{C}_{+}\cup\{z\in\mathbb{R}: -\infty<\operatorname{Im} G_{\mu_{c,\Sigma}}(z+\ii0)<0 \}$ be a compact subset. Let $\varepsilon>0$ be small enough such that (equation eq:clean saddle point equation of the paper) has a unique solution $u=u_n^*(z)\in\{u\in\mathbb{C}:\operatorname{Im} u<-\varepsilon\}$ for all $z\in B$. Then, $u_n^*$ is analytic on a neighborhood of $B$ and \begin{equation}
	\lim\limits_{n\rightarrow\infty}u_n^*(z)=G_{\mu_{c,\Sigma}}(z)=:u^*(z)
\end{equation} uniformly on $B$. Moreover, $u^*$ can be analytically continued from the upper-half plane to a neighborhood of $\mathbb{C}_+\cup\{z\in\mathbb{R}: -\infty< \operatorname{Im} G(z+\ii0)<0\}$ and we will denote this extension also by $u^*$.

\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 6 of arXiv:2609.03054, 'The classes of bivariate Schur and Herglotz matrix-valued rational functions: realizations'] Let $F:\RHPtwo\to \Cmats{m}{n}$ be a rational matrix function such that
$\norm{F(z)}\leq 1$ for all $z\in\RHPtwo$. Then the following conditions are equivalent:
\begin{enumerate}[\rm (i)]
\item function $F$ is symmetric;
\item $F$ admits a realization of the form \eqref{eq:realization} such that \eqref{eq:c1} and
\eqref{eq:symre} 

hold for some unitary involution $U\in\Cmats{k}{k}$.
\end{enumerate}
Additionally, if $F\in\mathbb R^{m\times n}(z_1,z_2)$ then the matrices $A,B,C,D,P_1,P_2,U$ in {\rm (ii)} may be chosen as real matrices.

