body:
[Theorem t.CLT of arXiv:2411.12003, 'Central Limit Theorem for non-stationary random products of $\SL(2, \R)$ matrices'] Let $\mathcal{K}$ be a compact subset in the set of probability measures on the group~${\mathrm{SL}}(2,{\mathbb R})$ that satisfies the measures condition, and there exists $\gamma \textcolor{black}{\, > 2}$ and $M>0$ such that for any $\mu \in \mathcal{K}$ one has
\begin{equation} 
    {\mathbb E}\,_{\mu} (\log \|A\| )^{\gamma} < M.
\end{equation}
Then the random variables
    $$
        \frac{\log \|T_n\|-L_n}{\sqrt{\mathop{\rm Var}\nolimits(\log\|T_n\|)}}
    $$
    converge in distribution to $\mathcal{N}(0,1)$, with the convergence that is uniform with respect to the choice of the sequence $\mu_1,\mu_2,\dots\in\mathcal{K}$.

     Also, there are constants $C_1, C_{2}>0$ and an index $n_0$ such that for all $n\ge n_0$ and all $\mu_1,\dots,\mu_n\in\mathcal{K}$ one has
    \begin{equation} 
        C_1^2{n}\le \mathop{\rm Var}\nolimits(\log\|T_n\|)\le C_{2}^2{n}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 20 (Common-phase bilinear identity) of arXiv:2608.24863, 'Uniform Logarithmic Sobolev Inequalities for the 2D Coulomb Gas at the Diffusive Temperatu'] If $F,G$ are entire and $FG\in L^1(\mathbb P_{N,\beta})$, then
\begin{equation}
 \int_{\C^N} FG\,\D \mathbb P_{N,\beta}=F(0)G(0).
\end{equation}

[Proposition prop:local_hajek_intro of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] Define
\begin{equation}

    \widehat{\mathsf{N}}_G^{\rho \to v}(x) \coloneqq \mathsf{N}_G^{\rho \to v}(x) - \mathsf{d}_\rho p^{\mathsf{e}-1} n^{\mathsf{v}-2} \mathsf{deg}_v(x).
\end{equation}
Then, for all $\zeta \in (0, \frac{3}{4})$, there is some $c > 0$ such that
\begin{equation}
    \mathbb{P} \mleft[
        \mleft|
            \widehat{\mathsf{N}}_G^{\rho \to v}(X) - \mathbb{E} \mleft[ \widehat{\mathsf{N}}_G^{\rho \to v}(X) \mright]
        \mright| > n^{\mathsf{v} - 1.75 + \zeta}
    \mright] \leq \Exp{- c n^{\frac{4}{3} \zeta}}.
\end{equation}
In particular, for all $\xi > 0$ we have
\begin{equation}
    \operatorname{Var} \mleft[
        \widehat{\mathsf{N}}_G^{\rho \to v}(x)
    \mright] \lesssim n^{2\mathsf{v} - 3.5 + \xi}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 12 of arXiv:2604.06516, 'From stochastic individual-based models to free-boundary Hamilton-Jacobi equations'] For any $t>0$ and for any closed $A\subset\mathbb{D}[0,t]$, 
\begin{equation}

  \limsup_{K\rightarrow +\infty} \frac{1}{\log K} \log\big(\mathbb{E}[N_t^{K,A}]\big)
\le  \sup_{f\in A} F_t(f),
\end{equation}
and for any open $G\subset\mathbb{D}[0,t]$
\begin{equation}

  \liminf_{K\rightarrow +\infty} \frac{1}{\log K} \log\big(\mathbb{E}[N_t^{K,G}]\big)
\ge  \sup_{f\in G} F_t(f),
\end{equation}
     with the usual convention that $\sup\emptyset=-\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 61 (Summably normalized reduced density) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] Enumerate the flattenings entering \eqref{all:eq:4.3} as $(L_{s,\nu})_{\nu\ge1}$ and choose
$\beta_{s,\nu}>0$ with $\sum_\nu\beta_{s,\nu}<\infty$.  Then
\begin{equation}
 \overline D_s^{\,\mathrm{nl}}(F)
 =
 \sum_{\nu\ge1}\beta_{s,\nu}
 \frac{L_{s,\nu}L_{s,\nu}^*}
 {1+\norm{L_{s,\nu}}_{\HS}^2}

\end{equation}
converges in trace norm and
\begin{equation}
 \boxed{
 \cN_s(F)
 =\ol{\Ran\bigl(\overline D_s^{\,\mathrm{nl}}(F)\bigr)^{1/2}}.}

\end{equation}
The analogous density obtained from all flattenings has range $\cS_s(F)$.

