body:
[Proposition 1 of arXiv:2506.19272, 'Fully lifted \emph{blirp} interpolation -- a large deviation view'] Consider vector $\p=[\p_0,\p_1,\p_2]$ with $\p_0\geq \p_1\geq \p_2=0$,  vector $\q=[\q_0,\q_1,\q_2]$ with $\q_0\geq \q_1\geq \q_2=0$, and a scalar $\m_1$. For $k\in\{1,2\}$ let $G\in\mR^{m \times n},u^{(4,k)}\in\mR^1,\u^{(2,k)}\in\mR^{m\times 1}$, and $\h^{(k)}\in\mR^{n\times 1}$ be independent Gaussian objects with  i.i.d. zero-mean components.  Let the variances of the elements of $G$, $u^{(4,1)}$, $u^{(4,2)}$, $\u^{(2,1)}$, $\u^{(2,2)}$, $\h^{(1)}$, and $\h^{(2)}$ be $1$, $\p_0\q_0-\p_1\q_1$, $\p_1\q_1$, $\p_0-\p_1$, $\p_1$, $\q_0-\q_1$, and $\q_1$, respectively. Let ${\mathcal U}_k=[u^{(4,k)},\u^{(2,k)},\h^{(k)}]$ and  assume that sets ${\mathcal X}=\{\x^{(1)},\x^{(2)},\dots,\x^{(l)}\}$, $\bar{{\mathcal X}}=\{\bar{\x}^{(1)},\bar{\x}^{(2)},\dots,\bar{\x}^{(l)}\}$,  and  ${\mathcal Y}=\{\y^{(1)},\y^{(2)},\dots,\y^{(l)}\}$ where $\x^{(i)}, \bar{\x}^{(i)}\in \mR^{n}$ and $\y^{(i)}\in \mR^{m}$, $1\leq i\leq l$ are given. Let $p,\beta\geq 0$ and $s$ be real numbers and let $f_{\bar{\x}^{(i)}}(\cdot) : \mR^n  \rightarrow \mR$ be a given function. Consider 
\begin{equation}
\psi( t)  =  \mE_{G,{\mathcal U}_2} \frac{1}{p|s|\sqrt{n}\m_1}
\log \lp  \sum_{i_3=1}^{l}  \lp  \mE_{{\mathcal U}_1} \lp \sum_{i_1=1}^{l}\lp\sum_{i_2=1}^{l}e^{\beta D_0^{(i_1,i_2,i_3 )}} \rp^{s}\rp^{\m_1} \rp^p \rp,
\end{equation}
where
\begin{eqnarray}
 D_0^{(i_1,i_2,i_3)} & \triangleq & \sqrt{t}(\y^{(i_2)})^T
 G\x^{(i_1)}+\sqrt{1-t}\|\x^{(i_1)}\|_2 (\y^{(i_2)})^T(\u^{(2,1)}+\u^{(2,2)})\nonumber \\
 & & +\sqrt{t}\|\x^{(i_1)}\|_2\|\y^{(i_2)}\|_2(u^{(4,1)}+u^{(4,2)}) +\sqrt{1-t}\|\y^{(i_2)}\|_2(\h^{(1)}+\h^{(2)})^T\x^{(i_1)}
 + f_{\bar{\x}^{(i_3)} } ( \x^{(i_1)}  ). \nonumber \\
 \end{eqnarray}
Then
\begin{eqnarray}
\frac{d\psi(t)}{dt}  & = &   \frac{\mbox{sign}(s)\beta^2}{2\sqrt{n}} \lp \phi_1^{(1)}+\phi_{21}^{(1)} +\phi_{22}^{(1)} +\phi_{01}^{(1)}+\phi_{02}^{(1)}\rp,
 \end{eqnarray}
where $\phi$'s are as in (\ref{eq:cpt8}).

[Lemma lem:lifts of arXiv:2608.29657, 'Hypocoercivity of Tempered Bouncy Particle Samplers for Heavy-Tailed Targets'] Recall ${\mathcal L}_\sigma g = - \nabla_x^\star \sigma^2 \nabla_x g $ for any $g\in C^2({\mathbb R}^d)$. The following equalities hold:
    \begin{align}
    \Pi\, {\mathcal L}_{\mathrm{tr}} \Pi\, b  = 0 \quad \text{and}\quad \Pi\, {\mathcal L}_{\mathrm{tr}}^\star \Pi\, b  = 0\quad&\text{for any  $b \in C^1_\Pi$;}  \tag{L1}\\
    \Pi\, {\mathcal L}_{\mathrm{tr}}^\star {\mathcal L}_{\mathrm{tr}} \Pi f  = -{\mathcal L}_\sigma \Pi f, \quad &\text{for any } f \in C_\Pi^2;\tag{L2}\\
    \langle {\mathcal L}_{\mathrm{tr}}^\star h, g \rangle_{L^2(\mu_\sigma)} = \langle h, {\mathcal L}_{\mathrm{tr}} g \rangle_{L^2(\mu_\sigma )} , \quad &\text{for any } h \in W_{\mathrm{tr}^\star} \text{ and } g \in W_\mathrm{tr}.  \tag{L3}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] A mild solution $X(\cdot)$  is a strong solution  to (eqSEE of the paper) if the following three conditions hold for all $x \in H$ and $0 \leq s \leq t \leq T$, a.s.,  
    \begin{enumerate}[(i)]
        \item  $X_0 \in D(A), S(t-s) F(s, x) \in D(A)$ and $S(t-s) \widetilde{F}(s, x) \in D(A)$;
        \item  $|A S(t-s) F(s, x)|_H \leq \alpha(t-s)|x|_H$ for some real-valued stochastic process $\alpha(\cdot) \in L_{\mathbb{F}}^{1}(0, T)$ a.s.; 
        \item  $|A S(t-s) \widetilde{F}(s, x)|_H \leq \beta(t-s)|x|_H$ for some real-valued stochastic process $\beta(\cdot) \in L_{\mathbb{F}}^{2}(0, T)$ a.s.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

