[Proposition 11 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] Suppose that~\eqref{co:6} and~\eqref{eq:integrability condition} are valid for $\rho > 0$. Then for any positive solution $I$ to~\eqref{eq:SIS epidemic model} and $x_{0} \geq 0$, the following two assertions hold:
\begin{enumerate}[(i)]
\item If $x_{0} > 0$ and for each $\delta\in ]0,x_{0}[$ there is a measurable locally integrable function $w_{\delta}\colon\R_{+}\rightarrow\R$ such that $\limsup_{t\uparrow\infty}\frac{1}{t^{\rho}}\int_{0}^{t}w_{\delta}(s)\,\mathrm{d}s > 0$ and
\begin{equation*}
\liminf_{s\uparrow\infty}\inf_{x\in ]0,N(s)]:\,x < x_{0} - \delta}\frac{1}{s^{\rho -1}}\big(h\big(s,x,N(s),\mathcal{L}(I_{s})\big) - w_{\delta}(s)\big) \geq 0,
\end{equation*}
then $I$ persists above $x_{0}$, that is, $\limsup_{t\uparrow\infty} I_{t}\geq x_{0}$ a.s.

\item If for each $\delta > 0$ there is a measurable locally integrable function $w_{\delta}\colon\R_{+}\rightarrow\R$ such that $\liminf_{t\uparrow\infty}\frac{1}{t^{\rho}}\int_{0}^{t}w_{\delta}(s)\,\mathrm{d}s < 0$ and
\begin{equation*}
\limsup_{s\uparrow\infty}\sup_{x\in ]0,N(s)]:\,x > x_{0} + \delta}\frac{1}{s^{\rho -1}}\big(h\big(s,x,N(s),\mathcal{L}(I_{s})\big) - w_{\delta}(s)\big) \leq 0,
\end{equation*}
then $\liminf_{t\uparrow\infty} I_{t}\leq x_{0}$ a.s.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemmas4.111 of arXiv:2608.01279, 'Stochastic heat equation with nondegenerate Hölder diffusion coefficient: uniqueness below'] For each \(s>1/2\), we can find a constant $C_{s,g}>0$ depending only on $s$ and the function $g$ such that 

\begin{equation}
\|B_{F(t)}\|_{\mathcal{L}_2(H,H^{-s})}^2
=\|A^{-s/2}M_{F(t)}\|_{\mathrm{HS}}^2
\le C_{s,g} Z(t)^\beta+C_{s,g}\varepsilon_n^2,

\end{equation}
where $\mathcal{L}_2(H,H^{-s})$ is the space of Hilbert-Schmidt operators from $H$ to $H^{-s}$
and

\begin{equation}
Z(t)\le r_s^{2(1-s)}(t)\mathcal A_s^s(t),\quad \forall t\geq 0.

\end{equation}

