[Lemma 2-d_2-d of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] {cai2024high}}]
	For any $d\ge 7$ and $x,y\in \mathbb{Z}^d$, 
		\begin{equation}
		\sum\nolimits_{z\in \mathbb{Z}^d}|x-z|^{2-d}|z-y|^{2-d}\lesssim |x-y|^{4-d},
	\end{equation}
	\begin{equation}
			\sum\nolimits_{z\in \mathbb{Z}^d}|x-z|^{2-d}|z-y|^{4-d}\lesssim |x-y|^{6-d}, 
	\end{equation}
	\begin{equation}
		\sum\nolimits_{z\in \mathbb{Z}^d}|x-z|^{2-d}|z-y|^{6-2d}\lesssim |x-y|^{2-d},
	\end{equation}
	\begin{equation}
		\sum_{z_1,z_2,z_3\in \mathbb{Z}^d}|z_1-z_2|^{2-d}|z_2-z_3|^{2-d}|z_3-z_1|^{2-d}|x-z_1|^{2-d}|y-z_2|^{2-d}\lesssim |x-y|^{4-d},
	\end{equation}
		\begin{equation}
		\sum\nolimits_{z_1,z_2\in \mathbb{Z}^d}|x-z_1|^{2-d}|z_1-z_2|^{2-d}|z_2-x|^{2-d}|z_1-y|^{2-d}\lesssim |x-y|^{2-d}.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 of arXiv:2608.23989, 'Collision Properties in Discrete and Continuous Time on Bounded-Degree Graphs'] Let~$P$ be an irreducible Markov kernel on $\mathsf S$, and let $G_{\rm disc}$ and $G_{\rm cont}$ be the Green kernels associated with $\mathsf P_{\rm disc}$ and $\mathsf P_{\rm cont}$, respectively. Suppose that, for some~$\alpha>0$,
\begin{equation}
\inf_{x \in \mathsf S} P^2(x,x) \ge \alpha
\end{equation}
Then, there exists~$A = A(\alpha) > 0$ such that
$$ A \cdot G_{\rm disc}( (x,x);(y,y) ) \leq G_{\rm cont}( (x,x);(y,y) ) \leq 2 G_{\rm disc}( (x,x);(y,y) ). $$
for each~$x,y \in \mathsf S$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem prop-mainMN of arXiv:2411.15401, 'The reference interval in higher-order stochastic dominance'] Let $a,b\in\mathbb{R}$ with $a<b$ and $m,n\in\mathbb{N}$ with $m\le n-1$. 
\begin{align}

\mbox{For  all $X,Y\in\mathcal X_{[a,b]}$}:  \mbox{ $X$ dominates $Y$ in $(n,m){\rm SD}_{[a,b]}$}  ~\Longrightarrow~ 
\mbox{$X$ dominates $Y$ in $(n,m){\rm SD}_{\mathbb{R}}$}.
\end{align} 
 The backward implication of (equation eq:implies2 of the paper)  holds if and only if $n-m\le 3$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 18 of arXiv:2506.20411, 'Maximal Counts in the Stopped Occupancy Problem'] For fixed $k\in {\mathbb Z}$, $j\in{\mathbb Z}_{>0}$ and $M_n:=M_{n,1}(\tau_n)$,
\begin{align}
&{\mathbb P}[M_{n}-b_n=k,~\mu_{n, b_n+k}(\tau_n)=j]=\\\notag&\qquad
\int_{-\infty}^\infty p_0\left(e^{(e-1)s+ c_n-k}\right)p_j\left((e-1)e^{(e-1)s+c_n-k}\right)  e^{-s}p_\ell(e^{-s}){\rm d}s+o(1).
\end{align}

[Defn Characterization of Chordal SLE of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] Chordal SLE is a family of probability measures on curves $\mathbb{P}(\mathbb{H};a,b)$ $\eta:[0, \infty] \rightarrow \overline{\mathbb{H}}$ with $\eta(0)=a, \eta(\infty)=b$ and parametrized by capacity satisfies the following properties:
    \begin{itemize}
     \item (Conformal invariance) $\rho(z)\in {\rm Aut}(\mathbb{H})$, the pullback measure $\rho^* \mathbb{P}(a,b)=\mathbb{P}(\mathbb{H};\rho(a),\rho(b))$. From this, we may extend the definition of to  $\mathbb{P}(\mathbb{H};z_1,z_2)$ in any simply connected domain $\Omega$ with two boundary points $z_1,z_2$  by pulling back using a uniformizing conformal map $\Omega \rightarrow \mathbb{H}$ sending $z_1$ to $a$ and $z_2$ to $b$.
    \item (Domain Markov property) given an initial segment $\gamma[0, \tau]$ of the $\operatorname{SLE}_\kappa$ curve $\gamma \sim \mathbb{P}(\Omega ; x, y)$ up to a stopping time $\tau$, the conditional law of $\gamma[\tau, \infty)$ is the law $\mathbb{P}\left(\Omega \backslash K_\tau ; \gamma(\tau), y\right)$ of the $\mathrm{SLE}_\kappa$ curve in the complement of the hull $K_\tau$ from the tip $\gamma(\tau)$ to $y$.
    \end{itemize}

[Dfntn 3 (curl-type operator) of arXiv:2608.31054, 'Revisiting Picard's proof of the Picard--Weber--Weck selection theorem'] Let $\Omega\subseteq \R^d$ be open. We define the differential operator
\begin{align*}
    \Rot_c &:C_c^\infty(\Omega)^d\subseteq L^2(\Omega)^d\rightarrow L^2(\Omega)^{d\times d},\quad  v\mapsto \skw(\Grad_c   v),
\end{align*}
where
\begin{align*}
    \skw:L^2(\Omega)^{d\times d}\rightarrow L^2(\Omega)^{d\times d},\quad V\mapsto \frac{1}{\sqrt{2}}(V-V^\top),
\end{align*}
and we set $\Rotcirc := \overline{\Rot_c}$ and $\Rot := -(\Divcirc \skw)^\ast$.

[Corollary cor:K of arXiv:2412.01645, 'Regularisation by Gaussian rough path lifts of fractional Brownian motions'] Let (asn:b of the paper) and (asn:sigma of the paper) hold. Let $\chi\in\mathrm{Cut}_d$, $p\in[1,\infty)$, and let $X$ and $Y$ be two solutions to (equation eq:main of the paper).  Then the map $f\mapsto\mathcal{K} f$ defined for $f\in\mathcal{C}^2({\mathbb{R}}^d; {\mathbb{R}}^d)$ by   
\begin{equ}
(\mathcal{K} f)_{s,t}=\int_0^1\int_s^t(B_r-B_s)\otimes\Big(\chi_\rho(X_r-Y_r)\nabla f\big(\theta X_r+(1-\theta)Y_r\big)\Big)\,dr\,d\theta
\end{equ}
  extends as a continuous linear map from $\mathcal{C}^{\alpha+}({\mathbb{R}}^d; {\mathbb{R}}^d)$ to $\mathcal{C}^{1+\alpha H}_{2}([0,1]; L_p(\Omega ; {\mathbb{R}}^{d_0} \otimes {\mathbb{R}}^{d\times d}))$, whose norm depends only on $\alpha,p,d,d_1,\lambda,H,\|\sigma\|_{\mathcal{C}^5},C^X_{D, p}, C^X_{S, 2p}, C^Y_{D,p}, C^Y_{S, 2p}$. Moreover, one has the identity
    \begin{equ}
        \delta (\mathcal{K} f)_{s,u,t}=B_{s,u}\otimes(\mathcal{J} f)_{u,t}.
    \end{equ}

