[Theorem 14 of arXiv:2506.22020, 'Norm-dependent Lamperti-type MAP representations of stable processes and Brownian motions '] Let $X=(X_t)_{t\geq 0}$, with $X_t=(X^{(1)}_t,\ldots,X_t^{(d)})$, where the $X^{(i)}$ are independent (standard) one-dimensional spectrally-positive L\'evy processes, as defined just above. Define the Skorokhod-reflection of $X$ by $R=(R^{(1)},\ldots,R^{(d)})$, where $R^{(i)}\coloneqq X^{(i)}-\underbar{X}^{(i)}$. Then, for $g\in C^2_b([0,\infty)^d)$ satisfying the boundary conditions
	\begin{equation*}
		\frac{\partial g}{\partial z_i}(z_1,\ldots,z_{i-1},0,z_{i+1},\ldots,z_d)=0\enspace \forall z_k>0,\qquad i=1,\ldots,d,
	\end{equation*}
	the process
	\begin{equation*}
		g(R_t)-g(R_0)-\int_0^\infty \mathcal{L}g(R_s) ds\text{ is a martingale},
	\end{equation*}
	where $\mathcal{L}:C^2_b([0,\infty)^d)\to C^2_b([0,\infty)^d)$ is the operator defined by
	\begin{equation*}
		\mathcal{L}F(\boldsymbol{w})=\sum_{i=1}^d \Bigg( b_i \frac{\partial F}{\partial z_i}(\boldsymbol{w}) +\frac{\sigma_i^2}{2}\frac{\partial^2 F}{\partial z_i^2}(\boldsymbol{w})+\int_0^\infty \Big(F(\boldsymbol{w}+x\boldsymbol{e}_i)-F(\boldsymbol{w})-\frac{\partial F}{\partial z_i}(\boldsymbol{w}) x\mathbbm{1}_{(0,1)}(x)\Big)\Pi^{(i)}(dx) \Bigg),
	\end{equation*}
	where $\Pi^{(i)}$ denotes the L\'evy measure of $X^{(i)}$.

Let X solve dX_t = mu_t dt + sigma_t dW_t and let f(t, x) be once continuously differentiable in t and twice in x. Then f(t, X_t) is again an Ito process with df = (f_t + mu f_x + (1/2) sigma^2 f_xx) dt + sigma f_x dW: the chain rule of stochastic calculus carries the extra second-order term (1/2) sigma^2 f_xx inherited from the nonvanishing quadratic variation of Brownian motion.
X an Ito process with the stated dynamics
f in C^{1,2}

[Theorem thm:main of arXiv:2605.15401, 'Noise Tradeoffs, Stationary Information Flow, and Structural Balance in Unit-Birth Network'] Consider the unit-birth CTMC on $S=\mathbb{Z}_{\ge0}^N$ with generator
(equation eq:generator of the paper). Suppose Assumption~(ass:standing of the paper) holds, and let
$\pi$ be its stationary distribution. 
Then the following statements hold.
\begin{enumerate}[label=\textup{(\arabic*)}, leftmargin=2.2em]
\item For each $i$,
\begin{equation}
\mathbb{E}_\pi[X_i]=\tau_i\,\mu_i,
\end{equation}
and
\begin{equation}
F_{X_i}
=1+\frac{\mathrm{Cov}_\pi\!\big(f_i(X_{-i}),X_i\big)}{\mu_i}.
\end{equation}

\item The single information flow $(\dot I)_{X_i}$ defined in
(equation eq:Idot_clean_def of the paper) is well defined, and for each $i$,
\begin{equation}
\frac{F_{X_i}-1}{\tau_i}\ge (\dot I)_{X_i}.
\end{equation}

\item We have zero total information flow:
\begin{equation}
\sum_{i=1}^N (\dot I)_{X_i}=0.
\end{equation}
\end{enumerate}
Consequently, we have the global tradeoff
\begin{equation}
\sum_{i=1}^N \frac{F_{X_i}-1}{\tau_i}
\ge
\sum_{i=1}^N (\dot I)_{X_i}
=0.
\end{equation}
In particular, it is impossible to have $F_{X_i}\le 1$ for all $i$ with strict
inequality for at least one index: if $F_{X_k}<1$ for some $k$, then there
exists $j\neq k$ such that $F_{X_j}>1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:factorial_moments of arXiv:2606.09386, 'High-degree vertices in uniform recursive directed acyclic graphs with freezing'] Fix $m\in\mathbb{N}$, $c\in(0,m+1)$, and $K,L\in\mathbb{N}_0$ such that $K+L\geq 1$. Let $\mathbf x$ be a choice sequence that satisfies Assumption~$\hyperref[ass:A]{\mathbf{x}}$ for some $\varepsilon<1-c/(m+1)$ in Part~(item:hI of the paper) and some $\eta<1-c/(m+1)$ in Part~(item:Jn of the paper).  Let $i=i(n),i'=i'(n)$ and $j=j(n),j'=j'(n)$ be integers such that $i<i'$ and $j<j'$ for all $n$, $i+\lfloor\log_\theta (A_n)\rfloor\geq 0$ and $j+\lfloor\log_\theta F_n\rfloor\geq 0$ for all $n$, and 
\begin{equation} 
\limsup_{n\to\infty} \frac{\log_\theta (A_n)+i'}{h_n^+}<c\qquad\text{and}\qquad \limsup_{n\to\infty} \frac{\log_\theta(F_n)+j'}{\log F_n}<c.
\end{equation} 
Then, there exists $\alpha\in(0,1)$ such that for any non-negative integers $b_i,\ldots, b_{i'}$ and $c_j,\ldots, c_{j'}$ such that $b_i+\cdots+b_{i'}=K$ and $c_j+\cdots+c_{j'}=L$, we have 
\begin{equation}\begin{aligned} 
\mathbb E{}&\Bigg[\big(X^{(n)}_{\geq i'}\big)_{b_{i'}}\big(Y^{(n)}_{\geq j'}\big)_{c_{j'}}\prod_{i\leq k<i'}\big(X^{(n)}_k\big)_{b_k}\prod_{j\leq \ell<j'}\big(Y^{(n)}_\ell\big)_{c_\ell}\Bigg]\\
&=\Big(\big(\theta^{-i'+\varepsilon_n^\mathrm{a}}\big)^{b_{i'}}\!\!\prod_{i\leq k<i'}\!\!\big((1-\theta^{-1})\theta^{-k+\varepsilon_n^\mathrm{a}}\big)^{b_k}\Big)\Big(\big(\theta^{-j'+\varepsilon_n^\mathrm{f}}\big)^{c_{j'}}\!\!\prod_{j\leq \ell <j'}\!\!\big((1-\theta^{-1})\theta^{-\ell+\varepsilon_n^\mathrm{f}}\big)^{c_\ell}\Big)(1+\mathcal{O}(\delta_n)),
\end{aligned}\end{equation} 
where $\delta_n\coloneq \min\{A_n,F_n,I_{\hyperref[ass:A]{\mathbf{x}}}^\alpha\}^{-1}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

