[Theorem 6 of arXiv:2604.01336, 'Euler scheme for stochastic functional differential equations driven by fractional Brownia'] Assume that Hypotheses \ref{H1}, \ref{H2} and \ref{H3} are satisfied. Also,
		let $Z^{(n)}:= {X}-{X}^{(n)}$ and  $\overline{Z}^{(n)}:= \overline{X}-\overline{X}^{(n)}$ where $X$ is the solution to equation \eqref{eq1} and $X^{(n)}$ is the Euler scheme defined in \eqref{euler}. For $\lambda$ given in Hypothesis \ref{H1}, $0 <  \varepsilon <2\lambda-1$ and $s, t \in[0,T]$ with $s<t$, we have
		\begin{equation*}
			|Z^{(n)}_t| \leq \frac{\hat{C}_1}{n^{2\lambda-1-\varepsilon}},  \quad   
			|\delta Z^{(n)}{(s, t)}| \leq \frac{\hat{C}_2}{n^{2\lambda-1-\varepsilon}}|t-s|^\lambda,
		\end{equation*}
		\begin{equation*}
			\| \overline{Z}^{(n)}_t
			\| \leq  \frac{\hat{C}_1}{n^{2\lambda-1-\varepsilon}}  \quad  \text{and} \quad \|\delta \overline Z^{(n)}({s, t})\| \leq \frac{\hat{C}_2}{n^{2\lambda-1-\varepsilon}}|t-s|^\lambda,
		\end{equation*}    
		where $\hat{C}_1$ and $\hat{C}_2$ are positive constants such that $\hat{C}_1\leq c_1\exp(c_2(1+ \|B^H\|^{1/\lambda}_\lambda))$ and $\hat{C}_2\leq c_3\exp(c_4(1+ \|B^H\|^{1/\lambda}_\lambda))$, for some positive constants  $c_1, \cdots, c_4$ depending on $f$ and $\varepsilon$.

