[Theorem 4 (\cite{DovOrsToaldo}) of arXiv:2604.00882, 'On some extensions of generalized counting processes'] {The density $\ell_\nu(x,t)$ of the process $\mathcal{L}^\nu(t)$, $t > 0$, solves the time-fractional boundary-initial problem}
	\begin{equation}
		\begin{cases}
			\left( \mathbb{D}_t^{2\nu} + 2\lambda \mathbb{D}_t^{\nu}\right) \ell_\nu(x,t) = -\frac{\partial}{\partial x} \ell_\nu(x,t), \quad x > 0,\,\, t > 0,\,\, 0 < \nu < \frac{1}{2}, \\
			\ell_\nu(x,0) = \delta(x), \\
			\ell_\nu(0,t) = \frac{t^{-2\nu}}{\Gamma(1-2\nu)} + 2\lambda \frac{t^{-\nu}}{\Gamma(1-\nu)},
		\end{cases}
	\end{equation}

	{and has $x$-Laplace transform, for $0 < \gamma < \lambda^2$,}
	\begin{equation}
		\widetilde{\ell}_\nu(\gamma, t) = \frac{1}{2} \left[ \left( 1 + \frac{\lambda}{\sqrt{\lambda^2 - \gamma}} \right) E_{\nu,1} (r_1 t^\nu) + \left( 1 - \frac{\lambda}{\sqrt{\lambda^2 - \gamma}} \right) E_{\nu,1} (r_2 t^\nu) \right],
	\end{equation}

	{where}
	\begin{equation}
		r_1 = -\lambda + \sqrt{\lambda^2 - \gamma}, \quad r_2 = -\lambda - \sqrt{\lambda^2 - \gamma}.
	\end{equation}

	{The fractional derivatives appearing in \eqref{2.20} are  in the Riemann-Liouville sense.} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:URDlinktoRP of arXiv:2601.21762, 'Navier-Stokes with a fractional transport noise as a limit of multi-scale dynamics'] Let $(Z,\mathbb{Z})$ be an $\alpha$-H\"older continuous rough path with values in $H^\sigma$. Then   
      \begin{align*}
        \norm{A^1_{s,t}}_{\mathcal L(H^{-m}, H^{-(m+1)})} &\lesssim \norm{ Z_{s,t}}_{H^{\sigma}} \quad \text{for $m\in[0,2]$},\\
        \norm{A^2_{s,t}}_{\mathcal L(H^{-m}, H^{-(m+2)})} &\lesssim \norm{ \mathbb{Z}_{s,t}}_{H^{\sigma}\otimes H^\sigma} \quad \text{for $m\in[0,1]$}.
    \end{align*}
Moreover, $(A^{1}, A^{2}) $ is an unbounded rough driver.

[Lemma 2-l06 of arXiv:2412.04015, 'Linear fluctuation of interfaces in Glauber-Kawasaki dynamics'] Let $(\ell_N:N\ge 1)$ be the sequence introduced in the statement of
Theorem (mt1 of the paper).  Assume that $\sup_N (K^2_N/\ell^d_N)<\infty$.
Then, there exists a finite constant ${\mathfrak c}({\boldsymbol u}^N)$, depending only
on ${\boldsymbol u}^N$, $A$, $d$ and uniformly bounded in $N$, such that
\begin{equation*}
