\;+\; {\mathfrak c}({\boldsymbol u}^N)\, \frac{1}{\delta} \, \{\, 1 + \Vert
G\Vert^2_\infty \,\} \,
K^2 \, \big\{ H_N(f) \,+\, (N/\ell_N)^d\, \big\} 
\end{equation*}
for all $0<\delta<1$, $N\ge 1$ and density $f$ with respect to $\nu^N$.

