	We define:
	\begin{subequations}
		\begin{align} 
			\mulevelsettwoarg{\mulevelsetvalue}{I}
			& 
			\eqdef
			\mulevelsetarg{\mulevelsetvalue}
			\cap
			\left\lbrace (t,u,x^2,x^3) \in \R \times \R \times \T^2 
			\ | \ 
			\timefunction(t,u,x^2,x^3) \in I 
