[Lemma eq:c1 of arXiv:2411.14921, 'A boundary Harnack principle and its application to analyticity of 3D Brownian intersectio'] There exist constants $0<b_1=b_1(\lambda), b_2=b_2(\lambda)<\infty$ such that 
    \begin{equation}
    \sup_{n\ge 1}\,\sup_{\gamma\in\Gamma}\,Q_n(\gamma)\le b_1,
\end{equation}
and for all $n,n'\geq1$ and $\gamma\in\Gamma$,
\begin{equation}
        Q_n(\gamma)\leq b_2\, Q_{n'}(\gamma).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 2 (Interior H\"older continuity) of arXiv:2604.10142, 'H\MakeLowercase{arnack inequality for} $p$\MakeLowercase{-harmonic functions: \\ improved '] There exist   $C,\gamma>0$, such that for any $p$-harmonic function $u$ on $\overline B_{1}(0)$  and every $0<\delta<1$, we have 
    \begin{equation}
        \osc(u,B_\delta(0))\leq \frac{Cd}{p-1} \delta^\gamma \osc(u,B_1(0)).
    \end{equation}
    In particular, we can take $\gamma=\frac{1}{5}$ and $C=10^4$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary theorem1.69 of arXiv:2504.15992, 'Repeated singular values of a random symmetric matrix and decoupled singular value estimat'] Let $A_n$ be a random symmetric matrix with entry distribution $\zeta$ having mean 0, variance 1 and a finite log-Sobolev constant. Then for any $\kappa>0$, with probability $1-e^{-cn}$, singular values of $A_n$ in $[\kappa n^{1/2},(2-\kappa)n^{1/2}]$ are distinct. Moreover, for any $\epsilon>0$,
    $$
\mathbb{P}(\text{Minimal gap of singular values of $A_n$ in $[\kappa n^{1/2},(2-\kappa)n^{1/2}]$}\leq \epsilon n^{-3/2})\leq C\epsilon+e^{-cn}
    $$ for some $C,c>0$ depending only on $\zeta$ and $\kappa$.

    More generally, fix some $\sigma\in(0,1]$ (and no longer assume that $\zeta$ satisfies LSI). Then we have the following estimate: for the random matrix $A_n$ and any $\epsilon>0$, \begin{equation}
    \mathbb{P}_{A_n}(\text{Minimal gap of singular values in $[\kappa n^{-1/2+\sigma},(2-\kappa)n^{1/2}]$}\leq \epsilon n^{-3/2})\leq C\epsilon+e^{-cn^{\sigma/2}}
    \end{equation} for some $C,c>0$ depending only on $\zeta$ and $\kappa$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:comparison of arXiv:2604.20008, 'Mixing times of Langevin dynamics for \\ spiked matrix models'] Suppose that we are given the following stochastic processes:
    \begin{enumerate}
        \item Two real $(\mathcal F_t)$-adapted continuous processes $x_1(t,\omega)$ and $x_2(t,\omega)$;
        \item A one-dimensional $(\mathcal F_t)$-Brownian motion $W(t,\omega)$ such that $W(0)=0$ a.s.;
        \item Two real $(\mathcal F_t)$-adapted well-measurable processes $\beta_1(t,\omega)$ and $\beta_2(t,\omega)$.
    \end{enumerate}
    If the following conditions hold:
    \begin{enumerate}
        \item $x_i(t)=x_i(0)+\int_0^t(\beta_i(s)\mathrm ds+\sigma(s,x_i(s))\mathrm dW_s$ for $i=1,2$;
        \item $x_1(0)\leq x_2(0)$;
        \item $\sigma(t,x)\in C([0,\infty)\times \mathbb R)$;
        \item There exists a strictly increasing function $\rho$ defined on $[0,\infty)$ with $\rho(0)=0$, such that  
        \begin{align*}
            \int_{0}^{\infty}\rho^{-2}(\xi) d\xi=\infty\,,
        \end{align*}
        and
        \begin{align*}
            &|\sigma(t,x)-\sigma(t,y)|\leq\rho(|x-y|)\,,&&x,y\in\mathbb R,t\geq 0\,.
        \end{align*}
        \item There exists $b_1(t,x),b_2(t,x)\in C([0,\infty)\times \mathbb R)$ satisfy
        \begin{align*}
            \beta_1(t)\leq b_1(t,x)< b_2(t,x)\leq \beta_2(t)&&x\in\mathbb R,t\geq 0\,.
        \end{align*}   
    \end{enumerate}

    Then with probability $1$, $x_1(t)\leq x_2(t)$ for all $t\geq 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:jump-quadratic-variation-budgets-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] There exist constants \(\eta_R,\eta_V>0\) such that, for every \(n\), every \(2^n\le\lvert\xi\rvert\le2^{n+1}\), and every \(
d\in\mathfrak D_{\xi,n}^{\mathrm{osc}}\), the budgets can be chosen so that
\begin{equation}
R_{\xi,d,n}
\le
C2^{-sn/2}2^{-\eta_R n},
\end{equation}
and
\begin{equation}
V_{\xi,d,n}
\le
C2^{-sn}2^{-\eta_V n}.
\end{equation}

[Corollary cor:weak-recovery-S-sgd of arXiv:2609.03858, 'High-Dimensional Learning Dynamics of \\ Attention-Indexed Models'] Consider (equation eq:S-sgd of the paper) with
$\mathcal K=\{1\}$, where $S_1$ is the trainable student and $S_2$ is a fixed teacher. Suppose the
conditions of Theorem (theo:S-sgd-dynamics of the paper) and Assumption (assum:S-initialization of the paper) hold.

\begin{itemize}
\item[1.]If, at initialization,
\begin{equation}
a_+g_+(0)\neq0
\qquad\text{or}\qquad
a_-g_-(0)\neq0,

\end{equation}
then there exist constants
$c>0$ and $0<T_-<T_+<\infty$, independent of $d$, such that
\begin{equation}
\lim_{d\to\infty}\mathbb P\left(\left\lfloor\frac{T_-d}{\alpha_d}\right\rfloor<N_{\mathrm{wr},S}^{(d)}(c)
\le\left\lceil\frac{T_+d}{\alpha_d}\right\rceil\right)
=1.

\end{equation}
In particular, choosing the largest learning-rate scaling $\alpha_d=\Theta\left(\frac1{d\log d}\right)$ covered by Theorem (theo:S-sgd-dynamics of the paper) gives the weak recovery sample complexity
\begin{equation}
N_{\mathrm{wr},S}^{(d)}(c)=\Theta_{\mathbb P}(d^2\log d).
\end{equation}

\item[2.] Let the uninformative manifold be $\mathcal U:=\left\{(t,\Psi,\Omega):t_1=0,\Psi_{12}=0,\Omega_{12}=0\right\}$.
Suppose that
\begin{equation}
[\nabla_\Omega\Phi(\Psi,\Omega)]_{12}=[\nabla_\Psi\Phi(\Psi,\Omega)]_{12}=0
\qquad
\text{for every state in }\mathcal U.

\end{equation}
Then for every fixed $T<\infty$ and every $\epsilon>0$,
\begin{equation}
\lim_{d\to\infty}\mathbb P\left(\sup_{t\in[0,T]}
\max\left(|p_{\Psi,12}^{(d)}(t)|,|p_{\Omega,12}^{(d)}(t)|\right)>\epsilon\right)=0.

\end{equation}
In particular, for any learning-rates covered by
Theorem (theo:S-sgd-dynamics of the paper), $S$-SGD cannot achieve weak
recovery within $\mathcal O(d^2\log d)$ samples.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Coro cor:momentstoeps of arXiv:2605.07920, 'Primitive Sequences for Probability Measures on Compact Intervals'] We have
    \begin{equation}
        \mathbb{E}[X^n] = \sum_{j=0}^n (-1)^j n^{\underline{j}} b^{n-j} \varepsilon_j \quad \text{and} \quad
        \varepsilon_n = \sum_{j=0}^n \frac{(-1)^jb^{n-j}}{j! (n-j)!} \mathbb{E}[X^j],
    \end{equation}
    where $n^{\underline{j}} := n (n-1) (n-2) \cdots (n-j+1)$ is the $j$th falling factorial of $n$.

