[Lem See Proposition $9.2$ in \cite{R.T1986} of arXiv:2412.05521, 'Random attractors for the stochastic Nernst-Planck-Navier-Stokes system with multiplicativ'] For $n=2$, if $u,~\upsilon,~w \in V$, then
		\begin{align*}
			|b(u,\upsilon,w)|\leq k\|u\|_{L^2}^{\frac{1}{2}}\|\nabla u\|_{L^2}^{\frac{1}{2}}\|\nabla \upsilon\|_{L^2}\|w\|_{L^2}^{\frac{1}{2}}\|\nabla w\|_{L^2}^{\frac{1}{2}}, 
		\end{align*}
		and if $u \in V$, $\upsilon \in D(A)$, and $w \in H$,then
		\begin{align*}
			|b(u,\upsilon,w)|\leq k\|u\|_{L^2}^{\frac{1}{2}}\|\nabla u\|_{L^2}^{\frac{1}{2}}\|\nabla \upsilon\|_{L^2}^{\frac{1}{2}}\|\Delta \upsilon\|_{L^2}^{\frac{1}{2}}\|w\|_{L^2}.
		\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 11 of arXiv:2604.22461, 'Large deviation principles for stationary solutions and invariant measures of a class of S'] For any $t_0 >-\infty$, we define $\sC_{t_0}$ as the space $C(\R;H) \cap  \{ \cap_{N \geq 1} L^2([t_0,N];V) \}$ equipped with the following distance
    \begin{equation*}
         d_{t_0} (X,Y) := \Big(  \sum_{N=1}^{+\infty} \frac{ 1 \wedge \sup_{s\in [-N,N] } \| X_s -Y_s \|_{H}^2 \wedge \int_{-N \vee t_0}^N  \| X_s -Y_s \|_{V}^2 \, \d s}{2^{N}} \Big)^{1/2},
    \end{equation*}
    for all $X,Y \in \sC_{t_0} $.


    The space $\sC_{+\infty}$ is defined as $C(\R;H)$ equipped with the metric
    \begin{equation*}
         d_{+\infty} (X,Y) := \Big(  \sum_{N=1}^{+\infty} \frac{ 1 \wedge \sup_{s\in [-N,N] } \| X_s -Y_s \|_{H}^2 }{2^{N}} \Big)^{1/2},
    \end{equation*}
    for all $X,Y \in \sC_{+\infty} $. For any $t_0 \in [ -\infty, +\infty]$ and $p \geq 1$, we define $L^{p}(\Omega,\sC_{t_0})$ as the space of all random functions lie on $\sC_{t_0}$ with the metric $ |\E |d_{t_0} (\cdot,\cdot)|^{p}|^{1/p} $.

[Lemma 9 (McDiarmid's inequality~\citep{mcdiarmid1989method}) of arXiv:2609.01397, 'Measuring consistency via ensemble margin and local prediction variability: Auditing decis'] Let $\mbf{z}_1,\dots,\mbf{z}_N$ be independent random variables taking values in a set $\mathcal{Z}$.
Let $\Phi:\mathcal{Z}^N \to \mathbb{R}$ be a function of $(\mbf{z}_1,\dots,\mbf{z}_N)$.
Assume $\Phi$ satisfies the bounded differences property: for each $i\in\{1,\dots,n\}$ there exists $c_i\ge0$ such that for all
$z_1,\dots,z_n,z'_i \in \mathcal{Z}$,
\begin{align}
    \big|\Phi(z_1,\dots,z_i,\dots,z_N) - \Phi(z_1,\dots,z'_i,\dots,z_N)\big|
    \le c_i .

\end{align}
Then for every $t>0$,
\begin{align}
    \prob_{\mbf{z}}*{
        \abs*{ \Phi(\mbf{z}_1,\dots,\mbf{z}_N)
        - \E[\Phi(\mbf{z}_1,\dots,\mbf{z}_N)]}
        \ge t
        }
    \le
    2\exp\parens*{ -\frac{2t^2}{\sum_{i=1}^N c_i^2} }
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 2 (Positive $\alpha$-stable law) of arXiv:2606.18458, 'Stable size-biasing and the positive scale-mixture order of generalized Gaussian laws'] Let $0<\alpha<1$. A positive $\alpha$-stable random variable $S_\alpha$ is the positive random variable whose Laplace transform is
\begin{equation}
\E e^{-uS_\alpha}=e^{-u^\alpha},\qquad u\ge0.

\end{equation}
Equivalently, $S_\alpha$ is the time-one marginal of the stable subordinator with Laplace exponent $u^\alpha$. This is the standard one-sided stable normalization used in classical treatments of stable laws \citep{Feller1971,Zolotarev1986,Nolan2020}.

[Lemma 4 of arXiv:2608.21701, 'Superdiffusivity of random walks on the three-dimensional randomly oriented Manhattan latt'] For $f\in {\ell}_{\rm sym}^2(U,d,n)$, we have
\begin{align}   
    \widehat{Sf}_j(\xi)&=-2\sum_{h\in [d]}\sin^2\Big(\frac{1}{2}\sum_{\ell\in [n]}\xi_{\ell}^h \Big)\widehat{f_j}(\xi) \quad \text{for \ } \ j\in [d]^n, \xi\in \mathbb{T}_j^d; \\

 \widehat{\widetilde{A}_+ f}_{j}(\xi) & = \frac{\mathbf{i}}{n+1} \sum_{r=1}^{n+1} \widehat{f}_{j_{1:n+1\setminus\{r\}}}(\xi_{1:n+1\setminus\{r\}}) \sin\Big(\sum_{\ell\in[n+1]\setminus\{r\}}\xi_{\ell}^{{j_r}} \Big)\quad\text{for $j\in [d]^{n+1}, \xi\in \mathbb{T}_j^d$}. 
  \end{align}

