[Thm 5 of arXiv:2608.21255, 'Laws of the iterated logarithm for random Dirichlet series with general weights'] Assume that $\me [\eta]=0$, $\sigma^2={\rm Var}[\eta]\in (0,\infty)$ and that $(a_k)$ satisfies \eqref{eq:basic} and Condition A. Then
\begin{equation*}
C\Big(\Big(\Big(\frac{1}{(2v(s)\log\log v(s))^{1/2}}\sum_{k\geq 1} \frac{a_k \eta_k}{k^{1/2+s}}: s>0~\text{sufficiently close to}~ 0 \Big)\Big)=[-1,1] \quad\text{\rm a.s.}
\end{equation*}
and $$v(s)~\sim~\frac{\sigma^2 c\Gamma(1+\beta)}{(2s)^\beta},\quad s\to 0+.$$
In particular,
\begin{equation*}
\limsup_{s\to 0+}\frac{1}{(2v(s)\log\log v(s))^{1/2}}\sum_{k\geq 1} \frac{a_k \eta_k}{k^{1/2+s}}=1 \quad\text{\rm a.s.}
\end{equation*}
and
\begin{equation*}
\liminf_{s\to 0+}\frac{1}{(2v(s)\log\log v(s))^{1/2}}\sum_{k\geq 1} \frac{a_k \eta_k}{k^{1/2+s}}=-1 \quad\text{\rm a.s.}
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 14 (Necessity in Breiman's conjecture) of arXiv:2608.24616, '2608.24616'] Suppose that $T_n$ converges in distribution, along the full sequence of
positive integers, to a nondegenerate random variable.  Then there is a
unique $\beta\in[0,1)$ such that
\begin{equation}
  \overline G\in \RV_{\infty}(-\beta).

\end{equation}
Equivalently, for every $c>0$,
\begin{equation*}
  \frac{\overline G(cx)}{\overline G(x)}\longrightarrow c^{-\beta}
  \qquad (x\to\infty).
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 2 of arXiv:2604.26549, 'Existence and uniqueness results of a stochastic nonlinear heat equation with a constraint'] For each fixed $u_0\in \Vp\cap \bM$, we say that there exists a \emph{martingale solution} of \eqref{eqn-main-prob-Ito} if and only if there exist
		\begin{itemize}
			\item[$\boldsymbol{\ast}$] a stochastic basis $(\wtilde{\Omega},\wtilde{\Fn},\wtilde{\Fb},\wtilde{\Pr})$,
			\item[$\boldsymbol{\ast}$] an $\mathbb{R}^M-$valued $\wtilde{\Fb} - $Wiener process $\wtilde{W} = (W_1,\dots, W_M)$,
			\item[$\boldsymbol{\ast}$] and an $\wtilde{\Fb} - $progressively measurable process $u :[0, T] \times\wtilde{\Omega}\to D(A)$ with $\wtilde{\Pr} - $a.e. paths
			$$u(\cdot,\omega)\in C([0,T]; \Vp\cap\bM)\cap L^2(0,T;D(A))\cap L^{2p-2}(0,T;L^{2p-2}(\bO))$$ such that for all $t\in[0, T]$ and all $\psi\in L^2(\bO)$, $\wtilde{\Pr} - $a.s.
			\begin{align}
				\nonumber(u(t),\psi) & =(u_0,\psi) + \int_0^t\big( \Delta u(s) -|u(s)|^{p-2}u(s) + \big( \norm{\nabla u(s)}_{L^2(\bO)}^2 + \norm{u(s)}_{L^p(\bO)}^p \big) (u(s),\psi)ds\\ 
				& \quad + \frac{1}{2}\sum_{i=1}^M\int_0^t(\kappa_i(u(s)),\psi)ds+ \sum_{i=1}^M\int_0^t(\Nn_i(u(s)),u(s))dW_i(s). 
			\end{align}
