    \text{else,}
  \end{cases}
  \end{align*}
  yielding
  \begin{align*}
  \kappa_0
    \ = \
    \kappa(\gamma_0,r_0)
  \ = \
  \left\{ \begin{array}{l}
    \frac{1}{\alpha(1-d)}
    \ \text{ if } \
    \frac{1}{(1-d)(1-2d)}
