body:
[Lem 54 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Let $A,A_n,$ and $B$ be compact subsets of a metric space
  $(X,d^X)$ consisting of at least two elements.
  \begin{itemize}
    \item [$\mathrm{(i)}$]There exist $a_1,a_2\in A$ and $b_1,b_2\in B$ satisfying the following.
    \begin{itemize}
      \item $a_1\neq a_2,b_1\neq b_2$
      \item $d^X(a_1,b_1),d^X(a_2,b_2)\leq d_{\mathrm{H}}^X(A,B)$
    \end{itemize}
    \item [$\mathrm{(ii)}$]If $A_n$ converges to $A$ in the Hausdorff topology,
    then there exists $a_1^n,a_2^n\in A$ and $b_1^n,b_2^n\in A_n$ satisfying the following.
    \begin{itemize}
      \item $a_1^n\neq a_2^n,b_1^n\neq b_2^n$
      \item $d^X(a_1^n,b_1^n),d^X(a_2^n,b_2^n)\leq d_{\mathrm{H}}^X(A,A_n)$
      \item $\inf_n d^X(a_1^n,a_2^n),\inf_n d^X(b_1^n,b_2^n)>0$
    \end{itemize}
  \end{itemize}

[Definition defin:energyestimate of arXiv:2606.01937, 'Stationary fluctuations for an exclusion process with mass and energy conservation'] We say that the process $(\mathcal{Z}_t)_{t\in [0,T]}$ satisfies the \emph{energy estimate} if there exists a finite constant $C_0>0$ such that for any $0\le s<t\le T$, any $0<\delta\le \varepsilon <1$ and any $\varphi\in\mathscr{S}'(\mathbb{R} )$, we have 
    \begin{equation}
        \mathbb{E}\big[ (\mathcal{A}_{s,t}^{\varepsilon} (\varphi )-\mathcal{A}_{s,t}^{\delta}(\varphi ))^2\big] \le C_0\varepsilon (t-s)\|\nabla\varphi\|_{L^2}^2.
    \end{equation}

[Lemma 16 of arXiv:2609.00285, 'Multicrossing complex of knot and secant classes'] For any $\gamma\in \widetilde{\mathdutchcal C}(L,n)$
\begin{enumerate}
    \item $\bar{\bar\gamma}=\gamma$;
    \item for any $p\in\{l,r\}$ and $i\in\{1,\dots,n\}$,
$
\overline{\partial^n_{i,p}(\gamma)}=\partial^n_{n+1-i,\bar p}(\bar\gamma)
$,
where $\bar l=r, \bar r=l$;

    \item  $\overline{d(\gamma)}=(-1)^n d(\bar\gamma)$;

    \item if $\gamma\in \widetilde{\mathdutchcal D}_i(L,n)$, $i=1,\dots,n-1$, then $\bar\gamma\in\widetilde{\mathdutchcal D}_{n+2-i}(L,n)$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:several-maxima-tail of arXiv:2507.19554, 'Full extremal process in four-dimensional membrane model'] We have
		\begin{equation}
			\mcP(\exists A \subset \Xi_{N, r}: \lv A \rv > \log r, (u, v)\in A \Rightarrow h_u + h_v > 2(m_N - \lambda\log\log r)) > 1 - Ce^{-e^{c\lambda\log\log r}}
		\end{equation}
		for some $C,c > 0$, all $N \geq 1$ and all $r,\lambda \geq C$. (Proof in the paper; no proof environment follows the statement in the TeX.)

