[Theorem 6 of arXiv:2608.19560, '\textbf{Computing transient probabilities in Markovian queues with balking conditional on '] For a fixed $J \in \{1,2,\ldots\}$, $\widetilde{\bm{p}}^{(J)}(t)$ is given by

\begin{align}
\widetilde{\bm{p}}^{(J)}(0)
&=
\underbrace{
\left[
\begin{array}{cccc}
\bm{p}(0) & \bm{0} & \cdots & \bm{0}
\end{array}
\right]}_{\ds J+1},  

\\
\widetilde{\bm{p}}^{(J)}(t)
&=
\widetilde{\bm{p}}^{(J)}(T_{n-1})
\exp(\widetilde{\bm{Q}}_n^{(J)}(t-T_{n-1})),
\quad
T_{n-1} < t \leq T_n,\ n=1,2,\ldots,N,

\end{align}

where $\widetilde{\bm{Q}}_n^{(J)}$ is defined as

\begin{align}
\widetilde{\bm{Q}}_n^{(J)}
&=
\underbrace{
\left[
\begin{array}{ccccc}
\bm{Q}_n & \lambda_n\bm{B} & \bm{O} & \cdots & \bm{O}\\
\bm{O} & \bm{Q}_n & \lambda_n\bm{B} & \cdots & \bm{O}\\
\bm{O} & \bm{O} & \bm{Q}_n & \cdots & \bm{O}\\
\vdots & \vdots & \vdots & \ddots & \vdots\\
\bm{O} & \bm{O} & \bm{O} & \cdots & \bm{Q}_n
\end{array}
\right]
}_{\ds (J+1)\times(J+1)}.

\end{align}

[Theorem eq:regime of arXiv:2604.04747, 'Scaling limit and density conjecture for activated random walk on the complete graph'] \thlabel{thm:gumby}
Assume that
    \begin{align}
n^{1/2 + \varepsilon} \ll r_n = \exp(o(n^{1/3})) \text{ for some } \varepsilon >0. 
\end{align}
Then, as $n \to \infty$, 
\begin{equation}
    G_n \xrightarrow[]{d} G.
\end{equation}
Moreover, 
\begin{equation}
    \var(G_n) \to \var(G) = \frac{\pi^2}{6}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

