 Under \cref{ass:gp-true,ass:gp-eigenvalues},
    \begin{equation}
    \E\sbr{\norm[0]{\widehat f_t-f^\star}^2}
    \lesssim t^{-2\fs/(d+2\fs)}.
    \end{equation}

