[Proposition 12 of arXiv:2608.18075, '2608.18075'] On the common full measure driver event $\mathsf Y_*$ of
\Cref{lem:common-endpoint-event}, for every
$q\in(0,1/4)$ there is a measurable
finite rank field
\begin{align*}
 K_q(z,Y):E_z\longrightarrow\mathcal H
\end{align*}
with the following properties.
\begin{enumerate}[label=\textup{(\roman*)}]
\item In finitely many state tangent charts,
$K_q$ has the form
\begin{align*}
 K_q(z,Y)=\sum_{i=1}^{N_q}\chi_i(z,Y)K_i(z),
\end{align*}
where $K_i(z)$ is the smooth transport, in the corresponding tangent
trivialisation, of a fixed deterministic finite rank operator, and the
$\chi_i$ are smooth Hilbert coordinate cutoffs satisfying
$0\le\sum_i\chi_i\le1$.
\item There is a Borel good core $G_q\subset\mathsf X\times\mathsf Y$ and a
number $p_*>0$, independent of $q$, such that
\begin{align}
 \inf_{\widehat\mu\in\mathfrak I}
   (\widehat\mu\otimes\mathbf{P}_Y)(G_q)\ge p_*,
\end{align}
and, with the compensated linear residual
\begin{align*}
 R_q(z,Y)=J(z,Y)-A(z,Y)K_q(z,Y),
\end{align*}
one has
\begin{align}
 \|R_q(z,Y)\|&\le q &&\text{on }G_q,
 \notag\\
 \|R_q(z,Y)\|&\le \|J(z,Y)\|+q
 &&\text{everywhere}.                         
\end{align}
\item There is a finite constant $C_q\ge1$ (not asserted to be uniform as $q\to0$) such that
\begin{align}
 \|K_q(z,Y)h\|_{\mathcal H}
 &\le C_q\|h\|,\\
 \|D_{\mathcal H}(K_q(z,Y)h)\|_{\HS(\mathcal H)}
 &\le C_q\|h\|.
\end{align}
Here $D_{\mathcal H}$ denotes the Malliavin derivative with respect to the
fresh Wiener noise on the block.
\end{enumerate}

