[Lemma 24 of arXiv:2609.02064, 'Coalescence and fluctuations of O'Connell--Yor polymers\\ via the free-energy correlation '] For every compact $K\subset\R$,
  \begin{align}
    \sup_{u\in K}|\cZ_u^\eps-\cZ_u|\longrightarrow0.
  \end{align}
  The map $u\mapsto \cZ_u$ is continuous and strictly positive.
  Consequently, there are $\eps_K>0$ and $c_{K,\omega}>0$ such that
  \begin{align}
    \inf_{\substack{u\in K\\0\leq\eps\leq\eps_K}}\cZ_u^\eps
    \geq c_{K,\omega}.
  \end{align}

[Prop energy-est of arXiv:2411.06861, 'Quenched invariance principle for random walks in random environments admitting a cycle de'] Let $B$ be a finite subset of $\mathbb{Z}^d$. 
Consider a function $\eta: \mathbb{Z}^d\to \mathbb{R}$ with 
\begin{align*}
    \supp \eta \subset B, \quad 0\leq \eta \leq 1, \quad \eta \equiv 0  \text{ on } \partial B.
\end{align*}
Suppose $u: \mathbb{R} \times \mathbb{Z}^d \to \mathbb{R}$ is either non-negative $L^\omega$-subharmonic $(-L^\omega u\leq 0)$,  or $L^\omega$-harmonic $(L^\omega u = 0)$ on $B$. Then we have for $p \in [1,\infty]$, there exists a constant $C_{\mathrm{En}} $ such that for all $t\in I $, 
\begin{align}


  \frac{\mathcal{E}_\Gamma^\omega(\eta u)}{\abs{B}}\leq C_{\mathrm{En}} \norm{\mu^{(2), \omega}}_{p, B} \, \norm{\nabla \eta}^2_{\ell_\infty(E)}  \norm{u^2}_{p_*,B}, 
\end{align}
with $p_*= p/(p-1)$ being the H\"{o}lder conjugate of $p$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemm 3 of arXiv:2607.13849, 'Rearranged Stochastic Heat Equation with an Entropy Gradient Structure'] Let $X_t$ be the solution to \eqref{0.1} in the sense of Definition \ref{Defi 0.1}. Then, we have
\begin{equation*}
	\mathrm{d}_t\|X_{t}\|_2^{2}= - 2 \|D_{\mathbf{x}}X_{t}\|_2^2 \mathrm{d}t +
	 c_{\lambda} \mathrm{d}t + 2\langle X_t,\mathrm{d}W_t\rangle
\end{equation*} 
where $c_{\lambda}:=\sum_{k \in \mathbb{N}} \lambda_k^2.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem arm_exponents of arXiv:2604.14122, 'The scaling limit of random walk and\\ the intrinsic metric on planar critical percolation'] For every $\zeta>0$, $j\geq 1$, there exists $\rho_{\zeta,j}>0$ big enough such that
\begin{enumerate}
\item[(a)] If $j > 1$, for every non-constant sequence of colors $\sigma$ and
for all $R\geq r \geq \rho_{\zeta,j}$ 
$$\!\left(\frac{R}{r}\right)^{-\alpha_j-\zeta}\leq\mathbf{P} (j \textrm{ arms of colors given by }\sigma \textrm{ in } A(r,R) )\leq \!\left(\frac{R}{r}\right)^{-\alpha_j+\zeta},$$
where $\alpha_j=\frac{j^2-1}{12}$ are the full-plane polychromatic exponents.
\item[(b)] For every sequence of colors $\sigma$ and for all $R\geq r\geq \rho_{\zeta,j}$ 
\begin{equation*}
    \begin{split}
        \!\left(\frac{R}{r}\right)^{-\alpha^h_j-\zeta}\leq\mathbf{P} (j \textrm{ arms of colors given by }\sigma \textrm{ in } A(r,R) {\textrm{ in the half-plane}})
        \leq \!\left(\frac{R}{r}\right)^{-\alpha^h_j+\zeta},
    \end{split}
\end{equation*}
where $\alpha^h_j=\frac{j(j+1)}{6}$ are the half-plane exponents. 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eq:equiv-thom of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] We define the \emph{equivariant Thom spectrum functor}
    \begin{equation}
        \ul{\textup{Th}}^\otimes\colon\ul\Spc^\otimes_{{\vphantom{\textup{t}}\smash{\textup{Orb}}}\triangleright\textup{Glo}/\ul\textup{VRep}^{\oplus}}\to{\mathpalette\ulhelper{\mathfrak S\kern-.5pt\mathfrak p}}\hbox{\rule[-2pt]{0pt}{0pt}}^\otimes
    \end{equation}
    as the unique ${\vphantom{\textup{t}}\smash{\textup{Orb}}}$-cocontinuous symmetric monoidal extension of ${\mathpalette\ulhelper{\mathfrak J}}\hbox{\rule[-2pt]{0pt}{0pt}}^\otimes$.

