[Proposition prop:lil of arXiv:2411.02362, 'Limit theorems for random Dirichlet series: boundary case'] Assume that $\mathbb{E}[\eta]=0$, $\sigma^2=\mathbb{E} [\eta^2]\in (0,\infty)$ and let $\alpha>-1/2$. Then, almost surely,
\begin{equation*}
C\bigg(\bigg(\Big(\frac{2^{2\alpha}}{\sigma^2 \Gamma(1+2\alpha)}\frac{s^{1+2\alpha}}{\log\log 1/s}\Big)^{1/2}\sum_{k\geq 2}\frac{(\log k)^\alpha}{k^{1/2+s}}\eta_k: s\in (0, {\rm e}^{-1})\bigg)\bigg)=[-1,1],
\end{equation*}
where $\Gamma$ is the Euler gamma function. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 2 of arXiv:2506.18313, 'A stochastic model for the diffusion of competing opinions with trend-following, oppositio'] For any $n\ge 1$, we have
\begin{equation}

 \dE[(N_n,M_n)] = \dE(N_n)(1,-1)+T_n(0,1)
\end{equation}
and
\begin{equation}

 \dE[(N_n,M_n)^T(N_n,M_n)] = \dE(N_n^2)\left(\begin{array}{cc}
1 & -1 \\
-1 & 1 
\end{array}
\right)+T_n\dE(N_n)\left(\begin{array}{cc}
0 & 1 \\
1 & -2
\end{array}
\right)
+T_n^2\left(\begin{array}{cc}
0 & 0 \\
0 & 1
\end{array}
\right),
\end{equation}
where
\begin{equation}

 \dE[N_n] = \frac{(\theta+T_0)_n}{(T_0)_n}\left(N_0-\frac{a}{1-\theta} T_0\right)+\frac{a}{1-\theta}T_n,
\end{equation}
and
\begin{eqnarray}

 \dE[N_n^2]  = \frac{(2\theta+T_0)_n}{(T_0)_n}\Bigg[ N_0^2+  \frac{1}{(2\theta+T_0)}\left( N_0 - \frac{a}{1-\theta}T_0\right) \left[ (2a-1)T_0+(\theta+T_0)\left(\frac{2a(2\theta+T_0)}{(\theta-1)} \right) \right] \notag \\
+  \frac{a(1-2a)}{(1-\theta)(2\theta-1)} \left(T_0 -  \frac{(T_0)_{n+1}}{(2\theta+T_0)_n}\right)- \frac{a^2}{(1-\theta)^2} \frac{\Gamma(T_0+2)}{\Gamma(T_0)} \left(1-\frac{(T_0+2)_{n-1}}{(2\theta+T_0)_{n-1}} \right)  \notag\\
- \frac{(\theta+T_0)}{(2\theta+T_0)}\left( N_0 - \frac{a}{1-\theta}T_0\right) \left[ (2a-1)\frac{(\theta+T_0+1)_{n-1}}{(2\theta+T_0+1)_{n-1}}+ \frac{2a}{\theta-1}\frac{(\theta+T_0+1)_{n}}{(2\theta+T_0+1)_{n-1}}\right]  \Bigg].
\end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

