body:
[Lemma intBound of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] For any interval $I=(a,b)\subset\mathbb{R}$ where $a$ and $b$ are allowed to be infinite, consider the integral equation:
    \begin{equation}
h(x)=\int_a^xK(x,t)\phi(t)\left[J(t)+h(t)\right]dt.
    \end{equation}
Assume the following conditions hold:
\begin{itemize}
    \item The functions $\phi$ and $J$ are continuous on $I$.
    \item The kernel $K(x,t)$ and its first two partial $x$ derivatives are all continuous for any $(x,t)\in I^2$. Additionally, $K(x,x)=0$ for any $x\in I$.
    \item There exist positive continuous functions $P_0,~P_1$ and nonnegative continuous $Q$ on the real line such that for any $(x,t)\in I^2$,
    \begin{equation}
        |K(x,t)|\le P_0(x)Q(t),~~|\partial_1K(x,t)|\le P_1(x)Q(t).
    \end{equation}
    \item For any $x\in I$, $\Phi(x):=\int_a^x|\phi(t)|dt$ is convergent. Moreover, 
    \begin{equation}
        \kappa:=\sup_{x\in I}|Q(x)J(x)|~~and~~\kappa_0:=\sup_{x\in I}|P_0(x)Q(x)|
    \end{equation} are all finite.
    \item If $a=-\infty$, then additionally there exist $C\ge0$ and $R>0$ such that $|Q(x)|\le C$ for any $x\le-R$.
\end{itemize}
Then there is a unique solution $h$ of (equation I-equa1 of the paper) such that
\begin{equation}
    \frac{|h(x)|}{P_0(x)},~\frac{|h'(x)|}{P_1(x)}\le\frac{\kappa}{\kappa_0}\left(e^{\kappa_0\Phi(x)}-1\right).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 3 of arXiv:2608.01419, 'A model of opinion dynamics evolving via a preferential attachment mechanism involving mul'] Recall the function $f$ defined via \eqref{X_{n+1}_conditional_distribution}, and the function $g$ as defined in \eqref{g_defn}. Assume, throughout, that $p\in(0,1)\setminus\{1/2\}$. Then, in each of the following cases, the function $G$, defined in \eqref{G_defn}, has a unique root in $[0,1]$ (lying strictly between $0$ and $1$):
\begin{enumerate}
\item when $f(x)=c$ for all $x\in[0,1]$, for some $c\in(0,1)$;
\item when $f(x)=x$ for all $x\in[0,1]$, and $p\in(0,1/2)$;
\item when $f(x)=x$ for all $x\in[0,1]$, $p\in(1/2,1)$ and either
\begin{equation}
\beta\geqslant \frac{(2p-1)(k-1)}{4(1-p)},
\end{equation}
or \eqref{beta_p_cond} does not hold and one of the following two inequalities is true:
\begin{align}
{}&G\left(\frac{1}{2}-\frac{\sqrt{3(k-1)(2p-1)\{(k-1)(2p-1)-4\beta(1-p)\}}}{6(k-1)(2p-1)}\right)>0,_cond}\\
{}&G\left(\frac{1}{2}+\frac{\sqrt{3(k-1)(2p-1)\{(k-1)(2p-1)-4\beta(1-p)\}}}{6(k-1)(2p-1)}\right)<0;_cond}
\end{align}
\item  when $f(x)=e^{x-1}$ for all $x\in[0,1]$, $k\geqslant 2$, $p\in(0,1/2)$ and $\beta>k(1-2p)$. 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

