body:
[Lemma AJSJAsd of arXiv:2603.12774, 'Synchronization by noise for stochastic differential equations driven by fractional Browni'] Let \( H \in (0,1) \). For \( \omega \in C_0^\infty(\mathbb{R}^-, \mathbb{R}^d) \), define
	\begin{align}
		\mathcal{D}_H \omega(t)
		:= \frac{1}{\alpha_H} \int_{-\infty}^{0}
		(-r)^{H - \frac{1}{2}}
		\left( \dot{\omega}(t + r) - \dot{\omega}(r) \right)
		\, \mathrm{d}r, 
		\quad t \le 0.
	\end{align}
	This operator extends continuously from \(C_0^\infty(\mathbb{R}^-, \mathbb{R}^d) \) to \( \mathcal{B}_H \) and satisfies the following properties.
	\begin{itemize}
		\item The map
		\begin{align}
			\mathcal{D}_H : \mathcal{B}_H \longrightarrow \mathcal{B}_{1-H}
		\end{align}
		admits a bounded inverse.
		\item There exists a unique Gaussian measure \( \mathbf{P} \) on \( \mathcal{B}_H \) such that the associated canonical process is a time-reversed Brownian motion.
		\item The canonical process associated with the pushforward measure \( (\mathcal{D}_H)_{\ast} \mathbf{P} \) on \( \mathcal{B}_{1-H} \) is a time-reversed fractional Brownian motion with Hurst parameter \( H \).
		\item The quadruple \( \left( \mathcal{B}_H, \{P_t\}_{t \ge 0}, \mathbf{P}, \{\vartheta_t\}_{t \ge 0} \right) \) forms a stationary noise process in the sense of Definition~(SDS of the paper), where:
		\begin{enumerate}
			\item the shift maps \( \{\vartheta_t\}_{t \ge 0} \) on \( \mathcal{B}_H \) are defined by
			\begin{align}
				\vartheta_t \omega(s) := \omega(s - t) - \omega(-t), \quad s \le 0.
			\end{align}
			\item for every \( t \ge 0 \), the map \( P_t : \mathcal{B}_H \times \mathcal{B}_H \to \mathcal{B}_H \) is given by
			\begin{align}
				P_t(\omega^-, \omega^+)(s)
				:= 
				\begin{cases}
					\omega^+(-s - t) - \omega^+(-t), & -t \le s \le 0, \\[4pt]
					\omega^-(s + t) - \omega^+(-t), & s \le -t.
				\end{cases}
			\end{align}
		\end{enumerate}
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 50 ({\cite[Lemma 3.1) of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] {Cr18}}]
Let $A$ be a non-empty open subset of $F$. 
For any measurable $f:F\to\mathbb{R}_{\geq 0}$, it holds that
\begin{equation*}
    G_A f(y)=\int_F g_A(y,z)f(z)\mu(dz), \quad\forall y\in F,
\end{equation*}
where
\begin{equation*}
    g_A(y,z):=\frac{R(y,A)+R(z,A)-R_A(y,z)}{2},
\end{equation*}
with
\begin{equation*}
    R_A(y,z):= \sup\{\calE(f,f)^{-1} : f \in \calF, f(y)=1, f(z)=0, f|_{A}\;\;\rm{constant} \}
\end{equation*}
being the resistance between $y$ and $z$ in the network with $A$  `fused'. 
Note that the function $g_A$ satisfies $0 \le g_A(y,z)=g_A(z,y) \le g_A(y,y) = R(y,A)$ and
\begin{equation}
    |g_A(y,z)-g_A(y,w)|\leq R(w,z), \quad \forall y, z, w \in F.
\end{equation}
Furthermore, $g_{x}$ is given by
\begin{equation*}
    g_{x}(y,z):=\frac{R(x,y)+R(x,z)-R(y,z)}{2}.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:dyadiccorona of arXiv:2602.08591, 'The Yang--Mills measure on compact surfaces as a \\ universal scaling limit of lattice gau'] We denote by $F^N$ the faces of $\Lambda^N$. 
Fix an arbitrary $\varepsilon>0$, then there exists $c_\varepsilon<C_\varepsilon$ such that for every $N$, for any face $\square$ of the grid $\Lambda^N$ that does meet $\cup_{a\in \mathrm{Crit}(f)_1} B(a,\varepsilon)$, we have
\begin{equation}
c_\varepsilon 2^{-2N}\leqslant \int_\square \sigma \leqslant C_\varepsilon 2^{-2N}.     
\end{equation}

Moreover, for all $N$, for all squares that are at approximate distance
$2^{-j}$ (measured in the coordinates $(r,\theta)$) of some given singular point in $\Psi\left(\mathrm{Crit}(f)_1 \right)$ $j=1,\dots,N$,  
\begin{equation}
c2^{j}2^{-2N} \leqslant
 \int_\square \sigma\leqslant C 2^j 2^{-2N}.   
\end{equation}
where the constants $c,C$ do not depend on $j,N$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 20 of arXiv:2607.21759, 'Marchenko--Pastur law for tensor powers of exchangeable unconditional vectors'] Let $L = L_n$ and $d = d_n$ be sequences of numbers, and we assume $d \geq 1$. Provided that $Ld^2/n\to 0$, we have \begin{equation}
        \lim_{n \to \infty} \biggl(1 + \frac{Ld}{n}\biggr)^{d} = 1. 
    \end{equation} It follows that when $d = o(\sqrt n)$, $\frac{n\dotsm (n-d+1)}{n^d} \to 1$, $\binom{n-d}{d} / \binom{n}{d} \to 1$, and $\binom{n}{d} / \binom{n + d - 1}{d} \to 1$.

