[Theorem t:main theorem of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Suppose that $\Phi$ is a locally absolutely square-integrable invariant random complex measure, and let $K$ be an invariant transport kernel. We distinguish the following two cases. 
\begin{enumerate}[label=(\roman*)]
    \item Let $p\in[-d,\infty)$, and assume that either Condition~(c:condition square-integrable general with p of the paper) or Condition~(c:condition square-integrable Markov with p of the paper) holds. Further, assume that, for $q\in\N_0$ with $q<\max(\tfrac{d+p}{2},1)$, the random complex (tensor-valued) measure $\Psi_q$ defined by
    \begin{equation}
        \Psi_q(dy) := \bigg(\int x^{\otimes q} \, K^\ast(y, dx)\bigg)\, \Phi(dy), \quad y\in\R^d, 
    \end{equation}
    is (beyond) $(p-2q)$-uniform. Then $K\Phi$ is (beyond) $p$-uniform.

    \item Let $\varepsilon>0$, assume that Condition~(c:condition square-integrable stealthy of the paper) holds, and assume that $\Psi_q$ is $\infty$-uniform with radius $\varepsilon$ for every $q\in\N_0$. Then $K\Phi$ is also $\infty$-uniform with radius $\varepsilon$.
\end{enumerate}
\begin{proof}
    The proof mainly relies on the more general result of the following Theorem~(t:main theorem formula of the paper). Let $n:= \max(\lceil\tfrac{d+p}{2}-1\rceil, 0)$, i.e., $n=\lfloor\tfrac{d+p}{2}\rfloor$ if $\tfrac{d+p}{2}\notin\N$, and $n=\tfrac{d+p}{2}-1$ if $\tfrac{d+p}{2}\in\N$. For the first part, i.e., when Condition~(c:condition square-integrable general with p of the paper) or~(c:condition square-integrable Markov with p of the paper) holds for some $p\in[-d,\infty)$, Theorem~(t:main theorem formula of the paper) implies, with convergence in $L^2$ as $r\to\infty$, that
    \begin{equation}
        K\Phi(f_r) = \sum_{q=0}^{n}\frac{1}{q!} \Psi_q\big(f_r^{(q)}\big) + o\Big(r^{\tfrac{d-p}{2}}\Big),
    \end{equation}
    where $f\in\cC_c^\infty(\R^d, [0,\infty))$, $f\neq0$, and $f_r^{(q)}$ denotes the (possibly tensor-valued) $q$-th derivative of $f_r$. As defined in (equation e: tensor valued measure of the paper), we evaluate the integral of a tensor-valued complex measure of a tensor-valued function using the inner product. We obtatin that, as $r\to\infty$,
    \begin{align}
        \frac{\BV[K\Phi(f_r)]}{r^{d-p}} &\leq (n+2)^2\sum_{q=0}^{n}\frac{\BV\big[\Psi_q\big(f_r^{(q)}\big)\big]}{q!^2r^{d-p}}  + o(1)\nonumber\\
        &\leq (n+2)^2\sum_{q=0}^{n}\frac{\BV\big[\Psi_q\big(f^{(q)}(\tfrac{\cdot}{r})\big)\big]}{q!^2r^{d-(p+2q)}}  + o(1),
    \end{align}
    where we also used Remark~(r: f_r formulas of the paper). Now the assertion follows from Theorem~(t:asymptotic variance test function of the paper) since we assumed that $\Psi_q$ is (beyond) $(p-2q)$-uniform for $q\in\{0,...,n\}$.

    The second part, i.e., where we assume that Condition~(c:condition square-integrable stealthy of the paper) holds for some $\varepsilon>0$, follows from the second statement in Theorem~(t:main theorem formula of the paper). Let $f\in L^1(\R^d,[0,\infty))$ be a function such that $\hat{f}\in\cC^\infty$ with $\supp(\hat{f})\subseteq B_\varepsilon$ and $\hat{f}(k)\neq0$ for all $k\in B_{\varepsilon-\vartheta}$ and some $\vartheta\in(0, \varepsilon)$. Then, by Theorem~(t:main theorem formula of the paper), with convergence in $L^2$,
    \begin{equation}
        K\Phi(f) = \sum_{q=0}^{\infty}\frac{1}{q!} \Psi_q\big(f^{(q)}\big).
    \end{equation}
    Note that the Paley-Wiener theorem ensures that $f\in\cC^\infty$. Now Theorem~(t: stealthy characterization of the paper) implies that the RHS of~(equation e:stealthy taylor of the paper) is deterministic, as we assumed that $\Psi_q$ is $\infty$-uniform with radius $\varepsilon$ for every $q\in\N_0$, and that $\hat{f}$, and therefore also $\widehat{f^{(q)}}$ has support in $B_\varepsilon$ for every $q\in\N_0$. Hence, the LHS (left-hand side) must also be deterministic, which implies that $K\Phi$ is $\infty$-uniform with radius $\varepsilon-\vartheta$ by Theorem~(t: stealthy characterization of the paper), as $\hat{f}(k)\neq 0, k\in B_{\ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2604.17253, 'Large Deviations for the Nonlinear Schrödinger Equation with Randomized Quasi-Periodic Ini'] The {\em branch set} $\Gamma^{(k)}$ is defined recursively by
\begin{align*}
\Gamma^{(k)} =
\begin{cases}
\{0,1\}, & k = 1; \\
\{0\} \cup \bigl(\Gamma^{(k-1)}\bigr)^3, & k \ge 2,
\end{cases}
\end{align*}
where $0$ corresponds to a linear node and $1$ corresponds to a cubic interaction node.

[Proposition 41 (Completed Harish--Chandra reflection) of arXiv:2608.29585, '2608.29585'] For every zero-framed knot $K$ and every integer $n\ge2$, let
\begin{equation}
 f_K=\widehat\hc
 \bigl(J_K(\mathfrak{gl}_n;q^2)\bigr).
\end{equation}
Then
\begin{equation}
 \mathsf D_c^*f_K=f_K\quad(c\in\Z),
 \qquad
 \mathsf I^*f_K=f_K.
\end{equation}

[Theorem 8 of arXiv:2506.13347, 'Ergodic theorem for the differential equations with interaction'] The multiple integrals $m_k$ of the braid satisfy the following limit behavior
\begin{equation}
\lim\limits_{t\rightarrow\infty} \frac{m_k(t)}{t^k}
=\frac{1}{k!}\omega(u_{j_1}, u_{j'_1})\cdots\omega(u_{j_k}, u_{j'_k})
,\,\, k=2,\cdots, n.
\end{equation}

