[Proposition 9 (Diffusion matrix at equilibrium) of arXiv:2609.03847, 'A counterexample to McKean's conjecture for the Landau-Coulomb equation'] There exist constants $c,C>0$ such that,
		\begin{equation}

			A[M](v) 	=
			\frac{1}{|v|}\Pi^\perp_v +\frac{1}{|v|^3}	\left(	3\frac{v\otimes v}{|v|^2}-\Id	\right) +	\mathcal E_A(v)
			\qquad \text{for $|v |>1$},
		\end{equation}	where
	\begin{align*}
			|\mathcal E_A(v)|	\leq	C \exp \lp -c|v|^2 \rp.
	\end{align*}
	In particular,
		\begin{equation}

			A[M](v) :(v\otimes v)	=	\frac{2}{|v|}+ 	O  \lp \exp \lp -c|v|^2\rp \rp.
		\end{equation}

