[Theorem THm-scal-eps of arXiv:2605.15742, 'Turbulent stretching of FENE dumbbell polymer model via special stochastic scaling and sin'] (Stochastic scaling limit)
   Let  $f_0\in H.$       For any $\varepsilon>0,$ there exists a unique $f_\varepsilon$ such that
    \begin{itemize}
        \item a.s.  $f_\varepsilon \in L^2(0, T;V) \cap C([0, T];H),$
        \item   $f_\varepsilon$ satisfies:  $f_\varepsilon(0)=f_0$ and a.s. for any $\Phi \in V$ it holds
        \begin{align}
    \langle\dfrac{\partial f_\varepsilon}{\partial t},\Phi\rangle_{V^\prime,V}=-\int_{\mathbb{T}^2}\int_D\big ( \dfrac{\kappa}{\beta} f_\varepsilon F(r)r+\dfrac{1}{\beta}\nabla_rf_\varepsilon+ \dfrac{1}{2}\varphi_\varepsilon^2 A(r) \nabla_rf_\varepsilon\big)\cdot \nabla_r\left(\dfrac{\Phi}{\mathbf{M}}\right) drdx.
\end{align}
    \end{itemize}
      Moreover, the following convergence holds, as $N\to +\infty$
    \begin{align}
        f^\varepsilon_N(t) \rightharpoonup f_\varepsilon(t) \text{ in } L^2(\Omega,H) \text{ for any } t\in [0,T],
    \end{align}
  where $(f^\varepsilon_N)_{N}$ is unique quasi-regular weak solution (in the sense of (Def-sol-QR-* of the paper)) to       (equation Ito-FP_eps-V2 of the paper).

[Lemma eq:trace-derivative-1 of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[lemma]{lem:trace-derivatives}
For \(r=1\),
\begin{equation}
 \abs{D\operatorname{Tr} f(A)[C]}
 \le C_f\sqrt n\left\lVertC\right\rVert_{\mathrm{HS}}.
\end{equation}
For \(2\le r\le m+1\),
\begin{equation}
 \abs{D^r\operatorname{Tr} f(A)[C,\ldots,C]}
 \le C_{f,r}\left\lVertC\right\rVert_{\mathrm{HS}}^2\left\lVertC\right\rVert_{\mathrm{op}}^{r-2}.
\end{equation}
The constants are uniform in \(n,A,C\).

