\begin{equation}
\begin{split}
&\sum_{i\neq j} \mathbf{P}(B_{i,j}^{(d)} \textrm{ is important})^2 \mathbf{P}\!\left(B_i \textrm{ is } B_i^{(d+1)}\textrm{-important}\right)\mathbf{P}\!\left(B_j \textrm{ is } B_j^{(d+1)}\textrm{-important}\right)\\
