[Theorem Thm: Taylor Lipschitz of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] For $m\ge 0$ and $\tau_0\in{\mathcal T}$, let $H_{z_1z_2}$ be the expression defined in (equation Eq: def H of the paper). In addition let $\mathbb X:{\mathcal F}^{\le m}\to\mathbb{R}$ be a multiplicative functional. Then
		\begin{align}
			&\Upsilon_{\tau_0}(z_2)-\sum_{w\in{\mathcal F}^{\leq m}}\frac{\Upsilon_{w\curvearrowright\tau_0}(z_1)}{\pi(w)} \, \mathbb X(w)=\sum_{w\in{\mathcal F}^{\leq m}}H_{z_1z_2}(w;\tau_0) \cdot z^{[m+1-|w|]}\, \mathbb X(w),
		\end{align}
		where $\pi(w)$ is defined in (equation Eq: permutation factor of the paper) and $z^{[i]}$ in (equation eq:zk12 of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm self-adjBS of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] For $\mu > -\frac12$ and ${\boldsymbol{\kappa}} \in {\mathbb R}^{d_2-1}$ with ${\kappa}_i > -1$, $1 \le i \le d_2-1$,
\begin{align*} 
  {\mathfrak D}_{\mu,{\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \Sigma} & = \frac{1}{|{\bm y}|} \left[ \frac{1}{{\bm W}_{\mu,{\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \Sigma} ({\bm x},{\bm y})}
    \sum_{i=1}^{d_1} \partial_{x_i} \left({\bm W}_{\mu+1,{\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \Sigma} ({\bm x},{\bm y}) \partial_{x_i} \right)  
     + \sum_{1 \le i < j \le d_1} \big( D_{i,j}^{({\bm x})} \big)^2 \right]\\
   & +  \frac{1}{{\bm W}_{\mu,{\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \Sigma} ({\bm x},{\bm y})} \sum_{i=1}^{d_2-1} (\partial_{y_i} - \partial_{y_{d_2}})
       y_i  {\bm W}_{\mu,{\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \Sigma} ({\bm x},{\bm y}) (\partial_{y_i} - \partial_{y_{d_2}}) \notag \\
  & +  \frac{1}{|{\bm y}|^{d_1+1} {\bm W}_{\mu,{\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \Sigma} ({\bm x},{\bm y})} 
         \big(|{\bm y}| \partial_{y_{d_2}} +{\langle} {\bm x}, \nabla_{{\bm x}}{\rangle} \big) |{\bm y}|^{d_1}
              {\bm W}_{\mu,{\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \Sigma} ({\bm x},{\bm y}) \big(|{\bm y}| \partial_{y_{d_2}} + {\langle} {\bm x}, \nabla_{{\bm x}}{\rangle} \big). \notag
\end{align*}

