[Prop eq:diffrel_green of arXiv:2606.06187, 'How to Study Reflected Brownian Motion in a Quadrant via Kernel Functional Equations?\\ \m'] The function $\widetilde g_1$ can be meromorphically continued to $\mathbb{C}$ through the difference equation
\begin{equation}
\widetilde g_1(\omega+2\beta)
=
\widetilde G(\omega)\,\widetilde g_1(\omega)
+
\widetilde H(\omega),

\end{equation}
where
\[
\widetilde G(\omega)
:=
\frac{k_1(\omega)\,k_2(\widetilde\zeta(\omega))}
{k_2(\omega)\,k_1(\widetilde\zeta(\omega))}
\]
and
\begin{equation}
\widetilde H(\omega)
:=
\frac{k_2(\widetilde\zeta(\omega))}{k_1(\widetilde\zeta(\omega))
} \left(
\frac{
\,e^{x(e^{i\omega})a+y(e^{i\omega})b}}{k_2(\omega)}
-
\frac{\,e^{x(e^{i\widetilde\zeta(\omega)})a+
y(e^{i\widetilde\zeta(\omega)})b}
}{
\,k_2(\widetilde\zeta(\omega))} \right) .

\end{equation}
The functional equation (equation feg:revetement of the paper) and the invariance properties (equation invg:relevement of the paper) remain valid on the whole complex plane $\mathbb{C}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma11 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Let $\varphi$ be a characteristic satisfying (C1 of the paper). Then, for every  $t \in \mathbb{R}$, $u \in \mathcal{I}$ and $k \in \mathbb{N}_{0}$,
\begin{align}
\varphi_{u}^{(k)}(t) \stackrel{a.s.}{=} \mathbb{E}[\varphi_{u}(t) \mid \mathcal{A}_{u}^{(k-1)}].
\end{align}

[Proposition 11 of arXiv:2512.08745, 'Variance strikes back: sub-game--perfect Nash equilibria in time‑inconsistent $N$‑player g'] Let {\rm\Cref{assumpNecessity_meanField}} hold, and let $\hat\alpha$ be a sub-game--perfect mean-field equilibrium. Then, there exists a quadruple $(Y^{1}, Z^{1,1}, M^{1,\star}, \Z^{1,m,1,\star,})$ satisfying the following {\rm BSDE} system
\begin{align}
\notag Y^1_t &= g\big(X^1_{\cdot \land T}, \cL_{\hat\alpha}(X^1_{\cdot \land T})\big) + G\big(\varphi_1(X^1_{\cdot \land T}),\varphi_2(\cL_{\hat\alpha}(X^1_{\cdot \land T}))\big)+ \int_t^T f_s\big(X^1_{\cdot \land s},\cL_{\hat\alpha}(X^1_{\cdot \land s},\hat\alpha_s),\hat\alpha_s\big) \d s \\
\notag &\quad  - \frac{1}{2} \int_t^T \partial^2_{m,m}G\big(M^{1,\star}_s,N^{\star}_s\big) \big\|Z^{1,m,1,\star}_s\big\|^2 \d s - \int_t^T Z^{1,1}_s \cdot \d \big(W_s^{\hat\alpha}\big)^1, \; t \in [0,T], \; \P \text{\rm--a.s.}, \\
\notag M^{1,\star}_t &\;= \varphi_1(X^1_{\cdot \land T}) - \int_t^T Z^{1,m,1,\star}_s \cdot \d \big(W_s^{\hat\alpha}\big)^1, \; t \in [0,T], \; \P \text{\rm--a.s.},\\
N^{\star}_t &\coloneqq \varphi_2(\cL_{\hat\alpha}(X^1_{\cdot \land T})), \; t \in [0,T],\; \P\text{\rm--a.s.},
\end{align}
where, for notational convenience, we write $W^{\hat\alpha} \coloneqq W_s^{\hat\alpha,\xi}$ with $\xi_t \coloneqq \cL_{\hat\alpha}(X^1_{\cdot \land t}, \hat\alpha_t)$ for each $t \in [0,T]$. Furthermore, there exists some $p \geq 1$ such that
\begin{align*}
&\sup_{\alpha \in \cA^\smalltext{1}} \E^{\P^{\smalltext{\alpha}}} \Bigg[ \sup_{t \in [0,T]} \big|Y^{1}_t\big|^p + \bigg(\int_0^T \big\|{Z}_t^{1,1}\big\|^2 \d t\bigg)^\frac{p}{2} \Bigg] +\esssup_{\alpha \in \cA^\smalltext{1}} \Bigg\{\sup_{t \in [0,T]}  \big| M^{1,\star}_t\big| + \sup_{\tau \in \cT_{0,T}} \E^{\P^{\smalltext{\alpha}\smalltext{,}\smalltext{1}\smalltext{,}\smalltext{\tau}}_{\smalltext{\cdot}}} \bigg[ \int_\tau^T \big\|Z^{1,m,1,\star}_t\big\|^2 \d t \bigg] \Bigg\} < +\infty.
\end{align*}
The value process satisfies $V^1_t = Y^{1}_t$, $\P\text{\rm--a.s.}$, for any $t \in [0,T]$, and the sub-game--perfect mean-field equilibrium $\hat\alpha$ satisfies
\begin{align*}
\hat\alpha_t \in \argmax_{a \in A} \big\{h_t\big(X^1_{\cdot \land t}, \cL_{\hat\alpha}(X^1_{\cdot \land t},\hat\alpha_t), Z^{1,1}_t, a\big)\big\}, \; \text{\rm for}\; \d t \otimes \d \P\text{\rm--a.e.} \; (t,\omega) \in [0,T] \times \Omega.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemm 11 of arXiv:2605.23292, 'Second-order Poincaré inequalities and localization on the Poisson space'] (localization of  mixed moments of first and  second order difference operators)
Assume the score $\xi: (X \times \R \times \MM) \times \mathbf{N} \to \R$ satisfies $BL(\theta,\theta')$ space-time localization on  $(X,d,\nu) \times (\R, \mu)$ as in Def.~\ref{def:space-time-loc} with short-range scores $(\xi^{[r]})_{r>0},(\xi^{(s)})_{s \in \R}$ and functions $\psi$ and $\phi$. Put $C_p=(36p-20) (M_{5,X}^\xi)^{(p-1)/p}$ for $p \in \N$.

\noindent (i) 
For all non-negative integers $p_1, p_2, p_3, p_4$ satisfying $p_1 + p_2+ p_3+ p_4 = p-1 >0$, there is a constant $c>0$ depending only on $p$ such that for 
 all $(z_1,t_{z_1}),(z_2,t_{z_2}),(z_3,t_{z_3}),(z_4,t_{z_4}),(x,t_{x}) \in X \times \R$
and   for all $r > 0$
\begin{multline*}
\sup_{\substack{\mathcal{A}_i \subset \{(z_1,t_{z_1}),\hdots,(z_4,t_{z_4})\},\\i=1,\hdots,4}}
\bigg|\E \Pi_{i = 1}^4 \left(D_{(x,t_{x},M_x)} \xi((z_i, t_{z_i},M_{z_i}), \tP \cup \tA_i))\right)^{p_i}\\
 - \E \Pi_{i = 1}^4 \left(D_{(x,t_{x},M_x)} \xi^{[r]}((z_i, t_{z_i},M_{z_i}), \tP \cup \tA_i))\right)^{p_i} \bigg| \leq c C_p \psi(r)^{1/p}
\end{multline*}
and for all $s \in \R$
\begin{multline*}
\sup_{\substack{\mathcal{A}_i \subset \{(z_1,t_{z_1}),\hdots,(z_4,t_{z_4})\},\\i=1,\hdots,4}}
\bigg|\E \Pi_{i = 1}^4 \left(D_{(x,t_{x},M_x)} \xi((z_i, t_{z_i},M_{z_i}), \tP \cup \tA_i))\right)^{p_i}\\
 - \E \Pi_{i = 1}^4 \left(D_{(x,t_{x},M_x)} \xi^{(s)}((z_i, t_{z_i}, M_{z_i}), \tP \cup \tA_i))\right)^{p_i} \bigg| \leq  c C_p\phi(s)^{1/p}.
\end{multline*}

\noindent (ii) 
For all non-negative integers $p_1, p_2, p_3, p_4$ satisfying $p_1 + p_2+ p_3+ p_4 = p-1$,
there is a constant $c>0$ 
depending only on $p$  such that for all $(z_1,t_{z_1}),$ $(z_2,t_{z_2}),$ $(z_3,t_{z_3}),$ $(z_4,t_{z_4}),$ $(x,t_x),$ $(y,t_y) \in X \times \R$
and all $r > 0$
\begin{multline*}
\sup_{\substack{\mathcal{A}_i \subset \{(z_1,t_{z_1}),\hdots,(z_4,t_{z_4})\},\\i=1,\hdots,4}}
\bigg|\E \Pi_{i = 1}^4 \left(\DD_{(x,t_x,M_x),(y,t_y,M_y)} \xi((z_i, t_{z_i}, M_{z_i}), \tP \cup \tA_i))\right)^{p_i}  \\
 - \E \Pi_{i = 1}^4 \left(\DD_{(x,t_x,M_x),(y,t_y,M_y)} \xi^{[r]}((z_i,t_{z_i}, M_{z_i}), \tP \cup \tA_i))\right)^{p_i} \bigg| \leq c C_p \psi(r)^{1/p}
\end{multline*}
and for all $s \in \R$
\begin{multline*}
\sup_{\substack{\mathcal{A}_i \subset \{(z_1,t_{z_1}),\hdots,(z_4,t_{z_4})\},\\i=1,\hdots,4}}
\bigg|\E \Pi_{i = 1}^4 \left(\DD_{(x,t_x,M_x),(y,t_y,M_y)} \xi((z_i, t_{z_i}, M_{z_i}), \tP \cup \tA_i))\right)^{p_i}  \\
 - \E \Pi_{i = 1}^4 \left(\DD_{(x,t_x,M_x),(y,t_y,M_y)} \xi^{(s)}((z_i,t_{z_i}, M_{z_i}), \tP \cup \tA_i))\right)^{p_i} \bigg| \leq c C_p \phi(s)^{1/p}.
\end{multline*}

[Proposition prop:non-crossing of arXiv:2606.12143, 'Continuous stochastic flows driven by white noise and their duals'] Suppose that $(\sigma,b)$ satisfy Assumption~(assu:H of the paper) and conditions~(item:1a of the paper)--(item:1d of the paper). Then, almost surely, for all $(a_1,r_1),(a_2,r_2)\in {\mathbb R}^2$ and all $y,z\in {\mathbb R}$,
    \begin{align*}
        \overline\mathcal S_{r_1,y}(a_1)< \overline\mathcal S_{r_2,y}(a_2) \ \Longrightarrow \ \overline\mathcal S_{r_1,z}(a_1)\le \overline\mathcal S_{r_2,z}(a_2).
    \end{align*}

[Lemma 5 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] Set
\begin{equation}
  c_\alpha
  :=\frac1\pi\int_0^\infty\frac{1-\cos u}{u^\alpha}\,\mathrm du
  =-\frac{1}{2\Gamma(\alpha)\cos(\pi\alpha/2)}>0.

\end{equation}
With respect to Lebesgue measure on \(\mathbb R\setminus\{0\}\), the process
\(Z\) killed at \(T_0\) has Green density
\begin{equation}
  g_\alpha(x,y)
  =c_\alpha\bigl(
       |x|^{\alpha-1}+|y|^{\alpha-1}-|x-y|^{\alpha-1}
     \bigr),
  \qquad x,y\neq0.

\end{equation}

[Theorem 6 of arXiv:2606.16083, 'Eyring--Kramers asymptotics for infinite-dimensional stochastic gradient systems'] Let $U\in C^2(B)$ satisfy \eqref{Eq:Th_Assumption}. Then the set $\mathcal{S}:=\left\{x\in H:\nabla F=0\right\}$ is compact in $B$, and for all $r>0$ there exist constants $\lambda,\beta_0>0$, such that
   \begin{align}

     \frac{1}{\beta} \int_B \|\nabla \Psi\|_H^2\mathrm{d}\mu_\beta\geq \lambda \beta \|\Psi\|^2_{L^2(\mu_\beta)}
   \end{align}
    for all $\beta\geq \beta_0$ and $\Psi\in \mathrm{Lip}_b(B)$ with $\mathrm{dist}_B\! \left(\mathrm{supp}(\Psi),\mathcal{S}\right)\geq r$.

