[Lem 1 of arXiv:2605.02420, '\textbf{Large time behavior of critical marked Hawkes processes with heavy tailed marks an'] Under Assumption \ref{ass:nu_beta}, the function   $H$ given by \eqref{e:Hdef} 
is nondecreasing and for any $x\in[0,1]$ we have
\begin{equation}

 H(x)= Kx^{1+\beta}W(x),
\end{equation}
where $K=\frac{c_\nu}{\beta}\Gamma(1-\beta)$ and $W$ is a nonnegative bounded function satisfying
\begin{equation}
 \lim_{x\to 0+}W(x)=1.

\end{equation}
Moreover, there exists a constant $C>0$ such that for any $0\le x\le y$
\begin{equation}

 0\le H(y)-H(x)\le C(y-x)y^\beta.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:sharper-offdiag of arXiv:2608.18293, 'Critical tensor covariance at the Marchenko--Pastur threshold'] Assume in addition that $\mathbb{E} X^3=0$, let $A$ be complex symmetric, write
$A^\circ$ for its zero-diagonal part, and suppose $d/n\to0$. Then, for all
sufficiently large $n$,
\begin{equation}
 \frac1{p^2}\mathbb{E}|x^{\mathsf T}A^\circ x|^2
 \le \frac{2d(n-d)}{n(n-1)}
 e^{vd^2/(n-2d)}\|A\|_\mathrm{op}^2.

\end{equation}

[Theorem 5 (Second-order Markov random field property) of arXiv:2510.22533, 'Marginal dynamics of probabilistic cellular automata on trees'] Suppose Condition \ref{cond:deterministic} holds, and let $A \subset V$. Suppose
	\begin{equation}

		{X_A}(0) \perp {X_{V \setminus (A\cup\partial^2A)}}(0) \mid {X_{\partial^2A}}(0). 
	\end{equation}
	Then ${X_A}[k] \perp {X_{V \setminus (A\cup\partial^2A)}}[k] \: | \: {X_{\partial^2A}}[k]$ for each $k \in \N_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 2 (Uniform remainder estimates) of arXiv:2608.24616, '2608.24616'] There is a deterministic function $\delta:(0,1]\to[0,\infty)$, with
$\delta(u)\to0$ as $u\downarrow0$, such that, for either sign and every
finitely supported subprobability weight sequence $P$,
\begin{equation}
        |N_P^\varepsilon(u)|\leq u^2\delta(u),\qquad 0<u\leq1.
\end{equation}
Moreover, for a constant $C$ depending only on $r$ and the law of $X$,
\begin{equation}
        |N_P^\varepsilon(u)|
        \leq 2+C u^r\sum_jp_j^r,\qquad u\geq1.
\end{equation}

[Proposition prop_compensated_martingale of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] Let $A \in \mathscr{A}_0$. Then, the  process $\overline{N}_A$ defined by
\begin{equation}
\overline{N}_A(t) \coloneqq \sum\limits_{0<s\leq t} \1_A(\Delta \overline{M}(s)) - \int_0^t \int_{Y} \1_A(F(s,\overline{u}(s),y))\, \nu(\mathrm{d} y) \, \mathrm{d}s, \;\;  t\in [0,T],
\end{equation}
is an   ${\overline{\mathbb{F}}}$-martingale. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition LLN_perturbed_process of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] Fix $G \in C^{0,1}(\Omega_T)$. A function  {$\rho \in L^2([0,T],H^1([0,1]))$} such that $0\leq \rho \leq 1$ a.e. in $\Omega_T$ is called a weak solution of 
\begin{align} 
    \begin{cases}
    \partial_t \rho = \Delta \rho-2\nabla\{\sigma(\rho)\nabla G\}\\
    \nabla \rho_t(0) -2\sigma(\rho_t(0))\nabla G_t(0) = -\mathfrak{p}^-(\rho_t(0),G_t(0))\\
    \nabla \rho_t(1) -2\sigma(\rho_t(1))\nabla G_t(1)= \mathfrak{p}^+(\rho_t(1),G_t(1))\\
    \rho(0,x) = \gamma(x)
    \end{cases} 
\end{align} if 
\begin{align*}
    \int_0^1 \left[\rho_t H_t -\gamma H_0 -\int_0^t \rho_s\partial_s H_s\;ds \right] dx &=\int_0^t\int_0^1\{-\nabla\rho_s\nabla H_s+ 2\sigma(\rho_s)\nabla G_s\nabla H_s\}\;dx\;ds\\
    &+ \int_0^t \{\mathfrak{p}^-(\rho_s(0),G_s(0))H_s(0)+\mathfrak{p}^+(\rho_s(1),G_s(1))H_s(1)\} ds,
\end{align*}
for all $t\in [0,T]$ and all test functions $H\in C^{1,2}( {\Omega_T})$.

[Lemma lem: upper-bound for the sum of squares of k point function of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] Recall the convention that ${\operatorname{dist}}(A,B)=1$ if $A\cap B\neq\emptyset$.
    For any subset $I,S \subset\Lambda_N$, let \begin{equation}
        F(S, I)=\prod_{x\in I}\frac{1}{\big[{\operatorname{dist}}(x,S\cup (I\setminus\{x\}))\big]^{\frac{1}{{8}}}}.
    \end{equation}
For any \(s\in(0,1)\), there exists a constant \(c_4=c_4(s)>0\) such that the following holds. Let \(t>0\), and let \(S,\Lambda\subset\Lambda_N\) satisfy
$
\partial\Lambda\subset S\subset\Lambda,
$
and assume moreover that
\begin{equation}
\sum_{x\in\Lambda}\frac{1}{{\operatorname{dist}}(x,S)^s}
\le
tN^{2-s}.
\end{equation}
Then
\begin{align}
\sum_{x_i\in\Lambda,\,1\le i\le k}
F(S,\{x_1,x_2,\cdots,x_k\})^{8s}
\le
(c_4t)^kN^{(2-s)k}(k!)^s.

\end{align}

     As a consequence, we have
    \begin{align}
        \sum_{\substack{I\subset \Lambda,|I|=k} } F(S, I)^{8s}&\le (c_4t)^{k}N^{(2-s)k}\cdot(k!)^{-1+s}.
    \end{align}

[Lemma 3 (Downward jumps are not admissible) of arXiv:2608.30859, 'Conservation Laws with Discontinuous Flux:\\ A First Application to Traffic Flow'] Let the flux functions $f,g$ satisfy the Assumption \ref{assump}. Let $(u^-,\theta^-)$ and $(u^+,\theta^+)$ denote the left and right state of a jump. Then, any downward jump ($u^->u^+$) violates the Lax admissibility condition
    \begin{equation}
        \theta^+f^\prime(u^+)+(1-\theta^+)g^\prime(u^+)\leq \lambda\leq \theta^- f^\prime(u^-)+(1-\theta^-)g^\prime(u^-),
    \end{equation}
    where
    \begin{equation}
        \lambda = \displaystyle\frac{[\theta^+ f(u^+)+(1-\theta^+)g(u^+)]-[\theta^- f(u^-)+(1-\theta^-)g(u^-)]}{u^+-u^-}.        
    \end{equation}

