+
(-1)^{n/2} \dfrac{n!}{2^{n/2} (n/2)! }
(V_{A^{\rm gen}_{m}}^{n/2} - V_{A^{\rm gen, +}_{m-1}}^{n/2},f)
.
\end{multline*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 of arXiv:2608.23462, '2608.23462'] Suppose that Assumption~\ref{assu:frozenLipschitz} holds, that $g$ and $\sigma_k$, $k=1,\dots,d_2$, are continuously differentiable in $x \in \R^{d_1}$ as well as in $y\in \R^{d_2}$, and that the mixed second-order derivatives $D^2_{y,x} g$ and $D^2_{y,x} \sigma_k$ exist. Assume moreover that $D_x g$, $D_x \sigma_k$, $D_y g$, $D_y \sigma_k$, $D^2_{y,x} g$, and $D^2_{y,x} \sigma_k$ are jointly continuous and uniformly bounded on $\R^{d_1+d_2}$.
    Then the mapping $(x,y) \mapsto \hat{Y}^{x,y}$ is differentiable in $x$ in the sense that there is a family of processes $D_x \hat Y^{x,y} v$ indexed with $x,v\in \R^{d_1}$, $y\in \R^{d_2}$ satisfying
    \begin{align} 
        \lim\limits_{h \to 0} &\hat{\E} \bigg[ \sup_{t \in [0,T]} \bigg| \frac{\hat{Y}^{x + hv,y}_t - \hat{Y}^{x,y}_t }{h} -D_x \hat{Y}^{x,y}_t v\bigg|^2 \bigg] = 0
    \end{align}
    for any finite $T >0$ where the first-order derivative flow $D_x \hat{Y}^{x,y} v$ is an instance of the general dynamics
    \begin{align} 
        \begin{cases}
        d \zeta^{x,y,z,v}_t = D_x g(x,\hat{Y}^{x,y}_t) v dt + D_y g(x,\hat{Y}^{x,y}_t) \zeta^{x,y,z,v}_t dt \\ \qquad \qquad \qquad + \sum_{k=1}^{d_2} \Big( D_x \sigma_k(x,\hat{Y}^{x,y}_t) v + D_y \sigma_k(x,\hat{Y}^{x,y}_t) \zeta^{x,y,z,v}_t \Big) d \hat{W}^k_t, \\
        \zeta^{x,y,z,v}_0 = z \in \R^{d_2}
        \end{cases}
    \end{align}
    for $z=0$, i.e. $D_x \hat{Y}^{x,y} v = \zeta^{x,y,0,v}$. Moreover for each $p \geq 2$ and finite time horizon $T > 0$, the process is uniformly bounded in $x,y$, i.e. there exists $C_{p,T}> 0$ with
    \begin{align*}
        \hat\E \Big[ \sup_{0\leq t \leq T}|\zeta^{x,y,z,v}_t|^p \Big] &\leq C_{p,T}( |v|^p + |z|^p )
    \end{align*}
    for $x,v \in \R^{d_1}$, $y,z \in \R^{d_2}$ and continuous in $x,y$ with respect to convergence in $L^p$, i.e.
    \begin{align*}
        \lim\limits_{(x',y') \to (x,y)} &\hat{\E} \Big[ \sup_{t \in [0,T]} | \zeta^{x',y',z,v}_t - \zeta^{x,y,z,v}_t|^p \Big] = 0.
    \end{align*}
    for $x,v \in \R^{d_1}$, $y,z \in \R^{d_2}$. Additionally, if $\hat Y^{x}$ is $p$-dissipative for $p \geq 2$ with constant $\beta > 0$, then there exists $ C_{\beta,p}^{(1)},C_{\beta,p}^{(2)} > 0$ with
    \begin{align*}
        \|\zeta^{x,y,z,v}_t\|_{L^p} \leq \{ e^{-(p\beta /2)t}|z|^p + C_{\beta,p}^{(1)}|v|^p \}^{1/p} \leq e^{-(\beta  /2)t} |z| + C_{\beta,p}^{(2)}|v|
    \end{align*}
    for all $x,v \in \R^{d_1}$, $y,z \in \R^{d_2}$, and $t \geq 0$.

[Lemma 5 (Compatibility lemma) of arXiv:2609.00673, '2609.00673'] Let \(x_i>0\) for \(1\le i\le n-1\), and let
\(\phi_i\in(-\pi,\pi]\setminus\{0,\pi\}\) for \(1\le i\le n-2\).
Assume
\begin{equation}
\frac{x_{i+2}+x_{i+1}\cos\phi_{i+1}}{\sin\phi_{i+1}}
=
\frac{x_i+x_{i+1}\cos\phi_i}{\sin\phi_i},
\qquad 1\le i\le n-3.

\end{equation}
Define the endpoint values
\begin{align}
y_1&=\frac{x_2+x_1\cos\phi_1}{\sin\phi_1},
\\
y_{n-1}&=\frac{x_{n-2}+x_{n-1}\cos\phi_{n-2}}
{\sin\phi_{n-2}},

\end{align}
and, for \(2\le j\le n-2\), define \(y_j\) by either of the equal
expressions
\begin{equation}
y_j=
\frac{x_{j-1}+x_j\cos\phi_{j-1}}{\sin\phi_{j-1}}
=
\frac{x_{j+1}+x_j\cos\phi_j}{\sin\phi_j}.

\end{equation}
The equality in \eqref{eq:y-interior} is precisely
\eqref{eq:finite-step} with index \(j-1\). Then, for every
\(1\le i\le n-2\),
\begin{align}
-x_i&=x_{i+1}\cos\phi_i-y_{i+1}\sin\phi_i,
\\
y_i&=x_{i+1}\sin\phi_i+y_{i+1}\cos\phi_i.

\end{align}

[Theorem 11 (Classwise directional coefficient-module presentation) of arXiv:2609.02449, 'Finite Directional Coefficient Modules over Euler Fibers of $A$-Hypergeometric Systems'] For every reference vector $\bm{\lambda}\in\Lambda$, normalization induces linear isomorphisms
\begin{equation}

\Sol_{\bm{w},\Lambda}^{\mathrm{dir}}\bigl(H_{A}(\bm{\beta})\bigr)\cong\Coeff_{\bm{w}}^{\mathrm{dir}}(\Lambda)\cong\Hom_{S}\left(M_{\Lambda,\bm{w}}^{\mathrm{dir}},\C[\bm{y}]\right).
\end{equation}
Under these isomorphisms, a normalized family $(c_{\Lambda,I})_{I\in\NS(\Lambda)}$ is converted directly into raw coefficients by \eqref{eq:raw-coefficient-reconstruction} and then into a formal logarithmic series by \eqref{eq:classwise-formal-logarithmic-expression}. (Proof in the paper; no proof environment follows the statement in the TeX.)

