\end{compactenum}
\begin{equation}

\lim_{n\to \infty} \max_{ p \in \lgeo \lfloor b_n x\rfloor, \lfloor b_n y \rfloor \rgeo } \big| D^{_{(n)}}_{{s_n}} (p) \! -\! D_s (p/b_n)  \big|\eqo 0 \; .
\end{equation}
\begin{compactenum}
\item[] Moreover, the r.v.~$\big( D^{_{(n)}}_{^{s_n}} ( V_{s_n} (\tau_{\geq n}) ) \big)_{\! n\in \bbN^*}$ are uniformly integrable: 
\end{compactenum}
\begin{equation}

\lim_{c\to \infty} \sup_{n\in \bbN^*} \bE \Big[ D^{_{(n)}}_{^{s_n}} ( V_{s_n} (\tau_{\geq n}) ) \un_{ \big\{ D^{_{(n)}}_{^{s_n}} ( V_{s_n} (\tau_{\geq n}) ) \geq c \big\}} \Big] = 0\; . 
\end{equation}
\begin{compactenum}
\item[$(iv)$] The joint convergence 
\end{compactenum}
\begin{equation}

\mathscr Q_n'= \Big(  \tfrac{1}{b_n} V_{\lfloor n\cdot \rfloor} (\tau_n) ,   \tfrac{1}{a_n} H_{ n\cdot } (\tau_n)  ,    \tfrac{1}{a_n} C_{2n\cdot } (\tau_n)  \Big) \underset{n\to \infty}{-\!\!\!-\!\!\!\longrightarrow} 
\big(  X', H', H'  \big)
\end{equation}
\begin{compactenum}
\item[]  holds weakly on $\bD ([0, 1], \bbR)  \times  \bC ([0, 1] , \bbR)^2$ equipped with the product topology. Here 
$(X', H')$ has the same law as $(X, H(X))$ under $\bN (dX \, | \zeta \eqo 1)$.  
\end{compactenum} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 2 of arXiv:2609.01333, '2609.01333'] Let $ e_1= (1,0)$ and $\gamma > 0$.  For a $C^2$ function $\varphi: \mathbb{R} \to \mathbb{R} \setminus \{0\}$, the map $$\varphi \mapsto \cF(\varphi) := \cH_{\Omega_\varphi}$$
is defined for every $(t, \varphi(t)z) \in \partial \Omega_\varphi$ with $z \in \mathbb{S}^1 = \partial B_1$, by
\begin{align*}
 \cF(\varphi)(t)= \cH_{\Omega_\varphi} ((t, \varphi(t) z))= \cF_0(\varphi)(t)+ \gamma \cF_1(\varphi)(t)
\end{align*}

where the Yukawa interaction takes the form,
\begin{align}
\int_{\Omega_\varphi} \hspace{-1.5ex}G_\kappa(|(t, \varphi(t) z)  -\xi|)\mathrm{d}\xi =\hspace{-1.5ex}\int_\mathbb{R}\int_{B_1} \hspace{-1.5ex} \varphi^2(s) G_\kappa(|(t, \varphi(t)e_1)-(s,\varphi(s)y)|)\mathrm{d} y \mathrm{d}s=:\mathcal{F}_1(\varphi)(t).
\end{align}
While, the mean curvature of $\partial\Omega_\varphi$  at $(t, \varphi(t) z)  \in\partial \Omega_\varphi$ is given by
\begin{align}
\begin{split}
H_{\partial\Omega_\varphi}((t, \varphi(t)z) )
&=\frac{-\varphi''}{(1+\varphi'^2)^{\frac{3}{2}}}+\frac{1}{\varphi(1+\varphi'^2)^{\frac{1}{2}}}. =: \mathcal{F}_0(\varphi)(t).
\end{split}
\end{align}
Moreover,  for $\lambda \in (0,\infty)$ the function $t\mapsto \cF(\lambda)(t) = C_{\lambda,\kappa}$ is constant, where
\begin{align*}
C_{\lambda,\kappa} &=H_{\partial\Omega_{\lambda}}((0,\lambda e_1))+\gamma \int_{\Omega_{\lambda}}G_\kappa(|(0,\lambda e_1)-z|) \mathrm{d}z=\frac{1}{\lambda} + 2 \gamma\lambda^2 \int_{B_1} K_0(\lambda\kappa|e_1-y|)\mathrm{d}y.
\end{align*}

