body:
[Theorem thm:central-bound of arXiv:2606.27073, 'Retention Profiles and KL Contraction Bounds in Finite Markov Chains'] For any $\mu\neq\pi$,
\[
  \frac{D_{\mathrm{KL}}(\mu P\|\pi)}{D_{\mathrm{KL}}(\mu\|\pi)}
  \;\le\;
  M\cdot\frac{D_{\mathrm{KL}}(\mu\|\pi)+H(\mu)}{D_{\mathrm{KL}}(\mu\|\pi)}
  \;-\;
  \frac{I_\mu(X;Y)}{D_{\mathrm{KL}}(\mu\|\pi)},
\]
where $H(\mu)=-\sum_x\mu(x)\log\mu(x)$ is the Shannon entropy.
Equality holds if and only if $r(x)=M$ for all $x$ in the support of $\mu$.

[Theorem 2 of arXiv:2606.12720, 'On McDiarmid's Inequality under Dependence \\ via Approximate Tensorization of Entropy'] {McDiarmid's Inequality (\cite{mcdiarmid1989})}


    Let $X \in \mathcal X^n$ have independent entries. Assume $f : \mathcal X^n \to \R$ fulfills the bounded differences property with constants $c := (c_1,...,c_n)\T$. Then, for all $t > 0$ we have
    \begin{align*}
        \P\Parent{|f(X) - \E[f(X)]| \geq t} 
        &\leq 2\exp\Parent{-\frac{2t^2}{\twonorm{c}^2}}. 
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 51 of arXiv:2605.02430, '\textbf{Scaling limit of the range of tree-valued branching random walks in random environ'] We keep the above notation. We fix $\alpha \ino (1, 2]$ and we assume that $\mu$ satisfies (\ref{hypostaintro}). For all $\lambda \ino \bbR_+$, we set $\Lambda_0(\lambda)\eqo -\log \bE [e^{-\lambda \cL_1}]$, $\Lambda_1 (\lambda)\eqo -\log \varphi_\mu (e^{-\lambda})$ and $\Lambda_2 (\lambda)\eqo -\log \bE[ e^{-\lambda \cV_1}] $. Then there are $c_\mu, c^\prime_\mu \ino (0, \infty)$ such that 
\begin{equation}

\Lambda_0 (\lambda) \sim_{0^+}c_\mu \,  \lambda^{\frac{\! \alpha-1}{\alpha}}  L\big(\tfrac{1}{\lambda} \big) \quad \textrm{and} \quad \Lambda_2(\Lambda_1 (\lambda)) \sim_{0^+} c^\prime_\mu\,   \lambda^{\frac{\! \alpha-1}{\alpha}}  L\big(\tfrac{1}{\lambda} \big)
\end{equation} 
where $L$ is the slowly varying function appearing in (\ref{bnBiGoTe}). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma of arXiv:2601.07808, 'Supercritical long-range percolation on graphs of polynomial growth: the truncated one-arm'] \label[lemma]{prop:one_arm_connection}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 2$, and suppose that $J : V \times V \to \mathbf{R}_+$ is a transitive kernel with $J(x,y) = O(d_G(x,y)^{-d \alpha})$ with $\alpha > 1$.  

    For $r \in \mathbf{N}$, $b \geq 2$, and $\mathbf{m} \in \mathcal{M}(b)$, there exist $c_1 = c_1(G,J) > 0$ and $c_2 = c_2(G) > 0$ such that 

    \begin{multline}        
        \sum_{\substack{
            \mathbf{r} \in \mathcal{R}(b,\mathbf{m},r)
            \\
            \mathbf{A} \in \mathcal{A}(b,\mathbf{m})
        }}
        \mathbf{P}_{\beta}
        \left(
            P(\mathbf{A},\mathbf{r})
            \subseteq
            \mathcal{H}^*(\mathbf{A})
        \right)
        \\
        \leq 
        c_1 
        r^{d(1 - \alpha)}
        (b-2)^{d \alpha - d + 1}
        \mathbf{E}_{\beta}\left[\deg(o)\right]^{b-1}
        \prod_{i=0}^{b-1} 
        \exp
        \left(
            c_2 \beta m_i
        \right)
        .
    \end{multline} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2608.25772, 'Propagation of Chaos and Gaussian Fluctuations for Mean-field Coupled Maps'] Under the assumption \textup{\textbf{(A1.1)}}, let $\bar{\rho}_t,t=0,1,\dots$ be a solution to \eqref{eq:mf-dynamics}. Then there exists some constant $C>0$, depending on $\Delta,\mathrm{Lip}(F)$ and $\Vert h\Vert_{C^1}$, such that
    \begin{equation}
        W_1(\mu_N(t),\bar{\rho}_t)\leq\mathrm{e}^{Ct}W_1(\mu_N(0),\bar{\rho}_0),\qquad t=0,1,\dots,
    \end{equation}
    where $W_1$ denotes the $1$-Wasserstein distance. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 4 of arXiv:2608.29157, 'Dilator-based analysis of $\KP$'] We define the addition over $\varepsilon(X)$ as follows:
    \begin{enumerate}
        \item $0 + \alpha = \alpha+0 := \alpha$.
        \item For $u,v\in X$,
        \begin{equation*}
            \varepsilon_u + \varepsilon_v =
            \begin{cases}
                \omega^{\varepsilon_u} + \omega^{\varepsilon_v} & \text{If }u\ge v, \\
                \varepsilon_v & \text{If }u<v.
            \end{cases}
        \end{equation*}
        \item For $u\in X$ and $\alpha_0,\cdots,\alpha_{m-1}\in \varepsilon(X)$,
        \begin{equation*}
            \varepsilon_u + (\omega^{\alpha_0}+\cdots+\omega^{\alpha_{m-1}}) = 
            \begin{cases}
                \omega^{\varepsilon_u} + \omega^{\alpha_0}+\cdots+\omega^{\alpha_{m-1}} & \text{If }\varepsilon_u \ge\alpha_0, \\
                \omega^{\alpha_0}+\cdots+\omega^{\alpha_{m-1}} & \text{If }\varepsilon_u < \alpha_0,
            \end{cases}
        \end{equation*}
        and
        \begin{equation*}
            (\omega^{\alpha_0}+\cdots+\omega^{\alpha_{m-1}}) + \varepsilon_u = 
            \begin{cases}
                \omega^{\alpha_0}+\cdots+\omega^{\alpha_{m-1}} + \omega^{\varepsilon_u}& \text{If }\varepsilon_u \le\alpha_{m-1}, \\
                (\omega^{\alpha_0}+\cdots+\omega^{\alpha_{m-2}}) + \varepsilon_u & \text{If }\varepsilon_u>  \alpha_{m-1}.
            \end{cases}
        \end{equation*}

        \item For $\alpha_0,\cdots,\alpha_{m-1},\beta_0,\cdots,\beta_{n-1}\in\varepsilon(X)$,
        we define $(\omega^{\alpha_0}+\cdots+\omega^{\alpha_{m-1}}) + (\omega^{\beta_0}+\cdots+\omega^{\beta_{n-1}})$ by
        \begin{equation*}
            \begin{cases}
                (\omega^{\alpha_0}+\cdots+\omega^{\alpha_{m-2}}) +(\omega^{\beta_0}+\cdots+\omega^{\beta_{n-1}}) & \text{If }\alpha_{m-1}<\beta_0, \\
                \omega^{\alpha_0}+\cdots +\omega^{\alpha_{m-1}}+\omega^{\beta_0}+\cdots+\omega^{\beta_{n-1}} & \text{If }\alpha_{m-1}\ge\beta_0.
            \end{cases}
        \end{equation*}
    \end{enumerate}
    We also define the multiplication over $\varepsilon(X)$ as follows:
    \begin{enumerate}
        \item $0\cdot\alpha = \alpha\cdot 0 := 0$.
        \item For $u,v\in X$, $\varepsilon_u\cdot \varepsilon_v := \omega^{\varepsilon_u + \varepsilon_v}$. (Here we follow the previous definition of the addition.) 
        \item For $u\in X$ and $\alpha_0,\cdots,\alpha_{m-1}\in \varepsilon(X)$,
        \begin{itemize}
            \item $\varepsilon_u \cdot (\omega^{\alpha_0}+\cdots+\omega^{\alpha_{m-1}}) = \omega^{\varepsilon_u + \alpha_0} + \cdots + \omega^{\varepsilon_u + \alpha_{m-1}}$, and
            \item $(\omega^{\alpha_0}+\cdots+\omega^{\alpha_{m-1}})  \cdot\varepsilon_u = \omega^{\alpha_0+\varepsilon_u}$.
        \end{itemize}

        \item For $\alpha_0,\cdots,\alpha_{m-1},\beta\in\varepsilon(X)$, we first define
        \begin{equation*}
            (\omega^{\alpha_0}+\cdots+\omega^{\alpha_{m-1}}) \cdot \omega^\beta = 
            \begin{cases}
                \omega^{\alpha_0}+\cdots+\omega^{\alpha_{m-1}} & \beta = 0,\\
                \omega^{\alpha_0+\beta} & \beta\neq 0.
            \end{cases}
        \end{equation*}
        Then for $\sigma = \omega^{\alpha_0}+\cdots+\omega^{\alpha_{m-1}}\in \varepsilon(X)$ and $\beta_0,\cdots,\beta_{n-1}\in\varepsilon(X)$, we define
        \begin{equation*}
            \sigma \cdot (\omega^{\beta_0}+\cdots+\omega^{\beta_{n-1}}) :=  \sigma \cdot \omega^{\beta_0} + \cdots + \sigma \cdot \omega^{\beta_{n-1}}. 
        \end{equation*}
    \end{enumerate}
    Here, we identify the formal expression $\omega^{\varepsilon_u}$ with $\varepsilon_u$.

