[Lemma lem: main1 of arXiv:2509.20779, 'Diffusive Scaling limit of stochastic Box-Ball systems and P\MakeLowercase{ush}TASEP'] Every limit point $(W',X',Y')$ of $(W^n, X^n, Y^n)_{n \in \mathbb{N}}$ satisfies the following properties: 
    \begin{enumerate}
    \item [(i)] $W' = X' + R Y'$ a.s.,
    \item [(ii)] $W'$ has continuous paths and $W'(t) \in S$ for all $t \ge 0$ a.s.,
    \item [(iii)] 
    \begin{itemize}
        \item [(a)] $X'$ is a $d$-dimensional Brownian motion with drift $\mathbf 0$ and covariance matrix $\Sigma$, and initial distribution $\delta_\mathbf{0}$,
        \item [(b)] $\{X'(t)-X'(0),\mathcal F_t,t\ge0\}$ is a martingale, where $\mathcal F_t = \sigma\{(W'(s),X'(s),Y'(s)):0 \le s \le t\}$, 
    \end{itemize}
    \item [(iv)] $Y'$ is an $\{\mathcal F_t\}$-adapted $k$-dimensional process such that a.s. for $j \in \{1,2,\dots, k\}$,
    \begin{itemize}
        \item [(a)] $Y'_j(0)=0$,
        \item [(b)] $Y'_j$ is continuous and non-decreasing, 
        \item [(c)] $Y'_j(t)$ can increase only on $F_{f(j)}$, i.e., 
        \begin{align*}
            \int_0^{t}\mathbf{1}{F_{f(j)}}(W'(s))dY'_j(s)=Y'_j(t) \quad \text{for all } t \ge 0
        \end{align*}


    \end{itemize}
\end{enumerate}

