[Corollary YA of arXiv:2411.09976, 'Occupation times on the legs of a diffusion spider'] For  $r\in\{1,2,\dotsc, R\}$ and $z_i>0,\, i=1,2,\dotsc,r,$ 
\begin{equation} 
\mathbf{E}_\mathbf{0}\left(\mathrm{exp}\bigg(- \sum_{i=1}^r z_i A_T^{(i)}\bigg)\right) 
= \frac{\displaystyle 1 -\sum_{j=1}^r \beta_j +\sum_{j=1}^r  \frac{\lambda\,\beta_j}{\lambda + z_j} \frac{c_{\lambda+z_j}}{c_\lambda}}
{\displaystyle 1 -\sum_{j=1}^r \beta_j +\sum_{j=1}^r \beta_j \frac{c_{\lambda+z_j}}{c_\lambda}},
\end{equation}
where (cf. (equation cr1 of the paper)) 
\begin{equation*}
c_\lambda:=-\frac{d}{dS}\varphi_\lambda(0+)>0.
\end{equation*}
In particular, for $z_i>0$, $i=1,2,\dotsc,R$,
\begin{equation} 
\mathbf{E}_\mathbf{0}\left(\mathrm{exp}\bigg(- \sum_{i=1}^R z_i A_T^{(i)}\bigg)\right) 
= \frac{\displaystyle \sum_{j=1}^R   \frac{\lambda\,\beta_j\,c_{\lambda+z_j}}{\lambda + z_j}}
{\displaystyle \sum_{j=1}^R \beta_j \, c_{\lambda+z_j}}
\end{equation}

[Theorem 32 of arXiv:2607.14948, 'Graph alignment in sparse inhomogeneous models via self-overlap'] Let $K$ be a Chung-Lu graph with associated degree law $\mu \in L^1$, and set $d^*(K) = \frac{\E[D^2]}{\E[D]}$ where $D \sim \mu$.
    \begin{itemize}
         \item Assume that $d^* > 1$. Then there exist constants
    $c_K,\delta_K>0$ such that, with high probability, $K$ has a connected
    component $\mc{G}$, with vertex set $V_\mc{G}$, satisfying
    $|V_\mc{G}| \geq c_K n$ and
    \begin{equation}
       |K[V_\mc{G}]| \geq (1+\delta_K)|V_\mc{G}|.
        \end{equation}
        Moreover, the degrees inside $\mc{G}$ are uniformly integrable in the
        following sense: for every $\zeta>0$, there exists $\eta>0$ such that,
        with high probability,
        \begin{equation}
         \sup_{\substack{N \subseteq V_\mc{G}\\ |N|\leq \eta n}}
         \sum_{v\in N}\deg_K(v)
         \leq \zeta |V_\mc{G}|.
        \end{equation}
        \item Assume that $d^* < 1$. If we pick $v \in V$ uniformly at random, then the connected component $\mc{T}_v$ of $v$ is a tree with high probability; furthermore, there exists a random variable $\mc{T}$ on the set of finite-size trees such that
        \begin{equation}
            \mc{T}_v \overset{\text{(law)}}{\goesto{n \to +\infty}} \mc{T}.
        \end{equation}
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 (Regression for $d \geq 1$) of arXiv:2608.26974, 'Why not to use the Gaussian kernel'] Consider the Gaussian kernel in~\eqref{eq:gaussian} for $d \geq 1$ and $\sigma \geq 0$.  
  If $X_n = \{x_1, \ldots, x_n\}$ for any sequence $\{ x_i \}_{i=1}^\infty \subset \R^d$ of pairwise distinct points whose closure has non-empty interior, then
  \begin{equation*}
    \sup_{x \in K} \V_\sigma( x \mid \mathcal{D}_n ) \to 0 \quad \text{ as } \quad n \to \infty \quad \text{ for any compact } \quad K \subset \R^d .
  \end{equation*}

[Theorem 2 of arXiv:2608.27166, 'Well-posedness and regularity of stochastic heat equations on moving domains'] Under Assumptions 2.1 and 2.2.  For each $u_0\in L^2(\OO)$, equation \eqref{eq:moving-spde} has a unique weak solution.  There exists $\alpha\in(0,1)$ such that the weak solution $u$ of \eqref{eq:moving-spde} has a modification whose sample paths are H\"older continuous on $Q_{T_0,2T_0}$. Furthermore, for every $p>0$,
\begin{equation}
\E\|u\|_{C^{\alpha/2,\alpha}(Q_{T_0,2T_0})}^p
\leq
C
\left(
\|u_0\|_{L^2(\OO)}
+
K_{0}
\right)^p .

\end{equation}
Here $C$ depends on $d$, $L$, $\Lambda$, $p,T_0,T,|\OO|$, and on the uniform bounds in Assumption~\ref{ass:moving-domain}. (Proof in the paper; no proof environment follows the statement in the TeX.)

