[Lemma 30 of arXiv:2609.04033, 'From configuration spaces to graph complexes via $\mathbf{FA}$-modules'] There is an isomorphism of graded $S_n$-representations $$H^\ast_c(F(S^1\vee S^1,n))\tensor_{\mathbb{Z}_2\times S_3}( Id\boxtimes V_{2,1})\cong\bigoplus_\lambda \Sigma^{|\lambda|} q_\lambda\Phi[n,\lambda^\ast]$$ where

$$
q_{\lambda} = \begin{cases}
	\left\lfloor \ds\frac{a-b+2}{3} \right\rfloor & \text{ if } \lambda = (a,b) \text{ and } a\equiv b \text{ mod } 2, \\ \\
	0 & \text{ else.}
\end{cases} 
$$

[Definition Def:alpha-mixing of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] A sequence $\{X_k\}_{k\geq 1}$ of $d$-dimensional random vectors on a sublinear expectation space $(\Omega, \mathcal{H}, \hat{\mathbb{E}})$ is called $\alpha$-mixing if there exist $c_X>0,\alpha>0$ such that for any non-empty finite subset $\Lambda^1,\Lambda^2\subset \mathbb{N}$ with $\Lambda^1_{max}:=\max_{u_1\in \Lambda^1}u_1\leq \min_{u_2\in \Lambda^2}u_2=:\Lambda^2_{min}$ and $\phi\in C_{lip}(\mathbb{R}^{2d})$ with Lipschitz constant $l_{\phi}>0$,
		\begin{equation*}
			\begin{split}
				|\hat{\mathbb{E}}[\phi(\bar{X}_{\Lambda^1}, \bar{X}_{\Lambda^2})] - \hat{\mathbb{E}}[\hat{\mathbb{E}}[\phi(x, \bar{X}_{\Lambda^2})]|_{x=\bar{X}_{\Lambda^1}}]| \leq c_X l_{\phi} e^{-\alpha |\Lambda^2_{min}-\Lambda^1_{max}|},
			\end{split}
		\end{equation*}
		where $\bar{X}_{\Lambda^i}=\frac{1}{|\Lambda^i|}\sum_{u_i\in \Lambda^i}X_{u_i}$  and $|\Lambda^i|$ is the number of elements in $\Lambda^i$, $i=1,2$.

[Theorem 6 of arXiv:2606.25501, 'An RDT based approach to large deviations of Wishart and Wigner matrices spectral edges'] (\cite{Gordon85})
 Assume the setup of Theorem \ref{thm:minGordonpos1}. Let $\psi_q(\cdot)$ be an increasing function on the real axis. Then
\begin{equation*}
\mE(\min_{i}\max_{j}\psi_q(X_{ij}))\leq \mE(\min_i\max_{j} \psi_q(Y_{ij})).
\end{equation*}
Also, let $\psi_q(\cdot)$ be a decreasing function on the real axis. Then
\begin{equation*}
   \mE(\max_{i}\min_{j}\psi_q(X_{ij}))\geq \mE(\max_i\min_{j}\psi_q(Y_{ij})).
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 2 (Exact reflection) of arXiv:2609.03466, 'Least-Favorable Location for Binomial Top-$t$ Selection'] Let $T(p)=1-\delta-p$. Then, for every $n,k,t$ and $p\in[0,1-\delta]$,
\begin{equation*}
 P_{n,k,t,\delta}(p)=P_{n,k,k-t,\delta}(T(p)).
\end{equation*}
Consequently, when $k=2t$,
\begin{equation*}
 P_{n,k,t,\delta}(\pc+u)=P_{n,k,t,\delta}(\pc-u),
 \qquad \pc=\frac{1-\delta}{2},
\end{equation*}
whenever both arguments belong to $[0,1-\delta]$.

[Lemma 7 of arXiv:2506.17061, 'Non-uniform bounds for non-normal approximation via Stein's method with applications to th'] For $z \ge 5$ and $\xi$ is a random variable satisfying $0\le |\xi|\le |\Delta|$. Then
		\begin{equation}
			\E(f_{z}(W))^2 \le \dfrac{B^p (p^{p/k}+\E|W|^{2p})}{(1+z)^{2p}},
		\end{equation}
		and
		\begin{equation}
			\E(f_{z}'(W+\xi))^2 \le \dfrac{B^p (p^{p/k}+\E|W|^{2p})}{(1+z)^{2p}}.
		\end{equation}

