[Lemma Generic-gn of arXiv:2412.01635, 'On the Weak Convergence of the Function-Indexed Sequential Empirical Process and its Smoot'] (Properties of $\gamma$)\\
	For $\nu > 2, \kappa \in (0, 1/2 - 1/\nu), C \geq 0$ and $R,J: (0,\infty) \to [0,\infty)$ let
	\begin{equation}
		\gamma(m, \delta) = C m \left(R(\delta) + J(\delta) m^{-\kappa} \right)^2, ~ m \in \mathbb N, \delta > 0.
	\end{equation}

	\begin{itemize}
		\item[(i)] For any $\delta > 0$, the pair $(\nu/2, \gamma(.,\delta))$ fulfills condition (equation MSS-ConditionM of the paper) with index $Q = 2^{2\kappa} \in [1,2^{1-2/\nu}).$

		\item[(ii)] For any $\delta > 0$, $\gamma(., \delta)$ fulfills condition (item:Uniform_FCLT_Cond4 of the paper) of Theorem (UniformFCLT-general of the paper).		

		\item[(iii)] If $\lim_{\delta \downarrow 0} R(\delta) = 0$, then $\gamma$ fulfills condition (item:Uniform_FCLT_Cond3 of the paper) of Theorem (UniformFCLT-general of the paper). 
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemmain of arXiv:2605.01878, '\Large Random trade timing and power-law tails in realized prices'] Let $(X_t, t\geq 0)$ be a Markov-modulated L\'{e}vy process with the matrix Laplace exponent $A(z)$, described in Section (smain1a of the paper). Let $1_N$ denote the $N \times 1$ vector of ones, and let $w_0=(w_{01},w_{02},\ldots,w_{0N})'$ denote the initial distribution of $J$, i.e., $w_{0,j}=\mathbb{P}(J_0 = j)$ for $j = 1,\ldots,N$. Then
\begin{align} 
M_t(s) \coloneqq E[e^{sX_t}]= w_0' \, e^{A(s)t} \, 1_N, \qquad s \in \mathcal I.
\end{align}

