[Theorem 4 (Strong Duality) of arXiv:2608.22746, 'Generative Neural Networks for Sinkhorn Distributionally Robust Hypothesis Testing'] For the convex risk function $\Phi$ and Sinkhorn discrepancy $\mathcal{S}_{\Reg}$, the following results hold:
    \begin{enumerate}
        \item If Assumptions~\ref{assumption-tcost} and~\ref{assumption-2}\ref{assumption-2-el-bound} hold, then
        \begin{equation}\nonumber
            \textnormal{Optimal Value of~\eqref{Eq:hard:constrained:SDRO} = }\max_{\mathbb{P}_0\in \mathbb{B}_{\rho_0}(\widehat{\mathbb{P}}_0), \mathbb{P}_1\in \mathbb{B}_{\rho_1} (\widehat{\mathbb{P}}_1)}\,  \inf_{\phi \in \mathcal{F}} \quad \Phi(\phi;\mathbb{P}_0,\mathbb{P}_1);
        \end{equation} 
        \item If Assumptions~\ref{assumption-tcost} and~\ref{assumption-2} hold, then 
        \begin{equation}\nonumber
            \textnormal{Optimal Value of~\eqref{Eq:soft:constrained:SDRO} = } \max_{\mathbb{P}_0, \mathbb{P}_1 \in \mathscr{P}(\Omega)} \, \inf_{\phi \in \mathcal{F}} \quad  \Phi(\phi;\mathbb{P}_0,\mathbb{P}_1) - \sum_{k \in \mathbb{K}} \lambda_k \mathcal{S}_{\Reg}(\widehat{\mathbb{P}}_k,\mathbb{P}_k), 
        \end{equation} 
        where $\lambda_k > 0$ for any $k \in \mathbb{K}$. 
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:RGflow of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Let  $j \le N$ on $\Lambda = \Lambda_N$,  $j< \infty$ on $\Lambda = \Z^d$ and $\alpha \in [1/2,1]$.
\begin{enumerate}
\item Sequence $( \vec{\nu}_k , \vec{g}_k ,  \vec{\lambda}_k ,  K_k)_{k \le j} \in \prod_{k =0}^j \D_j (\alpha)$ is called the \emph{RG flow of length $j$} if there exist $(\delta u_{k})_{k=1}^j$ with
\begin{align}
	(\delta u_{k+1} ,   \vec{\nu}_{k+1} , \vec{g}_{k+1},  \vec{\lambda}_{k+1} ,  K_{k+1} ) = \Phi^{\Lambda}_{k+1} ( \vec{\nu}_k , \vec{g}_k ,  \vec{\lambda}_k ,  K_k )
	\quad \text{for all} \quad k < j
	.
\end{align}
The sequence is called the \emph{infinite RG flow} if the same holds with $j = \infty$.

We use the term \emph{bulk RG flow} for a sequence $( \vec{\nu}_k , \vec{g}_k, K_{\varnothing,k})_{k \le j} \in \prod_{k=0}^j \D_{\varnothing,k} (\alpha)$ with the same property.

\item For $j< \infty$,  sequence $( \vec{\nu}_k , \vec{g}_k )_{k \le j} \in \prod_{k =0}^j \cD_{\varnothing,k}^{(0)} (\alpha)$ is called the \emph{bulk perturbative RG flow of length $j$} if there exist $(\delta u_{k})_{k=1}^j$ with
\begin{align}
	(\delta u_{k+1} ,   \vec{\nu}_{k+1} , \vec{g}_{k+1}  ) = \mathbb{V}^{(0)} \Phi_{k+1}^{{\operatorname{pt}}} ( \vec{\nu}_k , \vec{g}_k )
	\quad \text{for all} \quad k < j .
\end{align}
\end{enumerate}

