[Theorem 6 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Assume  the notation of Lemma \ref{lemma 4.23.3} and let
$(d,q,p)$ be properly tight.  Then for any Borel $f(t, x)\geq0$   we have  
\begin{equation}

I(p,q,f):= E_{\cF_{\tau}}\int_{\tau}^{\gamma}e^{-\phi_{\tau,t}}\kappa_{t}
f(\sft_{t},x_{t})\,dA_{t}\leq N(d)  (A+B^{2})^{ d/(2p)}
\|f\|_{L_{(q,p)}},
\end{equation}
where 
$\kappa_{t}=
r_{t}^{1/q}(\det a_{t})^{1/p}c^{\nu}_{t}$ 
and for any $\alpha\geq0$ we set $\alpha^{0}=1$ \(say, if $\nu=0$\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 57 (Set Induction) of arXiv:2608.29157, 'Dilator-based analysis of $\KP$'] Let $A(x)$ be a formula and let 
    \begin{equation*}
        \Ind_A :\equiv \forall x\in \ttL(u)_\ttOmega \bigl[\bigl(\forall y\in x A(y)\bigr)\to A(x)\bigr].
    \end{equation*}
    Then we have $H[\ttX]\dststile{}{\omega^{\rk(\Ind_A)}}\Ind_A \to \forall x\in \ttL(u)_\ttOmega A(x)$.

[Corollary 16 of arXiv:2605.02093, 'An analytic approach to the finite $R$-transform'] Let $\epsilon > 0$, and let $(p_N)_{N=1}^\infty$ be a sequence of polynomials with $p_N \in \calP_N((-\infty, -\epsilon])$.
   \begin{enumerate}
    \item If the empirical root distributions $\meas{p_N}$ converge weakly to a probability measure $\mu$, then $R_{p_N}^{(N)}(s)$ converges to $R_\mu(s)$ for $s \in (0, G_\mu(0))$.
    \item  Suppose, in addition, that there exists $M>\epsilon$ such that $p_N\in\calP_N([-M,-\epsilon])$ for all $N$.
    If the finite $R$-transforms $R_{p_N}^{(N)}(s)$ converge to a function $R(s)$ defined on $(0,1/M)$, then there exists a probability measure $\mu \in \calM([-M, -\epsilon])$ such that $\meas{p_N} \weakto \mu$ and $R_\mu(s) = R(s)$.
   \end{enumerate}

[Lemma G_A_decoupling_lemma of arXiv:2603.28520, 'The Supercritical Loop O(1) and Random Current Models: Uniqueness and Mixing'] For $A \subseteq \Lambda_r$, with $\abs{A}$ odd, the following localization identity holds
    \begin{align*}
        \mathcal{G}_A \cap \mathtt{UC}_{r,R} \cap \mathtt{Pis}_{r,R} \cap \{ \mathtt{Giant}_{r,R} \leftrightarrow \infty \} =
        \mathcal{G}^{R}_A \cap \mathtt{UC}_{r,R} \cap \mathtt{Pis}_{r,R} \cap \{ \mathtt{Giant}_{r,R} \leftrightarrow \infty \}. 
    \end{align*}

[Corollary Zm-singlecross of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] The map $Z_{m}^{i}:[0,1]\rightarrow \lbrack 0,1]$ is
continuous and strictly increasing, and exactly one of the following holds:

\begin{enumerate}
\item (\emph{Single-crossing (SC)}) There exists a unique fixed point $
p_{m}^{i}\in (0,1)$ such that 
\begin{equation}
Z_{m}^{i}(x)>x\quad \text{for }x<p_{m}^{i},\qquad Z_{m}^{i}(x)<x\quad \text{
for }x>p_{m}^{i}.  
\end{equation}

\item (\emph{Strictly overdiagonal (SO)}) $Z_{m}^{i}(x)>x$ for all $x\in
(0,1)$.
\end{enumerate}

