[Proposition stochastic-rescaling-and-lumping-commute-and-partition-constant-eigenvector of arXiv:2412.08400, '\vspace{-1.0cm} Characterization of Exponential Families of \\ Lumpable Stochastic Matrice'] The operation of ${\mathfrak{s}}$-normalization satisfies the following properties.
\begin{enumerate}
    \item[(i)\xspace] ${\mathfrak{s}}$-normalization preserves $\kappa$-lumpability and 
the following diagram commutes
\[ \begin{tikzcd}
  \mathcal{F}_\kappa^+(\mathcal{Y}, \mathcal{E}) \arrow{r}{\kappa_\star} \arrow[swap]{d}{{\mathfrak{s}}} & \mathcal{F}^+(\mathcal{X}, \mathcal{D})  \arrow{d}{{\mathfrak{s}}} \\%
\mathcal{W}_\kappa(\mathcal{Y}, \mathcal{E}) \arrow{r}{\kappa_\star}&  \mathcal{W}(\mathcal{X}, \mathcal{D}).
\end{tikzcd}
\]
\item[(ii)\xspace] For any $F \in \mathcal{F}^+_\kappa(\mathcal{Y}, \mathcal{E})$, the right Perron--Frobenius eigenvector $v$ of $F$ satisfies that for any $x \in \mathcal{X}$ and any $y_1,y_2 \in \mathcal{S}_x$, $v(y_1) = v(y_2)$---we say that $v$ is constant on the partition induced from $\kappa$.
\end{enumerate}

[Lem 33 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] There exist constants $\varepsilon > 0$ and $C>1$ such that the following holds for any $q,q' \in [-\varepsilon, \varepsilon]$, with $q \ge q'$, and $z \in \mathfrak{X}$. For each $\mathfrak{e}_z \in \{ \mathfrak{e}_{z;q}, \mathfrak{e}_{z;q'} \}$, we have 
                       \begin{multline}

            \mathcal{H}_{q'} (z) + C^{-1} (\mathfrak{d}_z \mathfrak{e}_z)^{1/2} (q-q') - C \mathfrak{d}_z^{1/2} (q-q')^{3/2} \\ 
            \le \mathcal{H}_q (z) \le \mathcal{H}_{q'} (z) + C(\mathfrak{d}_z \mathfrak{e}_{z})^{1/2} (q-q') + C \mathfrak{d}_z^{1/2} (q-q')^{3/2}.                        
\end{multline}

\noindent In addition, we have 
    \begin{flalign}

             \mathcal{H}_q (z) \ge \mathcal{H}_{q'} (z) + C^{-1} (\mathfrak{d}_z \mathfrak{e}_z)^{1/2} (q-q').                       
\end{flalign} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 11 (Consistency of empirical endpoint calibration) of arXiv:2609.02196, 'Schr\"odinger Bridges on Lie Group Manifolds for Probabilistic Intrinsic Generation'] Under Assumption~\ref{ass:rcm-calibration},
\begin{equation}
\varepsilon_{{\rm end},N}
\leq\varepsilon_{{\rm end,app},N}
+2\delta_{{\rm end},N}
+\varepsilon_{{\rm end,opt},N},
\end{equation}
and hence \(\varepsilon_{{\rm end},N}\to0\) in probability. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 19 of arXiv:2609.01020, '2609.01020'] There exist $0<\e_1 \ll 1$ and $\lambda>0$ such that 
we have an isomorphism 
\begin{equation}
\psi_t(G)_{(0,0)} \simeq \rsect(B(0;\e)\times B(0;\lambda \e)\times \{t\};G)
\end{equation}
for any $0<\e \leq \e_1$ and $t\in \CC^\ast$ such that $0<\abs{t} \ll 1$.

[Lemma l4.5 of arXiv:2604.22510, 'Asymptotics of Multi-Scale McKean--Vlasov Diffusions with Super-Linear Kernels: a Lifted S'] The limit pair ${{\boldsymbol{ {\Pi}}}}$ has the decomposition $((2.17 of the paper))$, i.e., for any $F \in C_b(\mathbb{R}^m\times\mathscr{P}_2(\mathbb{R}^m)),$
	\begin{align*}
		&\int_{\mathbb{R}^d\times\mathbb{R}^m\times\mathscr{P}_2(\mathbb{R}^m)\times[0,T]}F(y,\rho){{\boldsymbol{ {\Pi}}}}(dhdyd\rho dt) \\
		=&\int_{0}^{T}\int_{\mathbb{R}^m\times\mathscr{P}_2(\mathbb{R}^m)}F(y,\rho )(\nu^{\mathscr{L}_{\bar{X}_t}}\times \delta_{\nu^{\mathscr{L}_{\bar{X}_t}}})(dyd\rho)dt.
	\end{align*}

