body:
[Proposition prop:cross_monster of arXiv:2603.28936, 'Composition of random functions and word reconstruction'] For every $u\in \mathbb{R}$, we have
\begin{align}
\mathbb E^{i,j,\ell}_{\mathbf{Y},\mathbf{Y}'}
\bigl[u^{Y_{k}+Y_{k}'}\mathbf{1}_{Y_{2k}=Y_{2k}'=0}\bigr]
	= F_1^{i,j} (u)F_2^{i,j,\ell} (u),
\end{align}
where 
\begin{align}
	F_1^{i,j} (u):&=	\bigl(\prod_{s=0}^{i-1}g_{k-s}(u^{\mathbf{1}_{\{s\leq k\}}}\eta_{k})\bigr) \bigl(\prod_{s=0}^{j-1}g_{k-s}(u^{\mathbf{1}_{\{s\leq k\}}}\eta_{k})\bigr)
	\\&=
	\bigl(\prod_{s=0}^{(i-1)\wedge k}g_{k-s}(u \eta_{k})\bigr) \bigl(\prod_{s=0}^{(j-1)\wedge k}g_{k-s}(u \eta_{k})\bigr) \bigl(\prod_{s=k+1}^{i-1} \eta_{2k-s}\bigr)  \bigl(\prod_{s=k+1}^{j-1} \eta_{2k-s}\bigr),
\end{align}
and 
\begin{align}
F_2^{i,j,\ell} (u):=\begin{cases}
g_{\ell}(\eta_{2k-i-\ell}\eta_{2k-j-\ell}) &\text{if $k<i$,}\\
g_{k-i}(u g_{i+\ell-k}(\eta_{2k-i-\ell}\eta_{2k-j-\ell})) &\text{if $i\leq k <j$ and $k\leq i+\ell$,}\\
g_{\ell}(g_{k-i-\ell}(u\eta_{k})\eta_{2k-j-\ell}) &\text{if $i\leq k <j$ and $i+\ell<k$,}\\
g_{k-j}(u g_{j-i}(u g_{i+\ell-k}(\eta_{2k-i-\ell}\eta_{2k-j-\ell}))) &\text{if $j\leq k$ and $k\leq i+\ell$,}\\
g_{k-j}(u g_{\ell+j-k} (g_{k-i-\ell}(u\eta_{k})\eta_{2k-j-\ell})) &\text{if $j\leq k$ and $i+\ell< k<j+\ell$,}\\
g_{\ell}(g_{k-i-\ell}(u\eta_{k})g_{k-j-\ell}(u\eta_{k})) &\text{if $j\leq k$ and $j+\ell\leq k$}.
\end{cases}
\end{align}

[Theorem thm:main_variance of arXiv:2603.28936, 'Composition of random functions and word reconstruction'] For any integer $k\geq 1$, $w\in \{a,b\}^k$ and $u\in [0,1]$,  we have
\begin{align}
	\frac{\mathrm{Var}(Q_n^w(u))}{n} \xrightarrow{n \to \infty} c(w,u),

\end{align}
	where the function $c(w,u)$ is a computable ``measure of auto-correlation'' of $w$, whose explicit expression is given in Section~(subsec:def-cw-selfcontained of the paper).
	Moreover, if $w$ and $w'$ are not isomorphic, the functions $u\mapsto c(w,u)$ and $u\mapsto c(w',u)$ are restrictions of distinct analytic functions, and they are distinct almost everywhere on $[0,1]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Qn of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let $\mathcal Q_1,\mathcal Q_2\in \mathbb{A}^{\alpha}\cup \mathbb{B}^{\beta}$ with symbols taking values in $\mathbb{C}^{d\times d}$ and with fixed decomposition.   There exist  sequences $\{\mathcal Q_{i,n}\}_{n\ge1}$ $(i=1,2)$ such that the following properties hold:
		\begin{enumerate}[label={{\bf (\arabic*)}},leftmargin=0.79cm]\setlength\itemsep{0.2em}
			\item For $i=1,2$ and $n\ge1$, $\mathcal Q_{i,n}\in{\rm OP}\mathbf S^{-\infty}$ if $\mathcal Q_i\in\mathbb{A}^{\alpha}$ or $\mathcal Q_{i,n}\in{\rm OP}\mathbf S_0^{-\infty}$ if $\mathcal Q_i\in\mathbb{B}^{\beta}$;



			\item $\{\mathcal Q_{i,n}\}_{n\ge1}\subset \mathbb{A}^{\alpha}$ is bounded   if $\mathcal Q_{i}\in \mathbb{A}^{\alpha}$ and $\{\mathcal Q_{i,n}\}_{n\ge1}\subset \mathbb{B}^{\beta}$ is bounded if $\mathcal Q_{i}\in \mathbb{B}^{\beta}$; 

			\item Let $\delta_i=\delta_{\mathcal Q_i}$ be given in (equation delta-Qi of the paper). Then, for $i=1,2$ and $\theta\ge0$,
			\begin{align}
				\lim_{n\to\infty}\|\mathcal Q_{i,n}f-\mathcal Q_{i}f\|_{H^{\theta}} =0,\qquad f\in H_d^{\theta+\delta_i}, 
			\end{align}
			\begin{align}
				\|\mathcal Q_{i,n}-\mathcal Q_{i,m}\|_{\mathscr L(H^s,H^{\theta})} 
				\lesssim  (n \land m)^{-(s-\theta-\delta_i)},\qquad s>\theta+\delta_i,
			\end{align}
			\begin{align}
				\|\mathcal Q_{i,n}^2-\mathcal Q_{i,m}^2\|_{\mathscr L(H^s,H^{\theta})}
				\lesssim   (n \land m)^{-(s-\theta-2\delta_i)},\qquad s>\theta+2\delta_i.
			\end{align}

			\item $($\textbf{Uniform cancellation in renormalization}$)$  Let $s \ge 0$. There exist constants $C_{i,j}=C_{i,j}(s,d)>0$, for $i,j\in\{1,2\}$, such that
			\begin{equation}
				\sup_{n \ge 1} \left| \langle f, \mathcal{Q}_{i,n} f \rangle_{H^s} \right| \leq C_{i,1} \|f\|^2_{H^s}, \qquad f \in H_d^s, \quad i = 1,2,
			\end{equation}
			and
			\begin{equation}
				\sup_{n \ge 1} \left| \langle \mathcal{Q}_{i,n}^2 f, f \rangle_{H^s} + \langle \mathcal{Q}_{i,n} f, \mathcal{Q}_{i,n} f \rangle_{H^s} \right| \leq C_{i,2} \|f\|^2_{H^s}, \qquad f \in H_d^s, \quad i = 1,2.
			\end{equation}

			\item  In particular, 
			if $\mathcal Q_i\in\mathbb{B}^\beta$ satisfies $\mathcal Q_i+\mathcal Q_i^*=0$ for $i=1,2$, then for  any $s \ge 0$,
			\begin{equation*} 
				\sup_{n \ge 1} \left| \langle f, \mathcal{Q}_{i,n} f \rangle_{H^s} \right| =0, \qquad f \in H_d^s, \quad i = 1,2,
			\end{equation*}
			and
			\begin{equation*} 
				\sup_{n \ge 1} \left| \langle \mathcal{Q}_{i,n}^2 f, f \rangle_{H^s} + \langle \mathcal{Q}_{i,n} f, \mathcal{Q}_{i,n} f \rangle_{H^s} \right| =0, \qquad f \in H_d^s, \quad i = 1,2.
			\end{equation*}
		\end{enumerate}

