[Lemma l:averaging set linear map of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $B\in\cB^d$ with $\lambda_d(B)\in(0,\infty)$, $n\in\N$, $p\in\N_0$, and $F:\R^d\to\R^d$ be an affine transformation. Suppose that  $x_1,...,x_n\in\R^d$ form an averaging set of $B$ of degree $p$. Then $F(x_1),...,F(x_n)$ form an averaging set of $F(B)$ of degree $p$.
    \begin{proof}
        There is an invertible matrix $A\in\R^{d\times d}$ and a vector $b\in\R^d$ such that \linebreak$F(x) = Ax+b, x\in\R^d$. Consequently, 
        \begin{equation*}
            \frac{1}{\lambda_d(F(B))}\int_{F(B)} y^{\otimes q}\, dy = \frac{|\det(A)|}{\lambda_d(F(B))}\int_B (Ax+b)^{\otimes q} \, dx = \frac{1}{\lambda_d(B)}\int_B (Ax+b)^{\otimes q} \, dx
        \end{equation*}
        for $q\in\{0,...,p\}$.
        As every component of $x\mapsto (Ax+b)^{\otimes q}$ is a polynomial of degree $q$, the assertion follows from the fact that $x_1,...,x_n$ form an averaging set of $B$ of degree $p$, since
        \begin{equation*}
            \frac{1}{\lambda_d(B)}\int_B (Ax+b)^{\otimes q} \, dx = \frac{1}{n} \sum_{k=1}^n (Ax_k+b)^{\otimes q} = \frac{1}{n} \sum_{k=1}^n F(x_k)^{\otimes q},\quad q\in\{0,...,p\}.
        \end{equation*}
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition propo:discont of arXiv:2512.12124, 'A discontinuous percolation phase transition on the hierarchical lattice'] Consider percolation on $\mathbb{H}_L$ with respect to some isometry-invariant kernel $J$. If we define $\theta=\mathbb{P}_J ( |K_0| = \infty )$ and 
    	\begin{align}
		\beta \coloneqq \limsup_{|e|\to \infty} J(e) \frac{L^{-1}|e|^{2}}{\log\log(|e|)} ,
	\end{align}
    then one has either $\theta=0$ or $\beta \theta^2 \geq 1$.

