[Lemma 20 of arXiv:2609.01098, 'Gaussian upper bounds for averaged heat semigroups on graphs'] Let $x,y\in X$, $p\in[1,\infty]$, $C,t>0$, $r_2\geq r_1\geq 0$. Assume that for $z\in\{x,y\}$, all $\delta\in(0,1)$ and all $\omega\in\ell^\infty(X)$ we have
\[
\left(\fint_{t/2-\delta r_1^2}^{t/2+\delta r_1^2}\| {B_z(r_1)}P_\tau^\omega\|_{2,2p}^{2p}\drm \tau\right)^\frac{1}{p}
\leq C(z)\delta^{-\frac{n}{2}}(1+\delta r_2^2 h(\omega))^{\frac{n}{2}+1}\fint_{t/2-\delta r_2^2}^{t/2+\delta r_2^2}\| P_\tau^\omega\|_{2,2}^2\drm \tau.
\]
Then we have 
\begin{multline*}
\left(
\fint_{t-\frac{r_1^2}{1\vee r_2^2\sigma}}^{t+\frac{r_1^2}{1\vee r_2^2\sigma}} \| {B_x(r_1)}P_{t} {B_y(r_1)}\|_{(2p)',2p}^p\drm t 
\right)^\frac{1}{p}
\\
\leq 
2^{n+5}\sqrt{C(x)C(y)}
(1\vee r_2^2\sigma)^{\frac{n}{2}}
 \euler^{-\Lambda(t-r_2^2)-tS^{-2}\zeta(\rho(B_x(r_1),B_y(r_1))S/t)}
\end{multline*}
where $\sigma=\sigma(\rho(B_x(r_1),B_y(r_1))S/t)$ is given in Theorem~\ref{thm:abstractbound}.

