[Lemma LR of arXiv:2601.15223, 'Large time behaviour for a class of 2D and 3D stochastic non-Newtonian fluids of different'] Assume that condition (equation third-grade-paremeters-res of the paper) and Hypothesis (Hyp-f-U of the paper) are satisfied, and let $\mathfrak{r}\in\mathbb{R}$, $\omega\in\Omega$ and $B=\{B(\mathfrak{r},\omega): \mathfrak{r}\in\mathbb{R}, \; \omega\in\Omega\}\in\mathfrak{D}$. Then, for each $\varepsilon>0$ and for each $s\in[\mathfrak{r}-1,\mathfrak{r}]$, there exists $\mathfrak{k}_0:=\mathfrak{k}_0(\varepsilon,s)\in\mathbb{N}$ such that  the solution $\boldsymbol{\mathcal{Z}}(\cdot)$ to system (equation CTGF of the paper) satisfies
	\begin{align}
		\mathopen{}\mathclose\bgroup\originalleft\|\boldsymbol{\mathcal{Z}}(s;\mathfrak{r}-t,\vartheta_{-\mathfrak{r}}\omega,\boldsymbol{\mathcal{Z}}_{\mathfrak{r}-t})\aftergroup\egroup\originalright\|^2_{\mathbb{L}^2(\mathbb{Q}^{c}_{\mathfrak{k}})}\leq\varepsilon, 
	\end{align}
	for all $\boldsymbol{\mathcal{Z}}_{\mathfrak{r}-t}\in B(\mathfrak{r}-t,\vartheta_{-t}\omega)$, for all $t\geq \widetilde{\mathcal{T}}=\max\{\mathcal{T}, \widehat{\mathcal{T}}\}$ and for all $\mathfrak{k}\geq \mathfrak{k}_0$,	where  $\mathbb{Q}_{\mathfrak{k}}=\{x\in\mathbb{Q} :\,|x|< \mathfrak{k}\}$, $\mathbb{Q}^{c}_{\mathfrak{k}}=\mathbb{Q}\backslash\mathbb{Q}_{\mathfrak{\mathfrak{k}}}$,
	and   ${\mathcal{T}}$ and $\widehat{\mathcal{T}}$ are the same time given in Lemmas (LemmaUe of the paper) and (LemmaUe-24 of the paper), respectively.

[Maintheorem 2 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] Assume \(0<H<1/2\).  The following assertions hold.
\begin{enumerate}[
  label=\textup{(\themaintheorem.\arabic*)},
  ref=\themaintheorem.\arabic*,
  font=\normalfont\bfseries,
  leftmargin=*
]
\item
\emph{Tangent limit.}
If \(\tau\) is the unique maximiser of \(B\) on \([0,1]\), then there is a
probability law \(Q\) on \(\mathcal X\) such that the zooms \(\Xi_a\)
defined in \eqref{eq:tangent-zoom} satisfy
\begin{equation}
  \mathcal L(\Xi_a)\Longrightarrow Q
  \qquad\text{on }\mathcal X
  \quad\text{as }a\to\infty.

\end{equation}
The limiting law is \(H\)-self-similar: if \(X\) has law \(Q\), then, for
every \(c>0\),
\begin{equation}
  \bigl(c^H X(t/c)\bigr)_{t\in\mathbb R}
  \stackrel d= X.

\end{equation}

\item
\emph{Two-sided hard-wall limit.}
The tangent law \(Q\) in \ref{thm:main-tangent-limit} is also the path-space
limit of the finite-grid hard-wall laws from \eqref{eq:pure-wall-law}:
\begin{equation}
  Q_{h,L^-,L^+}\Longrightarrow Q

\end{equation}
whenever \(h\downarrow0\) through dyadic values and
\(L^-\to\infty\), \(L^+\to\infty\), without any restriction on the ratio of
the two horizons. Moreover,
\begin{equation}
  Q\bigl(
    f(0)=0,
    f(t)<0\text{ for every }t\in\mathbb R\setminus\{0\}
  \bigr)=1.

\end{equation}

\item
\emph{Rerooting-rescaling invariance.}
For each fixed nondegenerate compact interval
\(I\subset\mathbb R\) with \(0\notin I\), the tangent law \(Q\) is
rerooting-rescaling invariant at its maximum in \(I\) with exponent \(H\).
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defin 2 (Unconstrained model) of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] Given a Borel set $E \subset \mathcal{M}_1(\mathbb{R})$ define the mass function by

\begin{align*}

&\Pi_{N}: \mathfrak{B}(\mathcal{M}_1(\mathbb{R})) \longrightarrow \intff{0}{1} \\

    &\Pi_{N}[E] = \frac{1}{\mathcal{Z}_N^\mathsf{u} [V]}\Int{  \mathcal{A}_N }{}

\mc{I}(\bs{\la}^+_N ; \veps_N) \Delta(\boldsymbol{\lambda}_N^+) \pl{k=1}{N} \Big\{ \mathrm{e}^{- V(\lambda_k^+)} \Big\}

\, \mathbbm{1}_{E}(\op{L}_N^{(\boldsymbol{\lambda}_N^+)} )    \, \mathrm{d}\bs{\lambda}^+_N \, .
\end{align*}
Likewise we define the un-normalised mass function,

\begin{align*}

&\overline{\Pi}_{N}: \mathfrak{B}(\mathcal{M}_1(\mathbb{R})) \longrightarrow \intfo{0}{+\infty} \\

&\overline{\Pi}_{N}[E] = \frac{ (N-1)! }{  |\ln(2\veps_N)|^{N-1}}\Int{  \mathcal{A}_N }{} \mc{I}(\bs{\la}^+_N ; \veps_N)

\Delta(\boldsymbol{\lambda}_N^+) \pl{k=1}{N} \Big\{ \mathrm{e}^{- V(\lambda_k^+)} \Big\}

\, \mathbbm{1}_{E}(\op{L}_N^{(\boldsymbol{\lambda}_N^+)} )    \, \mathrm{d}\bs{\lambda}^+_N \, .

\end{align*}

