[Proposition prop.GreenEstimate of arXiv:2606.13442, 'Scaling limit of additive functionals for reversible non-gradient exclusion process: criti'] The following estimates hold for the Green function $\overline{g}_\lambda$.
		\begin{enumerate}
			\item 
			The $\ell^2$ norm is of order $\lambda^{-1}$:
			\begin{equation*}
				\norm{\overline{g}_\lambda}^2_{\ell^2(\mathbb{Z}^2)} \sim \lambda^{-1}.
			\end{equation*}
			\item 
			The Dirichlet energy is of order $\log(\lambda^{-1})$:
			\begin{equation*}
				\expec{\overline{g}_\lambda, -\tfrac{1}{2}\Delta_Q\overline{g}_\lambda}_{\ell^2(\mathbb{Z}^2)} =  \tfrac{1}{4\pi\sqrt{\det[\mathbf{D}(\rho)]}}\log(\lambda^{-1}) + O(1).
			\end{equation*}
			\item 
			The finite difference is uniformly bounded:
			\begin{equation*}
				\sup_{\lambda\in(0,1)}\sup_{i=1,2}\norm{{\mathsf{D}}_{e_i}\overline{g}_\lambda}_{\ell^\infty(\mathbb{Z}^2)}\leqslant C.
			\end{equation*}
		\end{enumerate}

