[Lemma of arXiv:2609.00425, 'Individual and Uniform Eventual Positivity of Self-Adjoint Semigroups'] The space $H$ decomposes as $H = H_{\mathrm{even}} \oplus H_{\mathrm{odd}}$, where
    \begin{align*}
        H_{\mathrm{even}}
        &\coloneqq
        \set{x\in\ell^2(\mathbb{Z}) : x_n=x_{-n}\text{ for all }n\in\mathbb{Z}}, \\
        H_{\mathrm{odd}}
        &\coloneqq
        \set{x\in\ell^2(\mathbb{Z}) : x_n=-x_{-n}\text{ for all }n\in\mathbb{Z}}.
    \end{align*}
    Moreover, the following assertions hold:
    \begin{enumerate}[\upshape (i)]
        \item The sequence $(p_n)_{n \in \mathbb{N}_0}$ is an orthonormal basis of $H_{\mathrm{even}}$, where $p_0 \coloneqq e_0$ and
        \begin{align*}
            p_n \coloneqq \frac{1}{\sqrt{2}}(e_n+e_{-n}) \in \ell^2(\mathbb{Z}), \quad n \in \mathbb{N}.
        \end{align*}
        \item The sequence $(q_n)_{n \in \mathbb{N}}$ is an orthonormal basis of $H_{\mathrm{odd}}$, where
        \begin{align*}
            q_n \coloneqq \frac{1}{\sqrt{2}} (e_n - e_{-n}) \in \ell^2(\mathbb{Z}), \quad n \in \mathbb{N}.
        \end{align*}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:S6V-seed-linear of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] Let $H = L^2(C_r)$.  The seed functions
$\psi_{t,x,m}$ and $\phi_{t,x,m}$ defined in
(equation eq:S6V-seed-def of the paper) satisfy the linear problem
(equation eq:Linear-Psi-3 of the paper) and the adjoint linear problem
(equation eq:Linear-Phi-Prob of the paper) on $\mathcal{V}$ with edge
weights $(c_k, \lambda_k)$.  Explicitly:
\begin{align}
\psi_{t,x+1,m-1}
&= \psi_{t,x,m-1} + \tau^{-1}\psi_{t,x,m},
 \\
\psi_{t-1,x,m-1}
&= \psi_{t,x,m-1} + \alpha\psi_{t,x,m},

\end{align}
and
\begin{align}
\phi_{t,x,m-1}
&= \phi_{t,x+1,m-1}
   + \tau^{-1}\phi_{t,x+1,m-2},
 \\
\phi_{t,x,m-1}
&= \phi_{t-1,x,m-1}
   + \alpha\phi_{t-1,x,m-2}.

\end{align}

[Lemma 60 (Finite negative-rank reflection) of arXiv:2608.29585, '2608.29585'] For every zero-framed knot $K$, every $m\ge1$, and every $0\le r\le m$,
\begin{equation}
 \HH_r(K;q^{-m},q)=\HH_{m-r}(K;q^{-m},q).
\end{equation}
Moreover, for every zero-framed knot $K$ and every $r\ge0$,
\begin{equation}
 \HH_r(K;q,q)=1.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 321-avoiding-permutons of arXiv:2604.23751, 'Large deviation principles for pattern-avoiding permutations, and limit shapes for constra'] The map $\Psi$ is a continuous surjective map from $\mathcal D$ to the set $\mathcal P_{\Av(321)}$ of $321$-avoiding permutons.
    Moreover, considering a $321$-avoiding permuton $\mu$ and its decomposition $\mu=\mu_{{\begin{tikzpicture}[scale=.4]
  \draw (0,0) -- (0.5,0) -- (0.5,0.5);
  \draw[thick,dotted] (0,0) -- (0.5,0.5);
\end{tikzpicture}}}+\mu_{{\, \begin{tikzpicture}[scale=.4]
  \draw (0,0) -- (0,0.5) -- (0.5,0.5);
  \draw[thick,dotted] (0,0) -- (0.5,0.5);
\end{tikzpicture}}}+\mu_{\diagup}$ as above, we have
    \begin{equation}
        \Psi^{-1}(\mu) = \big\{\proj(\mu_{{\begin{tikzpicture}[scale=.4]
  \draw (0,0) -- (0.5,0) -- (0.5,0.5);
  \draw[thick,dotted] (0,0) -- (0.5,0.5);
\end{tikzpicture}}} + \nu) : 0 \le \nu \le \mu_{\diagup} \big\} \,,
    \end{equation}
    where we recall that $\proj(\pi)$ is the pair of measures given by the projections of $\pi$ on the horizontal and vertical axes respectively.

[Theorem thm:self_scaling_convergence of arXiv:2608.29448, '\method: Self-Scaled Adaptive Preconditioning for Physics-Informed Learning'] Let $\mathcal{H}_k \in \mathbb{S}_{++}^d$ be the true Hessian at step $k$, and let $\mathbf{K}_k = \mathbf{L}_k^{-1} \otimes \mathbf{R}_k^{-1}$ be the unscaled Kronecker-factored approximation of the inverse Hessian. Let $\mathbf{s}_k = \mathbf{W}_k - \mathbf{W}_{k-1}$ be the displacement vector and $\mathbf{y}_k = \nabla \mathcal{L}(\mathbf{W}_k) - \nabla \mathcal{L}(\mathbf{W}_{k-1})$ be the change in gradients.

The scaling factor $\tau_k$ defined in (equation eq:tau_k of the paper) minimizes the spectral disparity between the secant approximation and the preconditioner along the search direction. It is the unique solution to the trace-weighted spectral matching problem
\begin{equation}
    \tau_k = \arg\min_{\tau > 0} \left| \ln \left( \frac{\mathbf{s}_k^\top \mathbf{y}_k}{\mathbf{s}_k^\top (\tau \mathbf{K}_k)^{-1} \mathbf{s}_k} \right) \right|_{\mathbf{K}_k},
\end{equation}
assuming the approximation $\mathbf{y}_k \approx \mathcal{H}_k \mathbf{s}_k$. Furthermore, this choice centers the local Rayleigh quotient of the preconditioned system $\mathbf{P}_k \mathcal{H}_k$ around unity, where $\mathbf{P}_k = \tau_k^{-1} \mathbf{K}_k$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor 88 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] For every $k\geq 0$ and $n\geq 1$, the following decomposition holds:
