body:
[Lemma expansions of arXiv:2603.27906, 'Marked GUE-corners process in doubly periodic dimer models'] Let~$z_k=1+\frac{Z_k}{N^\frac{1}{2}}$,~$k=1,2$, with $|Z_k|< N^{\frac{1}{2}}$ (on the canonical local chart in this text, at a neighbourhood of $q_{\infty}$). Then, as~$N\to \infty$, we have that
\begin{equation} 
\exp(NG(z_k,w_k))= \exp\left(NG(1)+\frac{\sigma^2}{2}Z_k^2+\mathcal{O}\left(\frac{|Z_k|^3}{N^{\frac{1}{2}}}\right)\right),
\end{equation}
\begin{equation} 
w_k^{r_k}=
Z_k^{-\ell r_k} 
N^{\frac{\ell r_k}{2}} 
\left(B+\mathcal{O}\left(\frac{|Z_k|}{N^{\frac{1}{2}}}\right)\right)^{r_k}
=
Z_k^{-\ell r_k} 
N^{\frac{\ell r_k}{2}} 
B^{r_k}\left(1+\mathcal{O}\left(\frac{r_k |Z_k|}{N^{\frac{1}{2}}}\right)\right),
\end{equation}
and
\begin{equation} 
z_i^{\sqrt{N}\mu_k}=\left(1+\frac{Z_k}{ \sqrt{N}}\right)^{\mu_k\sqrt{N}}=\exp\left(\mu_k Z_k+\mathcal{O}\left(\frac{\mu_k |Z_k|^2}{N^{\frac{1}{2}}}\right)\right),
\end{equation}
where $B$ is as in Lemma (lemma:local_action_function of the paper).

