[Lemma 45 of arXiv:2608.18075, '2608.18075'] Fix $T<\infty$. There is a deterministic constant
$C_{{\rm loc},T}\ge1$ such that, if
\begin{align*}
 \mathcal L_T(w_0,y)
 &=\exp\left(C_{{\rm loc},T}
       (1+\mathbb W_T(w_0,y)^{q_\sigma})\right),\\
 \delta_T(w_0,y)
 &=\min\left\{1,\frac1{8\mathcal L_T(w_0,y)^2}\right\},
\end{align*}
then the following assertions hold for every $(w_0,y)\in H^b\times\mathsf Y_T$.
\begin{enumerate}[label=\textup{(\roman*)}]
\item
On the open $H^b\times\mathsf Y_T$ ball
\begin{align*}
 B_{H^b\times\mathsf Y_T}
 \left((w_0,y),\frac{\delta_T(w_0,y)}2\right),
\end{align*}
the map $(x,\tilde y)\longmapsto
\bigl(v^{x,\tilde y},w_T^{x,\tilde y}\bigr)$ 
is twice Fr\'echet differentiable from $H^b\times\mathsf Y_T$ into
$C([0,T];H^b)\times H^b$, with continuous operator valued first and
second derivatives. In particular, for every
$\|(h,k)\|_{H^b\times\mathsf Y_T}<\delta_T(w_0,y)/2$,
\begin{align}
 \|w^{w_0+h,y+k}\|_{L^{p_\sigma}(0,T;H^b)}
 \le \mathbb W_T(w_0,y)+C_T.
\end{align}

\item
For $\mathsf p_0\in H$, put
\begin{align*}
 w^{\circ,x,\tilde y}
 &=v^{x,\tilde y}+\tilde y^\circ,
 \qquad
 \rho_t^{x,\mathsf p_0,\tilde y}
 =U_{w^{\circ,x,\tilde y}}(t,0)\mathsf p_0.
\end{align*}
Then
\begin{align*}
 (x,\mathsf p_0,\tilde y)\longmapsto
 \bigl(w_T^{x,\tilde y},\rho_T^{x,\mathsf p_0,\tilde y}\bigr)
\end{align*}
is locally twice Fr\'echet differentiable into $H^b\times H$, again
with continuous operator valued first and second derivatives. On the
open set where $\rho_T\ne0$, projective normalisation gives an
operator norm $C^2$ projective endpoint.

\item
Let
\begin{align*}
 \mathcal V_T:H^b\times\mathsf Y_T\longrightarrow C([0,T];H^b),
 \qquad
 \mathcal V_T(x,\tilde y)=v^{x,\tilde y}.
\end{align*}
For
$\|(h,k)\|_{H^b\times\mathsf Y_T}<\delta_T(w_0,y)/2$, set
\begin{align*}
 \Xi_1^{h,k}
 &=
 \bigl\|D\mathcal V_T(w_0+h,y+k)\bigr\|_
 {\mathcal L(H^b\times\mathsf Y_T,C([0,T];H^b))},\\
 \Xi_2^{h,k}
 &=
 \bigl\|D^2\mathcal V_T(w_0+h,y+k)\bigr\|_
 {\mathcal L^{(2)}(H^b\times\mathsf Y_T,C([0,T];H^b))},
\end{align*}
and put
\begin{align*}
 \mathcal X_T(w_0,y)
 =
 1+\sup_{\|(h,k)\|_{H^b\times\mathsf Y_T}<\delta_T(w_0,y)/2}
 \bigl(\Xi_1^{h,k}+\Xi_2^{h,k}\bigr).
\end{align*}
Then
\begin{align}
 \log\delta_T(w_0,y)^{-1}
 +\log^+\mathcal X_T(w_0,y)
 \le C_T\bigl(1+\mathbb W_T(w_0,y)^{q_\sigma}\bigr).
\end{align}
\end{enumerate}

