body:
[Thm ThmMainGLN of arXiv:2605.06429, '\large \bf $\mathsf{GL}_N(\mathbb{C})$ BROWNIAN MOTION AND STOCHASTIC PDE ON ENTIRE FUNCTI'] Let $\theta\in \mathbb{R}$ be fixed. Then, there exists a unique Feller diffusion process $(\mathbf{X}_{GL}^t)_{t\ge 0}$ on $\Upsilon_+$ such that whenever, 
\begin{equation*}
\left((N^{-1}\mathsf{x}_i^{(N)}(0))_{i\in \mathbb{N}},N^{-1}\sum_{i=1}^\infty \mathsf{x}_i^{(N)}(0)\right)  \overset{N \to \infty}{\longrightarrow} \boldsymbol{v}=((x_i)_{i\in \mathbb{N}},\gamma)\in \Upsilon_+,
\end{equation*}
we have, as $N \to \infty$,
\begin{equation*}
\left((N^{-1}\mathsf{x}_i^{(N)}(\bullet))_{i\in \mathbb{N}},N^{-1}\sum_{i=1}^\infty \mathsf{x}_i^{(N)}(\bullet)\right) \overset{\mathrm{d}}{\longrightarrow} \left((\mathsf{x}_i(\bullet))_{i\in \mathbb{N}},\boldsymbol{\gamma}(\bullet)\right)\overset{\mathrm{def}}{=} \mathbf{X}_{GL}^\bullet
\end{equation*}
in $\mathrm{C}(\mathbb{R}_+;\Upsilon_+)$
where $\mathbf{X}_{GL}^0=\boldsymbol{v}$, and $\overset{\mathrm{d}}{\longrightarrow}$ denotes convergence in distribution.
Furthermore, for any $\gamma\ge \sum_{i=1}^\infty x_i$, whenever $(x_i)_{i\in \mathbb{N}}\in \mathbf{W}_{\infty;+}^\circ$, the projection of $\mathbf{X}_{GL}^\bullet$ on the $(\mathsf{x}_i(\bullet))_{i\in \mathbb{N}}$ solves the infinite system of SDE
\begin{equation}
\mathsf{x}_i(t)= x_i+\int_0^t\mathsf{x}_i(s)\mathrm{d}\mathsf{w}_i(s) + \frac{\theta}{2}\int_0^t\mathsf{x}_i(s)\mathrm{d}s
 +\int_0^t\sum_{j=1,j\neq i}^{\infty}\frac{\mathsf{x}_i(s)\mathsf{x}_j(s)}{\mathsf{x}_i(s)-\mathsf{x}_j(s)}\mathrm{d}s, \  \forall t\ge 0 , \   i \in \mathbb{N},
 \end{equation}
with independent standard Brownian motions $(\mathsf{w}_i)_{i\in \mathbb{N}}$ and $(\mathsf{x}_i(t))_{i\in \mathbb{N},t\in \mathbb{R}_+}$ viewed as a line ensemble satisfies a  Gibbs  property with respect to exponential Brownian bridges. Moreover, as $N\to \infty$,
\begin{equation*}
\mathfrak{gl}_{\bullet;N}\overset{\mathrm{d}}{\longrightarrow} \mathfrak{gl}_\bullet,
\end{equation*}
in $\mathrm{C}(\mathbb{R}_+;\mathfrak{LP}_+)$ where $\mathfrak{gl}_t(z)=\mathfrak{E}_{\mathbf{X}_{GL}^t}^+(z)$ is a Markov process with values in $\mathfrak{LP}_+$ which solves the following stochastic partial differential equation 
\begin{equation}
\mathrm{d}\mathfrak{gl}_t(z)=\mathrm{d}\mathsf{M}_t(z;\mathfrak{gl})+\left[\frac{\theta}{2}z\partial_z\mathfrak{gl}_t(z)
    -
    \frac{z^2}{2}\partial_{z}^2\mathfrak{gl}_t(z)\right]\mathrm{d}t
\end{equation}
where $\mathsf{M}\in \mathrm{C}(\mathbb{R}_+;\mathsf{H}(\mathbb{C}))$ and for all $z\in \mathbb{C}$, $t\mapsto \mathsf{M}_t(z;\mathfrak{gl})$ are continuous local martingales with covariation, for $z,w \in \mathbb{C}$,
\begin{equation}
\langle \mathsf{M}_t(z;\mathfrak{gl}),\mathsf{M}_t(w;\mathfrak{gl})\rangle=\frac{zw}{z-w}\int_0^t\left(\mathfrak{gl}_s(z)\partial_w\mathfrak{gl}_s(w)-\mathfrak{gl}_s(w)\partial_z\mathfrak{gl}_s(z)\right)\mathrm{d}s.
\end{equation}
Finally, for $\theta<0$, we have,  as $t \longrightarrow \infty$,  $\mathfrak{gl}_t(z)\overset{\mathrm{d}}{\longrightarrow} 1$ in $\mathfrak{LP}_+$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def1 of arXiv:2606.27844, 'Critical percolation on preferential attachment graphs with infinite variance'] Let $m\leq n$ be an integer and $s=s(n)$ such that $m\le sn \le n$. 
  \begin{enumerate}
    \item  Let $x,y \in \{1,\dots,n\}$ be two vertices in $\mathscr{G}_n$. We call $u\in\{ \lfloor sn \rfloor +1,
    \dots,n\}$ a \emph{one-connector} for $x$ and $y$, if $x\sim u$ and $u\sim y$ in $\mathscr{G}_{n}$. If two vertices $x$ and $y$ are distinct and connected by a one-connector we write \smash{$x\overset{_1}{\longleftrightarrow} y$}.
    \item We define the \emph{core graph} by its vertex set $C_m=\{1,\dots,m\}$  and edge set
        \begin{align*}
            E_m:=\big\{\{x,y\}\subset C_m  \,:\, x\overset{1}{\longleftrightarrow} y   \big\}\;.
        \end{align*}
\end{enumerate}

[Theorem thm_monton of arXiv:2607.05054, 'Root Dynamics of Differentiated Polynomials with Rotationally Invariant Structure'] Let $ n \geq 2 $, $w_1, \ldots, w_n > 0$, and $a, b \geq 0$ be integers with $ b < n $. Let $P$ be a monic polynomial of degree $ n $ with real roots $ z_1 \leq \cdots \leq z_n $. Define the operator $ \mathcal{O}_{a,b} $ which maps $P$ to $Q(z): = z^a \cdot P^{(b)}(z)$, where $ P^{(b)} $ is the $b$-th derivative of $ P $. Let $\Delta_n$ be the set of nondecreasing sequences $ (z_1, \ldots, z_n) \in \mathbb{R}^n $. The map $ \Phi_{a,b} : \Delta_n \to \Delta_{n - b + a} $ sending the roots of $ P $ to the nondecreasing sequence of roots of $Q$ satisfies: 
    \begin{enumerate}
        \item \textbf{Monotonicity}: If $ (z_1, \ldots, z_n) \preccurlyeq (z_1', \ldots, z_n') $ in $ \Delta_n $, then 
    \begin{align}
    \Phi_{a,b}(z_1, \ldots, z_n) \preccurlyeq \Phi_{a,b}(z_1', \ldots, z_n') \quad \text{in} \quad \Delta_{n - b + a},
    \end{align}
    where $(u_1, \dots, u_p) \preccurlyeq (u'_1, \dots, u'_p)$ if and only if $u_j \leq u'_j$ for all $j \in \{1, \dots, p\}$. 
     \item \textbf{Lipschitz continuity}: If $ w_1 = \cdots = w_n $, then the map $\Phi_{a,b}$ is $ \frac{n}{n - b} $-Lipschitz in the Lévy metric for empirical measures.
    \end{enumerate}

