[Definition 4 of arXiv:2506.17109, 'Limit theorems under nonlinear expectations dominated by sublinear expectations'] Let $\{ \mathbb{\tilde{F}}_{i}[\cdot]\}_{i=1}^{\infty}$ be a
sequence of nonlinear expectations on $(\mathbb{R}^{d},C_{b.Lip}
(\mathbb{R}^{d}))$. $\{ \mathbb{\tilde{F}}_{i}[\cdot]\}_{i=1}^{\infty}$ is
called tight if there exists a tight sublinear expectation $\mathbb{\hat{F}
}[\cdot]$ on $(\mathbb{R}^{d},C_{b.Lip}(\mathbb{R}^{d}))$ such that
$\mathbb{\tilde{F}}_{i}[\cdot]$ is dominated by $\mathbb{\hat{F}}[\cdot]$ for
$i\geq1$.

[Proposition prop:2d_kernel_BGR of arXiv:2507.22011, 'Random Lozenge Waterfall:\\Dimensional Collapse of Gibbs Measures'] {borodin-gr2009q}}]

	The two-dimensional correlation kernel $\widetilde{K}(s,x;t,y)$
	of the $q$-Racah nonintersecting path ensemble is given by
	\begin{equation}

		\widetilde{K}(s,x;t,y)=
		\begin{cases}
			\displaystyle
			\sum_{n=0}^{N-1}
			(\widetilde{\mathscr{C}}_n^{t} \widetilde{\mathscr{C}}_n^{t+1}\ldots \widetilde{\mathscr{C}}_n^{s-1})^{-1}\hspace{1pt}
			f_n^s(x)\hspace{1pt} f_n^t(y),&\qquad  s\ge t;\\[12pt]
			\displaystyle
			-\sum_{n\ge N}
			(\widetilde{\mathscr{C}}_n^s \widetilde{\mathscr{C}}_n^{s+1}\ldots \widetilde{\mathscr{C}}_n^{t-1})\hspace{1pt}
			f_n^s(x)\hspace{1pt} f_n^t(y)
			,&\qquad  s<t.
		\end{cases}
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 10 of arXiv:2606.20169, 'THEORY OF UNCERTAIN PROBABILITY:\\ CAN WE DERIVE THE PROBABILITY DENSITY FUNCTION OF UNCER'] The variance of an uncertain random variable $\mathbb{X}$ is defined by
\begin{equation}
\begin{aligned}
\sigma_{\mathbb{X}}^2=Var\left(\mathbb{X}\right)=E\left[\left(\mathbb{X}-E(\mathbb{X})\right)^2\right].
\end{aligned}
\end{equation}

Its nonnegative square root denoted by $\sigma_{\mathbb{X}}$ is the standard deviation of $\mathbb{X}$. If $z$ is a positive integer, then $E\left(\mathbb{X}^z\right)$ is called the $z$th moment of $\mathbb{X}$.

[Proposition prop for tightness two of arXiv:2504.06238, 'Infinite Boundary Friction Limit for Weak Solutions of the Stochastic Navier-Stokes Equati'] For any sequence of stopping times $(\gamma_n)$ with $\gamma_n: \Omega \rightarrow [0,T]$, and any  $R > 1$, $\phi \in W^{1,2}_{\sigma}$,
    \begin{equation} 
    \lim_{\delta \rightarrow 0^+}\sup_{n \in \mathbb{N}}\mathbbm{E}\left(\left\vert\left\langle \hat{u}^{n}_{(\gamma_n + \delta) \wedge T} - \hat{u}^{n}_{\gamma_n} , \phi \right\rangle \right\vert\right)= 0.
\end{equation} 
Moreover the sequence of the laws of $(u^n)$ is tight in the space of probability measures over\\ $C\left([0,T];W^{-\varepsilon,2}_{\sigma}\right)$.

[Definition of arXiv:2411.12522, 'Canonical insurance models: stochastic equations and comparison theorems'] Given the canonical measurable space $(\Omega,\mathcal{F}_\infty)$, the probability mesaure $\mathbb{P}$ on $(\Omega,\mathcal{F}_\infty)$, the probability kernels $\mathbb{P}_s^i$, $s\in[0,\infty)$, $i\in\mathcal{Z}$, on $(\Omega,\mathcal{F}_\infty)$, and the collection
\begin{align*}
\mathcal{P} := \big((\mathbb{P}_s^i)_{s \in [0,\infty),i\in\mathcal{Z}},\mathbb{P}\big)
\end{align*}
defined by Theorem~(TheoremCanoncialSpace of the paper) are called the \emph{canonical probability measure}, \emph{canonical probability kernels}, and \emph{canonical probability model} generated by $(\alpha, \Lambda)$, respectively.

[Proposition propHidden of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] For any solution to the equation (equation ch-5-4.12-eq1 of the paper), we have

\begin{align}
    \notag
    &  \Big|\frac{\partial y}{\partial \nu}\Big
    |_{L^2_{{\mathbb{F}}}(0,T;L^2(\Gamma_0))} 
    \\ \notag
    & \leq e^{{\cal C}(L^2 + 1)}
    \Big(|(y_0,y_1)|_{L^2_{{\cal F}_0}(\Omega; H_0^1(G)\times L^2(G))}+ |F(\cdot,\cdot,0,0,0)|_{L^2_{{\mathbb{F}}}(0,T;L^2(G))} 
    \\
