[Lemma 14 (Electric cancellation at zeroth order) of arXiv:2609.01589, 'Uniform stability of expanding simple waves for Euler--Poisson--Boltzmann: a singular comp'] Assume the bootstrap bounds of \cref{sec:high-order}.  The electric work in
the fluid perturbation energy satisfies
\begin{equation}
\begin{split}
  -\int_\Om n v\cdot\nabla\psi\,\dd x
  =-&\frac{\dd}{\dd t}\int_\Om
  \left\{\frac{\eps^2}{2}\abs{\nabla\psi}^2
  +\cH_e^*(\psi;\phi^a)\right\}\,\dd x
  +\mathfrak e_0, 
\end{split}
\end{equation}
where
\begin{equation}
  \abs{\mathfrak e_0}
  \le C\bigl(K_a(t)+\norm W_{H^s}\bigr)\cE_{s,\eps}
  +C\bigl(\mathfrak R_s^a\bigr)^2. 
\end{equation}
Here $K_a$ is a bounded combination of profile derivatives.

[Lemma lem : FdTmon/UpperBound/Heredity of arXiv:2412.03320, 'Large deviation principle at speed $n$ for the random metric in first-passage percolation'] For all $K\in \mathbb{N}$,
	\begin{equation}

		\FdTmonsup(D_{K+1}) \le \FdTmonsup(D_{K}) + \int_0^L J_{\mathrm{pp}} \p{\sigma_{K+1}'(t), \module[D]{\dot{\sigma}_{K+1} }(t) } \mathrm{d} t.
	\end{equation}

