[Defin 6 of arXiv:2604.03548, 'Degree-preserving conservative processes and a unified approach for their hydrodynamics'] Let $\rho_0\in L^2(\mathbb T)$. A measurable function $\rho: [0,T] \times \mathbb{T} \to \mathbb R$ is a weak solution to the heat equation with initial profile $\rho_0$
\begin{equation}  

\begin{cases}
\begin{aligned}
& \partial_t \rho(t,u) = D\Delta \rho(t,u)
&& (t,u) \in {(0,T)} \times \mathbb{T},
\\
& \rho(0,u) = \rho_0(u) && u \in \mathbb{T}
\end{aligned}
\end{cases}
\end{equation}
if $\rho \in L^2 ([0,T]\times \mathbb T)$ and for all $t \in [0, T]$ and  $H \in C^{1,2}([0, T] \times \mathbb{T}) $ it holds
\begin{equation}
\int_{\mathbb T} \rho(t,u)H(t,u) du
- \int_{\mathbb T} \rho_0(u)H(0,u) du 
- \int_0^t \int_{\mathbb T} \rho(s,u)(\partial_s + \Delta) H(s,u)du ds
= 0. 
\end{equation}

[Lemma lem:support-identity of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] We have
\begin{equation}
  F(z)^2=2Q(z)+F(z^2)+2C(z)-2.
\end{equation}

[Proposition coaff of arXiv:2412.02486, 'On the curvatures of \\ random complex submanifolds'] [bettigayet] Let $f:\mathbb{C}^n \to \mathbb{C}^r$ be $r$ independent copies of the Bargmann--Fock field. 
	Then, 
	\begin{equation*}
	\ensuremath \mathrm{Cov} (f(0), \nabla_0 f(0),\nabla_0^2f(0)) = \ensuremath \mathrm{Cov}_{\mathrm{BF}},
	\end{equation*}
	where 
	\begin{equation}
	\ensuremath \mathrm{Cov}_{\mathrm{BF}}:=	 \begin{pmatrix}
	1 & 0 & 0\\
	0   & \pi \ \ensuremath \mathrm{Id}_{\mathbb{C}^n}  & 0\\
	0&0& \pi^2\Sigma_\mathrm{GOE}
	\end{pmatrix} \otimes \ \ensuremath \mathrm{Id}_{\mathbb{C}^r}.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:compactness-fibered-probability-measures of arXiv:2606.21556, 'Mean field limit of non-exchangeable interacting diffusions on co-evolutionary networks'] The space \((\widetilde{\mathcal{P}}_{\nu}(\mathcal{X}\times [0,1]),\delta_{\text{BL},1})\) is Polish. Moreover we have:
	\begin{enumerate}
		\item[(i)] A subset \(\mathcal{K}\subset (\widetilde{\mathcal{P}}_{\nu}(\mathcal{X}\times [0,1]),\delta_{\text{BL},1})\) is relatively compact if and only if it is tight.
		\item[(ii)] The space \((\widetilde{\mathcal{P}}_{\nu}(\mathcal{X}\times [0,1]),\delta_{\text{BL},1})\) is compact if and only if \(\mathcal{X}\) is compact.
	\end{enumerate}

[Prop weak_sec_H_-1 of arXiv:2411.06861, 'Quenched invariance principle for random walks in random environments admitting a cycle de'] Under the same assumption of Lemma (lem:corrector_construction of the paper), 

  \begin{enumerate}[(i)]
  \item
    The domain the Dirichlet form given in (equation eq:def:dirichlet_form_annealed of the paper) can be extended to $L^{2}(\mu \mathbb{P}) \times L^{2}(\mu \mathbb{P})$, and satisfies a \emph{weak sector condition}: there exists a constant $C_{\mathrm{sec_w}} > 0$ such that

    \begin{align}

      \abs{\mathcal{E}(\xi, \varphi)}^{2}
      \;\leq\;
      C_{\mathrm{sec_w}} \norm{\xi}^{2}_{L^2(\mu\mathbb{P})}\, \norm{\varphi}^{2}_{L^2(\mu\mathbb{P})},
      \qquad \forall\, \xi, \varphi \in L^{2}(\mu\mathbb{P});
    \end{align}

  \item
    for $i = 1, \dots, d$, and $V^{i}$, $\alpha$ given in (equation eq:def:local_drift of the paper)  and Assumption~(ass:finite_H_-1_norm of the paper),

    \begin{align}

      \abs{\mathbb{E}[\xi V^i(\cdot, 0)]}
      \;\leq\;
      \sqrt{2} \alpha\, \norm{D\xi}_{\mathrm{cov}},
      \qquad \forall\, \xi \in L^2(\mu\mathbb{P}).
    \end{align}
  \end{enumerate}

