[Theorem eq:linear_seat of arXiv:2411.14818, 'Scaling limits of solitons in the Box-Ball system'] Suppose that $\eta \in \Omega$. Then, for any $k \in {\mathbb{N}}$ and $i \in {\mathbb{Z}}$, we have
                    \begin{align}
                        \zeta_{k}\left(T\eta, i +  k + o_{k}\left(\eta\right) \right) = \zeta_{k}\left(\eta, i \right),
                    \end{align}
                where the offset $o_{k}\left(\eta\right)$ is given by 
                    \begin{align}
                        &o_{k}\left(\eta\right) \\
                        &:= s_{\infty}\left(\eta,0\right) - s_{\infty}\left( T\eta,0\right) + 2\sum_{y = s_{\infty}\left(0\right)+ 1}^{0} \sum_{\ell = 1}^{k}  \eta^{\downarrow}_{\ell}\left(y\right) - 2\sum_{y = Ts_{\infty}\left(0\right)+1}^{0}\sum_{\ell = 1}^{k}  T\eta^{\uparrow}_{\ell}\left(y\right).
                    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 16 (The fluid variable array $\wavearray$ and the partial array $\wavearraypartial$) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] We define the \emph{array of wave\footnote{These ``wave-variables'' solve wave equations; 
see Theorem\,\ref{T:GEOMETRICWAVETRANSPORTSYSTEM}.} variables} as follows:
\begin{subequations}
\begin{align}  
\wavearray 
& \eqdef (\Psi_0,\Psi_1,\Psi_2,\Psi_3,\Psi_4) 
\eqdef (\LogDensity,v^1,v^2,v^3,\Ent).
\end{align}We define the \emph{partial array of wave-variables} by:
\begin{align} 
	\wavearraypartial 
	& \eqdef (\Psi_1,\Psi_2,\Psi_3,\Psi_4)
	 = (\LRiemann,v^2,v^3,\Ent).
	\end{align}  
	\end{subequations}
We define the \emph{array of velocity variables} by:
	\begin{align} 
		\velocityarray \eqdef (v^1,v^2,v^3).
	\end{align}

We define the \emph{array of small velocity variables} by:
	\begin{align} 
		\velocityarraypartial \eqdef (v^2,v^3)
	\end{align}

