[Lemma 13 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] Assume that $d,M,N,y$ satisfy all conditions in Lemma \ref{lemme_technical_high_dimension}. For any $\epsilon>0$, there exists $c(d,\epsilon)>0$ such that  
 	  	\begin{equation}
 	  	  \mathbb{P}\big( \mathcal{V}^+_y(M)  \le cM^4 \mid  \bm{0}\xleftrightarrow{\ge 0} y \big) \le \epsilon.  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 2 of arXiv:2605.06556, 'Probability of Quota Violations in Divisor Apportionment Methods with Nonzero Allocations'] Let $A$ be a divisor method that guarantees nonzero allocations on $M$ seats and suppose the populations are ordered such that $p_1 < \cdots < p_n$. The apportionment $A(p_1, \dots, p_n)$ exhibits a \emph{quota violation caused by nonzero allocations} if the following conditions hold:
\begin{enumerate}
\item $A(p_1, \dots, p_n)$ violates the quota rule.
\item $\tilde{A}(p_1, \dots, p_n) = A(p_1, \dots, p_n)$.
\item When apportioning $M$ seats $A(p_{2}, \dots, p_n)$ does not violate the quota rule.
\end{enumerate}

[Theorem 9 (Existence, minimality, and covariance of the support) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] The family $\cS(F)$ has the following properties.
\begin{enumerate}[label=\textup{(\roman*)}]
 \item Every kernel in \eqref{primitive:eq:F-expansion} satisfies
 \begin{equation}
  g_{a,q,\bm m}
  \in\widehat\bigotimes_{s=1}^Q \cS_s(F)^{\odot m_s}.

 \end{equation}
 \item If closed graded subspaces $T_s\subset E_s$ also satisfy
 $
 g_{a,q,\bm m}\in\widehat\bigotimes_sT_s^{\odot m_s}
 $
 for every $a,q,\bm m$, then
 \begin{equation}
  \cS_s(F)\subset T_s
  \qquad(1\le s\le Q).

 \end{equation}
 \item Every $\cS_s(F)$ is separable, even when $E_s$ is not separable.
 \item If $U_s:E_s\to E_s'$ are grade-preserving unitaries and
 $\Gamma(U)F$ is the transported packet, then
 \begin{equation}
  \cS_s(\Gamma(U)F)=U_s\cS_s(F).

 \end{equation}
\end{enumerate}
Thus $\cS(F)$ is the unique minimal graded one-particle support of the
represented packet.

[Lemma lem: inherit local information of arXiv:2411.16398, 'Large Deviations of Cover Time of Tori in Dimensions $d\geq 3$'] Suppose $\omega \in \mathcal{A}$ and $\overline{\omega} \in \overline{\Psi}(\omega)$. 
    For all $\boldsymbol{x}_j \in \mathcal{R}(\mathcal{L}_{\boldsymbol{F}}^{\beta_N}(\omega))$: 
    \begin{enumerate}[label=(\roman*)]
        \item If the type of $\boldsymbol{x}_j$ is (d), we have 
        \begin{equation}

            \mathsf{Dir}(\overline{\omega},H_{\beta_N}(\overline{\omega},\boldsymbol{x}_j))=\mathsf{Dir}(\overline{\omega},H_{\beta_N}(\overline{\omega},\boldsymbol{x}_j)-1).
        \end{equation}
        \item If the type of $\boldsymbol{x}_j$ is not (d), we have
        \begin{equation}

            \mathsf{Dir}(\overline{\omega},H_{\beta_N}(\overline{\omega},\boldsymbol{x}_j)+i)=\mathsf{Dir}(\beta^{(j)},H_0(\beta^{(j)},\boldsymbol{x}_j)+i), \quad i\in\{0,\pm 1\}.
        \end{equation}
    \end{enumerate}

[Definition 2 (Regulated processes) of arXiv:2605.04359, 'Well-posedness of reflected BSDEs with default time and irregular barrier: An application '] \begin{itemize}
		\item A process $\mathcal{X}: \Omega \times [0,T] \rightarrow \mathbb{R}$ is said to be a regulated process if for $\mathbb{P}$-almost all $\omega \in \Omega$, the function $t \mapsto \mathcal{X}_t(\omega)$ has finite right limits at each point $t \in [0,T)$, and finite left limits at each point of $(0,T]$.
		\item For any process $\mathcal{X}: \Omega \times [0,T] \rightarrow \mathbb{R}$ with regulated trajectories, we set
		\begin{itemize}
			\item $\mathcal{X}_{s-}=\lim\limits_{u \nearrow s} \mathcal{X}_u$ the left limit of $\mathcal{X}$ at $s \in ]0,T]$ and $\Delta_{-} \mathcal{X}_{s}=\mathcal{X}_{s}-\mathcal{X}_{s-}$ with the convention $\Delta_{-} \mathcal{X}_{0}=0$.
			\item $\mathcal{X}_{s+}=\lim\limits_{s\swarrow u} \mathcal{X}_u$ the right limit of $\mathcal{X}$ at $s \in [0,T[$ and $\Delta_{+} \mathcal{X}_{s}=\mathcal{X}_{s+}-\mathcal{X}_{s}$ with the convention $\Delta_{+} \mathcal{X}_{T}=0$.
		\end{itemize}
		\item Let $\mathcal{K}: \Omega \times [0,T] \rightarrow \mathbb{R}$ be a finite variation, regulated process, then we write $\mathcal{K}=\mathcal{K}^d+\mathcal{K}^c+\mathcal{K}^g$, where the process $\mathcal{K}^c$ is continuous, the RCLL process $\mathcal{K}^d$ equals $\mathcal{K}^d_t=\sum_{0 < s \leq t}\Delta_{-}\mathcal{K}_{s}$
		and the LCRL process $\mathcal{K}^g$ is given by $\mathcal{K}^g_t=\sum_{0 \leq s < t}\Delta_{+}\mathcal{K}_{s}$. This also means that $\mathcal{K}_t=\mathcal{K}^{\ast}_t+\sum_{0 \leq s < t}\Delta_{+}\mathcal{K}_{s}$ where the RCLL process $\mathcal{K}^{\ast}$ represents the right-continuous part of the process $\mathcal{K}$ satisfying
		$\mathcal{K}^{\ast}=\mathcal{K}-\mathcal{K}^g=\mathcal{K}^c+\mathcal{K}^d$ and $\mathcal{K}^g$ it's purely jumping part.
	\end{itemize}

[Cor corollary:L*sirvepatodo of arXiv:2411.12717, 'Excursion theory for Markov processes indexed by Lévy trees'] We can find a measurable subset of full   $\mathbf{N}_{x,r}$ measure at which we have
     \begin{equation}
    L^*_t(\rho, W)= L_t(\rho , W), \quad t \geq 0,  
\end{equation}
and
    \begin{equation}
    L^*_t(\emph{tr}(\rho, W))= L_{\Gamma_t(\rho,W)}(\rho , W), \quad t \geq 0.   
\end{equation}
In particular,    in a  measurable subset of full $\mathbf{N}^*_x$  measure, the process $(L^*_t: t \geq 0)$ is  continuous, non-decreasing and null at $0$.

[Defi of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] [AGS08]
    Let $(S,d)$ be a metric space and $F:S\to (-\infty,\infty]$ measurable. Let $D(F):=\{s\in S\mid F(s)<\infty\}$ be the domain of $F$. The local slope $ \left\lvert\partial  F\right\rvert$ of $F$ is defined by \begin{align*}
        \left\lvert\partial  F\right\rvert(s):=\limsup_{s'\to s}\frac{(F(s)-F(s'))_+}{d(s,s')},\quad \forall s\in D(F).
    \end{align*}

[Definition def:locally dissipative of arXiv:2411.01364, 'Global Dynamics of Granular Media Equations via Stochastic Order'] The equation (equation eq:mvsystem of the paper) is called locally dissipative at $a\in\mathbb R$ with configuration $(r,g)$, if
\begin{enumerate}[label=(\roman*)]
\item the function $g:\mathbb R_+\times\mathbb R_+\to\mathbb R$ satisfies, for all $x\in\mathbb R$, $\mu\in\mathcal P_2(\mathbb R)$,
\begin{equation*}
-2xV'(x+a)-2x(W'*\mu)(x)+\sigma^2(x+a)\leq -g(x^2,\|\mu\|_2^2);
\end{equation*}
\item the number $r>0$ and the function $g$ satisfy
\begin{equation*}
\begin{split}
&g(\cdot,r^2) \text{ is continuous and convex};\\
&\inf_{0\leq w\leq r^2}g(z,w)=g(z,r^2);\\
&\inf_{z\geq r^2}g(z,r^2)>0.
\end{split}
\end{equation*}
\end{enumerate}

