[Lemma lem:bounds-f^regular of arXiv:2411.12076, 'Explicit solutions of the SI and Bass models on sparse Erd\H{o}s-R\'enyi and regular netwo'] Consider the Bass/{\rm SI} model~{\rm ((eqs:Bass-SI-models-ME of the paper),(eqs:d-regular-network of the paper))} on  infinite $d$-regular networks. 
	\begin{enumerate}
		\item 
		When $d=2$, the expected adoption level is the same as on infinite circles/lines,
		i.e., 
		\begin{equation}

			f^{\rm 2-regular}(t;p,q,I^0) \equiv f^{\rm 1D}(t;p,q,I^0),
		\end{equation}


		where
				\begin{equation}

			f^{\rm 1D}:=
			\begin{cases}
				1-(1-I^0) e^{-(p+q)t+ q(1-I^0)\frac{1-e^{-pt}}{p}}, &\ \text{\rm if} \ p>0,\\
				1-(1-I^0) e^{-qI^0 t

				}, & \ \text{\rm if} \ p=0.
			\end{cases}
		\end{equation}




			\item  

			$\lim_{d \to \infty} f^{ \text{\rm d-reg}}(t;p,q,I^0) = f^{\rm compart}(t;p,q, I^0)$,
			where $ f^{\rm compart}$ is the expected adoption/infection level
		in the  compartmental Bass/{\rm SI} model~(equation eq:f^complete_infty-ODE of the paper).
		\item  For $d=2,3, \dots$,
		\begin{equation}

			f^{\rm 1D}(t;p,q,I^0) \le f^{ \text{\rm d-reg}}(t;p,q,I^0)  < f^{\rm compart}(t;p,q, I^0), \qquad t>0.
		\end{equation}
	\end{enumerate}

[Lemma 16 of arXiv:2510.22533, 'Marginal dynamics of probabilistic cellular automata on trees'] Suppose Condition \ref{cond:UGW} holds.
For each $k \in \N_0$ and each bounded measurable function $h \colon (\PolishX^{k+1})^2 \times \SQ(\PolishX^{k+1})^2 \to \Rmb$, it holds a.s.\ on the event $\{N_{\myroot}(\tree) \neq \emptyset\}$ that 
	\begin{align*}
		\E & \left[\left. \frac{1}{|N_{\myroot}(\tree)|} \sum_{u \in N_{\myroot}(\tree)} h(X_{\myroot}[k],X_u[k],\lan X_{N_{\myroot}(\tree)}[k] \ran,\lan X_{N_u(\tree)}[k] \ran) \, \right| \, X_{\myroot}[k], \, \lan X_{N_{\myroot}(\tree)}[k]\ran\right] \\
		& = \E\left[\left. h(X_{\myroot}[k],X_1[k],\lan X_{N_{\myroot}(\tree)}[k] \ran,\lan X_{N_1(\tree)}[k] \ran) \, \right| \, X_{\myroot}[k], \, \lan X_{N_{\myroot}(\tree)}[k]\ran\right].
	\end{align*}

