[Dfn 224 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] In the spherical (resp.\ Ising) projection pursuit problem, we say that an algorithm $\cA$ (as in \eqref{eq:algorithms-as-maps}) \textbf{$(\ioeps,\gamma)$-attains} a target measure $\mu\in \cP_2(\bbR)$ if the output $\bx = \cA(\bG,\bg^{\aux})$ satisfies, with probability at least $\gamma$, \emph{both} of the following properties:
    \begin{enumerate}[(i)]
         \item  
         $\bx \in S_N(\iota)$ (resp.\ $\Sigma_N(\iota)$);
         \item 
         $\bbW_2(\mu,\mu_{\bG}(\bx)) \le \ioeps$.
    \end{enumerate}
For $\fq \in [1,2)$, we say that $\cA$ is \textbf{$(\fq,\iotamsr,\iotasol,\gamma)$-confined} to a subset $\cM\subseteq \cP_2(\bbR)$ if the output $\bx$ satisfies, with probability at least $\gamma$, \emph{either} of the following properties:
    \begin{enumerate}[(i)]
        \item  $\bx \notin S_N(\iotasol)$ (resp.\ $\Sigma_N(\iotasol)$);
        \item  $\bbW_\fq(\mu_{\bG}(\bx),\cM) \le \iotamsr$.
    \end{enumerate}

[Lemma lem:secondhalfsumgeneral of arXiv:2412.09145, 'Asymptotic expansions for normal deviations of random walks conditioned to stay positive'] For all $a, b>0$, $a\notin \mathbb{Z}$ and $t \in (0,1)$ there exist numbers $c_{i,\nu}$ such that, uniformly in $z$,
\begin{multline*}
    \sum_{k=2}^{\lfloor n/2\rfloor} 
        \frac{z^m}{(n-k+t)^{b}(k-t)^a}
        e^{-\frac{z^2}{2 (n-k+t)}}
\\
=
    \frac{z^m}{n^b}
    e^{-\frac{z^2}{2 n}}
    \sum_{\nu=0}^{\lfloor a \rfloor-1}
        \frac{z^{2\nu}}{n^{\nu}}
        \sum_{i=\nu}^{\lfloor a \rfloor-1}
            \frac{c_{i,\nu}g_{a-i}(t)}{n^{i}}
+
    O\left(\frac{1}{n^{a+b-m/2-1}}\right),
\end{multline*}
where
\begin{align*}
    g_{\lambda}(t) 
=
    \sum_{k=2}^{\infty}
        \frac{1}{(k-t)^{\lambda}}.
\end{align*}

