[Thm master of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] {DRC-1}}]
    There exists a coupling $\mathbb P_{\delta}$ of the following objects
    \begin{enumerate}[label=(\roman*)]
        \item A double random current $\mathbf{n}_\delta$ with wired boundary conditions on $D_\delta$ and a double random current $\mathbf{n}_\delta^\dagger$ with free boundary conditions on $D_\delta^\dagger$
        \item A height function $h_\delta$ taking integer values on $D_\delta$ and half-integer values on $D_\delta^\dagger$
        \item A XOR-Ising model $\tau_\delta$ with $+$ boundary conditions on $D_\delta$ and a XOR-Ising model $\tau_\delta^\dagger$ with free boundary conditions on $D_\delta^\dagger$
    \end{enumerate}
    in such a way that
    \begin{enumerate}[label=(\arabic*)]
        \item There exists no pair $(e, e^\dagger)$ of dual edges such that $\mathbf{n}_\delta(e)>0$ and $\mathbf{n}_\delta^\dagger(e^\dagger)>0$.
        \item The set
        \begin{equation}
            \mathbf{n}_\delta^\mathrm{odd} :=\{e\in E_\delta: \mathbf{n}_\delta(e)\ \text{is odd}\}
        \end{equation}
        is equal to the collection of interfaces of $\tau_\delta^\dagger$. In particular, the spin $\tau_\delta^\dagger(u)$ is given by a product of  $-c_\delta$ over the inner boundaries surrounding $u$.
        The same holds for the dual models.
        \item The spins are given by
        \begin{align}
            &\tau_\delta(v) = \cos(\pi h_\delta(v)), \\ 
            &\tau_\delta^\dagger(u) = \sin(\pi h_\delta(u)).
        \end{align}
        In particular, 
        \begin{equation}
            h_\delta(u)-h_\delta(v) = \frac{1}{2}\ \tau_\delta(v)\tau_\delta^\dagger(u).
        \end{equation}
        \item The conditional law of $\tau_\delta$ given $\mathbf{n}_\delta$ is that of i.i.d. symmetric sign assignments $(\xi_k^\delta)_{k\geq1}$ to the clusters of $\mathbf{n}_\delta$. The same holds for the dual models.
        \item [ dimer-boson, nesting-field] The bosonisation identity holds, i.e.
        \begin{equation}
            \mathbb E_\delta\Big[\prod_{i=1}^n\cos(\pi h_\delta(v_i))\prod_{j=1}^k\sin(\pi h_\delta(u_j))\Big] = \mathbb E_{\delta, \beta}^+\Big[ \prod_{i=1}^n\sigma_\delta(v_i)\prod_{j=1}^k\mu_\delta(u_j)\Big]^2
        \end{equation}
        for any primal vertices $v_1, \ldots, v_n\in D_\delta$ and any dual vertices $u_1, \ldots, u_k\in D_\delta^\dagger$. Here, the so-called disorder operators are such that
        \begin{align}
            \mathbb E_{\delta, \beta}^+\Big[\prod_{j=1}^k \mu_\delta(u_j)\Big] := \mathbb E_{\delta, \beta}^+\Big[\exp\big\{-2\beta\sum_{xx'\in E_\delta^\gamma}\sigma_\delta(x)\sigma_\delta(x')\big\}\Big] = \mathbb E_{\delta, \beta^\dagger}^\varnothing\Big[\prod_{j=1}^k\sigma_\delta^\dagger(u_j)\Big],
        \end{align}
        where $\gamma$ is any\footnote{The second equality is the well-known Kramers--Wannier duality of the Ising model. In particular, the expression on the left-hand side of (equation eq:disorder of the paper) does not depend on the choice of the disorder line $\gamma$, but only on the choice of dual vertices $u_1, \ldots, u_k$. The expectation on the right-hand side of (equation eq:bosonisation of the paper) does depend on the homology class of $\gamma$ in $D_\delta\setminus\{v_1, \ldots, v_n\}$, but only up to a sign that is cancelled by the square.} collection of dual edges such that $\{u_1, \ldots, u_k\}$ is the set of dual vertices incident to an odd number of edges in $\gamma$,  and $E_\delta^\gamma$ is the subset of edges of $E_\delta$ crossed by $\gamma$.
        \item When exploring a cluster of $\mathbf{n}_\delta$ from the outside, the law of $\mathbf{n}_\delta$ inside each inner boundary is that of a DRC with free boundary conditions. The same holds for $\mathbf{n}_\delta^\dagger$.
        \item When exploring a cluster of $\mathbf{n}_\delta$ from the outside, the law of $\mathbf{n}_\delta^\dagger$ inside each inner boundary is that of a DRC with wired boundary conditions (and thus the inner boundary itself is identified into (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2506.22040, '\vspace{-3em} Khinchin inequalities for uniforms on spheres with a deficit'] Let $d \geq 2$ be a fixed dimension, let $\xi_1, \xi_2, \dots$ be independent random vectors uniform on the unit Euclidean sphere $S^{d-1}$ in $\R^d$ and let $Z$ be a Gaussian random vector in $\R^d$ with mean $0$ and covariance $\frac{1}{d}I_d$. Let $p \geq 2$. For every $n \geq 1$, every real scalars $a_1, \dots, a_n$ with $\sum_{j=1}^n a_j^2 = 1$, we have
\begin{equation}
\E\left|\sum_{j=1}^n a_j\xi_j\right|^p \leq \E|Z|^p - c_{p,d}\sum_{j=1}^n a_j^4,
\end{equation}
where
\[ 
c_{p,d} = \frac{(p+d-2)(p+d-4)}{24d^2(d+2)}\cdot \begin{cases} 3p(p-2), & 2 \leq p \leq 4, \\ 1, & p > 4. \end{cases}
 \] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 58 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $\eta>0$, $k\geq 0$, $q\in\{1,\dots,k-1\}$, $j\geq 1$, $l\geq 0$, with $j+2l\leq 2(k-q)+1$, 
and $b\geq v\vee(2\lambda)$.
Then
\begin{multline*}
\E\Big[\big\Vert
\ell_{0,b}^{2(k-q)+1-j-2l}
(\log \CR(z,D))^{q}
V_{A_{0,b}}^{l}
\,:\Phi_{D\setminus A_{0,b}}^{j} :
\ind_{\{z\in A_{0,b}\text{~or~}\ell_{0,b}(z)=b\}}
\big\Vert_{H^{-\eta}(\C)}^{2}
\Big]
=
\\
j!
b^{4(k-q)+2-2j- 4l}
\int_{D^{2}}
(\log \CR(z,D))^{q}
(\log \CR(w,D))^{q}
\LK_{\eta}(\vert w-z\vert)
\\
\times
\E
\big[
V_{A_{0,b}}(z)^{l}V_{A_{0,b}}(w)^{l}
G_{D\setminus A_{0,b}}(z,w)^{j}
\ind_{\{\ell_{0,b}(z)=\ell_{0,b}(w)=b\}}
\big]
\,d^{2}z\,d^{2}w
.
\end{multline*}
If $f_{0}$ is a deterministic cutoff function as in \eqref{Eq A E tilde N}, then
\begin{multline*}
\E\Big[\big\Vert
f_{0}
\ell_{0,b}^{2(k-q)+1-j-2l}
(\log \CR(z,D))^{q}
V_{A_{0,b}}^{l}
\,:\Phi_{D\setminus A_{0,b}}^{j} :
\ind_{\{z\in A_{0,b}\text{~or~}\ell_{0,b}(z)=b\}}
\big\Vert_{H^{-\eta}(\C)}^{2}
\Big]
=
\\
j!
b^{4(k-q)+2-2j- 4l}
\int_{D^{2}}
f_{0}(z)f_{0}(w)
(\log \CR(z,D))^{q}
(\log \CR(w,D))^{q}
\LK_{\eta}(\vert w-z\vert)
\\
\times
\E
\big[
V_{A_{0,b}}(z)^{l}V_{A_{0,b}}(w)^{l}
G_{D\setminus A_{0,b}}(z,w)^{j}
\ind_{\{\ell_{0,b}(z)=\ell_{0,b}(w)=b\}}
\big]
\,d^{2}z\,d^{2}w
.
\end{multline*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:small-n of arXiv:2609.00777, 'Universal murmuration and Hecke augmentation'] For $0\leq\sigma,\tau\leq1$,
\begin{equation*}
\begin{aligned}
\sum_{\substack{n\leq Y^\sigma\\d\leq Y^\tau}}
\frac{\mathcal S_{d,n,r}}{nd}
&=
\frac{Y}{\zeta(2)}BC(r)
+O\left(\frac{Y}{P^2}\right)\\
&\quad+
O_\varepsilon\left(
(QXY)^\varepsilon
\left(
\sqrt X\,Y^{\sigma/2}
+Y^{\tau+3\sigma/2}
+Y^{1-2\tau}
+Y^{1-\sigma/5}
\right)
\right).
\end{aligned}
\end{equation*}

