[Coro of arXiv:2601.20502, 'Optimal matching under size priority'] Let $(\mathbb{T},o)$ be a UBGW with Poisson $\mathcal{P}(c)$ reproduction law with $c<e$.
    Let $(G_n,o_n)$ be a sequence of random weighted graphs converging locally in total variation to $(\mathbb{T},o)$. Define $\mathcal{M}_{\max}(G_n)$ to be the set of maximal matchings on $(G_n)$
    We then have the following convergence:
        \begin{equation}
            \begin{aligned}
                \frac{1}{|E(G_n)|} \sum_{e \in E(G_n)} \mathbbm{1}_{\forall \mathbb{M} \in \mathcal{M}_{\max}(G_n), e \in \mathbb{M}} &\overset{\mathbb{P}}{\longrightarrow} \gamma^2, \\
                 \frac{1}{|E(G_n)|} \sum_{e \in E(G_n)} \mathbbm{1}_{\forall \mathbb{M} \in \mathcal{M}_{\max}(G_n), e \notin \mathbb{M}} &\overset{\mathbb{P}}{\longrightarrow} (1-\gamma)^2.
            \end{aligned}
        \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Tm main_tm_new of arXiv:2607.08869, 'Inequalities for convex functions of random points inside and on the boundary of convex bo'] Under the same assumptions on $K$ as in Theorem~(main_tm of the paper),
    \begin{align}
        I \preceq_{cx} B,
    \end{align}
    i.e., $\mathbb E \varphi(I) \leqslant \mathbb E \varphi(B)$ for every convex $\varphi \colon \mathbb{R}^d \to \mathbb{R}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:dissipation of arXiv:2606.28575, 'Global smooth solutions by high mode Lie-Transport noise for Logarithmically Hyperdissipat'] Let $M\ge 1$ and $r_0, \gamma$ satisfying $-\frac{1}{2} < r_0 < \gamma < 0$. There exists $\nu_0>0$ depending only on $M$ such that for all $\nu>\nu_0$ and all $\|\omega_0\|_{H^{\gamma}_g}\le M $, there exists a unique global solution $\omega^{{\operatorname{det}}} $ of 
    \begin{equation}
\begin{cases}
    \partial_t\omega^{{\operatorname{det}}} + \mathcal{L}_u \omega^{{\operatorname{det}}} + A\omega^{{\operatorname{det}}} - \nu\Delta \omega^{{\operatorname{det}}}   =0 \\
    u= K[ \omega^{{\operatorname{det}}}].
    \end{cases}
\end{equation}
Moreover, it holds, for some $\eta_0 >0$  
    \begin{align}
    \sup_{t>0}\|\omega^{\operatorname{det}}_t\|_{H_g^\gamma}^2 + \|\omega^{\operatorname{det}} \|_{L^2(0, +\infty; H^{\gamma+1}_g)}^2 &\lesssim \|\omega_0\|_{H_g^\gamma}^2 \\
        \|\omega^{\operatorname{det}}_t\|_{H^{r_0}_g} &\lesssim  e^{-\eta_0 t} \|\omega_0\|_{H^\gamma_g} .
    \end{align}

