[Proposition prop:mgfref of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Let $V_{0,\varnothing} \in \cV$,  $\vec\textbf{a} \in \operatorname{HB}_{\epsilon_p}$,  $g^{(\emptyset)} >0$ and $g^{(\km)} =0$ for $\km \in \ko_{4,\nabla}$.
Then for $f \in (\R^n )^{\Lambda}$ and $\textbf{a}^{(\emptyset)} >0$,
\begin{align}
	\frac{\E_{C^{(\vec{\textbf{a}})}} [ e^{-V_{0,\varnothing} (\Lambda, \varphi) + (f,\varphi) }  ] } {\E_{C^{(\vec{\textbf{a}})}} [ e^{-V_{0,\varnothing} (\Lambda, \varphi) }  ]}
		= e^{\frac{1}{2} (f,  C^{(\vec{\textbf{a}})} f)}  
		\frac{\int_{\R^n} Z_{N,\varnothing} ( y \one +  C^{(\vec{\textbf{a}})} f ) e^{-\frac{1}{2} t_N^{-1} L^{dN} |y|^2  } {\rm d} y }{\int_{\R^n} Z_{N,\varnothing}  ( y \one ) e^{-\frac{1}{2} t_N^{-1} L^{dN} |y|^2  } {\rm d} y } \\
		= e^{\frac{1}{2} (f,  w_N  f)}  
		\frac{\int_{\R^n} Z_{N,\varnothing} ( y \one +  w_N f ) e^{(f, y \one)} e^{-\frac{1}{2} t_N^{-1} L^{dN} |y|^2  } {\rm d} y }{\int_{\R^n} Z_{N,\varnothing}  ( y \one ) e^{-\frac{1}{2} t_N^{-1} L^{dN} |y|^2  } {\rm d} y }
\end{align}
where $\one$ is the unit-valued function on $\Lambda$.
If $\textbf{a}^{(\emptyset)} = 0$,  then (equation eq:mgfref2 of the paper) holds with $t_N^{-1} = 0$.

