[Prop 17 of arXiv:2505.20799, 'A note on the improved sparse Hanson-Wright inequalities'] Let $\delta\in\mathbb{R}^d$ and $B\in \mathbb{R}^{d\times m}$  as in Theorem \ref{thm:RIP}. For a fixed vector $x\in\mathbb{R}^{d}$, denote $A=xx^\T$. For any $r\ge 1$, we have
\begin{align}

    \big(\mathbb{E}\Vert  B^\T\cdot \mathrm{Diag}(\delta)\cdot A\cdot \mathrm{Diag}(\delta)\cdot B\Vert^{r}_{F} \big)^{1/r}\lesssim \Vert B\Vert_{l_2\to l_2}^2\Vert x\Vert_{2}^{2}.
\end{align}

[Lemma 22 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $\nu$ be a Borel measure on $\R^n$ and let $\mu$ be a Borel measure on
$\R^d$ which is homogeneous of degree $\alpha>0$. Suppose there
exists a continuous cost function $c:\R^n\times\R^d\to\R$ and a collection
$\mathcal C\subset 2^{\R^n}$ of bounded, measurable sets such that
\begin{enumerate}
    \item $c$ is positively $1$-homogeneous in the second variable;
    \item $-c$ is a non-negative mapping on
    $\mathcal C\times\mathcal B(\R^d)$;
    \item any $K\in\mathcal C$ failing the non-degeneracy condition \eqref{eq:non_degen} has $\nu$-measure zero;
    \item there exists $\lambda\in(0,1)$ and a set $B\in\mathcal C$ such that,
    for every $K\in\mathcal C$,
    \begin{equation}

        \nu(K)^\lambda \mu(K^{\circ,c})^{1-\lambda}
        \leq
        \nu(B)^\lambda \mu(B^{\circ,c})^{1-\lambda}
        :=
        C_{\nu,\mu}.
    \end{equation}
\end{enumerate}

Define the function $F(r)=C_{\nu,\mu}\,r^{\alpha(1-\lambda)}$ on $\R_+$. Then, the polish spaces $(\R^n,|\cdot|,\nu)$ and $(\R^d,|\cdot|,\mu)$ satisfy the cost-Santal\'o inequality associated with
$(\lambda,c,F)$ with domain $(\mathcal C,\mathcal B(\R^d))$. In the implied geometric
inequality,
\begin{equation}

    \nu(K)^\lambda \mu(L)^{1-\lambda}
    \leq
    C_{\nu,\mu}\,M(K,L)^{\alpha(1-\lambda)},
\end{equation}
where
\[ K\in\mathcal C, \,\,L\in\mathcal B(\R^d), \qquad \text{and} \quad M(K,L)=\sup_{x\in K,y\in L}-c(x,y),
\]
we have an equality characterization: if $L$ is bounded with $\nu(K)\mu(L)>0$, then there is equality in
\eqref{eq:implied_sant} if and only if, up to removal of null sets, one has $L=M(K,L)K^{\circ,c}$ and $K$ is a set for which equality holds in \eqref{eq:gen_geom_hypo}.

Consequently, for every $f\in\mathcal F(\mathcal C)$ and non-negative
measurable function $g$ satisfying the pointwise bound
\[
    f(x)^\lambda g(y)^{1-\lambda}
    \leq
    \Omega(-c(x,y)), \qquad \forall \, x\in \R^n, \, y\in \R^d, \text{such that } (-c(x,y))>0,
\]
 for a non-increasing function $\Omega:\R_+\to\R_+$, one has the functional inequality
\begin{equation}

\begin{split}
    \left(\int_{\R^n} f(x)\,d\nu(x)\right)^\lambda
    \left(\int_{\R^d} g(y)\,d\mu(y)\right)^{1-\lambda}
    &\leq
    C_{\nu,\mu}\,\alpha(1-\lambda)
    \int_0^\infty
    \Omega(r)r^{\alpha(1-\lambda)-1}\,dr
    \\
    &=\frac{C_{\nu,\mu}}{\mu(B_2^d)}
    \int_{\R^d}
    \Omega\left(|z|^{\frac{1}{1-\lambda}}\right)
    d\mu(z).
\end{split}
\end{equation}

[Proposition 6 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] The process $(J_n,S_n)_{n\geq0}$ is a Markov chain on $\X\times\N^d$ with transition kernel

\begin{equation*}
\Pp\left(J_{n+1}\in A,\ S_{n+1}=s+k\mid J_n=x,S_n=s\right)=q_k(x,A).
\end{equation*}

The process $J=(J_n)_{n\geq0}$ is a Markov chain on $\X$ with transition kernel $P$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 4 of arXiv:2609.01142, 'Lagrangian Foliations on compact K\"ahler manifolds'] We have 
\begin{itemize}
\item[i)] $c_1(M)=0\in H^2(\M,\mathbb R)$;
\item[ii)] $\ric(\cV,\cH)=0$;
\item[iii)] if $U,V\in \Gamma(\cV)$ 
we have \begin{equation}
\Ric(U,V)
=
\sum_i g((\bar\nabla_{X_i}T)_UV,X_i)
-
g(T_UV,N);\end{equation}
\item[iv)] we have $$\operatorname{scal} = 2\operatorname{div}N.$$ 
\end{itemize}

[Lemma lem:Gmu1 of arXiv:2605.15545, 'Crossover from subcritical to critical decay: \\ random walk, self-avoiding walk, percolat'] Let $d \ge 15$.
There is a constant such that
\begin{equation}
\bignorm{ \abs x \tau_p ^{(\mu)}(x) }_2 \lesssim 1
\end{equation}
uniformly in $p \in [p_c - \delta, p_c)$ and in $\mu \in \overline \Omega_p$.

