body:
[Definition of arXiv:2411.16103, 'Non-commutative Stein's Method: Applications to Free Probability and Sums of Non-commutati'] Let $a_1,\dots, a_n\in\mathcal{A}$ be given. The free cumulants $\{\kappa_{\pi}[a_1,\dots, a_n]\ ;\pi\in\mathcal{P}\}$	are defined as 
\begin{align*}
\kappa_{\pi}[a_1,\dots, a_n]
  &:=\sum_{\substack{\sigma\in NC(n)\\\sigma\leq \pi}}\tau_{\sigma}[a_1,\dots, a_{n}]\mu(\sigma,\pi).
\end{align*}

[Defi 3 (Green's measures and Laplace transforms) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] For $z_0=(a_0,b_0) \in \R^2$, we define the Green's measure on the plane $\R^2$ by
\begin{equation}
G(z_0,S) = \E_{z_0}\left[\int_0^{+\infty}\fc_{S}(Z_t)\,dt\right] = \iint_S g^{z_0}(a,b)\,da \,db, \quad \forall S \in \mathcal{B}(\R^2)
\end{equation}
where its density $g^{z_0}$ is called the Green's function and is equal to
\begin{equation}
g^{z_0}(a,b) = \int_0^{+\infty} p_t^{z_0}(a,b)\,dt, \quad \forall (a,b)\in\mathbb{R}^2.
\end{equation}

For $x, y, z \in \R$, we also define the Laplace transforms of $G(z_0,\cdot)$ restricted to the half-planes $\R \times (0,+\infty)$ and $\R \times (-\infty,0)$ by
$$
\phi_+^{z_0}(x,y) = \E_{z_0}\left[\int_0^{+\infty} e^{xA_t + yB_t} \fc_{B_t > 0}\,dt\right]
=\int_{\mathbb{R}}\int_0^\infty g^{z_0}(a,b)e^{xa+yb} 
\,da \,db, 
$$
$$
\phi_-^{z_0}(x,z) = \E_{z_0}\left[\int_0^{+\infty} e^{xA_t + zB_t} \fc_{B_t < 0}\,dt\right]
=\int_{\mathbb{R}}\int_{-\infty}^0 g^{z_0}(a,b)e^{xa+zb} 
\,da \,db.
$$
Finally, we define the Green's measure on the axis $\R \times \{0\}$  by
\begin{equation}
H(z_0, S) = \E_{z_0}\left[\int_0^{+\infty} \fc_S(A_t)\,dL^0_t(B)\right], \quad \forall S \in \mathcal{B}(\R)
\end{equation}
and its Laplace transform $\phi^{z_0}$ as
\begin{equation}
\phi^{z_0}(x) = \E_{z_0}\left[\int_0^{+\infty} e^{xA_t}\,dL^0_t(B)\right].
\end{equation}

[Theorem thm2 of arXiv:2411.03942, 'Asymptotic expansions relating to the distribution of the product of correlated normal ran'] Let $\mu_X,\mu_Y\in\mathbb{R}$, $\sigma_X,\sigma_Y>0$, $-1<\rho<1$ and $n\geq1$. 

\vspace{2mm}

\noindent 1. Suppose that $r_X+r_Y\not=0$. Then, as $x\rightarrow\infty$,
\begin{align}\bar{F}(x)&\sim\frac{(1+\rho)C_n}{2\sqrt{2\pi }}\bigg(\frac{1+\rho}{|r_X+r_Y|\sqrt{n}}\bigg)^{(n-1)/2}\exp\bigg(\frac{n}{8}\bigg(\frac{1+\rho}{1-\rho}\bigg)(r_X-r_Y)^2\bigg)\nonumber \\
&\quad\times\bigg(\frac{x}{s}\bigg)^{(n-3)/4}\exp\bigg(\frac{|r_X+r_Y|}{1+\rho}\sqrt{\frac{nx}{s}}-\frac{x}{s(1+\rho)}\bigg)\sum_{p=0}^\infty \gamma_p(r_X,r_Y,\rho,n)\frac{s^{p/2}}{x^{p/2}}, 
\end{align}
where $\gamma_0(r_X,r_Y,\rho,n)=1$ and, for $p\geq1$,
\begin{align*}
\gamma_p(r_X,r_Y,\rho,n)&=\sum_{\substack{i,j,k,\ell\geq0 \\ i+2j+k+\ell=p}}(-1)^{j+i} c_\ell(r_X,r_Y,\rho,n) \binom{(n-1)/2-\ell}{k}\binom{(n-3)/2-\ell-k-2j}{i}\\
&\quad\times ((\ell+k)/2-(n-3)/4)_j(1+\rho)^j\bigg(\frac{|r_X+r_Y|\sqrt{n}}{2}\bigg)^{k+i},     
\end{align*}
with $c_\ell(r_X,r_Y,\rho,n)$, $\ell\geq0$, defined as in part 1 of Theorem (thm1 of the paper).

\vspace{2mm}

\noindent 2. Suppose that $r_X+r_Y=0$. Then, as $x\rightarrow\infty$,
\begin{align}\bar{F}(x)&\sim \frac{1+\rho}{2^{n/2}\Gamma(n/2)}\bigg(\frac{x}{s}\bigg)^{n/2-1}\exp\bigg(-\frac{nr_X^2}{2}-\frac{x}{s(1+\rho)}\bigg)\sum_{k=0}^\infty \delta_k(r_X,\rho,n)\frac{s^k}{x^k}, 
\end{align}  
where $\delta_0(r_X,\rho,n)=1$ and, for $k\geq1$,
\begin{align*}
\delta_k(r_X,\rho,n)=\sum_{j=0}^k (-1)^{k-j}d_j(r_X,\rho,n)  (k+1-n/2)_{k-j}(1+\rho)^{k-j},  
\end{align*}
with $d_j(r_X,\rho,n)$, $j\geq0$, defined as in part 2 of Theorem (thm1 of the paper).

\vspace{2mm}

\noindent 3. Suppose that $r_X-r_Y\not=0$. Then, as $x\rightarrow-\infty$,
\begin{align}F(x)&\sim\frac{(1-\rho)C_n}{2\sqrt{2\pi }}\bigg(\frac{1-\rho}{|r_X-r_Y|\sqrt{n}}\bigg)^{(n-1)/2}\exp\bigg(\frac{n}{8}\bigg(\frac{1-\rho}{1+\rho}\bigg)(r_X+r_Y)^2\bigg)\nonumber \\
&\quad\times\bigg(\frac{|x|}{s}\bigg)^{(n-3)/4}\exp\bigg(\frac{|r_X-r_Y|}{1-\rho}\sqrt{\frac{n|x|}{s}}+\frac{x}{s(1-\rho)}\bigg)\sum_{p=0}^\infty \gamma_p(r_X,-r_Y,-\rho,n)\frac{s^{p/2}}{x^{p/2}}. 
\end{align}
\noindent 4. Suppose that $r_X-r_Y=0$. Then, as $x\rightarrow-\infty$,
\begin{align}F(x)&\sim \frac{1-\rho}{2^{n/2}\Gamma(n/2)}\bigg(\frac{|x|}{s}\bigg)^{n/2-1}\exp\bigg(-\frac{nr_X^2}{2}+\frac{x}{s(1-\rho)}\bigg)\sum_{k=0}^\infty \delta_k(r_X,-\rho,n)\frac{s^k}{|x|^k}. 
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq: upper bound for length of beta of arXiv:2411.16398, 'Large Deviations of Cover Time of Tori in Dimensions $d\geq 3$'] \begin{enumerate}[label=(\roman*)]
    \item For two vertices $\boldsymbol{x} ,\boldsymbol{y} \in \mathbb{T}_N$, we have 
    \begin{equation}

        L(\beta(\boldsymbol{x},\boldsymbol{y})) \leq 2d \cdot (d_{\infty}(\boldsymbol{x},\boldsymbol{y})+2).
    \end{equation}
    \item For each $\mathsf{C} \subset \mathbb{T}_N$ and $\boldsymbol{x} \in \mathsf{C}$, we have
    \begin{equation}

        L(\beta^{\mathrm{Tree}}(\mathsf{C},\boldsymbol{x})) \leq 6dl_N(|\mathsf{C}|-1).
    \end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 21 of arXiv:2608.27433, 'Scalar curvature on K\"ahler blow-ups and systolic inequalities'] Assume \(k=2\) and \(-1<\delta<0\). Then, for every \(\phi\in C^{4,\alpha}_\delta(\widetilde X)\),
\begin{equation}
  \norm{
    \mathscr D_{\omega_\eps,
      S(\omega_\eps)-\pi^*S(\omega)-\eps^2h_S}(\phi)
  }_{C^{0,\alpha}_{\delta-4}}
  \le
  C\eps^{\delta-2}r_\eps^{4-\delta}
  \norm{\phi}_{C^{4,\alpha}_\delta}.
\end{equation}

