[Lem 20 of arXiv:2604.25725, 'What is The Probability That A Random Graph With A Given Degree Sequence is Connected?'] For any $m$ large enough, $0<\gamma<1$, $0<\epsilon<10^{-10}$, $n_1 \le m^{1-\gamma}$, $n_2<\eps m$, $0<C \le m^{\gamma /20}$, $1\leq i$, $0\leq r\le C(\log m)^2$, the following holds: if $2|E(H_{i-1})|+X_{i-1} \le \epsilon m$ then  
\begin{equation*}
    \Cprob{\sum_{t=i}^{i+r-1} J_t\I{X_t\leq X_{t-1}} \ge \frac{C}{3} \text{ and }\forall i\leq t\leq i+r-1: X_{t-1}\le 2C}{H_{i-1}} <m^{-\gamma C/4}.
\end{equation*}

[Definition 44 of arXiv:2608.29157, 'Dilator-based analysis of $\KP$'] Let us define the deduction rules of $\RS_H$ as follows:
    \begin{center}
    \vspace{1em}
    \begin{mathprooftree}
        \def\fCenter#1#2{\sststile{#1}{#2}}
        \AxiomC{}
        \RightLabel{$(\mathrm{Ax}) \quad (x\in y\in u)$}
        \UnaryInfC{$H[\ttX]\fCenter{\rho}{\alpha} \Gamma,\ x\in y$}
    \end{mathprooftree}
    \hspace{3em}
    \begin{mathprooftree}
        \def\fCenter#1#2{\sststile{#1}{#2}}
        \AxiomC{}
        \RightLabel{$(\mathrm{Ax}) \quad (x\notin y\in u,\ y\in u)$}
        \UnaryInfC{$H[\ttX]\fCenter{\rho}{\alpha} \Gamma,\ x\notin y$}
    \end{mathprooftree}



    \vspace{1em}
    \begin{mathprooftree}
        \def\fCenter#1#2{\sststile{#1}{#2}}
        \AxiomC{$H[\ttX]\fCenter{\rho}{\alpha_0} \Gamma,\ A$}
        \AxiomC{$H[\ttX]\fCenter{\rho}{\alpha_1}  \Gamma,\ B$}
        \RightLabel{$(\land)$ \hspace{2em} ($\alpha_0,\alpha_1<\alpha$)\footnotemark}
        \BinaryInfC{$H[\ttX]\fCenter{\rho}{\alpha} \Gamma,\ A\land B$}
    \end{mathprooftree}
    \footnotetext{We do the comparison over $H(\ttX)$.}

    \vspace{1em}
    \begin{mathprooftree}
        \def\fCenter#1#2{\sststile{#1}{#2}}
        \AxiomC{$H[\ttX]\fCenter{\rho}{\alpha_0} \Gamma,\ A$}
        \RightLabel{$(\lor)$}
        \UnaryInfC{$H[\ttX]\fCenter{\rho}{\alpha} \Gamma,\ A\lor B$}
    \end{mathprooftree}
    \hspace{3em}
    \begin{mathprooftree}
        \def\fCenter#1#2{\sststile{#1}{#2}}
        \AxiomC{$H[\ttX]\fCenter{\rho}{\alpha_0} \Gamma,\ B$}
        \RightLabel{$(\lor)$ \hspace{2em} ($\alpha_0<\alpha$)}
        \UnaryInfC{$H[\ttX]\fCenter{\rho}{\alpha} \Gamma,\ A\lor B$}
    \end{mathprooftree}

    \vspace{1em}
    \begin{mathprooftree}
        \def\fCenter#1#2{\sststile{#1}{#2}}
        \AxiomC{$H[\ttX]\fCenter{\rho}{\alpha_0} \Gamma,\ s\dotin t\land r=s$}
        \RightLabel{$(\in)$ \hspace{2em} ($\alpha_0<\alpha$, $|s|<|t|$, $\rk^{\bfL(u)}_{H(\ttX)}(s)<\alpha$, $r\in t$ not basic.)}
        \UnaryInfC{$H[\ttX]\fCenter{\rho}{\alpha} \Gamma,\ r\in t$}
    \end{mathprooftree}

    \vspace{1em}
    \begin{mathprooftree}
        \def\fCenter#1#2{\sststile{#1}{#2}}
