body:
[Thm 2 of arXiv:2608.21255, 'Laws of the iterated logarithm for random Dirichlet series with general weights'] a) Assume that $\eta$ has a normal distribution with mean $0$ and variance $\sigma^2\in (0,\infty)$ and set $s_n=2^{-1}\eee^{-n^2}$ for $n\in\mn$. Then there exists a sequence $(a_k)$ satisfying \eqref{eq:standing} for which 
    \begin{equation}
        \limsup_{n\to\infty}\frac{X(s_n)}{(2v(s_n)\log\log v(s_n))^{1/2}}=\frac{1}{2^{1/2}}\quad\text{{\rm a.s.}}
    \end{equation}
    and
    \begin{equation}
        \liminf_{n\to\infty}\frac{X(s_n)}{(2v(s_n)\log\log v(s_n))^{1/2}}=-\frac{1}{2^{1/2}}\quad\text{{\rm a.s.}}
    \end{equation}
b) Assume that $\mmp\{\eta=\pm \sigma\}=1/2$. Then, with the same sequence $(a_k)$ and the same $s_n$ as in part (a), 
    \begin{equation}
        \limsup_{n\to\infty}\frac{X(s_n)}{(v(s_n))^{1/2}}=1\quad\text{{\rm a.s.}}
    \end{equation}
    and
    \begin{equation}
        \liminf_{n\to\infty}\frac{X(s_n)}{(v(s_n))^{1/2}}=-1\quad\text{{\rm a.s.}}
    \end{equation}
c) Assume that $\eta=\xi-\sigma$, where $\xi$ has an exponential distribution of mean $\sigma$. Then, with the same sequence $(a_k)$ and the same $s_n$ as in part (a), 
\begin{equation}
\limsup_{n\to\infty}\frac{X(s_n)}{(v(s_n))^{1/2}\log\log v(s_n)}=\frac{1}{2}\quad\text{{\rm a.s.}}
\end{equation}
and
\begin{equation}
\liminf_{n\to\infty}\frac{X(s_n)}{(v(s_n))^{1/2}}=-1\quad\text{{\rm a.s.}}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 16 of arXiv:2604.23461, 'Scaling limit of Sinkhorn-rescaled Random Matrices \\ via Stability of Static Schrödinger '] Fix $\phi \in L^{\infty}_{>0}(\mu_0 \otimes \mu_1)$. Also, let $(\xi, \eta) \in L^{\infty}(\mu_0) \times \overline{L}^{\infty}(\mu_1)$. Then $F$ is continuously (Frechet) differentiable at $(\phi, \xi, \eta)$. Furthermore, let $\partial_1$ be the partial derivative in the first coordinate and $\partial_{2}$ be the partial derivative with respect to $F$'s second two coordinates. The derivatives are the linear operators
	\begin{align}

		\partial_1F(\phi, \xi, \eta)\psi = \left( \int_{\Omega_{\c}} \psi(\cdot, y)e^{\xi(\cdot) + \eta(y)}d\mu_1(y), \int_{\Omega_{\r}}\psi(x, \cdot) e^{\xi(x) + \eta(\cdot)}d\mu_0(x) \right). 
	\end{align}
	and for $h = (h_0, h_1) \in L^{\infty}(\mu_0) \times \overline{L}^{\infty}(\mu_1)$, 
	\begin{multline}

		\partial_{2}F(\phi, \xi, \eta)h\\
		= \left(\int_{\Omega_c}\phi(\cdot, y)e^{\xi(\cdot) + \eta(y)}(h_{0}(\cdot) + h_{1}(y))d\mu_1(y), \int_{\Omega_{\r}}\phi(x, \cdot) e^{\xi(x) + \eta(\cdot)}(h_{0}(x) + h_{1}(\cdot))d\mu_0(x) \right).
	\end{multline}
	Furthermore, $\partial_2F(\phi, \xi, \eta)$ is an isomorphism from $L^{\infty}(\mu_0) \times \overline{L}^{\infty}(\mu_1)$ to $\mathcal{E}$.

