body:
[Corollary 132 of arXiv:2601.16377, '2601.16377'] Assume in the setting of Theorem~\ref{Theorem_correlators_expansion} that we have $\theta_{g,g} = 1$ for every $g \in [H]$. Let $h \in [H]$ and set
\begin{equation}

\hat{W}_{1;h}^{[2]}(z) = \Op_{h}\Bigg[\bigg(\frac{1}{s_g^{\circ}}\Big\{\hat{q}^{+,[2]}_{g} + \frac{q_g^+}{2} \big\langle \bth_g^{\otimes 2}\cdot \boldsymbol{\mathcal{F}}_{\bullet,\bullet}(*,*) \big\rangle \Big\}\bigg)_{g = 1}^{H}\,;\,\boldsymbol{0}\bigg],
\end{equation}
where
\begin{equation}

\hat{q}_{h}^{+,[2]}(z) = \frac{q_h^-(z)}{24} \big\langle \bth_h(4\bth_h^2 - 6\bth_h + 3) \cdot \partial_z^2 \mathcal{G}_{\boldsymbol{\mu}}(z)\big\rangle -   \frac{\partial_z^3 U_h(z)}{12} \cdot \phi_h^{+}(z) \cdot e^{\langle \bth_h \cdot \mathcal{G}_{\boldsymbol{\mu}}(z)\rangle}.
\end{equation}
Then, \eqref{eq_x30} and \eqref{eq_x31} can be replaced with
\[
\big|W_{1;h}(z) - \N^{-1}\hat{W}_{1;h}^{[2]}(z)\big| \leq C_1 \N^{-\frac{3}{2} + \varepsilon}, \qquad \big|\hat{W}_{1;h}^{[2]}(z)\big| \leq C_1.
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma L:Second-der-X-W1-W2 of arXiv:2606.23865, 'Uniform-in-time Gaussian fluctuations for multiscale nonlinear stochastic systems via Mall'] Let the process $D_{r_1,r_2}^{W_1 W_2} X_t^\varepsilon$ be the solution of equation (equation E:Second-der-X-W1-W2 of the paper). Then, for any $p \in \mathbb{N}$ and $t \ge r_1 \vee r_2$, there exists a time-independent positive constant $K$ such that
\begin{multline*}
\mathbb{E} \left[\left|D_{r_1,r_2}^{W_1 W_2} X_t^\varepsilon\right|^{2p} \right] \le K \left[\frac{\varepsilon^p}{\eta^p} + \varepsilon^p \eta^p \right] e^{- (2p)\alpha (t-r_1 \vee r_2)} e^{- (2p)\frac{\lambda}{\eta} (r_1 - r_2)}\mathds{1}_{(r_1 \ge r_2)} \\
 + K  \left[ \varepsilon^p \eta^p + {\varepsilon^{2p}} \right] e^{-(2p) \alpha (t - r_1 \wedge r_2)}.
\end{multline*}

