body:
[Proposition eq:finite-N-hard-slice-assumption of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[proposition]{prop:finite-N-dereg}
Fix \(N\), let \(n=N-1\), and let \(V\) be Borel measurable and bounded
below.  For almost every \(O\in\mathcal O_{N,L}\), suppose that \(g_J(O)\)
has a density \(p_O(g)\) on \(\mathbb R^n\) and that
\((h_J(O),A_J(O))\), conditionally on \(g_J(O)=g\), admits a jointly
measurable regular conditional kernel \(K_O(g,\,\mathrm d h\,\,\mathrm d A)\).  Assume
that versions at \(g=0\) have been fixed for which the hard-slice identity
\begin{equation}
 \mathscr C_{N,L}^J(V)
 =\omega_N\int_{\mathcal O_{N,L}}p_O(0)
   \int_{\mathbb R\times\operatorname{Sym}_n}
   e^{-NV(h)}\left\lvert\det A\right\rvert\,
   K_O(0,\,\mathrm d h\,\,\mathrm d A)\nu_N(\,\mathrm d O)
\end{equation}
holds.
For \(0<\eta\le1\) and \(R\ge1\), put
\[
 \Psi_{O,\eta,R}(g)
 =p_O(g)\int_{\mathbb R\times\operatorname{Sym}_n}
 e^{-NV(h)+\operatorname{Tr} f_{\eta,R}(A)}
 K_O(g,\,\mathrm d h\,\,\mathrm d A).
\]
Assume that \(g\mapsto\Psi_{O,\eta,R}(g)\) is bounded and continuous at zero for almost every \(O\), that
\[
 \int_{\mathcal O_{N,L}}\norm{\Psi_{O,\eta,R}}_\infty\nu_N(\,\mathrm d O)<\infty,
\]
and that
\begin{equation}
 \int_{\mathcal O_{N,L}}\int_{\mathbb R\times\operatorname{Sym}_n}
 e^{-NV(h)}(1+\left\lVertA\right\rVert_{\mathrm{op}})^n p_O(0)
 K_O(0,\,\mathrm d h\,\,\mathrm d A)\nu_N(\,\mathrm d O)<\infty.
\end{equation}
Then
\begin{equation}
 \lim_{R\to\infty}\lim_{\eta\downarrow0}\lim_{\varepsilon\downarrow0}
 \mathbb E\mathcal Z_{N,L}^J(V,\varepsilon,f_{\eta,R})
 =\mathscr C_{N,L}^J(V).
\end{equation}

[Proposition keyprop of arXiv:2605.27949, 'Yaglom limits of continuous-state branching processes in Brownian random environment \than'] For any $q > -\frac{\beta\eta}{2}$, the moment generating functions of $\nu_\Phi$ and $\nu_\Psi$ are given by:
\begin{eqnarray}
\int_{-\infty}^\infty \mathrm{e}^{q x} \, \nu_{\Phi} (\mathrm{d} x) = 2^{\frac{q}{\beta} + \eta - 2} \gamma^{- (\frac{q}{\beta} + \eta)} \frac{ \left[\Gamma \left( \frac\eta2 \right)\Gamma \left( \frac{q}{\beta} + \frac\eta2 \right)\right]^2}{\Gamma \left( \frac{q}{\beta} + \eta \right)} \left( \frac{\gamma \lambda^\beta}{2} \right)^{\frac\eta2} U \left( \frac\eta2, 1, \frac{\gamma  \lambda^\beta}{2} \right),
\end{eqnarray}
and
\begin{eqnarray}
\int_{-\infty}^\infty \mathrm{e}^{q x} \, \nu_{\Psi} (\mathrm{d} x) = 2^{\frac{q}{\beta} + \eta - 2} \gamma^{- (\frac{q}{\beta} + \eta)} \frac{ \left[\Gamma \left( \frac\eta2 \right)\Gamma \left( \frac{q}{\beta} + \frac\eta2 \right)\right]^2}{\Gamma \left( \frac{q}{\beta} + \eta \right)}.
\end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

