[Definition def:oriented_cone_horiz of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] Let $X$ be a unit vector in $V_1$. For $p\in\mathbb G$ and $\beta,\rho>0$, the \emph{oriented intrinsic horizontal cone} in the direction of $X$ is defined as
\begin{align*}
\mathcal C_p^+(\beta,\rho;X):=\mathcal{C}^+_p(\beta,\rho; \mathbb{H}_X,\mathbb{K}_X).
\end{align*}

[Thm inductive-step of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] Fix $s$ (in the definition of $\Delta$) sufficiently large. There exist constants $c_1,c_2,c_3$ and $\bar \kappa_0$ such that for all $\beta>\beta_0$, $\bar \kappa \ge\bar\kappa_0$, all $L\ge \beta^2 e^{2\beta}$ and any $n\in [N_0,N]$, 
    \begin{align*}
        \mathcal A(L_n,t_n,\delta_n) \implies \mathcal B(L_n, t_n',\delta_n') \implies \mathcal A(L_{n+1}, t_{n+1},\delta_{n+1})\,,
    \end{align*}
    where 
    \begin{align*}
        \delta_n' &= c_1\big(\delta_n + 
       L_N^{-c_2 \bar \kappa} + L_n^2 e^{ - c_2 \log t_n}\big) \quad &&;\quad &t_n' & = 2t_n \,,\\ 
        \delta_{n+1} &= c_3 \big( \delta_n + L_N^{-c_2 \bar \kappa} \big) \quad & &; \quad& t_{n+1} & = e^{ c_3 \beta \bar \kappa N} t_n\,.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 of arXiv:2605.11279, 'Flocking with Multiple Types: Competition, Fluid Limits and Traveling Waves'] Suppose that Assumptions \ref{assumption3} and \ref{assumption4} hold. 
    \begin{enumerate}[label = (\alph*)]
        \item  There exists $B_0 \in (0,\infty)$ such that, for any $t\geq 0$, $\varepsilon > 0$, and $\eta \in \parens*{0, \dfrac{\varepsilon}{B_0}}$,
        \begin{align*}
            \limsup_{n\to\infty} \prob\parens*{\sup_{s\in[0, t]} \sup_{x\in\real} \mu_n\bigparens{s, (x-\eta, x+\eta) \times \{+,-\}} > \varepsilon} = 0.
        \end{align*}

        \item  In particular, under Assumptions \ref{assumption0}, \ref{assumption2}, \ref{assumption3}, and \ref{assumption4}, for any subsequential weak limit $\mu(\cdot)$ of $\curlbr*{\mu_n(\cdot)\!: n\in\nat}$, almost surely, $\mu^\circ(t)$, defined by $\mu^{\circ}(t,A) := \mu\bigparens{t, A \times \{+,-\}}$ for $A \in \borel(\real),$ has a Lipschitz continuous cumulative distribution function $F^{\circ}(t)$ for any $t \geq 0$ and, almost surely, for any $t>0$ and $\eta>0$,
    \begin{align}

        \sup_{s\in[0,t]} \sup_{x\in\real} \ F^{\circ}(s,x+\eta) - F^{\circ}(s,x-\eta) \leq B_0\eta.
    \end{align}
    Here, we say that $F^\circ(\cdot)$ is the cumulative distribution function associated with the measure $\mu^\circ(\cdot)$.
    \end{enumerate}

