[Theorem 3 (\cite{Lott03}, Theorem 6.6 in \cite{WW09}) of arXiv:2608.30638, 'On compact steady pluriclosed soliton surfaces'] Let $(M,g,f)$ be a compact $n$-dimensional Riemannian manifold with $\Ric_f\geq 0$. Then the following holds:
    \begin{itemize}
        \item Any $\Delta_f$-harmonic $1$-form $\eta$ must be parallel and satisfies $\Ric_f(\eta^{\#},\eta^{\#})=0$ on $M$. In particular, $b_1(M)\leq n$;
        \item There exists a finite cover $\widehat M\to M$, such that we have Riemannian splitting $\widehat M\cong N\times\mathbb T^k$, where $N$ is compact and simply-connected, $T^k$ is a flat torus. Moreover, $\hat f$ is constant along $T^k$-factor and $k\geq b_1(M)$.
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma whatislemma2 of arXiv:2504.15992, 'Repeated singular values of a random symmetric matrix and decoupled singular value estimat'] For any $B>0$, and any $\zeta\in\Gamma_B$, consider the random matrix $A_n\sim\operatorname{Sym}_n(\zeta)$. For any 
    $p>0$ and $\delta_1,\delta_2>0$ define 
    $$\mathcal{E}(p,\delta_1\delta_2):=\left\{\frac{\mu_1(\lambda_1)\mu_1(\lambda_2)}{n}\leq (\delta_1\delta_2)^{-p}\right\}.$$ Then for any given $c'\in(0,1]$, 
    \begin{equation}\begin{aligned}
    \mathbb{E}_{A_n}^{\mathcal{E}(p,\delta_1\delta_2)} &\left[\prod_{i=1}^2 \frac{\|(A_n-\lambda_iI_n)^{-1}\|_*}{\mu_1(\lambda_i)}\sum_{\ell=1}^2\sum_{k=2}^{c'n}e^{-ck}\left(\frac{\sqrt{\mu_1(\lambda_1)\mu_1(\lambda_2)}}{\mu_k(\lambda_\ell)}\right)^{16/9}
        \right]
        \\&\lesssim 1+\mathbb{E}_{A_n}^{\mathcal{E}(p,\delta_1\delta_2)} \left[\left(\frac{\mu_1(\lambda_1)\mu_1(\lambda_2)}{n}\right)^{9/10}
\right]^{80/81}.
        \end{aligned}
    \end{equation}

