\begin{align}
	\mathbf{P}\otimes\mathbb{P}\text{-a.s.,}
	\quad
	1_{M^\theta{}^{\otimes n}F>0}
	\leq
	1_{\mathcal{G}[M^\theta,Y_{\star}^{\theta},\xi]^{\otimes n}F>0}\ .	
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Def 1 of arXiv:2604.24189, 'Malliavin calculus and densities for chaos-driven stochastic differential equations'] An $\R^m$-valued stochastic process $\{F_t\}_{t \geq 0}$ is called a \emph{chaotic process} (over the abstract Wiener space $(\Omega,\mathcal{F},\P,\mathfrak{H})$) if there exists $q \in \N$ such that, for every $t \geq 0$ and every $1 \leq \ell \leq m$, one can find $f_t^\ell \in \mathfrak{H}^{\odot  q}$ satisfying
\begin{equation}
F_t=(I_q(f_t^1),\dots,I_q(f_t^m)).
\end{equation}

[Definition 1 of arXiv:2605.20026, 'Quasihelix properties\\ of selected Volterra Gaussian processes'] A Gaussian process $G=\{G_t,\ t\ge0\}$ is called
\begin{itemize}
    \item[$(i)$] a \emph{$\rho$-quasihelix} if there exist $\rho>0$ and constants $C_1,C_2>0$ such that, for all $t,s\in[0,\infty)$,
    \begin{equation*}
        C_1|t-s|^{\rho}
        \le
        \|G_t-G_s\|_2
        \le
        C_2|t-s|^{\rho};
    \end{equation*}

    \item[$(ii)$] a \emph{local $(\rho,T_1,T_2)$-quasihelix} on the interval $[T_1,T_2]$ if there exist $\rho>0$ and constants $C_1(T_1,T_2),C_2(T_1,T_2)>0$ such that, for all $t,s\in[T_1,T_2]$,
    \begin{equation}
        C_1(T_1,T_2)|t-s|^{\rho}
        \le
        \|G_t-G_s\|_2
        \le
        C_2(T_1,T_2)|t-s|^{\rho};
    \end{equation}

    \item[$(iii)$] a \emph{local $(\rho_1,\rho_2,T_1,T_2)$-generalized quasihelix} on the interval $[T_1,T_2]$ if there exist $\rho_1,\rho_2>0$ and constants $C_1(T_1,T_2),C_2(T_1,T_2)>0$ such that, for all $t,s\in[T_1,T_2]$,
    \begin{equation}
        C_1(T_1,T_2)|t-s|^{\rho_1}
        \le
        \|G_t-G_s\|_2
        \le
        C_2(T_1,T_2)|t-s|^{\rho_2}.
    \end{equation}
\end{itemize}

[Lemma 9 of arXiv:2607.27150, 'Modelling Anomalous Diffusion: The Role of CTRWs and Non-Local Dynamics'] Fix $T>0$, and let $(\mathfrak{B}, \left\| \cdot \right\|)$ be a Banach space. Suppose that $f: [0, +\infty) \mapsto \mathfrak{B}$,  is such that there exists a Bochner integrable function $g: [0, +\infty) \mapsto \mathfrak{B}$ such that
		\begin{align}
			f(t) - f(0) = \int_0^t g(s) \, ds,\quad t \in [0,T].
		\end{align}
		Then $\partial_tf(t)$ and $\phi(\partial_t) f(t)$ exists a.e. in $[0,T]$ and are elements of $L^1([0,T]; \mathfrak{B})$. Moreover, for almost all $t\in [0,T]$, it holds that $\partial_tf(t)=g(t)$ and
		\begin{align}
			\phi(\partial_t)\big(f(t)-f(0)\big) = b \partial_tf(t) + \int_0^t \partial_sf(s) \, \bar{\nu}(t-s) \, ds.

		\end{align}
		If, furthermore, $g\in C([0,T]; \mathfrak{B})$, then $t \mapsto \phi(\partial_t ) f(t) \in C([0,T]; \mathfrak{B})$ and \eqref{der_dentro} holds for all $t\in [0,T]$.

