[Lem 22 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $\gamma >0$, $0 \leq s \leq t \leq T$ and $n \in \mathbb{N}_+$. Then
	\begin{align} 
	&	\mathbb{E}_{\nu_{\rho}} \Bigg[ \Bigg\{ \frac{\Theta(n) K_n}{\sqrt{n}} \int_s^t \dd r \sum_x \sum_{y=x+L_n}^{
	x+n-1}  [  H ( \tfrac{y - r v_n }{n}  ) - H ( \tfrac{x - r v_n }{n}  )  ] a(y-x)   \bar{\xi} _x^{\alpha}( \eta_r^n ) \bar{\xi} _y^{\beta}( \eta_r^n ) \Bigg\}^{2} \Bigg] \nonumber \\
		\leq  & \widehat{C} (t-s)^{2} \Bigg\{ \frac{  \big[ \Theta(n) K_n \big]^{2}  }{ n^{4}  } \mathbbm{1}_{ \{ \gamma \geq 1 \} } + \frac{ [ \Theta(n) K_n  ]^{2} }{n^{2}} \sum_{x=L_n}^{n} x^{- 2 \gamma} \Bigg\}. 
	\end{align}
	Furthermore, if $H \in C_c^2(\mathbb{R})$, the role of $\widehat{C}$ is fulfilled by some constant $C(H)$ satisfying \eqref{Cinvshift}.

