body:
[Prop:shadow3 of arXiv:2608.30973, 'Pseudo-Anosov flow and dynamics on guts'] Let \(l\) be a component of the frontier of \(\Theta(\widetilde{S})\) in \(P_{\varphi}\). Then,
\begin{enumerate}
\item \(l\) is a slice leaf of \(\mathcal{F}^{s/u}\). If it is a slice leaf \(l\) of \(\mathcal{F}^{s}\), then as a sequence of point \(\{p_{n}\}_{n\in \mathbb{N}}\) tends to a point in \(l\), the preimages \((\Theta|_{\widetilde{S}})^{-1}(p_{n})\) in \(\widetilde{S}\) escape in the positive direction.
Similar conclusion holds for unstable boundary slice leaves.
\item \(l\) is periodic, namely, there is an element \(g\in \pi_{1}(M)\) such that \(g\) fixes \(l\) and hence a unique point in \(l\).
\end{enumerate}

[Lem 7 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] Let $\delta\in (0,1/2),\mathsf C>0$, $X\sim \Hyp(n_1,n,m)$ with $\mathbb EX=\frac{n_1m}{n}\leq  \mathsf CN^\delta$. There exists constants $C,c$ depending on $\mathsf C$ such that
            \begin{equation}
                \mathbb P(X\geq 2a)\leq C\exp(-ca) \mbox{ for all } a\geq 3\mathsf CN^q.
            \end{equation}

[Theorem eq:time-reversed-detailed of arXiv:2507.12502, 'Quantitative Edge Eigenvector Universality for Random Regular Graphs: Berry-Esseen Bounds '] Let $p(s,x;t,y)$ denote the transition density of the forward process. If:
\begin{enumerate}
\item The coefficients $b_i$ and $\sigma_{ij}$ are bounded and Lipschitz continuous
\item The diffusion matrix $a_{ij} = \sum_k \sigma_{ik}\sigma_{jk}$ is uniformly elliptic
\item The transition density satisfies $\int p(0,x;t_*,y)\mu_0(dx) = \mu_{t_*}(dy)$
\end{enumerate}
Then the time-reversed process $\tilde{X}_i(s) = X_i(t_* - s)$ satisfies:
\begin{equation}
\mathrm{d} \tilde{X}_i(s) = \tilde{b}_i(s,\tilde{\mathbf{X}}(s))\mathrm{d} s + \sum_{j=1}^K \sigma_{ij}(t_*-s,\tilde{\mathbf{X}}(s))\mathrm{d} \tilde{B}_j(s)
\end{equation}
where $\tilde{B}_j$ are independent Brownian motions and
\begin{equation}
\tilde{b}_i(s,x) = -b_i(t_*-s,x) + \sum_{j=1}^K \sum_{k=1}^K \frac{\partial}{\partial x_k}[a_{ij}(t_*-s,x)] + 2\sum_{j=1}^K a_{ij}(t_*-s,x)\frac{\partial \log \rho_{t_*-s}}{\partial x_j}(x)
\end{equation}
with $\rho_t$ the marginal density at time $t$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 25 of arXiv:2506.09592, 'Extremal process of the local time of simple\\random walk on a regular tree'] Let~$\{T_k\}_{k\ge0}$ be as defined in Corollary~\ref{cor-1.3}. Then for all $n\ge1$,
\begin{equation}

\bigl(\ell_{\tau_\varrho}(x_0),\dots,\ell_{\tau_\varrho}(x_n)\bigr)\text{\rm\ under }P^\zero
\,\,\,\laweq\,\,(T_0,\dots,T_n).
\end{equation}
In addition,
\begin{equation}

\lim_{k \to \infty} \inf_{n \ge k}\,P\biggl(\,\bigcap_{j=k}^n\bigl\{T_j\le\alpha j\log(j)\bigr\}\biggr)=1
\end{equation}
holds true for each~$\alpha>1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 26 of arXiv:2608.30875, 'A Decomposition Theorem for Topological Semi-small Maps'] Let $f : X \longrightarrow Y$ be an almost covering such that $X$ is a closed topological manifold, the fibered set $R$ is closed  stratified space, and $Y$ is a closed topological $n$-pseudomanifold. Assume that the restriction $f|_{f^{-1}(R)} : f^{-1}(R) \longrightarrow R$ is a fiber bundle with fiber $F$, a closed orientable topological manifold, and that $\operatorname{codim}_{X}(f^{-1}(R)) \geq 2$. Furthermore, let the filtration $Y \supset Y_{n_{R}}(=R) \supset Y_{n_{R}-1} \supset \cdots$ be the refined stratification on $Y$ obtained by Proposition~\ref{RefinedStra}, where $n_{R}:= \dim(R)$. Set $S_{k}:= Y_{k} \setminus Y_{k-1}$ and assume the following:
     	\begin{enumerate}
     		\item suppose that the normal bundle over $f^{-1}(S_{k})$ in $X$ exists and is orientable, and that for each point in $R \setminus Y_{n_{R} -1}$, there is a trivializing neighborhood $U$ such that the connecting homomorphism in the Gysin sequence of the normal bundle over $f^{-1}(U)$ vanishes in degree $\operatorname{codim}_{X}(B)-1$.
     		\end{enumerate}
     		Let $R(f\vert_{X \setminus B})_{\ast}\underline{\mathbb{Q}}_{X \setminus B} \simeq \underline{\mathbb{Q}}_{Y \setminus R} \oplus \mathcal{L}$, where $\mathcal{L}$ is the local system on $Y \setminus R$ induced by the covering map $f\vert_{X \setminus B}$. If $\overline{p}(\operatorname{codim}_{Y}(R))+1 = \operatorname{codim}_{X}(B)$ and the refined strata of $Y$ are even-codimensional, then
     	\begin{align}
     	Rf_{\ast}\underline{\mathbb{Q}}_{X}[n] \simeq h_{\ast}(IC^{\overline{p}}_{R}\big(R^{0}( f \vert_{f^{-1}(S_{n_{R}}) })_{\ast}\underline{\mathbb{Q}}_{f^{-1}(S_{n_{R}})}\big) \oplus IC_{Y}^{\overline{p}}(\underline{\mathbb{Q}}_{Y \setminus R} \oplus \mathcal{L} ),
     	\end{align}
     	where $h: R\hookrightarrow Y$ is the canonical closed inclusion.

