body:
[Cor criteria of arXiv:2605.24671, 'Immigration Processes with Binomial Catastrophes and Random Survival Parameters'] Consider the process $C_{\mathrm{ind}}(\lambda,\nu)$ and let $X\sim \nu$. 
\begin{enumerate}
    \item \textit{General criteria.}
    \begin{itemize}
        \item If $\displaystyle\liminf_{n\to\infty} n\lambda\,\mathbb E(X^{n+1})>1$, then $\mathbb P(\mathcal A_{C_{\mathrm{ind}}})>0$.
        \item If $\displaystyle\limsup_{n\to\infty} n\lambda\,\mathbb E(X^{n+1})<1$, then $\mathbb P(\mathcal A_{C_{\mathrm{ind}}})=0$.
    \end{itemize}
    Furthermore, the expected number of catastrophes is infinite if and only if the sum of the moments diverges; that is,
    \begin{equation*}
        \mathbb E(M_{C_{\mathrm{ind}}})=\infty \quad \text{if and only if} \quad \sum_{n\ge0}\mathbb E(X^{n+1})=\infty.
    \end{equation*}
    \item \textit{Density criteria.} Suppose that $\nu$ admits a bounded density $f$ on $[0,1]$ and that the left limit $f(1^-):=\lim_{x\uparrow 1} f(x)$ exists. Then:
    \begin{itemize}
        \item If $f(1^-)>\frac{1}{\lambda}$, then $\mathbb P(\mathcal A_{C_{\mathrm{ind}}})>0$.
        \item If $f(1^-)<\frac{1}{\lambda}$, then $\mathbb P(\mathcal A_{C_{\mathrm{ind}}})=0$.
    \end{itemize}
    If, in addition, $f$ is left-differentiable at $1$ and $f(1^-)=\frac{1}{\lambda}$, then $\mathbb P(\mathcal A_{C_{\mathrm{ind}}})=0$.    
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop Day-convolution of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let ${\mathcal{C}}^\otimes$ be a small symmetric monoidal $T$-$\infty$-category. Then the symmetric monoidal product on $\ul\PSh_T({\mathcal{C}}^\otimes)$ is equivalent to the composite
    \begin{equation}
        \ul\PSh_T({\mathcal{C}})\times\ul\PSh_T({\mathcal{C}})\xrightarrow{\;{-}\mathbin{\widehat{\smash{\times}}}{-}\;}\ul\PSh_T({\mathcal{C}}\times{\mathcal{C}})\xrightarrow{\;\otimes_!\;}\ul\PSh_T({\mathcal{C}}),
    \end{equation}
    where the second functor is left Kan extension along the tensor product of ${\mathcal{C}}$.
    \begin{proof}
        The functors $\textup{pr}_1^*$ and $\textup{pr}_2^*$ are left adjoints, as is $\otimes_!$. Since the product on $\ul\PSh_T({\mathcal{C}}\times{\mathcal{C}})$ is $T$-bilinear as a consequence of Proposition~(prop:spc-T-cart-pres-sym-mon of the paper), we see that $((eq:Day-convolution of the paper))$ is $T$-bilinear. Moreover, in the diagram
        \[
            \begin{tikzcd}
                {\mathcal{C}}\times{\mathcal{C}}\arrow[d,"y_{\mathcal{C}}\times y_{\mathcal{C}}"']\arrow[r,equals] & {\mathcal{C}}\times{\mathcal{C}}\arrow[r,"{-}\otimes{-}"]\arrow[d,"y_{{\mathcal{C}}\times{\mathcal{C}}}"{description}]&{\mathcal{C}}\arrow[d,"y"]\\
                \ul\PSh_T({\mathcal{C}})\times\ul\PSh_T({\mathcal{C}})\arrow[r,"{-}\mathbin{\widehat{\smash{\times}}}{-}"'] & \ul\PSh_T({\mathcal{C}}\times{\mathcal{C}})\arrow[r,"\otimes_!"'] & \ul\PSh_T({\mathcal{C}})
            \end{tikzcd}
        \]
        the left-hand square commutes by [martini2022cocartesianfibrationsstraighteninginternal]*{Lemma~6.2.6} and the right-hand square does so by [martiniwolf2021limits]*{Corollary~3.3.3}. Altogether we see that $((eq:Day-convolution of the paper))$ is a $T$-bilinear functor extending the tensor product on ${\mathcal{C}}$. As the same holds for the tensor product on $\ul\PSh_T({\mathcal{C}}^\otimes)$ by definition, the claim now follows from the universal property of $\ul\PSh_T({\mathcal{C}})$ as the free (non-monoidal) $T$-cocompletion.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

