[Definition 27 (Branching Brownian motion (BBM) and on/off branching Brownian motion (ooBBM)) of arXiv:2604.01852, 'The on/off Brownian snake'] For $b$, $k \geq 0$, \emph{branching Brownian motion} with splitting rate $b$ and death rate $k$ (\emph{$\text{BBM}(b, k)$}) is a discrete particle system that evolves according to the following dynamics:
    \begin{enumerate}
        \item each particle independently moves according to the law of a Brownian motion in $\mathbb{R}^d$ during its lifetime;
        \item a particle splits into two particles at the same spatial location at rate $b$;
        \item a particle dies at rate $k$.
    \end{enumerate}
    When $b=k$ we set $\gamma = 2b$ and we refer to the particle system as a \emph{branching Brownian motion} with parameter $\gamma$ (\emph{$\text{BBM}(\gamma)$}).
    \par
    For $\gamma \geq 0$ and for $c$, $\Tilde{c}>0$, \emph{on/off branching Brownian motion} with parameter $\gamma$, dormancy rate $c$ and wake-up rate $\Tilde{c}$ (\emph{$\text{ooBBM}(\gamma, c, \Tilde{c})$}) is a discrete particle system where particles take values in $\mathbb{R}^d \times \{0,1\}$. The first component is the spatial position of the particle and the second component denotes whether a particle is active (taking value $1$) or dormant ($0$). We furthermore have the following.
    \begin{enumerate}
        \item Each \say{active} particle independently has the spatial motion of a Brownian motion in $\mathbb{R}^d$. It also has splitting rate $\gamma/2$ and death rate $\gamma/2$ for some $\gamma \geq 0$ as before. Finally an \say{active} particle switches to a \say{dormant} particle with rate $c$ for some $c>0$.
        \item Each \say{dormant} particle does not move or split or die. Each particle stays in the same spatial position and switches to an \say{active} particle with rate $\Tilde{c}$ for some $\Tilde{c}>0$.
    \end{enumerate}
    BBM takes values in the space of finite measures on $\mathbb{R}^d$, $\mathcal{M}_F(\mathbb{R}^d)$, and ooBBM takes values in the space of pairs of finite measures on $\mathbb{R}^d$, $\mathcal{M}_F(\mathbb{R}^d)^2$, where the first component is the sum of unit Dirac masses at the positions of dormant particles and the second component similarly represents the active particles.

[Proposition 19 (Uniform convergence of truncated killing times) of arXiv:2607.19752, 'Weak Equilibrium Measures and Capacity--Hitting Identities\\ for the Hypoelliptic Third-Or'] For every $M<\infty$, as $\delta\downarrow0$,
\begin{equation}
    \sup_{z\in\partial A}
    \E_z\left[
        \left|(\tau_\calC^\delta\wedge M)-(\tau_\calC\wedge M)\right|
    \right]
    \longrightarrow0 .
\end{equation}
The same statement holds for the adjoint processes.

[Definition 86 of arXiv:2608.26084, 'Localic Esakia Duality\\via Conic Frames'] We denote by:
	\begin{enumerate}
		\item $\Heyt_\weak$ the full subcategory of~$\DLat$ containing Heyting algebras;
		\item $\Heyt_\strong$ the wide subcategory of~$\Heyt_\weak$ containing Heyting algebra maps.
	\end{enumerate}

[Lemma Palm-Lcal of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] For all non-negative measurable functions $f$ on $(\Omega,{\mathcal F })$,
	\begin{align}
		\hspace{-0.1cm} \mathbb E_{{\mathcal R }}^0 [f (\theta_{\beta(0)}({\mathcal H }))]
		& = 
		\frac {4\lambda^2} {\lambda_{{\mathcal R }}}
		\int_{(\mathbb{R}^+)^3} \!\!\!
		\mathbb{E}_{\mathcal H }\left[ {\mathds{1}}_{{\mathcal H }\left(U^{\hat{s}(0,h,-t',h')}_{\hat{h}(0,h,-t',h')}\right)=0}
		f \left(\theta_{\hat{s}(0,h,-t',h')}           \left({\mathcal H }+\delta_{(0,h)}+\delta_{(-t',h')}\right)\right)\right] {\rm d} h'{\rm d} h\,  {\rm d} t',
        \nonumber
	\end{align}
where, $(\hat{s}(t,h,t',h'),\hat{h}(t,h,t',h'))$
are the coordinates of the intersection of the two radial birds with heads $(t,h)$ and $(t',h')$ and $\lambda_{\mathcal R }=\frac{4\sqrt{\lambda}}{\pi}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 13 of arXiv:2607.09246, 'Scaling limit of 1+1 dimensional directed polymer with power-law tail and spatial correlat'] Assume that conditions \textbf{(A)} and \textbf{(B)} hold. Let the tail exponent satisfy $\alpha > \frac{6}{3-2r}$. If the inverse temperature sequence $\beta_N$ satisfies the thermodynamic scaling $\beta_N N^{H/2} \to \beta \in [0, \infty)$ as $N \to \infty$. Then the modified partition function $\mathfrak{Z}_N(\beta_N; \bar{\omega})$ converges in distribution to the continuous Wiener chaos $Z_{\sqrt{2}\beta}(1, \cdot)$ given by:
\begin{equation}
Z_{\sqrt{2}\beta}(1, \cdot) = 1 + \sum_{k=1}^{\infty} (\sqrt{2}\beta)^{k} \int_{\Delta_{k}(1)} \int_{\mathbb{R}^k} \tilde{\rho}_{k}(\mathbf{t}, \mathbf{x}) W(\mathrm{d}\mathbf{t}, \mathrm{d}\mathbf{x}).
\end{equation}
Here, the notations
\begin{itemize}
    \item $\Delta_k(1) = \{0 < t_1 < \dots < t_k \le 1\}$ denotes the standard $k$-dimensional time simplex;
    \item $\tilde{\rho}_{k}(\mathbf{t}, \mathbf{x})$ is the symmetrized Gaussian heat kernel introduced in Lemma \ref{lem:3.2};
    \item $W(\mathrm{d}\mathbf{t}, \mathrm{d}\mathbf{x})$ is a centered Gaussian space-time white noise, whose spatial covariance structure is  the fractional kernel $K(z) = H(2H-1)|z|^{2H-2}$ defined in Section 1.
\end{itemize}

