[Corollary cor:12-34 of arXiv:2603.28161, 'Boundary four-point connectivities of conformal loop ensembles'] For $x_1<x_2<x_3<x_4$, recall $f(x)$ defined in~(equation eq:f(x) of the paper). Then
\begin{align}
&G^{(12)(34)}(x_1,x_2,x_3,x_4)=\int \tau^{2b}f(1-\tau)\Phi_{x_1,x_2}^b \widetilde\mu_{\mathcal{U}(\eta_{12});x_3,x_4}(d\eta_{34})\widetilde \mu_{\mathbbm{H},x_1,x_2}(d\eta_{12}),\\
&G^{(1234)}(x_1,x_2,x_3,x_4)=\frac{1}{-2\cos\left(\frac{4\pi}{\kappa}\right)}\int \tau^{2b}f(\tau)\Phi_{x_1,x_2}^b \widetilde\mu_{\mathcal{U}(\eta_{12});x_3,x_4}(d\eta_{34})\widetilde \mu_{\mathbbm{H},x_1,x_2}(d\eta_{12}).
\end{align}
Here $\tau$ and $\Phi_{x_1,x_2}$ are defined as above. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:dsm of arXiv:2510.22778, 'Free denoising diffusion models'] Let $\{g_{\theta}\}_{\theta\in\Theta}$ be a family of maps sending a self-adjoint
operator to a self-adjoint operator, and let $w:[0,T]\to(0,\infty)$ be a weight.
Define
\begin{equation}
  \mathcal L(\theta)=\int_{0}^{T}w(t)\;
  \tau\Big[\big(g_{\theta}(X_{t},t)-\sqrt{\alpha_{t}}\,X_{0}\big)^{2}\Big]\mathrm{d} t,
\end{equation}
and, given a minimiser $\theta^{\star}$, the estimated free score
\begin{equation}
  \widehat\xi_{t}(X_{t})=\frac{1}{v_{t}}\big(X_{t}-g_{\theta^{\star}}(X_{t},t)\big).
\end{equation}

[Lemma 32 of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] If $T_{\lfloor (\log n)^{\frac{3+2\varepsilon}{6}}\rfloor}-T_M=\sum_{m=M+1}^{\lfloor(\log n)^{\frac{3+2\varepsilon}{6}}\rfloor}\zeta_m\ge\tfrac{1}{3}\delta n$, then
    \begin{align}
        \sum_{m=M+1}^{\lfloor(\log n)^{\frac{3+2\varepsilon}{6}}\rfloor} \zeta_m\wedge\left(\frac{1}{3}\delta n-\sum_{j=m+1}^{\lfloor (\log n)^{\frac{3+2\varepsilon}{6}}\rfloor}\zeta_j\right)^+\ge\frac{1}{3}\delta n.
    \end{align}

