[Theorem polynomial theorem of arXiv:2412.01086, 'Spectral radii of sparse non-Hermitian random matrices'] Suppose $Z$ has Weibull entries with shape parameter $\alpha >0$ and $p_n\gg (\log n)^{\frac{2}{\alpha}}/n$. Then 
\begin{align*}
\frac{\rho (Z)}{\sqrt{np_n}}\to 1
\end{align*}
in probability. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn Def of approximate Tridiagonal Entries of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] Define $\Tilde{a}_0(t):=a_1(t)=e_1^TM(t)e_1$, and for $k\geq 1$, define 
    \begin{equation*}
        \Tilde{a}_{k+1}(t):=\sqrt{n}\theta(t)^T P_{2k-1}(\Tilde{M}(t)/\sqrt{n})\theta(t).
    \end{equation*}
    For $k \geq 0$ let 
    \begin{equation*}
        \Tilde{b}_k(t)^2-n:=n\theta(t)^T P_{2k}(\Tilde{M}(t)/\sqrt{n})\theta(t).
    \end{equation*}

[Corollary 10 of arXiv:2506.22020, 'Norm-dependent Lamperti-type MAP representations of stable processes and Brownian motions '] Assume $d=2.$ Let $(\rho,\Theta)=(\rho_t,\Theta_t)_{t\geq0}$ be the underlying MAP of $\mathcal{R}$ from (\ref{item_d}) with respect to the $L^1$ norm on $\mathbb{R}^2$. Then, $(\rho,\Theta)$ is the unique weak solution to the following SDE:
	\begin{equation*}
		d\begin{pmatrix}
			\rho_t \\ \Theta_t
		\end{pmatrix}=\boldsymbol{a}(\Theta_t) dt + \boldsymbol{b}(\Theta_t) d\boldsymbol{W}_t + \boldsymbol{\gamma}(\Theta_t) d\ell_t,
	\end{equation*}
	where $\boldsymbol{W}$ is $2$-dimensional Brownian motion, $\ell$ is local time of $\Theta$ at the boundary of $\mathcal{S}^{2,+}_{1}$ (i.e., $\{(0,1),(1,0)\}$), and for $\boldsymbol{\theta}=(\theta_1,\theta_2)\in\mathcal{S}^{2,+}_{1}$,
	\begin{equation*}
		\boldsymbol{a}(\boldsymbol{\theta})\coloneqq \begin{pmatrix}
			-1 \\ \theta_1-\theta_2 \\ \theta_2-\theta_1
		\end{pmatrix},\qquad \boldsymbol{\gamma}(\boldsymbol{\theta})\coloneqq\begin{pmatrix}
			1 \\ \mathbbm{1}_{\{(0,1)\}}(\boldsymbol{\theta})-\mathbbm{1}_{\{(1,0)\}}(\boldsymbol{\theta}) \\ \mathbbm{1}_{\{(1,0)\}}(\boldsymbol{\theta})-\mathbbm{1}_{\{(0,1)\}}(\boldsymbol{\theta})
		\end{pmatrix},
	\end{equation*}
	and
	\begin{equation*}
		\boldsymbol{b}(\boldsymbol{\theta})\coloneqq\begin{pmatrix}
			\frac{2\theta_1\theta_2}{\sqrt{\lambda_2(\boldsymbol{\theta})}+\sqrt{\lambda_3(\boldsymbol{\theta})}}+\frac{\sqrt{\lambda_2(\boldsymbol{\theta})}+\sqrt{\lambda_3(\boldsymbol{\theta})}}{2} & -\frac{\theta_1-\theta_2}{\sqrt{\lambda_2(\boldsymbol{\theta})}+\sqrt{\lambda_3(\boldsymbol{\theta})}} \\
			-\frac{\theta_1-\theta_2}{\sqrt{\lambda_2(\boldsymbol{\theta})}+\sqrt{\lambda_3(\boldsymbol{\theta})}} & \frac{\sqrt{\lambda_2(\boldsymbol{\theta})}+\sqrt{\lambda_3(\boldsymbol{\theta})}}{4}-\frac{\theta_1\theta_2}{\sqrt{\lambda_2(\boldsymbol{\theta})}+\sqrt{\lambda_3(\boldsymbol{\theta})}} \\
			\frac{\theta_1-\theta_2}{\sqrt{\lambda_2(\boldsymbol{\theta})}+\sqrt{\lambda_3(\boldsymbol{\theta})}} & \frac{\theta_1\theta_2}{\sqrt{\lambda_2(\boldsymbol{\theta})}+\sqrt{\lambda_3(\boldsymbol{\theta})}} - \frac{\sqrt{\lambda_2(\boldsymbol{\theta})}+\sqrt{\lambda_3(\boldsymbol{\theta})}}{4}
		\end{pmatrix},
	\end{equation*}
	where $\lambda_2(\boldsymbol{\theta})=1+\theta_1^2+\theta_2^2+\sqrt{(1+\theta_1^2+\theta_2^2)^2-2}$ and $\lambda_3(\boldsymbol{\theta})=1+\theta_1^2+\theta_2^2-\sqrt{(1+\theta_1^2+\theta_2^2)^2-2}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] With the same assumptions and notations as in Theorem~\ref{th:convBessel}, given a filtered probability space $(\Omega,\mathcal{F},(\mathcal{F}_{t})_{t\geq 0},\PP)$ and a family of independent $(\mathcal{F}_{t})_{t\geq 0}$-Brownian motions $(B^i)_{i\in \N}$, consider the strong solution of the following SDE for each $i\in \N$:
\begin{equation*}
\begin{cases}
& \dd \overline{X}^{i}_t= \overline{V}^{i}_t \dd t, \quad t>0,\\
& \dd \overline{V}^{i}_t= (u_{t}(\overline{X}_{t}^{i})-\overline{V}_{t}^{i}) \dd t + \sigma \dd B_{t}^{i}, \quad t>0 ,
\end{cases}
\end{equation*}
with initial conditions given by a family of random variables $(X_{0}^i,V_{0}^i)_{i\in \N}$. For each $N\in \N^*$, let $(X^{i,N},V^{i,N})_{i\in \N}$ be the solution of the fluid-particle system~\eqref{Part} with the same initial conditions $(X_{0}^i,V_{0}^i)_{i\in \N}$ and same driving Brownian motion $(B^i)_{i\in \N}$, whose existence is given by Proposition~\ref{prop:existence-IPS}.
Then for any $q\geq 1$ and any $N\in \N^*$,
\begin{equation*}
\max_{i\in \{1,\dots, N\}} \E \sup_{t\in [0,T]} \big|(X_{t}^{i,N},V_{t}^{i,N}) - (\overline{X}_{t}^i,\overline{V}_{t}^i)\big|^q \lesssim |\sigma-\sigma_{N}|^q + \E \sup_{t\in[0,T]} \big\| u^{N}_t- u_t \big\|_{ \gamma,p}^{q} .
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:RBJ-Sk-invariance of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] For $k = 1, 2$ and all $x, y \in \mathcal{V}^m$,
\begin{equation}
B_{\mathcal{S}_k u}
(\mathcal{S}_k x, \mathcal{S}_k y)
= B_u(x, y).
\end{equation}

[Proposition 17 (asymptotics of visiting probabilities) of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] For all finite \(A \subset \Z^d\) and \(a \in A\), we have

\begin{equation*}{
\begin{aligned}
\frac{\P(\Tree^{x} \cap A \neq \emptyset \text{ and } W_{\Tree}^{x}(\Omega_{\text{in}}^{A})=a)}{g_{\theta}(x)} &\xrightarrow[x \to \infty]{} \P(\Tree_{-}^{a} \cap A = \emptyset); \\
& \\
\frac{\P(\Tree^{x} \cap A \neq \emptyset \text{ and } W_{\Tree}^{x}(\Omega_{\text{out}}^{A})=a)}{g_{\theta}(x)} &\xrightarrow[x \to\infty]{} \P(\Tree_{+}^{a} \cap A = \emptyset).
\end{aligned}
}\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 11 of arXiv:2604.24392, 'Numerical approximation of Markovian BSDEs in infinite horizon and elliptic PDEs'] Assume  \eqref{as:generatorf} and \eqref{as:b:sigma}.
Let us assume that we have following growth estimates on $X$: there exist some constants $c_{1,\eqref{ass:momentXandnablaX}}$, $c_{2,\eqref{ass:momentXandnablaX}}$, $c_{3,\eqref{ass:momentXandnablaX}}$, $c_{4,\eqref{ass:momentXandnablaX}}$, $c_{5,\eqref{ass:momentXandnablaX}} \geqslant 0$ such that, for all $t\geqslant 0$,
\begin{equation}

\Exp{|X_t^x|^{2r'}}^{1/2} \leqslant (c_{1,\eqref{ass:momentXandnablaX}}+c_{2,\eqref{ass:momentXandnablaX}}|x|^{r'})e^{c_{3,\eqref{ass:momentXandnablaX}}t}, \quad \Exp{\norm{\nabla X_t^x}^{2}}^{1/2} \leqslant c_{4,\eqref{ass:momentXandnablaX}}e^{c_{5,\eqref{ass:momentXandnablaX}}t}.  
\end{equation}
Then, for $a>c_{3,\eqref{ass:momentXandnablaX}}$ and $\ta > c_{3,\eqref{ass:momentXandnablaX}}+c_{5,\eqref{ass:momentXandnablaX}}$ we have following upper-bounds:
$$c_{\infty,\eqref{eq:condition:normA:rho}} \leqslant \max \left\{\frac{1}{a} + \frac{c_{1,\eqref{ass:momentXandnablaX}}}{a-c_{3,\eqref{ass:momentXandnablaX}}} ,  \frac{c_{2,\eqref{ass:momentXandnablaX}}}{a-c_{3,\eqref{ass:momentXandnablaX}}} \right\}$$
and
\begin{align*}
  &\tilde{c}_{\infty,\eqref{eq:condition:normA:rho}}\\ \leq& M_{\sigma}M_{\sigma^{-1}} c_{4,\eqref{ass:momentXandnablaX}}\sqrt{\pi} \max \left\{ \frac{1}{\sqrt{\ta-c_{5,\eqref{ass:momentXandnablaX}}}} + \frac{c_{1,\eqref{ass:momentXandnablaX}}}{\sqrt{\ta - c_{5,\eqref{ass:momentXandnablaX}} - c_{3,\eqref{ass:momentXandnablaX}}}} , \frac{c_{2,\eqref{ass:momentXandnablaX}}}{\sqrt{\ta-c_{5,\eqref{ass:momentXandnablaX}}-c_{3,\eqref{ass:momentXandnablaX}}}}  \right\}.
  \end{align*}

