[Lem 76 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] For any point $z \in \mathfrak{X}$ and integer $m \in [0, (q-q') / u(z)]$, the following two statements hold w.o.p., for each $t \in [\mathsf{t}'+mN^{10K\delta+2} u(z), N^5]$. First,
		\begin{flalign}
			 
			H_{t} (z) \le \mathcal{H}_{q-m u(z)} (z) + N^{\delta-1}.
		\end{flalign}

		\noindent Second, we have
		\begin{flalign}
			 
			H_{t} (z) \le \mathcal{H}_{q-mu(z)} (z), \qquad \text{if $z \notin \mathfrak{L}_{q-mu(z)}^+ (\delta)$}.
		\end{flalign}

[Lemma 58 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Let us consider, for $R>0$, a function $\widetilde{\tau}_R$ defined by 
\begin{align}
       \widetilde{\tau}_R: C([0,T];\mathbb{R}^2) \ni \omega \mapsto \inf\{ t\in [0,T]: \lvert \omega(t)\rvert \geq R\}\in [0,T].
     \end{align}
     Then, the following assertions hold. 
\begin{trivlist}
\item[(i)] For every $R>0$, the function $\widetilde{\tau}_R$ is lower-semicontinuous.
\item[(ii)] If additionally $\mathbb{P}$ is a Borel probability measure on $C([0,T];\mathbb{R}^2)$, then  there exists a set $\mathscr{R} \subset (0,\infty)$, whose complement is  at most countable and a full $\mathbb{P}$-measure set $\Omega^\prime \subset C([0,T];\mathbb{R}^2)$ such that  for every $R \in \mathscr{R}$ 
the function $\widetilde{\tau}_R$ is continuous  at every  $\omega \in \Omega^\prime$. 
\end{trivlist} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:uricchios_bipartition_cover_bound of arXiv:2604.09509, 'An Improved Bipartition Cover Bound for the Multispecies Coalescent Model'] If we have a species tree with $k$ species and minimum branch length $T_{\mathrm{min}}$ (in coalescent units) and a set $\cG$ of at least

\begin{equation}
     M_o(k,T_{\mathrm{min}}) := \frac{\log\left(\frac{1-q}{k-3}\right)}{\log \left(1-g_{k-2, 1}(T_{\mathrm{min}})\right)}
\end{equation}

\noindent gene trees sampled independently under the MSC model, then $\cG$ forms a bipartition cover with probability at least $q$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 39 of arXiv:2604.01852, 'The on/off Brownian snake'] Recall the on/off Brownian snake from Definition \ref{definition oo snake} with index set $I$. Let $\varepsilon > 0$ and let $h \coloneqq \varepsilon / 2$. We define the following measure-valued processes for $i \in I$ and for $s \geq 0$:
    \begin{equation}
        (\mathcal{Z}_{s,i}^{(\varepsilon, \rm d)}, \mathcal{Z}_{s,i}^{(\varepsilon, \rm a)}) \coloneqq \Big(\sum_{\substack{p: A^i_{\gamma^{(h)}_{p, i}}(s)=0,\\ H^i_{\gamma^{(h)}_{p, i}}(s) \in [Y_{p, i}^{(h)}, Z_{p, i}^{(h)})}} \delta_{w^i_{\gamma^{(h)}_{p, i}}(H^i_{\gamma^{(h)}_{p, i}}(s))}, \sum_{\substack{p: A^i_{\gamma^{(h)}_{p, i}}(s) = 1, \\ H^i_{\gamma^{(h)}_{p, i}}(s) \in [Y_{p, i}^{(h)}, Z_{p, i}^{(h)})}} \delta_{w^i_{\gamma^{(h)}_{p, i}}(H^i_{\gamma^{(h)}_{p, i}}(s))}\Big).
    \end{equation}
    Then we have that $((\mathcal{Z}_s^{(\varepsilon, \rm d)}, \mathcal{Z}_s^{(\varepsilon, \rm a)}))_{s \geq 0}$ defined as $(\mathcal{Z}_s^{(\varepsilon, \rm d)}, \mathcal{Z}_s^{(\varepsilon, \rm a)}) \coloneqq (\sum_{i \in I} \mathcal{Z}_{s,i}^{(\varepsilon, \rm d)}, \sum_{i \in I} \mathcal{Z}_{s,i}^{(\varepsilon, \rm a)})$ for $s \geq 0$ is an $\text{ooBBM}(4/\varepsilon, c, \Tilde{c})$ with initial condition given by dormant particles and active particles distributed as Poisson random measures with intensities $\mu_{\rm d}/\varepsilon$, $\mu_{\rm a}/\varepsilon$.
    \par
    Furthermore the process $(\mathcal{Z}_y^{(\varepsilon)})_{y \geq 0}$, where for $y \geq 0$ we define
    \begin{equation*}
        \mathcal{Z}_y^{(\varepsilon)} \coloneqq \sum_{i \in I} \sum_{p: y \in [Y_{p, i}^{(h)}, Z_{p, i}^{(h)})} \delta_{w^i_{\gamma^{(h)}_{p, i}}(y)}, 
    \end{equation*}
    is a $\text{BBM}(4/\varepsilon)$ starting from a Poisson random measure with intensity $(\mu_{\rm d}+\mu_{\rm a})/\varepsilon$.
    \begin{proof}
        We first show that $\mathcal{Z}_0^{(\varepsilon)}$ and $(\mathcal{Z}_0^{(\varepsilon, \rm d)}, \mathcal{Z}_0^{(\varepsilon, \rm a)})$ have the correct distributions. Let $\mu' \coloneqq \mu_{\rm d} + \mu_{\rm a}$. The random measure $\mathcal{Z}_0^{(\varepsilon)}$ is then a Poisson random measure with intensity
        \begin{equation*}
            n(T_h<\infty) \mu'(\cdot) = \mu'(\cdot)/ 2h = \mu'(\cdot)/\varepsilon
        \end{equation*}
        and $\mathcal{Z}_0^{(\varepsilon, \rm d)}$, $\mathcal{Z}_0^{(\varepsilon, \rm a)}
        $ are particles under a Poisson random measures with intensities $\mu_{\rm d}/2h = \mu_{\rm d}/\varepsilon$,
        \newline
        $\mu_{\rm a}/2h = \mu_{\rm a}/\varepsilon$ according to Definition \ref{definition oo snake}. For the ooBBM case we have by Proposition \ref{proposition single ooBBM with branching} for each initial active particle the subsequent behaviour then has the correct distribution and the particles with a dormant initial state switch to an active particle at the correct rate since the $s_i$ are sampled from $\text{Exp}(\Tilde{c})$. Finally, note that particles evolve independently under the Poisson random measure. The case for BBM is simpler.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

