[Corollary cor:principal of arXiv:2609.01672, '\textbf{All-Minors Matrix-Tree Theory for Superport Networks:\\ Completed Quotient-Inciden'] For \(I\subseteq N\), \(|I|=k\), define
\begin{equation}
\Psi_I=
\sum_{\substack{F\in\mathcal{F}_{q-k+1}\\N\setminus I\text{ spans a tree of }H_F}}w(F),
\qquad \Psi_{\varnothing}:=\Phi_{\mathrm{valid}}.
\end{equation}
Then
\begin{equation}
\boxed{\det L[I,I]=\frac{\Psi_I}{\Phi_{\mathrm{valid}}}.}

\end{equation}

[Corollary 5 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] There exist  bounded bilinear maps
   \begin{equation}
      \bB_0: \StokesV \times \StokesV \to \StokesVp
    \end{equation}
\begin{equation}
 \bR_0:   \zero{H}{2}(\domO) \times \zero{H}{2}(\domO) \to \StokesVp,
\end{equation}
such that, respectively, 
     \begin{align}
         \duality{\bB_0(\bu,\bv)}{\bw}{\StokesV}{\StokesVp}&= \bb_0(\bu, \bv, \bw),\;\;\forall \bu,\,\bv,\,\bw \in \StokesV, 
     \end{align}
and  
    \begin{equation}
      \duality{\bR_0(\phi,\psi)}{\bu}{\StokesV}{\StokesVp}= r_0(\phi,\psi,\bu), \;\;\;\forall \phi,\,\psi \in \zero{H}{2}(\domO),\,\bu \in \StokesV.
    \end{equation}
Moreover, the operator $\bR_0$ can be uniquely extended to a bounded bilinear operator (denoted by the same letter),
   \begin{equation*}
     \bR_0: \newone{H} \times  \newone{H} \to \rU_0^\prime.
   \end{equation*}
In particular, there exists a constant $C$ depending only on $\domO$ such that
     \begin{equation}
         \Vert \bR_0(\phi,\psi) \Vert_{\rU_0^\prime} \leq C \lvert \phi \rvert_{\newone{H}} \lvert \psi \rvert_{\newone{H}}, \; \phi,\,\psi \in \newone{H}.
     \end{equation}

