[Lemma divergencelemma of arXiv:2505.12187, 'Speeding up quantum Markov processes through lifting'] Let $P_{t,O} = \exp(t \mathsf{L}_O)$ be a symmetric contraction $C_0$-semigroup satisfying (assp:locoercive of the paper). For any $T > 0$ and $x_t \in L^2_\perp([0,T]; \mathcal{H}_O)$, there exists a solution $(z_t, y_t) \in H^1_{\mathsf{L}_O} \times H^2_{\mathsf{L}_O}$ to the abstract divergence equation:
    \begin{align} 
        \partial_t z_t - \mathsf{L}_O y_t = x_t  
    \end{align}
    that satisfies the estimates:
\begin{align}  
    \lVert\mathsf{L}_O y_t\rVert_{T, \mathcal{H}_O} \le c_1 \lVertx_t\rVert_{T, \mathcal{H}_O}\,, \quad  \sqrt{\mathcal{E}_{T, \mathsf{L}_O}(z_t)} \le c_2 \lVertx_t\rVert_{T, \mathcal{H}_O}\,,
\end{align}
and 
\begin{align} 
     \sqrt{\mathcal{E}_{T, \mathsf{L}_O}(y_t)} \le c_3 \lVertx_t\rVert_{T,\mathcal{H}_O}\,, \quad  \sqrt{\mathcal{E}_{T, \mathsf{L}_O}(\partial_t y_t)} \le c_4 \lVertx_t\rVert_{T,\mathcal{H}_O}\,, 
\end{align}
where 
\begin{align} 
    c_1 = c_2 = \Theta(1)\,,\quad c_3 = \Theta\left(T + \frac{1}{\sqrt{\lambda_O}} \right)\,, \quad c_4 = \Theta\left(1 + \frac{1}{T \sqrt{\lambda_O}}\right)\,.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 127 of arXiv:2601.16377, '2601.16377'] Given these data, the master problem asks to find an $H$-tuple of functions $\boldsymbol{F}(z)=(F_h(z))_{h=1}^H$ having the following properties for any $h \in [H]$.
\begin{enumerate}
\item $F_h(z)$ is holomorphic in $\amsmathbb C\setminus \amsmathbb{A}_h^{\mathfrak{m}}$.
\item There exists a holomorphic function $A_h(z)$ of $z \in \amsmathbb{M}_h$ such that
\begin{equation}

 A_h(z) = \sqrt{(z-\alpha_h) (z-\beta_h)} \,\big\langle \bth_h \cdot \boldsymbol{F}(z)\big\rangle + E_h(z).
 \end{equation}
 \item $F_h(z) = \frac{\kappa_h}{z}+O\big(\frac{1}{z^2}\big)$ as $z \rightarrow \infty$. This can be equivalently restated as
\[
F_h(z)\,\, \mathop{=}_{z \rightarrow \infty} \,\, O\bigg(\frac{1}{z}\bigg) \qquad \textnormal{and} \qquad \oint_{\gamma_h} \frac{\dd z}{2\ii\pi}\, F_h(z) = \kappa_h,
\]
where $\gamma_h \subset \amsmathbb{M}_h$ is a contour surrounding $\amsmathbb{A}_h^{\mathfrak{m}}$ and having counterclockwise orientation.
\end{enumerate}

[Theorem thm:bounded-state-rate of arXiv:2606.25135, 'Convergence Rates for Semistochastic Processes'] Let $\{X_t\}$ be a semistochastic process with generator (equation eq:gen of the paper) 
on the state space $\mathcal{X} = [0,k]$, satisfying 

\begin{itemize}
\item[(i)] 
$0 <  \lambda_*  \leq  \Lambda(x)  \leq  \lambda^{*}  <  \infty$ for all $ x  \in \mathcal{X} $, 
for some constants $ \lambda_*$ and~$\lambda^{*}$, 
\item[(ii)] 
$\rho(x,\alpha)  \geq  \rho_{*} $ for all $x \in \mathcal{X}$ and $ \alpha  \in  [0, 1]$, 
for some constant $\rho_* > 0$, 
\item[(iii)]
the function $v$ is non-negative,  
Lipschitz, and $v(0) \neq 0$ with $v(x)=0$ for at most finitely many $x$.
\end{itemize}

Then $\{X_t\}$ converges exponentially fast to its unique stationary distribution $\pi$. 
Namely, for any time increment $\Delta t > 0$, and any initial distribution $\mu_0$, 

\begin{equation}  
d_{\mathrm{TV}}\left( \mu_t , \pi \right)  
\leq  
\left(1-\epsilon_{\Delta t}\right)^{\lfloor t /\Delta t \rfloor} \ , 
\end{equation}
where 
\begin{equation}  
\epsilon_{\Delta t} 
:= 
\frac{  \rho_{*}  \Phi  \lambda_*   \exp (-\lambda^{*}  \Delta t) } { k }   \ ,
\end{equation}
\begin{equation}
\Phi 
:= \int_ 0^{\phi^ {\Delta t} (0)} [\Delta t - \psi(0, z)] \, {\mathrm{d}} z  \ ,
\end{equation}
and $\phi$ and $\psi$ defined in~(equation eq:phi-psi of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 12 of arXiv:2604.27242, 'Statistical Inference for Homogenization Limits Driven by Wiener or Hermite Processes'] Let \(H>3/4\) and \(H^*(m)>1/2\). If \(C_{\varepsilon,\delta}\) is the estimator defined in \eqref{eq: estimators} then, if \(\delta = \varepsilon^{\alpha}\) for some \(0<\alpha<\frac{2H^*(m)-1}{2H^*(m-1)-1}\) we have that
\begin{equation}
\delta^{2H-2}(C_{\varepsilon,\delta} - C) \xrightarrow[\varepsilon\rightarrow 0]{L^2} c_H Z^{2,2H-1}_1
\end{equation}
where \(Z^{2,2H-1}_1\) is the observed value at time \(1\) of the Rosenblatt process constructed with the same Brownian motion that generates \(y^{\varepsilon}\) and \(c_H\) is an explicit constant. 
\begin{multline}

c_H = \left(\frac{c_m m!}{\sqrt{(m-1)!}}\right)^2\frac{(1/\Gamma(2H-1))^m}{((m-1)(2H-2)+2)((m-1)(2H-2)+1)} \\ \left(\frac{8}{(4H-3)(2H-1)}\right)^{1/2}
\end{multline} (Proof in the paper; no proof environment follows the statement in the TeX.)

