[Lemma 18 of arXiv:2604.23461, 'Scaling limit of Sinkhorn-rescaled Random Matrices \\ via Stability of Static Schrödinger '] Let $H: L^2(\mu_1) \times L^2(\mu_0) \to L^2(\mu_0 \otimes \mu_1)$, be the linear map $(u, v) \mapsto u \oplus v$, whose adjoint $H^{\top} : L^2(\mu_0 \otimes \mu_1) \to L^2(\mu_0) \times L^2(\mu_1)$ is given by
	\begin{align}
		H^{\top} \psi = \left( \int_{\Omega_{\c}} \psi(\cdot, y)d\mu_1(y), \int_{\Omega_{\r}} \psi(x, \cdot) d\mu_0(x) \right). 
	\end{align}
	Let $\psi \in L^{\infty}_{>0}(\mu_0 \otimes \mu_1)$. Then
	\begin{itemize}
		\item[(i)]  $\partial_2 F(\psi, B(\psi)) = H^{\top}\Xi(\psi, \balpha_{\psi}, \bbeta_{\psi})H$
		\item[(ii)] $\partial_1 F(\psi, B(\psi)) = H^{\top} \Upsilon(\balpha_{\psi}, \bbeta_{\psi})$
		\item[(iii)] $\partial_2 \Psi(\psi, B(\psi)) = \Xi(\psi, \balpha_{\psi}, \bbeta_{\psi})H$. 
	\end{itemize}

