[Lemma 7 of arXiv:2607.17030, 'Stationary measures for log-gamma polymer on a strip and in half-space'] If $-\alpha<u<0$ and $v>u$ then,   as $N\to\infty$, we have
 \begin{equation}

     \GG_N(\alpha,u,v)\sim \Gamma(\alpha-u)^{N}\Gamma(\alpha+u)^N \tfrac{\Gamma(\alpha+v)}{\Gamma(\alpha-u)}\EE[R^{-u-v}],
 \end{equation}
 where $R$ is  given by \eqref{Rseries}.

If $-\alpha<v<0$ and $u>v$, then, as $N\to\infty$, we have
\begin{equation}
  \GG_N(\alpha,u,v)\sim
  \Gamma(\alpha+v)^N\Gamma(\alpha-v)^N
  \tfrac{\Gamma(\alpha+u)}{\Gamma(\alpha-v)}
  \EE[(R')^{-u-v}],
\end{equation}
where
\begin{equation}
  R'  =1+\zeta_1'+\zeta_1'\zeta_2'
  +\ldots+\zeta_1'\dots\zeta_n'+\dots,
\end{equation}
and $(\zeta_i')_{i\ge1}$ are i.i.d.\ $\mathrm{Beta}_{II}(\alpha+v,\alpha-v)$ random variables. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] Let $\Phi = (\varphi_t)$ be a nonwandering flow on $M$ tangent to a continuous nonvanishing vector field $X$.
\begin{enumerate}
    \item Any $C^0$-foliation transverse to $\Phi$ is taut,
    \item Any contact pair (positively) transverse to $\Phi$ is taut.
\end{enumerate}

[Proposition 7 of arXiv:2608.22746, 'Generative Neural Networks for Sinkhorn Distributionally Robust Hypothesis Testing'] Let $\mathbb{P}$ and $\mathbb{Q}$ be probability measures with finite second moments. The strong dual formulation of Sinkhorn discrepancy $\mathcal{S}_{\Reg}(\mathbb{P}, \mathbb{Q})$ is given by 
\begin{equation} \nonumber
    \sup_{f \in L^1(\mathbb{P}), g \in L^1(\mathbb{Q})} \quad \Big\{ \int f(\boldsymbol{x}) \ \diff \mathbb{P}(\boldsymbol{x}) + \int g(\boldsymbol{z}) \ \diff \mathbb{Q} (\boldsymbol{z}) - \Reg \iint \left[\exp \Big (\frac{f(\boldsymbol{x})+g(\boldsymbol{z}) -  c(\boldsymbol{x}, \boldsymbol{z})}{\Reg} \Big)-1 \right] \diff \mathbb{P}(\boldsymbol{x}) \diff \mathbb{Q}(\boldsymbol{z}) \Big\}, 
\end{equation}
Let $f_{\Reg}$ and $g_{\Reg}$ be the solutions of the dual formulation, which is also known as optimal entropic potentials. Then the transport plan 
\begin{equation} \nonumber
    \gamma_{\Reg}(\diff \boldsymbol{x}, \diff \boldsymbol{z}) = \exp\left(\frac{f_{\Reg}(\boldsymbol{x})+g_{\Reg}(\boldsymbol{z}) -  c(\boldsymbol{x}, \boldsymbol{z})}{\Reg}\right) \diff \mathbb{P}(\boldsymbol{x}) \diff \mathbb{Q}(\boldsymbol{z})
\end{equation}
is the unique solution to the Sinkhorn discrepancy, and the optimal entropic potentials satisfy
\begin{subequations}
    \begin{equation}
        \int \exp\left(\frac{f_{\Reg}(\boldsymbol{x})+g_{\Reg}(\boldsymbol{z}) - c(\boldsymbol{x}, \boldsymbol{z})}{\Reg}\right) \diff \mathbb{P}(\boldsymbol{x}) = 1, \quad \forall \boldsymbol{z} \in \Omega, 
    \end{equation}
    \begin{equation}
        \int \exp\left(\frac{f_{\Reg}(\boldsymbol{x})+g_{\Reg}(\boldsymbol{z}) -  c(\boldsymbol{x}, \boldsymbol{z})}{\Reg}\right) \diff \mathbb{Q}(\boldsymbol{z}) = 1, \quad \forall \boldsymbol{x} \in \Omega, 
    \end{equation}
\end{subequations}
for $\mathbb{Q}$-almost every $\boldsymbol{z}$ and $\mathbb{P}$-almost every $\boldsymbol{x}$, respectively. (Proof in the paper; no proof environment follows the statement in the TeX.)

