Let $\{\UnitTimeNormalizedUbarDataSurfaceTangentVectorfield, \datasurfacegeometricp{x^2},\datasurfacegeometricp{x^3}\}$ be the vectorfields from Def.\,\ref{D:VECTORFIELDSTANGENTTOUBARDATASURFACE} and let $\ubar$ be a solution to \eqref{E:INGOINGEIKONALEQUATIONINITIALVALUEPROBLEM}. Then the following identities hold:
\begin{subequations} 
	\begin{align}
		\begin{split} 
			\Lunit \ubar & =  \left\{ - 2 \coefficientsInVectorfieldsTangetToUbarDataSurface \UnitTimeNormalizedUbarDataSurfaceTangentVectorfield \ubar  + 2 \frac{\upmu}{(\muX \muX \upmu)^2} |\angD \muX \upmu|_{\gtorus}^2 - 2 \frac{\upmu \coefficientsInVectorfieldsTangetToUbarDataSurface}{\muX \muX \upmu} \angD^A \muX \upmu \datasurfacegeometricp{x^A} \ubar \right. \\
			& \ \ - \coefficientsInVectorfieldsTangetToUbarDataSurface
			\left\{\left(2 \UnitTimeNormalizedUbarDataSurfaceTangentVectorfield \ubar + 2\upmu \coefficientsInVectorfieldsTangetToUbarDataSurface \UnitTimeNormalizedUbarDataSurfaceTangentVectorfield \ubar - 2 \frac{\upmu}{\muX \muX \upmu} \angD^A \muX \upmu \datasurfacegeometricp{x^A} \ubar\right)^2  + 4\left( 2 \coefficientsInVectorfieldsTangetToUbarDataSurface  + \upmu \coefficientsInVectorfieldsTangetToUbarDataSurface^2  - \frac{\upmu}{(\muX \muX \upmu)^2} |\angD \muX \upmu|_{\gtorus}^2\right)\left(\upmu \gtorus^{AB} \datasurfacegeometricp{x^A} \ubar \datasurfacegeometricp{x^B} \ubar - \upmu (\UnitTimeNormalizedUbarDataSurfaceTangentVectorfield \ubar)^2\right) \right\}^{1/2}\\
			& \ \ \times \left\{ -4 \coefficientsInVectorfieldsTangetToUbarDataSurface  - 2\upmu \coefficientsInVectorfieldsTangetToUbarDataSurface^2 + \frac{2\upmu}{(\muX \muX \upmu)^2} |\angD \muX \upmu|_{\gtorus}^2\right\}^{-1}
		\end{split} \\ 
		\begin{split} 
			\muX \ubar & = \left\{ 2 \UnitTimeNormalizedUbarDataSurfaceTangentVectorfield \ubar + 2\upmu \coefficientsInVectorfieldsTangetToUbarDataSurface \UnitTimeNormalizedUbarDataSurfaceTangentVectorfield \ubar - 2 \frac{\upmu}{\muX \muX \upmu} \angD^A \muX \upmu \datasurfacegeometricp{x^A} \ubar \right. \\
			& \ \ - 
			\left\{\left(2 \UnitTimeNormalizedUbarDataSurfaceTangentVectorfield \ubar + 2\upmu \coefficientsInVectorfieldsTangetToUbarDataSurface \UnitTimeNormalizedUbarDataSurfaceTangentVectorfield \ubar - 2 \frac{\upmu}{\muX \muX \upmu} \angD^A \muX \upmu \datasurfacegeometricp{x^A} \ubar\right)^2  + 4\left( 2 \coefficientsInVectorfieldsTangetToUbarDataSurface  + \upmu \coefficientsInVectorfieldsTangetToUbarDataSurface^2  - \frac{\upmu}{(\muX \muX \upmu)^2} |\angD \muX \upmu|_{\gtorus}^2\right)\left(\upmu \gtorus^{AB} \datasurfacegeometricp{x^A} \ubar \datasurfacegeometricp{x^B} \ubar - \upmu (\UnitTimeNormalizedUbarDataSurfaceTangentVectorfield \ubar)^2\right) \right\}^{1/2}\\
			& \ \ \times \left\{ -4 \coefficientsInVectorfieldsTangetToUbarDataSurface  - 2\upmu \coefficientsInVectorfieldsTangetToUbarDataSurface^2 + \frac{2\upmu}{(\muX \muX \upmu)^2} |\angD \muX \upmu|_{\gtorus}^2\right\}^{-1}
		\end{split}
	\end{align} 
\end{subequations}

