[Proposition prop.localtimesBRW of arXiv:2411.19145, 'On the intersection of critical percolation clusters and other tree-like random graphs'] There exists $C>0$, such that for any $n\ge 1$, and any $x_1,\dots,x_n,z \in \mathbb Z^d$ (possibly with repetition), with $d\ge 5$, 
\begin{equation}
\mathbb E_z\Big[\prod_{i=1}^n \ell_c(x_i)\Big] \le C^n \sum_{\mathfrak t\in \mathbb T_n} G_{d-2}(\mathfrak t,\underline x)\cdot g_{d-2}(x_{\mathfrak t},z),
\end{equation}
and 
\begin{equation}
\mathbb E_z\Big[\prod_{i=1}^n \ell_\infty(x_i)\Big] \le C^n \Big(\sum_{\mathfrak t\in \mathbb T_n^\circ} \widetilde G(\mathfrak t,\underline x,z) + \sum_{\mathfrak t\in \mathbb T_n} G_{d-2}(\mathfrak t,\underline x)\cdot g_{d-4}(x_{\mathfrak t},z)\Big). 
\end{equation}

