body:
[Definition 1 of arXiv:2506.11918, 'Central limit theorems for the Euler characteristic in the Random Connection Model for hig'] [Simplex functions and integral representations] 
Let $K$ be a simplicial complex with $\dim(K)\leq\alpha$ on the vertex set $\{1,\dots,r\}$ for some $r\in\N$.
\begin{enumerate}
\item Define the simplex function of $K$ by
\begin{align*}
f_K: \X^r \rightarrow [0,1], \qquad f_K(x_1,\dots,x_r):= \prod_{\sigma\in K} \; \varphi_{|\sigma|-1} (x_\sigma),
\end{align*}
where $\varphi_{|\sigma|-1} (x_\sigma)$ denotes the value of $\varphi_{|\sigma|-1}$ evaluated at the points $\{ x_i\,|\, i\in \sigma\}$.
\item The integral representation $I_K$ of $K$ (over an observation window $W$) is defined by
\begin{align*}
I_K(W) \,:=\, \int_{W^r} f_K(x_1,\dots,x_r) \;\; \lambda^r \, (\d {(x_1,\dots,x_r)}).
\end{align*}
We call $K$ the simplicial complex associated to $I_K$.
\item For $m,l\in\{1,\dots,\alpha+1\}$ and $\max\{m,l\}\leq r\leq m+l$, we consider the simplicial complex
\begin{align} 
K_{m,l}^r \,:=\, \Big\langle [1,\dots,m], [1,\dots,m+l-r,m+1,\dots,r] \Big\rangle
\end{align}
on the vertex set $\{1,\dots,r\}$, which is generated by a $(m-1)$-simplex and a $(l-1)$-simplex sharing $m+l-r$ vertices.
Moreover, we denote by $\kappa_{m,l}^r$ the simplex function and by $\z m l r$ the integral representation of $K_{m,l}^r$, which means
\begin{align*}
\z m l r (W) \,:=\, \int_{W^r} \kappa_{m,l}^r(x_1,\dots,x_r) \;\; \lambda^r \, (\d {(x_1,\dots,x_r)}).
\end{align*}
Finally, let $\kappa_m:=\kappa_{m+1,m+1}^{m+1}$ be the simplex function of a simplicial complex generated by an $m$-simplex.
\end{enumerate}

[Lemma lem.updet.upperbound of arXiv:2605.14149, 'The mean-field limit of online stochastic vector balancing'] The function $\mathcal{U}_p^{\mathrm{det}}$ is continuous on $[0,1) \times \mathcal{P}_p({\mathbb R})$. For each $t \in [0,1]$ and $m \in \mathcal{P}({\mathbb R})$ with bounded support, we have
    \begin{align} 
        \mathcal{U}_p^{\mathrm{det}}(t,m) \leq [m]_{\infty}.
    \end{align}
    Moreover, for each $q > p$, $t \in [0,1)$ and $m \in \mathcal{P}_q({\mathbb R})$, we have
    \begin{align} 
    \mathcal{U}_p^{\mathrm{det}}(t,m) \leq C (1-t)^{-p/(q-p)} \Big(\int_{\mathbb R} |x|^q\,m(dx)\Big)^{1/(q-p)},  
    \end{align}
    where $C=C(p,q)$ is a constant depending only on $p$ and $q$.

