[Thm THn of arXiv:2412.00610, 'Joint Poisson Convergence of Monochromatic Hyperedges in Multiplex Hypergraphs'] Fix an integer $r \geq 2$ and consider a sequence $H_n$ of $r$-uniform hypergraphs. Suppose the vertices of $H_n$ are colored uniformly at random with $c_n$ colors as in (equation eq:cn of the paper), such that the following hold: 
    $$\lim_{n \to \infty}\bE T(H_n) = \lambda \text{ and } \lim_{n \to \infty}\Var T(H_n) = \lambda, $$ 
    for some constant $\lambda \geq 0$. Then, as $n \rightarrow \infty$, $$T(H_n) \dto \Pois(\lambda).$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Dfn 104 (discrete-time occupation measures) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Partition time into intervals $I_d \equiv [q_d,q_{d+1})$, and partition space into rectangles 
	$R_{\vl,j}
	\equiv J_{\vl}
	\times K_j$, as above.
Let $\rho_{\vY,N}$ be the occupation density for $\vY^{\frozen,\bullet,N}$: that is, we let $\rho_{\vY,N}$ be uniform on each $I_d\times R_{\vl,j}$, with
	\[
	\frac{\rho_{\vY,N}(I_d\times R_{\vl,j})}{|I_d|}
	= \mu_{\bullet,\bG^N}
	\Big( \vY^{\frozen,\bullet,N}(q_d) \in R_{\vl,j}\Big)
	\,,\]
where $\mu_{\bullet,\bG^N}$ is as defined in Theorem~\ref{t:tightness}.  Recall from Definition~\ref{d:rerand.Ising} that in the spatial rerandomization, the $a(q_d)\in[M]$ indices and the $i(q_d)\in[N]$ indices evolve completely independently, so the processes $\vY^{\frozen,\bullet,N,\RomI:\RomIII}$ and $Y^{\frozen,\bullet,N,\Ising}$ are independent under $\mu_{\bullet,\bG^N}$. This implies the above is equal to
	\beq
	\mu_{\bullet,\bG^N}
	\bigg( 
	\vY^{\frozen,\bullet,
	N,\RomI:\RomIII}(q_d)
	 \in J_{\vl}
	 \bigg)
	\cdot
	\mu_{\bullet,\bG^N}
	\Big( Y^{\frozen,\bullet,N,\Ising}(q_d) 
	\in K_j \Big)\,.
	\eeq
We similarly let $\rho_{D,N}$ be the signed measure which is uniform on each $I_d\times R_{\vl,j}$, with
	\begin{align}\nonumber
	&\frac{\rho_{D,N}
	(I_d\times R_{\vl,j})}{|I_d|}
	= 
	\bE_{\bG^N} \bigg[
	\frac{\Delta \bar{D}^{\frozen,\RomI,N}(q_d)}
	{\delta_d}
	\ind\Big\{
	\vY^{\frozen,\bullet,N}(q_d) \in R_{\vl,j}
	\Big\}\bigg] \\
	&\qquad\stackrel{\eqref{e:review.b}}{=}
	(p^N)'(q_d)^{1/2}
	\bigg\{ \sum_{B^\frozen \in 
		B^{\frozen,\coarse}}
		\frac{|B^\frozen|}
			{|B^{\frozen,\coarse}|}
	\bbb^{\frozen,N}\Big(q_d, 
		B^\frozen \Big)
	\bigg\}
	\mu_{\bullet,\bG^N}
		\Big( 
		\vY^{\frozen,\bullet,N}(q_d) \in R_{\vl,j}\Big) \nonumber\\
	&\qquad\stackrel{\eqref{e:review.b}}{=}
	(p^N)'(q_d)^{1/2}
	\bbb^{\frozen,\coarse,N}(q_d, B^{\frozen,\coarse}) 
	\mu_{\bullet,\bG^N}
		\Big( 
		\vY^{\frozen,\bullet,N}(q_d) \in R_{\vl,j}\Big)

	\end{align}
with $B^{\frozen,\coarse}=B^{\frozen,\coarse}(q_d,J_{\vl})$ as defined by \eqref{e:coarsened.bucket}, and recalling that the last term above factorizes as in \eqref{e:a.i.factorization}. We similarly define measures $\rho_{V,N}$, $\rho_{U,N}$, 
$\rho_{\www,N}$,
and $\rho_{\rrr,N}$
 using increments of 
$\tilde{Q}^{\frozen,\RomII,N}$, $\tilde{Q}^{\frozen,\RomII,\RomIII,N}$, $\tilde{Q}^{\frozen,\Ising,N}$, and 
$C^{\frozen,\RomIII,N}$ respectively.

[Proposition 9 of arXiv:2608.27307, '2608.27307'] Under Assumption~\ref{ass:basic}, the following statements hold.
        \begin{enumerate}[label=(\roman*)]
                \item There exists a unique holomorphic function $\Pi:\C^+\to\C^{L\times L}$ such that, for every $z\in\C^+$, $\Om(\Pi(z),z)=0$, $\Im\Pi(z)>0$, and $\Im(z^{-1}\Pi_{11}(z))>0$.
                \item Define $\wt T(z):=z^{-1}\Pi_{11}(z)$ and $T(z):=\Pi_{22}(z)$. There exist unique positive semidefinite matrix-valued measures $V_1$ and $V_2$ on $[0,\infty)$, with values in $\C^{M\times M}$ and $\C^{N\times N}$, respectively, such that $V_1([0,\infty))=I_M$, $V_2([0,\infty))=I_N$, and
                      \begin{align}
                              \wt T(z)=\int_{[0,\infty)}\frac{V_1(\dd\la)}{\la-z},\qquad T(z)=\int_{[0,\infty)}\frac{V_2(\dd\la)}{\la-z}. \nonumber
                      \end{align}
                      Moreover, there exists a constant $C_*<\infty$ such that $\supp V_1\cup\supp V_2\subset[0,C_*]$.
                \item Let $\bnu_1:=\avg{V_1}_M$ and $\bnu_2:=\avg{V_2}_N$. Then $\bnu_1$ and $\bnu_2$ are compactly supported probability measures on $[0,\infty)$ and, with $\wt m(z):=\avg{\wt T(z)}_M$ and $m(z):=\avg{T(z)}_N$,
                      \begin{align}
                              \wt m(z)=\int_{[0,\infty)}\frac{\bnu_1(\dd\la)}{\la-z},\qquad m(z)=\int_{[0,\infty)}\frac{\bnu_2(\dd\la)}{\la-z}. \nonumber
                      \end{align}
                      Moreover,
                      \begin{align}
                              g(z)=-\avg{\Sg}_N+\int_{[0,\infty)}\frac{\la\avg{\Sg V_1(\dd\la)}_N}{\la-z}. \nonumber
                      \end{align}
                \item Writing $\bnu:=\bnu_2$, we have $\sup\supp\bnu\sim1$. Moreover, the mass at the origin is
                      \begin{align}
                              \bnu(\{0\})=\left(1-\frac{M}{N}\right)\mb 1\left(\frac{M}{N}\leq1\right). 
                      \end{align}
        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:abstract-simple-response of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] If $\Lambda_n^\mu$ is simple, then for every $f\inH_{\mathrm{reg}}$ the two one-sided
derivatives agree and
\begin{equation}
 \partial_f^-\Lambda_n^\mu
 =\partial_f^+\Lambda_n^\mu
 =:\partial_f\Lambda_n^\mu
 =-\kappa\Lambda_n^\mu
 \int_{S} f(\phi_n^\mu)^2\,d\mu.

\end{equation}
If $\int_{S}f\,d\rho=0$, then also
\begin{equation}
 \partial_f\Lambda_n^\mu=\int_{S}f\,d\eta_n^\mu.

\end{equation}

[Proposition 15 of arXiv:2605.03057, 'Uniform-in-time quantitative fluctuations of large scale interacting particle systems'] Assume Assumption~\ref{ass:smooth}. Let $\left(\mu_s\right)_{0\le s\le t}$ be the law flow of the McKean--Vlasov SDE~\eqref{eq:MV}.
Let $\varphi\in C_b^5\left(\R^d\right)$ and let $\left(\psi_s\right)_{0\le s\le t}$ be a classical solution to the backward equation
\begin{equation}

\partial_s\psi_s+\mathcal L_{\mu_s}\psi_s+\mathcal A_{\mu_s}\psi_s=0,\qquad s\in\left[0,t\right),\qquad \psi_t=\varphi.
\end{equation}
Then, the limiting variance in Definition \ref{def:uniform-time-limiting-variance-abs-assump} can be written as
\begin{equation}

\sigma_t^2\left(\varphi\right)
=
\Var\left(\psi_0\left(X_0\right)\right)
+\int_0^t \E\left(\norm{\sigma\left(X_s,\mu_s\right)^\top\nabla\psi_s\left(X_s\right)}^2\right) ds,
\end{equation}
where $X$ solves \eqref{eq:MV}. In particular, $\sigma_t^2\left(\varphi\right)=\lim_{N\to\infty}\sigma_{N,t}^2\left(\varphi\right)$.

[Lemma 27 of arXiv:2604.05234, 'Quantitative propagation of chaos and universality for asymmetric Langevin spin glass dyna'] Let $\bfJ$ be a $N \times N$ matrix of i.i.d. standard Gaussian random variables. Then for all $k, l \in \bbN$ we have
    \begin{equation}
        \frac{\bbE\big[\big(J^k(J^\top)^l\big)_{11}\big]}{N^{(k+l)/2}} = \left \{ \begin{aligned}&\delta_{k, l} + \frac{1}{N}\eps_{k, l}  &\quad & k+ l \text{ even,} 
        \\ &0 &\quad & k+l \text{ odd},\end{aligned}\right.

    \end{equation}
    where $\delta_{k,l}$ denotes the Kronecker delta and $|\eps_{k, l}| \leq (k+l)!!$. Additionally for all $k, l, n, m \in \bbN$,
\begin{equation}\frac{\textup{Cov}\big[\big(J^k(J^\top)^l\big)_{11},\big(J^n(J^\top)^m\big)_{11}\big]}{N^{(k+l+m+n)/2}} =
\left \{ \begin{aligned}& \frac{1}{N}\eps_{k,l,n,m}  &\quad & k+ l+n+m \text{ even,} 
        \\ &0 &\quad & k+l+n+m \text{ odd},\end{aligned}\right.
         \end{equation}
         where $|\eps_{k,l,m,n}| \leq (k+l+m+n)!!$.

