\begin{equation*}
	\frac{L(g f)}{gf} = \eth^2f  + \eth f\big( 2\eth g' +k_1\coth\frac{x}{2} +2k_2\coth(x) \big) + \eth^2g+k_1 \eth g \coth\frac{x}{2}+2k_2\eth g\coth x.  
\end{equation*}

Observe that
\begin{equation*}
	\eth_x g(x)=\frac{k_1}{2}\Big(\frac{2}{x}-\coth\frac{x}{2}\Big) + k_2\Big(\frac{1}{x}-\coth x\Big).
\end{equation*}
Moreover,
	\begin{multline*}
