[Cor discrete-exc of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] Let $\tau_\delta$ be the XOR-Ising field with $+$ boundary conditions on $D_\delta$. Let $(C_k^\delta)_{k=0}^N$ be the collection of clusters of the trace $\hat\mathbf{n}_\delta$ of a DRC with wired boundary conditions on $D_\delta$. Then,
    \begin{align*}
        \tau_\delta(z) = \mu^\delta_0(z)+\sum_{k=1}^N\xi_k^\delta\mu^\delta_k(z), 
    \end{align*}
    where $(\xi_k^\delta)_{k\geq1}^N$ are the i.i.d. symmetric signs and $(\mu_k^\delta)_{k\geq1}^N$ are the renormalized discrete area measures given by 
    \begin{equation}
        \mu^\delta_k(dz):=\delta^{-1/4}\mathbf{1}_{\{z\in C^\delta_k\}}dz.
    \end{equation}
    The dual statement  also holds, without the measure $\mu_0^\delta$ of the boundary cluster. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 7 of arXiv:2605.11279, 'Flocking with Multiple Types: Competition, Fluid Limits and Traveling Waves'] Suppose that Assumptions \ref{assumption0} and \ref{assumption2} hold. Then for any $t \geq 0$ and any $\eta >  0$,
    \begin{align*}
        \lim_{L\to\infty} \limsup_{n\to\infty} \prob\parens*{\int \abs*{x} \ind_{\curlbr*{|x| \geq L}} \mu_n(t, \di \xx) \geq \eta} = \lim_{L\to\infty} \limsup_{n\to\infty} \prob\parens*{\dfrac{1}{n}\dsum_{i=1}^n |x^n_i(t)| \ind_{\curlbr*{|x^n_i(t)| \geq L}} \geq \eta} = 0.
    \end{align*}

[Lem potential of arXiv:2411.16376, 'Higher order approximations in arcsine laws for subordinators'] Let $X=(X_t)_{t\geq0}$ be a killed subordinator which is not identically zero. Let $N\in\ensuremath{\mathbb{N}}$ and $\lambda\in(0,+\infty)$ be fixed. Assume that the Laplace exponent $\Phi(z)$ satisfies
\begin{align}
    \int_{-\infty}^{+\infty}
    \bigg|
    \bigg(
    \bigg(\frac{d}{dz}\bigg)^N
    \frac{1}{\Phi}\bigg)
    (\lambda+i\theta)
    \bigg|\,d\theta<+\infty.	
\end{align}
Then the potential measure $U|_{(0,+\infty)}$ restricted over $(0,+\infty)$ admits a continuous density 
\begin{align}
   u(x)=\frac{x^{-N}e^{\lambda x}}{2\pi}\int_{-\infty}^{+\infty}
       e^{i\theta x}
       \bigg(
      \bigg(-\frac{d}{dz}\bigg)^N \frac{1}{\Phi}\bigg)
    (\lambda+i\theta)
        \,d\theta,
       \quad
       0<x<+\infty.	
\end{align}

[Proposition 41 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] For every \(u>0\) there is a unique probability law \(Q^u\) on
\(C([-u,\infty))\) with the following property.  Suppose
\begin{equation}
\begin{gathered}
  h_n=2^{-r_n}\downarrow0,\qquad
  u_n\in h_n\mathbb N,\qquad u_n\to u,\\
  L_n\in h_n\mathbb N,\qquad L_n\to\infty,
\end{gathered}

\end{equation}
and let
\begin{equation}
  Q_n:=\mathcal L\bigl(
    W\,\big|\,W_t\leq0,
    \ t\in h_n\mathbb Z\cap[-u_n,L_n]
  \bigr).

\end{equation}
Then
\begin{equation}
  (\mathsf E_{u_n\to u})_*Q_n\Longrightarrow Q^u
  \quad\text{in }C_{\mathrm{loc}}([-u,\infty)).

\end{equation}
Moreover,
\begin{equation}
  Q^u(W_t\leq0\text{ for every }t\geq-u)=1,
  \qquad Q^u(W_{-u}<0)=1.

\end{equation}
The map
\begin{equation}
  u\longmapsto(\mathscr A_u)_*Q^u
  \quad\text{from }(0,\infty)\text{ to }\mathcal P(\mathcal Y)

\end{equation}
is weakly continuous.

There is also a unique directed one-sided hard-wall law \(Q^0\) on
\(C([0,\infty))\), obtained by using only positive dyadic constraint sites.
It satisfies
\begin{equation}
  Q^0(W_0=0,\ W_t\leq0\text{ for every }t\geq0)=1.

\end{equation}

