[Theorem 19 of arXiv:2510.27451, 'Bi-martingale optimal transport and its applications'] Assume a continuous cost ${c} \in C((\Rd)^2)$, bounded from below and satisfying the $p$-growth condition \eqref{eq:quad_bound_cost} for $p<2$, and probabilities $\mu,\nu \in \mathcal{P}^\ba_2(\Rd)$  (not necessarily in convex order).

	Take any sequences $\mu_{n}, \nu_{n} \in \mathcal{P}^\ba_2(\Rd)$ converging   in Zolotarev metric $Z_2$ to $\mu, \nu$, respectively. Moreover, take a sequence $\eps_n >0$ that converges to zero and for which,
	\begin{equation}

		\lim_{n \to +\infty} \frac{Z_2(\mu,\mu_{n})  + Z_2(\nu,\nu_{n})}{\eps_n}=0.
	\end{equation}
	Then, the sequence $F_n$\, $\Gamma$-converges to $F$ on the space $\Mes((\Rd)^2; \R \times \Rd)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:Okounkov_contraction of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Let $\Upsilon$ be an $s$-cell ribbon graph with perimeters $(m_1,\dots,m_s)$. The \emph{Okounkov contraction} is a map
\[
\Phi: \left\{ \Upsilon \right\} \longrightarrow \left\{ \Gamma \in \mathscr{D}_{s;\beta} \right\}
\]
constructed via the following operations:
\begin{enumerate}[leftmargin=*,label=(\roman*)]
    \item If the marked vertex lies on a tree, move it to the root of that tree;
    \item Collapse all univalent (degree-1) vertices;
    \item Remove all divalent (degree-2) vertices, except for marked ones;
    \item Record a weight $w_e$ on each edge $e$, which is  equal to one plus the number of divalent vertices removed along it.
\end{enumerate}

[Proposition prop:stronger-DHX of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] For any boundary condition $\xi\in\Sigma_M^c$ and any $\mathcal{P}_0,\mathcal{P}_1,\mathcal{U}$ defined as in Definition (def: boundary connectivity event of the paper) such that $\mathcal P_0\neq\emptyset$, there exists an absolute constant $c_7>0$ such that for any $I\subset\Lambda_M$ we have \begin{equation}
        \Big|\langle\sigma^I\mid \mathcal R\rangle^{\xi}_{\Lambda_M,0}\Big|\le c_7^{|I|} F(\bar\partial\Lambda_M,I);
    \end{equation}
\begin{equation}
        \Big|\langle\sigma^I\mid\mathcal S\rangle^{\xi}_{\Lambda_M,0}\Big|\le c_7^{|I|} F(\bar\partial\Lambda_M,I).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 11 of arXiv:2606.16083, 'Eyring--Kramers asymptotics for infinite-dimensional stochastic gradient systems'] Under Assumption~\ref{Ass_for_theorem_II}
for $\tau>0$ small enough
    \begin{align}

        \int_{B_\tau(x_\pm)}e^{-\beta U}\mathrm{d}\gamma_\beta=e^{-\beta F(x_\pm)}C_\pm \left(1+O_{\beta\rightarrow \infty}\left(1/\sqrt{\beta}\right)\right).
    \end{align}
    Furthermore, we have for $\beta$ large enough and a suitable constant $C>0$
    \begin{itemize}
        \item in the case $F(x_-)=F(x_+)=0$, that 
         \begin{align}

        \left|Z_\beta - \left(C_-+C_+\right)\right|\leq C/\sqrt{\beta},
    \end{align}
    \item in the case $0=F(x_-)<F(x_+)$
   \begin{align*}
       \left|Z_{\beta} - C_-\right|\leq C/\sqrt{\beta}.
   \end{align*}
    \end{itemize}
   In both cases $Z_\beta,Z_{\beta} \geq 1/2$ for $\beta$ large enough.

