body:
[Proposition 24 of arXiv:2606.22611, 'Upper and Lower Bounds on Expected Soft Maxima\\of Gaussian Processes'] For any $\nu\in \eP(T)$, let
\begin{align*}
	H_{\epsilon}(\nu)\deq \sup_{\rho\in B_{{\rm TV}}(\nu,\epsilon) }H(\rho)
\end{align*}
where
\begin{align}
	B_{{\rm TV}}(\nu,\epsilon) \deq \left\{ \mu \in \eP(T): \lVert \mu - \nu \rVert_{{\rm TV}} \le \epsilon \right\}
\end{align}
is the closed ball of radius $\epsilon$ with respect to total variation distance centered at $\nu$.
  For any $\epsilon \in [0,1-\frac{1}{\abs{T}}]$, let $\omega(\epsilon)
  \deq \epsilon \log (\abs{T}-1) + h(\epsilon) $
  where $h(\epsilon) \deq -\epsilon \log \epsilon - (1-\epsilon)\log (1-\epsilon)$ is the binary entropy function.
 \begin{enumerate}
   \item 
     Given any $\nu\in \eP(T)$ and $\epsilon, \delta \in [0, 1-\frac{1}{\abs{T}}]$, 
     \begin{align*}
      H_{\epsilon}(\nu) \le H_{\epsilon+\delta}(\nu)\le H_{\epsilon}(\nu) + \omega(\delta)
     \end{align*}
  \item For any $\epsilon,\delta \in [0, 1-\frac{1}{\abs{T}}]$,
    \begin{align*}
    \sup_{\rho,\nu:\, \lVert \rho-\nu \rVert_{\rm TV}\le \delta} 
    \abs{H_\epsilon(\rho)- H_{\epsilon}(\nu)} \le \omega(\delta)
    \end{align*}

 \end{enumerate}

