[Prop 17 of arXiv:2509.09589, 'Geometry of critical discrete structures: long-range percolation on the hierarchical latti'] [Upper bound on the two-point function]
\begin{enumeratea}
\item
Let $\alpha\in (0, d)$ and $\alpha < \theta < \min\{ 2\alpha, \alpha + d/3 \}$.
Then for $x\in\Lambda_n\setminus\{0\}$,
\begin{align}
	\pr(0 \connects x)
	\lesssim
	\begin{cases}
		\zeta_n^{-1} \| x\|^{-\alpha}\, ,\ \ \text{ if }\ \ L\leq \|x\| \leq L^{n a_0}\, ,
		\\[3pt]
		L^{-n( d + \alpha - \theta ) }\, , \text{ if }\ \ L^{n a_0}< \|x\| \leq L^n\, ,
	\end{cases}
\end{align}
where $a_0 = 2 - \theta\alpha^{-1}$.

\item 
Let $\alpha\in (0, d/3)$ and $2\alpha \leq \theta < \alpha + d/3 $.
Then
\begin{align}
\pr(0 \connects x)
\lesssim
L^{-n( d + \alpha - \theta ) }
\ \ \text{ for }\ \ x\in\Lambda_n\setminus\{0\}.
\end{align}

\end{enumeratea} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 6 of arXiv:2608.30658, 'Higher Regularity of Time-Periodic Solutions to Nonautonomous Hyperbolic Problems: Away fr'] {\bf 1.}	
			Assume that,  for all $j,k\le n$, the coefficients
			$a_j$,   $b_{jk}$,  $p_{jk}$, $r_{jk}$, and $h_j$
			belong to  $C^{1}_{per}$, the coefficients $f_j$ belong to $C_{per}\cap C_t^1$,
			the coefficients	$m_{jk}$   belong to  $C_{per}\cap C_x^1$, all   in their respective domains.
			If the conditions \reff{aj} and \reff{nonrez}
			are satisfied 
			for all $j\le n$,  $x\in[0,1]$, $t\in\R$, and $i=1$,
			then any continuous  solution to the problem~(\ref{lin})--\reff{per} 
			belongs to~$C^1(\Pi;\R^n)$.\\
			{\bf 2.}
			Assume that,  for all $j,k\le n$, the coefficients
			 $r_{jk}$ and $h_j$
			belong to  $C^{2}_{per}$,  the coefficients $a_j$, $b_{jk}$ belong to $C^{1}_{per}$ with  $\d_ta_j, \d_tb_{jk}\in C^{1}_{per}$,  the functions $f_j$ belong to $C^1_{per}\cap C_t^2$,
			the coefficients	$m_{jk}$   belong to  $C_{per}\cap C_x^2$ and have the continuous derivatives $\d_tm_{jk}$, 
			and the coefficients $p_{jk}$ belong to $C_{per}\cap C_t^2$ with $\d_xp_{jk}\in C_t^{1}$, all   in their respective domains.
			If the conditions \reff{aj} and \reff{nonrez}
			are satisfied 
			for all $j\le n$,  $x\in[0,1]$, $t\in\R$, $i=1$, and $i=2$,
			then any continuous  solution to the problem (\ref{lin})--\reff{per} 
			belongs to~$C^2(\Pi;\R^n)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem maximum_degree of arXiv:2606.09386, 'High-degree vertices in uniform recursive directed acyclic graphs with freezing'] Fix $m\in\mathbb{N}$, $c\in(0,m+1)$, and a choice sequence $\mathbf x$ such that Assumption~$\hyperref[ass:A]{\mathbf{x}}$ is satisfied for some $\varepsilon<1-c/(m+1)$ in Part~(item:hI of the paper) and some $\eta<1-c/(m+1)$ in Part~(item:Jn of the paper). Let $(i_n^\mathrm{a})_{n\in\mathbb{N}}$ and $(i_n^\mathrm{f})_{n\in\mathbb{N}}$ be sequences such that $i_n^\mathrm{a}+\log_\theta A_n >0$ and $i_n^\mathrm{f}+\log_\theta F_n >0$ for all $n$, and 
\begin{equation} 
\limsup_{n\to\infty} \frac{i_n^\mathrm{a}+\log_\theta A_n}{h_n^+}<c\qquad\text{and}\qquad \limsup_{n\to\infty}\frac{i_n^\mathrm{f}+\log_\theta F_n}{\log F_n}<c.
\end{equation} 
Then,
\begin{equation}
\mathbb{P}(\Delta_n^\mathrm{a}\geq \lfloor \log_\theta A_n\rfloor+i_n^\mathrm{a}, \Delta_n^\mathrm{f}\geq \lfloor \log_\theta F_n\rfloor+i_n^\mathrm{f}) =(1+o(1))\prod_{\square\in\{\mathrm a,\mathrm f\}}\!\!\! \big(1-\exp\big(-\theta^{-i_n^\square+\varepsilon_n^\square}\big)\big).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:prob_level_i_cell of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{lem:first_iterative_renormalisation}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 1$ and suppose that $J : V \times V \to \mathbf{R}_+$ is a transitive kernel satisfying $J(x,y) = \Omega (d_G(x,y)^{-d \alpha})$ with $\alpha \in (0,2)$.

    Let $\beta > \beta_c$, let $((\Tile{i}{j})_{j \geq 0})_{i \geq 0}$ be the renormalisation scheme in \thref{def:renormalisation_scheme}, and let $\xi=\xi(d,\alpha) > 0$ be sufficiently small. 

    For $\delta > 0$, there exist $r_0$ and $\overline{r}_0$ sufficiently large such that  for any cell $\Cell{i}{j}$

    \begin{equation}

        \mathbf{P}_{\beta}
        \left(
            \Cell{i}{j}
            \text{ is good}
        \right)
        \geq
        1 - \delta.
    \end{equation}

