[Deff reac-diff-domain-avg-lyap-exp of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] Let $\epsilon > 0$ be arbitrary and $P_{inv}(\mathcal{M}_0)$ denote the set of all invariant measures of the process $v_t \coloneqq u_t/\|u_t\|_{L^1}$ on $\mathcal{M}_0 \coloneqq \{v \in C(\overline D)_+ \mid \|v\|_{L^1} = 1\}$, where $u_t$ solves (equation reac-diff-domain-linearized of the paper). We define \begin{equation}
        \begin{aligned}
            \Lambda \coloneqq \sup_{\mu \in P_{inv}(\mathcal{M}_0)} \mu \Big(&-\int_D d\Delta\Big(vK^{-1}\Big)K^{-1} + (r - E)vK^{-1} + \frac{1}{2}\epsilon^2\sigma'(0)^2\Big[\int_D v\Big]^2 \Big) \,.
        \end{aligned}
    \end{equation}

[Lemma u Lu H-1 of arXiv:2411.05924, 'Non-negative Martingale Solutions to the Stochastic Porous Medium Equation with Sticky Beh'] For $\mathbf v_n, \mathbf w_n \in \mathbb R^n$,
    \begin{equation}

        \left\| \mathbf v_n \odot \mathbf w_n \right\|_{\mathbf H^{-1}_n} \lesssim \|\mathbf v_n\|_{\mathbf H^{-1}_n} \|\mathbf w_n\|_{\mathbf H^{1}_n}.
    \end{equation}

[Lemma 19 of arXiv:2606.09904, 'Non-explosion principles for branched rough differential equations with unbounded coeffici'] Assuming \(\phi\) is such that \(\|D^k\phi(x)\| \le l(\|x\|)^{\alpha_k}\) for all \(k = 0, 1, \dots, N\), 
  we have for any \(f \in \CF_{N - 1}\), 
  \begin{equation}
    \|\partial^f_X \phi(\mathbf{Y}_t)\| = \|\partial^{[f]}_X Y_t\|
      \le \frac{1}{\Pi(f)} l(\|Y_t\|)^{\sum_{k = 0}^{N - 1} \Lambda_k([f]) \alpha_k}.
  \end{equation}
  Moreover, if \(\alpha_k = (1 - \beta k)\alpha\) for some constants \(\alpha\) and \(\beta\), then 
  \begin{equation}
    \|D^n \partial^f_X \phi(\mathbf{Y}_t)\| \le \frac{(1 + |f|)^n}{\Pi(f)} 
      l(\|Y_t\|)^{((1 + |f|) - (n + |f|)\beta)\alpha}
  \end{equation}
  for any \(n \in \mathbb{N} \cup \{0\}\), \(n \le N - |f|\).

