[Prop 6 of arXiv:2606.14812, 'Joint convergence in Wiener chaos via transport hierarchy and Malliavin covariances'] Let $p \geq 2$ and let $(X_N = I_p(f_N), N \geq 1)$ with $f_N \in H^{\odot p}$ 
		for all $N \geq 1$. Assume that $(X_N, N \geq 1)$ satisfies \eqref{c1}. Let 
		$(\mathbb{Y}_N = (Y_{1,N}, \ldots, Y_{d,N}), N \geq 1)$ be a $d$-dimensional random sequence 
		such that for every $j = 1, \ldots, d$, $Y_{j,N}$ belongs to the $q_j$-th Wiener 
		chaos with $q_j < p$. Assume that
		\begin{equation*}
			\mathbb{Y}_N \xrightarrow[N\to\infty]{(d)} \mathbb{Y} = (Y_1, \ldots, Y_d).
		\end{equation*}
		Then
		\begin{equation*}
			(X_N, \mathbb{Y}_N) \xrightarrow[N\to\infty]{(d)} (Z, \mathbb{Y}),
		\end{equation*}
		where $Z \sim N(0, \sigma^2)$ and $Z$ is independent of $\mathbb{Y}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2411.04631, 'Existence of Martingale Solutions to Stochastic Constrained Heat Equation'] Suppose $v \in C ([0,T_1],\mathcal{S} )$ then we define \textbf{modulus of continuity of v} as 
    \begin{align}
        m(v,\epsilon)=\sup_{s_1,s_2 \in [0,T_1],\; |s_1-s_2|\leq \epsilon} \mathcal{\rho}(v(s_1),v(s_2)) \nonumber
    \end{align}

[Proposition pr2 of arXiv:2411.02362, 'Limit theorems for random Dirichlet series: boundary case'] Under the assumptions of Theorem (main of the paper),
\begin{equation}
\limsup_{s\to 0+}\Big(\frac{1}{\log 1/s\,\log^{(3)}1/s}\Big)^{1/2}\sum_{k\ge 2}\frac{(\log k)^{-1/2}}{k^{1/2+s}}\eta_k\geq(2\sigma^2)^{1/2}\quad\text{\rm a.s.}
\end{equation}
and
\begin{equation}
\liminf_{s\to 0+}\Big(\frac{1}{\log 1/s \,\log^{(3)}1/s 
}\Big)^{1/2}\sum_{k\ge 2}\frac{(\log k)^{-1/2}}{k^{1/2+s}}\eta_k\leq-(2\sigma^2)^{1/2}\quad\text{\rm a.s.}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition Mapping of a shape of arXiv:2608.12415, 'Sharp Phase Transition for Ellipsoid Fitting'] Given a shape \(\tau\), a mapping of \(\tau\) is a function
\(
    \sigma:V(\tau)\to \mathbb N
\)
such that:
\begin{enumerate}
    \item each vertex is assigned a label from the range specified by its vertex type;
    \item \(\sigma\) is injective on vertices of the same type.
\end{enumerate}

[Thm hadamard of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] {LK-hadamard}}]
    Consider the radial Loewner equation driven by $\zeta_t$. For a.e. $t<\tau(z)\wedge\tau(w)$ and all $z,w\in D_t$, the map $t\mapsto G_t(z,w)$ is absolutely continuous and 
    \begin{equation}
       -\partial_t G_t(z,w) = P_{\mathbb D}(g_t(z), \zeta_t)P_\mathbb D(g_t(w), \zeta_t),
    \end{equation} 
    where $g_t=f^{-1}_t:D_t\to\mathbb D$ and $P_\mathbb D(z, \zeta)=\frac{1-|z|^2}{|z-\zeta|^2}$ is the Poisson kernel in $\mathbb D$. (Proof in the paper; no proof environment follows the statement in the TeX.)

