body:
[Definition 18 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Assume that $(\Omega, \mathscr{F}, \mathbb{F},\mathbb{P})$
is a filtered complete probability space with filtration $\mathbb{F}= \{\mathscr{F}_t\}_{t\in[0,T]}$ satisfying the usual assumptions \ref{ass-usual}.     
Assume that $\tildeW$ is an $\ell^2$-cylindrical Wiener process on that probability space.
A $\mathbb{V}$-valued progressively measurable process $\bX=(\bu,\phi)$ is a weak solution, in the PDE sense, to Problem \eqref{eqn-compact-modified-stochastic-CHNSEs-3} if and only if 
\begin{trivlist}
\item[(i)] for $\mathbb{P}$-almost all $\omega \in \Omega$, the trajectory $\cp(\cdot,\omega)$ of the process  $\cp=(\cp(t): t\in [0,T])$ defined by
              \begin{equation}
                 \cp(t)= \Atwo \phi(t) + \psi^\prime(\phi(t)) - \avg{\psi^\prime(\phi(t))}, \;\; t\in [0,T]    
              \end{equation}
belongs to the space $L^{2}(0,T;\newone{H})$ and  
\begin{equation}
\mathbb{E} \int_0^T \lvert \cp(t)\rvert_{\newone{H}}^2\,\d t <\infty, 
\end{equation}
and 
\item[(ii)] 
the process $\left(\bF(\bX(t)): t \in [0,T]\right)$ is a $\mathbb{V}^\prime$-valued progressively measurable process such that 
\begin{equation}
    \mathbb{E} \int_0^T \Vert \bF(\bX(s)) \Vert_{\mathbb{V}^\prime}\,\d s <\infty,
\end{equation}
the process $\left(\newG_0(t,\bX(t)): t \in [0,T]\right)$ is an $\ell^2(\mathbb{H})$-valued progressively measurable process such that 
\begin{equation}
    \mathbb{E} \int_0^T \Vert \newG_0(s,\bX(s)) \Vert^2_{\ell^2(\mathbb{H})}\,\d s <\infty,
\end{equation}
and, $\mathbb{P}$-almost surely, 
\begin{equation}
\bX(t)=\bX_0+ \int_0^t  \bF(\bX(s))\,\d s + \int_0^t [ \newG_0(s,\bX(s))]\,\d \tildeW(s) \mbox{ in }  \nU^\prime, \mbox{ for every } t \in [0,T],
\end{equation}
where by $\int_0^t [ \newG_0(s,\bX(s))]\,\d \tildeW(s)$, we mean the It\^o integral understood as an $\mathbb{H}$-valued continuous martingale defined earlier,
and the maps $\bF$ and $\newG_0$ are defined in \eqref{eqn-F and G}.
\end{trivlist}

[Definition 231 of arXiv:2601.16377, '2601.16377'] The \emph{spectral curve} associated to the above data and a non-zero $\boldsymbol{v} \in \amsmathbb{R}^H$ is the Riemann surface
\begin{equation}

\Sigma_{\boldsymbol{v}} := \left(\bigsqcup_{\boldsymbol{w} \in \mathfrak{G}.\boldsymbol{v}} \widehat{\amsmathbb{H}}^{+} \sqcup \widehat{\amsmathbb{H}}^-\right) \Big/ \sim.
\end{equation}
Here, $\widehat{\amsmathbb{H}}^{\pm} \subset \widehat{\amsmathbb{C}}$ is the upper (respectively, lower) hemisphere of the Riemann sphere in which we include $\widehat{\amsmathbb{R}}^{\pm} := \amsmathbb{R} \cup \{\infty\} = \partial \widehat{\amsmathbb{H}}^{\pm}$. We call $\amsmathbb{B}^\pm$ the segment $\amsmathbb{B}$ inside $\widehat{\amsmathbb{R}}^{\pm}$, and likewise for $\overline{\amsmathbb{B}}_{h}^{\pm}$. The equivalence relation consists in identifying
\begin{itemize}
\item $\widehat{\amsmathbb{R}}^+ \setminus \amsmathbb{B}^+$ with $\widehat{\amsmathbb{R}}^- \setminus \amsmathbb{B}^-$ in the same copies;
\item $\overline{\amsmathbb{B}}_{h}^{+}$ in the $\boldsymbol{w}$-th copy with $\overline{\amsmathbb{B}}_{h}^{-}$ in the $T^{(h)}(\boldsymbol{w})$-th copy, for each $\boldsymbol{w} \in \mathfrak{G}.\boldsymbol{v}$ and $h \in [H]$.
\end{itemize}
For $\boldsymbol{w} \in \mathfrak{G}.\boldsymbol{v}$ we denote
\begin{equation}

\overline{\amsmathbb{B}}_{\boldsymbol{w}}^{\pm} = \bigcup_{g \in \textnormal{supp}(\boldsymbol{w})} \overline{\amsmathbb{B}}_{g}^{\pm} .
\end{equation}
We use the same notation for the image of \eqref{Bamhbw} in $\Sigma_{\boldsymbol{v}}$, and call
\begin{equation}

\overline{\amsmathbb{B}}_{\boldsymbol{w}} := \overline{\amsmathbb{B}}_{\boldsymbol{w}}^+ \cup \overline{\amsmathbb{B}}_{\boldsymbol{w}}^- \subset \Sigma_{\boldsymbol{v}}.
\end{equation}
the $\boldsymbol{w}$-th \emph{gluing locus}. The $\boldsymbol{w}$-th \emph{sheet}, denoted $\Sigma_{\boldsymbol{v},\boldsymbol{w}}$ is the image in $\Sigma_{\boldsymbol{v}}$ of the $\boldsymbol{w}$-th copy of $\widehat{\amsmathbb{H}}^+ \sqcup \widehat{\amsmathbb{H}}^-$ in \eqref{wcopydoubleplae}, from which we remove the $\boldsymbol{w}$-th gluing locus \eqref{wgluloc}. The $\boldsymbol{v}$-th sheet is called the \emph{principal sheet}.

[Thm 5 of arXiv:2608.26642, '2608.26642'] Assume that $\P_0[X_1^2]<\infty$. If a function $f\in C(\R)$ satisfies the Sturm--Liouville equation (\ref{main-SLeq}), then the following growth conditions are equivalent:
\begin{enumerate}
  \item[i.] (\ref{main-SLgrowth}) holds.
  \item[ii.] For every $z\in \R$,
  \begin{align}

    \lim_{x\to \pm \infty}\Big(f(x+z)-f(x)\Big)=\pm \frac{z}{\P_0[X_1^2]}.
  \end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:sublinearCorrector_martingaleFCLT of arXiv:2411.06861, 'Quenched invariance principle for random walks in random environments admitting a cycle de'] Suppose $d\geq 2$, Assumption ~(ass:P of the paper)-(i) and Assumption ~(ass:p-q-moment of the paper) hold. Let $\chi, \Phi$ be as constructed in Lemma (lem:corrector_construction of the paper). Then 
\begin{enumerate}[(i)]
    \item $\chi$ is sublinear on a large scale, i.e. for $\mathbb{P}$-a.e. $\omega$,  and all $i=1, \dots, d,$
    \begin{align}

    \lim_{n\to\infty}\frac{1}{n}\norm{\chi^i(\omega, \cdot)}_{\infty, B(n)}=0; 
    \end{align}
    \item  $M:= (\Phi(\cdot, X_t))_{t\geq 0}$ satisfies the quenched invariance principle, i.e. QFCLT holds for $M$ with a deterministic nondegenerate covariance matrix $\Sigma^2$ given by 
\begin{align}

    \Sigma^2_{i,j}=\mathbb{E}\Big[\sum_{z\in \mathcal{N}} c_{\mathrm{s}}^{\omega}(0, z)\Phi^i(\omega, z) \Phi^j(\omega, z) \Big],
\end{align}
for $1\leq i, j \leq d;$
\item $\chi$ vanishes along random walks under the diffusive scaling, i.e., 
for $\mathbb{P}$-a.e. $\omega$, and all $i=1, \dots, d$, $T>0$, 
\begin{align}

    \lim_{n\to \infty}\sup_{t\in [0, T]} \frac{1}{n}\abs{\chi^i(\omega, X_{n^2t})}=0 \qquad \text{in } \Prob_0^\omega.
\end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 3 of arXiv:2607.11756, 'Full replica symmetry breaking in the Sherrington--Kirkpatrick model'] Let $\mu=\mu_\beta$.  For every $q\in\supp\mu$,
\begin{equation}
 \Gamma_\mu(q)=q
\end{equation}
and
\begin{equation}
 \beta^2\E\bigl[u_{\mu,xx}(q,X_q^\mu)^2\bigr]\le1.
\end{equation}
In particular,
\begin{equation}
 \beta^2u_{\mu,xx}(0,0)^2\le1.
\end{equation}

[Lemma lm:es_conA of arXiv:2606.12143, 'Continuous stochastic flows driven by white noise and their duals'] Under Assumptions~(assu:H of the paper) and~(assu:A of the paper), the following properties hold.
\vspace{-0.5em}
\begin{enumerate}[label=(\roman*)]
    \item For any $x,y,t\in {\mathbb R}$ and $\alpha,\beta\in \{1,2\}$,
    $$
    \partial_x^\alpha \partial_y^\beta a(x,y,t) = \int_{\mathbb R} \partial_x^\alpha \sigma(x,t,s) \partial_y^\beta \sigma(y,t,s)\ensuremath{\mathrm{d}} s.
    $$
    In particular, $\partial_x \bar{\sigma}(x,t) = 2 \int_{\mathbb R} \sigma(x,t,s)\partial_x\sigma(x,t,s)\ensuremath{\mathrm{d}} s $.
    \vspace{-0.5em}

    \item The functions $a$ and $b$ belong to the classes $\widetilde{C}^{2,1}_{ub}$ and $C^{1,1}_{ub}$, respectively; see [Ku90] for the definitions of these spaces.
    \vspace{-0.5em}

    \item The coefficients $(\sigma,b)$ satisfy conditions~(item:1a of the paper)--(item:1d of the paper).
\end{enumerate}

