body:
[Theorem The:main_result of arXiv:2411.04778, 'Coupling between Brownian motion and random walks on the infinite percolation cluster'] Fix  $d\geqslant 2$ and $\mathfrak{p} \in (\mathfrak{p}_c(d), 1]$. For almost every configuration $\omega\in \Omega$ and $y\in\mathscr{C}_\infty(\omega)$, we can construct a version of VSRW $(S_t)_{t \geqslant 0}$
		and Brownian motion $(\bar{B}_t)_{t \geqslant 0}$ with diffusive constant $\bar{\sigma}$ in the same probability space, both starting from $y$, such that for every $\delta >0$ and for all $T > \mathcal{T}_\delta(y)$, we have
		\begin{align}
			\mathbb{E}^\omega\Big[\sup_{t\in [0,T]} \vert S_t - \bar{B}_t \vert_2 \Big] \leqslant K T^{\frac{1}{3}+\delta},
		\end{align}
		where $K$ is a finite positive constant depending on $d, \mathfrak{p},\delta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 146 of arXiv:2601.16377, '2601.16377'] Consider a family of discrete ensembles with $H=1$ parameterized by $\boldsymbol{t} = (\hat{a},\hat{b},\hat{n})$ in some open set of $\amsmathbb{R}^3$, where $[\hat{a},\hat{b}]$ represents the defining segment and $\hat{n}$ the segment filling fraction. We suppose that the weights satisfy Assumption~\ref{Assumptions_analyticity} with integers $\iota^{\pm}$ and complex domain $\amsmathbb{M}$ independent of $\boldsymbol{t}$ while the regular part of the potential $U(z)$ and the parameters $\rho_j^{\pm}$ for $j \in [\iota^{\pm}]$ are twice-continuously differentiable with respect to $\boldsymbol{t}$ for any $z \in \amsmathbb{M}$ --- with partial derivatives up to order $2$ which are holomorphic functions of $z \in \amsmathbb{M}$. Assume that the discrete ensemble for $\boldsymbol{t}^0$ satisfies Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic}, \ref{Assumptions_offcrit}, \ref{Assumptions_analyticity} and that the equilibrium measure has a single band.

Then, there exists a constant $C > 0$ depending only on the constants in the assumptions, such that for any $\varepsilon > 0$ and for any $\boldsymbol{t}$ in the $\frac{1}{C}$-neighborhood of $\boldsymbol{t}^0$ and satisfying the integrality constraints \eqref{integra}, for $\N$ large enough in a way that depends only on $\varepsilon$ and $C$ we have
\begin{equation}

\Big|\log \Z_\N -\big( \I[\boldsymbol{\mu}]\N^2  + \theta \hat n\, \N \log \N + \mathbbm{Rest}_1 \N \big) \Big| \leq  \eps,
\end{equation}
and the absolute values of $\mathbbm{Rest}_1$ and its first and second partial derivatives with respect to $\boldsymbol{t}$ are bounded by $C$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 4 (Phase-space constrained limits) of arXiv:2604.02129, 'Realisation of constraints in underdamped Langevin dynamics'] Given $\eps>0$, let $(Q_t,P_t)$ be the solution to~\eqref{eq:abc-slow},\eqref{eq:intro-Phase-Cons-Fast} with corresponding initial datum $(Q^i_0,P^i_0)$ for $i=1,2$.
    \begin{enumerate}[label=(\roman*)]
        \item 
        For any $t\geq 0$
        \begin{align}


             \max\biggl\{\E\Bigl[|Q^{1}_t|^2\Bigr] , \E\Bigl[ |P^{1}_t|^2\Bigr]\biggr\} &\leq C_1 \left(\eps +  e^{- \frac{t}{\eps} C_2} \Bigl(   \bigl|Q^{1}_0\bigr|^2+ \bigl|P^{1}_0\bigr|^2  \Bigr)\right), 
        \end{align}
        where $C_1, C_2>0$ are independent of $\eps$ and $r$. 


        \item Let $(q_t,p_t)\in \R^{2(d-k)}$ with initial data $(q_0,p_0)=(Q^2_0,P^2_0)$ evolve according to~\eqref{eq:limit-gen} with $\hat q=0 \in \R^k$. Recall the definition of the potential $V$ from~\eqref{eq:Valpha} and the parameter $\alpha\geq 0$. In general (i.e. for any $\alpha\geq 0$) we have 
        \begin{align}

            \mathbb{E} \biggl[ \sup_{t\in [0,T]}\left|\begin{pmatrix}
            q_t - Q^{2}_t \\ p_t-P^{2}_t  
            \end{pmatrix} \right|^2 \biggr] \leq 
            \begin{cases}
            C_3 e^{C_4  T} \Bigl( \eps T^2 + \eps T \Bigl( |Q_0^{1}|^2 +  |P_0^{1}|^2 \Bigr)\Bigr) \ \ &\text{if $\alpha=0$,}\\

            \eps C_5 \left( T + |Q^1_0|^2 + |P^1_0|^2 \right) &\text{if $\alpha>0$}.
            \end{cases}
        \end{align}
        In the case when $\alpha>0$ (i.e. $V$ has a quadratic part) and $\eps$ small enough we additionally have the uniform-in-time $L^1$- estimate
        \begin{align}
            \mathbb{E} \biggl[ \sup_{t \geq r}\left|\begin{pmatrix}
            q_t - Q^{2}_t \\ p_t-P^{2}_t  
            \end{pmatrix} \right| \biggr] \leq \sqrt{\eps} C_6  + 

            \eps C_7 e^{- C_8 r}\Bigl( |Q_0^{1}| +  |P_0^{1}| \Bigr)       
            \end{align}
        Here 

        the constants $C_i>0$ for $i\in \{3,\ldots,8\}$ are independent of $\eps>0$ and $T>0$.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:curved-support-upper-bound of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] Let \(\nu\) be a nonzero finite Borel measure supported on \(\mathbb S^1\). Then
\begin{equation}
\dim_{\mathrm F}(\nu)\le\alpha_{\min}(\nu).
\end{equation}

