body:
[Lemma thm:gaussian.mc.characterization of arXiv:2604.22453, 'Adapted Wasserstein Barycenters of Gaussian Processes'] Let $\mathbb{X}^1, \ldots, \mathbb{X}^K \in \mathcal{FG}(T, d)$ be filtered Gaussian processes. 
Let \(\pi = \mathcal{L}(\widebar{\boldsymbol{\epsilon}}) = \mathcal{N}_{KTd}(\mathbf{0}, \mathbf{P})\) be a jointly Gaussian coupling of $\mathbb{X}^1,\ldots,\mathbb{X}^K$, where $\mathbf{P}$ satisfies (equation eqn:P.block.condition of the paper). The following are equivalent:
\begin{enumerate}
\item[(i)] \(\pi\) is multicausal.
\item[(ii)] $\mathbf{P} = (\mathbf{P}_{s,t})_{s,t = 1}^T$ is block diagonal. Equivalently, the stacked noises $\widebar{\boldsymbol{\epsilon}}_1, \ldots, \widebar{\boldsymbol{\epsilon}}_T$ are jointly independent under $\pi$.
\end{enumerate}

[Definition 1 (The random environment) of arXiv:2607.02019, 'Critical branching processes in random environment with immigration and an application to '] Let $(\mathcal E_n)_{n\in\mathbb Z}$ be an i.i.d.\ sequence of random variables, called the \emph{environment}.  For each $n\in\mathbb Z$,
the value of $\mathcal E_n$ determines the reproduction and immigration laws in force between generations $n$ and $n+1$.  Conditional on $(\mathcal E_n)_{n\in\mathbb Z}$, we define:
\begin{itemize}
	\item For each $n\in\mathbb Z$, a sequence $(\xi_{n,i})_{i\ge1}$ of offspring random variables that are identically distributed over $i$.
	\item For each $n\in\mathbb Z$, an immigration random variable $M_n$.
\end{itemize}

We assume the following independence, given $(\mathcal E_n)_{n\in\mathbb Z}$
\begin{itemize}
	\item For each fixed $n$, the variables $(\xi_{n,i})_{i\ge1}$ are independent for all $n$ and $i$ and are independent of $M_n$.
	\item For $n\neq m$, the collections $\{(\xi_{n,i})_{i\ge1},\,M_n\}$ and $\{(\xi_{m,i})_{i\ge1},\,M_m\}$ are independent.
\end{itemize}

[Prop 39 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $p=p(\xi)$ be of the form
    \begin{equation*}
        p(\xi)=\sum_{k\in \Lambda}p_ke^{2i\pi \ps{k}{\xi}}, \quad\xi\in \T^d,
    \end{equation*}
    where $\Lambda=\prod_{j=1}^d\disc{-n_j}{m_j}$, $n_j,m_j\geq 0$ and $p_k\in \C$, $k\in \Lambda$. We assume that 
    \begin{equation}
        \exists \hspace{0.1cm }k\in \Lambda\setminus \{0\}, \m p_k\neq 0.
    \end{equation}
    Let us denote 
    \begin{equation*}
        S:=\sum_{j=1}^d (n_j+m_j)>0, \mm \Xi:=\prod_{j=1}^d(n_j+m_j+1) \mm\text{and}\mm m:=\sum_{\substack{k\in \Lambda\\ k\neq 0}}\bb{p_k}>0.
    \end{equation*}
    Then, for all $z\in \C$, $t\geq 0$, 
    \begin{equation}
        \mathrm{L}\pr{\acc{\xi \in \T\m ;\m \bb{p(\xi)-z}^2\leq t}}\leq 14d \pr{\frac{\sqrt{\Xi}}{m}\sqrt{t}}^{\frac{1}{S}}.
    \end{equation}

