[Defi def:relEnt of arXiv:2602.17579, 'Non-equilibrium functional inequalities for finite Markov chains'] For $\varphi\in \mathcal D_\pi(\ensuremath{\mathbb{Z}})$ we define the \emph{relative entropy} and ($M$-)\emph{Fisher information} 
     respectively as
    \begin{align}
        \mathscr{H}_{\pi}(\varphi) &\coloneqq \sum_{z\in\ensuremath{\mathbb{Z}}}  \varphi(z)\log \varphi(z) \pi(z),  \\
        \mathscr{R}_\pi(\varphi,M) &\coloneqq \bigl(\varphi , -M \log \varphi\bigr)_{\pi} =  -\sum_{z,z'\in\ensuremath{\mathbb{Z}}} \varphi(z) \log \varphi(z') M(z,z') \pi(z). 
    \end{align}

[Proposition prop:harmonic of arXiv:2609.02987, 'Tail Likelihood Reinforcement Learning'] For every truncation order $T\geq1$,
\begin{equation}
J_{\mathrm{TailRL{}}}^{(T)}(\theta;x)
=
\sum_{k=1}^{T}
\frac{\text{Best-of-}k(\theta;x)-1}{k}.

\end{equation}

