[Proposition prop:basic-facts-probability of arXiv:2512.21026, 'Minimax Duality in Game-Theoretic Probability\thanks{Work in progress: mistakes are likely'] Let $(\Omega,\mathcal{Z})$ be a gamble space, and let $A\subseteq\Omega$.
  Then
  \begin{enumerate}
  \item $\underline{\textsf{\textbf{P}}} A = 1 - \overline{\textsf{\textbf{P}}} A^c$.
  \end{enumerate}
  If gambles are furthermore arbitrage-free and positive-linear, then
  \begin{enumerate}[resume]
  \item $0 \leq \underline{\textsf{\textbf{P}}} A \leq \overline{\textsf{\textbf{P}}} A \leq 1$.
  \item $\overline{\textsf{\textbf{P}}} A + \overline{\textsf{\textbf{P}}} A^c \geq 1$.
  \end{enumerate}

