[Lem strong-law of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] Let $W,V,U$ be as in (as-W of the paper), (as-V of the paper), (as-U of the paper).
For any $x \in \mathcal{M}$ we have 
\begin{equation}
    \lim_{t \to \infty} \frac{M_t^W(x)}{t} = 0 \qquad \textrm{a.s.}
\end{equation}
and for any $x \in \mathcal{M}_+$ we have 
\begin{equation}
    \lim_{t \to \infty} \frac{M_t^V(x)}{t} = 0 \qquad \textrm{a.s.} \,,
\end{equation}
where $M^W_t$ and $M^V_t$ were defined in (equation Mtf of the paper).

[Lem 5. lem: technical lemmas for pcpt of aging functions of arXiv:2412.08236, 'Aging and sub-aging for Bouchaud trap models on resistance metric spaces'] The following statements hold.
  \begin{enumerate} [label = (\roman*)]
    \item 
      For each $l > 0$, 
      \begin{equation} 
        \lim_{r \to \infty} 
        \sup_{n \geq 1} 
        P_{\rho_{n}}^{\nu_{n}} \Bigl( \tau_{B_{R_{n}}(\rho_{n}, r)}^{\nu_{n}} \leq l \Bigr) 
        = 0.
      \end{equation}
    \item 
      For any $x_{n} \in F_{n}$ and $x \in F$ such that $x_{n} \to x$ in $M$,
      and any $\delta > 0$,
      \begin{equation}
        \lim_{\eta \to 0} 
        \limsup_{n \to \infty} 
        P_{x_{n}}^{\nu_{n}}(\tau_{B_{R_{n}}(x_{n}, \delta)}^{\nu_{n}} \leq \eta)  
        = 0.
      \end{equation} 
  \end{enumerate}

[Lemma 18 of arXiv:2606.09121, 'Truncated Signature Information for Mixed Fractional Brownian Paths'] Let $U\subset\R^p$ be open, let $\mu:U\to\R^d$ be continuously differentiable, and let $\theta_0\in U$.  If $J_0=D\mu(\theta_0)$ has full column rank, then there exist $r>0$ and $c>0$ such that $\overline{B}(\theta_0,r)\subset U$ and
\begin{equation}
    \|\mu(\theta)-\mu(\theta_0)\|
    \ge c\|\theta-\theta_0\|,
    \qquad \|\theta-\theta_0\|\le r.
\end{equation}

[Lemma 3 of arXiv:2506.17470, 'The coalescent of a sample from a linear-fractional branching process'] Let  $p\in (0,1), r\in [0,1]$ with $p\neq r$ and $y\in(0,1)$. 
The process $\textbf{H}^{p,r}_{y}$ is a Coalescent Point Process associated with a BGW process with $(p_y, r_y)$-linear fractional distribution where $p_y:=1-y(1-p)$ and $r_y:=1-y(1-p)+r-p$. Moreover, the tail distribution of $H_{y,i}$, $i\ge 1$, is given by 
\begin{equation}
    \mathbb{P}(H_{y,i}>n)= \frac{r-p}{y(1-p)m^n- [y(1-p)-(r-p)]}, \qquad n\ge  0.
\end{equation}

