[Theorem 5 of arXiv:2609.01774, 'Hypoellipticity on time-periodic space-times'] Let $M$ be the interior of an asymptotically Euclidean manifold $X$, $\mathcal{M}=\Sb^1\times M$, $s\in\Nb$, 
$L$ as in \eqref{inhomog}, 
and $P\in\Psi^{r,\rho}_\cls(X)$ be elliptic, positive and self-adjoint, with order components $r,\rho>0$. Moreover,
let $\gamma_0=\frac{d}{\min\{r,\rho\}}$ and $\varepsilon$ be given by \eqref{eq:defeps}.
Fix $\alpha=-1$ and 

\begin{align*}
	&\beta>\gamma_0 s, \phantom{ + 1- s\varepsilon}\hspace*{5pt}\quad\text{if } s\varepsilon \ge1, \quad \text{or}
	\\
	&\beta>\gamma_0 s + 1- s\varepsilon,\quad \text{if } s\varepsilon<1.
\end{align*}

Then: 

\begin{enumerate}
    \item 
     For almost every $m \in[-1,1]$ there exists $C_m>0$ such that 
\begin{equation}
    \nm{u}_{L^2_{t,x}(\M)} \leq C_m \nm{(L -m) u}_{H^{\beta}_t L^2_x(\M)}.
\end{equation}

    \item For all $\ep>0$, there exists a set $\mathcal{A}_{\ep}$ with $\mu(\mathcal{A}_\ep) <\ep$ and $C_{\ep}>0$ such that for all $m \in [-1,1] \backslash \mathcal{A}_{\ep}$, we have the uniform upper bound
    \begin{equation}
        \nm{u}_{L^2(\M)} \leq C_{\ep}\nm{(L-m) u}_{H^{\beta}_t L^2_x(\M)} .
    \end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 5 of arXiv:2604.23572, '2604.23572'] In any work-conserving single-server queue satisfying
Assumptions~\ref{assumption-1} to \ref{assumption-3}, the first two
factorial moments, $f_0^{(1)}$ and $f_0^{(2)}$, of the lengths of busy
cycles in steady state are given by

\begin{eqnarray*}
f_0^{(1)} 
&=& \frac{1}{1-\rho} ,
\\
f_0^{(2)}
&=&
\frac{2 \rho}{(1-\rho)^2}
+ 
\frac{1}{(1-\rho)^3} \sum_{k \in K} \left(
2 \rho_k \E[\tilde{H}_k] 
+ \rho_k (\rho - \rho_k) 
+ \E[H_k]^2 \delta_k^{(2)} 
\right),
\end{eqnarray*}

where $\delta_k^{(2)}$ is given in (\ref{delta_k^2}). (Proof in the paper; no proof environment follows the statement in the TeX.)

