[Lemma res-pted-Quillen of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let $\alpha\colon G\to G'$ be a homomorphism of compact Lie groups. Then
    \[
        \alpha_!\colon\cat{$\bm G$-$\textbf{\textup{L}}$-Top}_*\rightleftarrows\cat{$\bm{G'}$-$\textbf{\textup{L}}$-Top}_*
	\nobreak
	\mspace{6mu plus 1mu}
	{:}
	\nonscript\mkern-\thinmuskip
	\mathpunct{}
	\mspace{2mu}
\alpha^*
    \]
    is a Quillen adjunction with homotopical right adjoint. If $\alpha$ is injective, then also
    \[
        \alpha^*\colon\cat{$\bm{G'}$-$\textbf{\textup{L}}$-Top}_*\rightleftarrows\cat{$\bm{G}$-$\textbf{\textup{L}}$-Top}_*
	\nobreak
	\mspace{6mu plus 1mu}
	{:}
	\nonscript\mkern-\thinmuskip
	\mathpunct{}
	\mspace{2mu}
 \alpha_*
    \]
    is a Quillen adjunction.
    \begin{proof}
        As $\alpha^*$ commutes with the functors forgetting the basepoint, and since weak equivalences, cofibrations, and fibrations are created by the forgetful functor, this is immediate from the corresponding unbased statements recorded as Lemmas~(lemma:restr-right-Quillen of the paper) and~(lemma:restr-inj-left-Quillen of the paper).
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 24 of arXiv:2605.31300, 'Cone-Additive Functions for Random Walks on Free Products of Graphs'] Assume that $\mathscr{R}>1$.
Then there exists a constant $\mathfrak{c}_{edges}>0$ such that
$$
\mathfrak{c}_{edges}=\lim_{n\to\infty} \frac{\mathbf{E}^{(r)}_{n}}{n}
=\lim_{n\to\infty} \frac{R_{\text{edges}}^{(r)}\bigl([X_0,\ldots,X_n]\bigr)}{n}
\quad \textrm{ almost surely.}
$$

[Lemma lem:st_cor_3 of arXiv:2411.14818, 'Scaling limits of solitons in the Box-Ball system'] Suppose that $\mathbf{q} \in \mathcal{Q}$ and ${\mathbb{E}}_{\nu_\mathbf{q}}\left[ {s_{\infty}\left(1\right)}^2 \right] < \infty$. Then for any $k, \ell \in {\mathbb{N}}$ with $k < \ell$ and $u, v \in {\mathbb{R}}$, we have 
                \begin{align}
                    &\lim_{n \to \infty} \frac{1}{n} \sigma^{\left( \left\lfloor n u \right\rfloor \right)}_{k,\ell}\left({\eta}, 0\right) = f_{k,\ell}\left(\mathbf{q}, u\right), \quad \nu_{\mathbf{q}}\text{-a.s.,} \\
                    &\varlimsup_{L \to \infty} \varlimsup_{n \to \infty}\nu_{\mathbf{q}}\left( \left| \frac{1}{n} \sigma^{\left( \left\lfloor n u \right\rfloor \right)}_{k,\ell}\left(0\right) - f_{k,\ell}\left(\mathbf{q}, u\right) \right| > \frac{L}{\sqrt{n}} \right) = 0 ,
                \end{align}
            and 
                \begin{align}
                    &\varlimsup_{L \to \infty} \varlimsup_{n \to \infty}\nu_{\mathbf{q}}\left( \left| \frac{1}{n} \sigma^{\left( \left\lfloor n u \right\rfloor \right)}_{k,\ell}\left(n^2\right) - \frac{1}{n} \sigma^{\left( \left\lfloor n v \right\rfloor \right)}_{k,\ell}\left(n^2\right) - f_{k,\ell}\left(\mathbf{q}, u - v\right)  \right| > \frac{L}{\sqrt{n}} \right) = 0, \\  
                \end{align}
            where 
                \begin{align}
                    f_{k,\ell}\left(\mathbf{q}, u\right) := \frac{\bar{\Xi}_{\ell - k}\left(\theta^{k}\mathbf{q}\right) \bar{J}_{k}\left(\mathbf{q}\right)u}{\bar{s}_{\infty}\left(\theta^{k}\mathbf{q}\right) \bar{J}_{\ell}\left(\mathbf{q}\right)}.
                \end{align}

