[Lemma lem:NM_kl of arXiv:2411.14818, 'Scaling limits of solitons in the Box-Ball system'] Assume that $\eta \in \Omega$. Then, for any $k,\ell \in {\mathbb{N}}$, $i \in {\mathbb{Z}}$ and $n \in {\mathbb{Z}}_{\ge 0}$, we have 
            \begin{align}
                \sum_{m = 1}^{n} N^{{i}}_{k,\ell}\left(\eta,m\right) = \sum_{j = X^{{i}}_{k - \ell}\left(\Psi_{\ell}\left(\tilde{\eta}\right), 0 \right) + 1}^{X^{{i}}_{k - \ell}\left(\Psi_{\ell}\left(\tilde{\eta}\right), n \right)} \zeta_{\ell}\left(\tilde{\eta},j\right),
            \end{align}
        and 
            \begin{align}
                M^{(i)}_{k}\left(\eta,n\right) = \sum_{m = 0}^{n-1} \left( 1 - r\left( T^{m}\Psi_{k}\left(\tilde{\eta}\right), J_{k}\left(\tilde{\eta}, i\right) \right) \right),
            \end{align}
        where
            \begin{align}
                J_{k}\left(\eta, i\right) := 
                \begin{dcases}
                    \min\left\{ j \in {\mathbb{Z}}_{\ge 0} \ ; \ \sum_{h = 0}^{j} \mathbf{1}_{\left\{ \zeta_{k}\left(\eta, h\right) > 0 \right\}} = i \right\} \ & \ i \ge 1, \\
                    - \min\left\{ j \in {\mathbb{Z}}_{\ge 0} \ ; \ \sum_{h = -j}^{-1} \mathbf{1}_{\left\{ \zeta_{k}\left(\eta, h\right) > 0 \right\}} = - i + 1 \right\}  \ & \ i \le 0.
                \end{dcases}
            \end{align} 
        In addition, 
                \begin{align}
                \sum^{J_{\ell}\left( \eta, \sigma^{(i)}_{k, \ell}\left(\eta, 0 \right) \right) - 1}_{j = J_{\ell}\left( \eta, \sigma^{(i)}_{k, \ell}\left(\eta, n \right) \right)} \zeta_{\ell}\left(\eta, j \right) 
                \le M^{(i)}_{k,\ell}\left(\eta,n\right) 
                \le \sum^{J_{\ell}\left( \eta, \sigma^{(i)}_{k, \ell}\left(\eta, 0 \right) \right)}_{j = J_{\ell}\left( \eta, \sigma^{(i)}_{k, \ell}\left(\eta, n \right) \right) - 1} \zeta_{\ell}\left(\eta, j \right),
            \end{align}
        where 
            \begin{align}
                \sigma^{(i)}_{k, \ell}\left(\eta, n\right) := \inf\left\{ j \in {\mathbb{Z}} \ ; \ X^{(j)}_{\ell - k}\left(\Psi_{k}\left(\tilde{\eta}\right), n \right) \ge J_{k}\left(\tilde{\eta}, i\right)  \right\}.
            \end{align}

