[Lemma lem:biggins-chernoff-block-count-exponent of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] Assume the minimal Kahane--Peyri\`ere regime. For \(a\in\mathbb R\) and \(n\ge1\), set
\begin{equation*}
N_n(a)=\#\{u\in\{0,1\}^{n}:Q_u\ge 2^{an}\}.
\end{equation*}
Then:
\begin{enumerate}
\item For every \(a\in\mathbb R\),
\begin{equation*}
\Lambda(a):=\lim_{n\to\infty}\frac1n\log_2\mathbb E N_n(a)
=
\inf_{q\ge0}
\left\{
1+\log_2\mathbb E(W^q)-qa
\right\},
\end{equation*}
where \(W^0:=\mathbf 1_{\{W>0\}}\), and for \(q>0\) the term is \(+\infty\) if \(\mathbb E(W^q)=+\infty\).

\item If \(a<1-A_{\mathrm{loc}}(W)\), then \(\Lambda(a)>0\).

\item The function \(\Lambda\) is finite and continuous on \((-\infty,1-A_{\mathrm{loc}}(W))\).
\end{enumerate}

[Prop eq:ST0_OP of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] For ${\gamma} > - d_1$, let ${\alpha} = {\gamma} + d_1 -1$. Define 

\begin{equation} 
 {\mathsf Q}_{\bm j, \ell, m}^n(\bm x,\bm y) = \bm T_{\bm j, n-m}^{({\boldsymbol{\kappa}}, \alpha+2m)}(\bm y) (1-|\bm y|)^m 
      {\mathsf Y}_{\ell}^m \left(\frac{\bm x}{1-|\bm y|}\right). 
\end{equation}
Then $\{{\mathsf Q}_{\bm j, \ell, m}^n: |\bm j| = n-m, \, 1 \le \ell \le \dim {\mathcal H}_m^{d_1}, \, 0 \le m  \le n, \bm j \in {\mathbb N}_0^{d_2}\}$ 
is an orthogonal basis of ${\mathcal V}_n({\mathbb S}^{d_1-1}\!\! \rtimes \triangle^{d_2}, {\mathsf W}_{{\gamma}, {\boldsymbol{\kappa}}}^\triangle)$. Moreover, 
the norm square of ${\mathsf Q}_{\bm j, \ell, m}^n$ 
is given by 
\begin{equation} 
   {\mathsf h}_{m,n}^{{\gamma},{\boldsymbol{\kappa}}}  
       =   \frac{\bm b^\triangle_{({\boldsymbol{\kappa}},\alpha)}}{\bm b^\triangle_{({\boldsymbol{\kappa}}, \alpha + 2m)}} \bm h_{\bm j,m}^{({\boldsymbol{\kappa}}, {\alpha}+ 2m), \triangle}
       = \frac{({\gamma} +d_1)_{2m}} {(|{\boldsymbol{\kappa}}|+ {\gamma} + d_1 + d_2)_{2m}} \bm h_{\bm j,m}^{({\boldsymbol{\kappa}}, {\alpha}+ 2m), \triangle}.  
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

