[Theorem main of arXiv:2507.10545, 'KPZ equation from a class of nonlinear SPDEs in infinite volume'] \fsp Suppose that in addition to Assumptions (assump:potential of the paper) and (assump:noneq of the paper), the following assumptions are satisfied.

\begin{enumerate}
\item For any $p\geq1$ and $\zeta>0$, we have the following moment estimates for some $\kappa_{p}>0$ and any $|\mathfrak{l}|\lesssim N$:

\begin{align}
\sup_{\x\in\Z}\E|\mathbf{Z}^{N}_{0,\x}|^{2p}\lesssim_{p}\exp(\tfrac{\kappa_{p}|x|}{N})\quad\mathrm{and}\quad\sup_{\x\in\Z}\E|\grad^{\mathbf{X}}_{\mathfrak{l}}\mathbf{Z}^{N}_{0,\x}|^{2p}\lesssim_{p,\zeta}N^{-p+p\zeta}|\mathfrak{l}|^{p-p\zeta}\exp(\tfrac{\kappa_{p}|x|}{N}).
\end{align}

\item The initial data {\small$\X\mapsto\mathbf{Z}^{N}_{0,N\X}$} converges locally uniformly in {\small$\X\in\R$} to some function {\small$\X\mapsto\mathbf{Z}_{0,\X}$} in probability.
\end{enumerate}

Then, there exists a coupling between {\small$\mathbf{Z}^{N}$} and the solution $\mathbf{Z}$ to (equation eq:she of the paper) with initial data {\small$\mathbf{Z}_{0,\cdot}$} from bullet point (2) above such that {\small$\mathbf{Z}^{N}_{\t,N\X}-\mathbf{Z}_{\t,\X}\to0$} locally uniformly on $[0,1]\times\R$ in probability in the large-$N$ limit. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma MMD-A-H of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] Let ${\varsigma _l}$ be the symmetric mollifier with the scale $l > 0$. Then
\begin{equation*}
{\left\| {f - f*{\varsigma _l}} \right\|_N} \lesssim {l^2}{\left\| f \right\|_{N + 2}} , \ \ \forall \, N \in {\mathbb{Z}^ + } \cup \left\{ 0 \right\} ,
\end{equation*}
and
\begin{equation*}
{\left\| {\left( {fg} \right)*{\varsigma _l} - \left( {f*{\varsigma _l}} \right)\left( {g*{\varsigma _l}} \right)} \right\|_N} \lesssim {l^{2 - N + M}}\left( {{{\left\| f \right\|}_{M + 1}}{{\left\| g \right\|}_1} + {{\left\| f \right\|}_1}{{\left\| g \right\|}_{M + 1}}} \right) , \ \ \forall \, N , M \in {\mathbb{Z}^ + } \cup \left\{ 0 \right\} .
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop_w_dim2 of arXiv:2606.27549, 'On Analytically Tractable Multidimensional Diffusions via Doob $h$-Transforms, with Resett'] Let the assumptions of Lemma (pos_eigenvalue of the paper) hold, and let the vector ${\bf r}=(r_1,r_2)$ satisfy 

\begin{equation}
 {\bf r}\cdot   A \cdot{\bf r}^\top=\left\{
    \begin{array}{ll}
      {\bf r} \cdot {\bf m}^\top,   & \text{if}\; \delta=0,\\
       \lambda,  & \text{if}\; \delta=1,
    \end{array}
    \right.

\end{equation}

where $\lambda$ is any of the positive eigenvalues of $M$. Then, 
a solution of Eq.\ ((2.5 of the paper)) for the process $\widehat{\bf X}_t$ with infinitesimal moments ((inf_mom_lin_bid of the paper)) is:

\begin{equation}
    h_c({\bf x})=1+c \int_0^{{\bf r}\cdot{\bf x}^\top} \exp \{-(2-\delta)z^{\delta+1}\}\ {\rm d}z= 
\left\{
\begin{array}{ll}
 1+c\exp\bigl\{-2\,{\bf r} \cdot {\bf x}^\top\bigr\},  & \text{if}\; \delta=0, 
 \\[2mm]
 1+c\,{\rm Erf}\bigl\{{\bf r}\cdot{\bf x}^\top\bigr\}, & \text{if}\; \delta=1,
\end{array}
\right. 

\end{equation}

where $\delta$ is given in Eq.\ ((delta of the paper)), and where $c\in (0,+\infty)$ if $\delta=0$, and $c\in (-1,0)\cup (0,1)$ if $\delta=1$.

