[Lemma 2 (Proposition 2.2 in \cite{Guan-Ma2003}) of arXiv:2609.02516, 'Power convexity of the torsion function on horo-convex domains in hyperbolic space'] Suppose that $W=(w_{\alpha\beta})$ is diagonal. For $k=1,2,\cdots,n$, we have
\begin{equation}}
\frac{\partial\sigma_k(W)}{\partial w_{\alpha\beta}}=\begin{cases}
\sigma_{k-1}(W|\alpha) & \mathrm{if}\ \alpha=\beta,\\
0 & \mathrm{if}\ \alpha\neq\beta,
\end{cases}
\end{equation}
and $$\frac{\partial^2\sigma_k(W)}{\partial w_{\alpha\beta}\partial w_{\gamma\delta}}=\begin{cases}
\sigma_{k-2}(W|\alpha\gamma) & \mathrm{if}\ \alpha=\beta,\gamma=\delta,\alpha\neq\gamma,\\
-\sigma_{k-2}(W|\alpha\gamma) & \mathrm{if}\ \alpha=\delta,\beta=\gamma,\alpha\neq\gamma,\\
0 & \mathrm{otherwise}.
\end{cases}$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 38 (Finite-time empirical $W_2$ bound from moving entropy) of arXiv:2608.28827, 'Quantitative Target Convergence and Uniform-in-Time\\ Propagation of Chaos for Langevin-Re'] Under Assumptions~\ref{ass:core-target}, \ref{ass:concentration},
\ref{ass:W2}, and \ref{ass:initial-T2},
\begin{equation}
    \E W_2^2(\mu_t^N,\mu_t)
    \le\frac{4C_t}{N}J_N(t)+2Cr_{N,d}
    \le C\left\{
       \frac{e^{L_{\mathrm{ent}}t}}{N}+r_{N,d}
    \right\}
    \le Cr_{N,d}e^{L_{\mathrm{ent}}t}, \qquad t \ge 0.
\end{equation}

[Lem 19 of arXiv:2604.06122, 'REM universality for linear random energy'] The function $G$ is continuous, twice differentiable, and verifies the following
\begin{enumerate}
\item $G(0)=G'(0)=0$;
\item $G''(\lambda)>0$ for any $\lambda\in \R$;
\item $\{G'(\lambda):\, \lambda \in \R_{> 0}\}= (0,\varsigma)$;
\item there exists a continuous and strictly increasing function $\hat \lambda:[0,\varsigma)\to \R_{\geq 0}$ such that
\been{

 G'(\hat \lambda(a))= a,\qquad \forall a\in [0,\varsigma).
}
Moreover $\hat\lambda(0)=0$ and $\hat\lambda((0,\varsigma))=\R_{> 0}$.
\end{enumerate}
The $\FLT$ $G^*$ satisfies
\begin{enumerate}
\setcounter{enumi}{4}
\item for any $a\in (0,\varsigma)$
\been{

G^*(a)=a \hat \lambda(a)- G(\hat \lambda(a)),\qquad \dot G^*(a)=\hat \lambda(a);
}
\item $G^*$ is strictly increasing in $[0,\varsigma)$;
\item $\{G^*(a):\, a\in (0,\varsigma)\}=(0,\gamma)$
\item there exists a continuous increasing function $\hat a:(0,\gamma)\to (0,\varsigma)$ such that
\been{

G^*(\hat a(c))=c,\quad \forall c\in (0,\gamma).
}
\end{enumerate}

[Lemma L:4th-Power-I22 of arXiv:2606.23865, 'Uniform-in-time Gaussian fluctuations for multiscale nonlinear stochastic systems via Mall'] Let $\Phi(x,y)$ and $\Xi(x,y)$ be the solutions of the first and second Poisson equations in (equation E:I2-Poisson-Eq of the paper). Then,
\begin{equation*}
\begin{aligned}
 \int_0^t e^{2\alpha s} & \Phi(X_s^\varepsilon, Y_s^\eta) \{c(X_s^\varepsilon, Y_s^\eta) - \bar{c}(X_s^\varepsilon) \} \thinspace ds = \int_0^t  e^{2 \alpha s} \mathscr{L}_y \Xi (X_s^\varepsilon, Y_s^\eta) \thinspace ds \\
 & \qquad \qquad = \eta \thinspace  e^{2 \alpha t} \Xi(X_t^\varepsilon,Y_t^\eta) - \eta  \Xi(X_0^\varepsilon,Y_0^\eta) - \eta \int_0^t 2 \alpha e^{2 \alpha s} \Xi(X_s^\varepsilon, Y_s^\eta) \thinspace ds \\
 & \qquad \qquad  - \eta  \int_0^t  e^{2 \alpha s} \Xi_x(X_s^\varepsilon, Y_s^\eta) c(X_s^\varepsilon, Y_s^\eta) \thinspace ds  - \eta  \sqrt{\varepsilon}\int_0^t  e^{2 \alpha s} \sigma(X_s^\varepsilon) \Xi_x(X_s^\varepsilon, Y_s^\eta) \thinspace dW_s^1\\
 & \qquad \qquad  - \frac{\eta}{\sqrt{\eta}}\int_0^t e^{2 \alpha s} \tau(Y_s^\eta) \Xi_y(X_s^\varepsilon, Y_s^\eta) \thinspace dW_s^2 - \frac{\varepsilon \eta}{2} \int_0^t  e^{2 \alpha s} \sigma^2(X_s^\varepsilon) \Xi_{xx}(X_s^\varepsilon, Y_s^\eta) \thinspace ds.
\end{aligned}
\end{equation*}

