[Prop 9 of arXiv:2609.03819, 'Stochastic damped wave and Euler-Bernoulli equations with singular locally H\"older contin'] Assume that Hypotheses \ref{H0}, \ref{H0.5} and \ref{H1} hold and let $\vartheta\in [0,1)$. For every $n\in\N$,  $\varphi\in C_b^\vartheta(H_n)$, $t>0$ and $x,h,k\in H_n$ we have
\begin{align}
&|\scal{\nabla(R_n(t)\varphi)(x)}{h}_{H_n}|\leq \|e^{tA_n}h\|_{H_n}^\vartheta \|\Gamma_{t,n}h\|^{1-\vartheta}_{H_n}\|\varphi\|_{C^\vartheta_b(H_n)},\\
&|D^2(R_n(t)\varphi)(x)(h,k)|\leq 2^{(1-\vartheta)/2}\|e^{tA_n}k\|_{H_n}^\vartheta\|\Gamma_{t,n}k\|_{H_n}^{1-\vartheta}\|\Gamma_{t,n}h\|_{H_n}\|\varphi\|_{C^\vartheta_b(H_n)},
\end{align}
where we set $C^0_b(H_n)=C_b(H_n)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 208 of arXiv:2601.16377, '2601.16377'] Let $p_1(z),\ldots,p_H(z)$ be polynomials of degree (at most) $H-1$, such that
 \begin{equation}

  \oint_{\gamma_h} \frac{p_g(\zeta)}{\sigma(\zeta)} \frac{\dd \zeta}{2\ii\pi}= \delta_{g,h}.
 \end{equation}
 Consider the integral operator $\mathcal{P}^H:\mathscr{L}^2(\gamma^+) \longrightarrow \mathscr{L}^2(\gamma^+)$ given by $\displaystyle f \longmapsto \oint_{\gamma^+} f(w)\, \dfrac{ P^H(z,w)}{2\ii\pi}\dd w$, where
 \begin{equation}

 P^H(z,w)= \frac{p_h(z)}{\sigma(z)},\quad \textnormal{ for } w\in \gamma_h^+, \quad h\in [H].
 \end{equation}
 Then for any polynomial $f(z)$ of degree at most $H-1$, we have
 \begin{equation}

 \mathcal P^H \left[\frac{f}{\sigma}\right](z)=\frac{f(z)}{\sigma(z)}.
 \end{equation}
 Further, for any $f\in \mathscr{L}^2(\gamma^+)$ with vanishing integrals around each $\gamma_h$, $h\in[H]$, we have $\mathcal P^H f=0$.

[Theorem 3 (Halfspace theorem for globally minimizing boundaries) of arXiv:2609.03916, 'Halfspace Theorems for Anisotropic Minimal Surfaces and Perimeter Minimizers'] Let $\Phi$ satisfy
\eqref{old-eq:regularity-bounds}--\eqref{old-eq:ellipticity}, without any evenness
assumption, and let $E\subset\R^{n+1}$ be a global $\Phi$-perimeter minimizer.  If
\begin{equation}
 \varnothing\ne\supp |D\chi_E|
 \subset\{x\cdot e\ge c\}
\end{equation}
for some $e\in\mathbb S^n$ and $c\in\R$, then $E$ agrees almost
everywhere with a halfspace.  In particular, $\supp |D\chi_E|$ is an affine
hyperplane. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem random variables of arXiv:2608.18045, 'Supercritical sharpness for the random cluster representation of real-valued spin models'] Let $X_1,\ldots, X_n$ be integrable real-valued random variables on a probability space $(\Omega, \mathcal F, \mathbb P)$. Let $S_n= X_1 + \ldots +X_n$. 
Assume the following.
\begin{enumerate}
    \item[(i)] There exists $a\in\mathbb R$ such that $\mathbb E[X_i] \geq a$ for every $1 \leq i \leq n$.
    \item[(ii)] There exist $M\geq \max\{a,0\}$ and $\delta > 0$ such that $\mathbb E[X_i \mathbbm{1}_{X_i>M}]\leq \delta$ for every $1 \leq i \leq n$.
\end{enumerate}
Then,
\begin{equation}
    \mathbb P[S_n \geq (a-2\delta)n]\geq \delta':=\frac{\delta}{M-a+2\delta}.
\end{equation}

