body:
[Theorem 28 (Weighted centered layer theorem) of arXiv:2605.11451, '2605.11451'] Let $1/2<\alpha<1$ and $\delta\ge3\alpha$. For every $B>0$ and $L>0$,
\begin{equation}
 LB\sum_{|G|=L}\frac{(1-s^p)^{\delta+\alpha}}{|G'(s)|}
 +LB\sum_{H=L}\frac{(1-s^p)^{\delta+\alpha}}{|H'(s)|}
 \ge
 \int_{\{|G|<L<H\}}s(1-s^p)^\delta\,\dd s.
\end{equation}
Endpoint roots and tangencies are interpreted by limits. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 13 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $K \in \mathcal{C}^n$ and let $L \in \mathcal{B}(\R^n)$ be non-empty. Define $M(K,L) = \sup_{x\in K, y\in L} \langle x, y \rangle$. Then,
    \begin{enumerate}
        \item If $L$ is unbounded, then $M(K,L)=\infty$.
        \item If $L$ is bounded, then $0\leq M(K,L)<\infty$ and $L\subseteq M(K,L)K^\circ$. Moreover, one has $M(K,L)=0$ if and only if $L=\{o\}$.
    \end{enumerate}

[Lemma lemma2-3 of arXiv:2609.00627, 'Global well-posedness of radially symmetric strong solutions to two-dimensional compressib'] Let $\Omega$ be a bounded Lipschitz domain in $\mathbb{R}^2$. Then,  for any $ q>2$, there are positive constants $C_1, C_2$ depending on $q$ and $\Omega$, such that for any functions $\boldsymbol{u},\boldsymbol{v}:\Omega\rightarrow\mathbb{R}^2$ with $\boldsymbol{u}\in H^1(\Omega)$ and $\boldsymbol{v}\in W^{1,q}(\Omega)$,
	\begin{equation}
		\|\boldsymbol{u}\|_{L^q(\Omega)}\leq C_1\|\boldsymbol{u}\|_{L^2(\Omega)}^\frac{2}{q}\|\nabla\boldsymbol{u}\|_{L^2(\Omega)}^{1-\frac{2}{q}}+C_2\|\boldsymbol{u}\|_{L^2(\Omega)}
	\end{equation}
	and
		\begin{equation}
		{\Vert \boldsymbol{v} \Vert}_{L^\infty(\Omega)} \le C_1{\Vert \boldsymbol{v} \Vert}_{L^2(\Omega)}^{\frac{q-2}{2q-2}}{\Vert \nabla \boldsymbol{v} \Vert}_{L^q(\Omega)}^{\frac{q}{2q-2}}+C_2\|\boldsymbol{v}\|_{L^2(\Omega)}. 
	\end{equation}
	Furthermore, if $ \boldsymbol{u}\cdot\boldsymbol{n}|_{\partial \Omega}=\boldsymbol{v}\cdot\boldsymbol{n}|_{\partial \Omega}=0\text{ or } \int_{\Omega} u_i dx=\int_\Omega v_i=0$ with $i=1,2$, then $C_2=0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

