body:
[Proposition 71 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $Y$ be a continuous $\bbr^{m \times d}$-valued process, and let $Y'$ be a continuous $\bbr^{m \times d \times d}$-valued processes such that $(Y,Y') \in \scrd_X^{2 \alpha}([0,T],\bbr^{m \times d})$ on $N_1^c$. Then the following statements are true:
\begin{enumerate}
\item The $\bbr^m$-valued rough integral
\begin{align*}
\int_0^T Y_s \, d \mathbf{B}^{\text{\rm It\^o}}_s = \lim_{|\Pi| \to 0} \sum_{[u,v] \in \Pi} ( Y_u B_{u,v} + Y_u' \bbb_{u,v}^{\text{\rm It\^o}} )
\end{align*}
exists on $N_1^c$.

\item If $Y$ and $Y'$ are adapted and bounded, then there is a $\bbp$-nullset $N$ with $N_1 \subset N$ such that
\begin{align*}
\int_0^T Y_s \, d \mathbf{B}^{\text{\rm It\^o}}_s = \int_0^T Y_s \, dB_s \quad \text{on $N^c$.}
\end{align*}
\end{enumerate}

[Prop thm2.2 of arXiv:2411.11408, 'Multidimensional specific relative entropy between continuous martingales'] We have:
\begin{equation*}\begin{split}  
h_l(\mathbb{Q}^a|\mathbb{B})&=\textstyle \frac{1}{2}\int _0^1\big(
tr(G(s)) -l -\log (\det G(s))\big)ds =\sup _{n\in \mathbb{N}} \frac{1}{n} H(\mathbb{Q}^a|\mathbb B)|_{\mathcal{F}^n} \in [0, \infty],
\end{split} \end{equation*}
and $\frac{1}{n}\log(\frac{d\mathbb{Q}^a}{d\mathbb{B}})|_{\mathcal{F}^n}\xrightarrow{L^1(\mathbb{Q}^a)} \frac{1}{2}\int _0^1 \big( tr(G(s))-l-\log(\det G(s)) \big) ds$ if the latter is finite.

