    \begin{equation}
        \d \nu_{S,AB}(x)=Z^{-1}_{S,AB}q(x)\overleftarrow{q}(x)\rho(x)\d\sigma_S(x),
    \end{equation}
    where 
    $$Z_{S,AB}=\int_{S}q(x)\overleftarrow{q}(x)\rho(x)\d\sigma_S(x).$$

