[Proposition 60 of arXiv:2506.10494, 'Geometric Jensen-Shannon Divergence Between Gaussian Measures On Hilbert Space'] Let $\Ncal(m_i,C_i) \in \Gauss(\Hcal, \mu_{*})$. Let
	$m_{\alpha}\in \Hcal, C_{\alpha}\in \Sym(\Hcal)\cap\Tr(\Hcal)$ be defined as in Theorem \ref{theorem:geometric-interpolation-equivalent-Gaussian-Hilbert-space}.
	Let $C_{\alpha,\gamma}$ be defined as in Eq.\eqref{equation:C-alpha-gamma}. Then

	\begin{align}
		\lim_{\gamma \approach 0^{+}}||C_{\alpha,\gamma}^{-1/2}(m_i - m_{\alpha})|| = ||C_{\alpha}^{-1/2}(m_i - m_{\alpha})||, \;\; i=0,1.
	\end{align}

[Lemma 20 of arXiv:2606.17501, 'Critical spectral behavior and large deviations for geometric $\alpha$-stable processes'] The critical coupling constant $\theta_{c}$ is characterized
  as the unique positive number such that
  \begin{align}

    \inf \left\{ \cE^{\alpha}(u,u) : u \in \cF_{e}^{\alpha}, \ \theta_{c} \int_{\bR^{d}} u^{2} d\mu = 1 \right\} = 1.
  \end{align}

