\begin{align*}
\mathbb{E}\Phi(S_x + u\mathscr{E}) &= \mathbb{E}\left[\int_0^\infty \Phi(S_x + ut)e^{-t} \mathrm{d} t \right]\\
&= \mathbb{E}\left[-\Phi(S_x + ut)e^{-t}\Big|_{t=0}^\infty + \int_0^\infty u\Phi'(S_x + ut)e^{-t} \mathrm{d} t\right] \\
