\begin{equation}
\max_{-1\le x\le1}
(1-x)^{\alpha+1/2}(1+x)^{\beta+1/2}\bigl|p_n^{(\alpha,\beta)}(x)\bigr|^2
<3\alpha^{1/3}\Bigl(1+\frac\alpha n\Bigr)^{1/6}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 21 of arXiv:2607.21392, 'Gaussian Convexity Principles for Sharp Moderate Deviations of Gaussian Maxima and Critica'] There exists a universal constant $C<\infty$ such that the following holds for all $N\ge 1$ and all $\lambda\in[0,1]$.
\begin{equation}
p_N(\lambda)=\gamma + \varepsilon_N(\lambda),
\end{equation}
where $|\varepsilon_N(\lambda)|\le C\gamma^2.$ In particular, for $\lambda\in[\lambda_0,1]=[1-N^{-1/3},1],$ there exists a universal constant $A<\infty$ such that
\begin{equation}
p_N(\lambda)\le \frac1N + A N^{-4/3}.
\end{equation}

[Theorem thm: moment lb of arXiv:2411.09614, 'Moment estimates for the stochastic heat equation on Cartan-Hadamard manifolds'] Fix $\alpha>\frac{n-2}{4},\beta>0$. Let $p\geq 2$ be an integer. For any $x\in M,R>0$ if $u_0$ is bounded, $u_0\geq \varepsilon>0$ in $B(x,R)$ and $\sec_M\geq -K_2>-\infty$, we have for $0<r\leq R$ \begin{equation}
        \mathbb{E}[\abs{u(t,x)}^p]\geq C \varepsilon^p\exp\left\{\max \left[\left(Q(r),C\right)\right]pt\right\}
    \end{equation}
    where $Q(r):=\beta^2(p-1)\overline{G}_{2\alpha}(r)-\frac{c}{r^2}-C$, $c,C>0$ depend on $\alpha,n,K_2$ and $R$, and $\overline{G}_\alpha(\cdot)$ is the function defined in Lemma (Lower Bound for correlation of the paper). In particular, if $R=+\infty$, we have 
    \begin{equation}
        \liminf_{t\uparrow+\infty,x\in M} \frac{\ln \mathbb{E}[\abs{u(t,x)}^p]}{t}\geq p\max\left(\sup_{0<r<+\infty}Q(r),C\right).
    \end{equation}

[Proposition 67 (Asymptotic series) of arXiv:2605.14630, '2605.14630'] For every $n\geqs0$ there exists a constant $M_n$ such that the ratio of partition 
functions satisfies 
\begin{equation}

 \biggabs{\frac{\cZ_{1,\alpha}}{\cZ_{1,0}}
 - \sum_{m=0}^n \frac{(-\alpha)^m}{m!}
 \biggexpecin{\mu_{1,0}}{\biggpar{\int_{\Lambda}\Wick{\phi(x)^4}\6x}^m}}
 \leqs M_n \alpha^{n+1}\;.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 18 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $f\in \mathscr{C}^{\infty}(\mc{T}_{\A{1},\A{2}})$ and recall that $c_{n,m}(f)$ is defined by \eqref{Coeffs de Fourier en les deux variables}. Then, for all $k\in \N$, $n,m\in \Z^d$,
    \begin{equation}
        c_{n,m}(f)=\mc{O}_k(1)(\A{1}\A{2})^{d/2}\jap{(n,m)}^{-k}\sum_{\bb{\beta}+\bb{\gamma}\leq k}\A{1}^{-\bb{\beta}/2}\A{2}^{-\bb{\gamma}/2}\norme{\partial_x^\beta\partial_\xi^\gamma f}_{L^1(\mc{T}_{\A{1},\A{2}})}.
    \end{equation}
    In particular, if $0<\A{1}\leq\A{2}\leq 1$, then \eqref{Estimation des coeffs de Fourier en les deux variables - 1} becomes
    \begin{equation}
        c_{n,m}(f)=\mc{O}_k(1)\A{1}^{(d-k)/2}\A{2}^{d/2}\jap{(n,m)}^{-k}\sum_{\bb{\beta}+\bb{\gamma}\leq k}\norme{\partial_x^\beta\partial_\xi^\gamma f}_{L^1(\mc{T}_{\A{1},\A{2}})}.
    \end{equation}

