[Thm 119 of arXiv:2507.08909, 'Annealed almost periodic entropy'] Let $\pi$ be a separable representation of $\G$.
\begin{enumerate}
\item[a.] If $\pi$ is cyclic and disjoint from $\l$, and if $\rmh^0(\pi) > -\infty$, then for every $\eps > 0$ there is a representation $\rho$ on $H_\pi\oplus H_\l$ such that $\rho \simeq \l$ and
\begin{equation}
\sum_{s \in S\cup S^{-1}}\|(\pi\oplus \l)(s) - \rho(s)\|^2_{\rm{HS}} \le 4(\eps - \rmh^0(\pi)).
\end{equation}
\item[b.] If $\rmh^0(\pi) > -\infty$, then $\pi$ is contained in a Hilbert--Schmidt perturbation of an inflation of $\l$.
\item[c.] If $\rmh^0(\pi) = 0$, then $\pi \lesssim_{\rm{a}} \l$.
\end{enumerate}

