[Theorem MainThm: lower_bound_alpha_ge_d of arXiv:2608.00399, 'The Heavy-tailed Frog Model'] Let $d \ge 1$. Assume $Q$ is a symmetric, translation-invariant, and heavy-tailed transition matrix on $\mathbb Z^d$ with exponent $\alpha > d$. Consider the frog model on \( \mathbb Z^d \) equipped with $Q$. For any $\varepsilon \in (0, 1)$, there exists a positive constant $c = c(Q, \lambda, \ell, \varepsilon)$ such that 
\begin{align*}
    \mathbb P\left( \text{for } \forall L > 0, \mathcal{A}(cL) \subseteq B(L), \frac{|\mathcal{A}(cL)|}{L^d} < \varepsilon \right) \ge 1 - \varepsilon,
\end{align*}
where $B(L) := [-L, L]^d \cap \mathbb Z^d$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 8 of arXiv:2606.14812, 'Joint convergence in Wiener chaos via transport hierarchy and Malliavin covariances'] Let $p\geq 2$ be an integer and let $ (X_{N}= I_{p} (f_{N}), N\geq 1)$ with $f_{N}\in H^{ \odot p}$ for every $N\geq 1$. Assume that $(X_{N}, N\geq 1)$ satisfies (\ref{c1}). Let $ (\mathbb{Y}_{N}= (Y_{1,N},..., Y_{d, N}), N\geq 1)$ such that for every $j=1,..., d$, 
		\begin{equation}
			Y_{j, N}= \sum _{q=1}^{N_{0, j}}I_{q} ( g_{q, N} ^{(j)}), \mbox{ with } g_{q, N}^{(j)} \in H ^{\odot q}.
		\end{equation}
		Assume (\ref{c4}), which is equivalent to 
		\begin{equation}

			\mathbf{E}\left[ X_{N} I_{p}(g ^ {(j)}_{p,N})\right]\to _{N \to \infty} \rho _{j}, \mbox{ for } j=1,...,d.
		\end{equation} Then
		\begin{enumerate}
			\item If $\mathbb{Y}_{N} \to _{N \to \infty} \mathbb{Y}$ in $ L^{2}(\Omega)$, then 
			\begin{equation*}
				(X_{N}, \mathbb{Y}_{N})\to \xrightarrow[N\to\infty]{(d)} (Z, \mathbb{Y}),
			\end{equation*}
			where $Z\sim N(0, \sigma ^{2})$ and the characteristic function of the random vector $(Z, \mathbb{Y})$ is given by (\ref{phi}). 
			\item If $\max_{j=1,..., d}N_{0, j}\leq p$ and $ \mathbb{Y}_{N} \xrightarrow[N\to\infty]{(d)} \mathbb{Y}$,  then 
			\begin{equation*}
				(X_{N}, \mathbb{Y}_{N})\xrightarrow[N\to\infty]{(d)}  (Z, \mathbb{Y}),
			\end{equation*}
			where $Z\sim N(0, \sigma ^{2})$ and the characteristic function of the random vector $(Z, \mathbb{Y})$ is given by (\ref{phi}). 
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

