body:
[Lemma convsubs of arXiv:2609.02213, 'Invariant subspaces for free linearizations of Lipschitz maps'] Let $(M,e)$ be a pointed metric space. Let $p\in\mathbb{N}$ and let $a_1,\ldots,a_p\in\mathbb{K}$ be such that $\sum_{i=1}^p a_i = 0$ and
		\begin{equation} 
			\sum_{i\in J}a_i\neq 0,
			\qquad \forall J\subset\{1,\ldots,p\},\; \emptyset \neq J \subsetneq \{1,\ldots, p\}.
		\end{equation}
		For $1\leq k\leq p$, let $(x_k(n))_n$ be sequences in $M$, and set $\gamma_n:=\sum_{k=1}^p a_k\delta(x_k(n))$.
		If $(\gamma_n)_n$ has a weakly convergent subsequence with limit $\gamma=\sum_{k=1}^q b_k\delta(y_k) \neq 0$,
		where $1\leq q\leq p$ and $b_k\neq 0$, then, after passing to a further subsequence,
		\begin{enumerate}
			\item Each $y_k$ is the limit of at least one of the sequences $(x_m(n))_n$;
			\item If $(x_m(n))_n$ does not converge to some $y_k$, then it converges to $e$.
		\end{enumerate}
		In particular, the subsequence converge to $\gamma$ in norm.

[Corollary cor:bspa of arXiv:2411.18749, 'A star is born: Explosive Crump--Mode--Jagers branching processes'] Let $s$ satisfy~(equation eq:gsass of the paper) and Assumption~(ass:s of the paper), and suppose that 
	\begin{equation} 
	\lim_{n\to\infty}\frac{\mu_{  (\log(n)\mu_n^{-1})^{1/\beta}}}{\mu_n}=\infty,
	\end{equation}  
	where $\beta$ is as in Assumption~(ass:s of the paper). Then, the limiting infinite tree $T_\infty$ contains a unique vertex with infinite degree and no infinite path, almost surely. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:Laplace.polynomial.calculus of arXiv:2606.04859, 'Stein's method for the Wishart distribution'] Let $m\in \mathbb{N}$, $\alpha > d-1 + 2m$, and $\Theta\in \mathcal{S}_{+}^d$. Then, for all $T\in \mathcal{S}_{+}^d$ and all index pairs $(i_{\ell}, j_{\ell})\in [d]^2$,
\begin{equation}
\mathcal{L}\left[\left(\prod_{\ell=1}^m \nabla_{i_{\ell} j_{\ell}}\right) f_{\alpha, I_d, \Theta}^{\mathcal{W}}\right](T)
= \left(\prod_{\ell=1}^m T_{i_{\ell} j_{\ell}}\right)\mathcal{L}[f_{\alpha, I_d, \Theta}^{\mathcal{W}}](T).
\end{equation}
More generally, if $P(U)$ is a scalar polynomial of degree at most $m$ in the entries of a symmetric $d\times d$ matrix $U$, and $P(\nabla)$ denotes the differential operator obtained by replacing $U_{ij}$ by $\nabla_{ij}$, then
\begin{equation}
\mathcal{L}[P(\nabla) f_{\alpha, I_d, \Theta}^{\mathcal{W}}](T) = P(T) \, \mathcal{L}[f_{\alpha, I_d, \Theta}^{\mathcal{W}}](T).
\end{equation}

