body:
[Corollary of arXiv:2411.09257, 'Iterated Generalized Counting Process and its Extensions'] The pmf of multivariate IGCP has following equivalent form:
\begin{equation*}
\hat{p}_{\bar{\mathcal{M}}}(\bar{n},t)=\sum_{\substack{\Omega(k_i,n_i)\\i=1,2,\dots,q}}\Big(\prod_{i=1}^{q}\prod_{j_i=1}^{k_i}\frac{(\lambda_{ij_i})^{n_{ij_i}}}{n_{ij_i}!}\Big)\sum_{\sum_{j_{0}=1}^{k_0}r_{j_{0}}=z_{k}}z_{k}!\Big(\prod_{j_0=1}^{k_0}\frac{j_0^{r_{j_{0}}}}{r_{j_{0}}!}\Big)\prod_{j_0=1}^{k_0}\mathcal{B}_{r_{j_0}}(\mu_{j_0}te^{-j_0\Lambda})e^{\mu_{j_0}te^{-j_0\Lambda}},
\end{equation*}
where $\mathcal{B}_n(x)$ is the $n$th order Bell polynomial. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 37 of arXiv:2608.15914, 'Absorption cutoff and stationary singularities for rounded Gaussian random dynamical syste'] Let \cref{ass:gaussian-stable-selected} hold. Let $q_N\to q_0$ with
  $q_N>0$, let $\nu_{A,N}$ be the unique nonzero invariant law of
  $K_{A,N}$, and let
  $(Z_t^{(N)},\widetilde Z_t^{(N)})$ be the synchronous coupling driven by the
  same Gaussian vectors, with $Z_0^{(N)}=q_N$ and
  $\widetilde Z_0^{(N)}\sim\nu_{A,N}$. Then there is a constant $C<\infty$
  such that, for every $c\geq0$,
  \begin{equation}
    \limsup_{N\to\infty}
    \sqrt N\,
    \Ee\abs{
      Z_{\pospart{n_N(c)-1}}^{(N)}
      -
      \widetilde Z_{\pospart{n_N(c)-1}}^{(N)}
    }
    \leq
    C\mu_A^c .
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:contraction of arXiv:2608.22765, 'Learning to Control Coupled-Dynamics Environments with Joint Markov Decision Processes'] Every deterministic stationary policy $\pi$ induces a map $\mathcal T^\pi:\mathcal E_p\to\mathcal E_p$. For all $\eta,\zeta\in\mathcal E_p$,
\begin{equation}
D_p(\mathcal T^\pi\eta,\mathcal T^\pi\zeta)\le\gamma D_p(\eta,\zeta).
\end{equation}

[Lemma 147 (Monotonicity of $x^1$) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] The following identity holds:
		\begin{align}
			\nullgeop{u}x^1 \eqdef \left\{ \ReciprocaluLunitAppliedtoTimeFunction L^1 + \upmu X^1 + \MagnitueofinnerproductofnewLandnewuL  \frac{\angD^A \ubar X^A}{X^1} \right\} + \left\{ L^A + \upmu X^A - \MagnitueofinnerproductofnewLandnewuL \angD^A \ubar\right\} \left\{ \frac{X^A}{X^1} + L^1 \frac{\geop{x^A}\ubar}{\geop{t} \ubar} + \frac{L^B X^B \geop{x^A} \ubar}{X^1 \geop{t} \ubar}\right\}. 
		\end{align}
	Moreover, the following estimate holds on $\characteristicdiamondtwoarg{[\leftubar,\ubarboot]}{[\moreinterestingu_1,\moreinterestingu_2]}$:
		\begin{align}
			\nullgeop{u} x^1 = - \frac{1}{2}\upmu \left\{ 1 + \mathcal{O}_{\mydiam}(\mathring{\upalpha})
				\right\}.   
		\end{align}
	Finally, for every fixed $[\ubar,x^2,x^3] \in [\leftubar,\ubarboot]\times\T^2$, the map $\ubar \mapsto x^1(\ubar,u,x^2,x^3)$ is strictly decreasing on $[\moreinterestingu_1,\moreinterestingu_2]$.

[Lemma 10 of arXiv:2607.22438, 'A deterministic scalar reduction for the phase transition in two interacting urns'] Fix \(z\in(1/2,3/4)\). Assume that
\begin{equation*}
 x_p(z)=2z-q_p(z)\in\left(0,\frac12\right).
\end{equation*}
Then one has
\begin{equation*}
 \frac{\partial}{\partial p}\Phi_p(z)>0.
\end{equation*}

