[Lemma lma:antidiag of arXiv:2608.26564, 'Real ideal points, Conway spheres, and left-orderable Dehn fillings'] In the ordered bases $(\mathcal P_i, \mathcal L_i)$, we have $J = \mathrm{red}(\widehat R) = \omega E_{12}$, for some $\omega \in \mathbb{R}^\times$. After multiplying the normalizers $C_i$ by elements reducing to the identity and rescaling, the relative conjugator can be represented by 
\begin{equation*}
	S_\theta = \begin{pmatrix}0&1 \\ -\theta & 0\end{pmatrix} \ \ \ \ \ \theta \in \mathfrak m_K
\end{equation*}
where $\theta(u) > 0$ for every sufficiently small $u$.

[Proposition 9 of arXiv:2608.27433, 'Scalar curvature on K\"ahler blow-ups and systolic inequalities'] The following estimates hold uniformly for small $\eps$.
\begin{enumerate}[label=\textup{(\roman*)}]
\item If $k>2$ and $4-2k<\delta<0$, then
\begin{equation}
  \norm{S(\omega_\eps)-\pi^*S(\omega)}
  _{C^{0,\alpha}_{\delta-4}}
  \le C\Theta_\eps,
\end{equation}
where \(\Theta_\varepsilon=r_\varepsilon^{3-\delta}+\varepsilon^{2k-2}r_\varepsilon^{4-\delta-2k}\). Moreover,
\begin{equation}
  \Theta_\varepsilon\to0
  \qquad\text{and}\qquad
  \varepsilon^{\delta-2}\Theta_\varepsilon\to0
  \qquad\text{as }\varepsilon\to0.
\end{equation}
\item If $k=2$ and $-1<\delta<0$, then
\begin{equation}
  \norm{S(\omega_\varepsilon)
  -
  \pi^*S(\omega)
  -
  \varepsilon^2 h_S}_{C^{2,\alpha}_{\delta-4}}
  \le Cr_\eps^{4-\delta},
\end{equation}
where \(h_S\) is defined as in Lemma \ref{k2:lem:Green-correction}. Moreover,
\begin{equation}
  r_\varepsilon^{4-\delta}\to0
  \qquad\text{and}\qquad
  \varepsilon^\delta r_\varepsilon^{4-\delta}\to0
  \qquad\text{as }\varepsilon\to0.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 145 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Fix $h>0$ and a base point ${\hat x}_0\ge 0$. Let ${\hat x}_1={\hat x}_1^{[M]}$ be chosen so that
	\begin{align*}
		U_{h;M,Q}'({\hat x}_0)=U_{h;0,0}'({\hat x}_1)
	\end{align*}
	(suppressing from the notation the dependence of $\hat{x}_1$ on $\hat{x}_0$ and $Q$.)
		The choice $M=-2{\hat x}_0-\eta$, for sufficiently small $\eta>0$, has the following property: for each fixed $h'\in(0,h]$, there is a constant
		$c=c(h',h,{\hat x}_0)>0$, such that
		\begin{align}
			\partial_hU_{h';M,Q}({\hat x}_0)-\partial_hU_{h';0,0}({\hat x}_1^{[-2 {\hat x}_0-\eta]})
			\ge cQ\eta.

		\end{align}
                For $0<\varepsilon<h$ one has $\inf\{ c(h',h,{\hat x}_0):h'\in [\varepsilon,h]\}>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 18 of arXiv:2609.03634, 'Joint Laws of Maximum Drawdown and Maximum Drawup for Spectrally Negative L\'{e}vy Process'] For any $\alpha,\beta>0$,
\[
\begin{aligned}
&\mathbb{P}\left(M_T^-<\alpha,\,M_T^+<\beta\right)\\
&=\begin{cases}
\displaystyle
\int_0^\alpha
\left\{
\frac{\left(Z^{(\gamma)}(r)-1\right)^2
\left[\left(W^{(\gamma)\prime}(r)\right)^2-W^{(\gamma)}(r)W^{(\gamma)\prime\prime}(r)\right]}
{\gamma\left(W^{(\gamma)}(r)\right)^3}
+
\frac{\left[
\gamma W^{(\gamma)}(r)-\left(Z^{(\gamma)}(r)-1\right)
\dfrac{W^{(\gamma)\prime}(r)}{W^{(\gamma)}(r)}
\right]^2}
{\gamma W^{(\gamma)}(r)}
\right\}\,dr
\\[3mm]
\displaystyle\qquad+
\frac{\left[
\gamma W^{(\gamma)}(\alpha)-\left(Z^{(\gamma)}(\alpha)-1\right)
\dfrac{W^{(\gamma)\prime}(\alpha)}{W^{(\gamma)}(\alpha)}
\right]^2}
{\gamma W^{(\gamma)\prime}(\alpha)}
\left[
1-\exp\left\{-(\beta-\alpha)\frac{W^{(\gamma)\prime}(\alpha)}{W^{(\gamma)}(\alpha)}\right\}
\right],
&0<\alpha\leq\beta,
\\[10mm]
\displaystyle
\int_0^\beta
\left\{
\frac{\left(Z^{(\gamma)}(r)-1\right)^2
\left[\left(W^{(\gamma)\prime}(r)\right)^2-W^{(\gamma)}(r)W^{(\gamma)\prime\prime}(r)\right]}
{\gamma\left(W^{(\gamma)}(r)\right)^3}
+
\frac{\left[
\gamma W^{(\gamma)}(r)-\left(Z^{(\gamma)}(r)-1\right)
\dfrac{W^{(\gamma)\prime}(r)}{W^{(\gamma)}(r)}
\right]^2}
{\gamma W^{(\gamma)}(r)}
\right\}\,dr
\\[3mm]
\displaystyle\qquad+
\frac{\left(Z^{(\gamma)}(\beta)-1\right)^2
\left[Z^{(\gamma)}(\beta)W_+^{(\gamma)\prime}(\beta)-\gamma\left(W^{(\gamma)}(\beta)\right)^2\right]}
{\gamma\left(W^{(\gamma)}(\beta)\right)^3}
\int_\beta^\alpha
\exp\left\{-(r-\beta)\frac{W_+^{(\gamma)\prime}(\beta)}{W^{(\gamma)}(\beta)}\right\}
\frac{\left(W^{(\gamma)\prime}(r)\right)^2-W^{(\gamma)}(r)W^{(\gamma)\prime\prime}(r)}
{Z^{(\gamma)}(r)W_+^{(\gamma)\prime}(r)-\gamma\left(W^{(\gamma)}(r)\right)^2}\,dr,
&0<\beta\leq\alpha.
\end{cases}
\end{aligned}
\]

