[Theorem thm_var_formula of arXiv:2608.09105, 'Longest convex chains with i.i.d.\ points'] Assume (equation p_cont of the paper).
There exists a universal constant $\alpha\in(0,\infty)$ (not depending on the density function $\mathfrak{p}$) such that
\eeq{ 
\lim_{n\to\infty}\frac{\mathscr{L}_n}{n^{1/3}} = \frac{\alpha}{2}\sup_{f\in\mathcal{F}}J_\mathfrak{p}(f) \quad \text{almost surely and in $L^p$ for every $p\in[1,\infty)$.}
} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:IPLDP of arXiv:2411.14818, 'Scaling limits of solitons in the Box-Ball system'] Assume that the initial distribution ${\mu}$ is a {space-homogeneous} Bernoulli product measure or two-sided  Markov distribution supported on $\Omega$ {and that $\mu\left(\eta\left(0\right) = \eta\left(1\right) = 1\right) > 0$}. {Let $\nu$ be the conditional probability measure such that ${\mu}$ is conditioned on $\Omega_{0}$.} Then, for any $k \in {\mathbb{N}}$, we have the following. 
                \begin{enumerate}

                    \item  {For any $i \in {\mathbb{Z}}$ and  $\mathbf{T} > 0$, under $\mu$ or $\nu$}, the following step-interpolation process,
                    \begin{align}
                        t \mapsto \frac{1}{n} {Y}^{i}_{k}\left(\left\lfloor n^2 t \right\rfloor  \right) - nt v^{\mathrm{eff}}_{k}\left( {\mu} \right),
                    \end{align}
                    converges weakly in $D[0,\mathbf{T}]$ to a Brownian motion with variance {$D_{k}$}, defined in (equation eq:dif_co of the paper) below. 

                    \item  {For any $i \in {\mathbb{Z}}$, under $\mu$ and $\nu$,} the sequence $\left({Y}^{i}_{k}\left(n\right)/ n\right)_{n \in {{\mathbb{N}}}}$ satisfies the LDP with a smooth convex rate function defined in (equation def:rate_I of the paper) below. 

                    \item  {For any {$i \in {\mathbb{Z}}$} and $p \ge 1$, we have 
                        \begin{align}
                            \lim_{n \to \infty} {\mathbb{E}}_{{\mu}}\left[ \left| \frac{{Y}^{i}_{k}\left(n\right)}{n} - v^{\mathrm{eff}}_{k}\left({\mu}\right) \right|^{p} \right] = \lim_{n \to \infty} {\mathbb{E}}_{\nu}\left[ \left| \frac{{Y}^{i}_{k}\left(n\right)}{n} - v^{\mathrm{eff}}_{k}\left({\mu}\right) \right|^{p} \right] =  0.
                        \end{align}}
                \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 13 of arXiv:2603.28226, '2603.28226'] An atomic filtration $(\mathcal F_n)_{n\ge1}$ is called $\alpha$-regular if there exists $\alpha\in(0,1]$ such that for every $n\ge2$, every parent atom $P\in\mathcal A_{n-1}$, and every child atom $C\in\mathcal A_n$ with $C\subseteq P$,
\begin{equation}

 \mathbb P(C)\ge \alpha\,\mathbb P(P).
\end{equation}

[Definition 14 (The almost Riemann invariants) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] We define the \emph{almost Riemann invariants away from symmetry} $\almostRiemann_{(\pm)}$ as follows:
\begin{align} 
\almostRiemann_{(\pm)} 
& \eqdef 
v^1 
\pm 
\almostRiemannfunction(\LogDensity,\Ent),
& 
\mbox{where } 
\almostRiemannfunction(\LogDensity,\Ent)
&
\eqdef 
\int_0^{\LogDensity} 
	\Speed(\LogDensity',\Ent) 
\, \rmd \LogDensity'.
\end{align}

[Prop support and density of 231 permuton of arXiv:2604.23751, 'Large deviation principles for pattern-avoiding permutations, and limit shapes for constra'] Let $f\in\mathcal{F}$, and let $\mu_f$ be the unique permuton with RLM curve $f$.
    Assume the following:
    \begin{enumerate}
        \item $f$ is increasing and continuous on $[0,1]$. 
        In particular, there is a unique $x^*\in(0,1)$ such that $f(x^*) = 1-x^*$.
        \item The graph $G_f$ of $f$ is invariant under the symmetry $(x,y) \mapsto (1-y, 1-x)$, that is: 
        \[ \text{for all } x\in[0,1],\quad f(1-f(x)) = 1-x .\]
        \item $f$ is strictly convex.
    \end{enumerate}
    Then $\mu_f$ equals $\mu_\nearrow + \mu_\searrow$ where:
    \begin{itemize}
        \item $\mu_\nearrow$ is the pushforward of the measure with cumulative distribution function (CDF) 
        \[ F_\nearrow : x\in[0,1] \mapsto \left\{
        \begin{array}{ll}
            f(x)
            &\text{ if } x\le x^* \,;\\
            1 + x- 2x^*
            &\text{ if } x\ge x^* \,;
        \end{array}
        \right. \]
        via $x\mapsto(x,f(x))$;
        \item $\mu_\searrow$ is the pushforward of the measure with CDF
        \[ F_\searrow : x\in[0,1] \mapsto \left\{
        \begin{array}{ll}
            x - f(x)
            &\text{ if } x\le x^* \,;\\
            2x^* - 1
            &\text{ if } x\ge x^* \,;
        \end{array}
        \right. \]
        via $x\mapsto(x,1-x)$.
    \end{itemize}
    The support of $\mu_\nearrow$ is the graph $G_f$ of $f$, and the support of $\mu_\searrow$ is the antidiagonal line from $(1,0)$ to $(x^*, f(x^*))$.

[Lemma 17 of arXiv:2606.23383, 'Near-Lipschitz stability of the Kim--Milman flow map'] Suppose $\mu$ satisfies \eqref{theta} with $L_t \defeq L_t(\mu)$ as in \eqref{eq:def-L_t}. For any $\nu \in \cP_2(\R^d)$,\looseness-1
\begin{align*}
\frac{\dd}{\dd t} \bigl(2 L_t^2\, {\mathsf H}(q_t^\nu\mmid q_t^\mu) \bigr)^{1/2} \leq
-\FI(q^\nu_{t}\mmid q^\mu_{t})^{1/2} - \theta_{t}\,\bigl(2 L_{t}^2\, {\mathsf H}(q_{t}^\nu\mmid q_{t}^\mu) \bigr)^{1/2} \,.
\end{align*}

